local function fts(v)
	return v / FPS
end

local function v(v1, v2)
	return {
		x = v1,
		y = v2
	}
end

local function r(x, y, w, h)
	return {
		pos = v(x, y),
		size = v(w, h)
	}
end

local function find_all_t(store, template_name, contains, fn)
	if not store or not store.entities then
		return {}
	end

	return table.filter(store.entities, function(k, v)
		return (contains and string.find(v.template_name, template_name) or v.template_name == template_name) and (not fn or fn(k, v))
	end)
end

local function filter_t(entities, origin, range, filter_func)
	local ts

	if SSO and SSO:is_all_entities(entities) then
		ts = {}

		SSO:filter(ts, "targets", origin.x, origin.y, range, function(k, v)
			return not filter_func or filter_func(v, origin)
		end)
	else
		ts = table.filter(entities, function(k, v)
			return not filter_func or filter_func(v, origin)
		end)
	end

	return ts
end

local function index_at(t, v, eq_fn)
	for i = 1, #t do
		if eq_fn and eq_fn(t[i], v) then
			return i
		end

		if not eq_fn and t[i] == v then
			return i
		end
	end

	return nil
end

local function any(t, pred)
	for i = 1, #t do
		if pred and pred(t[i]) then
			return true
		end
	end

	return false
end

local function all(t, pred)
	for i = 1, #t do
		if not pred(t[i]) then
			return false
		end
	end

	return true
end

local function get_keys(t)
	local ks = {}
	local i = 1

	for k, v in pairs(t) do
		ks[i] = k
		i = i + 1
	end

	return ks
end

local function shuffle_table(t)
	for i = #t, 2, -1 do
		local j = math.random(i)

		t[i], t[j] = t[j], t[i]
	end
end

local function first(t, predicate)
	for i = 1, #t do
		if predicate(t[i]) then
			return t[i]
		end
	end

	return nil
end

local function get_random_round_robin(mutable_history, n, m)
	if not m then
		m = n
		n = 1
	end

	if m < n then
		log.error("ERROR: Random round robin needs M to be bigger or equal than N")
	end

	if #mutable_history == 0 then
		for i = n, m do
			table.insert(mutable_history, i)
		end
	end

	local pos = math.random(1, #mutable_history)
	local v = mutable_history[pos]

	table.remove(mutable_history, pos)

	return v
end

local function generate_blue_noise_cluster(count, candidates, random_fn, ...)
	local points = {}
	local x, y = random_fn(...)

	points[1] = {
		x = x,
		y = y
	}

	for i = 2, count do
		local bestCandidate
		local bestDistance2 = -1

		for c = 1, candidates do
			local px, py = random_fn(...)
			local minDist2 = math.huge

			for _, p in ipairs(points) do
				local d2 = V.dist2(px, py, p.x, p.y)

				if d2 < minDist2 then
					minDist2 = d2
				end
			end

			if bestDistance2 < minDist2 then
				bestDistance2 = minDist2
				bestCandidate = {
					x = px,
					y = py
				}
			end
		end

		points[i] = bestCandidate
	end

	return points
end

local function random_point_in_ellipse(cx, cy, a, b)
	local t = 2 * math.pi * math.random()
	local r = math.sqrt(math.random())
	local x = r * math.cos(t)
	local y = r * math.sin(t)

	return cx + x * a, cy + y * b
end

local function random_point_in_rectangle(x_min, y_min, x_max, y_max)
	return math.random(x_min, x_max), math.random(y_min, y_max)
end

local function random_points_in_circumference(cx, cy, radius, distance)
	local points = {}
	local length = 2 * math.pi * radius
	local n = math.max(1, math.floor(length / distance + 0.5))

	for i = 0, n - 1 do
		local angle = 2 * math.pi * i / n

		table.insert(points, {
			x = cx + radius * math.cos(angle),
			y = cy + radius * math.sin(angle)
		})
	end

	return points
end

local function random_point_in_ellipse_in_valid_paths(cx, cy, a, b, paths)
	local t = 2 * math.pi * math.random()
	local r = math.sqrt(math.random())
	local x = r * math.cos(t)
	local y = r * math.sin(t)

	return cx + x * a, cy + y * b
end

