	elseif type(field) == "number" then
		return field
	else
		log.error("ERROR FIELD TYPE NOT RECOGNIZED")

		return 0
	end
end

local function binomial(n, k)
	local result = 1

	for i = 1, k do
		result = result * (n - (k - i))
		result = result / i
	end

	return result
end

local function bernstein(i, n, t)
	return binomial(n, i) * (1 - t)^(n - i) * t^i
end

local function evaluate(controlPoints, t)
	local n = #controlPoints - 1
	local numeratorX = 0
	local numeratorY = 0
	local denominator = 0

	for i = 0, n do
		local p = controlPoints[i + 1]
		local b = bernstein(i, n, t)
		local wb = b * p.weight

		numeratorX = numeratorX + p.x * wb
		numeratorY = numeratorY + p.y * wb
		denominator = denominator + wb
	end

	return {
		x = numeratorX / denominator,
		y = numeratorY / denominator
	}
end

local function generate_bezier_curve(controlPoints, resolution)
	local curve = {}

	for i = 0, resolution do
		local t = i / resolution

		table.insert(curve, evaluate(controlPoints, t))
	end

	return curve
end

local function point_in_valid_path(x, y, path_indexes)
	local pi, spi, ni, dist = unpack(P:nearest_nodes(x, y, path_indexes)[1])
	local width = P:path_width(pi, spi, ni)
	local node_pos = P:node_pos(pi, spi, ni)

	if dist <= width and P:is_node_valid(pi, ni) and GR:cell_is(node_pos.x, node_pos.y, bor(TERRAIN_LAND, TERRAIN_ICE)) and not GR:cell_is(node_pos.x, node_pos.y, bor(TERRAIN_NOWALK)) and P:is_path_active(pi) then
		return true
	else
		return false
	end
end

local function is_disabled(store, target)
	if target.enemy and #target.enemy.blockers > 0 then
		return true
	end

	local modifiers = table.filter(store.entities, function(k, v)
		return v.modifier and v.modifier.target_id == target.id and v.modifier.type == MOD_TYPE_STUN
	end)

	return #modifiers > 0
end

local function find_center_of_group(targets, node_prediction)
	if not targets then
		return
	end

	local np = node_prediction or 1
	local average_x = 0
	local average_y = 0

	for _, v in pairs(targets) do
		if not v then
			-- block empty
		elseif v.__ffe_pos then
			average_x = average_x + v.__ffe_pos.x
			average_y = average_y + v.__ffe_pos.y
		else
			local node_offset = P:predict_enemy_node_advance(v, np)
			local e_ni = v.nav_path.ni + node_offset
			local v_pos = P:node_pos(v.nav_path.pi, v.nav_path.spi, e_ni)

			average_x = average_x + v_pos.x
			average_y = average_y + v_pos.y
		end
	end

	return v(average_x / #targets, average_y / #targets)
end

local function find_most_populated_path(enemies)
	if not enemies or #enemies == 0 then
		return nil
	end

	local paths_count = {}
	local found_paths = {}

	for k, v in pairs(enemies) do
		if not table.contains(found_paths, v.nav_path.pi) then
			table.insert(found_paths, v.nav_path.pi)
			table.insert(paths_count, {
				v.nav_path.pi,
				1
			})
		else
			local i = index_at(paths_count, v, function(tv, iv)
				return iv.nav_path.pi == tv[1]
			end)

			paths_count[i][2] = paths_count[i][2] + 1
		end
	end

	table.sort(paths_count, function(v1, v2)
		return v1[2] > v2[2]
	end)

	return paths_count
end

local function apply_delayed_cooldowns(store, cd, attacks)
	local function apply_cd(a)
		if not a.cooldown then
			return
		end

		local in_cooldown = store.tick_ts - a.ts < a.cooldown

		if not in_cooldown then
			a.ts = store.tick_ts - a.cooldown + cd
		end
	end

	for _, aa in ipairs(attacks) do
		if aa.throttle_cooldown_on_skill_use then
			apply_cd(aa)
		end
	end
end

