scripts.tween_utils = {}

function scripts.tween_utils.reverse_remove(this, store, script)
	if this.tween.disabled then
		if this.tween_prop_replace then
			this.tween.props[1].keys[2] = this.tween_prop_replace
		end

		this.tween.disabled = false
		this.tween.ts = store.tick_ts
		this.tween.remove = true
		this.tween.reverse = true
		this.tween.run_once = false
		this.pending_removal = false

		if this.timed then
			this.timed.duration = 10
		end

		for i = 2, #this.tween.props do
			this.tween.props[i].disabled = true
		end

		return false
	end

	return true
end

function scripts.tween_utils.tween_remove(this, store, script)
	if this.tween.disabled then
		this.tween.disabled = false
		this.tween.ts = store.tick_ts
		this.tween.remove = true
		this.tween.run_once = false
		this.pending_removal = false

		if this.timed then
			this.timed.duration = 10
		end

		return false
	end

	return true
end

function scripts.tween_utils.wait_update(this, store, script)
	if this.wait_time then
		U.y_wait(store, this.wait_time)
	else
		this.render.sprites[1].ts = store.tick_ts

		U.y_animation_wait(this, 1, 1)
	end

	queue_remove(store, this)
end

scripts.mod_utils = {}

function scripts.mod_utils.wait_then_remove_update(this, store)
	local target = store.entities[this.modifier.target_id]

	if not target then
		queue_remove(store, this)

		return
	end

	if this.tween then
		this.tween.ts = store.tick_ts
	end

	this.pos = target.pos

	U.y_wait(store, this.modifier.duration)

	while store.tick_ts - this.modifier.ts < this.modifier.duration do
		coroutine.yield()
	end

	queue_remove(store, this)
end

function scripts.mod_utils.mod_stun_chance_insert(this, store)
	if math.random() > this.modifier.chance then
		return false
	end

	return scripts.mod_stun.insert(this, store)
end

function scripts.mod_utils.armor_sunder_insert(this, store, script)
	local target = store.entities[this.modifier.target_id]

	if not target or band(this.modifier.vis_flags, target.vis.bans) ~= 0 or band(this.modifier.vis_bans, target.vis.flags) ~= 0 then
		return false
	end

	if target.health.armor <= 0 then
		return false
	end

	SU.armor_dec(target, this.modifier.armor_red_factor)

	return false
end

function scripts.mod_utils.armor_inc_insert(this, store, script)
	local target = store.entities[this.modifier.target_id]

	if not target or target.health.dead then
		return false
	end

	if band(this.modifier.vis_flags, target.vis.bans) ~= 0 or band(this.modifier.vis_bans, target.vis.flags) ~= 0 then
		log.paranoid("mod %s cannot be applied to entity %s:%s because of vis flags/bans", this.template_name, target.id, target.template_name)

		return false
	end

	SU.armor_inc(target, this.armor_inc)
	SU.magic_armor_inc(target, this.armor_inc)
	signal.emit("mod-applied", this, target)

	if target and target.unit and this.render then
		for i = 1, #this.render.sprites do
			local s = this.render.sprites[i]

			s.ts = store.tick_ts

			if s.size_names then
				s.name = s.size_names[target.unit.size]
			end
		end
	end

	return true
end

function scripts.mod_utils.armor_inc_update(this, store, script)
	local m = this.modifier
	local target = store.entities[m.target_id]

	if not target then
		queue_remove(store, this)

		return
	end

	this.pos = target.pos

	while true do
		target = store.entities[m.target_id]

		if not target or target.health.dead or store.tick_ts - m.ts >= m.duration then
			queue_remove(store, this)

			return
		end

		if this.render and m.use_mod_offset and target.unit.mod_offset then
			for i = 1, #this.render.sprites do
				local s = this.render.sprites[i]

				if not s.exclude_mod_offset then
					s.offset.x, s.offset.y = target.unit.mod_offset.x, target.unit.mod_offset.y
				end
			end
		end

		coroutine.yield()
	end
end

function scripts.mod_utils.armor_inc_remove(this, store, script)
	local target = store.entities[this.modifier.target_id]

	if target then
		SU.armor_dec(target, this.armor_inc)
		SU.magic_armor_dec(target, this.armor_inc)
	end

	return true
end

function scripts.mod_utils.damage_reduction_insert(this, store)
	local target = store.entities[this.modifier.target_id]

	if target and target.unit then
		target.unit.damage_factor = target.unit.damage_factor * this.damage_red_factor

		signal.emit("mod-applied", this, target)
	end

	return true
end

function scripts.mod_utils.damage_reduction_remove(this, store)
	local target = store.entities[this.modifier.target_id]

	if target and target.unit then
		target.unit.damage_factor = target.unit.damage_factor / this.damage_red_factor
	end

	return true
end

scripts.mod_movement_terrain = {}

function scripts.mod_movement_terrain.remove(this, store)
	if not this._mods then
		return true
	end

	for _, m in ipairs(this._mods) do
		if store.entities[m.id] then
			queue_remove(store, m)
		end
	end

	this._mods = nil

	return true
end

function scripts.mod_movement_terrain.update(this, store)
	if not this.terrain then
		log.error("Mod movement terrain for target" .. tostring(this.modifier.target_id) .. " has no terrain setup. Removing.")
		queue_remove(store, this)

		return
	end

	local target = store.entities[this.modifier.target_id]
	local change = false
	local on_auras = false
	local last_terrain = GR:cell_type(target.pos.x, target.pos.y)
	local last_aura_check_ts = store.tick_ts

	this.on_terrain = GR:cell_is(target.pos.x, target.pos.y, this.terrain)

	local function check_walking_on_auras()
		if this.auras_to_consider_terrain and store.tick_ts - last_aura_check_ts > 0.25 then
			last_aura_check_ts = store.tick_ts

			for i, aura_t in ipairs(this.auras_to_consider_terrain) do
				local existing_auras = find_all_t(store, aura_t)

				for i, aura in ipairs(existing_auras) do
					if U.is_inside_ellipse(target.pos, aura.pos, aura.aura.radius) then
						on_auras = true

						return true
					end
				end
			end

			on_auras = false
		end

		return false
	end

	local function check_on_terrain()
		return GR:cell_is(target.pos.x, target.pos.y, this.terrain) or on_auras
	end

	local function get_terrain()
		if on_auras then
			return this.terrain
		end

		return GR:cell_type(target.pos.x, target.pos.y)
	end

	local function changed_terrain()
		local t = get_terrain()
		local last_terrain_is_target = band(last_terrain, this.terrain) ~= 0

		return not last_terrain_is_target and band(t, this.terrain) ~= 0 or last_terrain_is_target and band(t, this.terrain) == 0
	end

	local function instance_mods()
		if not this.mods then
			log.error("ERROR: Mod %s:%s has no mods to instantiate.", this.id, this.template_name)

			return
		end

		local mods = {}

		for _, mt in ipairs(this.mods) do
			local m = E:create_entity(mt)

			m.modifier.target_id = this.modifier.target_id
			m.modifier.source_id = this.modifier.target_id
			m.modifier.duration = 1e+99

			queue_insert(store, m)
			table.insert(mods, m)
		end

		this._mods = mods
	end

	while true do
		if not store.entities[this.modifier.target_id] or store.entities[this.modifier.target_id].health and store.entities[this.modifier.target_id].health.dead then
			queue_remove(store, this)

			return
		end

		check_walking_on_auras()

		this.on_terrain = check_on_terrain()

		if this.on_terrain and changed_terrain() then
			if this.add_vis_bans then
				this._pushed_bans = U.push_bans(target.vis, this.add_vis_bans)
			end

			if this.add_vis_flags then
				target.vis.flags = U.flag_set(target.vis.flags, this.add_vis_flags)
			end

			instance_mods()

			if this.on_entered_terrain_fn then
				this.on_entered_terrain_fn()
			end
		end

		if not this.on_terrain and changed_terrain() then
			if this._pushed_bans then
				U.pop_bans(target.vis, this._pushed_bans)

				this._pushed_bans = nil
			end

			if this.add_vis_flags then
				target.vis.flags = U.flag_clear(target.vis.flags, this.add_vis_flags)
			end

			scripts.mod_movement_terrain.remove(this, store)

			if this.on_left_terrain_fn then
				this.on_left_terrain_fn()
			end
		end

		last_terrain = get_terrain()

		coroutine.yield()
	end
end

local SU5 = {}

function SU5.find_towers_in_range_vis(entities, origin, attack, filter_func)
	local bans = attack.vis_bans or 0
	local flags = attack.vis_flags or 0
	local towers = table.filter(entities, function(k, v)
		return not v.pending_removal and v.tower and (not v.vis or band(v.vis.flags, bans) == 0 and band(v.vis.bans, flags) == 0) and (not attack.excluded_templates or not table.contains(attack.excluded_templates, v.template_name)) and U.is_inside_ellipse(v.pos, origin, attack.max_range) and (attack.min_range == 0 or not U.is_inside_ellipse(v.pos, origin, attack.min_range)) and (not filter_func or filter_func(v, origin, attack))
	end)

	if not towers or #towers == 0 then
		return nil
	else
		return towers
	end
end

function SU5.valid_node_interval(x, y, offset_back, offset_forward, path_width_factor, flags)
	offset_back = offset_back or 0
	offset_forward = offset_forward or 0
	path_width_factor = path_width_factor or 1

	local nodes = P:nearest_nodes(x, y, nil, nil, true, flags)

	for _, n in pairs(nodes) do
		do
			local pi, spi, ni, dist = unpack(n)

			if dist < path_width_factor * P:path_width(pi, spi, ni) then
				for off = -1, offset_back, -1 do
					if not P:is_node_valid(pi, ni + off, flags) then
						goto label_61_0
					end
				end

				for off = 1, offset_forward do
					if not P:is_node_valid(pi, ni + off, flags) then
						goto label_61_0
					end
				end

				return true
			end
		end

		::label_61_0::
	end

	return false
end

function SU5.go_to_forced_waypoint(this, store)
	if this.motion.forced_waypoint then
		local w = this.motion.forced_waypoint

		if V.dist(w.x, w.y, this.pos.x, this.pos.y) < 2 * this.motion.max_speed * store.tick_length then
			this.pos.x, this.pos.y = w.x, w.y
			this.motion.forced_waypoint = nil

			return false
		end

		U.set_destination(this, this.motion.forced_waypoint)

		local an, af = U.animation_name_facing_point(this, "walk", this.motion.dest)

		U.animation_start(this, an, af, store.tick_ts, true)
		U.walk(this, store.tick_length)

		return true
	end

	return false
end

scripts.mod_test_unit_pos_kr5 = {}

function scripts.mod_test_unit_pos_kr5.update(this, store, script)
	local m = this.modifier

	m.ts = store.tick_ts

	local target = store.entities[m.target_id]

	if not target then
		queue_remove(store, this)

		return
	end

	this.pos = target.pos

	local targetZ = Z_EFFECTS
	local targetOffset = V.vv(0)

	if target.render then
		targetZ = target.render.sprites[1].z
	end

	if target.unit then
		if this.position_test == "HEAD" and target.unit.head_offset then
			targetOffset = V.vclone(target.unit.head_offset)
		elseif this.position_test == "MOD" and target.unit.mod_offset then
			targetOffset = V.vclone(target.unit.mod_offset)
		elseif this.position_test == "HIT" and target.unit.hit_offset then
			targetOffset = V.vclone(target.unit.hit_offset)
		end
	end

	for _, s in pairs(this.render.sprites) do
		s.offset = targetOffset
		s.z = targetZ
	end

	while true do
		target = store.entities[m.target_id]

		if not target or target.health and target.health.dead or m.duration >= 0 and store.tick_ts - m.ts > m.duration then
			queue_remove(store, this)

			return
		end

		coroutine.yield()
	end
end

scripts.mod_lifesteal_kr5 = {}

function scripts.mod_lifesteal_kr5.insert(this, store)
	local source = store.entities[this.modifier.source_id]
	local target = store.entities[this.modifier.target_id]
	local damage = 0

	if target and target.health then
		local dmg_value = this.damage

		if this.damage_min then
			dmg_value = math.random(this.damage_min, this.damage_max)
		end

		local d = E:create_entity("damage")

		d.value = dmg_value
		d.source_id = this.id
		d.target_id = target.id
		d.damage_type = this.damage_type

		if not this.only_predict_damage then
			queue_damage(store, d)
		end

		damage = U.predict_damage(target, d)
	end

	if source and source.health then
		local heal_hp = this.heal_hp_fixed and this.heal_hp_fixed or 0

		if this.heal_hp_damage_factor then
			heal_hp = heal_hp + damage * this.heal_hp_damage_factor
		end

		source.health.hp = km.clamp(0, source.health.hp_max, source.health.hp + heal_hp)
	end

	return false
end

scripts.delayed_play_kr5 = {}

function scripts.delayed_play_kr5.update(this, store, script)
	local s = this.render.sprites[1]
	local d = this.delayed_play
	local clicks = 0

	if math.random() < d.flip_chance then
		s.flip_x = not s.flip_x
	end

	if d.idle_animation then
		U.animation_start(this, d.idle_animation, nil, store.tick_ts, d.loop_idle)
	else
		s.hidden = true
	end

	d.delay = U.frandom(d.start_min_delay and d.start_min_delay or d.min_delay, d.start_max_delay and d.start_max_delay or d.max_delay)

	if d.start_fixed_delay then
		d.delay = d.start_fixed_delay
	end

	while true do
		if not d.disabled and this.ui and d.required_clicks then
			if this.ui.clicked then
				this.ui.clicked = nil
				clicks = clicks + 1

				if clicks < d.required_clicks then
					S:queue(d.click_sound)
				end

				if d.click_tweens and this.tween then
					this.tween.props[1].ts = store.tick_ts
					this.tween.disabled = false
				end
			end

			if clicks == d.required_clicks then
				if not d.idle_animation then
					s.hidden = false
				end

				S:queue(d.clicked_sound)

				if d.required_clicks_fx then
					SU.insert_sprite(store, d.required_clicks_fx, this.pos)
				end

				if d.required_clicks_hides then
					s.hidden = true
				elseif d.clicked_animation then
					U.y_animation_play(this, d.clicked_animation, nil, store.tick_ts, 1)
				end

				if d.achievement then
					AC:got(d.achievement)
				end

				if d.achievement_flag then
					AC:flag_check(unpack(d.achievement_flag))
				end

				if d.achievement_inc then
					AC:inc_check(d.achievement_inc)
				end

				if d.play_once then
					queue_remove(store, this)

					return
				end

				if not d.idle_animation then
					s.hidden = true
				else
					U.animation_start(this, d.idle_animation, nil, store.tick_ts, d.loop_play)
				end

				clicks = 0
				this.ui.clicked = nil
			end
		end

		if store.tick_ts - s.ts > d.delay then
			s.ts = store.tick_ts

			if d.disabled then
				-- block empty
			else
				if not d.idle_animation then
					s.hidden = false
				end

				if math.random() < d.flip_chance then
					s.flip_x = not s.flip_x
				end

				if d.play_animation then
					if d.play_sound then
						S:queue(d.play_sound)
					end

					if d.play_duration then
						U.animation_start(this, d.play_animation, nil, store.tick_ts, true)

						if U.y_wait(store, d.play_duration, function()
							return d.click_interrupts and this.ui.clicked
						end) then
							goto label_65_0
						end
					else
						U.animation_start(this, d.play_animation, nil, store.tick_ts, false)

						while not U.animation_finished(this) do
							if d.click_interrupts and this.ui.clicked then
								goto label_65_0
							end

							coroutine.yield()
						end
					end
				end

				if not d.idle_animation then
					s.hidden = true
				else
					U.animation_start(this, d.idle_animation, nil, store.tick_ts, d.loop_idle)
				end

				if this.ui and not d.click_interrupts then
					this.ui.clicked = nil
				end
			end
		end

		::label_65_0::

		coroutine.yield()
	end
end

scripts.aura_apply_mod_towers = {}

function scripts.aura_apply_mod_towers.update(this, store, script)
	local first_hit_ts
	local last_hit_ts = 0
	local cycles_count = 0
	local victims_count = 0
	local interrupted = false

	if this.aura.track_source and this.aura.source_id then
		local te = store.entities[this.aura.source_id]

		if te and te.pos then
			this.pos = te.pos
		end
	end

	last_hit_ts = store.tick_ts - this.aura.cycle_time

	if this.aura.apply_delay then
		last_hit_ts = last_hit_ts + this.aura.apply_delay
	end

	while true do
		if this.interrupt then
			last_hit_ts = 1e+99
			interrupted = true
		elseif interrupted then
			last_hit_ts = store.tick_ts
			interrupted = false
		end

		if this.aura.cycles and cycles_count >= this.aura.cycles or this.aura.duration >= 0 and store.tick_ts - this.aura.ts > this.actual_duration then
			break
		end

		if this.aura.stop_on_max_count and this.aura.max_count and victims_count >= this.aura.max_count then
			break
		end

		if this.aura.track_source and this.aura.source_id then
			local te = store.entities[this.aura.source_id]

			if not te or te.health and te.health.dead and not this.aura.track_dead then
				break
			end
		end

		if this.aura.requires_magic and this.aura.source_id then
			local te = store.entities[this.aura.source_id]

			if not te or not te.enemy then
				goto label_67_0
			end

			if this.render then
				this.render.sprites[1].hidden = not te.enemy.can_do_magic
			end

			if not te.enemy.can_do_magic then
				goto label_67_0
			end
		end

		if this.aura.source_vis_flags and this.aura.source_id then
			local te = store.entities[this.aura.source_id]

			if te and te.vis and band(te.vis.bans, this.aura.source_vis_flags) ~= 0 then
				goto label_67_0
			end
		end

		if this.aura.requires_alive_source and this.aura.source_id then
			local te = store.entities[this.aura.source_id]

			if te and te.health and te.health.dead then
				goto label_67_0
			end
		end

		if not (store.tick_ts - last_hit_ts >= this.aura.cycle_time) or this.aura.apply_duration and first_hit_ts and store.tick_ts - first_hit_ts > this.aura.apply_duration then
			-- block empty
		else
			if this.render and this.aura.cast_resets_sprite_id then
				this.render.sprites[this.aura.cast_resets_sprite_id].ts = store.tick_ts
			end

			first_hit_ts = first_hit_ts or store.tick_ts
			last_hit_ts = store.tick_ts
			cycles_count = cycles_count + 1

			local towers = U.find_towers(store.entities, this.pos, 0, this.aura.radius, function(v, o)
				return v.tower.type ~= "holder" and v.tower.type ~= "build_animation" and (not v.tower_holder or not v.tower_holder.blocked) and (not this.aura.allowed_templates or table.contains(this.aura.allowed_templates, v.template_name)) and (not this.aura.excluded_templates or not table.contains(this.aura.excluded_templates, v.template_name)) and (not this.aura.filter_source or this.aura.source_id ~= v.id)
			end)

			if towers then
				for i, target in ipairs(towers) do
					if this.aura.targets_per_cycle and i > this.aura.targets_per_cycle then
						break
					end

					if this.aura.max_count and victims_count >= this.aura.max_count then
						break
					end

					local mods = this.aura.mods or {
						this.aura.mod
					}

					for _, mod_name in pairs(mods) do
						local new_mod = E:create_entity(mod_name)

						new_mod.modifier.level = this.aura.level
						new_mod.modifier.target_id = target.id
						new_mod.modifier.source_id = this.id

						if this.aura.hide_source_fx and target.id == this.aura.source_id then
							new_mod.render = nil
						end

						queue_insert(store, new_mod)
					end

					victims_count = victims_count + 1
				end
			end
		end

		::label_67_0::

		coroutine.yield()
	end

	signal.emit("aura-apply-mod-towers-victims", this, victims_count)
	queue_remove(store, this)
end

scripts.enemy_ranged = {}

function scripts.enemy_ranged.get_info(this)
	local min, max, damage_type, attacks

	if this.ranged and this.ranged.attacks then
		for _, a in pairs(this.ranged.attacks) do
			if a.bullet then
				local b = E:get_template(a.bullet)

				if b and b.bullet.damage_min and b.bullet.damage_max then
					min, max = b.bullet.damage_min, b.bullet.damage_max
					damage_type = b.bullet.damage_type

					break
				end
			end
		end
	elseif this.melee and this.melee.attacks then
		for _, a in pairs(this.melee.attacks) do
			if a.damage_min then
				min, max = a.damage_min, a.damage_max
				damage_type = a.damage_type

				break
			end
		end

		if this.unit and min then
			min, max = min * this.unit.damage_factor, max * this.unit.damage_factor
		end
	end

	if min and max then
		min, max = math.ceil(min), math.ceil(max)
	end

	local armor = band(this.health.immune_to, DAMAGE_PHYSICAL) ~= 0 and 1 or this.health.armor
	local magic_armor = band(this.health.immune_to, DAMAGE_MAGICAL) ~= 0 and 1 or this.health.magic_armor

	return {
		type = STATS_TYPE_ENEMY,
		hp = this.health.hp,
		hp_max = this.health.hp_max,
		damage_min = min,
		damage_max = max,
		damage_type = damage_type,
		damage_icon = this.info.damage_icon,
		armor = armor,
		magic_armor = magic_armor,
		lives = this.enemy and this.enemy.lives_cost or 0,
		immune = this.health.immune_to == DAMAGE_ALL_TYPES
	}
end

scripts.enemy_demon_lord = {}

function scripts.enemy_demon_lord.update(this, store)
	local a = this.timed_attacks.list[1]

	a.ts = store.tick_ts

	local function ready_to_shield()
		return this.enemy.can_do_magic and store.tick_ts - a.ts > a.cooldown
	end

	local function get_shield_targets()
		return U.find_enemies_in_range(store.entities, this.pos, 0, a.max_range, a.vis_flags, a.vis_bans, function(e)
			return table.contains(a.allowed_templates, e.template_name)
		end)
	end

	::label_70_0::

	while true do
		if this.health.dead then
			SU.y_enemy_death(store, this)

			return
		end

		if this.unit.is_stunned then
			SU.y_enemy_stun(store, this)
		else
			if ready_to_shield() then
				local targets = get_shield_targets()

				if not targets then
					SU.delay_attack(store, a, 0.5)
				else
					a.ts = store.tick_ts

					U.animation_start(this, a.animation, nil, store.tick_ts, false)

					if a.sound then
						S:queue(a.sound)
					end

					if SU.y_enemy_wait(store, this, a.cast_time) then
						goto label_70_0
					end

					targets = get_shield_targets()

					if targets then
						local shielded_count = 0

						for _, target in ipairs(targets) do
							if shielded_count >= a.max_count then
								break
							end

							shielded_count = shielded_count + 1

							local m = E:create_entity(a.mod)

							m.modifier.source_id = this.id
							m.modifier.target_id = target.id

							queue_insert(store, m)
						end
					end

					if SU.y_enemy_animation_wait(this) then
						goto label_70_0
					end
				end
			end

			if not SU.y_enemy_mixed_walk_melee_ranged(store, this, false, ready_to_shield, ready_to_shield) then
				-- block empty
			else
				coroutine.yield()
			end
		end
	end
end

scripts.mod_demon_shield = {}

function scripts.mod_demon_shield.insert(this, store)
	local m = this.modifier
	local target = store.entities[m.target_id]

	if not target or not target.health or target.health.dead then
		return false
	end

	m.ts = store.tick_ts
	target.health.on_damage = scripts.mod_demon_shield.on_damage
	this._hits = 0
	this._hit_sources = {}
	this._blood_color = target.unit.blood_color
	target.unit.blood_color = BLOOD_NONE
	target._shield_mod = this

	return true
end

function scripts.mod_demon_shield.remove(this, store)
	local m = this.modifier
	local target = store.entities[m.target_id]

	if target then
		target.health.on_damage = nil
		target._shield_mod = nil
		target.unit.blood_color = this._blood_color

		local fx = E:create_entity("fx_demon_lord_shield_end")

		fx.pos = V.v(this.pos.x, this.pos.y)
		fx.render.sprites[1].offset = V.vclone(this.render.sprites[1].offset)
		fx.render.sprites[1].ts = store.tick_ts

		queue_insert(store, fx)
	end

	return true
end

function scripts.mod_demon_shield.update(this, store, script)
	local m = this.modifier
	local target = store.entities[m.target_id]

	if not target or not target.pos then
		queue_remove(store, this)

		return
	end

	this.pos = target.pos

	if m.use_mod_offset and target.unit and target.unit.mod_offset then
		local s = this.render.sprites[1]

		s.offset.x, s.offset.y = target.unit.mod_offset.x, target.unit.mod_offset.y
	end

	U.y_animation_play(this, "start", nil, store.tick_ts, 1)
	U.animation_start(this, "loop", nil, store.tick_ts, true)

	while true do
		target = store.entities[m.target_id]

		if not target or target.health.dead or m.duration >= 0 and store.tick_ts - m.ts > m.duration then
			queue_remove(store, this)

			return
		end

		this.pos = target.pos

		coroutine.yield()
	end
end

function scripts.mod_demon_shield.on_damage(this, store, damage)
	local mod = this._shield_mod

	if not mod then
		log.error("mod_demon_shield.on_damage for enemy %s has no mod pointer", this.id)

		return true
	end

	if U.flag_has(damage.damage_type, bor(DAMAGE_INSTAKILL, DAMAGE_DISINTEGRATE, DAMAGE_EAT, DAMAGE_IGNORE_SHIELD)) then
		queue_remove(store, mod)

		return true
	end

	if U.flag_has(damage.damage_type, DAMAGE_ONE_SHIELD_HIT) then
		if not mod._hit_sources[damage.source_id] then
			mod._hit_sources[damage.source_id] = true
			mod._hits = mod._hits + 1
		end
	elseif not U.flag_has(damage.damage_type, DAMAGE_NO_SHIELD_HIT) then
		mod._hits = mod._hits + 1
	end

	if mod._hits >= mod.shield_ignore_hits then
		queue_remove(store, mod)
	end

	return false
end

scripts.aura_utils = {}

function scripts.aura_utils.apply_area_damage(this, store, script)
	local enemies = U.find_targets_in_range(store.entities, this.pos, 0, this.aura.radius, this.aura.vis_flags, this.aura.vis_bans)

	if enemies then
		local ignore_dist_factor = this.aura.ignore_dist_factor or this.aura.chance_ignore_dist_factor and math.random() <= this.aura.chance_ignore_dist_factor

		for _, enemy in pairs(enemies) do
			local d = E:create_entity("damage")

			d.damage_type = this.aura.damage_type

			if this.aura.reduce_armor then
				d.reduce_armor = this.aura.reduce_armor
			end

			if ignore_dist_factor then
				d.value = this.aura.damage_max
			else
				local dist_factor = U.dist_factor_inside_ellipse(enemy.pos, this.pos, this.aura.radius)

				d.value = math.floor(this.aura.damage_max - (this.aura.damage_max - this.aura.damage_min) * dist_factor)
			end

			if this.aura.damage_factor then
				d.value = math.ceil(d.value * this.aura.damage_factor)
			end

			if (d.damage_type == DAMAGE_EXPLOSION or d.damage_type == DAMAGE_ELECTRICAL) and this.aura.explosive_factor then
				d.explosive_factor = this.aura.explosive_factor
			end

			d.source_id = this.id
			d.target_id = enemy.id

			queue_damage(store, d)

			if this.aura.mod or this.aura.mods then
				local mods = this.aura.mods or {
					this.aura.mod
				}

				if this.aura.mod and this.aura.mods then
					mods = table.merge(this.aura.mods, {
						this.aura.mod
					})
				end

				for _, mod_name in pairs(mods) do
					local m = E:create_entity(mod_name)

					m.modifier.target_id = enemy.id
					m.modifier.level = this.aura.level

					queue_insert(store, m)
				end
			end
		end
	end

	queue_remove(store, this)
end

scripts.decal_utils = {}

function scripts.decal_utils.censor_cn_insert(this, store, script)
	return not features.no_copyrighted_easter_eggs
end

function scripts.decal_utils.track_target_update(this, store, script)
	local target = store.entities[this.target_id]
	local s

	if not target or not target.pos then
		queue_remove(store, this)

		return
	end

	this.pos = target.pos

	local st = target.render.sprites[1]

	if this.render then
		for _, sp in pairs(this.render.sprites) do
			sp.ts = store.tick_ts
		end

		s = this.render.sprites[1]
	end

	local function contains(s, pattern, exclude)
		local c = string.find(s, pattern) ~= nil

		if exclude then
			local e = type(exclude) == "table" and exclude or {
				exclude
			}

			for _, v in pairs(e) do
				if string.find(s, v) ~= nil then
					return false
				end
			end
		end

		return c
	end

	while true do
		target = store.entities[this.target_id]

		if not target or target.health.dead then
			if target and this.animation_out and s then
				U.y_animation_play(this, this.animation_out, target.render.sprites[1].flip_x, store.tick_ts, 1, 1)
			end

			queue_remove(store, this)

			return
		end

		if this.flip and s then
			s.flip_x = st.flip_x
		end

		if this.animation_front and this.string_front and s and s.name ~= this.animation_front and contains(st.name, this.string_front, this.exclude_front) then
			U.animation_start(this, this.animation_front, s.flip_x, store.tick_ts, true, 1)

			if this.sort_y_offset_front then
				s.sort_y_offset = this.sort_y_offset_front
			end
		end

		if this.animation_back and this.string_back and s and s.name ~= this.animation_back and contains(st.name, this.string_back, this.exclude_back) then
			U.animation_start(this, this.animation_back, s.flip_x, store.tick_ts, true, 1)

			if this.sort_y_offset_back then
				s.sort_y_offset = this.sort_y_offset_back
			end
		end

		if this.animation_side and this.string_side and s and s.name ~= this.animation_side and contains(st.name, this.string_side, this.exclude_side) then
			U.animation_start(this, this.animation_side, s.flip_x, store.tick_ts, true, 1)

			if this.sort_y_offset_side then
				s.sort_y_offset = this.sort_y_offset_side
			end
		end

		coroutine.yield()
	end
end

function scripts.decal_utils.animation_on_tap_update(this, store, script)
	local tapped = false

	while not tapped do
		if this.ui and this.ui.clicked then
			if this.tap_sound then
				S:queue(this.tap_sound)
			end

			U.y_animation_play(this, this.tap_anim, nil, store.tick_ts, this.tap_anim_play_times)

			if not this.no_loop_anim then
				U.animation_start(this, this.loop_anim, nil, store.tick_ts, true)
			end

			this.ui.clicked = nil

			if this.tap_disables then
				this.ui.can_click = false
			end

			if this.tap_ends then
				tapped = true
			end
		end

		coroutine.yield()
	end
end

scripts.decal_utils.animation_in_loop_out = {}

function scripts.decal_utils.animation_in_loop_out.update(this, store, script)
	if not this.start_sprite_idx then
		this.start_sprite_idx = 1
	end

	if not this.idle_sprite_idx then
		this.idle_sprite_idx = 1
	end

	if not this.end_sprite_idx then
		this.end_sprite_idx = 1
	end

	if this.delay_animation_start then
		U.y_wait(store, this.delay_animation_start)
	end

	this.render.sprites[1].animated = true

	for i = 1, #this.render.sprites do
		this.render.sprites[i].hidden = false
	end

	if this.animation_start then
		U.y_animation_play(this, this.animation_start, nil, store.tick_ts, 1, this.start_sprite_idx)
	end

	if this.animation_idle then
		U.animation_start(this, this.animation_idle, nil, store.tick_ts, true, this.idle_sprite_idx, this.idle_force_ts)

		this.ts = store.tick_ts

		while store.tick_ts - this.ts < this.duration do
			coroutine.yield()
		end
	end

	if this.animation_end then
		U.y_animation_play(this, this.animation_end, nil, store.tick_ts, 1, this.end_sprite_idx)
	end

	queue_remove(store, this)
end

scripts.fx_utils = {}

function scripts.fx_utils.in_loop_out(this, store, script)
	if this.animation_in then
		U.y_animation_play(this, this.animation_in, nil, store.tick_ts, 1, 1)
	end

	if this.animation_loop then
		this.render.sprites[1].loop = true
		this.render.sprites[1].ts = store.tick_ts

		U.animation_start(this, this.animation_loop, nil, store.tick_ts, true)
		U.y_wait(store, this.loop_time)
	end

	if this.animation_end then
		U.y_animation_play(this, this.animation_end, nil, store.tick_ts, 1, 1)
	end

	queue_remove(store, this)
end

scripts.bolt_tower_wizard = {}

function scripts.bolt_tower_wizard.insert(this, store, script)
	local b = this.bullet

	if this.impulse_per_distance then
		local dx, dy = V.sub(b.to.x, b.to.y, b.from.x, b.from.y)
		local dist = V.len(dx, dy)

		this.initial_impulse = this.impulse_per_distance * dist
	end

	if b.target_id then
		local target = store.entities[b.target_id]

		if not target or band(target.vis.bans, F_RANGED) ~= 0 then
			return false
		end
	end

	b.speed.x, b.speed.y = V.normalize(b.to.x - b.from.x, b.to.y - b.from.y)

	local s = this.render.sprites[1]

	if not b.ignore_rotation then
		s.r = V.angleTo(b.to.x - this.pos.x, b.to.y - this.pos.y)
	end

	return true
end

function scripts.bolt_tower_wizard.update(this, store)
	local b = this.bullet
	local fm = this.force_motion
	local target = store.entities[b.target_id]
	local ps

	local function move_step(dest)
		local dx, dy = V.sub(dest.x, dest.y, this.pos.x, this.pos.y)
		local dist = V.len(dx, dy)
		local nx, ny = V.mul(fm.max_v, V.normalize(dx, dy))
		local stx, sty = V.sub(nx, ny, fm.v.x, fm.v.y)

		if dist <= 4 * fm.max_v * store.tick_length then
			stx, sty = V.mul(fm.max_a, V.normalize(stx, sty))
		end

		fm.a.x, fm.a.y = V.add(fm.a.x, fm.a.y, V.trim(fm.max_a, V.mul(fm.a_step, stx, sty)))
		fm.v.x, fm.v.y = V.trim(fm.max_v, V.add(fm.v.x, fm.v.y, V.mul(store.tick_length, fm.a.x, fm.a.y)))
		this.pos.x, this.pos.y = V.add(this.pos.x, this.pos.y, V.mul(store.tick_length, fm.v.x, fm.v.y))
		fm.a.x, fm.a.y = 0, 0

		return dist <= fm.max_v * store.tick_length
	end

	if b.particles_name then
		ps = E:create_entity(b.particles_name)
		ps.particle_system.emit = true
		ps.particle_system.track_id = this.id

		queue_insert(store, ps)
	end

	local pred_pos

	if target then
		pred_pos = P:predict_enemy_pos(target, fts(5))
	else
		pred_pos = b.to
	end

	local iix, iiy = V.normalize(pred_pos.x - this.pos.x, pred_pos.y - this.pos.y)
	local last_pos = V.vclone(this.pos)

	b.ts = store.tick_ts

	while true do
		target = store.entities[b.target_id]

		if target and target.health and not target.health.dead and band(target.vis.bans, F_RANGED) == 0 then
			local hit_offset = V.v(0, 0)

			if not b.ignore_hit_offset then
				hit_offset.x = target.unit.hit_offset.x
				hit_offset.y = target.unit.hit_offset.y
			end

			local d = math.max(math.abs(target.pos.x + hit_offset.x - b.to.x), math.abs(target.pos.y + hit_offset.y - b.to.y))

			if d > b.max_track_distance then
				log.debug("BOLT MAX DISTANCE FAIL. (%s) %s / dist:%s target.pos:%s,%s b.to:%s,%s", this.id, this.template_name, d, target.pos.x, target.pos.y, b.to.x, b.to.y)

				target = nil
				b.target_id = nil
			else
				b.to.x, b.to.y = target.pos.x + hit_offset.x, target.pos.y + hit_offset.y
			end
		end

		if this.initial_impulse and store.tick_ts - b.ts < this.initial_impulse_duration then
			local t = store.tick_ts - b.ts

			if this.initial_impulse_angle_abs then
				fm.a.x, fm.a.y = V.mul((1 - t) * this.initial_impulse, V.rotate(this.initial_impulse_angle_abs, 1, 0))
			else
				local angle = this.initial_impulse_angle

				if iix < 0 then
					angle = angle * -1
				end

				fm.a.x, fm.a.y = V.mul((1 - t) * this.initial_impulse, V.rotate(angle, iix, iiy))
			end

			fm.v.x, fm.v.y = V.trim(fm.max_v, V.add(fm.v.x, fm.v.y, V.mul(store.tick_length, fm.a.x, fm.a.y)))
			this.pos.x, this.pos.y = V.add(this.pos.x, this.pos.y, V.mul(store.tick_length, fm.v.x, fm.v.y))
		else
			last_pos.x, last_pos.y = this.pos.x, this.pos.y

			if move_step(b.to) then
				break
			end
		end

		if b.align_with_trajectory then
			this.render.sprites[1].r = V.angleTo(this.pos.x - last_pos.x, this.pos.y - last_pos.y)
		end

		coroutine.yield()
	end

	if target and not target.health.dead then
		if math.random() > b.chance_to_ignore_mr then
			b.reduce_magic_armor = 0
		end

		local d = SU.create_bullet_damage(b, target.id, this.id)

		queue_damage(store, d)

		if b.mod or b.mods then
			local mods = b.mods or {
				b.mod
			}

			for _, mod_name in pairs(mods) do
				local m = E:create_entity(mod_name)

				m.modifier.target_id = b.target_id
				m.modifier.level = b.level

				queue_insert(store, m)
			end
		end
	elseif b.damage_radius and b.damage_radius > 0 then
		local targets = U.find_enemies_in_range(store.entities, this.pos, 0, b.damage_radius, b.vis_flags, b.vis_bans)

		if targets then
			for _, target in pairs(targets) do
				local d = SU.create_bullet_damage(b, target.id, this.id)

				queue_damage(store, d)
			end
		end
	end

	this.render.sprites[1].hidden = true

	if b.hit_fx then
		local fx = E:create_entity(b.hit_fx)

		fx.pos.x, fx.pos.y = b.to.x, b.to.y
		fx.render.sprites[1].ts = store.tick_ts
		fx.render.sprites[1].runs = 0

		queue_insert(store, fx)
	end

	if b.hit_decal then
		local decal = E:create_entity(b.hit_decal)

		decal.pos = V.vclone(b.to)
		decal.render.sprites[1].ts = store.tick_ts

		queue_insert(store, decal)
	end

	if this.hit_sfx then
		S:queue(this.hit_sfx)
	end

	if ps and ps.particle_system.emit then
		ps.particle_system.emit = false

		U.y_wait(store, ps.particle_system.particle_lifetime[2])
	end

	queue_remove(store, this)
end

scripts.mod_tower_stun = {}

function scripts.mod_tower_stun.insert(this, store)
	local m = this.modifier
	local target = store.entities[m.target_id]

	if not target or not target.vis then
		log.error("ERROR: Tower cant be stunned because it doesnt contain a vis component. Ignoring.")

		return false
	end

	if band(this.modifier.vis_flags, target.vis.bans) ~= 0 or band(this.modifier.vis_bans, target.vis.flags) ~= 0 then
		log.paranoid("mod %s cannot be applied to entity %s:%s because of vis flags/bans", this.template_name, target.id, target.template_name)

		return false
	end

	m.ts = store.tick_ts

	SU.tower_block_inc(target)

	this.pos = target.pos

	return true
end

function scripts.mod_tower_stun.update(this, store)
	local m = this.modifier

	while store.tick_ts - m.ts < m.duration do
		coroutine.yield()
	end

	queue_remove(store, this)
end

function scripts.mod_tower_stun.remove(this, store)
	local m = this.modifier
	local target = store.entities[m.target_id]

	SU.tower_block_dec(target)

	return true
end

scripts.mod_shake_sprite = {}

function scripts.mod_shake_sprite.update(this, store, script)
	local m = this.modifier
	local target = store.entities[m.target_id]
	local ts = store.tick_ts
	local time_left = this.modifier.duration
	local base_mult = 1
	local base_offset = V.vclone(target.render.sprites[1].offset)

	while time_left > 0 do
		time_left = time_left - store.tick_length

		local decay = time_left / m.duration

		target.render.sprites[1].offset.x = base_offset.x + (math.random() * 2 - 1) * m.intensity * decay * base_mult
		target.render.sprites[1].offset.y = base_offset.y + (math.random() * 2 - 1) * m.intensity * decay * base_mult

		coroutine.yield()
	end

	target.render.sprites[1].offset.x = base_offset.x
	target.render.sprites[1].offset.y = base_offset.y

	queue_remove(store, this)
end

scripts.mod_configurable_dps = {}

function scripts.mod_configurable_dps.insert(this, store, script)
	local target = store.entities[this.modifier.target_id]

	if not target or target.health.dead then
		return false
	end

	if band(this.modifier.vis_flags, target.vis.bans) ~= 0 or band(this.modifier.vis_bans, target.vis.flags) ~= 0 then
		log.paranoid("mod %s cannot be applied to entity %s:%s because of vis flags/bans", this.template_name, target.id, target.template_name)

		return false
	end

	if target and target.unit and this.render then
		local s = this.render.sprites[1]

		s.ts = store.tick_ts

		if s.size_names then
			s.name = s.size_names[target.unit.size]
		end

		if s.size_scales then
			s.scale = s.size_scales[target.unit.size]
		end

		if target.render then
			s.z = target.render.sprites[1].z
		end
	end

	this.dps.damage_min = this.dps.damage_config[this.modifier.level]
	this.dps.damage_max = this.dps.damage_config[this.modifier.level]
	this.dps.ts = store.tick_ts - this.dps.damage_every
	this.modifier.ts = store.tick_ts

	signal.emit("mod-applied", this, target)

	return true
end

scripts.enemy_basic_with_random_range = {}

function scripts.enemy_basic_with_random_range.insert(this, store, script)
	if scripts.enemy_basic.insert(this, store, script) then
		for _, a in ipairs(this.ranged.attacks) do
			if a.max_range_variance then
				a.max_range = a.max_range + math.random(0, a.max_range_variance)
			end
		end

		return true
	else
		return false
	end
end

scripts.enemy_shadow_blades = {}

function scripts.enemy_shadow_blades.update(this, store, script)
	local function check_smokebomb()
		return not this.health.dead and this.health.hp < this.health.hp_max * this.smokebomb.hp_threshold and this.enemy.can_do_magic and P:nodes_to_goal(this.nav_path) >= this.smokebomb.min_nodes_to_exit
	end

	::label_94_0::

	while true do
		if this.health.dead then
			SU.y_enemy_death(store, this)

			return
		end

		if this.unit.is_stunned then
			SU.y_enemy_stun(store, this)
		else
			if check_smokebomb() then
				U.animation_start(this, this.smokebomb.animation, nil, store.tick_ts, 1)

				if U.y_wait(store, this.smokebomb.delay, function()
					return this.health.dead or this.unit.is_stunned
				end) then
					goto label_94_0
				end

				this.health_bar.alpha = 0
				this.health.hp = this.health.hp_max
				this.health.ignore_damage = true
				this.vis.bans = F_ALL
				this.trigger_deselect = true

				S:queue(this.smokebomb.sound)

				local smoke = E:create_entity(this.smokebomb.smoke_t)

				if smoke.aura then
					smoke.aura.source_id = this.id
					smoke.aura.ts = store.tick_ts
				end

				smoke.pos = V.vclone(this.pos)

				queue_insert(store, smoke)
				U.y_animation_wait(this)
				queue_remove(store, this)

				return
			end

			if not SU.y_enemy_mixed_walk_melee_ranged(store, this, false, check_smokebomb, check_smokebomb, check_smokebomb) then
				-- block empty
			else
				coroutine.yield()
			end
		end
	end
end

scripts.aura_shadow_blades_smoke = {}

function scripts.aura_shadow_blades_smoke.insert(this, store, script)
	this.aura.ts = store.tick_ts

	if this.render then
		for _, s in pairs(this.render.sprites) do
			s.ts = store.tick_ts
		end
	end

	this.aura.duration = get_difficulty_field_value(store, this.aura.duration)
	this.actual_duration = this.aura.duration

	local nearest_nodes = P:nearest_nodes(this.pos.x, this.pos.y)
	local pi, spi, ni = unpack(nearest_nodes[1])

	this.pos = P:node_pos(pi, 1, ni)
	this.decals = {}
	this.decals_pos = {
		P:node_pos(pi, 1, ni - 4),
		P:node_pos(pi, 1, ni),
		P:node_pos(pi, 1, ni + 4),
		P:node_pos(pi, 2, ni - 2),
		P:node_pos(pi, 2, ni + 2),
		P:node_pos(pi, 3, ni - 2),
		P:node_pos(pi, 3, ni + 2)
	}

	for k, v in pairs(this.decals_pos) do
		local decal = E:create_entity(this.decal_t)

		decal.pos = v
		decal.render.sprites[1].ts = store.tick_ts - fts(math.random(0, 15))
		decal.tween.ts = store.tick_ts

		queue_insert(store, decal)
		table.insert(this.decals, decal)
	end

	return true
end

function scripts.aura_shadow_blades_smoke.remove(this, store, script)
	for k, v in pairs(this.decals) do
		v.tween.ts = store.tick_ts
		v.tween.reverse = true
		v.tween.remove = true
	end

	return true
end

scripts.mod_shadow_blades_smoke = {}

function scripts.mod_shadow_blades_smoke.insert(this, store, script)
	local m = this.modifier
	local target = store.entities[m.target_id]

	if not target or target.health.dead then
		return false
	end

	if band(this.modifier.vis_flags, target.vis.bans) ~= 0 or band(this.modifier.vis_bans, target.vis.flags) ~= 0 then
		log.paranoid("mod %s cannot be applied to entity %s:%s because of vis flags/bans", this.template_name, target.id, target.template_name)

		return false
	end

	if target and target.unit and this.render then
		for i = 1, #this.render.sprites do
			local s = this.render.sprites[i]

			s.flip_x = target.render.sprites[1].flip_x
			s.ts = store.tick_ts

			if s.size_names then
				s.name = s.size_names[target.unit.size]
			end
		end
	end

	if target then
		if target.dodge then
			target._old_dodge = target.dodge
		end

		E:add_comps(target, "dodge")

		target.dodge.chance = 1
		target.dodge.show_pop = true
		target.dodge.silent = true
		target.dodge.ranged = true
	end

	return true
end

function scripts.mod_shadow_blades_smoke.remove(this, store, script)
	local m = this.modifier
	local target = store.entities[m.target_id]

	if target then
		if target._old_dodge then
			target.dodge = target._old_dodge
		else
			target.dodge = nil
		end
	end

	return true
end

scripts.enemy_crow = {}

function scripts.enemy_crow.update(this, store)
	local shadow_sprite = this.render.sprites[2]

	U.y_animation_play(this, "in", nil, store.tick_ts, 1)
	U.animation_start(this, "idle", nil, store.tick_ts, true)

	while true do
		if this.health.dead then
			shadow_sprite.hidden = true

			SU.y_enemy_death(store, this)

			return
		end

		if this.unit.is_stunned then
			SU.y_enemy_stun(store, this)
		else
			SU.y_enemy_walk_until_blocked(store, this)
		end
	end
end

scripts.enemy_demon_imp = {}

function scripts.enemy_demon_imp.update(this, store)
	local shadow_sprite = this.render.sprites[2]

	U.animation_start(this, "idle", nil, store.tick_ts, true)

	while true do
		if this.health.dead then
			shadow_sprite.hidden = true

			SU.y_enemy_death(store, this)

			return
		end

		if this.unit.is_stunned then
			SU.y_enemy_stun(store, this)
		else
			SU.y_enemy_walk_until_blocked(store, this)
		end
	end
end

scripts.enemy_crowcaller = {}

function scripts.enemy_crowcaller.update(this, store, script)
	local as = this.timed_attacks.list[1]

	as.ts = store.tick_ts

	local cg = store.count_groups[as.count_group_type]
	local spawn_count = get_difficulty_field_value(store, as.spawn_count)

	local function ready_to_spawn()
		return store.tick_ts - as.ts > as.cooldown and this.enemy.can_do_magic and (not cg[as.count_group_name] or cg[as.count_group_name] < as.count_group_max)
	end

	local function break_fn()
		return ready_to_spawn() and P:nodes_to_goal(this.nav_path.pi, this.nav_path.spi, this.nav_path.ni) > this.spawn_crow_node_limit
	end

	::label_103_0::

	while true do
		if this.health.dead then
			SU.y_enemy_death(store, this)

			return
		end

		if this.unit.is_stunned then
			SU.y_enemy_stun(store, this)
		else
			if ready_to_spawn() and P:nodes_to_goal(this.nav_path.pi, this.nav_path.spi, this.nav_path.ni) > this.spawn_crow_node_limit then
				S:queue(as.sound)

				as.ts = store.tick_ts

				U.animation_start(this, as.animation, nil, store.tick_ts, false)

				if SU.y_enemy_wait(store, this, as.cast_time) or #this.enemy.blockers > 0 then
					goto label_103_0
				end

				if spawn_count == 1 then
					local crow = E:create_entity(as.entity)

					crow.nav_path.pi = this.nav_path.pi
					crow.nav_path.spi = this.nav_path.spi
					crow.nav_path.ni = this.nav_path.ni + 6
					crow.pos = P:node_pos(crow.nav_path.pi, crow.nav_path.spi, crow.nav_path.ni)
					crow.pos.y = crow.pos.y + 1
					crow.source_id = this.id
					crow.enemy.gold = 0
					crow.render.sprites[1].flip_x = this.render.sprites[1].flip_x

					queue_insert(store, crow)
				else
					local spi_history = {}
					local ni_history = {}

					for i = 1, spawn_count do
						local crow = E:create_entity(as.entity)

						crow.nav_path.pi = this.nav_path.pi
						crow.nav_path.spi = get_random_round_robin(spi_history, 3)
						crow.nav_path.ni = this.nav_path.ni + get_random_round_robin(ni_history, 4, 8)
						crow.pos = P:node_pos(crow.nav_path.pi, crow.nav_path.spi, crow.nav_path.ni)
						crow.pos.y = crow.pos.y + 1
						crow.source_id = this.id
						crow.enemy.gold = 0
						crow.render.sprites[1].flip_x = this.render.sprites[1].flip_x

						queue_insert(store, crow)
					end
				end

				U.y_animation_wait(this)
			end

			if not SU.y_enemy_mixed_walk_melee_ranged(store, this, false, break_fn, false) then
				-- block empty
			else
				coroutine.yield()
			end
		end
	end
end

scripts.enemy_headhunter = {}

function scripts.enemy_headhunter.can_instakill(this, store, attack, target)
	return target.health and target.health.hp / target.health.hp_max <= get_difficulty_field_value(store, attack.hp_threshold) and band(attack.vis_bans, target.vis.flags) == 0
end

scripts.enemy_goblin = {}

function scripts.enemy_goblin.update(this, store, script)
	if this.spawn_from_bullet then
		this.render.sprites[1].flip_x = this.start_flipped

		U.y_animation_play(this, "fall", nil, store.tick_ts)

		local nearest

		if P:is_path_active(this.path_to_spawn) then
			nearest = P:nearest_nodes(this.pos.x, this.pos.y, {
				this.path_to_spawn
			}, {
				1,
				2,
				3
			})
		else
			nearest = P:nearest_nodes(this.pos.x, this.pos.y, nil, {
				1,
				2,
				3
			}, true)
		end

		local path_pi, path_spi, path_ni

		if #nearest > 0 then
			path_pi, path_spi, path_ni = unpack(nearest[1])
		end

		this.nav_path.pi = path_pi
		this.nav_path.spi = path_spi
		this.nav_path.ni = path_ni
	end

	while true do
		if this.health.dead then
			SU.y_enemy_death(store, this)

			return
		end

		if this.unit.is_stunned then
			SU.y_enemy_stun(store, this)
		elseif not SU.y_enemy_mixed_walk_melee_ranged(store, this, false) then
			-- block empty
		else
			coroutine.yield()
		end
	end
end

scripts.enemy_orc_warrior = {}

function scripts.enemy_orc_warrior.update(this, store, script)
	local aura = E:create_entity(this.rage.aura)

	aura.aura.source_id = this.id
	aura.aura.ts = store.tick_ts

	queue_insert(store, aura)

	local function can_rage()
		return this.trigger_rage and this.enemy.can_do_magic and not U.has_modifiers(store, this, this.rage.mod)
	end

	::label_108_0::

	while true do
		if this.health.dead then
			SU.y_enemy_death(store, this)

