		if this.unit.is_stunned then
			SU.y_enemy_stun(store, this)
		else
			if this.trigger_rage then
				S:queue(this.rage.sound)

				this.trigger_rage = false

				U.animation_start(this, this.rage.animation, nil, store.tick_ts, false)

