scripts.enemy_orc_wildling = {}

function scripts.enemy_orc_wildling.update(this, store, script)
	local worg_mode = false
	local worg_check_ts = store.tick_ts
	local trigger_mode_change = false
	local normal_angles = this.render.sprites[1].angles.walk
	local normal_speed = this.motion.max_speed

	E:get_template(this.worg_mode.mod).slow.factor = get_difficulty_field_value(store, this.worg_mode.speed)

	local mod

	local function check_worg_mode_change()
		if store.tick_ts - worg_check_ts < 0.25 then
			return false
		end

		worg_check_ts = store.tick_ts

		local range = worg_mode and this.worg_mode.range * 1.2 or this.worg_mode.range
		local targets = U.find_enemies_in_range(store.entities, this.pos, 0, range, this.vis.flags, 0, function(e, o)
			return e.template_name == "enemy_worg" or e.template_name == "enemy_rider_goblin"
		end)

		trigger_mode_change = worg_mode ~= (targets and #targets >= 1)
		worg_mode = targets and #targets >= 1

		return trigger_mode_change
	end

	while true do
		if this.health.dead then
			SU.y_enemy_death(store, this)

			return
		end

		if this.unit.is_stunned then
			SU.y_enemy_stun(store, this)
		else
			if trigger_mode_change then
				trigger_mode_change = false

				if worg_mode then
					S:queue(this.worg_mode.sound_in)

					this.render.sprites[1].angles.walk = this.worg_mode.angles_walk
					mod = E:create_entity(this.worg_mode.mod)
					mod.modifier.target_id = this.id
					mod.modifier.source_id = this.id

					queue_insert(store, mod)
				else
					this.render.sprites[1].angles.walk = normal_angles

					if mod then
						mod.modifier.duration = 0
					end

					mod = nil
				end
			end

			if not SU.y_enemy_mixed_walk_melee_ranged(store, this, false, check_worg_mode_change) then
				-- block empty
			else
				coroutine.yield()
			end
		end
	end
end

scripts.enemy_rider_goblin = {}

function scripts.enemy_rider_goblin.update(this, store, script)
	while true do
		if this.health.dead then
			local can_spawn = band(this.health.last_damage_types, this.no_spawn_damage_types) == 0

			if can_spawn and store.level.run_complete and store.waves_finished then
				local enemies_left = table.filter(store.entities, function(_, e)
					return e.main_script and (e.main_script.co or e.main_script.runs > 0) and (e.enemy and e.health and not e.health.dead or e.enemy and e.death_spawns or e.spawner and not e.spawner.eternal or e.picked_enemies and #e.picked_enemies > 0 or e.tunnel and #e.tunnel.picked_enemies > 0) and e.id ~= this.id
				end)

				can_spawn = #enemies_left > 0
			end

			if can_spawn and not this.forced_death then
				local c = E:create_entity(this.spawn_controller)

				c.worg = this

				queue_insert(store, c)

				this.sound_events.death = this.sound_death_and_spawn
			end

			SU.y_enemy_death(store, this)

			return
		end

		if this.unit.is_stunned then
			SU.y_enemy_stun(store, this)
		elseif not SU.y_enemy_mixed_walk_melee_ranged(store, this, false) then
			-- block empty
		else
			coroutine.yield()
		end
	end
end

scripts.controller_rider_goblin_spawn = {}

function scripts.controller_rider_goblin_spawn.update(this, store, script)
	local np = this.worg.nav_path
	local nodes_ahead = math.random(this.min_nodes_ahead, this.max_nodes_ahead)
	local nodes_to_end = P:nodes_to_goal(np.pi, np.spi, np.ni)

	if nodes_to_end <= this.spawn_max_nodes_to_exit then
		nodes_ahead = 1
	end

	local dest = P:node_pos(np.pi, np.spi, np.ni + nodes_ahead)
	local offset_x = this.start_offset.x

	if this.worg.render.sprites[1].flip_x then
		offset_x = offset_x * -1
	end

	local b = E:create_entity(this.spawn_bullet)

	b.pos.x, b.pos.y = this.worg.pos.x + offset_x, this.worg.pos.y + this.start_offset.y
	b.bullet.from = V.vclone(b.pos)
	b.bullet.to = dest
	b.bullet.source_id = this.worg.id
	b.path_to_spawn = np.pi

	queue_insert(store, b)
	queue_remove(store, this)
end

scripts.bullet_enemy_flying = {}

function scripts.bullet_enemy_flying.update(this, store, script)
	local b = this.bullet
	local shadow, shadow_start_pos

	if this.decal_shadow then
		shadow = E:create_entity(this.decal_shadow)
		shadow.pos = V.vclone(b.from)
		shadow.pos.y = b.from.y - 25

		queue_insert(store, shadow)

		shadow_start_pos = V.vclone(shadow.pos)
	end

	while store.tick_ts - b.ts + store.tick_length < b.flight_time do
		coroutine.yield()

		b.last_pos.x, b.last_pos.y = this.pos.x, this.pos.y
		this.pos.x, this.pos.y = SU.position_in_parabola(store.tick_ts - b.ts, b.from, b.speed, b.g)

		if b.align_with_trajectory then
			this.render.sprites[1].r = V.angleTo(this.pos.x - b.last_pos.x, this.pos.y - b.last_pos.y)
		elseif b.rotation_speed then
			this.render.sprites[1].r = this.render.sprites[1].r + b.rotation_speed * store.tick_length
		end

		if b.hide_radius then
			this.render.sprites[1].hidden = V.dist(this.pos.x, this.pos.y, b.from.x, b.from.y) < b.hide_radius or V.dist(this.pos.x, this.pos.y, b.to.x, b.to.y) < b.hide_radius
		end

		if shadow then
			shadow.pos.x = shadow_start_pos.x + (b.to.x - shadow_start_pos.x) * ((store.tick_ts - b.ts) / b.flight_time)
			shadow.pos.y = shadow_start_pos.y + (b.to.y - shadow_start_pos.y) * ((store.tick_ts - b.ts) / b.flight_time)

			local height = this.pos.y - shadow.pos.y
			local s = km.clamp(0.6, 1, 40 / height)

			shadow.render.sprites[1].scale = V.vv(s)
		end
	end

	local goblin = E:create_entity(b.hit_payload)

	goblin.pos = V.vclone(b.to)
	goblin.spawn_from_bullet = true
	goblin.path_to_spawn = this.path_to_spawn
	goblin.start_flipped = b.from.x > b.to.x

	queue_insert(store, goblin)

	if b.hit_fx then
		local hfx = E:create_entity(b.hit_fx)

		hfx.pos = V.vclone(b.to)
		hfx.render.sprites[1].ts = store.tick_ts

		queue_insert(store, hfx)
	end

	if shadow then
		queue_remove(store, shadow)
	end

	queue_remove(store, this)
end

scripts.enemy_troll_warrior_landing = {}

function scripts.enemy_troll_warrior_landing.update(this, store)
	U.y_animation_wait(this, 1)
	scripts.enemy_mixed_cliff.update(this, store)
end

scripts.enemy_troll_warrior_stage_13_suicide_glider = {}

function scripts.enemy_troll_warrior_stage_13_suicide_glider.insert(this, store)
	local np = this.nav_path
	local banned_paths = {
		np.pi,
		7,
		8,
		9,
		10,
		11,
		12
	}
	local paths = {}

	for i = 1, #P.paths do
		if not table.contains(banned_paths, i) then
			table.insert(paths, i)
		end
	end

	local subpaths = {
		1,
		2,
		3
	}
	local nn = P:nearest_nodes(this.pos.x, this.pos.y, paths, subpaths)

	np.pi = nn[1][1]
	np.spi = nn[1][2]
	np.ni = nn[1][3]

	return scripts.enemy_basic.insert(this, store)
end

scripts.enemy_troll_champion_jumper = {}

function scripts.enemy_troll_champion_jumper.update(this, store)
	local walk = true
	local jump_i = 1
	local dest = P:node_pos(this.nav_path.pi, this.nav_path.spi, this.jump_points[jump_i][1])
	local old_speed = this.motion.max_speed
	local old_hb_offset_y = this.health_bar.offset.y
	local old_cr_offset_y = this.ui.click_rect.pos.y
	local old_ho_offset_y = this.unit.hit_offset.y
	local old_mo_offset_y = this.unit.mod_offset.y
	local y_offset = 0
	local y_velocity, y_accel
	local bans = this.vis.bans
	local shadow_sprite = this.render.sprites[2]
	local shadow_tween = this.tween

	if this.force_center_path then
		this.nav_path.spi = 1
	end

	local function calc_gravity(d)
		local t = d / this.motion.max_speed

		y_accel = -2 * this.jump_speed.y / t
	end

	local function calc_velocity(t, startx, destx)
		y_velocity = -(this.jump_gravity / 2) * t
		this.motion.max_speed = math.abs(destx - startx) / t
	end

	local function is_in_gap(pos, gap)
		local start = P:node_pos(this.nav_path.pi, this.nav_path.spi, gap[1])
		local finish = P:node_pos(this.nav_path.pi, this.nav_path.spi, gap[2])
		local dirx = finish.x - start.x
		local diry = finish.y - start.y
		local tx = (pos.x - start.x) / dirx
		local ty = (pos.y - start.y) / diry

		return math.max(tx, ty) < 1
	end

	local function fall_death(start_y_velocity, start_y_offset, over_void)
		this.render.sprites[1].z = over_void and this.fall_void_z or Z_OBJECTS

		U.animation_start(this, "death_2", not this.render.sprites[1].flip_x, store.tick_ts, true)

		local y_velocity = math.min(this.default_start_y_velocity, start_y_velocity)
		local y_accel = this.fall_gravity
		local dist_acum = 0
		local distance_to_despawn = over_void and math.abs(this.pos.y + this.render.sprites[1].offset.y - this.y_to_die) or start_y_offset

		while distance_to_despawn > math.abs(dist_acum) do
			y_velocity = y_velocity + y_accel * store.tick_length

			if over_void then
				this.pos.y = this.pos.y + y_velocity * store.tick_length
			else
				this.render.sprites[1].offset.y = this.render.sprites[1].offset.y + y_velocity * store.tick_length
			end

			dist_acum = dist_acum + y_velocity * store.tick_length

			coroutine.yield()
		end
	end

	local function should_hide_shadow_in_flight()
		return this.disappearing_shadows and (this.jump_points[jump_i][3] or not this.jump_points[jump_i][4] or is_in_gap(this.pos, this.jump_points[jump_i][4])) or false
	end

	this.vis.flags = U.flag_set(this.vis.flags, F_FLYING)
	this.motion.max_speed = old_speed

	U.set_destination(this, dest)

	while true do
		if this.health.dead then
			local is_void = this.jump_points[jump_i][3] or not this.jump_points[jump_i][4] or is_in_gap(this.pos, this.jump_points[jump_i][4])

			if not walk then
				if is_void then
					shadow_sprite.hidden = true
					this.unit.show_blood_pool = false
				end

				fall_death(y_velocity, y_offset, is_void)
			end

			shadow_sprite.hidden = true

			SU.y_enemy_death(store, this)

			return
		end

		if walk and this.unit.is_stunned then
			SU.y_enemy_stun(store, this)
		else
			if walk then
				local an, af = U.animation_name_facing_point(this, "walk", this.motion.dest)

				U.animation_start(this, an, af, store.tick_ts, true)

				local reached_dest = U.walk(this, store.tick_length)

				walk = not reached_dest

				if not walk then
					dest = P:node_pos(this.nav_path.pi, this.nav_path.spi, this.jump_points[jump_i][2])

					U.y_animation_play(this, "jump", dest.x < this.pos.x, store.tick_ts)

					bans = this.vis.bans
					this.vis.bans = U.flag_set(this.vis.bans, F_ALL)

					U.set_destination(this, dest)

					if this.jump_mode == "time" then
						y_accel = this.jump_gravity

						calc_velocity(this.jump_time, this.pos.x, dest.x)
					elseif this.jump_mode == "velocity" then
						this.motion.max_speed = this.jump_speed.x
						y_velocity = this.jump_speed.y

						calc_gravity(V.dist(this.pos.x, this.pos.y, dest.x, dest.y))
					end

					shadow_sprite.hidden = false

					if should_hide_shadow_in_flight() then
						shadow_tween.reverse = false
						shadow_tween.disabled = false
						shadow_tween.ts = store.tick_ts
					end
				end
			end

			if not walk then
				local reached_dest = U.walk(this, store.tick_length)

				this.nav_path.ni = P:nearest_nodes(dest.x, dest.y, {
					this.nav_path.pi
				}, {
					this.nav_path.spi
				})[1][3]
				y_velocity = y_velocity + y_accel * store.tick_length
				y_offset = km.clamp(0, 1e+99, y_offset + y_velocity * store.tick_length)

				if y_velocity > 0 then
					if this.render.sprites[1].name ~= "air_up" then
						U.animation_start(this, "air_up", nil, store.tick_ts, true)
					end
				elseif this.render.sprites[1].name ~= "air_down" then
					U.animation_start(this, "air_down", nil, store.tick_ts, true)
				end

				this.render.sprites[1].offset = v(0, y_offset)
				this.health_bar.offset.y = old_hb_offset_y + y_offset
				this.ui.click_rect.pos.y = old_cr_offset_y + y_offset
				this.unit.hit_offset.y = old_ho_offset_y + y_offset
				this.unit.mod_offset.y = old_mo_offset_y + y_offset

				if shadow_tween.disabled and shadow_sprite.alpha == 255 and should_hide_shadow_in_flight() then
					shadow_tween.reverse = false
					shadow_tween.disabled = false
					shadow_tween.ts = store.tick_ts
				end

				if shadow_tween.disabled and shadow_sprite.alpha == 0 and not should_hide_shadow_in_flight() then
					shadow_tween.reverse = true
					shadow_tween.disabled = false
					shadow_tween.ts = store.tick_ts
				end

				walk = reached_dest

				if walk then
					shadow_sprite.hidden = true
					y_offset = 0
					y_velocity = 0
					this.render.sprites[1].offset = v(0, 0)
					this.health_bar.offset.y = old_hb_offset_y
					this.ui.click_rect.pos.y = old_cr_offset_y
					this.unit.hit_offset.y = old_ho_offset_y
					this.unit.mod_offset.y = old_mo_offset_y
					this.vis.bans = bans

					U.y_animation_play(this, "land", nil, store.tick_ts)

					this.motion.max_speed = old_speed
					jump_i = jump_i + 1

					if jump_i > #this.jump_points then
						break
					end

					dest = P:node_pos(this.nav_path.pi, this.nav_path.spi, this.jump_points[jump_i][1])

					U.set_destination(this, dest)
				end
			end
		end

		coroutine.yield()
	end

	this.vis.flags = U.flag_clear(this.vis.flags, F_FLYING)
	this.nav_path.ni = P:nearest_nodes(this.pos.x, this.pos.y, {
		this.nav_path.pi
	}, {
		1
	})[1][3]

	local next, new = P:next_entity_node(this, store.tick_length)

	if not next then
		log.debug("(%s) %s has no valid next node", this.id, this.template_name)

		return false
	end

	U.set_destination(this, next)
	U.set_heading(this, next)
	scripts.enemy_mixed.update(this, store)
end

scripts.enemy_troll_glider = {}

function scripts.enemy_troll_glider.update(this, store)
	local shadow_sprite = this.render.sprites[2]

	while true do
		if this.health.dead then
			if band(this.health.last_damage_types, bor(DAMAGE_DISINTEGRATE)) ~= 0 and this.unit.can_disintegrate and this.unit.disintegrate_fx then
				local fx = E:create_entity(this.unit.disintegrate_fx)

				fx.pos.x, fx.pos.y = this.pos.x, this.pos.y
				fx.render.sprites[1].scale = V.vv(1)
				fx.render.sprites[1].ts = store.tick_ts

				if fx.render.sprites[1].size_names then
					fx.render.sprites[1].name = fx.render.sprites[1].size_names[this.unit.size]
				end

				if band(this.vis.flags, F_FLYING) ~= 0 and this.unit.hit_offset then
					fx.render.sprites[1].offset.y = this.unit.hit_offset.y
				end

				queue_insert(store, fx)

				this.unit.hide_during_death = true
				this.unit.show_blood_pool = false
			end

			if band(this.health.last_damage_types, bor(DAMAGE_INSTAKILL, DAMAGE_EAT)) ~= 0 then
				queue_remove(store, this)

				return
			end

			if band(this.health.last_damage_types, bor(DAMAGE_NO_SPAWNS)) ~= 0 then
				queue_remove(store, this)

				return
			end

			if band(this.health.last_damage_types, bor(DAMAGE_DISINTEGRATE)) == 0 then
				local fx = E:create_entity(this.death_fx)

				fx.pos = V.vclone(this.pos)
				fx.pos.x, fx.pos.y = fx.pos.x + this.death_fx_offset.x, fx.pos.y + this.death_fx_offset.y
				fx.render.sprites[1].ts = store.tick_ts
				fx.render.sprites[1].flip_x = this.render.sprites[1].flip_x

				queue_insert(store, fx)
			end

			S:queue(this.sound_events.death, this.sound_events.death_args)

			if GR:cell_is(this.pos.x, this.pos.y, bor(TERRAIN_LAND, TERRAIN_ICE)) and not GR:cell_is(this.pos.x, this.pos.y, bor(TERRAIN_NOWALK)) then
				U.animation_start(this, "fall_loop", nil, store.tick_ts)

				local dt = fts(1)

				while this.render.sprites[1].offset.y > 0 do
					this.render.sprites[1].offset.y = this.render.sprites[1].offset.y - this.fall_speed * dt

					coroutine.yield()
				end

				shadow_sprite.hidden = true

				U.y_animation_play(this, "drop", nil, store.tick_ts, 1, 1)
				SU.y_enemy_death(store, this)
				queue_remove(store, this)

				return
			else
				queue_remove(store, this)

				return
			end
		end

		if this.unit.is_stunned then
			SU.y_enemy_stun(store, this)
		else
			SU.y_enemy_walk_until_blocked(store, this)
			coroutine.yield()
		end
	end
end

scripts.enemy_troll_glider_stage_13_suicide = {}

function scripts.enemy_troll_glider_stage_13_suicide.update(this, store)
	local sunray = find_all_t(store, this.sunray_t)[1]
	local shadow_sprite = this.render.sprites[2]
	local is_suicide = true
	local old_death_spawn = this.death_spawns.name
	local old_z = this.render.sprites[1].z
	local np = this.nav_path
	local is_left = this.nav_path.pi == this.left_path

	while true do
		if this.health.dead then
			if band(this.health.last_damage_types, bor(DAMAGE_INSTAKILL)) ~= 0 then
				queue_remove(store, this)

				return
			end

			S:queue(this.sound_events.death, this.sound_events.death_args)

			if band(this.health.last_damage_types, bor(DAMAGE_DISINTEGRATE)) == 0 and this.unit.can_disintegrate then
				local fx = E:create_entity(this.death_fx)

				fx.pos = V.vclone(this.pos)
				fx.pos.x, fx.pos.y = fx.pos.x + this.death_fx_offset.x, fx.pos.y + this.death_fx_offset.y
				fx.render.sprites[1].ts = store.tick_ts
				fx.render.sprites[1].flip_x = this.render.sprites[1].flip_x

				queue_insert(store, fx)
			end

			if GR:cell_is(this.pos.x, this.pos.y, bor(TERRAIN_LAND, TERRAIN_ICE)) and not GR:cell_is(this.pos.x, this.pos.y, bor(TERRAIN_NOWALK)) then
				U.animation_start(this, "fall_loop", nil, store.tick_ts)

				local dt = fts(1)

				while this.render.sprites[1].offset.y > 0 do
					this.render.sprites[1].offset.y = this.render.sprites[1].offset.y - this.fall_speed * dt

					coroutine.yield()
				end

				if shadow_sprite then
					shadow_sprite.hidden = true
				end

				U.y_animation_play(this, "drop", nil, store.tick_ts, 1, 1)
				SU.y_enemy_death(store, this)
				queue_remove(store, this)

				return
			else
				queue_remove(store, this)

				return
			end
		end

		if this.unit.is_stunned then
			SU.y_enemy_stun(store, this)
		else
			SU.y_enemy_walk_until_blocked(store, this, true, function()
				if np.ni > this.node_to_consider_too_far and this.render.sprites[1].z == old_z then
					this.render.sprites[1].z = Z_OBJECTS
					this.health_bar.z = Z_OBJECTS

					if this.render.sprites[2] then
						this.render.sprites[2].z = Z_OBJECTS
					end
				end

				if np.ni < this.node_to_consider_too_far and this.render.sprites[1].z == Z_OBJECTS then
					this.render.sprites[1].z = old_z
					this.health_bar.z = old_z

					if this.render.sprites[2] then
						this.render.sprites[2].z = old_z
					end
				end

				if is_suicide and not sunray.has_sorcerers(is_left) then
					is_suicide = false

					local banned_paths = {
						np.pi,
						9,
						10,
						11,
						12
					}
					local paths = {}

					for i = 1, #P.paths do
						if not table.contains(banned_paths, i) then
							table.insert(paths, i)
						end
					end

					local subpaths = {
						1,
						2,
						3
					}
					local nn = P:nearest_nodes(this.pos.x, this.pos.y, paths, subpaths)

					np.pi = nn[1][1]
					np.spi = nn[1][2]
					np.ni = nn[1][3]
					this.death_spawns.name = this.fallback_death_spawn_name
				end

				if not is_suicide and sunray.has_sorcerers(is_left) and np.ni < this.node_to_consider_too_far then
					is_suicide = true

					local paths = {
						7,
						8
					}
					local subpaths = {
						1,
						2,
						3
					}
					local nn = P:nearest_nodes(this.pos.x, this.pos.y, paths, subpaths)

					np.pi = nn[1][1]
					np.spi = nn[1][2]
					np.ni = nn[1][3]
					this.death_spawns.name = old_death_spawn
				end

				if is_suicide and sunray.has_sorcerers(is_left) then
					local sorc_id, sorc_position = sunray.get_sorcerer_position(is_left)

					if sorc_id and sorc_position and V.dist2(this.pos.x, this.pos.y, sorc_position.x, sorc_position.y) <= math.pow(this.trigger_distance, 2) then
						this.vis.bans = F_ALL
						this.health_bar.hidden = true

						if shadow_sprite then
							shadow_sprite.hidden = true
						end

						S:queue(this.sound_events.suicide)
						U.y_animation_play(this, this.anim_suicide, nil, store.tick_ts, 1, 1)

						local sorc = sunray.get_sorcerer(sorc_id)
						local n_sorc_id, n_sorc_position = sorc_id, sorc_position

						if not sorc then
							n_sorc_id, n_sorc_position = sunray.get_sorcerer_position(is_left)

							if n_sorc_id and n_sorc_position then
								sorc = sunray.get_sorcerer(n_sorc_id)
							end
						end

						n_sorc_position = n_sorc_position or sorc_position

						local suicide_bomb = E:create_entity(this.bullet)

						suicide_bomb.pos = V.v(this.pos.x + this.bullet_spawn_offset.x * (this.render.sprites[1].flip_x and -1 or 1), this.pos.y + this.bullet_spawn_offset.y)
						suicide_bomb.bullet.from = V.vclone(suicide_bomb.pos)
						suicide_bomb.bullet.to = n_sorc_position
						suicide_bomb.bullet.target_id = sorc and sorc.id or nil
						suicide_bomb.render.sprites[1].flip_x = this.render.sprites[1].flip_x
						suicide_bomb.render.sprites[1].r = V.angleTo(suicide_bomb.bullet.to.x - suicide_bomb.bullet.from.x, suicide_bomb.bullet.to.y - suicide_bomb.bullet.from.y)

						queue_insert(store, suicide_bomb)
						coroutine.yield()

						this.render.sprites[1].hidden = true

						queue_remove(store, this)

						return
					end
				end
			end)
			coroutine.yield()
		end
	end
end

scripts.bullet_troll_glider_stage_13_suicide = {}

function scripts.bullet_troll_glider_stage_13_suicide.update(this, store, script)
	local b = this.bullet
	local ease_tables = {
		this.pos,
		this.pos
	}
	local ease_keys = {
		"x",
		"y"
	}
	local froms = {
		b.from.x,
		b.from.y
	}
	local tos = {
		b.to.x,
		b.to.y
	}
	local last_pos = V.vclone(this.pos)

	this.render.sprites[1].r = V.angleTo(b.to.x - b.from.x, b.to.y - b.from.y)

	U.y_ease_keys(store, ease_tables, ease_keys, froms, tos, b.flight_time, "quad-in", function(dt, p)
		if b.align_with_trajectory then
			if this.render.sprites[1].flip_x then
				this.render.sprites[1].r = V.angleTo(last_pos.x - this.pos.x, last_pos.y - this.pos.y)
			else
				this.render.sprites[1].r = V.angleTo(this.pos.x - last_pos.x, this.pos.y - last_pos.y)
			end

			last_pos.x, last_pos.y = this.pos.x, this.pos.y
		end
	end)

	local hfx = E:create_entity(b.hit_fx)

	hfx.pos.x, hfx.pos.y = this.pos.x, this.pos.y
	hfx.render.sprites[1].ts = store.tick_ts
	hfx.render.sprites[1].flip_x = this.render.sprites[1].flip_x

	queue_insert(store, hfx)
	S:queue(this.sound_events.hit)

	local target = store.entities[b.target_id]

	if target then
		local d = E:create_entity("damage")

		d.source_id = this.id
		d.target_id = b.target_id
		d.value = math.random(b.damage_min, b.damage_max)
		d.damage_type = b.damage_type
		d.pop = b.pop
		d.pop_conds = b.pop_conds

		queue_damage(store, d)
	end

	queue_remove(store, this)
end

scripts.enemy_troll_crusher = {}

function scripts.enemy_troll_crusher.update(this, store, script)
	local ap = this.timed_attacks.list[1]

	ap.ts = store.tick_ts

	local pound_check_ts = store.tick_ts
	local trigger_pound = false

	local function should_pound()
		if not this.enemy.can_do_magic then
			return false
		end

		if trigger_pound then
			return true
		end

		if store.tick_ts - pound_check_ts < 0.25 then
			return false
		end

		if store.tick_ts - ap.ts < ap.cooldown then
			return false
		end

		pound_check_ts = store.tick_ts

		local aura_t = E:get_template(ap.aura)
		local towers = U.find_towers(store.entities, this.pos, 0, aura_t.aura.radius - ap.stun_radius_offset, function(v, o)
			return v.tower.type ~= "holder" and v.tower.type ~= "build_animation" and (not v.tower_holder or not v.tower_holder.blocked) and (not aura_t.aura.allowed_templates or table.contains(aura_t.aura.allowed_templates, v.template_name)) and (not aura_t.aura.excluded_templates or not table.contains(aura_t.aura.excluded_templates, v.template_name) and not U.has_modifier_types(store, v, MOD_TYPE_PROTECTION))
		end)

		trigger_pound = towers and #towers > 0

		return trigger_pound
	end

	local function deal_area_damage(hit_pos, attack)
		local targets = U.find_soldiers_in_range(store.entities, hit_pos, 0, attack.damage_radius, attack.vis_flags, attack.vis_bans, function(v, o)
			return not attack.fn_filter or attack.fn_filter(this, store, attack, v)
		end)

		if targets then
			for i, e in ipairs(targets) do
				if attack.count and i > attack.count then
					break
				end

				local d = E:create_entity("damage")

				d.source_id = this.id
				d.target_id = e.id
				d.damage_type = attack.damage_type
				d.value = math.ceil(this.unit.damage_factor * math.random(attack.damage_min, attack.damage_max))
				d.pop = attack.pop
				d.pop_chance = attack.pop_chance
				d.pop_conds = attack.pop_conds

				queue_damage(store, d)

				if attack.mod then
					local mod = E:create_entity(attack.mod)

					mod.modifier.target_id = e.id
					mod.modifier.source_id = this.id

					queue_insert(store, mod)
				end
			end
		end
	end

	::label_139_0::

	while true do
		if this.health.dead then
			SU.y_enemy_death(store, this)

			return
		end

		if this.unit.is_stunned then
			SU.y_enemy_stun(store, this)
		else
			if trigger_pound then
				this.health.ignore_damage = true

				U.animation_start(this, ap.animation, nil, store.tick_ts, false)

				trigger_pound = false
				ap.ts = store.tick_ts

				S:queue(this.sound_events.skill)

				if SU.y_enemy_wait(store, this, ap.hit_time) then
					this.health.ignore_damage = false

					goto label_139_0
				end

				local af = this.render.sprites[1].flip_x
				local hit_pos = V.vclone(this.pos)

				if ap.hit_offset then
					hit_pos.x = hit_pos.x + (af and -1 or 1) * ap.hit_offset.x
					hit_pos.y = hit_pos.y + ap.hit_offset.y
				end

				local aura = E:create_entity(ap.aura)

				aura.aura.source_id = this.id
				aura.aura.ts = store.tick_ts
				aura.pos = V.vclone(this.pos)

				queue_insert(store, aura)
				deal_area_damage(hit_pos, ap)

				if ap.hit_fx then
					local fx = E:create_entity(ap.hit_fx)

					fx.pos = V.vclone(hit_pos)
					fx.render.sprites[1].ts = store.tick_ts

					queue_insert(store, fx)
				end

				if ap.hit_decal then
					local fx = E:create_entity(ap.hit_decal)

					fx.pos = V.vclone(hit_pos)
					fx.render.sprites[1].ts = store.tick_ts

					queue_insert(store, fx)
				end

				this.health.ignore_damage = false

				while not U.animation_finished(this, 1) and not SU.enemy_interrupted(this) do
					coroutine.yield()
				end
			end

			if not SU.y_enemy_mixed_walk_melee_ranged(store, this, false, should_pound, should_pound) then
				-- block empty
			else
				coroutine.yield()
			end
		end
	end
end

scripts.mod_troll_crusher_tower_stun = {}

function scripts.mod_troll_crusher_tower_stun.insert(this, store)
	local m = this.modifier
	local target = store.entities[m.target_id]
	local source = store.entities[m.source_id]

	if not target then
		queue_remove(store, this)

		return
	end

	this.pos = target.pos

	return true
end

function scripts.mod_troll_crusher_tower_stun.update(this, store)
	local m = this.modifier
	local target = store.entities[m.target_id]
	local source = store.entities[m.source_id]

	if not target then
		queue_remove(store, this)

		return
	end

	local t = this.max_delay * (V.dist(target.pos.x, target.pos.y, source.pos.x, source.pos.y) / this.max_range)

	U.y_wait(store, t)
	S:queue(this.sound_events.block)

	this.render.sprites[1].hidden = false

	U.animation_start(this, "start", nil, store.tick_ts)

	m.ts = store.tick_ts

	SU.tower_block_inc(target)

	local start_ts = store.tick_ts

	this.render.sprites[1].ts = store.tick_ts

	U.y_animation_wait(this)
	U.animation_start(this, "loop", nil, store.tick_ts)

	while store.tick_ts - start_ts < m.duration - this.end_anim_duration do
		coroutine.yield()
	end

	U.y_animation_play(this, "end", nil, store.tick_ts)
	queue_remove(store, this)
end

scripts.enemy_frost_icecaller = {}

function scripts.enemy_frost_icecaller.update(this, store, script)
	local ai = this.timed_attacks.list[1]
	local target_pos, trigger_icicles

	local function find_soldiers_and_heroes(center, range)
		local targets = U.find_soldiers_in_range(store.entities, center, ai.min_range, range, ai.vis_flags, ai.vis_bans, function(v, o)
			return not v.pending_removal and (v.soldier or v.hero)
		end)

		if targets then
			table.sort(targets, function(e1, e2)
				return V.dist(e1.pos.x, e1.pos.y, this.pos.x, this.pos.y) < V.dist(e2.pos.x, e2.pos.y, this.pos.x, this.pos.y)
			end)
		end

		return targets
	end

	local function remove_val(t, w)
		for i, v in ipairs(t) do
			if w == v then
				table.remove(t, i)
			end
		end
	end

	local function icicles_attack()
		local distance = ai.icicle_row_spread

		local function spawn_icicle(pi, spi, ni)
			spi = spi or math.random(1, 3)

			local pos = P:node_pos(pi, spi, ni)

			pos.x = pos.x + math.random(-ai.icicle_spread, ai.icicle_spread)
			pos.y = pos.y + ai.icicles_y_offset + math.random(-ai.icicle_spread, ai.icicle_spread)

			local ic = E:create_entity(ai.icicle_t)

			ic.pos = pos

			if ic.pos.x < this.pos.x then
				ic.render.sprites[1].flip_x = true
			end

			ic.render.sprites[1].scale = V.vv(U.frandom(ai.scale_min, ai.scale_max))

			queue_insert(store, ic)
		end

		local function is_valid_path(k, pi)
			return (not store.level.ignore_walk_backwards_paths or not table.contains(store.level.ignore_walk_backwards_paths, pi)) and P:is_path_active(pi)
		end

		local available_paths = {}

		for k, v in pairs(P.paths) do
			table.insert(available_paths, k)
		end

		if store.level.ignore_walk_backwards_paths then
			available_paths = table.filter(available_paths, is_valid_path)
		end

		local pos = target_pos
		local direction = 1

		if pos then
			local ftni = P:nearest_nodes(pos.x, pos.y, {
				this.nav_path.pi
			})[1][3]

			if ftni < this.nav_path.ni then
				direction = -1
			end
		end

		local nearest = P:nearest_nodes(pos.x, pos.y, available_paths, nil, true)

		if #nearest > 0 then
			local pi, spi, ni = unpack(nearest[1])

			ni = ni - direction * ai.icicles_row_anticipation

			S:queue(ai.sound_fall, {
				delay = ai.stalactite_fall_time
			})

			for nx = ni, ni + (ai.icicle_rows - 1) * distance * direction, distance * direction do
				if P:is_node_valid(pi, nx) then
					local order = {
						2,
						1,
						3
					}

					for i = 1, 3 - ai.icicles_per_row do
						local r = math.random(1, 3)

						remove_val(order, r)
					end

					for i = 1, ai.icicles_per_row do
						spawn_icicle(pi, order[i], nx)
						U.y_wait(store, ai.duration / (ai.icicle_rows * ai.icicles_per_row))
					end
				end
			end
		end
	end

	local function should_icicles()
		if not this.enemy.can_do_magic then
			return false
		end

		local targets = find_soldiers_and_heroes(this.pos, ai.range)

		if targets and targets[1] then
			target_pos = V.vclone(targets[1].pos)
		end

		trigger_icicles = targets and #targets > 0 and store.tick_ts - ai.ts > ai.cooldown and #this.enemy.blockers == 0

		return trigger_icicles
	end

	::label_146_0::

	while true do
		if this.health.dead then
			SU.y_enemy_death(store, this)

			return
		end

		if this.unit.is_stunned then
			SU.y_enemy_stun(store, this)
		else
			if trigger_icicles then
				S:queue(ai.sound_channel)
				U.animation_start(this, ai.animation, target_pos.x < this.pos.x, store.tick_ts, false)

				trigger_icicles = false
				ai.ts = store.tick_ts

				if SU.y_enemy_wait(store, this, ai.cast_time) then
					goto label_146_0
				end

				icicles_attack()
				U.y_animation_wait(this)
			end

			if not SU.y_enemy_mixed_walk_melee_ranged(store, this, false, should_icicles) then
				-- block empty
			else
				coroutine.yield()
			end
		end
	end
end

scripts.decal_frost_icecaller_icicle = {}

function scripts.decal_frost_icecaller_icicle.update(this, store)
	U.animation_start(this, this.anim_in, nil, store.tick_ts)
	U.y_wait(store, this.damage_delay)

	local targets = U.find_soldiers_in_range(store.entities, this.pos, 0, this.damage_radius, this.vis_flags, this.vis_bans, function(v, o)
		return not v.pending_removal and (v.soldier or v.hero)
	end)

	if targets then
		for _, enemy in pairs(targets) do
			local d = E:create_entity("damage")

			d.damage_type = this.damage_type
			d.value = U.frandom(this.damage_min, this.damage_max)
			d.source_id = this.id
			d.target_id = enemy.id

			queue_damage(store, d)
		end
	end

	U.animation_start(this, this.anim_loop, nil, store.tick_ts)
	U.y_wait(store, U.frandom(1, 2))
	U.y_animation_play(this, this.anim_out, nil, store.tick_ts)
	queue_remove(store, this)
end

scripts.enemy_troll_pathfinder = {}

function scripts.enemy_troll_pathfinder.insert(this, store, script)
	this.on_ice_mod = E:create_entity(this.on_ice_mod)
	this.on_ice_mod.modifier.target_id = this.id

	queue_insert(store, this.on_ice_mod)

	return scripts.enemy_basic.insert(this, store, script)
end

function scripts.enemy_troll_pathfinder.update(this, store, script)
	local old_angles = this.render.sprites[1].angles.walk

	local function got_on_ice()
		this.render.sprites[1].angles.walk = this.render.sprites[1].angles.slide

		if this.enemy.blockers and #this.enemy.blockers > 0 then
			U.unblock_all(store, this)
		end
	end

	local function left_ice()
		this.render.sprites[1].angles.walk = old_angles

		if this.enemy.blockers and #this.enemy.blockers > 0 then
			U.unblock_all(store, this)
		end
	end

	this.on_ice_mod.on_entered_terrain_fn = got_on_ice
	this.on_ice_mod.on_left_terrain_fn = left_ice

	while true do
		if this.health.dead then
			if this.on_ice_mod.on_terrain then
				this.unit.hide_during_death = true
				this.unit.death_animation = nil
				this.death_spawns.concurrent_with_death = true
				this.death_spawns.quantity = 1

				signal.emit("trolls-on-ice")
			end

			SU.y_enemy_death(store, this)

			return
		end

		if this.unit.is_stunned then
			SU.y_enemy_stun(store, this)
		else
			SU.y_enemy_mixed_walk_melee_ranged(store, this)
		end

		coroutine.yield()
	end
end

scripts.decal_troll_pathfinder_dead_sliding = {}

function scripts.decal_troll_pathfinder_dead_sliding.update(this, store, script)
	local arrived = false
	local s = P:node_pos(this.nav_path.pi, this.nav_path.spi, this.nav_path.ni)
	local f = P:node_pos(this.nav_path.pi, this.nav_path.spi, this.nav_path.ni + 2)
	local dir = V.v(f.x - s.x, f.y - s.y)
	local ndirx, ndiry = V.normalize(dir.x, dir.y)
	local t = -this.motion.max_speed / this.motion.accel
	local fposx = this.pos.x + ndirx * this.motion.max_speed * t + ndirx * this.motion.accel / 2 * t * t
	local fposy = this.pos.y + ndiry * this.motion.max_speed * t + ndiry * this.motion.accel / 2 * t * t
	local dt = store.tick_length

	this.render.sprites[1].ts = store.tick_ts
	this.motion.dest = V.v(fposx, fposy)
	this.motion.arrived = false

	if this.sound_in then
		S:queue(this.sound_in)
	end

	while not arrived do
		U.walk(this, dt)

		arrived = this.motion.max_speed == 0

		coroutine.yield()
	end

	U.y_wait(store, this.wait_time_after_stop)
	queue_remove(store, this)
end

scripts.enemy_frost_baiter = {}

function scripts.enemy_frost_baiter.insert(this, store, script)
	this.on_ice_mod = E:create_entity(this.on_ice_mod)
	this.on_ice_mod.modifier.target_id = this.id

	queue_insert(store, this.on_ice_mod)

	return scripts.enemy_basic.insert(this, store, script)
end

function scripts.enemy_frost_baiter.y_jump(this, store, dest, break_fn)
	this._flying = true

	local b = this.bullet

	b.from = V.vclone(this.pos)
	b.to = dest
	b.ts = store.tick_ts
	b.last_pos = V.vclone(this.pos)
	this.bullet.speed = SU.initial_parabola_speed(b.from, b.to, b.flight_time, b.g)

	local original_y = this.pos.y
	local max_height = 90

	while store.tick_ts - b.ts + store.tick_length < b.flight_time do
		coroutine.yield()

		b.last_pos.x, b.last_pos.y = this.pos.x, this.pos.y
		this.pos.x, this.pos.y = SU.position_in_parabola(store.tick_ts - b.ts, b.from, b.speed, b.g)

		local t = (store.tick_ts - b.ts) / b.flight_time
		local coly = b.from.y + (b.to.y - b.from.y) * t

		this.render.sprites[2].offset.y = coly - this.pos.y

		local height = this.pos.y - coly
		local scale = km.clamp(0.5, 1, (max_height - height) / max_height)

		this.render.sprites[2].scale = V.vv(scale)

		if b.align_with_trajectory then
			this.render.sprites[1].r = V.angleTo(this.pos.x - b.last_pos.x, this.pos.y - b.last_pos.y)
		elseif b.rotation_speed then
			this.render.sprites[1].r = this.render.sprites[1].r + b.rotation_speed * store.tick_length
		end

		if b.hide_radius then
			this.render.sprites[1].hidden = V.dist(this.pos.x, this.pos.y, b.from.x, b.from.y) < b.hide_radius or V.dist(this.pos.x, this.pos.y, b.to.x, b.to.y) < b.hide_radius
		end

		if break_fn and break_fn() then
			break
		end
	end

	this._flying = false
end

function scripts.enemy_frost_baiter.update(this, store, script)
	local cont, blocker
	local bait_ts = store.tick_ts - this.bait_cooldown

	this.render.sprites[2].hidden = true

	while true do
		if this.health.dead then
			SU.y_enemy_death(store, this)

			return
		end

		if this.unit.is_stunned then
			SU.y_enemy_stun(store, this)
		else
			cont, blocker = SU.y_enemy_walk_until_blocked(store, this, false)

			if not cont then
				-- block empty
			elseif not blocker or not SU.y_wait_for_blocker(store, this, blocker) then
				-- block empty
			else
				while SU.can_melee_blocker(store, this, blocker) do
					local np = this.nav_path
					local nodes_to_end = P:nodes_to_goal(np.pi, np.spi, np.ni)

					if this.enemy.can_do_magic and store.tick_ts - bait_ts > this.bait_cooldown and nodes_to_end > this.bait_max_nodes_to_exit then
						bait_ts = store.tick_ts

						local bait = E:create_entity(this.decoy_t)

						bait.pos = V.vclone(this.pos)
						bait.render.sprites[1].flip_x = this.render.sprites[1].flip_x
						bait.heading.angle = this.render.sprites[1].flip_x and math.pi / 2 or 0

						queue_insert(store, bait)

						for i, v in ipairs(this.enemy.blockers) do
							local blocker = store.entities[v]

							U.unblock_target(store, blocker)
							U.block_enemy(store, blocker, bait)
						end

						local np = this.nav_path
						local nodes_ahead = math.random(this.min_jump_distance, this.max_jump_distance)
						local water_check_distance = (nodes_ahead + this.node_water_tolerance) * P.average_node_dist
						local fwd_entrances = table.filter(store.entities, function(k, v)
							local is_and_near = v.template_name == "decal_stage_10_well" and U.is_inside_ellipse(v.pos, this.pos, water_check_distance)

							if not is_and_near then
								return false
							end

							if v.paths and not table.contains(v.paths, np.pi) then
								return false
							end

							local nearest_node = P:nearest_nodes(v.pos.x, v.pos.y, {
								np.pi
							}, {
								np.spi
							}, true)[1]

							return nearest_node[3] > np.ni
						end)
						local going_to_puddle = fwd_entrances and #fwd_entrances > 0
						local dest = going_to_puddle and V.vclone(fwd_entrances[1].pos) or P:node_pos(np.pi, np.spi, np.ni + nodes_ahead)

						S:queue(this.sound_events.jump)
						U.animation_start(this, "jumpball", nil, store.tick_ts, true)

						this.render.sprites[2].hidden = false
						this.vis._force_old_bans = this.vis.bans
						this.vis.bans = U.flag_set(this.vis.bans, F_BLOCK)
						this.render.sprites[1].z = Z_BULLETS

						scripts.enemy_frost_baiter.y_jump(this, store, dest)

						this.render.sprites[1].z = Z_OBJECTS

						if not this._passed_entrance then
							this.vis.bans = U.flag_clear(this.vis.bans, F_BLOCK)
						end

						this.render.sprites[2].hidden = true
						np.ni = np.ni + nodes_ahead

						break
					end

					if not SU.y_enemy_melee_attacks(store, this, blocker) then
						break
					end

					coroutine.yield()
				end
			end
		end

		coroutine.yield()
	end
end

scripts.enemy_magma_elemental = {}

function scripts.enemy_magma_elemental.insert(this, store, script)
	if not scripts.enemy_basic.insert(this, store, script) then
		return false
	end

	if this.play_spawn_animation then
		this._spawn_vis_bans = this.vis.bans
		this._spawn_ignore_damage = this.health.ignore_damage
		this.vis.bans = bor(F_ALL)
		this.health.ignore_damage = true
		this.health_bar.hidden = true
	end

	return true
end

function scripts.enemy_magma_elemental.update(this, store, script)
	if this.play_spawn_animation then
		U.animation_start(this, "spawn_loop", true, store.tick_ts, true)
		U.y_wait(store, this.spawn_loop_time)
		U.animation_start(this, "spawn", true, store.tick_ts, false)
		U.y_animation_wait(this)

		this.health_bar.hidden = nil
		this.vis.bans = this._spawn_vis_bans
		this.health.ignore_damage = this._spawn_ignore_damage

		if this.die_after_spawn then
			this.health_bar.hidden = true
			this.health.hp = 0

			while not this.health.dead do
				coroutine.yield()
			end
		end
	end

	return scripts.enemy_mixed.update(this, store, script)
end

