scripts.decal_dark_disciple_book = {}

function scripts.decal_dark_disciple_book.update(this, store, script)
	local source = store.entities[this.source_id]

	while true do
		if not source or not store.entities[this.source_id] or source.pending_removal then
			break
		end

		if source.health.dead or source.recall_book then
			break
		end

		coroutine.yield()
	end

	U.y_animation_play(this, "death", nil, store.tick_ts, 1, 1)
	queue_remove(store, this)
end

scripts.bullet_dark_disciple_tower_stun = {}

function scripts.bullet_dark_disciple_tower_stun.update(this, store, script)
	local b = this.bullet
	local mspeed = b.min_speed
	local target, ps
	local source = store.entities[b.source_id]
	local s = this.render.sprites[1]

	if b.rotation_speed then
		b.rotation_speed = b.rotation_speed * (b.to.x > this.pos.x and -1 or 1)

		if b.rotation_speed > 0 then
			s.flip_x = not s.flip_x
		end
	end

	if b.target_id then
		S:queue(this.sound_events.travel)
	else
		S:queue(this.sound_events.summon)
	end

	while V.dist(this.pos.x, this.pos.y, b.to.x, b.to.y) > mspeed * store.tick_length do
		if b.target_id then
			target = store.entities[b.target_id]
		end

		if not source or not store.entities[b.source_id] or source.pending_removal or source.recall_book or source.health.dead or not target then
			if source then
				source.recall_book = true
			end

			U.y_animation_play(this, "death", nil, store.tick_ts, 1, 1)
			queue_remove(store, this)

			return
		end

		if target then
			if b.max_track_distance then
				local d = math.max(math.abs(target.pos.x - b.to.x), math.abs(target.pos.y - b.to.y))

				if d > b.max_track_distance then
					b.target_id = nil
					target = nil
				end
			else
				b.to.x, b.to.y = target.pos.x, target.pos.y
			end
		end

		if b.rotation_speed then
			s.r = s.r + b.rotation_speed * store.tick_length
		else
			s.r = V.angleTo(this.pos.x - b.last_pos.x, this.pos.y - b.last_pos.y)
		end

		mspeed = mspeed + FPS * math.ceil(mspeed * (1 / FPS) * b.acceleration_factor)
		mspeed = km.clamp(b.min_speed, b.max_speed, mspeed)
		b.speed.x, b.speed.y = V.mul(mspeed, V.normalize(b.to.x - this.pos.x, b.to.y - this.pos.y))
		this.pos.x, this.pos.y = this.pos.x + b.speed.x * store.tick_length, this.pos.y + b.speed.y * store.tick_length

		if ps then
			ps.particle_system.emit_direction = this.render.sprites[1].r
		end

		coroutine.yield()
	end

	if target then
		if b.mod then
			local mod = E:create_entity(b.mod)

			mod.modifier.source_id = b.source_id
			mod.modifier.target_id = target.id

			queue_insert(store, mod)
		end

		if b.hit_payload then
			local hp = E:create_entity(b.hit_payload)

			hp.pos.x, hp.pos.y = b.to.x, b.to.y
			hp.source_id = b.source_id

			queue_insert(store, hp)
		end
	end

	queue_remove(store, this)
end

scripts.mod_enemy_dark_disciple_cage = {}

function scripts.mod_enemy_dark_disciple_cage.update(this, store)
	local m = this.modifier
	local target = store.entities[m.target_id]
	local source = store.entities[m.source_id]

	if not target or not source then
		queue_remove(store, this)

		return
	end

	m.ts = store.tick_ts

	SU.tower_block_inc(target)

	this.pos = target.pos

	if this.tween and not this.tween.disabled then
		this.tween.ts = store.tick_ts
	end

	S:queue(this.sound_in)
	U.animation_start(this, "in", nil, store.tick_ts)
	U.y_wait(store, fts(10))
	U.animation_start(this, "idle", nil, store.tick_ts, true)

	local start_ts = store.tick_ts

	while true do
		if not source or not store.entities[m.source_id] or source.pending_removal then
			break
		end

		if source.health.dead or this.remove or source.recall_book then
			break
		end

		coroutine.yield()
	end

	U.animation_start(this, "out", nil, store.tick_ts)
	S:queue(this.sound_out)
	U.y_wait(store, fts(11))
	SU.tower_block_dec(target)
	queue_remove(store, this)
end

scripts.enemy_dark_knight = {}

function scripts.enemy_dark_knight.update(this, store, script)
	local kill_count = 0

	local function create_decal_on_kill()
		local decal = E:create_entity(this.decal_on_kill)

		decal.render.sprites[1].ts = store.tick_ts
		decal.target_id = this.id

		queue_insert(store, decal)
	end

	local function check_transformation()
		if #this.track_kills.killed > kill_count then
			kill_count = #this.track_kills.killed
		end

		if #this.track_kills.killed >= this.kills_to_transform then
			this.health.ignore_damage = true

			S:queue(this.transformation_sound)
			U.y_animation_play(this, "transform", nil, store.tick_ts, 1)
			SU.do_death_spawns(store, this)
			queue_remove(store, this)
		end
	end

	::label_232_0::

	while true do
		if this.health.dead then
			SU.y_enemy_death(store, this)

			return
		end

		if this.unit.is_stunned then
			SU.y_enemy_stun(store, this)
		else
			if not SU.y_enemy_mixed_walk_melee_ranged(store, this, false, nil, nil, nil) then
				goto label_232_0
			else
				check_transformation()
			end

			coroutine.yield()
		end
	end
end

scripts.enemy_skeleton = {}

function scripts.enemy_skeleton.insert(this, store, script)
	if not scripts.enemy_basic.insert(this, store, script) then
		return false
	end

	if this.render.sprites[1].name == "raise" then
		this._raise_vis_bans = this.vis.bans
		this._raise_ignore_damage = this.health.ignore_damage
		this.vis.bans = bor(F_ALL)
		this.health.ignore_damage = true
		this.health_bar.hidden = true
	end

	return true
end

function scripts.enemy_skeleton.update(this, store, script)
	if this.render.sprites[1].name == "raise" then
		if this.sound_events and this.sound_events.raise then
			S:queue(this.sound_events.raise, this.sound_events.raise_args)
		end

		local an, af = U.animation_name_facing_point(this, "raise", this.motion.dest)

		U.y_animation_play(this, an, af, store.tick_ts, 1)

		if not this.health.dead then
			this.health_bar.hidden = nil
		end

		if this._raise_vis_bans then
			this.vis.bans = this._raise_vis_bans
			this.health.ignore_damage = this._raise_ignore_damage
		end

		U.animation_start(this, "idle", af, store.tick_ts, true)
	end

	return scripts.enemy_mixed.update(this, store, script)
end

scripts.enemy_necromancer = {}

function scripts.enemy_necromancer.get_info(this)
	local min, max, damage_type

	if this.timed_attacks and this.timed_attacks.list then
		local ba = this.timed_attacks.list[1]

		min, max = ba.damage_min, ba.damage_max
		damage_type = ba.damage_type
	end

	if min and max then
		min, max = math.ceil(min), math.ceil(max)
	end

	local armor = band(this.health.immune_to, DAMAGE_PHYSICAL) ~= 0 and 1 or this.health.armor
	local magic_armor = band(this.health.immune_to, DAMAGE_MAGICAL) ~= 0 and 1 or this.health.magic_armor

	return {
		type = STATS_TYPE_ENEMY,
		hp = this.health.hp,
		hp_max = this.health.hp_max,
		damage_min = min,
		damage_max = max,
		damage_type = damage_type,
		damage_icon = this.info.damage_icon,
		armor = armor,
		magic_armor = magic_armor,
		lives = this.enemy and this.enemy.lives_cost or 0,
		immune = this.health.immune_to == DAMAGE_ALL_TYPES
	}
end

function scripts.enemy_necromancer.update(this, store, script)
	local ca = this.timed_attacks.list[1]
	local bullet_return_offset = V.v(-7, 35)
	local ca_damage = math.ceil(U.frandom(ca.damage_min, ca.damage_max))
	local sa = this.timed_actions.list[1]
	local cg = store.count_groups[sa.count_group_type]

	sa.ts = store.tick_ts + sa.first_cooldown

	local summon_amount = get_difficulty_field_value(store, sa.max_count)
	local summon_delay = fts(30 / summon_amount)

	local function break_animation()
		return this.health.dead or this.unit.is_stunned
	end

	local function custom_ranged_attack(target, attack)
		if store.tick_ts - attack.ts < attack.cooldown then
			return false
		end

		attack.ts = store.tick_ts

		local an, af, ai = U.animation_name_facing_point(this, ca.animations[1], target.pos)

		U.animation_start(this, an, af, store.tick_ts, false)

		while store.tick_ts - attack.ts < attack.shoot_time do
			if this.health.dead or this.unit.is_stunned and not attack.ignore_stun then
				return false
			end

			coroutine.yield()
		end

		local target_pos_x = target.pos.x + target.unit.hit_offset.x
		local target_pos_y = target.pos.y + target.unit.hit_offset.y
		local distance_to_target = V.dist(this.pos.x, this.pos.y, target_pos_x, target_pos_y)
		local bullet_speed = distance_to_target / ca.duration
		local bullet = E:create_entity(attack.bullet)

		bullet.pos = V.v(target_pos_x, target_pos_y)
		bullet.bullet.from = V.vclone(bullet.pos)
		bullet.bullet.to = V.v(this.pos.x + bullet_return_offset.x, this.pos.y + bullet_return_offset.y)
		bullet.bullet.target_id = target.id
		bullet.bullet.source_id = this.id
		bullet.bullet.min_speed = bullet_speed
		bullet.bullet.max_speed = bullet_speed

		queue_insert(store, bullet)

		local d = E:create_entity("damage")

		d.damage_type = ca.damage_type
		d.value = ca_damage
		d.target_id = target.id
		d.source_id = this.id

		queue_damage(store, d)

		local particle = E:create_entity("ps_bullet_soul_trail_necromancer")

		particle.particle_system.track_id = bullet.id

		queue_insert(store, particle)
		U.animation_start(this, ca.animations[2], af, store.tick_ts, true)

		if U.y_wait(store, ca.duration + fts(3), break_animation) then
			queue_remove(store, bullet)
		end

		if this and this.health then
			this.health.hp = km.clamp(0, this.health.hp_max, this.health.hp + ca_damage * ca.lifesteal)
		end

		U.y_animation_play(this, ca.animations[3], nil, store.tick_ts, 1)
		U.animation_start(this, "idle", af, store.tick_ts, false)

		return true
	end

	local function summon_count_exceeded()
		return cg[sa.count_group_name] and cg[sa.count_group_name] >= sa.count_group_max
	end

	local function summon_skeletons()
		if summon_count_exceeded() or not this.enemy.can_do_magic then
			return false
		end

		U.animation_start(this, sa.animation, nil, store.tick_ts, false)
		S:queue(sa.sound)

		for i = 1, summon_amount do
			if SU.y_enemy_wait(store, this, summon_delay) then
				return false
			end

			if i ~= 1 and summon_count_exceeded() then
				break
			end

			local e = E:create_entity(sa.entity_names[1])
			local noff = sa.summon_offsets[i] or sa.summon_offsets[1]

			e.nav_path.pi = this.nav_path.pi
			e.nav_path.spi = noff[1]
			e.nav_path.ni = this.nav_path.ni + math.random(noff[2], noff[3])
			e.enemy.gold = 0

			E:add_comps(e, "count_group")

			e.count_group.name = sa.count_group_name
			e.count_group.type = sa.count_group_type

			if P:is_node_valid(e.nav_path.pi, e.nav_path.ni) then
				queue_insert(store, e)
			end

			coroutine.yield()
		end

		if SU.y_enemy_animation_wait(this) then
			return false
		end

		sa.ts = store.tick_ts
	end

	local function ready_to_summon()
		if U.get_blocker(store, this) then
			sa.ts = store.tick_ts

			return false
		elseif store.tick_ts - sa.ts >= sa.cooldown and not summon_count_exceeded() and P:nodes_to_goal(this.nav_path.pi, this.nav_path.spi, this.nav_path.ni) > sa.summon_skeleton_node_limit then
			summon_skeletons()
		end
	end

	::label_238_0::

	while true do
		if this.health.dead then
			SU.y_enemy_death(store, this)

			return
		end

		if this.unit.is_stunned then
			SU.y_enemy_stun(store, this)
		else
			local cont, blocker, ranged = SU.y_enemy_walk_until_blocked(store, this, false, ready_to_summon)

			if not cont then
				goto label_238_0
			elseif blocker then
				SU.y_enemy_melee_attacks(store, this, blocker)
			else
				custom_ranged_attack(ranged, ca)
			end

			coroutine.yield()
		end
	end
end

scripts.enemy_death_rider = {}

function scripts.enemy_death_rider.update(this, store, script)
	local a = this.timed_attacks.list[1]

	a.ts = store.tick_ts - a.cooldown

	local normal_speed = this.motion.max_speed
	local galloping = false
	local gallop_ts = 0
	local mod

	while true do
		if this.health.dead then
			SU.y_enemy_death(store, this)

			return
		end

		if this.unit.is_stunned then
			SU.y_enemy_stun(store, this)
		else
			if not a.disabled and store.tick_ts - a.ts > a.cooldown then
				local soldiers = U.find_soldiers_in_range(store.entities, this.pos, 0, a.range, a.vis_flags, a.vis_bans, function(v, o)
					local ni = P:nearest_nodes(v.pos.x, v.pos.y, {
						this.nav_path.pi
					})[1][3]

					return ni > this.nav_path.ni
				end)

				if soldiers and #soldiers > 0 then
					a.ts = store.tick_ts
					mod = E:create_entity(a.mod)
					mod.modifier.target_id = this.id
					mod.modifier.source_id = this.id

					queue_insert(store, mod)
					S:queue(a.sound)
				end
			end

			SU.y_enemy_walk_step(store, this)
		end
	end
end

scripts.enemy_dark_construct = {}

function scripts.enemy_dark_construct.update(this, store, script)
	local function spawn_darklings()
		local np = this.nav_path
		local offset_x = this.start_offset.x

		if this.render.sprites[1].flip_x then
			offset_x = offset_x * -1
		end

		U.y_animation_play(this, "death_in", this.render.sprites[1].flip_x, store.tick_ts, 1, 1)
		U.animation_start(this, "death_loop", this.render.sprites[1].flip_x, store.tick_ts, 1, 1)

		for i = 1, this.spawn_count do
			local nodes_ahead = math.random(this.min_nodes_ahead, this.max_nodes_ahead)
			local nodes_to_end = P:nodes_to_goal(np.pi, np.spi, np.ni)

			if nodes_to_end <= this.spawn_max_nodes_to_exit then
				nodes_ahead = 1
			end

			local dest = P:node_pos(np.pi, math.random(1, 3), np.ni + nodes_ahead)
			local b = E:create_entity(this.spawn_bullet)

			b.pos.x, b.pos.y = this.pos.x + offset_x, this.pos.y + this.start_offset.y
			b.bullet.from = V.vclone(b.pos)
			b.bullet.to = dest
			b.bullet.source_id = this.id
			b.path_to_spawn = np.pi

			queue_insert(store, b)

			local spawn_fx = E:create_entity(this.spawn_fx)

			spawn_fx.pos.x, spawn_fx.pos.y = this.pos.x + this.spawn_fx_offset.x, this.pos.y + this.spawn_fx_offset.y
			spawn_fx.render.sprites[1].ts = store.tick_ts

			queue_insert(store, spawn_fx)

			local delay_between_shots = fts(U.frandom(0, this.spawn_count / 23))

			U.y_wait(store, delay_between_shots)
		end
	end

	while true do
		if this.health.dead then
			local can_spawn = band(this.health.last_damage_types, this.no_spawn_damage_types) == 0

			if can_spawn and store.level.run_complete and store.waves_finished then
				local enemies_left = table.filter(store.entities, function(_, e)
					return e.main_script and (e.main_script.co or e.main_script.runs > 0) and (e.enemy and e.health and not e.health.dead or e.enemy and e.death_spawns or e.spawner and not e.spawner.eternal or e.picked_enemies and #e.picked_enemies > 0 or e.tunnel and #e.tunnel.picked_enemies > 0) and e.id ~= this.id
				end)

				can_spawn = #enemies_left > 0
			end

			if can_spawn and not this.forced_death then
				spawn_darklings()
			end

			SU.y_enemy_death(store, this)

			return
		end

		if this.unit.is_stunned then
			SU.y_enemy_stun(store, this)
		elseif not SU.y_enemy_mixed_walk_melee_ranged(store, this, false) then
			-- block empty
		else
			coroutine.yield()
		end
	end
end

scripts.enemy_darkling = {}

function scripts.enemy_darkling.update(this, store, script)
	if this.spawn_from_bullet then
		this.render.sprites[1].flip_x = this.start_flipped

		U.y_animation_play(this, "land", nil, store.tick_ts)

		local nearest

		if P:is_path_active(this.path_to_spawn) then
			nearest = P:nearest_nodes(this.pos.x, this.pos.y, {
				this.path_to_spawn
			}, {
				1,
				2,
				3
			})
		else
			nearest = P:nearest_nodes(this.pos.x, this.pos.y, nil, {
				1,
				2,
				3
			}, true)
		end

		local path_pi, path_spi, path_ni

		if #nearest > 0 then
			path_pi, path_spi, path_ni = unpack(nearest[1])
		end

		this.nav_path.pi = path_pi
		this.nav_path.spi = path_spi
		this.nav_path.ni = path_ni
	end

	local move_anim = "walk"
	local roll_ts
	local normal_speed = this.motion.max_speed
	local rolling = false

	this.roll_ts = store.tick_ts - this.roll_cooldown

	while true do
		if this.health.dead then
			SU.y_enemy_death(store, this)

			return
		end

		if this.unit.is_stunned then
			SU.y_enemy_stun(store, this)
		else
			if store.tick_ts - this.roll_ts > this.roll_cooldown then
				local targets = U.find_targets_in_range(store.entities, this.pos, 0, this.roll_range, 0, bor(F_ENEMY), function(v, o)
					local ni = P:nearest_nodes(v.pos.x, v.pos.y, {
						this.nav_path.pi
					})[1][3]

					return ni > this.nav_path.ni
				end)

				if targets and #targets > 0 then
					move_anim = "roll"
					this.roll_ts = store.tick_ts
					this.motion.max_speed = this.roll_movement_speed
					roll_ts = store.tick_ts
					rolling = true
				end
			end

			if rolling and store.tick_ts - roll_ts > this.roll_duration then
				move_anim = "walk"
				this.motion.max_speed = normal_speed
				rolling = false
			end

			SU.y_enemy_walk_step(store, this, move_anim, 1)
		end
	end
end

