			vh
		}

		coroutine.yield()
	end
end

local function y_hero_melee_block_and_attacks(store, hero)
	local target = SU.soldier_pick_melee_target(store, hero)

	if not target then
		return false, A_NO_TARGET
	end

	if SU.soldier_move_to_slot_step(store, hero, target) then
		if hero.melee and hero.melee.forced_cooldown and hero.melee.force_cooldown_at_slot_walk then
			hero.melee.forced_ts = store.tick_ts
		end

		return true
	end

	local attack = SU.soldier_pick_melee_attack(store, hero, target)

	if not attack then
		return false, A_IN_COOLDOWN
	end

	local upg = UP:get_upgrade("heroes_lethal_focus")
	local triggered_lethal_focus = false
	local attack_pop = attack.pop
	local attack_pop_chance = attack.pop_chance

	if attack.basic_attack and upg then
		if not hero._lethal_focus_deck then
			hero._lethal_focus_deck = SU.deck_new(upg.trigger_cards, upg.total_cards)
		end

		triggered_lethal_focus = SU.deck_draw(hero._lethal_focus_deck)
	end

	if triggered_lethal_focus then
		hero.unit.damage_factor = hero.unit.damage_factor * upg.damage_factor
		attack.pop = {
			"pop_crit_heroes"
		}
		attack.pop_chance = 1
	end

	local triggered_crit = attack.critical_chance and math.random() < attack.critical_chance

	if triggered_crit then
		hero.unit.damage_factor = hero.unit.damage_factor * 2
		attack.pop = {
			"pop_crit_heroes"
		}
		attack.pop_chance = 1
	end

	if attack.xp_from_skill then
		SU.hero_gain_xp_from_skill(hero, hero.hero.skills[attack.xp_from_skill])
	end

	local attack_done

	if attack.loops then
		attack_done = SU.y_soldier_do_loopable_melee_attack(store, hero, target, attack)
	elseif attack.type == "area" then
		attack_done = SU.y_soldier_do_single_area_attack(store, hero, target, attack)
	else
		attack_done = SU.y_soldier_do_single_melee_attack(store, hero, target, attack)
	end

	if triggered_lethal_focus then
		hero.unit.damage_factor = hero.unit.damage_factor / upg.damage_factor
		attack.pop = attack_pop
		attack.pop_chance = attack_pop_chance
	end

	if triggered_crit then
		hero.unit.damage_factor = hero.unit.damage_factor / 2
		attack.pop = attack_pop
		attack.pop_chance = attack_pop_chance
	end

	if attack_done then
		return false, A_DONE
	else
		return true
	end
end

local function y_hero_ranged_attacks(store, hero)
	local target, attack, pred_pos = SU.soldier_pick_ranged_target_and_attack(store, hero)

	if not target then
		return false, A_NO_TARGET
	end

	if not attack then
		return false, A_IN_COOLDOWN
	end

	local upg = UP:get_upgrade("heroes_lethal_focus")
	local triggered_lethal_focus = false
	local bullet_t = E:get_template(attack.bullet)
	local bullet_use_unit_damage_factor = bullet_t.bullet.use_unit_damage_factor
	local bullet_pop = bullet_t.bullet.pop
	local bullet_pop_conds = bullet_t.bullet.pop_conds

	if attack.basic_attack and upg then
		if not hero._lethal_focus_deck then
			hero._lethal_focus_deck = SU.deck_new(upg.trigger_cards, upg.total_cards)
		end

		triggered_lethal_focus = SU.deck_draw(hero._lethal_focus_deck)
	end

	if triggered_lethal_focus then
		if bullet_t.bullet.damage_radius > 0 then
			hero.unit.damage_factor = hero.unit.damage_factor * upg.damage_factor_area
		else
			hero.unit.damage_factor = hero.unit.damage_factor * upg.damage_factor
		end

		bullet_t.bullet.use_unit_damage_factor = true
		bullet_t.bullet.pop = {
			"pop_crit"
		}
		bullet_t.bullet.pop_conds = DR_DAMAGE
	end

	local triggered_crit = bullet_t.bullet.critical_chance and math.random() < bullet_t.bullet.critical_chance

	if triggered_crit then
		hero.unit.damage_factor = hero.unit.damage_factor * 2
		bullet_t.bullet.use_unit_damage_factor = true
		bullet_t.bullet.pop = {
			"pop_crit"
		}
		bullet_t.bullet.pop_conds = DR_DAMAGE
	end

	local start_ts = store.tick_ts
	local attack_done

	U.set_destination(hero, hero.pos)

	if attack.loops then
		attack_done = SU.y_soldier_do_loopable_ranged_attack(store, hero, target, attack)
	else
		attack_done = SU.y_soldier_do_ranged_attack(store, hero, target, attack, pred_pos)
	end

	if attack_done then
		attack.ts = start_ts

		if attack.shared_cooldown then
			for _, aa in pairs(hero.ranged.attacks) do
				if aa ~= attack and aa.shared_cooldown then
					aa.ts = attack.ts
				end
			end
		end

		if hero.ranged.forced_cooldown then
			hero.ranged.forced_ts = start_ts
		end
	end

	if triggered_lethal_focus then
		hero.unit.damage_factor = hero.unit.damage_factor / upg.damage_factor
		bullet_t.bullet.use_unit_damage_factor = bullet_use_unit_damage_factor
		bullet_t.bullet.pop = bullet_pop
		bullet_t.bullet.pop_conds = bullet_pop_conds
	end

	if triggered_crit then
		hero.unit.damage_factor = hero.unit.damage_factor / 2
		bullet_t.bullet.use_unit_damage_factor = bullet_use_unit_damage_factor
		bullet_t.bullet.pop = bullet_pop
		bullet_t.bullet.pop_conds = bullet_pop_conds
	end

	if attack_done then
		return false, A_DONE
	else
		return true
	end
end

scripts.power_control_custom = {}

function scripts.power_control_custom.can_select_point(this, x, y, store)
	if not this.power_id then
		return false
	end

	local pc = E:get_template("power_" .. this.power_id .. "_control")

	if not pc.user_selection.can_select_point_fn or pc.user_selection.can_select_point_fn(pc, x, y, store) then
		return true
	end

	return false
end

function scripts.power_control_custom.get_cooldown(this, store)
	if not this.power_id then
		return false
	end

	local pc = E:get_template("power_" .. this.power_id .. "_control")
	local cooldown = pc.power_cooldown_fn and pc.power_cooldown_fn() or pc.cooldown

	cooldown = cooldown * GS.mode_power_cooldown_factor[(store.level_mode_6 or store.level_mode)]

	return cooldown
end

function scripts.power_control_custom.insert(this, store)
	local e = E:create_entity("power_" .. this.power_id .. "_control")

	e.pos.x, e.pos.y = this.pos.x, this.pos.y

	queue_insert(store, e)

	return false
end

scripts.item_control_custom = {}

function scripts.item_control_custom.can_select_point(this, x, y, store)
	local c = E:get_template("controller_item_" .. this.item)

	c.pos.x, c.pos.y = x, y

	return c.can_fire_fn(c, x, y, store)
end

function scripts.item_control_custom.insert(this, store)
	local e = E:create_entity("controller_item_" .. this.item)

	e.pos.x, e.pos.y = this.pos.x, this.pos.y

	queue_insert(store, e)

	return false
end

scripts.hero_gerald = {}

function scripts.hero_gerald.level_up(this, store, initial)
	if not initial then
		S:queue(this.sound_events.level_up)
	end

	local hl = this.hero.level
	local ls = this.hero.level_stats

	this.health.hp_max = ls.hp_max[hl]
	this.regen.health = ls.regen_health[hl]
	this.health.armor = ls.armor[hl]
	this.melee.attacks[1].damage_min = ls.melee_damage_min[hl]
	this.melee.attacks[1].damage_max = ls.melee_damage_max[hl]
	this.melee.attacks[2].damage_min = ls.melee_damage_min[hl]
	this.melee.attacks[2].damage_max = ls.melee_damage_max[hl]
	this.health.hp = this.health.hp_max
	this.hero.melee_active_status = {}

	for index, attack in ipairs(this.melee.attacks) do
		this.hero.melee_active_status[index] = attack.disabled
	end
end

function scripts.hero_gerald.insert(this, store)
	this.hero.fn_level_up(this, store, true)

	this.melee.order = U.attack_order(this.melee.attacks)
	this.timed_attacks.list[4].disabled = not this.hero.skills.ultimate.active

	return true
end

function scripts.hero_gerald.update(this, store)
	local h = this.health
	local brk, sta
	local old_tombstone_time = this.hero.tombstone_show_time
	local old_tombstone_respawn_animation = this.hero.tombstone_respawn_animation

	this.health_bar.hidden = false

	local sa, sb, sc, su, st1, st2 = this.hero.skills.skill_a, this.hero.skills.skill_b, this.hero.skills.skill_c, this.hero.skills.ultimate, this.hero.skills.talent_1, this.hero.skills.talent_2
	local saa = this.timed_attacks.list[1]

	saa.ts = store.tick_ts - saa.cooldown

	local sba = this.timed_attacks.list[2]

	sba.ts = store.tick_ts - sba.cooldown

	local sca = this.timed_attacks.list[3]

	sca.ts = store.tick_ts - sca.cooldown

	local ua = this.timed_attacks.list[4]

	ua.ts = store.tick_ts - ua.cooldown

	local ult_start_cd = store.wave_group_number == 0

	if not st1.disabled then
		this.dodge.chance = st1.chance
	end

	if not st2.disabled then
		local regen = E:create_entity(st2.aura)

		regen.aura.source_id = this.id

		queue_insert(store, regen)
	end

	while true do
		if ult_start_cd and store.wave_group_number > 0 then
			ult_start_cd = false
			ua.ts = store.tick_ts
		end

		if h.dead then
			if not sca.disabled and store.tick_ts - sca.ts > sca.cooldown then
				h.ignore_damage = true

				local a = sca

				a.ts = store.tick_ts

				U.animation_start(this, a.animation, nil, store.tick_ts, false)
				S:queue(a.sound)
				U.y_wait(store, a.cast_time)

				local decal = E:create_entity(a.decal)

				decal.pos = this.pos
				decal.render.sprites[1].ts = store.tick_ts

				queue_insert(store, decal)

				if this.soldier.target_id and store.entities[this.soldier.target_id] and not store.entities[this.soldier.target_id].health.dead then
					local mod_teleport = E:create_entity(a.mod)

					mod_teleport.modifier.target_id = this.soldier.target_id
					mod_teleport.modifier.source_id = this.id

					queue_insert(store, mod_teleport)
				end

				SU.hero_gain_xp_from_skill(this, sc)

				this.health.death_finished_ts = nil
				this.health_bar.hidden = false
				this.ui.can_click = true
				this.health.dead = false
				this.force_respawn = nil
				this.health.hp = this.health.hp_max * a.hp_ptg
				this.health.ignore_damage = false

				SU.y_hero_animation_wait(this)
			else
				if band(h.last_damage_types, bor(DAMAGE_EAT)) ~= 0 then
					this.hero.tombstone_show_time = nil
					this.hero.tombstone_respawn_animation = nil
				end

				SU.y_hero_death_and_respawn_kr5(store, this)

				this.hero.tombstone_show_time = old_tombstone_time
				this.hero.tombstone_respawn_animation = old_tombstone_respawn_animation
			end

			if not st2.disabled then
				local regen = E:create_entity(st2.aura)

				regen.aura.source_id = this.id

				queue_insert(store, regen)
			end
		end

		if this.unit.is_stunned then
			SU.soldier_idle(store, this)
		else
			while this.nav_rally.new do
				if SU.y_hero_new_rally(store, this) then
					goto label_266_1
				end
			end

			if SU.hero_level_up(store, this) then
				U.y_animation_play(this, "level_up", nil, store.tick_ts, 1)
			end

			if not ua.disabled and store.tick_ts - ua.ts > ua.cooldown and this.soldier.target_id ~= nil and this.motion.arrived then
				local a = ua
				local start_ts = store.tick_ts
				local target = store.entities[this.soldier.target_id]

				if not target or target.health.dead then
					goto label_266_0
				end

				U.animation_start(this, a.animation, nil, store.tick_ts, false)
				S:queue(a.sound_cast)
				S:queue(a.sound_taunt)

				if SU.y_hero_wait(store, this, fts(16)) then
					goto label_266_1
				end

				local enemies = U.find_enemies_in_range(store.entities, this.pos, 0, a.initial_stun_radius, a.vis_flags, a.vis_bans)

				enemies = enemies or {}

				if enemies and not any(enemies, function(v)
					return v.id == target.id
				end) then
					table.insert(enemies, 1, target)
				end

				for k, v in pairs(enemies) do
					local mod = E:create_entity(a.mod_initial_stun)

					mod.modifier.source_id = this.id
					mod.modifier.target_id = v.id

					queue_insert(store, mod)
				end

				S:queue(a.sound_hit)

				local start_ts = store.tick_ts

				while store.tick_ts - start_ts < a.hit_time - fts(16) do
					if SU.soldier_interrupted(this) then
						goto label_266_0
					end

					coroutine.yield()
				end

				a.ts = start_ts

				if a.shared_cooldown then
					for _, aa in pairs(this.melee.attacks) do
						if aa ~= a and aa.shared_cooldown then
							aa.ts = a.ts
						end
					end
				end

				local d = E:create_entity("damage")

				d.source_id = this.id
				d.target_id = target.id
				d.damage_type = a.damage_type
				d.value = math.ceil(this.unit.damage_factor * math.random(a.damage_min, a.damage_max))

				queue_damage(store, d)

				local mod = E:create_entity(a.mod_hit_stun)

				mod.modifier.source_id = this.id
				mod.modifier.target_id = target.id

				queue_insert(store, mod)

				local hit_pos = V.vclone(this.pos)

				if a.hit_offset then
					hit_pos.x = hit_pos.x + (this.render.sprites[1].flip_x and -1 or 1) * a.hit_offset.x
					hit_pos.y = hit_pos.y + a.hit_offset.y
				end

				local aura = E:create_entity(a.hit_aura)

				aura.pos = V.vclone(hit_pos)
				aura.aura.source_id = this.id
				aura.aura.excluded_entities = {
					target.id
				}

				queue_insert(store, aura)

				local decal = E:create_entity(a.hit_decal)

				decal.pos = V.vclone(this.pos)

				for i = 1, #decal.render.sprites do
					decal.render.sprites[i].ts = store.tick_ts
					decal.render.sprites[i].flip_x = this.render.sprites[i].flip_x
				end

				queue_insert(store, decal)
				SU.hero_gain_xp_from_skill(this, su)
				SU.y_hero_animation_wait(this)
				U.animation_start(this, "idle", nil, store.tick_ts, true)

				goto label_266_1
			end

			::label_266_0::

			brk, sta = y_hero_melee_block_and_attacks(store, this)

			if brk or sta ~= A_NO_TARGET then
				if not sba.disabled and store.tick_ts - sba.ts > sba.cooldown and this.soldier.target_id ~= nil and this.motion.arrived then
					local a = sba
					local start_ts = store.tick_ts

					U.animation_start(this, a.animation, nil, store.tick_ts, false)
					S:queue(a.sound)

					if SU.y_hero_wait(store, this, a.cast_time) then
						-- block empty
					else
						a.ts = start_ts

						SU.hero_gain_xp_from_skill(this, sb)

						local mod = E:create_entity(a.mod)

						mod.modifier.source_id = this.id
						mod.modifier.target_id = this.id

						queue_insert(store, mod)
						SU.y_hero_animation_wait(this)
						U.animation_start(this, "idle", nil, store.tick_ts, true)
					end
				end
			else
				if not saa.disabled and store.tick_ts - saa.ts > saa.cooldown then
					local a = saa
					local soldiers = U.find_soldiers_in_range(store.entities, this.pos, a.min_range, a.max_range, a.vis_flags, a.vis_bans, function(s, o)
						return s.id ~= this.id and s.soldier.target_id ~= nil
					end)

					if not soldiers or #soldiers < a.min_targets then
						SU.delay_attack(store, a, fts(10))
					else
						local start_ts = store.tick_ts

						U.animation_start(this, a.animation, nil, store.tick_ts, false)
						S:queue(a.sound)

						if SU.y_hero_wait(store, this, a.cast_time) then
							goto label_266_1
						end

						a.ts = start_ts

						SU.hero_gain_xp_from_skill(this, sa)

						local decal = E:create_entity(a.decal)

						decal.pos = this.pos
						decal.render.sprites[1].ts = store.tick_ts

						queue_insert(store, decal)

						for k, v in pairs(soldiers) do
							local mod = E:create_entity(a.mod)

							mod.modifier.source_id = this.id
							mod.modifier.target_id = v.id

							queue_insert(store, mod)
						end

						SU.y_hero_animation_wait(this)
						U.animation_start(this, "idle", nil, store.tick_ts, true)

						goto label_266_1
					end
				end

				if SU.soldier_go_back_step(store, this) then
					-- block empty
				else
					SU.soldier_idle(store, this)
					SU.soldier_regen(store, this)
				end
			end
		end

		::label_266_1::

		coroutine.yield()
	end
end

scripts.mod_gerald_skill_a = {}

function scripts.mod_gerald_skill_a.insert(this, store, script)
	local target = store.entities[this.modifier.target_id]

	if not target or target.health.dead then
		return false
	end

	if band(this.modifier.vis_flags, target.vis.bans) ~= 0 or band(this.modifier.vis_bans, target.vis.flags) ~= 0 then
		log.paranoid("mod %s cannot be applied to entity %s:%s because of vis flags/bans", this.template_name, target.id, target.template_name)

		return false
	end

	SU.armor_inc(target, this.armor_inc)
	SU.magic_armor_inc(target, this.armor_inc)
	signal.emit("mod-applied", this, target)

	return true
end

function scripts.mod_gerald_skill_a.update(this, store, script)
	local m = this.modifier
	local target = store.entities[m.target_id]

	if not target then
		queue_remove(store, this)

		return
	end

	this.pos = target.pos

	local fx = E:create_entity(this.fx)

	fx.pos = this.pos
	fx.render.sprites[1].ts = store.tick_ts

	queue_insert(store, fx)
	U.y_animation_play(this, "start", nil, store.tick_ts, 1)
	U.animation_start(this, "idle", nil, store.tick_ts, true)

	while true do
		target = store.entities[m.target_id]

		if not target or target.health.dead or store.tick_ts - m.ts >= m.duration then
			U.y_animation_play(this, "end", nil, store.tick_ts, 1)
			queue_remove(store, this)

			return
		end

		coroutine.yield()
	end
end

function scripts.mod_gerald_skill_a.remove(this, store, script)
	local target = store.entities[this.modifier.target_id]

	if target then
		SU.armor_dec(target, this.armor_inc)
		SU.magic_armor_dec(target, this.armor_inc)
	end

	return true
end

scripts.mod_gerald_skill_b = {}

function scripts.mod_gerald_skill_b.insert(this, store, script)
	local target = store.entities[this.modifier.target_id]

	if not target or target.health.dead then
		return false
	end

	if band(this.modifier.vis_flags, target.vis.bans) ~= 0 or band(this.modifier.vis_bans, target.vis.flags) ~= 0 then
		log.paranoid("mod %s cannot be applied to entity %s:%s because of vis flags/bans", this.template_name, target.id, target.template_name)

		return false
	end

	SU.armor_inc(target, this.armor_inc)
	SU.magic_armor_inc(target, this.armor_inc)
	SU.spiked_armor_inc(target, this.spiked_armor)
	signal.emit("mod-applied", this, target)

	return true
end

function scripts.mod_gerald_skill_b.update(this, store, script)
	local m = this.modifier
	local target = store.entities[m.target_id]

	if not target then
		queue_remove(store, this)

		return
	end

	this.pos = target.pos

	U.y_animation_play(this, "start", nil, store.tick_ts, 1)
	U.animation_start(this, "loop", nil, store.tick_ts, true)

	while true do
		target = store.entities[m.target_id]

		if not target or target.health.dead or store.tick_ts - m.ts >= m.duration then
			this.tween.disabled = false
			this.tween.ts = store.tick_ts

			return
		end

		coroutine.yield()
	end
end

function scripts.mod_gerald_skill_b.remove(this, store, script)
	local target = store.entities[this.modifier.target_id]

	if target then
		SU.armor_dec(target, this.armor_inc)
		SU.magic_armor_dec(target, this.armor_inc)
		SU.spiked_armor_dec(target, this.spiked_armor)
	end

	return true
end

scripts.aura_gerald_talent_2_regeneration = {}

function scripts.aura_gerald_talent_2_regeneration.insert(this, store)
	local gerald = store.entities[this.aura.source_id]

	this.regen.health = gerald.health.hp_max * this.regen_ptg

	return true
end

scripts.hero_zefira = {}

function scripts.hero_zefira.level_up(this, store, initial)
	if not initial then
		S:queue(this.sound_events.level_up)
	end

	local hl = this.hero.level
	local ls = this.hero.level_stats

	this.health.hp_max = ls.hp_max[hl]
	this.regen.health = ls.regen_health[hl]
	this.health.armor = ls.armor[hl]
	this.melee.attacks[1].damage_min = ls.melee_damage_min[hl]
	this.melee.attacks[1].damage_max = ls.melee_damage_max[hl]

	local bt = E:get_template(this.ranged.attacks[1].bullet)

	bt.bullet.damage_min = ls.ranged_damage_min[hl]
	bt.bullet.damage_max = ls.ranged_damage_max[hl]
	this.health.hp = this.health.hp_max
	this.hero.melee_active_status = {}

	for index, attack in ipairs(this.melee.attacks) do
		this.hero.melee_active_status[index] = attack.disabled
	end
end

function scripts.hero_zefira.insert(this, store)
	this.hero.fn_level_up(this, store, true)

	this.melee.order = U.attack_order(this.melee.attacks)
	this.ranged.order = U.attack_order(this.ranged.attacks)
	this.timed_attacks.list[1].disabled = not this.hero.skills.ultimate.active

	return true
end

function scripts.hero_zefira.update(this, store)
	local h = this.health
	local brk, sta
	local old_tombstone_time = this.hero.tombstone_show_time
	local old_tombstone_respawn_animation = this.hero.tombstone_respawn_animation

	this.health_bar.hidden = false

	local asa = this.melee.attacks[1]

	asa.ts = store.tick_ts - asa.cooldown

	local ulti = this.timed_attacks.list[1]

	ulti.ts = store.tick_ts - ulti.cooldown

	local ult_start_cd = store.wave_group_number == 0
	local sa, sb, sc, su, st1, st2 = this.hero.skills.skill_a, this.hero.skills.skill_b, this.hero.skills.skill_c, this.hero.skills.ultimate, this.hero.skills.talent_1, this.hero.skills.talent_2

	sc.ts = store.tick_ts - sc.cooldown

	local t1_aura

	if not sb.disabled then
		local aura_check = E:create_entity(sb.aura_check)

		aura_check.aura.target_id = this.id
		aura_check.aura.source_id = this.id

		queue_insert(store, aura_check)
	end

	if not st1.disabled then
		t1_aura = E:create_entity(st1.aura)
		t1_aura.aura.target_id = this.id
		t1_aura.aura.source_id = this.id

		queue_insert(store, t1_aura)
	end

	if not st2.disabled then
		E:get_template(this.ranged.attacks[1].bullet).bullet.critical_chance = st2.crit_chance
		asa.critical_chance = st2.crit_chance
	end

	local function y_zefira_new_rally(store, this)
		local r = this.nav_rally

		if r.new then
			r.new = false

			U.unblock_target(store, this)

			if this.sound_events then
				S:queue(this.sound_events.change_rally_point)
			end

			if SU.hero_will_teleport(this, r.pos) then
				local tp = this.teleport
				local vis_bans = this.vis.bans

				this.vis.bans = F_ALL
				this.health.ignore_damage = true
				this.health_bar.hidden = true

				S:queue(tp.sound_in)

				if tp.fx_out then
					local fx = E:create_entity(tp.fx_out)

					fx.pos.x, fx.pos.y = this.pos.x, this.pos.y
					fx.render.sprites[1].ts = store.tick_ts

					if fx.tween then
						fx.tween.ts = store.tick_ts
					end

					queue_insert(store, fx)
				end

				local an, af = U.animation_name_facing_point(this, tp.animations[1], r.pos)

				U.animation_start(this, an, af, store.tick_ts, 1, nil)
				SU.y_hero_animation_wait(this)

				if tp.delay > 0 then
					U.sprites_hide(this, nil, nil, true)
					U.y_wait(store, tp.delay)
					U.sprites_show(this, nil, nil, true)
				end

				this.pos.x, this.pos.y = r.pos.x, r.pos.y

				U.set_destination(this, this.pos)

