				local nodes_between_spears = 2
				local spears = {}

				local function spawn_spear(pi, spi, ni, spear_id)
					local pos = P:node_pos(pi, spi, ni)

					pos.x = pos.x + math.random(-4, 4)
					pos.y = pos.y + math.random(-5, 5)

					local s = E:create_entity(a.spear_t)

					s.pos = V.vclone(pos)
					s.render.sprites[1].flip_x = this.render.sprites[1].flip_x

