end

scripts.bolt_KR6 = {}

function scripts.bolt_KR6.insert(this, store, script)
	if scripts.bolt.insert(this, store, script) then
		U.animation_start(this, "idle", nil, store.tick_ts, true)

		return true
	else
		return false
	end
end

function scripts.bolt_KR6.update(this, store, script)
	local b = this.bullet
	local s = this.render.sprites[1]
	local mspeed = b.min_speed
	local target, ps
	local new_target = false
	local target_invalid = false

	if b.particles_name then
		ps = E:create_entity(b.particles_name)
		ps.particle_system.track_id = this.id

		queue_insert(store, ps)
	end

	if b.in_anim then
		U.y_animation_play(this, b.in_anim, nil, store.tick_ts, 1, 1)
	end

	::label_283_0::

	S:queue(this.sound_events.travel)

	s.z = Z_BULLETS
	s.sort_y_offset = nil

	U.animation_start(this, "idle", nil, store.tick_ts, s.loop)

	if ps then
		ps.particle_system.emit = true
	end

	while V.dist2(this.pos.x, this.pos.y, b.to.x, b.to.y) > mspeed * store.tick_length * mspeed * store.tick_length do
		coroutine.yield()

		if not target_invalid then
			target = store.entities[b.target_id]
		end

		if target and not new_target then
			local tpx, tpy = target.pos.x, target.pos.y

			if not b.ignore_hit_offset then
				tpx, tpy = tpx + target.unit.hit_offset.x, tpy + target.unit.hit_offset.y
			end

			local d = math.max(math.abs(tpx - b.to.x), math.abs(tpy - b.to.y))

			if d > b.max_track_distance or band(target.vis.bans, F_RANGED) ~= 0 then
				target_invalid = true
				target = nil
			end
		end

		if target and target.health and not target.health.dead then
			if b.ignore_hit_offset then
				b.to.x, b.to.y = target.pos.x, target.pos.y
			else
				b.to.x, b.to.y = target.pos.x + target.unit.hit_offset.x, target.pos.y + target.unit.hit_offset.y
			end

			new_target = false
		end

		mspeed = mspeed + FPS * math.ceil(mspeed * (1 / FPS) * b.acceleration_factor)
		mspeed = km.clamp(b.min_speed, b.max_speed, mspeed)
		b.speed.x, b.speed.y = V.mul(mspeed, V.normalize(b.to.x - this.pos.x, b.to.y - this.pos.y))
		this.pos.x, this.pos.y = this.pos.x + b.speed.x * store.tick_length, this.pos.y + b.speed.y * store.tick_length

		if not b.ignore_rotation then
			s.r = V.angleTo(b.to.x - this.pos.x, b.to.y - this.pos.y)
		end

		if ps then
			ps.particle_system.emit_direction = s.r
		end
	end

	while b.store and not b.target_id do
		coroutine.yield()

		if b.target_id then
			mspeed = b.min_speed
			new_target = true

			goto label_283_0
		end
	end

	this.pos.x, this.pos.y = b.to.x, b.to.y

	if target and not target.health.dead then
		local d = SU.create_bullet_damage(b, target.id, this.id)

		queue_damage(store, d)

		if b.mod or b.mods then
			local mods = b.mods and b.mods or {
				b.mod
			}

			for _, mod_name in pairs(mods) do
				local mod = E:create_entity(mod_name)

				mod.modifier.source_id = this.id
				mod.modifier.target_id = target.id
				mod.modifier.level = b.level
				mod.modifier.source_damage = d

				queue_insert(store, mod)
			end
		end
	end

	if b.hit_fx then
		local sfx = E:create_entity(b.hit_fx)

		sfx.pos.x, sfx.pos.y = b.to.x, b.to.y
		sfx.render.sprites[1].ts = store.tick_ts
		sfx.render.sprites[1].r = s.r

		queue_insert(store, sfx)
	end

	queue_remove(store, this)
end

scripts.aura_zefira_skill_b_check = {}

function scripts.aura_zefira_skill_b_check.update(this, store, script)
	local zefira = store.entities[this.aura.source_id]
	local skill_ts = store.tick_ts

	if this.aura.track_source and this.aura.source_id then
		this.pos = zefira.pos
	end

	while true do
		if store.tick_ts - skill_ts > this.cooldown and U.get_blocked(store, zefira) then
			local targets = U.find_enemies_in_range(store.entities, this.pos, 0, this.aura.radius, this.aura.vis_flags, this.aura.vis_bans, function(v, o)
				return (not this.aura.excluded_templates or not table.contains(this.aura.excluded_templates, v.template_name)) and (not this.aura.filter_source or this.aura.source_id ~= v.id)
			end)

			if targets and #targets >= this.min_targets then
				SU.hero_gain_xp_from_skill(zefira, zefira.hero.skills.skill_b)

				local aura = E:create_entity(this.aura_t)

				aura.aura.target_id = this.aura.target_id
				aura.aura.source_id = this.aura.source_id

				queue_insert(store, aura)

				skill_ts = store.tick_ts

				S:queue(this.sound_cast)
			end
		end

		coroutine.yield()
	end
end

scripts.aura_zefira_skill_b = {}

function scripts.aura_zefira_skill_b.insert(this, store, script)
	local zefira = store.entities[this.aura.source_id]

	SU.armor_inc(zefira, this.aura.armor_inc)
	SU.magic_armor_inc(zefira, this.aura.magic_armor_inc)

	this.aura.ts = store.tick_ts
	this.actual_duration = this.aura.duration

	return true
end

function scripts.aura_zefira_skill_b.update(this, store, script)
	local zefira = store.entities[this.aura.source_id]
	local last_hit_ts = 0

	if this.aura.track_source and this.aura.source_id then
		this.pos = zefira.pos
	end

	U.y_animation_play(this, "start", nil, store.tick_ts, 1)
	U.animation_start(this, "loop", nil, store.tick_ts, true)

	while true do
		while true do
			if store.tick_ts - this.aura.ts > this.actual_duration then
				goto label_287_0
			end

			if zefira and zefira.health and zefira.health.dead then
				goto label_287_0
			end

			if store.tick_ts - last_hit_ts >= this.aura.cycle_time then
				last_hit_ts = store.tick_ts

				local targets = U.find_enemies_in_range(store.entities, this.pos, 0, this.aura.radius, this.aura.vis_flags, this.aura.vis_bans, function(v, o)
					return (not this.aura.allowed_templates or table.contains(this.aura.allowed_templates, v.template_name)) and (not this.aura.excluded_templates or not table.contains(this.aura.excluded_templates, v.template_name)) and (not this.aura.excluded_entities or not table.contains(this.aura.excluded_entities, v.id))
				end)

				if targets then
					for _, target in pairs(targets) do
						local d = E:create_entity("damage")

						d.source_id = this.id
						d.target_id = target.id

						local dmin, dmax = this.aura.damage_min, this.aura.damage_max

						d.value = math.random(dmin, dmax)
						d.damage_type = this.aura.damage_type
						d.track_damage = this.aura.track_damage
						d.xp_dest_id = this.aura.xp_dest_id
						d.xp_gain_factor = this.aura.xp_gain_factor

						queue_damage(store, d)

						local fx = E:create_entity(this.aura.hit_fx)

						fx.render.sprites[1].ts = store.tick_ts
						fx.pos = V.vclone(target.pos)
						fx.pos.x, fx.pos.y = fx.pos.x + target.unit.hit_offset.x, fx.pos.y + target.unit.hit_offset.y

						queue_insert(store, fx)

						local mods = this.aura.mods or {
							this.aura.mod
						}

						for _, mod_name in pairs(mods) do
							local m = E:create_entity(mod_name)

							m.modifier.level = this.aura.level
							m.modifier.target_id = target.id
							m.modifier.source_id = this.id

							if this.aura.hide_source_fx and target.id == this.aura.source_id then
								m.render = nil
							end

							queue_insert(store, m)
						end
					end
				end
			end

			coroutine.yield()
		end

		coroutine.yield()
	end

	::label_287_0::

	U.y_animation_play(this, "end", nil, store.tick_ts, 1)
	queue_remove(store, this)
end

function scripts.aura_zefira_skill_b.remove(this, store, script)
	local zefira = store.entities[this.aura.source_id]

	SU.armor_dec(zefira, this.aura.armor_inc)
	SU.magic_armor_dec(zefira, this.aura.magic_armor_inc)

	return true
end

scripts.mod_zefira_skill_c_dmg_buff = {}

function scripts.mod_zefira_skill_c_dmg_buff.update(this, store, script)
	local m = this.modifier

	this.modifier.ts = store.tick_ts

	local target = store.entities[m.target_id]

	if not target or not target.pos then
		queue_remove(store, this)

		return
	end

	this.pos = target.pos

	U.y_animation_play(this, "in", nil, store.tick_ts, 1)
	U.animation_start(this, "loop", nil, store.tick_ts, true)

	while true do
		target = store.entities[m.target_id]

		if not target or target.health.dead or m.last_node and target.nav_path.ni > m.last_node then
			U.y_animation_play(this, "out", nil, store.tick_ts, 1)
			queue_remove(store, this)

			return
		end

		if m.duration >= 0 and store.tick_ts - m.ts > m.duration then
			U.animation_start(this, "out", nil, store.tick_ts, false)

			while not U.animation_finished(this) and store.tick_ts - m.ts > m.duration do
				coroutine.yield()
			end

			if store.tick_ts - m.ts > m.duration then
				queue_remove(store, this)

				return
			end

			U.y_animation_play(this, "in", nil, store.tick_ts, 1)
			U.animation_start(this, "loop", nil, store.tick_ts, true)
		end

		if this.render and target.unit then
			local s = this.render.sprites[1]
			local flip_sign = 1

			if target.render then
				flip_sign = target.render.sprites[1].flip_x and -1 or 1
			end

			if m.health_bar_offset and target.health_bar then
				local hb = target.health_bar.offset
				local hbo = m.health_bar_offset

				s.offset.x, s.offset.y = hb.x + hbo.x * flip_sign, hb.y + hbo.y
			elseif m.use_mod_offset and target.unit.mod_offset then
				s.offset.x, s.offset.y = target.unit.mod_offset.x * flip_sign, target.unit.mod_offset.y
			end
		end

		coroutine.yield()
	end
end

scripts.decal_zefira_ultimate_spear = {}

function scripts.decal_zefira_ultimate_spear.update(this, store, script)
	U.animation_start(this, "in", nil, store.tick_ts, false)

	local enemies = U.find_enemies_in_range(store.entities, this.pos, 0, this.damage_radius, this.vis_flags, this.vis_bans)

	if enemies and #enemies > 0 then
		for i = 1, #enemies do
			local d = E:create_entity("damage")

			d.damage_type = this.damage_type
			d.value = math.random(this.damage_min, this.damage_max)
			d.source_id = this.id
			d.target_id = enemies[i].id

			queue_damage(store, d)
		end
	end

	local decal = E:create_entity(this.decal_t)

	decal.pos = V.vclone(this.pos)
	decal.render.sprites[1].ts = store.tick_ts

	queue_insert(store, decal)
	U.y_animation_wait(this)
	U.animation_start(this, "loop", nil, store.tick_ts, true)
	U.y_wait(store, fts(30))
	U.y_animation_play(this, "out", nil, store.tick_ts)

	this.render.sprites[1].hidden = true

	queue_remove(store, this)
end

scripts.mod_zefira_talent = {}

function scripts.mod_zefira_talent.insert(this, store, script)
	local target = store.entities[this.modifier.target_id]

	if not target or target.health.dead or target.enemy and not target.enemy.can_accept_magic then
		return false
	end

	if band(this.modifier.vis_flags, target.vis.bans) ~= 0 or band(this.modifier.vis_bans, target.vis.flags) ~= 0 then
		log.paranoid("mod %s cannot be applied to entity %s:%s because of vis flags/bans", this.template_name, target.id, target.template_name)

		return false
	end

	if not target.health.raw_armor then
		target.health.raw_armor = target.health.armor
	end

	if not target.health.raw_magic_armor then
		target.health.raw_magic_armor = target.health.magic_armor
	end

	SU.armor_dec(target, target.health.raw_armor * this.armor_factor)
	SU.magic_armor_dec(target, target.health.raw_magic_armor * this.armor_factor)
	signal.emit("mod-applied", this, target)

	if target.unit.size == UNIT_SIZE_MEDIUM or target.unit.size == UNIT_SIZE_LARGE then
		this.render.sprites[1].prefix = "hero_zefira_talent_mod_bigDef"
		this.render.sprites[2].prefix = "hero_zefira_talent_decal_bigDef"
	end

	return true
end

function scripts.mod_zefira_talent.update(this, store, script)
	local buff = this.armor_buff
	local m = this.modifier
	local last_ts = store.tick_ts
	local target = store.entities[m.target_id]

	if not target then
		queue_remove(store, this)

		return
	end

	this.pos = target.pos

	while true do
		target = store.entities[m.target_id]

		if not target or target.health.dead or store.tick_ts - m.ts >= m.duration then
			queue_remove(store, this)

			return
		end

		if this.render and m.use_mod_offset and target.unit.mod_offset then
			this.render.sprites[1].offset.x, this.render.sprites[1].offset.y = target.unit.mod_offset.x, target.unit.mod_offset.y
		end

		coroutine.yield()
	end
end

function scripts.mod_zefira_talent.remove(this, store, script)
	local target = store.entities[this.modifier.target_id]

	if target then
		SU.armor_inc(target, target.health.raw_armor * this.armor_factor)
		SU.magic_armor_inc(target, target.health.raw_magic_armor * this.armor_factor)
	end

	return true
end

scripts.hero_stage_05_alleria = {}

function scripts.hero_stage_05_alleria.insert(this, store)
	this.melee.order = U.attack_order(this.melee.attacks)
	this.ranged.order = U.attack_order(this.ranged.attacks)

	return true
end

function scripts.hero_stage_05_alleria.update(this, store)
	local h = this.health
	local brk, sta
	local old_tombstone_time = this.hero.tombstone_show_time
	local old_tombstone_respawn_animation = this.hero.tombstone_respawn_animation

	this.health_bar.hidden = false

	local ma = this.timed_attacks.list[1]

	ma.ts = store.tick_ts - ma.cooldown

	local wa = this.timed_attacks.list[2]

	wa.ts = store.tick_ts - wa.cooldown

	if not this.ignore_in_animation then
		U.y_animation_play(this, "in", this.in_cinematic, store.tick_ts, 1)
	end

	U.animation_start(this, "idle", this.in_cinematic, store.tick_ts, true)

	while this.in_cinematic do
		coroutine.yield()
	end

	while true do
		if h.dead then
			if band(h.last_damage_types, bor(DAMAGE_EAT)) ~= 0 then
				this.hero.tombstone_show_time = nil
				this.hero.tombstone_respawn_animation = nil
			end

			SU.y_hero_death_and_respawn_kr5(store, this)

			this.hero.tombstone_show_time = old_tombstone_time
			this.hero.tombstone_respawn_animation = old_tombstone_respawn_animation
		end

		if this.unit.is_stunned then
			SU.soldier_idle(store, this)
		else
			while this.nav_rally.new do
				if SU.y_hero_new_rally(store, this) then
					goto label_296_0
				end
			end

			if store.tick_ts - ma.ts > ma.cooldown and this.soldier.target_id == nil then
				local enemies = U.find_enemies_in_range(store.entities, this.pos, ma.min_range, ma.max_range, ma.vis_flags, ma.vis_bans)

				if not enemies or #enemies < ma.min_targets then
					SU.delay_attack(store, ma, 1.5)
				else
					ma.ts = store.tick_ts

					local an, af = U.animation_name_facing_point(this, ma.animations[1], enemies[1].pos)

					U.y_animation_play(this, an, af, store.tick_ts, 1)

					local enemy_idx = 1

					for i = 1, ma.shots do
						S:queue(ma.sound)
						U.animation_start(this, ma.animations[2], nil, store.tick_ts, false)
						U.y_wait(store, ma.shoot_time)

						local target = enemies[enemy_idx]
						local bullet = E:create_entity(ma.bullet)

						bullet.pos = V.vclone(this.pos)

						if ma.bullet_start_offset then
							local offset = ma.bullet_start_offset

							bullet.pos.x, bullet.pos.y = bullet.pos.x + (this.render.sprites[1].flip_x and -1 or 1) * offset.x, bullet.pos.y + offset.y
						end

						bullet.bullet.from = V.vclone(bullet.pos)
						bullet.bullet.to = V.vclone(target.pos)

						if not ma.ignore_hit_offset then
							bullet.bullet.to.x = bullet.bullet.to.x + target.unit.hit_offset.x
							bullet.bullet.to.y = bullet.bullet.to.y + target.unit.hit_offset.y
						end

						bullet.bullet.target_id = target.id
						bullet.bullet.source_id = this.id

						if bullet.bullet.use_unit_damage_factor then
							bullet.bullet.damage_factor = this.unit.damage_factor
						end

						queue_insert(store, bullet)

						enemy_idx = enemy_idx + 1

						if enemy_idx > #enemies then
							enemy_idx = 1
						end

						U.y_animation_wait(this)
					end

					U.y_animation_play(this, ma.animations[3], nil, store.tick_ts, 1)
				end
			end

			if store.tick_ts - wa.ts > wa.cooldown and this.soldier.target_id == nil then
				local enemies = U.find_enemies_in_range(store.entities, this.pos, 0, wa.range_check, wa.vis_flags, wa.vis_bans)

				if not enemies or #enemies < wa.min_targets then
					-- block empty
				else
					wa.ts = store.tick_ts

					local an, af = U.animation_name_facing_point(this, wa.animation, enemies[1].pos)

					U.animation_start(this, an, af, store.tick_ts, 1)
					U.y_wait(store, wa.cast_time)

					local e = E:create_entity(wa.entity)

					e.pos.x = this.pos.x + wa.spawn_offset.x
					e.pos.y = this.pos.y + wa.spawn_offset.y
					e.nav_rally.center = e.pos
					e.nav_rally.pos = V.vclone(e.pos)

					local has_mod, mods = U.has_modifiers(store, this, "mod_stage_05_tree_buff")

					if has_mod then
						e.health.hp_max = e.health.hp_max * mods[1].cat_hp_buff
						e.health.hp = e.health.hp_max
						e.melee.attacks[1].damage_min = e.melee.attacks[1].damage_min * mods[1].cat_dmg_buff
						e.melee.attacks[1].damage_max = e.melee.attacks[1].damage_max * mods[1].cat_dmg_buff
					end

					queue_insert(store, e)
					S:queue(wa.sound)
					U.animation_start(e, "in", nil, store.tick_ts, false)
					U.y_animation_wait(this)
				end
			end

			brk, sta = y_hero_melee_block_and_attacks(store, this)

			if brk or sta ~= A_NO_TARGET then
				-- block empty
			elseif SU.soldier_go_back_step(store, this) then
				-- block empty
			else
				brk, sta = y_hero_ranged_attacks(store, this)

				if brk then
					-- block empty
				else
					SU.soldier_idle(store, this)
					SU.soldier_regen(store, this)
				end
			end
		end

		::label_296_0::

		coroutine.yield()
	end
end

scripts.hero_stage_18_denas = {}

local function denas_spawn_guard_squad(store, dg, spawn_pos, entity_name, walk_from, turn_y)
	local squad_id
	local out = {}

	for j = 1, 2 do
		local e = E:create_entity(entity_name or dg.entity)

		squad_id = squad_id or e.id
		e.reinforcement.squad_id = squad_id
		e.render.sprites[1].prefix = e.render.sprites[1].prefix .. j
		e.pos.x = j == 1 and spawn_pos.x + 10 or spawn_pos.x - 10
		e.pos.y = j == 1 and spawn_pos.y - 10 or spawn_pos.y + 10

		if j == 2 then
			e.info.random_name_format = "SOLDIER_REINFORCEMENTS_F_%i_NAME"
			e.info.random_name_count = 4
		end

		-- e.info.portrait = string.format("gui_bottom_info_image_soldiers_%04i", 6 + j)
		e.nav_rally.center = V.vclone(spawn_pos)

		if walk_from then
			e.nav_rally.pos = V.v(e.pos.x, e.pos.y)
			e.pos.x = walk_from.x + (j == 1 and 12 or -12)
			e.pos.y = walk_from.y + (j == 1 and -8 or 8)
			e.nav_grid.waypoints = turn_y and {
				V.v(e.pos.x, turn_y)
			} or {}
			e.nav_rally.new = true
			e.sound_events.change_rally_point = nil
		else
			e.nav_rally.pos = V.vclone(e.pos)
		end

		queue_insert(store, e)

		out[#out + 1] = e
	end

	return out
end

function scripts.hero_stage_18_denas.insert(this, store)
	this.melee.order = U.attack_order(this.melee.attacks)

	return true
end

local function denas_find_bomb_cluster(store, this, ba, predict_time)
	local enemies = U.find_enemies_in_range(store.entities, this.pos, 0, ba.max_range, ba.vis_flags, ba.vis_bans)

	if not enemies then
		return nil, 0
	end

	local pos = {}

	for i = 1, #enemies do
		local e = enemies[i]
		local p = e.pos

		if predict_time and e.motion and e.motion.speed then
			if e.motion.forced_waypoint then
				p = V.v(e.pos.x + predict_time * e.motion.speed.x, e.pos.y + predict_time * e.motion.speed.y)
			else
				local node_offset = P:predict_enemy_node_advance(e, predict_time)

				p = P:node_pos(e.nav_path.pi, e.nav_path.spi, e.nav_path.ni + node_offset)
			end
		end

		pos[i] = p
	end

	local vc = store.visible_coords
	local best, best_count = nil, 0

	for i = 1, #enemies do
		local epos = pos[i]

		if epos.x > vc.left + ba.edge_margin and epos.x < vc.right - ba.edge_margin and not U.is_inside_ellipse(epos, this.pos, ba.hero_margin) then
			local count = 0

			for j = 1, #enemies do
				if U.is_inside_ellipse(pos[j], epos, ba.cluster_radius) then
					count = count + 1
				end
			end

			if best_count < count then
				best, best_count = epos, count
			end
		end
	end

	return best, best_count
end

function scripts.hero_stage_18_denas.y_bombardement(store, this)
	local ba = this.timed_attacks.list[1]

	if store.tick_ts - ba.ts <= ba.cooldown then
		return false
	end

	local best, best_count = denas_find_bomb_cluster(store, this, ba, nil)

	if not best or best_count < ba.min_targets then
		SU.delay_attack(store, ba, 1.5)

		return false
	end

	local target_pos = V.vclone(best)
	local start_ts = store.tick_ts
	local flip = target_pos.x < this.pos.x

	U.animation_start(this, ba.animation, flip, store.tick_ts)

	while store.tick_ts - start_ts < ba.cast_time do
		if this.nav_rally.new or this.health.dead or this.unit.is_stunned then
			SU.delay_attack(store, ba, 1.5)

			return true
		end

		coroutine.yield()
	end

	ba.ts = store.tick_ts

	local flight_time = E:get_template(ba.bullet).bullet.flight_time
	local pbest, pcount = denas_find_bomb_cluster(store, this, ba, flight_time)

	if pbest and pcount >= ba.min_targets then
		target_pos = V.vclone(pbest)
	end

	local vc = store.visible_coords
	local mid_x = (vc.left + vc.right) / 2
	local offset_border = 50
	local from_x = mid_x > target_pos.x and vc.left + offset_border or vc.right - offset_border
	local from_y = vc.bottom - 60

	for i = 1, ba.shots do
		local e = E:create_entity(ba.bullet)
		local p

		if i == 1 then
			p = V.v(target_pos.x, target_pos.y)
		else
			local spread = math.random(ba.min_spread, ba.max_spread)

			p = V.v(target_pos.x + math.random(-spread, spread), target_pos.y + math.random(-spread, spread))
		end

		e.pos.x, e.pos.y = from_x, from_y
		e.bullet.from = V.vclone(e.pos)
		e.bullet.to = p
		e.bullet.source_id = this.id
		e.bullet.damage_factor = 1

		queue_insert(store, e)

		local ts = store.tick_ts

		while store.tick_ts - ts < ba.burst_interval do
			if this.nav_rally.new or this.health.dead or this.unit.is_stunned then
				return true
			end

			coroutine.yield()
		end
	end

	while not U.animation_finished(this) do
		if this.nav_rally.new or this.health.dead or this.unit.is_stunned then
			return true
		end

		coroutine.yield()
	end

	return true
end

function scripts.hero_stage_18_denas.y_denas_guards(store, this)
	local dg = this.timed_attacks.list[2]

	if store.tick_ts - dg.ts <= dg.cooldown then
		return false
	end

	local info = U.find_enemies_in_paths(store.entities, this.pos, dg.range_nodes_min, dg.range_nodes_max, dg.max_path_dist, 0, bor(F_FLYING, F_WATER, F_CLIFF), nil)

	if not info then
		SU.delay_attack(store, dg, 1.5)

		return false
	end

	local target = info[1].enemy
	local spawn_pos = P:node_pos(target.nav_path.pi, 1, target.nav_path.ni + dg.ahead_nodes)
	local start_ts = store.tick_ts

	U.animation_start(this, dg.animation, spawn_pos.x < this.pos.x, store.tick_ts)

	while store.tick_ts - start_ts < dg.cast_time do
		if this.nav_rally.new or this.health.dead or this.unit.is_stunned then
			SU.delay_attack(store, dg, 1.5)

			return true
		end

		coroutine.yield()
	end

	dg.ts = store.tick_ts

	denas_spawn_guard_squad(store, dg, spawn_pos)

	while not U.animation_finished(this) do
		if this.nav_rally.new or this.health.dead or this.unit.is_stunned then
			return true
		end

		coroutine.yield()
	end

	return true
end

function scripts.hero_stage_18_denas.y_cinematic_entrance(store, this)
	local dest = this.cinematic_entrance_to
	local entry = V.v(this.pos.x, this.pos.y)
	local speed = this.motion.max_speed
	local dg = this.timed_attacks.list[2]

	local function dist_left()
		return V.dist(this.pos.x, this.pos.y, dest.x, dest.y)
	end

	local taunted = false
	local gallop_ts
	local gallop_y = store.visible_coords.bottom - speed * (this.cinematic_gallop_lead or 0)

	local function y_walk_while(cond)
		while cond() do
			U.walk(this, store.tick_length)

			if not gallop_ts and this.pos.y >= gallop_y then
				gallop_ts = store.tick_ts

				S:queue(this.sound_events.cinematic_gallop)
				S:queue(this.sound_events.cinematic_neigh, {
					delay = this.cinematic_neigh_delay
				})
			end

			if not taunted and this.pos.y >= store.visible_coords.bottom then
				taunted = true

				S:queue(this.sound_events.cinematic_entrance)
			end

			coroutine.yield()
		end
	end

	U.set_destination(this, dest)
	U.animation_start(this, "cinematic_walk_up", nil, store.tick_ts, true)
	y_walk_while(function()
		return dist_left() > speed * fts(22)
	end)
	U.animation_start(this, "cinematic_drift_in", nil, store.tick_ts, false)
	y_walk_while(function()
		return not U.animation_finished(this)
	end)
	U.animation_start(this, "cinematic_drift_loop", nil, store.tick_ts, true)

	while not U.walk(this, store.tick_length) do
		coroutine.yield()
	end

	this.pos.x, this.pos.y = dest.x, dest.y
	this.nav_rally.center = V.vclone(dest)
	this.nav_rally.pos = V.vclone(dest)
	this.nav_rally.new = false

	U.animation_start(this, "cinematic_drift_out", nil, store.tick_ts, false)
	U.y_animation_wait(this)
	U.animation_start(this, "summon_royal_guard", nil, store.tick_ts, false)
	U.y_wait(store, dg.cast_time)
	signal.emit("show-balloon_tutorial-pos", "S18_TRANS_01", false, V.v(this.pos.x, this.pos.y + 80))

	local turn_y = dest.y + (entry.y > dest.y and 50 or -50)
	local guards = {}

	for _, sp in ipairs(this.initial_squads_pos or {}) do
		local from = V.v(entry.x + sp.entry_offset.x, entry.y + sp.entry_offset.y)

		for _, g in ipairs(denas_spawn_guard_squad(store, dg, sp.pos, dg.initial_entity, from, turn_y)) do
			guards[#guards + 1] = g
		end

		U.y_wait(store, 0.25)
	end

	U.y_animation_wait(this)
	U.animation_start(this, "idle", nil, store.tick_ts, true)

	local deadline = store.tick_ts + 12

	local function arrived(g)
		if not store.entities[g.id] then
			return true
		end

		if g.health and g.health.dead then
			return true
		end

		return not g.nav_rally.new and V.dist(g.pos.x, g.pos.y, g.nav_rally.pos.x, g.nav_rally.pos.y) <= 8
	end

	while deadline > store.tick_ts do
		local all = true

		for _, g in ipairs(guards) do
			if not arrived(g) then
				all = false

				break
			end
		end

		if all then
			break
		end

		coroutine.yield()
	end

	this.cinematic_entrance_done = true

	U.animation_start(this, "idle", nil, store.tick_ts, true)

	while not this.cinematic_look_start do
		coroutine.yield()
	end

	U.y_animation_play(this, "look_around_in", nil, store.tick_ts, 1)
	U.animation_start(this, "look_around_loop", nil, store.tick_ts, true)

	while not this.cinematic_look_end do
		coroutine.yield()
	end

	U.y_animation_play(this, "look_around_out", nil, store.tick_ts, 1)
	U.animation_start(this, "idle", nil, store.tick_ts, true)

	this.cinematic_look_done = true
end

function scripts.hero_stage_18_denas.update(this, store)
	local h = this.health
	local brk, sta

	this.health_bar.hidden = false

	local ba = this.timed_attacks.list[1]

	SU.delay_attack(store, ba, 2)

	local dg = this.timed_attacks.list[2]

	SU.delay_attack(store, dg, 4)

	if not this.ignore_in_animation then
		U.y_animation_play(this, "revive", this.in_cinematic, store.tick_ts, 1)
	end

	U.animation_start(this, "idle", this.in_cinematic, store.tick_ts, true)

	if not this.cinematic_entrance_to then
		for _, sp in ipairs(this.initial_squads_pos or {}) do
			denas_spawn_guard_squad(store, dg, sp.pos, dg.initial_entity)
		end
	end

	if this.cinematic_entrance_to then
		scripts.hero_stage_18_denas.y_cinematic_entrance(store, this)
	end

	while this.in_cinematic do
		coroutine.yield()
	end

	while true do
		if h.dead then
			SU.y_hero_death_and_respawn_kr5(store, this)
		end

		if this.unit.is_stunned then
			SU.soldier_idle(store, this)
		else
			while this.nav_rally.new do
				local rsb = this.rally_speed_boost
				local walk_angles = this.render.sprites[1].angles.walk
				local boosted = false

				if V.dist(this.pos.x, this.pos.y, this.nav_rally.pos.x, this.nav_rally.pos.y) > rsb.min_dist then
					this.motion.max_speed = this.motion.max_speed * rsb.speed_factor
					walk_angles[1] = "walk"
					boosted = true
				end

				local out = SU.y_hero_new_rally(store, this)

				if boosted then
					this.motion.max_speed = this.motion.max_speed / rsb.speed_factor
				end

				walk_angles[1] = "walk_slow"

				if out then
					goto label_308_0
				end
			end

			do
				local target = SU.soldier_pick_melee_target(store, this)

				if not target or this.soldier.target_id == target.id and this.motion.arrived then
					if scripts.hero_stage_18_denas.y_bombardement(store, this) then
						goto label_308_0
					end

					if scripts.hero_stage_18_denas.y_denas_guards(store, this) then
						goto label_308_0
					end
				end
			end

			brk, sta = y_hero_melee_block_and_attacks(store, this)

			if brk or sta ~= A_NO_TARGET then
				-- block empty
			elseif SU.soldier_go_back_step(store, this) then
				-- block empty
			else
				SU.soldier_idle(store, this)
				SU.soldier_regen(store, this)
			end
		end

		::label_308_0::

		coroutine.yield()
	end
end

scripts.hero_bolin = {}

function scripts.hero_bolin.level_up(this, store, initial)
	if not initial then
		S:queue(this.sound_events.level_up)
	end

	local hl = this.hero.level
	local ls = this.hero.level_stats

	this.health.hp_max = ls.hp_max[hl]
	this.regen.health = ls.regen_health[hl]
	this.health.armor = ls.armor[hl]
	this.melee.attacks[1].damage_min = ls.melee_damage_min[hl]
	this.melee.attacks[1].damage_max = ls.melee_damage_max[hl]

	local bt = E:get_template(this.ranged.attacks[1].bullet)

	bt.bullet.damage_min = ls.ranged_damage_min[hl]
	bt.bullet.damage_max = ls.ranged_damage_max[hl]

	local bsc = E:get_template(this.hero.skills.skill_c.bullet)

	bsc.bullet.damage_min = bt.bullet.damage_min
	bsc.bullet.damage_max = bt.bullet.damage_max

	local bu = E:get_template(this.hero.skills.ultimate.bullet)

	bu.bullet.damage_min = bt.bullet.damage_min
	bu.bullet.damage_max = bt.bullet.damage_max

	local busc = E:get_template(this.hero.skills.ultimate.bullet_skill_c)

	busc.bullet.damage_min = bt.bullet.damage_min
	busc.bullet.damage_max = bt.bullet.damage_max
end

function scripts.hero_bolin.insert(this, store)
	this.hero.fn_level_up(this, store, true)

	local st = this.hero.skills.talent

	this.melee.order = U.attack_order(this.melee.attacks)
	this.ranged.order = U.attack_order(this.ranged.attacks)
	this.timed_attacks.list[3].disabled = not this.hero.skills.ultimate.active

	return true
end

function scripts.hero_bolin.update(this, store)
	local h = this.health
	local brk, sta
	local old_tombstone_time = this.hero.tombstone_show_time
	local old_tombstone_respawn_animation = this.hero.tombstone_respawn_animation
	local area_damage_active, shot_count = false, 0

	this.health_bar.hidden = false

	local asa = this.melee.attacks[1]
	local aa = this.ranged.attacks[1]
	local saa = this.timed_attacks.list[1]
	local sba = this.timed_attacks.list[2]
	local sua = this.timed_attacks.list[3]
	local ult_start_cd = store.wave_group_number == 0

	asa.ts = store.tick_ts - asa.cooldown

	local sa, sb, sc, su, st1, st2 = this.hero.skills.skill_a, this.hero.skills.skill_b, this.hero.skills.skill_c, this.hero.skills.ultimate, this.hero.skills.talent_1, this.hero.skills.talent_2

	this.max_mines_near = false

	if not sc.disabled then
		aa.bullet = sc.bullet
	end

	if not st2.disabled then
		area_damage_active = true
	end

	local function shoot_bullet(target, t, af, ai)
		local bullet = E:create_entity(t)

		bullet.pos = V.vclone(this.pos)

		if sua.bullet_start_offset then
			local offset = sua.bullet_start_offset[ai]

			bullet.pos.x, bullet.pos.y = bullet.pos.x + (af and -1 or 1) * offset.x, bullet.pos.y + offset.y
		end

		bullet.bullet.from = V.vclone(bullet.pos)
		bullet.bullet.to = V.vclone(target.pos)

		if not sua.ignore_hit_offset then
			bullet.bullet.to.x = bullet.bullet.to.x + target.unit.hit_offset.x
			bullet.bullet.to.y = bullet.bullet.to.y + target.unit.hit_offset.y
		end

		bullet.bullet.target_id = target.id
		bullet.bullet.source_id = this.id
		bullet.bullet.xp_dest_id = this.id
		bullet.bullet.level = sua.level

		if bullet.bullet.use_unit_damage_factor then
			bullet.bullet.damage_factor = this.unit.damage_factor
		end

		if shot_count >= st2.shot_count then
			shot_count = 0
			bullet.bullet.hit_payload = st2.aura
		end

		queue_insert(store, bullet)
	end

	local function calculate_mortar_pos(first_enemy, e_pos, bullet_count, node_gap, pred_time)
		local a = saa
		local first_enemy_pos = P:predict_enemy_pos(first_enemy, pred_time)
		local nearest_middle_node_to_fe = P:nearest_nodes(first_enemy_pos.x, first_enemy_pos.y, {
			first_enemy.nav_path.pi
		}, {
			1
		})[1]
		local fepi, fespi, feni = unpack(nearest_middle_node_to_fe)
		local ret = {}
		local nni = feni

		if nni - node_gap * 2 < 0 then
			nni = node_gap * 2 + 1
		end

		local pi

		for i = 1, bullet_count do
			local dir = i == 1 and -1 or 1

			pi, nni = P:find_valid_node(fepi, nni, dir)

			local node_pos = P:node_pos(fepi, 1, nni)

			if point_in_valid_path(node_pos.x, node_pos.y, {
				fepi
			}) then
				table.insert(ret, P:node_pos(fepi, 1, nni))
			end

			nni = nni - node_gap
		end

		return ret
	end

	local function calculate_mine_pos(near_mines)
		local a = sba
		local valid_positions = P:get_all_valid_pos(this.pos.x, this.pos.y, a.min_range, a.max_range, TERRAIN_LAND, function(x, y)
			for _, mine in ipairs(near_mines) do
				if V.dist(mine.pos.x, mine.pos.y, x, y) <= a.min_dist_between_mines then
					return false
				end
			end

			return true
		end, nil, {
			1,
			2,
			3
		})

		return valid_positions[math.random(1, #valid_positions)]
	end

	local function spawn_casings(this, attack)
		if not attack.casings_to_spawn or not attack.casing_spawn_time then
			log.error("Wrong attack configurations")

			return
		end

		local c = E:create_entity(this.casing_controller)

		c.time_to_spawn = attack.casing_spawn_time
		c.amount_to_spawn = attack.casings_to_spawn
		c.animation_names = attack.animations_for_casings
		c.source_id = this.id
		c.sprite_id = 1
		c.spawn_origin = V.v(this.pos.x, this.pos.y)

		queue_insert(store, c)
	end

	local function should_skip_ultimate(targets)
		if targets and #targets >= sua.min_targets then
			return false
		end

		for k, v in pairs(targets) do
			if v.health.hp >= sua.min_hp then
				return false
			end
		end

		return true
	end

	while true do
		local cc, ddc, target, attack

		if ult_start_cd and store.wave_group_number > 0 then
			ult_start_cd = false
			sua.ts = store.tick_ts
		end

		if h.dead then
			ddc = E:create_entity(this.death_dmg_controller)
			ddc.source_id = this.id

			queue_insert(store, ddc)

			if band(h.last_damage_types, bor(DAMAGE_EAT)) ~= 0 then
				this.hero.tombstone_show_time = nil
				this.hero.tombstone_respawn_animation = nil
			end

			SU.y_hero_death_and_respawn_kr5(store, this)

			this.hero.tombstone_show_time = old_tombstone_time
			this.hero.tombstone_respawn_animation = old_tombstone_respawn_animation
		end

		if this.unit.is_stunned then
			SU.soldier_idle(store, this)
		else
			while this.nav_rally.new do
				if SU.y_hero_new_rally(store, this) then
					goto label_311_2
				end

				this.max_mines_near = false
			end

			if SU.hero_level_up(store, this) then
				U.y_animation_play(this, "levelup", nil, store.tick_ts, 1)
			end

			brk, sta = y_hero_melee_block_and_attacks(store, this)

			if brk or sta ~= A_NO_TARGET then
				-- block empty
			elseif SU.soldier_go_back_step(store, this) then
				-- block empty
			else
				if not sua.disabled and store.tick_ts - sua.ts > sua.cooldown and this.soldier.target_id == nil then
					local an, af, ultimate_aura
					local ultimate_bullet_t = sc.disabled and su.bullet or su.bullet_skill_c
					local trigger_target, targets = U.find_foremost_enemy(store.entities, this.pos, 0, sua.max_range, 0, sua.vis_flags, sua.vis_bans)
					local skip = not trigger_target or should_skip_ultimate(targets)
					local sts
					local se = false

					if skip then
						SU.delay_attack(store, sua, fts(10))
					else
						ultimate_aura = E:create_entity(su.aura_decal)
						ultimate_aura.pos.x, ultimate_aura.pos.y = this.pos.x, this.pos.y
						ultimate_aura.target_id = this.id

						queue_insert(store, ultimate_aura)

						af = not (trigger_target.pos.x > this.pos.x)

						U.animation_start(this, sua.animations[1], af, store.tick_ts, 1, 1)

						sts = store.tick_ts
						sua.ts = store.tick_ts

						while not U.animation_finished(this, 1) do
							if this.unit.is_stunned or this.health.dead or this.nav_rally and this.nav_rally.new then
								SU.delay_attack(store, sua, fts(10))

								goto label_311_0
							end

							if store.tick_ts - sts > sua.sound_time and not se then
								se = true

								S:queue(sua.sound_taunt)
								S:queue(sua.sound)
							end

							coroutine.yield()
						end

						an, af = U.animation_name_facing_point(this, sua.animation, trigger_target.pos, 1)
						an = sua.animations[2] .. an

						for i = 1, sua.shot_count do
							local j = i

							if i ~= 1 and i ~= sua.shot_count then
								j = 2
							elseif i == sua.shot_count then
								j = 3
							end

							local target = U.find_foremost_enemy(store.entities, this.pos, 0, sua.max_range, 0, sua.vis_flags, sua.vis_bans)

							if not target then
								sua.ts = store.tick_ts

								goto label_311_0
							end

							local an, af, ai = U.animation_name_facing_point(this, sua.animation, target.pos, 1)

							an = "powershoot" .. an .. j

							U.animation_start(this, an, af, store.tick_ts, 1, 1)

							if i == 1 then
								U.y_wait(store, sua.shoot_time)
							end

							shoot_bullet(target, ultimate_bullet_t, af, ai)

							if area_damage_active then
								shot_count = shot_count + 1
							end

							if i == sua.shot_count then
								spawn_casings(this, sua)
							end

							while not U.animation_finished(this, 1) do
								if this.unit.is_stunned or this.health.dead or this.nav_rally and this.nav_rally.new then
									sua.ts = store.tick_ts

									goto label_311_0
								end

								coroutine.yield()
							end
						end

						SU.hero_gain_xp_from_skill(this, su)

						sua.ts = store.tick_ts
					end

					::label_311_0::

					queue_remove(store, ultimate_aura)

					goto label_311_2
				end

				if not saa.disabled and store.tick_ts - saa.ts > saa.cooldown then
					local bt = E:get_template(saa.bullet)
					local pred_time = 2 * (math.sqrt(2 * bt.bullet.fixed_height * bt.bullet.g * -1) / bt.bullet.g * -1)
					local first, targets, pred_pos = U.find_foremost_enemy(store.entities, this.pos, saa.min_range, saa.max_range, pred_time, saa.vis_flags, saa.vis_bans)

					if not first or #targets < saa.min_targets then
						SU.delay_attack(store, saa, fts(10))
					else
						local destinations = calculate_mortar_pos(first, this.pos, saa.bullet_count, saa.mortar_gap, pred_time)

						if not destinations or #destinations == 0 then
							SU.delay_attack(store, saa, fts(10))
						else
							local start_ts = store.tick_ts
							local af

							af = not (first.pos.x > this.pos.x)

							U.animation_start(this, saa.animation, af, store.tick_ts, 1, 1)
							U.y_wait(store, saa.shoot_time)
							S:queue(saa.sound)
							S:queue(saa.sound_hit, {
								delay = pred_time
							})

							for i = 1, saa.bullet_count do
								local shooting_right = not this.render.sprites[1].flip_x
								local boffset = saa.bullet_start_offset
								local b = E:create_entity(saa.bullet)

								b.bullet.damage_min = saa.damage_min
								b.bullet.damage_max = saa.damage_max

								if b.bullet.fixed_height then
									b.bullet.flight_time = pred_time + 0.18 * (i - 1)
								end

								b.pos.x = this.pos.x + boffset.x * (shooting_right and 1 or -1)
								b.pos.y = this.pos.y + boffset.y
								b.bullet.from = V.vclone(b.pos)
								b.bullet.to = destinations[i] or destinations[1]
								b.bullet.source_id = this.id

								queue_insert(store, b)
							end

							while not U.animation_finished(this, 1) and not this.nav_rally.new do
								coroutine.yield()
							end

							SU.hero_gain_xp_from_skill(this, sa)

							saa.ts = store.tick_ts

							goto label_311_2
						end
					end
				end

				if not aa.disabled and store.tick_ts - aa.ts > aa.cooldown and this.soldier.target_id == nil then
					local an, af, ai, bullet, target_pos
					local trigger_target, targets, pred_pos = U.find_foremost_enemy(store.entities, this.pos, 0, aa.max_range, 0, aa.vis_flags, aa.vis_bans)
					local skip = not trigger_target
					local sts
					local se = false

					if skip then
						SU.delay_attack(store, aa, fts(10))
					else
						target_pos = V.vclone(pred_pos)

						spawn_casings(this, aa)

						an, af, ai = U.animation_name_facing_point(this, aa.animation, trigger_target.pos, 1)

						U.animation_start(this, an, af, store.tick_ts, 1, 1)

						sts = store.tick_ts

						while store.tick_ts - sts < aa.shoot_time do
							if this.unit.is_stunned or this.health.dead or this.nav_rally and this.nav_rally.new then
								SU.delay_attack(store, aa, fts(10))

								goto label_311_1
							end

							coroutine.yield()
						end

						if not trigger_target or trigger_target.health.dead or not store.entities[trigger_target.id] then
							trigger_target, targets, pred_pos = U.find_foremost_enemy(store.entities, this.pos, 0, aa.max_range, 0, aa.vis_flags, aa.vis_bans)

							if not trigger_target then
								SU.delay_attack(store, aa, fts(10))

								goto label_311_1
							end

							target_pos = V.vclone(pred_pos)
						end

						bullet = E:create_entity(aa.bullet)
						bullet.pos = V.vclone(this.pos)

						if aa.bullet_start_offset then
							local offset = aa.bullet_start_offset[ai]

							bullet.pos.x, bullet.pos.y = bullet.pos.x + (af and -1 or 1) * offset.x, bullet.pos.y + offset.y
						end

						bullet.bullet.from = V.vclone(bullet.pos)
						bullet.bullet.to = v(target_pos.x + trigger_target.unit.hit_offset.x, target_pos.y + trigger_target.unit.hit_offset.y)
						bullet.bullet.target_id = trigger_target and trigger_target.id or nil
						bullet.bullet.source_id = this.id
						bullet.bullet.xp_dest_id = this.id

						if aa.xp_gain_factor then
							bullet.bullet.xp_gain_factor = aa.xp_gain_factor
						end

						bullet.bullet.level = aa.level

						if bullet.bullet.use_unit_damage_factor then
							bullet.bullet.damage_factor = this.unit.damage_factor
						end

						if shot_count >= st2.shot_count then
							shot_count = 0
							bullet.bullet.hit_payload = st2.aura
						end

						bullet.damage_cap = sc.damage_cap[sc.level]

						queue_insert(store, bullet)

						if area_damage_active then
							shot_count = shot_count + 1
						end

						aa.ts = store.tick_ts

						while not U.animation_finished(this, 1) do
							if this.unit.is_stunned or this.health.dead or this.nav_rally and this.nav_rally.new then
								SU.delay_attack(store, aa, fts(10))

								goto label_311_1
							end

							coroutine.yield()
						end

						goto label_311_2
					end
				end

				::label_311_1::

				if not sba.disabled and store.tick_ts - sba.ts > sba.cooldown and this.soldier.target_id == nil and not this.max_mines_near and store.wave_group_number > 0 then
					target = U.find_foremost_enemy(store.entities, this.pos, 0, sba.max_range, 0, sba.vis_flags, sba.vis_bans)

					if target then
						SU.delay_attack(store, sba, fts(10))
					else
						local near_mines = table.filter(store.entities, function(k, v)
							return v.template_name == "aura_bolin_skill_b_trigger" and V.dist2(v.pos.x, v.pos.y, this.pos.x, this.pos.y) <= sba.max_range * sba.max_range
						end)

						if #near_mines >= sba.max_mines then
							this.max_mines_near = true

							SU.delay_attack(store, sba, fts(10))
						else
							local mine_pos = calculate_mine_pos(near_mines)

							if not mine_pos then
								this.max_mines_near = true

								SU.delay_attack(store, sba, fts(10))
							else
								local all_mines = find_all_t(store, "aura_bolin_skill_b_trigger")

								if #all_mines >= sba.max_mines then
									local far_mines = table.filter(all_mines, function(k, v)
										return V.dist2(v.pos.x, v.pos.y, this.pos.x, this.pos.y) > sba.max_range * sba.max_range
									end)

									table.sort(far_mines, function(e1, e2)
										return V.dist2(e1.pos.x, e1.pos.y, this.pos.x, this.pos.y) > V.dist2(e2.pos.x, e2.pos.y, this.pos.x, this.pos.y)
									end)

									far_mines[1].trigger = true
								end

								local start_ts = store.tick_ts

								U.y_animation_play(this, sba.animations[1], nil, store.tick_ts, 1, nil)
								U.animation_start(this, sba.animations[2], nil, store.tick_ts, 1, nil)

								if SU.y_hero_wait(store, this, sba.throw_time) then
									goto label_311_2
								end

								local b = E:create_entity(sba.bullet)

								b.bullet.from = V.v(this.pos.x + sba.bullet_start_offset.x, this.pos.y + sba.bullet_start_offset.y)
								b.bullet.to = V.v(mine_pos.x, mine_pos.y)
								b.bullet.source_id = this.id
								b.pos = V.vclone(b.bullet.from)

								queue_insert(store, b)
								SU.y_hero_animation_wait(this)
								U.y_animation_play(this, sba.animations[3], nil, store.tick_ts, 1, nil)

								sba.ts = start_ts

								SU.hero_gain_xp_from_skill(this, sb)

								goto label_311_2
							end
						end
					end
				end

				SU.soldier_idle(store, this)
				SU.soldier_regen(store, this)
			end
		end

		::label_311_2::

		coroutine.yield()
	end
end

scripts.bullet_bolin = {}

function scripts.bullet_bolin.update(this, store, script)
	local b = this.bullet
	local source = store.entities[this.bullet.source_id]
	local target = store.entities[this.bullet.target_id]

	local function create_fx(hfx)
		local sfx = E:create_entity(hfx)

		sfx.render.sprites[1].ts = store.tick_ts

		local is_air = target and band(target.vis.flags, F_FLYING) ~= 0

		if b.hit_fx_ignore_hit_offset and target and not is_air then
			sfx.pos.x, sfx.pos.y = target.pos.x, target.pos.y
		else
			local hoffset = V.vclone(target.unit.hit_offset)

			sfx.pos.x, sfx.pos.y = target.pos.x + hoffset.x, target.pos.y + hoffset.y
		end

		if sfx.allow_rotation and source then
			local vx, vy = V.sub(target.pos.x, target.pos.y, source.pos.x, source.pos.y)
			local r = km.unroll(V.angleTo(vx, vy))

			sfx.render.sprites[1].r = r
		end

		queue_insert(store, sfx)
	end

	local st_1 = source.hero.skills.talent_1

	if not st_1.disabled then
		b.reduce_armor = st_1.reduce_armor
	end

	if target and not target.health.dead then
		local d = SU.create_bullet_damage(b, target.id, this.id)

		queue_damage(store, d)

		local hfx

		if b.hit_fxs and #b.hit_fxs > 0 then
			for i = 1, #b.hit_fxs do
				create_fx(b.hit_fxs[i])
			end
		elseif b.hit_fx then
			create_fx(b.hit_fx)
		end

		if b.hit_payload then
			local hp

			if type(b.hit_payload) == "string" then
				hp = E:create_entity(b.hit_payload)
			else
				hp = b.hit_payload
			end

			if hp.aura then
				hp.aura.level = this.bullet.level
				hp.aura.source_id = this.id
				hp.pos.x, hp.pos.y = target.pos.x, target.pos.y
			else
				hp.pos.x, hp.pos.y = target.pos.x, target.pos.y
			end

			if hp.damage_factor then
				hp.damage_factor = b.damage_factor
			end

			queue_insert(store, hp)
		end
	end

	queue_remove(store, this)
end

scripts.controller_bolin_death_explosion = {}

function scripts.controller_bolin_death_explosion.update(this, store, script)
	U.y_wait(store, this.time_to_spawn)

	local source = store.entities[this.source_id]
	local exp = E:create_entity(this.aura)

	exp.pos.x, exp.pos.y = source.pos.x, source.pos.y

	queue_insert(store, exp)
end

scripts.controller_bolin_spawn_casing = {}

function scripts.controller_bolin_spawn_casing.update(this, store, script)
	local source = store.entities[this.source_id]
	local source_spr = source.render.sprites[this.sprite_id]
	local max = 4

	U.y_wait(store, this.time_to_spawn, function(s, t)
		return not table.contains(this.animation_names, source_spr.name)
	end)

	if source and table.contains(this.animation_names, source_spr.name) then
		if this.amount_to_spawn > 1 then
			S:queue(this.sound)
		end

		for i = 1, math.min(this.amount_to_spawn, max) do
			local csing = E:create_entity(this.casing)
			local random_y = 3 * (i - 2) + U.frandom(-3, 3)

			csing.pos.x, csing.pos.y = this.spawn_origin.x + this.spawn_offset.x, this.spawn_origin.y + this.spawn_offset.y + random_y
			csing.y_origin = this.spawn_origin.y + random_y

			if not source_spr.flip_x then
				csing.initial_direction_v.x = csing.initial_direction_v.x * -1
			end

			queue_insert(store, csing)
		end
	end

	queue_remove(store, this)
end

scripts.fx_bolin_bullet_casing = {}

function scripts.fx_bolin_bullet_casing.update(this, store, script)
	local ps

	if this.particles_name then
		ps = E:create_entity(this.particles_name)
		ps.particle_system.track_id = this.id

		queue_insert(store, ps)
	end

	local nvx, nvy = V.normalize(this.initial_direction_v.x + U.frandom(-0.02, 0.02), this.initial_direction_v.y + U.frandom(-0.06, 0.06))
	local conserved_speed = this.initial_speed * U.frandom(0.9, 1.1)
	local cvx, cvy = V.mul(conserved_speed, nvx, nvy)
	local dt = fts(1)
	local last_ts = store.tick_ts
	local spr = this.render.sprites[1]
	local bounces = 0

	while not V.eq(cvx, cvy, 0, 0) do
		this.pos.x, this.pos.y = this.pos.x + cvx * dt, this.pos.y + cvy * dt
		spr.r = spr.r + -km.sign(nvx) * 20 * dt

		if this.pos.y <= this.y_origin then
			if bounces == this.bounces then
				cvx, cvy = 0, 0
				spr.r = 0
				spr.z = Z_DECALS

				U.y_animation_play(this, this.rest_anim, nil, store.tick_ts)

				break
			end

			bounces = bounces + 1
			this.pos.y = this.y_origin
			conserved_speed = conserved_speed * this.elasticity
			cvy = conserved_speed * nvy
			cvx = conserved_speed * nvx

			if bounces == this.bounces and ps and ps.particle_system.emit then
				ps.particle_system.emit = false
			end
		end

		cvy = cvy + this.g * dt
		dt = store.tick_ts - last_ts
		last_ts = store.tick_ts

		coroutine.yield()
	end

	U.y_wait(store, 2)

	this.tween.ts = store.tick_ts
	this.tween.disabled = false
end

scripts.bullet_bolin_skills_parabola = {}

function scripts.bullet_bolin_skills_parabola.insert(this, store)
	local b = this.bullet

	b.speed = SU.initial_parabola_speed(b.from, b.to, b.flight_time, b.g)
	b.ts = store.tick_ts
	b.last_pos = V.vclone(b.from)

	if b.rotation_speed then
		this.render.sprites[1].r = 0
		b.rotation_speed = b.rotation_speed * (b.to.x > b.from.x and -1 or 1)
	end

	this.render.sprites[1].hidden = false

	return true
end

function scripts.bullet_bolin_skills_parabola.update(this, store, script)
	local ps
	local b = this.bullet

	this.render.sprites[1].hidden = false

	if b.particles_name then
		ps = E:create_entity(b.particles_name)
		ps.pos.x, ps.pos.y = this.pos.x, this.pos.y
		ps.particle_system.track_id = this.id

		queue_insert(store, ps)
	end

	while store.tick_ts - b.ts + store.tick_length < b.flight_time do
		coroutine.yield()

		b.last_pos.x, b.last_pos.y = this.pos.x, this.pos.y
		this.pos.x, this.pos.y = SU.position_in_parabola(store.tick_ts - b.ts, b.from, b.speed, b.g)

		if b.rotation_speed then
			this.render.sprites[1].r = this.render.sprites[1].r + b.rotation_speed * store.tick_length
		end

		if this.change_z_midflight and store.tick_ts - b.ts > this.change_z_time then
			this.render.sprites[1].z = this.change_z_midflight
		end
	end

	if b.payload then
		local hp

		if type(b.payload) == "string" then
			hp = E:create_entity(b.payload)
		else
			hp = b.payload
		end

		hp.pos.x, hp.pos.y = b.to.x, b.to.y
		hp.source_id = b.source_id

		if hp.render then
			hp.render.sprites[1].ts = store.tick_ts
		end

		if hp.aura then
			hp.aura.level = this.bullet.level
		end

		queue_insert(store, hp)
	end

	if b.hit_fx then
		local hfx = E:create_entity(b.hit_fx)

		hfx.pos.x, hfx.pos.y = b.to.x, b.to.y

		queue_insert(store, hfx)
	end

	if b.hit_decal then
		local d = E:create_entity(b.hit_decal)

		d.pos.x, d.pos.y = this.pos.x, this.pos.y
		d.render.sprites[1].ts = store.tick_ts

		queue_insert(store, d)
	end

	if ps then
		ps.particle_system.emit = false
	end

	if b.damage_min and b.damage_max then
		local enemies = U.find_enemies_in_range(store.entities, b.to, 0, b.damage_radius, b.damage_flags, b.damage_bans)

		if enemies then
			for _, enemy in pairs(enemies) do
				local d = E:create_entity("damage")

				d.damage_type = b.damage_type
				d.value = math.random(b.damage_min, b.damage_max)
				d.source_id = this.id
				d.target_id = enemy.id

				if b.xp_gain_factor and b.xp_dest_id then
					d.xp_gain_factor = b.xp_gain_factor
					d.xp_dest_id = b.source_id
				end

				queue_damage(store, d)
			end
		end
	end

	if this.exit_animation then
		this.render.sprites[1].r = 0

		if this.exit_z then
			this.render.sprites[1].z = this.exit_z
		end

		U.y_animation_play(this, this.exit_animation, nil, store.tick_ts, 1, 1)
	end

	queue_remove(store, this)
end

scripts.aura_bolin_skill_b_trigger = {}

function scripts.aura_bolin_skill_b_trigger.update(this, store, script)
	local function do_damage()
		local enemies = U.find_targets_in_range(store.entities, this.pos, 0, this.aura.radius, this.aura.vis_flags, this.aura.vis_bans)

		if enemies then
			for _, enemy in pairs(enemies) do
				local d = E:create_entity("damage")

				d.damage_type = this.damage_type

				if this.reduce_armor then
					d.reduce_armor = this.reduce_armor
				end

				if not this.ignore_dist_factor then
					local dist_factor = U.dist_factor_inside_ellipse(enemy.pos, this.pos, this.aura.radius)

					d.value = math.floor(this.damage_max - (this.damage_max - this.damage_min) * dist_factor)
				else
					d.value = math.random(this.damage_min, this.damage_max)
				end

				if this.damage_factor then
					d.value = math.ceil(d.value * this.damage_factor)
				end

				d.source_id = this.id
				d.target_id = enemy.id

				queue_damage(store, d)

				if this.aura.mod or this.aura.mods then
					local mods = this.aura.mods or {
						this.aura.mod
					}

					for _, mod_name in pairs(mods) do
						local m = E:create_entity(mod_name)

						m.modifier.target_id = enemy.id
						m.modifier.level = this.aura.level

						queue_insert(store, m)
					end
				end
			end
		end
	end

	U.y_animation_wait(this, 1)
	U.animation_start(this, "idle", nil, store.tick_ts, true)

	local targets

	repeat
		targets = U.find_enemies_in_range(store.entities, this.pos, 0, this.trigger_radius, this.aura.vis_flags, this.aura.vis_bans_trigger)

		coroutine.yield()
	until targets and #targets > 0 or this.trigger

	U.animation_start(this, "explode", nil, store.tick_ts, false)

	this.render.sprites[1].z = Z_OBJECTS

	S:queue(this.sound_hit)
	do_damage()

	local hd = E:create_entity(this.hit_decal)

	hd.pos.x, hd.pos.y = this.pos.x, this.pos.y

	queue_insert(store, hd)

	store.entities[this.source_id].max_mines_near = false

	U.y_animation_wait(this, nil)
	queue_remove(store, this)
end

scripts.bullet_bolin_skill_c = {}

function scripts.bullet_bolin_skill_c.update(this, store, script)
	local b = this.bullet
	local t = store.entities[b.target_id]

	if not t then
		return false
	end

	local s = store.entities[b.source_id]

	if t.health then
		if band(t.vis.flags, bor(F_BOSS, F_MINIBOSS)) ~= 0 then
			b.damage_min = b.damage_min + t.health.hp_max * this.boss_hp_pctg
			b.damage_max = b.damage_max + t.health.hp_max * this.boss_hp_pctg
		else
			b.damage_min = b.damage_min + t.health.hp_max * this.hp_pctg
			b.damage_max = b.damage_max + t.health.hp_max * this.hp_pctg
		end

		if this.damage_cap then
			b.damage_min = math.max(b.damage_min, this.damage_cap)
			b.damage_max = math.max(b.damage_max, this.damage_cap)
		end
	end

	local st_1 = s.hero.skills.talent_1

	if not st_1.disabled then
		b.reduce_armor = st_1.reduce_armor
	end

	scripts.ray5_simple.update(this, store, script)
end

scripts.bullet_bolin_ultimate = {}

function scripts.bullet_bolin_ultimate.update(this, store, script)
	local b = this.bullet
	local s = store.entities[b.source_id]
	local st_1 = s.hero.skills.talent_1

	if not st_1.disabled then
		b.reduce_armor = st_1.reduce_armor
	end

	scripts.ray5_simple.update(this, store, script)
end

scripts.hero_malik = {}

function scripts.hero_malik.level_up(this, store, initial)
	if not initial then
		S:queue(this.sound_events.level_up)
	end

	local hl = this.hero.level
	local ls = this.hero.level_stats

	this.health.hp_max = ls.hp_max[hl]
	this.regen.health = ls.regen_health[hl]
	this.health.armor = ls.armor[hl]

	local m = find_all_t(store, "mod_malik_upgrade_b")[1]

	if m and m.active then
		this.melee.attacks[1].damage_min = ls.melee_damage_min[hl] * m.modifier.dmg_factor
		this.melee.attacks[1].damage_max = ls.melee_damage_max[hl] * m.modifier.dmg_factor
	else
		this.melee.attacks[1].damage_min = ls.melee_damage_min[hl]
		this.melee.attacks[1].damage_max = ls.melee_damage_max[hl]
	end

	this.health.hp = this.health.hp_max
	this.hero.melee_active_status = {}

	for index, attack in ipairs(this.melee.attacks) do
		this.hero.melee_active_status[index] = attack.disabled
	end
end

function scripts.hero_malik.insert(this, store)
	this.hero.fn_level_up(this, store, true)

	this.melee.order = U.attack_order(this.melee.attacks)
	this.timed_attacks.list[4].disabled = not this.hero.skills.ultimate.active

	if this.damage_based_on_health_upgrade_active then
		local m = E:create_entity(this.upgrade_b_mod_t)

		m.modifier.target_id = this.id

		queue_insert(store, m)
	end

	return true
end

function scripts.hero_malik.update(this, store)
	local h = this.health
	local brk, sta, blocker
	local old_tombstone_time = this.hero.tombstone_show_time
	local old_tombstone_respawn_animation = this.hero.tombstone_respawn_animation

	this.health_bar.hidden = false

	local sa, sb, sc, su, st1, st2 = this.hero.skills.skill_a, this.hero.skills.skill_b, this.hero.skills.skill_c, this.hero.skills.ultimate, this.hero.skills.talent_1, this.hero.skills.talent_2
	local saa = this.timed_attacks.list[1]

	saa.ts = store.tick_ts - saa.cooldown

	local sba = this.timed_attacks.list[2]

	sba.ts = store.tick_ts - sba.cooldown

	local sca = this.timed_attacks.list[3]

	sca.ts = store.tick_ts - sca.cooldown

	local ua = this.timed_attacks.list[4]

	ua.ts = store.tick_ts - ua.cooldown

	local ult_start_cd = store.wave_group_number == 0

	if not st1.disabled then
		this.melee.attacks[1].type = "area"
		this.melee.attacks[1].hit_decal = st1.decal
		this.melee.attacks[1].damage_flags = bor(this.melee.attacks[1].damage_flags, F_AREA)
	end

	if not st2.disabled then
		local buff = E:create_entity(st2.aura)

		buff.aura.source_id = this.id

		queue_insert(store, buff)
	end

	local function y_malik_new_rally_ultimate(store, anim)
		local r = this.nav_rally

		if r.new then
			r.new = false

			U.unblock_target(store, this)

			if this.sound_events then
				S:queue(this.sound_events.change_rally_point)
			end

			local out = SU.y_hero_walk_waypoints(store, this, anim)

			return out
		end
	end

	while true do
		if ult_start_cd and store.wave_group_number > 0 then
			ult_start_cd = false
			ua.ts = store.tick_ts
		end

		if h.dead then
			if this.chance_to_revive and math.random() < this.chance_to_revive then
				h.dead = false
				this.health_bar.hidden = false
				this.ui.can_click = true
				h.hp = h.hp_max * this.hp_ptg_on_revive
				this.force_respawn = nil
				h.ignore_damage = false

				U.y_animation_play(this, "lvlup", nil, store.tick_ts, 1)
			else
				if band(h.last_damage_types, bor(DAMAGE_EAT)) ~= 0 then
					this.hero.tombstone_show_time = nil
					this.hero.tombstone_respawn_animation = nil
				end

				SU.y_hero_death_and_respawn_kr5(store, this)

				this.hero.tombstone_show_time = old_tombstone_time
				this.hero.tombstone_respawn_animation = old_tombstone_respawn_animation
			end
		end

		if this.unit.is_stunned then
			SU.soldier_idle(store, this)
		else
			while this.nav_rally.new do
				if SU.y_hero_new_rally(store, this) then
					goto label_335_0
				end
			end

			if SU.hero_level_up(store, this) then
				U.y_animation_play(this, "lvlup", nil, store.tick_ts, 1)
			end

			if not ua.disabled and store.tick_ts - ua.ts > ua.cooldown and this.motion.arrived then
				local a = ua
				local target = store.entities[this.soldier.target_id]
				local enemies = U.find_enemies_in_range(store.entities, this.pos, 0, a.damage_radius, a.vis_flags, a.vis_bans)

				if not enemies or #enemies < a.min_targets then
					SU.delay_attack(store, ua, fts(10))
				else
					S:queue(a.sound_cast)
					S:queue(a.sound_loop, {
						delay = fts(24)
					})
					S:queue(a.sound_taunt)
					U.unblock_target(store, this)
					U.animation_start(this, a.animation_start, nil, store.tick_ts, false, 1)

					if SU.y_hero_wait(store, this, a.cast_time) then
						S:stop(a.sound_loop)

						goto label_335_0
					end

					local ts = store.tick_ts
					local vis_bans = this.vis.bans
					local prev_immune = this.health.immune_to

					this.vis.bans = F_ALL
					this.health.immune_to = this.nav_rally.immune_to

					local sm = E:create_entity(a.speed_mod)

					sm.modifier.target_id = this.id
					sm.modifier.source_id = this.id

					queue_insert(store, sm)

					local au = E:create_entity(a.aura_t)

					au.aura.source_id = this.id
					au.pos = V.vclone(this.pos)

					queue_insert(store, au)

					local ps = E:create_entity(a.ps_t)

					ps.pos = V.vclone(this.pos)
					ps.particle_system.track_id = this.id

					queue_insert(store, ps)
					U.animation_start(this, a.animation_loop, nil, store.tick_ts, true)

					while store.tick_ts - ts < a.duration do
						if this.nav_rally.new then
							y_malik_new_rally_ultimate(store, a.animation_loop)
						end

						coroutine.yield()
					end

					queue_remove(store, ps)
					queue_remove(store, au)
					queue_remove(store, sm)
					S:stop(a.sound_loop)
					S:queue(a.sound_end)
					SU.hero_gain_xp_from_skill(this, su)
					U.y_animation_play(this, a.animation_end, nil, store.tick_ts, false)

					this.vis.bans = vis_bans
					this.health.immune_to = prev_immune
					a.ts = store.tick_ts

					SU.y_hero_animation_wait(this)
					U.animation_start(this, "idle", nil, store.tick_ts, true)

					goto label_335_0
				end
			end

			blocker = store.entities[this.soldier.target_id]

			if not sca.disabled and store.tick_ts - sca.ts > sca.cooldown and this.soldier.target_id ~= nil and this.motion.arrived and blocker and blocker.health and not blocker.health.dead and blocker.health.hp_max <= sca.hp_threshold and blocker.health.hp >= sca.current_hp_threshold and band(blocker.vis.flags, sca.vis_bans) == 0 and band(blocker.vis.bans, sca.vis_flags) == 0 then
				local a = sca
				local start_ts = store.tick_ts

				U.animation_start(this, a.animation, nil, store.tick_ts, false)
				S:queue(a.sound)

				if SU.y_hero_wait(store, this, a.cast_time) then
					goto label_335_0
				end

				if not blocker or not U.is_blocked_valid(store, this) then
					this.soldier.target_id = nil
				else
					a.ts = start_ts

					SU.hero_gain_xp_from_skill(this, sc)

					local mod = E:create_entity(a.mod)

					mod.modifier.source_id = this.id
					mod.modifier.target_id = blocker.id
					mod.enemy_move_offset = a.enemy_move_offset

					queue_insert(store, mod)
					SU.y_hero_animation_wait(this)
					U.animation_start(this, "idle", nil, store.tick_ts, true)

					this.soldier.target_id = nil

					goto label_335_0
				end
			end

			if not saa.disabled and store.tick_ts - saa.ts > saa.cooldown and this.soldier.target_id ~= nil and this.motion.arrived then
				local blocker = store.entities[this.soldier.target_id]
				local a = saa
				local start_ts = store.tick_ts

				U.animation_start(this, a.animation, nil, store.tick_ts, false)
				S:queue(a.sound)

				if SU.y_hero_wait(store, this, a.cast_time) then
					goto label_335_0
				end

				if not blocker then
					this.soldier.target_id = nil
				else
					a.ts = start_ts

					SU.hero_gain_xp_from_skill(this, sa)

					local mod = E:create_entity(a.mod)

					mod.modifier.duration = a.duration
					mod.modifier.source_id = this.id
					mod.modifier.target_id = this.id
					mod.shield_max_damage = a.shield_base + blocker.health.hp_max * a.hp_increase_ptg

					queue_insert(store, mod)
					SU.y_hero_animation_wait(this)
					U.animation_start(this, "idle", nil, store.tick_ts, true)

					goto label_335_0
				end
			end

			if not sba.disabled and store.tick_ts - sba.ts > sba.cooldown and this.soldier.target_id ~= nil and this.motion.arrived then
				local a = sba
				local start_ts = store.tick_ts
				local enemies = U.find_enemies_in_range(store.entities, this.pos, 0, a.damage_radius, a.vis_flags, a.vis_bans)

				if not enemies or #enemies < a.min_targets then
					SU.delay_attack(store, sba, fts(10))
				else
					U.animation_start(this, a.animation, nil, store.tick_ts, false)
					S:queue(a.sound, {
						delay = fts(11)
					})
					S:queue(a.sound_taunt)

					a.ts = start_ts

					if SU.y_hero_wait(store, this, a.cast_time) then
						goto label_335_0
					end

					S:queue(a.sound_hit)
					SU.hero_gain_xp_from_skill(this, sb)

					local hit_pos = V.vclone(this.pos)

					if a.hit_offset then
						hit_pos.x = hit_pos.x + (this.render.sprites[1].flip_x and -1 or 1) * a.hit_offset.x
						hit_pos.y = hit_pos.y + a.hit_offset.y
					end

					local enemies = U.find_enemies_in_range(store.entities, hit_pos, 0, a.damage_radius, a.vis_flags, a.vis_bans)

					if enemies and #enemies > 0 then
						for k, v in pairs(enemies) do
							local d = E:create_entity("damage")

							d.source_id = this.id
							d.target_id = v.id
							d.damage_type = a.damage_type
							d.value = math.ceil(this.unit.damage_factor * math.random(a.damage_min, a.damage_max))

							queue_damage(store, d)

							local mod = E:create_entity(a.mod_stun)

							mod.modifier.source_id = this.id
							mod.modifier.target_id = v.id

							queue_insert(store, mod)
						end
					end

					local decal = E:create_entity(a.hit_decal)

					decal.pos = V.vclone(hit_pos)

					for i = 1, #decal.render.sprites do
						decal.render.sprites[i].ts = store.tick_ts
						decal.render.sprites[i].flip_x = this.render.sprites[i].flip_x
					end

					queue_insert(store, decal)
					SU.y_hero_animation_wait(this)
					U.animation_start(this, "idle", nil, store.tick_ts, true)

					goto label_335_0
				end
			end

			brk, sta = y_hero_melee_block_and_attacks(store, this)

			if this.health.dead then
				-- block empty
			elseif brk or sta ~= A_NO_TARGET then
				-- block empty
			elseif SU.soldier_go_back_step(store, this) then
				-- block empty
			else
				SU.soldier_idle(store, this)
				SU.soldier_regen(store, this)
			end
		end

		::label_335_0::

		coroutine.yield()
	end
end

scripts.fx_malik_hit = {}

function scripts.fx_malik_hit.insert(this, store)
	U.animation_start(this, this.insert_anim_name, nil, store.tick_ts)

	return true
end

scripts.mod_malik_skill_a = {}

function scripts.mod_malik_skill_a.insert(this, store)
	local m = this.modifier
	local target = store.entities[this.modifier.target_id]

	if band(this.modifier.vis_flags, target.vis.bans) ~= 0 or band(this.modifier.vis_bans, target.vis.flags) ~= 0 then
		log.paranoid("mod %s cannot be applied to entity %s:%s because of vis flags/bans", this.template_name, target.id, target.template_name)

		return false
	end

	if not target or not target.health or target.health.dead then
		return false
	end

	m.ts = store.tick_ts
	target.health._on_damage = target.health.on_damage
	target.health.on_damage = scripts.mod_malik_skill_a.on_damage
	this._hit_sources = {}
	this._blood_color = target.unit.blood_color
	target.unit.blood_color = BLOOD_NONE
	target._shield_mod = this
	this.health.hp = this.shield_max_damage
	this.health.hp_max = this.shield_max_damage

	return true
end

function scripts.mod_malik_skill_a.remove(this, store)
	local m = this.modifier
	local target = store.entities[m.target_id]

	if target then
		target.health.on_damage = target.health._on_damage
		target._shield_mod = nil
		target.unit.blood_color = this._blood_color
	end

	return true
end

function scripts.mod_malik_skill_a.update(this, store)
	local m = this.modifier

	this.modifier.ts = store.tick_ts

	local target = store.entities[m.target_id]

	if not target or not target.pos then
		queue_remove(store, this)

		return
	end

	this.pos = target.pos

	U.y_animation_play(this, this.animation_start, nil, store.tick_ts, 1)

	while true do
		target = store.entities[m.target_id]

		if not target or target.health.dead or m.duration >= 0 and store.tick_ts - m.ts > m.duration or m.last_node and target.nav_path.ni > m.last_node then
			this.tween.disabled = false
			this.tween.ts = store.tick_ts

			U.y_wait(store, this.tween.props[1].keys[2][1])
			queue_remove(store, this)

			return
		end

		if this.render and target.unit then
			local s = this.render.sprites[1]
			local flip_sign = 1

			if target.render then
				flip_sign = target.render.sprites[1].flip_x and -1 or 1
			end

			if m.health_bar_offset and target.health_bar then
				local hb = target.health_bar.offset
				local hbo = m.health_bar_offset

				s.offset.x, s.offset.y = hb.x + hbo.x * flip_sign, hb.y + hbo.y
			elseif m.use_mod_offset and target.unit.mod_offset then
				s.offset.x, s.offset.y = target.unit.mod_offset.x * flip_sign, target.unit.mod_offset.y
			end
		end

		U.animation_start(this, this.animation_loop, nil, store.tick_ts, true)
		coroutine.yield()
	end
end

function scripts.mod_malik_skill_a.on_damage(this, store, damage)
	local mod = this._shield_mod

	if not mod then
		log.error("mod_malik_skill_a.on_damage for enemy %s has no mod pointer", this.id)

		return true
	end

	if mod.shield_broken then
		return true
	end

	if U.flag_has(damage.damage_type, bor(DAMAGE_INSTAKILL, DAMAGE_DISINTEGRATE, DAMAGE_EAT, DAMAGE_IGNORE_SHIELD)) then
		mod.shield_broken = true

		queue_remove(store, mod)

		return true
	else
		mod.damage_taken = mod.damage_taken + damage.value
	end

	mod.health.hp = mod.shield_max_damage - mod.damage_taken

	if mod.damage_taken >= mod.shield_max_damage then
		mod.shield_broken = true

		queue_remove(store, mod)

		if mod.damage_taken - mod.shield_max_damage > 0 then
			damage.value = mod.damage_taken - mod.shield_max_damage

			return true
		end
	end

	return false
end

scripts.mod_malik_skill_c_instakill = {}

function scripts.mod_malik_skill_c_instakill.insert(this, store)
	local target = store.entities[this.modifier.target_id]
	local m = this.modifier

	if not target then
		return false
	end

	if band(target.vis.flags, this.modifier.vis_bans) ~= 0 then
		return false
	end

	if band(target.vis.bans, this.modifier.vis_flags) ~= 0 then
		return false
	end

	this._entity_frame_names = {}

	for _, es in pairs(target.render.sprites) do
		if es.animated then
			table.insert(this._entity_frame_names, es.frame_name)
		else
			table.insert(this._entity_frame_names, es.name)
		end
	end

	SU.stun_inc(target)

	this._pushed_bans = U.push_bans(target.vis, F_ALL)
	target.ui.can_click = false
	target.ui.can_select = false
	target.health_bar.hidden = true
	target.unit.show_blood_pool = false

	return true
end

function scripts.mod_malik_skill_c_instakill.update(this, store, script)
	local start_ts, target_hidden
	local m = this.modifier
	local target = store.entities[this.modifier.target_id]

	if not target then
		queue_remove(store, this)

		return
	end

	this.pos = target.pos

	local is_on_right = store.entities[this.modifier.source_id].pos.x < this.pos.x
	local is_exo = false

	for k, v in pairs(target.render.sprites) do
		if v.exo then
			is_exo = true

			break
		end
	end

	local es = E:create_entity(this.clone_decal)

	es.pos.y = es.pos.y + this.enemy_move_offset.y

	if is_on_right then
		es.pos.x = es.pos.x + this.enemy_move_offset.x
	else
		es.pos.x = es.pos.x - this.enemy_move_offset.x
	end

	start_ts = store.tick_ts
	es.tween.ts = store.tick_ts

	local offset_to_center = target.unit.hit_offset.y / 2

	es.render.sprites[1].offset.y = offset_to_center * -1
	es.tween.props[1].keys[2][1] = this.modifier.duration - fts(6)
	es.tween.props[1].keys[3][1] = this.modifier.duration
	es.render.sprites[1].z = Z_BULLETS

	if not is_exo then
		this._decal_clone = es
		es.pos.x, es.pos.y = target.pos.x, target.pos.y
		es.render = table.deepclone(target.render)

		for i, s in ipairs(es.render.sprites) do
			s.shader = es.shader
			s.shader_args = es.shader_args
			s.animated = false
			s.prefix = nil
			s.name = this._entity_frame_names[i]
		end

		queue_insert(store, es)
		coroutine.yield()
		U.sprites_hide(target, nil, nil, true)
	end

	while store.tick_ts - m.ts < m.duration and target and not target.health.dead do
		if is_on_right then
			es.pos.x = es.pos.x + this.fly_speed.x
			es.render.sprites[1].r = es.render.sprites[1].r - this.rotation_speed
		else
			es.pos.x = es.pos.x - this.fly_speed.x
			es.render.sprites[1].r = es.render.sprites[1].r + this.rotation_speed
		end

		es.pos.y = es.pos.y + this.fly_speed.y

		coroutine.yield()
	end

	if target.sound_events then
		target.sound_events.death = nil
	end

	local d = E:create_entity("damage")

	d.damage_type = bor(DAMAGE_INSTAKILL, DAMAGE_FX_NOT_EXPLODE, DAMAGE_NO_SPAWNS, DAMAGE_IGNORE_SHIELD)
	d.source_id = this.id
	d.target_id = target.id

	queue_damage(store, d)

	if not is_exo then
		queue_remove(store, es)
	end

	this._not_interrupted = true

	queue_remove(store, this)
end

scripts.mod_malik_upgrade_b = {}

function scripts.mod_malik_upgrade_b.update(this, store)
	local target = store.entities[this.modifier.target_id]

	local function apply_mod()
		this.active = true
		target.melee.attacks[1].damage_min = target.melee.attacks[1].damage_min * this.modifier.dmg_factor
		target.melee.attacks[1].damage_max = target.melee.attacks[1].damage_max * this.modifier.dmg_factor
	end

	local function remove_mod()
		this.active = false
		target.melee.attacks[1].damage_min = target.melee.attacks[1].damage_min / this.modifier.dmg_factor
		target.melee.attacks[1].damage_max = target.melee.attacks[1].damage_max / this.modifier.dmg_factor
	end

	while true do
		if not this.active and target.health and target.health.hp > target.health.hp_max * this.hp_threshold then
			apply_mod()
		end

		if this.active and target.health and target.health.hp <= target.health.hp_max * this.hp_threshold then
			remove_mod()
		end

		coroutine.yield()
	end
end

scripts.aura_malik_talent_2_buff = {}

function scripts.aura_malik_talent_2_buff.update(this, store, script)
	local target = store.entities[this.aura.source_id]
	local buff_active = false

	local function apply_buff()
		buff_active = true
		target.melee.attacks[1].damage_min = target.melee.attacks[1].damage_min * this.dmg_factor
		target.melee.attacks[1].damage_max = target.melee.attacks[1].damage_max * this.dmg_factor

		for i = 1, #target.hero.level_stats.melee_damage_min do
			target.hero.level_stats.melee_damage_min[i] = target.hero.level_stats.melee_damage_min[i] * this.dmg_factor
			target.hero.level_stats.melee_damage_max[i] = target.hero.level_stats.melee_damage_max[i] * this.dmg_factor
		end
	end

	local function remove_buff()
		buff_active = false
		target.melee.attacks[1].damage_min = target.melee.attacks[1].damage_min / this.dmg_factor
		target.melee.attacks[1].damage_max = target.melee.attacks[1].damage_max / this.dmg_factor

		for i = 1, #target.hero.level_stats.melee_damage_min do
			target.hero.level_stats.melee_damage_min[i] = target.hero.level_stats.melee_damage_min[i] / this.dmg_factor
			target.hero.level_stats.melee_damage_max[i] = target.hero.level_stats.melee_damage_max[i] / this.dmg_factor
		end
	end

	while true do
		local targets = U.find_targets_in_range(store.entities, target.pos, 0, this.aura.radius, this.aura.vis_flags, this.aura.vis_bans, function(v, o)
			return v.id ~= this.aura.source_id
		end)

		if not buff_active and (not targets or #targets == 0) then
			apply_buff()
		end

		if buff_active and targets and #targets > 0 then
			remove_buff()
		end

		coroutine.yield()
	end
end

scripts.hero_ashbite = {}

function scripts.hero_ashbite.level_up(this, store, initial)
	local hl = this.hero.level
	local ls = this.hero.level_stats

	this.health.hp_max = ls.hp_max[hl]
	this.regen.health = ls.regen_health[hl]
	this.health.armor = ls.armor[hl]

	local b = E:get_template(this.ranged.attacks[1].bullet)

	b.bullet.damage_max = ls.ranged_damage_max[hl]
	b.bullet.damage_min = ls.ranged_damage_min[hl]
	this.health.hp = this.health.hp_max
end

function scripts.hero_ashbite.insert(this, store)
	this.hero.fn_level_up(this, store, true)

	this.ranged.order = U.attack_order(this.ranged.attacks)
	this.timed_attacks.list[4].disabled = not this.hero.skills.ultimate.active

	return true
end

function scripts.hero_ashbite.remove(this, store)
	signal.remove("entity-killed", this.enemy_killed_fn)

	return true
end

function scripts.hero_ashbite.update(this, store)
	local brk, sta, old_vis_flags, old_vis_bans
	local shots_with_mod = 0
	local feeding_time = false
	local feeding_time_mod
	local feeding_time_start_ts = 0
	local shadow_sprite = this.render.sprites[2]
	local old_tombstone_time = this.hero.tombstone_show_time
	local old_tombstone_respawn_animation = this.hero.tombstone_respawn_animation
	local sa, sb, sc, su, st1, st2 = this.hero.skills.skill_a, this.hero.skills.skill_b, this.hero.skills.skill_c, this.hero.skills.ultimate, this.hero.skills.talent_1, this.hero.skills.talent_2
	local aa = this.ranged.attacks[1]

	aa.ts = store.tick_ts - aa.cooldown

	local saa = this.timed_attacks.list[1]

	saa.ts = store.tick_ts - saa.cooldown

	local sba = this.timed_attacks.list[2]

	sba.ts = store.tick_ts - sba.cooldown

	local sca = this.timed_attacks.list[3]

	sca.ts = store.tick_ts - sca.cooldown

	local ua = this.timed_attacks.list[4]

	ua.ts = store.tick_ts - ua.cooldown

	local ult_start_cd = store.wave_group_number == 0

	if not st1.disabled then
		local bt = E:get_template(this.ranged.attacks[1].bullet)

		bt.bullet.mod = st1.mod_t
	end

	if not st2.disabled then
		local skill_a_aura_t = E:get_template(this.timed_attacks.list[1].aura_t)

		skill_a_aura_t.aura.mod = st2.mod

		local skill_b_bullet_t = E:get_template(this.timed_attacks.list[2].bullet_t)
		local skill_b_bullet_aura_t = E:get_template(skill_b_bullet_t.bullet.hit_decal)

		E:get_template(skill_b_bullet_aura_t.aura.mod).dps.armor_sunder = st2.armor_sunder
	end

	local function flap_fx()
		local f = E:create_entity(sca.flap_fx)

		f.pos.x, f.pos.y = this.pos.x, this.pos.y
		f.render.sprites[1].ts = store.tick_ts

		queue_insert(store, f)
	end

	this.flap_fx_fn = flap_fx

	local function spawn_ultimate_bullet(attack, target, offset)
		local pred_pos, pred_ni

		if attack.node_prediction and target.motion and target.motion.speed then
			if target.motion.forced_waypoint then
				local dt = attack.node_prediction == true and 1 or attack.node_prediction

				pred_pos = V.v(target.pos.x + dt * target.motion.speed.x, target.pos.y + dt * target.motion.speed.y)
				pred_ni = target.nav_path.ni
			else
				local node_offset = P:predict_enemy_node_advance(target, attack.node_prediction)

				pred_ni = target.nav_path.ni + node_offset
				pred_pos = P:node_pos(target.nav_path.pi, target.nav_path.spi, pred_ni)
			end
		else
			pred_pos = target.pos
			pred_ni = target.nav_path.ni
		end

		local dir = this.render.sprites[1].flip_x and -1 or 1
		local b = E:create_entity(attack.bullet_t)

		b.bullet.target_id = target.id
		b.bullet.source_id = this.id
		b.bullet.xp_dest_id = this.id
		b.pos = V.v(this.pos.x + offset.x * dir, this.pos.y + this.flight_height + offset.y)
		b.bullet.from = V.vclone(b.pos)

		if b.bullet.ignore_hit_offset then
			b.bullet.to = V.v(pred_pos.x, pred_pos.y)
		else
			b.bullet.to = V.v(pred_pos.x + target.unit.hit_offset.x, pred_pos.y + target.unit.hit_offset.y)
		end

		if b.bullet.use_unit_damage_factor then
			b.bullet.damage_factor = this.unit.damage_factor
		end

		queue_insert(store, b)
	end

	local function find_targets_ultimate(a)
		local function sum_of_values(t)
			local sum = 0

			for i, v in ipairs(t) do
				sum = sum + v
			end

			return sum
		end

		local target, targets, pred_pos = U.find_foremost_enemy(store.entities, this.pos, a.min_range, a.max_range, a.node_prediction, a.vis_flags, a.vis_bans)

		if not targets or #targets < a.min_targets then
			return nil
		end

		local real_prediction = a.node_prediction + sum_of_values(a.fireball_timings)
		local target, targets, pred_pos = U.find_foremost_enemy(store.entities, this.pos, a.min_range, a.max_range, real_prediction, a.vis_flags, a.vis_bans)

		if not targets then
			return nil
		end

		targets = table.filter(targets, function(k, v)
			if not v.nav_path or not v.__ffe_pos then
				return false
			end

			local vni = P:nearest_nodes(v.__ffe_pos.x, v.__ffe_pos.y, {
				v.nav_path.pi
			})[1][3]

			return v.nav_path and v.__ffe_pos and (GR:cell_is(v.__ffe_pos.x, v.__ffe_pos.y, TERRAIN_LAND) or GR:cell_is(v.__ffe_pos.x, v.__ffe_pos.y, TERRAIN_ICE)) and P:is_node_valid(v.nav_path.pi, vni)
		end)

		table.sort(targets, function(e1, e2)
			local p1 = e1.nav_path
			local p2 = e2.nav_path

			return P:nodes_to_goal(p1.pi, p1.spi, p1.ni) < P:nodes_to_goal(p2.pi, p2.spi, p2.ni)
		end)

		return targets
	end

	this.tween.disabled = false
	this.tween.ts = store.tick_ts
	this.health_bar.hidden = false

	U.animation_start(this, this.idle_flip.last_animation, nil, store.tick_ts - fts(4), this.idle_flip.loop, nil, true)

	while true do
		if ult_start_cd and store.wave_group_number > 0 then
			ult_start_cd = false
			ua.ts = store.tick_ts
		end

		if this.health.dead then
			if this.__dust_controller then
				queue_remove(store, this.__dust_controller)
			end

			if band(this.health.last_damage_types, bor(DAMAGE_EAT, DAMAGE_INSTAKILL)) ~= 0 then
				this.hero.tombstone_show_time = nil
				this.hero.tombstone_respawn_animation = nil
			end

			SU.y_hero_death_and_respawn_kr5(store, this)

			this.hero.tombstone_show_time = old_tombstone_time
			this.hero.tombstone_respawn_animation = old_tombstone_respawn_animation

			U.animation_start(this, this.idle_flip.last_animation, nil, store.tick_ts, this.idle_flip.loop, nil, true)
		end

		while this.nav_rally.new and not feeding_time do
			if SU.y_hero_new_rally(store, this) then
				goto label_354_4
			end
		end

		if SU.hero_level_up(store, this) then
			U.y_animation_play(this, "lvlup", nil, store.tick_ts, 1)
		end

		if not feeding_time and not ua.disabled and store.tick_ts - ua.ts > ua.cooldown then
			local a = ua
			local start_ts = store.tick_ts
			local enemies = find_targets_ultimate(a)

			if not enemies or #enemies < a.min_targets then
				SU.delay_attack(store, a, fts(10))
			else
				U.animation_start(this, a.animation, nil, store.tick_ts, false)
				S:queue(a.sound_cast, {
					delay = fts(a.cast_time)
				})
				S:queue(a.sound_taunt, {
					delay = fts(a.cast_time)
				})

				if SU.y_hero_wait(store, this, a.cast_time) then
					S:stop(a.sound_cast)
					S:stop(a.sound_taunt)

					goto label_354_4
				end

				local fireballs = #a.fireball_timings
				local max_shot = 1

				for i, wait in ipairs(a.fireball_timings) do
					U.y_wait(store, wait)

					local j = max_shot

					for k = j, #enemies do
						if enemies[k].health.dead and fireballs - (i - 1) < #enemies - (k - 1) then
							j = k + 1
						else
							break
						end
					end

					if max_shot < j + 1 then
						max_shot = j + 1
					end

					spawn_ultimate_bullet(a, enemies[j], a.fireball_offsets[i])
				end

				if a.shared_cooldown then
					for _, aa in pairs(this.melee.attacks) do
						if aa ~= a and aa.shared_cooldown then
							aa.ts = a.ts
						end
					end
				end

				a.ts = store.tick_ts

				SU.hero_gain_xp_from_skill(this, su)
				U.y_animation_wait(this)
				U.animation_start(this, "idle", nil, store.tick_ts, true)

				goto label_354_4
			end
		end

		if not feeding_time and not sca.disabled and store.tick_ts - sca.ts > sca.cooldown and GR:cell_is(this.pos.x, this.pos.y, bor(TERRAIN_LAND, TERRAIN_ICE)) then
			local a = sca
			local start_ts = store.tick_ts
			local target = U.find_nearest_enemy(store.entities, this.pos, 0, this.melee.range, bor(a.vis_flags, F_BLOCK), bor(a.vis_bans, F_CLIFF), function(e)
				return (not e.enemy.max_blockers or #e.enemy.blockers == 0) and band(GR:cell_type(e.pos.x, e.pos.y), TERRAIN_NOWALK) == 0 and (not this.melee.fn_can_pick or this.melee.fn_can_pick(this, e)) and e.health.hp > a.target_min_hp and e.health.hp < a.target_max_hp
			end)

			if not target then
				SU.delay_attack(store, a, fts(10))

				goto label_354_0
			end

			local c = E:create_entity(a.dust_c)

			c.ashbite_e = this
			this.__dust_controller = c

			queue_insert(store, c)

			this.soldier.target_id = target.id

			U.animation_start(this, a.animation_down, nil, store.tick_ts)
			S:queue(a.sound)
			U.y_wait(store, a.wait_to_lower)

			this.render.sprites[1].z = Z_OBJECTS
			this._current_height = this.flight_height

			U.y_ease_key(store, this, "_current_height", this.flight_height, a.floor_height, a.lower_duration, a.ease_down, function(dt, p)
				this.drag_line_origin_offset.y = this._current_height
				this.render.sprites[1].offset.y = this._current_height
				this.health_bar.offset.y = this._current_height + 80
				this.ui.click_rect.pos.y = this._current_height - 20
				this.unit.hit_offset.y = this._current_height + 10
				this.unit.mod_offset.y = this._current_height + 10

				local scale = km.clamp(1, a.shadow_max_scale, a.shadow_max_scale * (this.flight_height - this._current_height) / (this.flight_height - a.floor_height))

				this.render.sprites[2].scale = V.vv(scale)
			end)

			old_vis_flags = this.vis.flags
			this.vis.flags = this.vis.feeding_flags
			old_vis_bans = this.vis.bans
			this.vis.bans = this.vis.feeding_bans

			SU.hero_gain_xp_from_skill(this, sc)

			if this.track_kills and this.track_kills.mod then
				feeding_time_mod = E:create_entity(this.track_kills.mod)
				feeding_time_mod.pos = V.vclone(this.pos)
				feeding_time_mod.modifier.target_id = this.id
				feeding_time_mod.modifier.source_id = this.id
				feeding_time_mod.heal_on_kill.hp = sca.heal_ptg * this.health.hp_max

				queue_insert(store, feeding_time_mod)
			end

			feeding_time = true
			feeding_time_start_ts = store.tick_ts

			U.y_animation_wait(this)

			goto label_354_4
		end

		::label_354_0::

		if not feeding_time and not sba.disabled and store.tick_ts - sba.ts > sba.cooldown then
			local a = sba
			local start_ts = store.tick_ts
			local pos_offset = v(this.pos.x + a.ignore_offset.x, this.pos.y + a.ignore_offset.y)
			local target, enemies, _ = U.find_foremost_enemy(store.entities, this.pos, a.min_range, a.max_range, a.node_prediction, a.vis_flags, a.vis_bans, function(e, o)
				return not e.unit.ignore_stun and not e.unit.is_stunned and GR:cell_is(e.pos.x, e.pos.y, bor(TERRAIN_LAND, TERRAIN_ICE)) and V.dist2(pos_offset.x, pos_offset.y, e.pos.x, e.pos.y) > a.radius * a.radius
			end)

			if not enemies or #enemies == 0 then
				SU.delay_attack(store, a, fts(10))

				goto label_354_1
			end

			table.sort(enemies, function(a1, a2)
				return a1.health.hp_max > a2.health.hp_max
			end)

			local target = enemies[1]
			local pred_pos, pred_ni

			if a.node_prediction and target.motion and target.motion.speed then
				if target.motion.forced_waypoint then
					local dt = a.node_prediction == true and 1 or a.node_prediction

					pred_pos = V.v(target.pos.x + dt * target.motion.speed.x, target.pos.y + dt * target.motion.speed.y)
					pred_ni = target.nav_path.ni
				else
					local node_offset = P:predict_enemy_node_advance(target, a.node_prediction)

					pred_ni = target.nav_path.ni + node_offset
					pred_pos = P:node_pos(target.nav_path.pi, target.nav_path.spi, pred_ni)
				end
			else
				pred_pos = target.pos
				pred_ni = target.nav_path.ni
			end

			this.render.sprites[1].flip_x = pred_pos.x < this.pos.x

			U.animation_start(this, a.animation, nil, store.tick_ts, false)
			S:queue(a.sound, {
				delay = fts(8)
			})

			if SU.y_hero_wait(store, this, a.cast_time) then
				goto label_354_4
			end

			a.ts = start_ts

			SU.hero_gain_xp_from_skill(this, sb)

			if a.shared_cooldown then
				for _, aa in pairs(this.melee.attacks) do
					if aa ~= a and aa.shared_cooldown then
						aa.ts = a.ts
					end
				end
			end

			local d = this.render.sprites[1].flip_x and -1 or 1
			local offset = V.v(a.offset.x * d, a.offset.y)
			local b = E:create_entity(a.bullet_t)

			b.bullet.target_id = target.id
			b.bullet.source_id = this.id
			b.bullet.xp_dest_id = this.id
			b.pos = V.v(this.pos.x + offset.x, this.pos.y + this.flight_height + offset.y)
			b.bullet.from = V.vclone(b.pos)

			if b.bullet.ignore_hit_offset then
				b.bullet.to = V.v(target.pos.x, target.pos.y)
			else
				b.bullet.to = V.v(target.pos.x + target.unit.hit_offset.x, target.pos.y + target.unit.hit_offset.y)
			end

			if b.bullet.use_unit_damage_factor then
				b.bullet.damage_factor = this.unit.damage_factor
			end

			queue_insert(store, b)

			a.ts = store.tick_ts

			SU.y_hero_animation_wait(this)
			U.animation_start(this, "idle", nil, store.tick_ts, true)

			goto label_354_4
		end

		::label_354_1::

		if not feeding_time and not saa.disabled and store.tick_ts - saa.ts > saa.cooldown then
			local a = saa
			local start_ts = store.tick_ts
			local pos_offset = v(this.pos.x + a.ignore_offset.x, this.pos.y + a.ignore_offset.y)
			local target, targets, _ = U.find_foremost_enemy(store.entities, this.pos, a.min_range, a.max_range, nil, a.vis_flags, a.vis_bans, function(e, o)
				return GR:cell_is(e.pos.x, e.pos.y, bor(TERRAIN_LAND, TERRAIN_ICE)) and V.dist2(pos_offset.x, pos_offset.y, e.pos.x, e.pos.y) > a.radius * a.radius
			end)

			if not targets or #targets < a.min_targets then
				SU.delay_attack(store, a, fts(10))

				goto label_354_2
			end

			local target_pos = target.pos

			this.render.sprites[1].flip_x = target_pos.x < this.pos.x

			U.animation_start(this, a.animation, nil, store.tick_ts, false)
			S:queue(a.sound, {
				delay = fts(14)
			})
			S:queue(a.sound_taunt)

			if SU.y_hero_wait(store, this, a.cast_time) then
				goto label_354_4
			end

			a.ts = start_ts

			SU.hero_gain_xp_from_skill(this, sa)

			if a.shared_cooldown then
				for _, aa in pairs(this.melee.attacks) do
					if aa ~= a and aa.shared_cooldown then
						aa.ts = a.ts
					end
				end
			end

			local d = this.render.sprites[1].flip_x and -1 or 1
			local offset = V.v(a.offset.x * d, a.offset.y)
			local fx = E:create_entity(a.fx_t)

			fx.pos = V.v(this.pos.x + offset.x, this.pos.y + this.flight_height + offset.y)
			fx.render.sprites[1].r = V.angleTo(target_pos.x - fx.pos.x, target_pos.y - fx.pos.y)
			fx.render.sprites[1].scale = V.v(km.clamp(a.min_scale_x, 1.5, V.dist(fx.pos.x, fx.pos.y, target_pos.x, target_pos.y) / a.image_width), 1)

			queue_insert(store, fx)
			U.y_wait(store, a.hit_time)
			S:queue(a.sound_hit)

			local hfx = E:create_entity(a.hit_fx_t)

			hfx.render.sprites[1].ts = store.tick_ts
			hfx.pos.x, hfx.pos.y = target_pos.x, target_pos.y

			queue_insert(store, hfx)

			local au = E:create_entity(a.aura_t)

			au.render.sprites[1].ts = store.tick_ts
			au.pos = V.vclone(target_pos)

			queue_insert(store, au)

			a.ts = store.tick_ts

			U.y_animation_wait(this)
			U.animation_start(this, "idle", nil, store.tick_ts, true)

			goto label_354_4
		end

		::label_354_2::

		if feeding_time then
			local feeding_target = store.entities[this.soldier.target_id]

			if this.nav_rally.new or not feeding_target or feeding_target.health.dead or store.tick_ts - feeding_time_start_ts > sca.duration then
				if this.soldier.target_id then
					U.unblock_target(store, this)
				end

				if this.__dust_controller then
					queue_remove(store, this.__dust_controller)
				end

				U.animation_start(this, sca.animation_up, nil, store.tick_ts)
				flap_fx()

				this.render.sprites[1].z = Z_FLYING_HEROES
				this._current_height = sca.floor_height

				U.y_ease_key(store, this, "_current_height", sca.floor_height, this.flight_height, sca.raise_duration, sca.ease_up, function(dt, p)
					this.drag_line_origin_offset.y = this._current_height
					this.render.sprites[1].offset.y = this._current_height
					this.health_bar.offset.y = this._current_height + 80
					this.ui.click_rect.pos.y = this._current_height - 20
					this.unit.hit_offset.y = this._current_height + 10
					this.unit.mod_offset.y = this._current_height + 10

					local scale = km.clamp(1, sca.shadow_max_scale, sca.shadow_max_scale * (this.flight_height - this._current_height) / (this.flight_height - sca.floor_height))

					this.render.sprites[2].scale = V.vv(scale)
				end)

				this.vis.flags = old_vis_flags
				this.vis.bans = old_vis_bans

				U.y_animation_wait(this)
				queue_remove(store, feeding_time_mod)

				feeding_time = false
				sca.ts = store.tick_ts
			else
				brk, sta = y_hero_melee_block_and_attacks(store, this)

				if not brk and sta == A_DONE then
					this.render.sprites[1].ts = store.tick_ts

					U.animation_start(this, "idle", nil, store.tick_ts, true)

					goto label_354_4
				end

				if brk or sta ~= A_NO_TARGET then
					goto label_354_4
				end
			end
		end

		if not feeding_time and store.tick_ts - aa.ts >= aa.cooldown then
			local pos_offset = v(this.pos.x + aa.ignore_offset.x, this.pos.y + aa.ignore_offset.y)
			local _, targets, __ = U.find_foremost_enemy(store.entities, this.pos, aa.min_range, aa.max_range, 0, aa.vis_flags, aa.vis_bans, function(e)
				return V.dist2(pos_offset.x, pos_offset.y, e.pos.x, e.pos.y) > aa.radius * aa.radius
			end)

			if not targets or #targets == 0 then
				-- block empty
			else
				brk, sta = y_hero_ranged_attacks(store, this)

				U.set_destination(this, this.pos)

				local target = targets[1]
				local start_ts = store.tick_ts
				local start_fx, b, bullet_start_offset
				local node_offset = P:predict_enemy_node_advance(target, aa.node_prediction)
				local t_pos = P:node_pos(target.nav_path.pi, target.nav_path.spi, target.nav_path.ni + node_offset)
				local an, af, ai = U.animation_name_facing_point(this, aa.animation, t_pos)

				U.animation_start(this, an, af, store.tick_ts)

				while store.tick_ts - start_ts < aa.shoot_time do
					if this.unit.is_stunned or this.health.dead or this.nav_rally and this.nav_rally.new then
						goto label_354_3
					end

					coroutine.yield()
				end

				S:queue(aa.sound)

				b = E:create_entity(aa.bullet)
				b.bullet.target_id = target.id
				b.bullet.source_id = this.id
				b.bullet.xp_dest_id = this.id
				b.pos = V.vclone(this.pos)
				bullet_start_offset = v(0, 0)

				if aa.bullet_start_offset and #aa.bullet_start_offset == 2 then
					local offset_index = af and 2 or 1

					bullet_start_offset = aa.bullet_start_offset[offset_index]
				end

				b.pos.x = b.pos.x + (af and -1 or 1) * bullet_start_offset.x
				b.pos.y = b.pos.y + bullet_start_offset.y
				b.bullet.from = V.vclone(b.pos)

				if b.bullet.ignore_hit_offset then
					b.bullet.to = V.v(target.pos.x, target.pos.y)
				else
					b.bullet.to = V.v(target.pos.x + target.unit.hit_offset.x, target.pos.y + target.unit.hit_offset.y)
				end

				if b.bullet.use_unit_damage_factor then
					b.bullet.damage_factor = this.unit.damage_factor
				end

				queue_insert(store, b)

				if aa.xp_from_skill then
					SU.hero_gain_xp_from_skill(this, this.hero.skills[aa.xp_from_skill])
				end

				aa.ts = start_ts

				while not U.animation_finished(this) do
					if this.unit.is_stunned or this.health.dead or this.nav_rally and this.nav_rally.new then
						goto label_354_3
					end

					coroutine.yield()
				end

				aa.ts = start_ts

				U.animation_start(this, this.idle_flip.last_animation, nil, store.tick_ts, this.idle_flip.loop, nil, true)

				::label_354_3::

				if start_fx then
					start_fx.render.sprites[1].hidden = true
				end

				this.render.sprites[1].ts = store.tick_ts
			end
		end

		SU.soldier_idle(store, this)
		SU.soldier_regen(store, this)

		::label_354_4::

		coroutine.yield()
	end
end

scripts.controller_ashbite_dust = {}

function scripts.controller_ashbite_dust.update(this, store, script)
	local skip_next = false

	while true do
		if not skip_next and this.ashbite_e and not this.ashbite_e.health.dead and (this.ashbite_e.render.sprites[1].frame_name == "hero_ashbiteDef_idle_0001" or this.ashbite_e.render.sprites[1].frame_name == "hero_ashbiteDef_feeding_attack_0001" or this.ashbite_e.render.sprites[1].frame_name == "hero_ashbiteDef_feeding_attack_0019") then
			skip_next = true

			this.ashbite_e.flap_fx_fn()
		else
			skip_next = false
		end

		coroutine.yield()
	end
end

scripts.bolt_dragon = {}

function scripts.bolt_dragon.insert(this, store, script)
	local b = this.bullet

	if this.impulse_per_distance then
		local dx, dy = V.sub(b.to.x, b.to.y, b.from.x, b.from.y)
		local dist = V.len(dx, dy)

		this.initial_impulse = this.impulse_per_distance * dist
	end

	if b.target_id then
		local target = store.entities[b.target_id]

		if not target or band(target.vis.bans, F_RANGED) ~= 0 then
			return false
		end
	end

	b.speed.x, b.speed.y = V.normalize(b.to.x - b.from.x, b.to.y - b.from.y)

	local s = this.render.sprites[1]

	if not b.ignore_rotation then
		s.r = V.angleTo(b.to.x - this.pos.x, b.to.y - this.pos.y)
	end

	return true
end

function scripts.bolt_dragon.update(this, store)
	local b = this.bullet
	local mspeed = b.min_speed
	local tl = store.tick_length
	local ps
	local targeted_hit_offset = false
	local flight_time = b.flight_time or 0.5
	local match_flip = this.pos.x > b.to.x

	if b.particles_name then
		ps = E:create_entity(b.particles_name)
		ps.particle_system.track_id = this.id

		queue_insert(store, ps)
	end

	local target = store.entities[b.target_id]

	if target then
		if b.flight_time then
			flight_time = b.flight_time
		else
			local flight_to_x, flight_to_y = target.pos.x, target.pos.y

			if band(target.vis.flags, F_FLYING) ~= 0 and target.unit and target.unit.hit_offset then
				flight_to_x, flight_to_y = flight_to_x + target.unit.hit_offset.x, flight_to_y + target.unit.hit_offset.y
			end

			local dist = V.dist(this.pos.x, this.pos.y, flight_to_x, flight_to_y)

			flight_time = dist / mspeed
		end

		if b.node_prediction then
			local node_offset = P:predict_enemy_node_advance(target, flight_time)

			b.to = P:node_pos(target.nav_path.pi, target.nav_path.spi, target.nav_path.ni + node_offset)

			if band(target.vis.flags, F_FLYING) ~= 0 and target.unit and target.unit.hit_offset then
				targeted_hit_offset = true
				b.to.x, b.to.y = b.to.x + target.unit.hit_offset.x, b.to.y + target.unit.hit_offset.y
			end
		else
			targeted_hit_offset = true
		end
	end

	if b.g then
		b.speed = SU.initial_parabola_speed(b.from, b.to, flight_time, b.g)
		b.ts = store.tick_ts
		b.last_pos = V.vclone(b.from)
	end

	if b.emit_decal then
		local d = E:create_entity(b.emit_decal)

		d.source_id = b.source_id
		d.pos.x, d.pos.y = this.pos.x, this.pos.y
		d.to = V.vclone(b.to)
		d.flight_time = flight_time

		queue_insert(store, d)
	end

	if b.g then
		while flight_time > store.tick_ts - b.ts + store.tick_length do
			coroutine.yield()

			b.last_pos.x, b.last_pos.y = this.pos.x, this.pos.y
			this.pos.x, this.pos.y = SU.position_in_parabola(store.tick_ts - b.ts, b.from, b.speed, b.g)

			if this.render and b.align_with_trajectory then
				this.render.sprites[1].r = V.angleTo(this.pos.x - b.last_pos.x, this.pos.y - b.last_pos.y)
			end
		end
	else
		while V.dist(this.pos.x, this.pos.y, b.to.x, b.to.y) > mspeed * tl do
			b.speed.x, b.speed.y = V.mul(mspeed, V.normalize(b.to.x - this.pos.x, b.to.y - this.pos.y))
			this.pos.x, this.pos.y = this.pos.x + b.speed.x * tl, this.pos.y + b.speed.y * tl

			if this.render and b.align_with_trajectory then
				this.render.sprites[1].r = V.angleTo(b.to.x - this.pos.x, b.to.y - this.pos.y)
			end

			coroutine.yield()
		end
	end

	if target and target.health and not target.health.dead and (not b.damage_radius or b.damage_radius == 0) then
		local d = SU.create_bullet_damage(b, target.id, this.id)

		queue_damage(store, d)

		if b.mod or b.mods then
			local mods = b.mods or {
				b.mod
			}

			for _, mod_name in pairs(mods) do
				local m = E:create_entity(mod_name)

				m.modifier.target_id = b.target_id
				m.modifier.level = b.level

				queue_insert(store, m)
			end
		end
	elseif b.damage_radius and b.damage_radius > 0 then
		local target_pos = target and V.vclone(target.pos) or b.to
		local targets = U.find_enemies_in_range(store.entities, target_pos, 0, b.damage_radius, b.vis_flags, b.vis_bans)

		if targets then
			for _, target in pairs(targets) do
				local d = SU.create_bullet_damage(b, target.id, this.id)

				queue_damage(store, d)

				if b.mod or b.mods then
					local mods = b.mods or {
						b.mod
					}

					for _, mod_name in pairs(mods) do
						local m = E:create_entity(mod_name)

						m.modifier.target_id = target.id
						m.modifier.level = b.level

						queue_insert(store, m)
					end
				end
			end
		end
	end

	S:queue(this.sound_events.hit)

	local fx, air_hit

	if b.hit_fx_air and target and target.vis and band(target.vis.flags, F_FLYING) ~= 0 then
		fx = E:create_entity(b.hit_fx_air)
		air_hit = true
	elseif b.hit_fx then
		fx = E:create_entity(b.hit_fx)
	end

	if fx then
		fx.pos.x, fx.pos.y = b.to.x, b.to.y
		fx.render.sprites[1].ts = store.tick_ts

		if b.hit_fx_match_flip then
			fx.render.sprites[1].flip_x = match_flip
		end

		queue_insert(store, fx)
	end

	if b.hit_decal and not air_hit then
		fx = E:create_entity(b.hit_decal)
		fx.pos.x, fx.pos.y = b.to.x, b.to.y

		if fx.render then
			fx.render.sprites[1].ts = store.tick_ts
		end

		if fx.aura then
			fx.aura.level = b.level
		end

		if fx.tween then
			fx.tween.ts = store.tick_ts
		end

		queue_insert(store, fx)
	end

	queue_remove(store, this)
end

scripts.mod_ashbite_skill_b_burn = {}

function scripts.mod_ashbite_skill_b_burn.update(this, store, script)
	local cycles, total_damage = 0, 0
	local m = this.modifier
	local dps = this.dps
	local dmin = dps.damage_min + m.level * dps.damage_inc
	local dmax = dps.damage_max + m.level * dps.damage_inc
	local fx_ts = 0
	local armor_sunder = 0

	local function do_damage(target, value)
		total_damage = total_damage + value

		local d = E:create_entity("damage")

		d.source_id = this.id
		d.target_id = target.id
		d.value = value
		d.damage_type = dps.damage_type
		d.pop = dps.pop
		d.pop_chance = dps.pop_chance
		d.pop_conds = dps.pop_conds

		queue_damage(store, d)
		SU.armor_dec(target, armor_sunder)
	end

	local target = store.entities[m.target_id]

	if not target then
		queue_remove(store, this)

		return
	end

	if band(target.vis.flags, F_BOSS) == 0 then
		armor_sunder = dps.armor_sunder
	end

	this.pos = target.pos

	while true do
		target = store.entities[m.target_id]

		if not target or target.health.dead then
			break
		end

		if store.tick_ts - m.ts >= m.duration - 1e-09 then
			if dps.damage_last then
				do_damage(target, dps.damage_last)
			end

			break
		end

		if this.render and m.use_mod_offset and target.unit.mod_offset then
			local so = this.render.sprites[1].offset

			so.x, so.y = target.unit.mod_offset.x, target.unit.mod_offset.y
		end

		if dps.damage_every and store.tick_ts - dps.ts >= dps.damage_every then
			cycles = cycles + 1
			dps.ts = dps.ts + dps.damage_every

			local damage_value = math.random(dmin, dmax)

			if cycles == 1 and dps.damage_first then
				damage_value = dps.damage_first
			end

			if not dps.kill then
				damage_value = km.clamp(0, target.health.hp - 1, damage_value)
			end

			do_damage(target, damage_value)

			if dps.fx and (not dps.fx_every or store.tick_ts - fx_ts >= dps.fx_every) then
				fx_ts = store.tick_ts

				local fx = E:create_entity(dps.fx)

				if dps.fx_tracks_target then
					fx.pos = target.pos

					if m.use_mod_offset and target.unit.mod_offset then
						fx.render.sprites[1].offset.x = target.unit.mod_offset.x
						fx.render.sprites[1].offset.y = target.unit.mod_offset.y
					end
				else
					fx.pos = V.vclone(this.pos)

					if m.use_mod_offset and target.unit.mod_offset then
						fx.pos.x, fx.pos.y = fx.pos.x + target.unit.mod_offset.x, fx.pos.y + target.unit.mod_offset.y
					end
				end

				fx.render.sprites[1].ts = store.tick_ts
				fx.render.sprites[1].runs = 0

				if fx.render.sprites[1].size_names then
					fx.render.sprites[1].name = fx.render.sprites[1].size_names[target.unit.size]
				end

				if fx.render.sprites[1].use_blood_color and target.unit.blood_color then
					fx.render.sprites[1].name = fx.render.sprites[1].name .. "_" .. target.unit.blood_color
				end

				if dps.fx_target_flip and target and target.render then
					fx.render.sprites[1].flip_x = target.render.sprites[1].flip_x
				end

				queue_insert(store, fx)
			end
		end

		coroutine.yield()
	end

	log.paranoid(">>>>> id:%s - mod_dps cycles:%s total_damage:%s", this.id, cycles, total_damage)
	queue_remove(store, this)
end

scripts.hero_rhodes = {}

function scripts.hero_rhodes.level_up(this, store, initial)
	if not initial then
		S:queue(this.sound_events.level_up)
	end

	local hl = this.hero.level
	local ls = this.hero.level_stats

	this.health.hp_max = ls.hp_max[hl]
	this.regen.health = ls.regen_health[hl]
	this.health.armor = ls.armor[hl]
	this.melee.attacks[1].damage_min = ls.melee_damage_min[hl]
	this.melee.attacks[1].damage_max = ls.melee_damage_max[hl]
	this.melee.attacks[2].damage_min = ls.melee_damage_min[hl]
	this.melee.attacks[2].damage_max = ls.melee_damage_max[hl]
	this.health.hp = this.health.hp_max
	this.hero.melee_active_status = {}

	for index, attack in ipairs(this.melee.attacks) do
		this.hero.melee_active_status[index] = attack.disabled
	end
end

function scripts.hero_rhodes.insert(this, store)
	this.hero.fn_level_up(this, store, true)

	this.melee.order = U.attack_order(this.melee.attacks)
	this.timed_attacks.list[4].disabled = not this.hero.skills.ultimate.active

	return true
end

function scripts.hero_rhodes.update(this, store)
	local h = this.health
	local brk, sta, blocker, about_to_block, started_blocking_ts, talent_1_armor_mod
	local delayed_attack_ult = false
	local old_tombstone_time = this.hero.tombstone_show_time
	local old_tombstone_respawn_animation = this.hero.tombstone_respawn_animation

	this.health_bar.hidden = false

	local sa, sb, sc, su, st1, st2 = this.hero.skills.skill_a, this.hero.skills.skill_b, this.hero.skills.skill_c, this.hero.skills.ultimate, this.hero.skills.talent_1, this.hero.skills.talent_2
	local saa = this.timed_attacks.list[1]

	saa.ts = store.tick_ts - saa.cooldown

	local sba = this.timed_attacks.list[2]

	sba.ts = store.tick_ts - sba.cooldown

	local sca = this.timed_attacks.list[3]

	sca.ts = store.tick_ts - sca.cooldown

	local ua = this.timed_attacks.list[4]

	ua.ts = store.tick_ts - ua.cooldown

	local ult_start_cd = store.wave_group_number == 0

	local function trigger_immune_to_stuns()
		this.unit.ignore_stun = true
		this.vis.bans = U.flag_set(this.vis.bans, F_STUN)
	end

	local function trigger_affected_by_stuns()
		this.unit.ignore_stun = false
		this.vis.bans = U.flag_clear(this.vis.bans, F_STUN)
	end

	if not st2.disabled then
		trigger_immune_to_stuns()
	end

	local function shoot_bullet(attack, enemy)
		local shooting_right = not this.render.sprites[1].flip_x
		local roffset = attack.ray_start_offset
		local hoffset = V.vclone(enemy.unit.hit_offset)

		if enemy.render.sprites[1].flip_x then
			hoffset.x = -hoffset.x
		end

		local b = E:create_entity(attack.bullet)

		b.pos.x = this.pos.x + roffset.x * (shooting_right and 1 or -1)
		b.pos.y = this.pos.y + roffset.y
		b.bullet.from = V.vclone(b.pos)
		b.bullet.to = V.v(enemy.pos.x + hoffset.x, enemy.pos.y + hoffset.y)
		b.bullet.target_id = enemy.id
		b.bullet.source_id = this.id
		b.bullet.damage_factor = this.unit.damage_factor

		queue_insert(store, b)
	end

	local function shoot_bullet_pos(attack, target_pos)
		local shooting_right = not this.render.sprites[1].flip_x
		local roffset = attack.ray_start_offset
		local b = E:create_entity(attack.bullet)

		b.pos.x = this.pos.x + roffset.x * (shooting_right and 1 or -1)
		b.pos.y = this.pos.y + roffset.y
		b.bullet.from = V.vclone(b.pos)
		b.bullet.to = V.v(target_pos.x, target_pos.y)
		b.bullet.source_id = this.id
		b.bullet.damage_factor = this.unit.damage_factor

		queue_insert(store, b)
	end

	local function get_paths_im_on(paths)
		if not paths then
			paths = {}

			for i = 1, #P.paths do
				table.insert(paths, i)
			end
		end

		local nearest_nodes = P:nearest_nodes(this.pos.x, this.pos.y, paths, nil, true)

		nearest_nodes = table.filter(nearest_nodes, function(k, v)
			local c = v[4] < P:path_width(v[1])

			return c
		end)

		local p = #nearest_nodes > 0 and {} or nil

		for i, v in ipairs(nearest_nodes) do
			table.insert(p, v[1])
		end

		return p
	end

	local function find_most_populated_path(enemies, min_enemies)
		local paths_count = {}
		local found_paths = {}

		for k, v in pairs(enemies) do
			if not table.contains(found_paths, v.nav_path.pi) then
				table.insert(found_paths, v.nav_path.pi)
				table.insert(paths_count, {
					v.nav_path.pi,
					1
				})
			else
				local i = index_at(paths_count, v, function(tv, iv)
					return iv.nav_path.pi == tv[1]
				end)

				paths_count[i][2] = paths_count[i][2] + 1
			end
		end

		table.sort(paths_count, function(v1, v2)
			return v1[2] > v2[2]
		end)

		return min_enemies <= paths_count[1][2] and paths_count[1][1] or nil
	end

	local function find_most_populated_path_that_we_are_on(enemies, min_enemies)
		local paths_count = {}
		local found_paths = {}

		for k, v in pairs(enemies) do
			if not table.contains(found_paths, v.nav_path.pi) then
				table.insert(found_paths, v.nav_path.pi)
				table.insert(paths_count, {
					v.nav_path.pi,
					1
				})
			else
				local i = index_at(paths_count, v, function(tv, iv)
					return iv.nav_path.pi == tv[1]
				end)

				paths_count[i][2] = paths_count[i][2] + 1
			end
		end

		local paths_hero = get_paths_im_on(found_paths)

		if paths_hero then
			for i1, v1 in ipairs(paths_count) do
				local remove = true

				for i2, v2 in ipairs(paths_hero) do
					if v1[1] == v2 then
						remove = false

						break
					end
				end

				if remove then
					table.remove(paths_count, i1)
				end
			end

			table.sort(paths_count, function(v1, v2)
				return v1[2] > v2[2]
			end)

			local s = 0

			for i, v in ipairs(paths_count) do
				local c = v[2]

				s = s + c
			end

			return min_enemies <= s and paths_count[1][1] or nil
		end

		return nil
	end

	local function is_about_to_block()
		local center = this.nav_rally and this.nav_rally.center or this.pos
		local target = U.find_nearest_enemy(store.entities, center, 0, this.melee.range, F_BLOCK, bit.bor(F_CLIFF), function(e)
			return (not e.enemy.max_blockers or #e.enemy.blockers == 0) and band(GR:cell_type(e.pos.x, e.pos.y), TERRAIN_NOWALK) == 0 and (not this.melee.fn_can_pick or this.melee.fn_can_pick(this, e))
		end)

		return target ~= nil
	end

	local function ult_walk(pos, dt, dest, speed, max_speed)
		local vx, vy = V.sub(dest.x, dest.y, pos.x, pos.y)
		local v_angle = V.angleTo(vx, vy)
		local v_len = V.len(vx, vy)
		local step = max_speed * dt
		local nx, ny = V.normalize(V.rotate(v_angle, 1, 0))

		if v_len <= step then
			pos.x, pos.y = dest.x, dest.y
			speed.x, speed.y = 0, 0

			return true
		end

		local sx, sy = V.mul(math.min(step, v_len), nx, ny)

		pos.x, pos.y = V.add(pos.x, pos.y, sx, sy)
		speed.x, speed.y = sx / dt, sy / dt

		return false
	end

	while true do
		if ult_start_cd and store.wave_group_number > 0 then
			ult_start_cd = false
			ua.ts = store.tick_ts
		end

		if h.dead then
			if band(h.last_damage_types, bor(DAMAGE_EAT)) ~= 0 then
				this.hero.tombstone_show_time = nil
				this.hero.tombstone_respawn_animation = nil
			end

			SU.y_hero_death_and_respawn_kr5(store, this)

			this.hero.tombstone_show_time = old_tombstone_time
			this.hero.tombstone_respawn_animation = old_tombstone_respawn_animation
		end

		if not this.unit.ignore_stun and this.unit.is_stunned then
			SU.soldier_idle(store, this)
		else
			while this.nav_rally.new do
				if SU.y_hero_new_rally(store, this) then
					goto label_375_3
				end
			end

			if SU.hero_level_up(store, this) then
				U.y_animation_play(this, "level_up", nil, store.tick_ts, 1)
			end

			if not st1.disabled and talent_1_armor_mod == nil and this.health.hp > this.health.hp_max * (1 - st1.hp_threshold) then
				talent_1_armor_mod = E:create_entity(st1.mod)
				talent_1_armor_mod.modifier.source_id = this.id
				talent_1_armor_mod.modifier.target_id = this.id

				queue_insert(store, talent_1_armor_mod)
			end

			if talent_1_armor_mod ~= nil and this.health.hp <= this.health.hp_max * (1 - st1.hp_threshold) then
				queue_remove(store, talent_1_armor_mod)

				talent_1_armor_mod = nil
			end

			brk, sta = y_hero_melee_block_and_attacks(store, this)

			if this.health.dead then
				-- block empty
			else
				if sta ~= A_NO_TARGET and sta ~= A_DONE then
					if started_blocking_ts == nil then
						started_blocking_ts = store.tick_ts
					end
				else
					started_blocking_ts = nil
				end

				if not brk and sta ~= A_IN_COOLDOWN and sta ~= A_DONE then
					about_to_block = is_about_to_block()
				else
					about_to_block = false
				end

				if delayed_attack_ult and store.tick_ts - sca.ts > sca.cooldown then
					delayed_attack_ult = false
				end

				if not ua.disabled and (store.tick_ts - ua.ts > ua.cooldown and this.motion.arrived and this.soldier.target_id == nil or (store.tick_ts - ua.ts > ua.cooldown or delayed_attack_ult) and about_to_block) then
					local a = ua
					local start_ts = store.tick_ts
					local det_range = about_to_block and a.range_pre_block or a.range
					local real_prediction = a.prediction_time
					local target, targets = U.find_foremost_enemy(store.entities, this.pos, 0, det_range, real_prediction, a.vis_flags, a.vis_bans)

					if not target or #targets == 0 then
						delayed_attack_ult = true

						SU.delay_attack(store, a, fts(10))

						goto label_375_0
					end

					local ray_t = E:get_template(a.bullet)
					local det_range = about_to_block and a.range_pre_block or a.range
					local _, targets = U.find_foremost_enemy(store.entities, target.pos, 0, ray_t.ray_duration * a.move_speed, fts(31), a.vis_flags, a.vis_bans)

					if not targets or #targets == 0 then
						delayed_attack_ult = true

						SU.delay_attack(store, a, fts(10))

						goto label_375_0
					end

					local path = targets and find_most_populated_path(targets, a.min_targets) or nil

					if not path then
						delayed_attack_ult = true

						SU.delay_attack(store, a, fts(10))

						goto label_375_0
					end

					delayed_attack_ult = false

					S:queue(ua.sound_cast)
					S:queue(a.sound_taunt)
					U.animation_start(this, a.animation_start, nil, store.tick_ts, false, 1)

					while not U.animation_finished(this, 1) do
						if SU.soldier_interrupted(this) then
							S:stop(ua.sound_cast)

							goto label_375_0
						end

						coroutine.yield()
					end

					local first_enemy_on_path = first(targets, function(v)
						return v.nav_path.pi == path
					end)
					local first_nodes = first_enemy_on_path and P:nearest_nodes(first_enemy_on_path.pos.x, first_enemy_on_path.pos.y, {
						path
					}, nil, true) or nil

					if not first_nodes or #first_nodes == 0 then
						S:stop(ua.sound_cast)

						delayed_attack_ult = true

						SU.delay_attack(store, a, fts(10))
						U.animation_start(this, a.animation_end, nil, store.tick_ts, false, 1)
						SU.y_hero_animation_wait(this)

						goto label_375_0
					end

					U.animation_start(this, a.animation_loop, nil, store.tick_ts, true, 1)

					local first_ni = first_nodes[1][3]
					local direction = -1
					local dest_ni = first_ni + 3 * direction
					local start = P:node_pos(path, 1, first_ni)
					local dest = P:node_pos(path, 1, dest_ni)
					local ray = E:create_entity(a.bullet)

					ray.bullet.from = v(this.pos.x + a.ray_start_offset.x * (this.render.sprites[1].flip_x and 1 or -1), this.pos.y + a.ray_start_offset.y)
					ray.bullet.to = V.vclone(start)
					ray.pos.x, ray.pos.y = ray.bullet.from.x, ray.bullet.from.y
					ray.bullet.source_id = this.id
					ray.bullet.damage_factor = this.unit.damage_factor
					ray.render.sprites[1].sort_y_offset = ray.bullet.to.y - ray.pos.y

					queue_insert(store, ray)
					S:queue(ua.sound_ray_cast)

					local particles = E:create_entity(a.particles_name)

					queue_insert(store, particles)

					local hit_decal = E:create_entity(a.hit_decal)

					hit_decal.render.sprites[1].ts = store.tick_ts

					queue_insert(store, hit_decal)

					local ray_begin_ts = store.tick_ts
					local aux_speed = {
						x = 0,
						y = 0
					}

					while store.tick_ts - ray_begin_ts < ray.ray_duration - ray.anim_end_duration do
						particles.pos.x, particles.pos.y = ray.bullet.to.x + a.hit_offset.x, ray.bullet.to.y + a.hit_offset.y
						hit_decal.pos.x, hit_decal.pos.y = ray.bullet.to.x, ray.bullet.to.y

						if ult_walk(ray.bullet.to, store.tick_length, dest, aux_speed, a.move_speed) then
							dest_ni = dest_ni + 3 * direction
							dest = P:node_pos(path, 1, dest_ni)
						end

						coroutine.yield()

						ray.render.sprites[1].sort_y_offset = ray.bullet.to.y - ray.pos.y
					end

					queue_remove(store, particles)
					queue_remove(store, hit_decal)
					U.animation_start(ray, ray.anim_end, nil, store.tick_ts, false, 1)
					SU.hero_gain_xp_from_skill(this, su)

					ua.ts = store.tick_ts
					this.nav_rally.new = nil

					U.animation_start(this, a.animation_end, nil, store.tick_ts, false, 1)

					while not U.animation_finished(this, 1) do
						if SU.soldier_interrupted(this) then
							goto label_375_0
						end

						coroutine.yield()
					end

					goto label_375_3
				end

				::label_375_0::

				if not sca.disabled and store.tick_ts - sca.ts > sca.cooldown and this.motion.arrived then
					local a = sca
					local start_ts = store.tick_ts
					local sc_aura = E:get_template(a.aura)
					local real_prediction = a.prediction_time + sc_aura.max_nodes * P.average_node_dist / sc_aura.motion.max_speed
					local target, targets = U.find_foremost_enemy(store.entities, this.pos, 0, a.max_range, real_prediction, a.vis_flags, a.vis_bans, function(v, o)
						return v.nav_path
					end)
					local path = targets and find_most_populated_path_that_we_are_on(targets, a.min_targets) or nil

					if not path then
						SU.delay_attack(store, a, fts(10))
					else
						U.animation_start(this, a.animation_start, nil, store.tick_ts, false, 1)
						S:queue(sca.sound_start)

						while not U.animation_finished(this, 1) do
							if SU.soldier_interrupted(this) then
								goto label_375_1
							end

							coroutine.yield()
						end

						local path = find_most_populated_path_that_we_are_on(targets, a.min_targets)

						if not path then
							local nearest = P:nearest_nodes(this.pos.x, this.pos.y, get_paths_im_on(), {
								1
							}, true)

							path = nearest[1] and nearest[1][1] or nil
						end

						if not path then
							SU.delay_attack(store, a, fts(10))
							U.animation_start(this, a.animation_end, nil, store.tick_ts, false, 1)
							S:queue(sca.sound_end)
							SU.y_hero_animation_wait(this)
						else
							if st2.disabled then
								trigger_immune_to_stuns()
							end

							local top = E:create_entity(a.aura)

							top.pos.x, top.pos.y = this.pos.x, this.pos.y
							top.pi = path
							top.rhodes = this

							queue_insert(store, top)
							U.animation_start(this, a.animation_loop, nil, store.tick_ts, true, 1)

							this._waiting_for_spinner = true

							while this._waiting_for_spinner and not top.pending_removal do
								coroutine.yield()
							end

							if st2.disabled then
								trigger_affected_by_stuns()
							end

							SU.hero_gain_xp_from_skill(this, sc)

							sca.ts = store.tick_ts
							this.nav_rally.new = nil

							U.animation_start(this, a.animation_end, nil, store.tick_ts, false, 1)
							S:queue(sca.sound_end)

							while not U.animation_finished(this, 1) do
								if SU.soldier_interrupted(this) then
									goto label_375_1
								end

								coroutine.yield()
							end

							goto label_375_3
						end
					end
				end

				::label_375_1::

				if not saa.disabled and store.tick_ts - saa.ts > saa.cooldown and this.motion.arrived then
					local a = saa
					local start_ts = store.tick_ts
					local target
					local trigger_target, targets, _ = U.find_foremost_enemy(store.entities, this.pos, a.min_range, a.max_range, a.node_prediction, a.vis_flags, a.vis_bans)

					if not targets or #targets == 0 then
						SU.delay_attack(store, a, fts(10))
					else
						local target_pos = V.vclone(trigger_target.pos)

						this.render.sprites[1].flip_x = P:predict_enemy_pos(trigger_target, a.cast_time).x < this.pos.x

						U.animation_start(this, a.animation, nil, store.tick_ts, nil, 1)
						S:queue(saa.sound)

						if SU.y_hero_wait(store, this, a.cast_time) then
							-- block empty
						else
							local shooting_right = not this.render.sprites[1].flip_x
							local ray_start_fx_1 = E:create_entity(saa.ray_fx_1)

							ray_start_fx_1.pos.x, ray_start_fx_1.pos.y = this.pos.x + saa.ray_start_offset.x * (shooting_right and 1 or -1), this.pos.y + saa.ray_start_offset.y
							ray_start_fx_1.render.sprites[1].ts = store.tick_ts

							queue_insert(store, ray_start_fx_1)

							local target, targets, _ = U.find_foremost_enemy(store.entities, this.pos, a.min_range, a.max_range, a.node_prediction, a.vis_flags, a.vis_bans)

							if not trigger_target or trigger_target.health.dead then
								if not target or #targets == 0 then
									shoot_bullet_pos(saa, target_pos)
								else
									shoot_bullet(a, target)
								end
							else
								shoot_bullet(a, trigger_target)
							end

							SU.hero_gain_xp_from_skill(this, sa)

							saa.ts = store.tick_ts
							this.nav_rally.new = nil

							while not U.animation_finished(this, 1) do
								if SU.soldier_interrupted(this) then
									goto label_375_2
								end

								coroutine.yield()
							end

							goto label_375_3
						end
					end
				end

				::label_375_2::

				if not sba.disabled and store.tick_ts - sba.ts > sba.cooldown and this.motion.arrived and this.soldier.target_id ~= nil and (this.health.hp <= this.health.hp_max * (1 - sba.trigger_hp_ptg) or started_blocking_ts and store.tick_ts - started_blocking_ts > sba.time_blocking_to_trigger) then
					local blocker = store.entities[this.soldier.target_id]
					local a = sba
					local start_ts = store.tick_ts

					U.animation_start(this, a.animation, nil, store.tick_ts, false)
					S:queue(sba.sound, {
						delay = fts(14)
					})

					if SU.y_hero_wait(store, this, a.cast_time) then
						-- block empty
					elseif not blocker then
						this.soldier.target_id = nil
					else
						a.ts = start_ts

						SU.hero_gain_xp_from_skill(this, sb)

						if a.shared_cooldown then
							for _, aa in pairs(this.timed_attacks.list) do
								if aa ~= a and aa.shared_cooldown then
									aa.ts = a.ts
								end
							end
						end

						local mod_a = E:create_entity(a.mod_armor)

						mod_a.modifier.source_id = this.id
						mod_a.modifier.target_id = this.id

						queue_insert(store, mod_a)

						local mod_h = E:create_entity(a.mod_heal)

						mod_h.modifier.source_id = this.id
						mod_h.modifier.target_id = this.id
						mod_h.hps.heal_min = this.health.hp_max * a.hp_heal_ptg
						mod_h.hps.heal_max = mod_h.hps.heal_min

						queue_insert(store, mod_h)
						SU.y_hero_animation_wait(this)
						U.animation_start(this, "idle", nil, store.tick_ts, true)

						goto label_375_3
					end
				end

				if brk or sta ~= A_NO_TARGET then
					-- block empty
				elseif SU.soldier_go_back_step(store, this) then
					-- block empty
				else
					SU.soldier_idle(store, this)
					SU.soldier_regen(store, this)
				end
			end
		end

		::label_375_3::

		coroutine.yield()
	end
end

scripts.mod_rhodes_skill_b_armor = {}

function scripts.mod_rhodes_skill_b_armor.update(this, store, script)
	local m = this.modifier

	this.modifier.ts = store.tick_ts

	local target = store.entities[m.target_id]

	if not target or not target.pos then
		queue_remove(store, this)

		return
	end

	this.pos = target.pos

	U.y_animation_wait(this, 1, 1)
	U.animation_start(this, this.anim_loop, nil, store.tick_ts, true, 1)

	while true do
		target = store.entities[m.target_id]

		if not target or target.health.dead or m.duration >= 0 and store.tick_ts - m.ts > m.duration or m.last_node and target.nav_path.ni > m.last_node then
			queue_remove(store, this)

			return
		end

		if this.render and target.unit then
			local s = this.render.sprites[1]
			local flip_sign = 1

			if target.render then
				flip_sign = target.render.sprites[1].flip_x and -1 or 1
			end

			if m.health_bar_offset and target.health_bar then
				local hb = target.health_bar.offset
				local hbo = m.health_bar_offset

				s.offset.x, s.offset.y = hb.x + hbo.x * flip_sign, hb.y + hbo.y
			elseif m.use_mod_offset and target.unit.mod_offset then
				s.offset.x, s.offset.y = target.unit.mod_offset.x * flip_sign, target.unit.mod_offset.y
			end
		end

		coroutine.yield()
	end
end

function scripts.mod_rhodes_skill_b_armor.remove(this, store, script)
	if not this.tween.disabled then
		return true
	end

	scripts.mod_armor_buff.remove(this, store, script)

	return scripts.tween_utils.reverse_remove(this, store, script)
end

scripts.aura_rhodes_skill_c = {}

function scripts.aura_rhodes_skill_c.update(this, store, script)
	local first_hit_ts
	local last_hit_ts = 0
	local nearest_nodes = P:nearest_nodes(this.pos.x, this.pos.y, {
		this.pi
	}, {
		1
	})
	local pi, spi, ni = unpack(nearest_nodes[1])
	local starting_ni = ni
	local distSq = 0

	last_hit_ts = store.tick_ts - this.aura.cycle_time

	if this.aura.apply_delay then
		last_hit_ts = last_hit_ts + this.aura.apply_delay
	end

	local is_backwards = true
	local origin = V.vclone(this.pos)
	local target_pos = P:node_pos(pi, spi, ni)
	local sound_flag = true

	if this.particles_name then
		local particle = E:create_entity(this.particles_name)

		particle.particle_system.track_id = this.id

		queue_insert(store, particle)
	end

	local function hit_enemies()
		local targets = U.find_enemies_in_range(store.entities, this.pos, 0, this.aura.radius, this.aura.vis_flags, this.aura.vis_bans, function(v, o)
			return (not this.aura.allowed_templates or table.contains(this.aura.allowed_templates, v.template_name)) and (not this.aura.excluded_templates or not table.contains(this.aura.excluded_templates, v.template_name)) and (not this.aura.filter_source or this.aura.source_id ~= v.id)
		end)

		if targets then
			for i, target in pairs(targets) do
				if target and not target.health.dead and target.enemy then
					queue_damage(store, SU.create_attack_damage(this, target.id, this.id))

					local hit_fx = E:create_entity(this.hit_fx)

					hit_fx.pos = V.vclone(target.pos)
					hit_fx.pos.x, hit_fx.pos.y = hit_fx.pos.x + target.unit.hit_offset.x, hit_fx.pos.y + target.unit.hit_offset.y
					hit_fx.render.sprites[1].ts = store.tick_ts

					queue_insert(store, hit_fx)

					local new_mod = E:create_entity(this.aura.mod)

					new_mod.modifier.target_id = target.id
					new_mod.modifier.source_id = this.id

					queue_insert(store, new_mod)
				end
			end
		end
	end

	local function go_step()
		if V.veq(this.pos, target_pos) then
			this.motion.arrived = true

			return false
		else
			U.set_destination(this, target_pos)

			if U.walk(this, store.tick_length) then
				return false
			else
				local an, af = U.animation_name_facing_point(this, "loop", this.motion.dest, 1, nil, true)

				U.animation_start(this, an, af, store.tick_ts, true)

				return true
			end
		end
	end

	local function run(is_backwards)
		local last_pos = this.pos

		distSq = V.dist2(target_pos.x, target_pos.y, this.pos.x, this.pos.y)

		if distSq < 25 then
			ni = ni + 3 * (is_backwards and -1 or 1)
			target_pos = P:node_pos(pi, spi, ni)
		end

		go_step()
	end

	S:queue(this.sound_loop)

	while true do
		if this.interrupt then
			last_hit_ts = 1e+99
		end

		if is_backwards and starting_ni - ni > this.max_nodes or ni <= 3 then
			is_backwards = false
		end

		if not is_backwards and starting_ni - ni < 3 then
			break
		end

		if store.tick_ts - last_hit_ts >= this.aura.cycle_time then
			if this.aura.apply_duration and first_hit_ts and store.tick_ts - first_hit_ts > this.aura.apply_duration then
				goto label_395_0
			end

			first_hit_ts = first_hit_ts or store.tick_ts
			last_hit_ts = store.tick_ts

			hit_enemies()
		end

		run(is_backwards)

		::label_395_0::

		coroutine.yield()
	end

	target_pos = origin

	while go_step() do
		distSq = V.dist2(target_pos.x, target_pos.y, this.pos.x, this.pos.y)

		if distSq < 25 and sound_flag then
			sound_flag = false

			S:stop(this.sound_loop)
			S:queue(this.sound_end)
		end

		coroutine.yield()
	end

	this.rhodes._waiting_for_spinner = false

	queue_remove(store, this)
end

scripts.hero_drakkan = {}

function scripts.hero_drakkan.level_up(this, store, initial)
	local hl = this.hero.level
	local ls = this.hero.level_stats

	this.health.hp_max = ls.hp_max[hl]
	this.regen.health = ls.regen_health[hl]
	this.health.armor = ls.armor[hl]

	local b = E:get_template(this.ranged.attacks[1].bullet)

	b.bullet.damage_min = ls.ranged_damage_min[hl]
	b.bullet.damage_max = ls.ranged_damage_max[hl]
	this.health.hp = this.health.hp_max
end

function scripts.hero_drakkan.insert(this, store)
	this.hero.fn_level_up(this, store, true)

	this.ranged.order = U.attack_order(this.ranged.attacks)
	this.timed_attacks.list[4].disabled = not this.hero.skills.ultimate.active

	return true
end

function scripts.hero_drakkan.update(this, store)
	local brk, sta, cell_type, old_vis_flags, old_vis_bans
	local shots_with_mod = 0
	local shadow_sprite = this.render.sprites[2]
	local old_tombstone_time, radius_ult_bullet
	local ult_start_y = store.visible_coords and store.visible_coords.top or REF_H
	local old_tombstone_time = this.hero and this.hero.tombstone_show_time or 0
	local old_tombstone_respawn_animation = this.hero and this.hero.tombstone_respawn_animation or 0
	local sa, sb, sc, su, st1, st2

	if this.hero then
		old_tombstone_time = this.hero.tombstone_show_time
		sa, sb, sc, su, st1, st2 = this.hero.skills.skill_a, this.hero.skills.skill_b, this.hero.skills.skill_c, this.hero.skills.ultimate, this.hero.skills.talent_1, this.hero.skills.talent_2
	end

	local aa = this.ranged.attacks[1]
	local saa = this.timed_attacks.list[1]
	local sba = this.timed_attacks.list[2]
	local sca = this.timed_attacks.list[3]
	local ua = this.timed_attacks.list[4]
	local ult_start_cd = store.wave_group_number == 0

	aa.ts = store.tick_ts - aa.cooldown

	if saa then
		saa.ts = store.tick_ts - saa.cooldown
	end

	if sba then
		sba.ts = store.tick_ts - sba.cooldown
	end

	if sca then
		sca.ts = store.tick_ts - sca.cooldown
	end

	if ua then
		ua.ts = store.tick_ts - ua.cooldown

		local ult_bullet_t = E:get_template(ua.bullet_t)

		radius_ult_bullet = ult_bullet_t.bullet.damage_radius
	end

	if st1 then
		this.teleport.disabled = st1.disabled
	end

	if st2 and not st2.disabled then
		this.timed_attacks.list[1].cooldown = this.timed_attacks.list[1].cooldown * (1 - st2.skills_cd_red)
		this.timed_attacks.list[2].cooldown = this.timed_attacks.list[2].cooldown * (1 - st2.skills_cd_red)
		this.timed_attacks.list[3].cooldown = this.timed_attacks.list[3].cooldown * (1 - st2.skills_cd_red)
	end

	local function pred_pos(attack, target)
		local pred_pos, pred_ni

		if attack.node_prediction and target.motion and target.motion.speed then
			if target.motion.forced_waypoint then
				local dt = attack.node_prediction == true and 1 or attack.node_prediction

				pred_pos = V.v(target.pos.x + dt * target.motion.speed.x, target.pos.y + dt * target.motion.speed.y)
				pred_ni = target.nav_path.ni
			else
				local node_offset = P:predict_enemy_node_advance(target, attack.node_prediction)

				pred_ni = target.nav_path.ni + node_offset
				pred_pos = P:node_pos(target.nav_path.pi, target.nav_path.spi, pred_ni)
			end
		else
			pred_pos = target.pos
			pred_ni = target.nav_path.ni
		end

		return pred_pos, pred_ni
	end

	local function spawn_ultimate_bullet(attack, target)
		local pred_pos, pred_ni = pred_pos(attack, target)
		local dir = this.render.sprites[1].flip_x and -1 or 1
		local b = E:create_entity(attack.bullet_t)

		b.bullet.target_id = target.id
		b.bullet.source_id = this.id
		b.bullet.xp_dest_id = this.id
		b.pos = V.v(pred_pos.x, ult_start_y)
		b.bullet.from = V.vclone(b.pos)
		b.bullet.to = V.v(pred_pos.x, pred_pos.y)

		if b.bullet.use_unit_damage_factor then
			b.bullet.damage_factor = this.unit.damage_factor
		end

		queue_insert(store, b)
	end

	local function find_targets_ultimate(a)
		local t, targets, p = U.find_foremost_enemy(store.entities, this.pos, 0, a.max_range, 0, a.vis_flags, a.vis_bans, function(v, o)
			if not v.nav_path then
				return false
			end

			local pred_pos, pred_ni = pred_pos(a, v)

			return v.nav_path and GR:cell_type(pred_pos.x, pred_pos.y) == TERRAIN_LAND and P:is_node_valid(v.nav_path.pi, pred_ni)
		end)

		if not targets or #targets < a.min_targets then
			return nil
		end

		local final_targets = {}
		local marked_ids = {}

		while #final_targets < ua.shots do
			local t = first(targets, function(v)
				return not table.contains(marked_ids, v.id)
			end)

			if t then
				table.insert(final_targets, t)
				table.remove(targets, index_at(targets, t, function(tv, iv)
					return tv.id == iv.id
				end))

				for i, v in ipairs(targets) do
					if U.is_inside_ellipse(v.pos, t.pos, radius_ult_bullet) and not table.contains(marked_ids, v.id) then
						table.insert(marked_ids, v.id)
					end
				end
			else
				break
			end
		end

		if #final_targets < ua.shots then
			shuffle_table(targets)

			for i = 1, ua.shots - #final_targets do
				table.insert(final_targets, targets[i])
			end
		end

		shuffle_table(final_targets)

		return final_targets
	end

	local function y_drakkan_new_rally(store, this)
		S:queue(this.sound_events.change_rally_point)

		local r = this.nav_rally

		if r.new then
			r.new = false

			U.unblock_target(store, this)

			if SU.hero_will_teleport(this, r.pos) then
				local tp = this.teleport
				local vis_bans = this.vis.bans

				this.vis.bans = F_ALL
				this.health.ignore_damage = true
				this.health_bar.hidden = true

				S:queue(tp.sound_in)

				if tp.fx_out then
					local fx = E:create_entity(tp.fx_out)

					fx.pos.x, fx.pos.y = this.pos.x, this.pos.y
					fx.render.sprites[1].ts = store.tick_ts

					if fx.tween then
						fx.tween.ts = store.tick_ts
					end

					queue_insert(store, fx)
				end

				local an, af = U.animation_name_facing_point(this, tp.animations[1], r.pos)

				U.animation_start(this, an, af, store.tick_ts, 1, nil)
				SU.y_hero_animation_wait(this)

				if tp.delay > 0 then
					U.sprites_hide(this, nil, nil, true)
					U.y_wait(store, tp.delay)
					U.sprites_show(this, nil, nil, true)
				end

				this.pos.x, this.pos.y = r.pos.x, r.pos.y

				U.set_destination(this, this.pos)

				this.motion.speed.x, this.motion.speed.y = 0, 0

				if tp.fx_in then
					local fx = E:create_entity(tp.fx_in)

					fx.pos.x, fx.pos.y = this.pos.x, this.pos.y
					fx.render.sprites[1].ts = store.tick_ts

					if fx.tween then
						fx.tween.ts = store.tick_ts
					end

					queue_insert(store, fx)
				end

				S:queue(tp.sound_out)
				U.y_animation_play(this, tp.animations[2], nil, store.tick_ts)

				this.health_bar.hidden = false
				this.vis.bans = vis_bans
				this.health.ignore_damage = false
			else
				local vis_bans = this.vis.bans
				local prev_immune = this.health.immune_to

				this.vis.bans = F_ALL
				this.health.immune_to = r.immune_to

				local out = SU.y_hero_walk_waypoints(store, this)

				U.animation_start(this, "walk", nil, store.tick_ts, true)

				this.vis.bans = vis_bans
				this.health.immune_to = prev_immune

				return out
			end
		end
	end

	this.tween.disabled = false
	this.tween.ts = store.tick_ts
	this.health_bar.hidden = false

	local spawn_ts = store.tick_ts

	if this.is_clone then
		U.y_animation_wait(this, 1, 1)
		U.animation_start(this, this.idle_flip.last_animation, nil, store.tick_ts - fts(4), this.idle_flip.loop, nil, true)
		U.y_wait(store, 0.3)
	else
		U.animation_start(this, this.idle_flip.last_animation, nil, store.tick_ts - fts(4), this.idle_flip.loop, nil, true)
	end

	while true do
		if ult_start_cd and store.wave_group_number > 0 then
			ult_start_cd = false
			ua.ts = store.tick_ts
		end

		if this.health.dead then
			if not this.is_clone then
				if band(this.health.last_damage_types, bor(DAMAGE_EAT, DAMAGE_INSTAKILL)) ~= 0 then
					this.hero.tombstone_show_time = nil
					this.hero.tombstone_respawn_animation = nil
				end

				SU.y_hero_death_and_respawn_kr5(store, this)

				this.hero.tombstone_show_time = old_tombstone_time
				this.hero.tombstone_respawn_animation = old_tombstone_respawn_animation

				U.animation_start(this, this.idle_flip.last_animation, nil, store.tick_ts, this.idle_flip.loop, nil, true)

				this.hero.tombstone_show_time = old_tombstone_time
			else
				SU.y_soldier_death(store, this)

				return
			end
		end

		if this.is_clone and store.tick_ts - spawn_ts > this.reinforcement.duration then
			if this.health.hp > 0 then
				this.reinforcement.hp_before_timeout = this.health.hp
			end

			this.health.hp = 0
			this.ui.can_click = false

			SU.remove_modifiers(store, this)
			SU.y_soldier_death(store, this)

			return
		end

		while this.nav_rally.new do
			if y_drakkan_new_rally(store, this) then
				goto label_402_2
			end
		end

		if not this.is_clone and SU.hero_level_up(store, this) then
			U.y_animation_play(this, "lvl_up", nil, store.tick_ts, 1)
		end

		if ua and not ua.disabled and store.tick_ts - ua.ts > ua.cooldown then
			local a = ua
			local start_ts = store.tick_ts
			local enemies = find_targets_ultimate(a)

			if not enemies or #enemies < a.min_targets then
				SU.delay_attack(store, a, fts(10))
			else
				U.animation_start(this, a.animation, nil, store.tick_ts, false)
				S:queue(a.sound_cast)
				S:queue(a.sound_taunt)

				if SU.y_hero_wait(store, this, a.cast_time) then
					S:stop(a.sound_cast)

					goto label_402_2
				end

				local shots = a.shots
				local shuffled = false

				for i = 1, shots do
					local e

					if shots > #enemies then
						if not shuffled and i > #enemies then
							shuffled = true

							shuffle_table(enemies)
						end

						i = i % #enemies

						if i == 0 then
							i = 1
						end
					end

					local e = enemies[i]

					spawn_ultimate_bullet(a, e)
					U.y_wait(store, U.frandom(a.delay_between_shots_min, a.delay_between_shots_max))
				end

				a.ts = store.tick_ts

				if not this.is_clone then
					SU.hero_gain_xp_from_skill(this, su)
				end

				while not U.animation_finished(this, 1) do
					if SU.soldier_interrupted(this) then
						goto label_402_2
					end

					coroutine.yield()
				end

				U.animation_start(this, "walk", nil, store.tick_ts, true)

				goto label_402_2
			end
		end

		if sca and not sca.disabled and store.tick_ts - sca.ts > sca.cooldown then
			local a = sca
			local start_ts = store.tick_ts
			local enemies = U.find_enemies_in_range(store.entities, this.pos, 0, sca.range, a.vis_flags, a.vis_bans)

			if not enemies or #enemies == 0 then
				SU.delay_attack(store, a, fts(10))
			else
				U.animation_start(this, a.animation, nil, store.tick_ts)
				U.y_wait(store, sca.cast_time)
				S:queue(a.sound)

				local dd = E:create_entity(sca.clone_t)

				dd.pos.x, dd.pos.y = this.pos.x + sca.spawn_offset.x, this.pos.y + sca.spawn_offset.y
				dd.nav_rally.center = V.vv(0)
				dd.is_clone = true
				dd.render.sprites[1].flip_x = this.render.sprites[1].flip_x

				queue_insert(store, dd)
				SU.hero_gain_xp_from_skill(this, sc)

				sca.ts = store.tick_ts

				while not U.animation_finished(this, 1) do
					if SU.soldier_interrupted(this) then
						break
					end

					coroutine.yield()
				end

				goto label_402_2
			end
		end

		if sba and not sba.disabled and store.tick_ts - sba.ts > sba.cooldown then
			local a = sba
			local start_ts = store.tick_ts
			local pos_offset = v(this.pos.x + a.ignore_offset.x, this.pos.y + a.ignore_offset.y)
			local target, enemies, _ = U.find_foremost_enemy(store.entities, this.pos, 0, a.max_range, a.node_prediction, a.vis_flags, a.vis_bans)

			if not enemies or #enemies < a.min_targets then
				SU.delay_attack(store, a, fts(10))
			else
				U.animation_start(this, a.animation_lower, nil, store.tick_ts)
				S:queue(a.sound)
				U.y_wait(store, a.wait_to_lower)

				this.render.sprites[1].z = Z_OBJECTS
				this._current_height = this.flight_height

				U.y_ease_key(store, this, "_current_height", this.flight_height, a.floor_height, a.lower_duration, a.ease_down, function(dt, p)
					this.drag_line_origin_offset.y = this._current_height
					this.render.sprites[1].offset.y = this._current_height
					this.health_bar.offset.y = this._current_height + 80
					this.ui.click_rect.pos.y = this._current_height - 20
					this.unit.hit_offset.y = this._current_height + 10
					this.unit.mod_offset.y = this._current_height + 10
				end)

				local dmg_aura = E:create_entity(a.aura_t)

				dmg_aura.pos.x, dmg_aura.pos.y = this.pos.x, this.pos.y

				queue_insert(store, dmg_aura)
				U.y_animation_wait(this, 1)

				this._current_height = this.flight_height
				this.drag_line_origin_offset.y = this._current_height
				this.render.sprites[1].offset.y = this._current_height
				this.health_bar.offset.y = this._current_height + 80
				this.ui.click_rect.pos.y = this._current_height - 20
				this.unit.hit_offset.y = this._current_height + 10
				this.unit.mod_offset.y = this._current_height + 10

				U.animation_start(this, a.animation_rise, nil, store.tick_ts)

				this.render.sprites[1].z = Z_FLYING_HEROES
				sba.ts = store.tick_ts

				SU.hero_gain_xp_from_skill(this, sb)

				this.nav_rally.new = nil

				while not U.animation_finished(this, 1) do
					if SU.soldier_interrupted(this) then
						break
					end

					coroutine.yield()
				end

				goto label_402_2
			end
		end

		if saa and not saa.disabled and store.tick_ts - saa.ts > saa.cooldown then
			local a = saa
			local start_ts = store.tick_ts
			local pos_offset = v(this.pos.x + a.ignore_offset.x, this.pos.y + a.ignore_offset.y)
			local target, targets, _ = U.find_foremost_enemy(store.entities, this.pos, a.min_range, a.max_range, nil, a.vis_flags, a.vis_bans, function(e, o)
				return GR:cell_is(e.pos.x, e.pos.y, bor(TERRAIN_LAND, TERRAIN_ICE)) and V.dist2(pos_offset.x, pos_offset.y, e.pos.x, e.pos.y) > a.radius * a.radius
			end)
			local targets_that_do_magic = targets and table.filter(targets, function(k, v)
				return v.enemy.has_magic
			end) or {}

			if not targets or #targets < a.min_targets and #targets_that_do_magic == 0 then
				SU.delay_attack(store, a, fts(10))

				goto label_402_0
			end

			local target_pos = target.pos

			this.render.sprites[1].flip_x = target_pos.x < this.pos.x

			U.animation_start(this, a.animation, nil, store.tick_ts, false)
			S:queue(a.sound, {
				delay = fts(14)
			})
			S:queue(a.sound_taunt)

			if SU.y_hero_wait(store, this, a.cast_time) then
				goto label_402_2
			end

			if a.shared_cooldown then
				for _, aa in pairs(this.melee.attacks) do
					if aa ~= a and aa.shared_cooldown then
						aa.ts = a.ts
					end
				end
			end

			local d = this.render.sprites[1].flip_x and -1 or 1
			local offset = V.v(a.offset.x * d, a.offset.y)
			local fx = E:create_entity(a.fx_t)

			fx.pos = V.v(this.pos.x + offset.x, this.pos.y + this.flight_height + offset.y)
			fx.render.sprites[1].ts = store.tick_ts
			fx.render.sprites[1].r = V.angleTo(target_pos.x - fx.pos.x, target_pos.y - fx.pos.y)
			fx.render.sprites[1].scale = V.v(km.clamp(a.min_scale_x, 1.5, V.dist(fx.pos.x, fx.pos.y, target_pos.x, target_pos.y) / a.image_width), 1)

			queue_insert(store, fx)
			U.y_wait(store, a.hit_time)
			S:queue(a.sound_hit)

			local au = E:create_entity(a.aura_t)

			au.render.sprites[1].ts = store.tick_ts
			au.pos = V.vclone(target_pos)

			queue_insert(store, au)

			a.ts = store.tick_ts

			SU.hero_gain_xp_from_skill(this, sa)

			this.nav_rally.new = nil

			while not U.animation_finished(this, 1) do
				if SU.soldier_interrupted(this) then
					goto label_402_2
				end

				coroutine.yield()
			end

			U.animation_start(this, "walk", nil, store.tick_ts, true)

			goto label_402_2
		end

		::label_402_0::

		if store.tick_ts - aa.ts >= aa.cooldown then
			local pos_offset = v(this.pos.x + aa.ignore_offset.x, this.pos.y + aa.ignore_offset.y)
			local _, targets, __ = U.find_foremost_enemy(store.entities, this.pos, aa.min_range, aa.max_range, 0, aa.vis_flags, aa.vis_bans, function(e)
				return V.dist2(pos_offset.x, pos_offset.y, e.pos.x, e.pos.y) > aa.radius * aa.radius
			end)

			if not targets or #targets == 0 then
				-- block empty
			else
				if not this.is_clone then
					brk, sta = y_hero_ranged_attacks(store, this)
				else
					brk, sta = SU.y_soldier_ranged_attacks(store, this)
				end

				U.set_destination(this, this.pos)

				local target = targets[1]
				local start_ts = store.tick_ts
				local start_fx, b, bullet_start_offset
				local node_offset = P:predict_enemy_node_advance(target, aa.node_prediction)
				local t_pos = P:node_pos(target.nav_path.pi, target.nav_path.spi, target.nav_path.ni + node_offset)
				local an, af, ai = U.animation_name_facing_point(this, aa.animation, t_pos)

				U.animation_start(this, an, af, store.tick_ts)

				while store.tick_ts - start_ts < aa.shoot_time do
					if this.unit.is_stunned or this.health.dead or this.nav_rally and this.nav_rally.new then
						goto label_402_1
					end

					coroutine.yield()
				end

				S:queue(aa.sound)

				b = E:create_entity(aa.bullet)
				b.bullet.target_id = target.id
				b.bullet.source_id = this.id
				b.bullet.xp_dest_id = this.id
				b.pos = V.vclone(this.pos)
				bullet_start_offset = v(0, 0)

				if aa.bullet_start_offset and #aa.bullet_start_offset == 2 then
					local offset_index = af and 2 or 1

					bullet_start_offset = aa.bullet_start_offset[offset_index]
				end

				b.pos.x = b.pos.x + (af and -1 or 1) * bullet_start_offset.x
				b.pos.y = b.pos.y + bullet_start_offset.y
				b.bullet.from = V.vclone(b.pos)

				if b.bullet.ignore_hit_offset then
					b.bullet.to = V.v(target.pos.x, target.pos.y)
				else
					b.bullet.to = V.v(target.pos.x + target.unit.hit_offset.x, target.pos.y + target.unit.hit_offset.y)
				end

				if b.bullet.use_unit_damage_factor then
					b.bullet.damage_factor = this.unit.damage_factor
				end

				queue_insert(store, b)

				if not this.is_clone and aa.xp_from_skill then
					SU.hero_gain_xp_from_skill(this, this.hero.skills[aa.xp_from_skill])
				end

				aa.ts = start_ts

				while not U.animation_finished(this) do
					if this.unit.is_stunned or this.health.dead or this.nav_rally and this.nav_rally.new then
						goto label_402_1
					end

					coroutine.yield()
				end

				aa.ts = start_ts

				U.animation_start(this, this.idle_flip.last_animation, nil, store.tick_ts, this.idle_flip.loop, nil, true)

				::label_402_1::

				if start_fx then
					start_fx.render.sprites[1].hidden = true
				end

				this.render.sprites[1].ts = store.tick_ts
			end
		end

		SU.soldier_idle(store, this)
		SU.soldier_regen(store, this)

		::label_402_2::

		coroutine.yield()
	end
end

scripts.decal_drakkan_tombstone = {}

function scripts.decal_drakkan_tombstone.update(this, store, script)
	U.y_animation_play(this, this.animation_in, nil, store.tick_ts, 1, 1)
	U.animation_start(this, this.animation_in, nil, store.tick_ts, nil, 1)

	while true do
		coroutine.yield()
	end
end

scripts.soldier_drakkan_clone = {}

function scripts.soldier_drakkan_clone.get_info(this)
	local a = this.ranged.attacks[1]
	local b = E:get_template(a.bullet)
	local min, max = b.bullet.damage_min, b.bullet.damage_max

	min, max = min * this.unit.damage_factor, max * this.unit.damage_factor
	min, max = math.ceil(min), math.ceil(max)

	return {
		type = STATS_TYPE_SOLDIER,
		hp = this.health.hp,
		hp_max = this.health.hp_max,
		damage_min = min,
		damage_max = max,
		damage_type = b.bullet.damage_type,
		damage_icon = this.info.damage_icon,
		armor = this.health.armor
	}
end

scripts.bullet_drakkan_ultimate = {}

function scripts.bullet_drakkan_ultimate.update(this, store, script)
	local b = this.bullet
	local dist_y = math.abs(b.from.y - b.to.y)
	local mspeed = dist_y / b.travel_time - b.acceleration * b.travel_time * 0.5
	local particle = E:create_entity(b.particles_name)

	particle.particle_system.track_id = this.id

	queue_insert(store, particle)

	while V.dist(this.pos.x, this.pos.y, b.to.x, b.to.y) > mspeed * store.tick_length do
		mspeed = mspeed + 1 / FPS * b.acceleration
		mspeed = km.clamp(b.min_speed, b.max_speed, mspeed)
		b.speed.x, b.speed.y = V.mul(mspeed, V.normalize(b.to.x - this.pos.x, b.to.y - this.pos.y))
		this.pos.x, this.pos.y = this.pos.x + b.speed.x * store.tick_length, this.pos.y + b.speed.y * store.tick_length
		this.render.sprites[1].r = V.angleTo(b.to.x - this.pos.x, b.to.y - this.pos.y)

		coroutine.yield()
	end

	this.pos.x, this.pos.y = b.to.x, b.to.y
	particle.particle_system.source_lifetime = 0

	local enemies = {}

	for _, v in pairs(store.entities) do
		if v.enemy and v.vis and v.health and not v.health.dead and band(v.vis.flags, b.damage_bans) == 0 and band(v.vis.bans, b.damage_flags) == 0 and U.is_inside_ellipse(v.pos, b.to, b.damage_radius) then
			table.insert(enemies, v)
		elseif v.template_name == "hero_lava" and v.health.hp > 0 and U.is_inside_ellipse(v.pos, b.to, b.damage_radius) then
			v._death_by_ultimate = true
			v.health.hp = 0
		end
	end

	local damage_value = math.ceil(b.damage_factor * math.random(b.damage_min, b.damage_max))

	for _, enemy in ipairs(enemies) do
		local d = E:create_entity("damage")

		d.source_id = this.id
		d.target_id = enemy.id
		d.value = damage_value
		d.damage_type = b.damage_type

		queue_damage(store, d)
	end

	S:queue(this.sound_events.hit)

	local cell_type = GR:cell_type(b.to.x, b.to.y)

	if band(cell_type, TERRAIN_WATER) ~= 0 then
		local fx = E:create_entity("fx_explosion_water")

		fx.pos.x, fx.pos.y = b.to.x, b.to.y
		fx.render.sprites[1].ts = store.tick_ts

		queue_insert(store, fx)

		if this.scorch_earth then
			local scorched = E:create_entity("power_scorched_water")

			scorched.pos.x, scorched.pos.y = b.to.x, b.to.y

			for i = 1, #scorched.render.sprites do
				scorched.render.sprites[i].ts = store.tick_ts
			end

			queue_insert(store, scorched)
		end
	else
		if b.hit_decal then
			local decal = E:create_entity(b.hit_decal)

			decal.pos.x, decal.pos.y = b.to.x, b.to.y
			decal.render.sprites[1].ts = store.tick_ts

			queue_insert(store, decal)
		end

		if b.hit_fx then
			local fx = E:create_entity(b.hit_fx)

			fx.pos.x, fx.pos.y = b.to.x, b.to.y
			fx.render.sprites[1].ts = store.tick_ts

			queue_insert(store, fx)
		end
	end

	queue_remove(store, this)
end

scripts.hero_myriath = {}

function scripts.hero_myriath.can_dodge(store, this, ranged_attack, attack, enemy)
	local skb = this.timed_attacks.list[2]

	if skb and not skb.disabled and store.tick_ts - skb.ts > skb.cooldown then
		if enemy and enemy.health and not enemy.health.dead then
			local skill = this.timed_attacks.list[2]
			local enp = enemy.nav_path
			local new_ni = enp.ni
			local node_limit = math.floor(skill.min_distance_from_end / P.average_node_dist)
			local node_jump = math.floor(skill.distance / P.average_node_dist)
			local nodes_to_goal = P:nodes_to_goal(enp)

			if node_limit < nodes_to_goal then
				new_ni = new_ni + math.min(nodes_to_goal - 1, node_jump)

				local new_pos = P:node_pos(enp.pi, enp.spi, new_ni)

				if band(GR:cell_type(new_pos.x, new_pos.y), TERRAIN_NOWALK) == 0 then
					this.dodge.new_pos = new_pos

					return true
				else
					return false
				end
			end
		end
	else
		return math.random() <= this.dodge.upg_d_chance
	end

	return false
end

function scripts.hero_myriath.level_up(this, store, initial)
	if not initial then
		S:queue(this.sound_events.level_up)
	end

	local hl = this.hero.level
	local ls = this.hero.level_stats

	this.health.hp_max = ls.hp_max[hl]
	this.regen.health = ls.regen_health[hl]
	this.health.armor = ls.armor[hl]
	this.melee.attacks[1].damage_min = ls.melee_damage_min[hl]
	this.melee.attacks[1].damage_max = ls.melee_damage_max[hl]
	this.melee.attacks[2].damage_min = ls.melee_damage_min[hl]
	this.melee.attacks[2].damage_max = ls.melee_damage_max[hl]

	local bt = E:get_template(this.ranged.attacks[1].bullet)

	bt.bullet.damage_min = ls.ranged_damage_min[hl]
	bt.bullet.damage_max = ls.ranged_damage_max[hl]
	this.health.hp = this.health.hp_max
	this.hero.melee_active_status = {}

	for index, attack in ipairs(this.melee.attacks) do
		this.hero.melee_active_status[index] = attack.disabled
	end
end

function scripts.hero_myriath.insert(this, store)
	this.hero.fn_level_up(this, store, true)

	this.melee.order = U.attack_order(this.melee.attacks)
	this.ranged.order = U.attack_order(this.ranged.attacks)
	this.timed_attacks.list[4].disabled = not this.hero.skills.ultimate.active

	return true
end

function scripts.hero_myriath.update(this, store)
	local h = this.health
	local brk, sta
	local old_tombstone_time = this.hero.tombstone_show_time
	local old_tombstone_respawn_animation = this.hero.tombstone_respawn_animation

	this.health_bar.hidden = false

	local clones_ids = {}
	local t1 = this.hero.skills.talent_1
	local t2 = this.hero.skills.talent_2
	local ska = this.timed_attacks.list[1]
	local pow_a = this.hero.skills.skill_a
	local ska_bullet = E:get_template(ska.bullet).bullet
	local skb = this.timed_attacks.list[2]
	local pow_b = this.hero.skills.skill_b
	local skc = this.timed_attacks.list[3]
	local pow_c = this.hero.skills.skill_c
	local ult = this.timed_attacks.list[4]
	local ult_start_cd = store.wave_group_number == 0
	local ultimate = this.hero.skills.ultimate

	if ska then
		ska.ts = store.tick_ts - ska.cooldown
	end

	if skb then
		skb.ts = store.tick_ts - skb.cooldown
	end

	if skc then
		skc.ts = store.tick_ts - skc.cooldown
	end

	if ult then
		ult.ts = store.tick_ts - ult.cooldown
	end

	if not t1.disabled then
		local clone_t = E:get_template("soldier_myriath_clone")

		clone_t.health.hp_max = clone_t.health.hp_max + t1.health_inc
		clone_t.duration = clone_t.duration + t1.duration_inc
	end

	if not t2.disabled then
		local clone_t = E:get_template("soldier_myriath_clone")

		clone_t.aura_explosion = t2.aura
	end

	local function y_myriath_new_rally(store, this)
		local r = this.nav_rally
		local vis_bans = this.vis.bans

		this.vis.bans = F_ALL
		this.health.ignore_damage = true
		r.new = false

		U.unblock_target(store, this)

		local an, af = U.animation_name_facing_point(this, "walk_in", r.pos)

		U.animation_start(this, an, af, store.tick_ts, 1, nil)

		local first_time = true

		::label_421_0::

		S:queue(this.sound_events.change_rally_point)

		if not first_time then
			local an, af = U.animation_name_facing_point(this, "walk", r.pos)

			U.animation_start(this, an, af, store.tick_ts, true, 1, true)
		end

		local dest = r.pos
		local n = this.nav_grid

		while not V.veq(this.pos, dest) do
			local w = table.remove(n.waypoints, 1) or dest

			U.set_destination(this, w)

			local runs = this.render.sprites[1].runs

			while not this.motion.arrived do
				if r.new then
					r.new = false
					first_time = false

					goto label_421_0
				end

				U.walk(this, store.tick_length)
				coroutine.yield()

				this.motion.speed.x, this.motion.speed.y = 0, 0

				if this.render.sprites[1].name == "walk_in" and U.animation_finished(this) then
					local an, af = U.animation_name_facing_point(this, "walk", this.motion.dest)

					U.animation_start(this, an, af, store.tick_ts, true, 1, true)

					runs = this.render.sprites[1].runs
				end
			end
		end

		U.y_animation_play(this, "walk_out", nil, store.tick_ts)

		this.vis.bans = vis_bans
		this.health.ignore_damage = false

		return interrupt
	end

	local function add_clone_id(id)
		table.insert(clones_ids, id)
	end

	local function remove_clone_id(id)
		table.remove(clones_ids, index_at(clones_ids, id))
	end

	local function cant_do_action()
		return SU.soldier_interrupted(this)
	end

	local function find_most_populated_path(enemies, min_enemies)
		local paths_count = {}
		local found_paths = {}

		for k, v in pairs(enemies) do
			if not table.contains(found_paths, v.nav_path.pi) then
				table.insert(found_paths, v.nav_path.pi)
				table.insert(paths_count, {
					v.nav_path.pi,
					1
				})
			else
				local i = index_at(paths_count, v, function(tv, iv)
					return iv.nav_path.pi == tv[1]
				end)

				paths_count[i][2] = paths_count[i][2] + 1
			end
		end

		table.sort(paths_count, function(v1, v2)
			return v1[2] > v2[2]
		end)

		return paths_count
	end

	local function sort_paths_by_distance(paths, min_distance)
		local available_paths = table.filter(paths, function(k, v)
			local count = 0
			local n = P:nearest_nodes(this.pos.x, this.pos.y, {
				v[1]
			})[1][3]
			local first_node = P:get_visible_start_node(v)

			for i = 0, min_distance do
				if first_node <= n - i then
					return true
				end

				if P:is_node_valid(v, first_node < n - i and n - i or first_node, 0) and not table.contains(store.level.ignore_walk_backwards_paths, v[1]) then
					count = count + 1

					if count >= min_distance then
						return true
					end
				else
					return false
				end
			end
		end)

		return available_paths
	end

	this.add_clone_id = add_clone_id
	this.remove_clone_id = remove_clone_id

	while true do
		if ult_start_cd and store.wave_group_number > 0 then
			ult_start_cd = false
			ult.ts = store.tick_ts
		end

		if h.dead then
			if band(h.last_damage_types, bor(DAMAGE_EAT)) ~= 0 then
				this.hero.tombstone_show_time = nil
				this.hero.tombstone_respawn_animation = nil
			end

			SU.y_hero_death_and_respawn_kr5(store, this)

			this.hero.tombstone_show_time = old_tombstone_time
			this.hero.tombstone_respawn_animation = old_tombstone_respawn_animation
		end

		if this.unit.is_stunned then
			SU.soldier_idle(store, this)
		else
			while this.nav_rally.new do
				if y_myriath_new_rally(store, this) then
					goto label_420_1
				end
			end

			if ult and not ult.disabled and store.tick_ts - ult.ts > ult.cooldown then
				local nearest = P:nearest_nodes(this.pos.x, this.pos.y)
				local t, targets, _ = U.find_foremost_enemy(store.entities, this.pos, ult.min_detection_range, ult.max_detection_range, ult.prediction, 0, ult.bans, function(v, o)
					for _, p in pairs(nearest) do
						if p[1] == v.nav_path.pi and v.nav_path.ni < p[3] then
							return true
						else
							return false
						end
					end
				end)

				if not targets or #targets < ult.min_targets then
					SU.delay_attack(store, ult, fts(10))

					goto label_420_0
				end

				local paths = find_most_populated_path(targets, 0)

				paths = sort_paths_by_distance(paths, ult.distance)

				if #paths == 0 then
					SU.delay_attack(store, ult, fts(10))

					goto label_420_0
				end

				local n = P:nearest_nodes(this.pos.x, this.pos.y, {
					paths[1][1]
				})
				local pos = P:node_pos(n[1][1], n[1][2], n[1][3])

				U.animation_start(this, ult.animation, this.render.sprites[1].flip_x, store.tick_ts, false, 1)
				S:queue(ult.sound_taunt)

				if SU.y_hero_wait(store, this, ult.cast_time) then
					goto label_420_1
				end

				S:queue(ult.sound_cast)

				for i = 1, 3 do
					local s = E:create_entity(ult.soldier)

					s.pos = V.vclone(this.pos)
						s.hero_myriath_id = this.id
					s.pi = n[1][1]
					s.spi = i
					s.ni = n[1][3] + math.random(-4, 4)

					queue_insert(store, s)
					U.y_wait(store, fts(3))
				end

				SU.hero_gain_xp_from_skill(this, ultimate)
				U.y_animation_wait(this)

				ult.ts = store.tick_ts

				goto label_420_1
			end

			::label_420_0::

			if skb and not skb.disabled and store.tick_ts - skb.ts > skb.cooldown and this.vis.bans ~= F_ALL and this.dodge.new_pos then
				local enemy = store.entities[this.soldier.target_id]

				if not enemy then
					this.dodge.new_pos = nil
				else
					local enemy_pos = enemy.pos
					local enemy_id = enemy.id
					local new_pos = this.dodge.new_pos

					this.dodge.new_pos = nil

					U.animation_start(this, skb.animation_out, nil, store.tick_ts, false)

					if SU.y_hero_wait(store, this, fts(6)) then
						goto label_420_1
					end

					U.unblock_target(store, this)

					local bans = this.vis.bans

					this.vis.bans = F_ALL

					SU.hide_modifiers(store, this, true)
					SU.hide_auras(store, this, true)
					S:queue(skb.sound)

					local clone = E:create_entity(ska.clone)

					clone.pos.x, clone.pos.y = this.pos.x, this.pos.y
					clone.hero_myriath_id = this.id
					clone.target_block = enemy
					clone.animation_spawn = "in"
					clone.render.sprites[1].flip_x = this.render.sprites[1].flip_x

					queue_insert(store, clone)
					U.y_animation_wait(this)

					this.pos.x, this.pos.y = new_pos.x, new_pos.y

					if not this.nav_rally.new then
						this.nav_rally.center = V.vclone(this.pos)
						this.nav_rally.pos = V.vclone(this.pos)
					end

					SU.hero_gain_xp_from_skill(this, pow_b)
					U.animation_start(this, skb.animation_in, nil, store.tick_ts, false, 1)
					U.y_wait(store, fts(3))
					SU.y_hero_animation_wait(this)

					this.vis.bans = bans
					this.vis._bans = nil

					SU.show_modifiers(store, this, true)
					SU.show_auras(store, this, true)
					U.y_animation_wait(this)

					skb.ts = store.tick_ts

					goto label_420_1
				end
			end

			if skc and not skc.disabled and store.tick_ts - skc.ts > skc.cooldown then
				local clones_cast = true

				for _, id in ipairs(clones_ids) do
					if store.entities[id] and store.entities[id].soldier and store.entities[id].soldier.target_id ~= nil then
						clones_cast = true
					end
				end

				if not this.soldier.target_id or this.soldier.target_id ~= nil and not this.motion.arrived or store.entities[this.soldier.target_id] and store.entities[this.soldier.target_id].health and store.entities[this.soldier.target_id].health.dead or not clones_cast then
					SU.delay_attack(store, skc, fts(10))
				else
					h.ignore_damage = true
					this.health_bar.hidden = true

					S:queue(skc.sound_cast)
					U.animation_start(this, skc.animation_in, this.render.sprites[1].flip_x, store.tick_ts, false, 1)

					for _, id in ipairs(clones_ids) do
						if store.entities[id] then
							store.entities[id].cast_mirror_slash = true
						end
					end

					SU.y_hero_animation_wait(this)

					if cant_do_action() then
						skc.ts = store.tick_ts

						SU.hero_gain_xp_from_skill(this, pow_c)

						h.ignore_damage = false
						this.health_bar.hidden = false

						goto label_420_1
					end

					local target = store.entities[this.soldier.target_id]
					local original_pos = V.vclone(this.pos)

					if not target or target.health.dead or this.soldier.target_id == nil then
						-- block empty
					else
						this.pos = V.vclone(target.pos)

						U.animation_start(this, skc.animation, this.render.sprites[1].flip_x, store.tick_ts, false, 1)
						S:queue(skc.sound_hit)

						for k, v in pairs(skc.hit_times) do
							U.y_wait(store, v)

							if target then
								local d = E:create_entity("damage")

								d.source_id = this.id
								d.target_id = this.soldier.target_id
								d.track_kills = this.track_kills ~= nil
								d.track_damage = skc.track_damage
								d.pop = skc.pop
								d.pop_chance = skc.pop_chance
								d.pop_conds = skc.pop_conds
								d.damage_type = skc.damage_type
								d.value = math.ceil(this.unit.damage_factor * math.random(skc.damage_min, skc.damage_max))

								queue_damage(store, d)
							end

							local fx = E:create_entity(skc.hit_fx)

							fx.pos.x, fx.pos.y = V.vclone(this.pos).x + skc.hit_offset.x, V.vclone(this.pos).y + skc.hit_offset.y
							fx.render.sprites[1].ts = store.tick_ts

							queue_insert(store, fx)
						end

						U.y_wait(store, fts(3))
					end

					this.pos = original_pos

					U.animation_start(this, skc.animation_out, this.render.sprites[1].flip_x, store.tick_ts, false, 1)
					U.y_wait(store, fts(3))
					SU.y_hero_animation_wait(this)

					h.ignore_damage = false
					this.health_bar.hidden = false

					SU.hero_gain_xp_from_skill(this, pow_c)

					skc.ts = store.tick_ts

					goto label_420_1
				end
			end

			if ska and not ska.disabled and store.tick_ts - ska.ts > ska.cooldown then
				local target, targets, _ = U.find_foremost_enemy(store.entities, this.pos, ska.min_range, ska.max_range, ska.node_prediction, ska.vis_flags, ska.vis_bans, function(e)
					return band(GR:cell_type(e.pos.x, e.pos.y), TERRAIN_NOWALK) == 0
				end)

				if not target or #targets == 0 then
					SU.delay_attack(store, ska, fts(10))
				else
					this.render.sprites[1].flip_x = target.pos.x < this.pos.x

					U.animation_start(this, ska.animation, nil, store.tick_ts, false)
					U.y_wait(store, fts(19), cant_do_action)

					if cant_do_action() then
						goto label_420_1
					end

					local flip = target.render.sprites[1].flip_x and -1 or 1
					local bullet = E:create_entity(ska.bullet)

					bullet.pos = V.v(this.pos.x, this.pos.y)
					bullet.bullet.from = V.vclone(bullet.pos)
					bullet.bullet.to = P:predict_enemy_pos(target, ska_bullet.flight_time)
					bullet.bullet.to.x = bullet.bullet.to.x + (target.enemy.melee_slot.x + this.soldier.melee_slot_offset.x) * flip
					bullet.bullet.target_id = target.id
					bullet.bullet.source_id = this.id

					queue_insert(store, bullet)
					S:queue(ska.sound)
					SU.y_hero_animation_wait(this)
					SU.hero_gain_xp_from_skill(this, pow_a)

					ska.ts = store.tick_ts

					goto label_420_1
				end
			end

			if SU.hero_level_up(store, this) then
				U.y_animation_play(this, "lvl_up", nil, store.tick_ts, 1)
			end

			brk, sta = y_hero_melee_block_and_attacks(store, this)

			if sta == A_DONE then
				U.animation_start(this, "idle", nil, store.tick_ts, true, 1, true)
			elseif brk or sta ~= A_NO_TARGET then
				-- block empty
			elseif SU.soldier_go_back_step(store, this) then
				-- block empty
			else
				brk, sta = y_hero_ranged_attacks(store, this)

				if brk then
					-- block empty
				else
					SU.soldier_idle(store, this)
					SU.soldier_regen(store, this)
				end
			end
		end

		::label_420_1::

		this.dodge.active = false

		coroutine.yield()
	end
end

scripts.soldier_myriath_clone = {}

function scripts.soldier_myriath_clone.insert(this, store)
	this.hero_myriath = store.entities[this.hero_myriath_id]

	if not this.hero_myriath or not (this.hero_myriath.template_name == "hero_myriath" or this.hero_myriath.template_name == "hero_myriath_2") then
		return false
	end

	this.melee.attacks[1].damage_min = this.hero_myriath.melee.attacks[1].damage_min * this.basic_melee_attack_ptg
	this.melee.attacks[1].damage_max = this.hero_myriath.melee.attacks[1].damage_max * this.basic_melee_attack_ptg

	local bullet_myriath = E:get_template(this.hero_myriath.ranged.attacks[1].bullet)
	local bullet_clone = E:get_template(this.ranged.attacks[1].bullet)

	bullet_clone.bullet.damage_min = bullet_myriath.bullet.damage_min * this.basic_ranged_attack_ptg
	bullet_clone.bullet.damage_max = bullet_myriath.bullet.damage_max * this.basic_ranged_attack_ptg
	this.timed_attacks.list[1].damage_min = this.hero_myriath.timed_attacks.list[3].damage_min * this.skill_c_attack_ptg
	this.timed_attacks.list[1].damage_max = this.hero_myriath.timed_attacks.list[3].damage_max * this.skill_c_attack_ptg
	this.nav_rally.pos = V.vclone(this.pos)

	if this.target_block then
		U.block_enemy(store, this, this.target_block)

		this.render.sprites[1].flip_x = not this.target_block.render.sprites[1].flip_x
	else
		this.render.sprites[1].flip_x = this.hero_myriath.render.sprites[1].flip_x
	end

	this.skc = this.hero_myriath.timed_attacks.list[3]

	return true
end

function scripts.soldier_myriath_clone.update(this, store)
	local spawn_ts = store.tick_ts
	local h = this.health
	local brk, sta

	this.health_bar.hidden = false

	local skc = this.timed_attacks.list[1]

	U.animation_start(this, this.animation_spawn, nil, store.tick_ts, false)

	if string.find(this.animation_spawn, "ultimate") then
		U.y_wait(store, this.animation_spawn_hit_time, nil)

		if this.animation_spawn_hit_fx then
			local sfx = E:create_entity(this.animation_spawn_hit_fx)

			sfx.pos.x, sfx.pos.y = V.vclone(this.pos).x + this.melee.attacks[1].hit_offset.x * (this.render.sprites[1].flip_x and -1 or 1), V.vclone(this.pos).y + this.melee.attacks[1].hit_offset.y
			sfx.render.sprites[1].ts = store.tick_ts

			queue_insert(store, sfx)
		end
	end

	U.y_animation_wait(this, 1, 1)
	this.hero_myriath.add_clone_id(this.id)

	while true do
		if h.dead or store.tick_ts - spawn_ts > this.duration then
			local sfx = this.death_sfx
			local death = this.death_anim

			if this.aura_explosion then
				local aura = E:create_entity(this.aura_explosion)

				aura.source_id = this.id
				aura.pos = V.vclone(this.pos)

				queue_insert(store, aura)

				sfx = this.death_explosion_sfx
				death = this.death_anim_explosion
			end

			this.hero_myriath.remove_clone_id(this.id)

			this.ui.can_click = false

			S:queue(sfx)
			SU.remove_modifiers(store, this)
			U.unblock_target(store, this)
			U.y_animation_play(this, death, this.render.sprites[1].flip_x, store.tick_ts, 1, 1)
			queue_remove(store, this)

			return
		end

		if this.unit.is_stunned then
			SU.soldier_idle(store, this)
		else
			if not skc or not this.cast_mirror_slash or this.soldier.target_id == nil or not store.entities[this.soldier.target_id] or store.entities[this.soldier.target_id].health.dead then
				-- block empty
			else
				this.cast_mirror_slash = false
				this.health.ignore_damage = true
				this.health_bar.hidden = true

				U.y_wait(store, fts(0.1))
				S:queue(skc.sound_cast)
				U.animation_start(this, skc.animation_in, this.render.sprites[1].flip_x, store.tick_ts, false, 1)
				U.y_animation_wait(this)

				local flip, posx, posy
				local original_pos = V.vclone(this.pos)
				local target = store.entities[this.soldier.target_id]

				if not target or target.health.dead or this.soldier.target_id == nil then
					-- block empty
				else
					flip = target.render.sprites[1].flip_x and -1 or 1
					posx = this.motion.arrived and V.vclone(this.pos).x or (V.vclone(target.pos).x + target.enemy.melee_slot.x + this.soldier.melee_slot_offset.x) * flip
					posy = this.motion.arrived and V.vclone(this.pos).y or V.vclone(target.pos).y + target.enemy.melee_slot.y + this.soldier.melee_slot_offset.y
					original_pos = v(posx, posy)
					this.pos = V.vclone(target.pos)

					U.animation_start(this, skc.animation, this.render.sprites[1].flip_x, store.tick_ts, false, 1)
					S:queue(skc.sound_hit)

					for k, v in pairs(skc.hit_times) do
						U.y_wait(store, v)

						if target then
							local d = E:create_entity("damage")

							d.source_id = this.id
							d.target_id = this.soldier.target_id
							d.track_kills = this.track_kills ~= nil
							d.track_damage = skc.track_damage
							d.pop = skc.pop
							d.pop_chance = skc.pop_chance
							d.pop_conds = skc.pop_conds
							d.damage_type = skc.damage_type
							d.value = math.ceil(this.unit.damage_factor * math.random(skc.damage_min, skc.damage_max))

							queue_damage(store, d)
						end

						local fx = E:create_entity(skc.hit_fx)

						fx.pos.x, fx.pos.y = V.vclone(this.pos).x + skc.hit_offset.x, V.vclone(this.pos).y + skc.hit_offset.y
						fx.render.sprites[1].ts = store.tick_ts

						queue_insert(store, fx)
					end
				end

				U.y_wait(store, fts(6))

				this.pos = original_pos

				U.y_animation_play(this, skc.animation_out, this.render.sprites[1].flip_x, store.tick_ts, 1, 1)

				this.health.ignore_damage = false
				this.health_bar.hidden = false
			end

			brk, sta = y_hero_melee_block_and_attacks(store, this)

			if sta == A_DONE then
				U.animation_start(this, "idle", nil, store.tick_ts, true, 1, true)
			elseif brk or sta ~= A_NO_TARGET then
				-- block empty
			elseif SU.soldier_go_back_step(store, this) then
				-- block empty
			else
				brk, sta = y_hero_ranged_attacks(store, this)

				if brk then
					-- block empty
				else
					SU.soldier_idle(store, this)
				end
			end
		end

		coroutine.yield()
	end
end

scripts.bullet_hero_myriath_skill_a = {}

function scripts.bullet_hero_myriath_skill_a.insert(this, store, script)
	local b = this.bullet

	b.speed = SU.initial_parabola_speed(b.from, b.to, b.flight_time, b.g)
	b.ts = store.tick_ts
	b.last_pos = V.vclone(b.from)

	if b.rotation_speed then
		if b.starting_rotation then
			this.render.sprites[1].r = b.starting_rotation
		else
			this.render.sprites[1].r = (math.random() - 0.5) * math.pi
		end

		b.rotation_speed = b.rotation_speed * (b.to.x > b.from.x and -1 or 1)
	end

	if b.hide_radius then
		this.render.sprites[1].hidden = true
	end

	if this.tween then
		for i = 1, #this.tween.props do
			this.tween.props[i].ts = store.tick_ts
		end
	end

	local ps = E:get_template(b.particles_name)

	if store.entities[b.target_id] and store.entities[b.target_id].pos.x < store.entities[b.source_id].pos.x then
		ps.particle_system.scales_x = {
			-1
		}
	else
		ps.particle_system.scales_x = {
			1
		}
	end

	return true
end

function scripts.bullet_hero_myriath_skill_a.update(this, store, script)
	local b = this.bullet
	local dmin, dmax = b.damage_min, b.damage_max
	local ps

	if b.particles_name then
		ps = E:create_entity(b.particles_name)
		ps.particle_system.track_id = this.id

		queue_insert(store, ps)
	end

	while store.tick_ts - b.ts + store.tick_length < b.flight_time do
		coroutine.yield()

		b.last_pos.x, b.last_pos.y = this.pos.x, this.pos.y
		this.pos.x, this.pos.y = SU.position_in_parabola(store.tick_ts - b.ts, b.from, b.speed, b.g)

		if b.align_with_trajectory then
			this.render.sprites[1].r = V.angleTo(this.pos.x - b.last_pos.x, this.pos.y - b.last_pos.y)
		elseif b.rotation_speed then
			this.render.sprites[1].r = this.render.sprites[1].r + b.rotation_speed * store.tick_length
		end

		if b.hide_radius then
			this.render.sprites[1].hidden = V.dist(this.pos.x, this.pos.y, b.from.x, b.from.y) < b.hide_radius or V.dist(this.pos.x, this.pos.y, b.to.x, b.to.y) < b.hide_radius
		end

		if b.anim_rising or b.anim_falling then
			if this.pos.y - b.last_pos.y >= 0 then
				if b.anim_rising and this.render.sprites[1].name ~= b.anim_rising then
					U.animation_start(this, b.anim_rising, nil, store.tick_ts, b.anim_rising_loops, 1)
				end
			elseif b.anim_falling and this.render.sprites[1].name ~= b.anim_falling then
				U.animation_start(this, b.anim_falling, nil, store.tick_ts, b.anim_falling_loops, 1)
			end
		end
	end

	if b.target_id then
		local d = E:create_entity("damage")

		d.damage_type = b.damage_type
		d.value = math.random(b.damage_min, b.damage_max)
		d.source_id = b.source_id
		d.target_id = b.target_id

		queue_damage(store, d)
	end

	if b.hit_fx then
		S:queue(this.sound_events.hit)

		local sfx = E:create_entity(b.hit_fx)

		sfx.pos = V.vclone(b.to)

		queue_insert(store, sfx)
	end

	if b.hit_payload then
		local target = store.entities[b.target_id]
		local hp = E:create_entity(b.hit_payload)
		local flip = target and target.render.sprites[1].flip_x and -1 or 1
		local pos_x = target and V.vclone(target.pos).x + (target.enemy.melee_slot.x + store.entities[b.source_id].soldier.melee_slot_offset.x) * flip or b.to.x
		local pos_y = target and V.vclone(target.pos).y + target.enemy.melee_slot.y or b.to.y

		hp.pos.x, hp.pos.y = pos_x, pos_y
		hp.hero_myriath_id = b.source_id
		hp.source_id = b.source_id
		hp.target_block = target
		hp.animation_spawn = "ultimate_attack_" .. math.random(1, 3)

		queue_insert(store, hp)
	end

	queue_remove(store, this)
end

scripts.hero_myriath_skill_c_glow = {}

function scripts.hero_myriath_skill_c_glow.insert(this, store, script)
	U.animation_start(this, this.animation_in, this.flip_x, store.tick_ts, false, 1, true)

	return true
end

function scripts.hero_myriath_skill_c_glow.update(this, store, script)
	U.y_animation_wait(this)
	U.y_animation_play(this, this.animation, this.flip_x, store.tick_ts, 1, 1)
	queue_remove(store, this)
end

scripts.soldier_myriath_ult = {}

function scripts.soldier_myriath_ult.update(this, store, script)
	local node_pos, distance
	local path_pi = this.pi
	local path_spi = this.spi
	local path_ni = this.ni
	local traversed = 0

	path_ni = path_ni - 3
	this.nav_rally.pos = P:node_pos(path_pi, path_spi, path_ni)

	if path_spi == 1 then
		this.aura = E:create_entity(this.damage_aura)
		this.aura.pos = this.pos
		this.aura.hero_myriath_id = this.hero_myriath_id

		queue_insert(store, this.aura)
	end

	local ps = E:create_entity(this.particles)

	ps.particle_system.track_id = this.id

	queue_insert(store, ps)

	while true do
		if this.duration and store.tick_ts - this.ts > this.duration or not GR:cell_is(this.pos.x, this.pos.y, bor(TERRAIN_LAND, TERRAIN_ICE)) or GR:cell_is(this.pos.x, this.pos.y, bor(TERRAIN_NOWALK)) or not P:is_node_valid(path_pi, path_ni) or traversed >= this.distance then
			queue_remove(store, this)

			return
		end

		node_pos = this.nav_rally.pos
		distance = V.dist2(node_pos.x, node_pos.y, this.pos.x, this.pos.y)

		if distance < 25 then
			path_ni = path_ni - 3
			traversed = traversed + 3
			this.nav_rally.pos = P:node_pos(path_pi, path_spi, path_ni)
		end

		if SU.soldier_go_back_step(store, this) then
			-- block empty
		end

		coroutine.yield()
	end
end

function scripts.soldier_myriath_ult.remove(this, store, script)
	if this.aura then
		queue_remove(store, this.aura)
	end

	return scripts.tween_utils.reverse_remove(this, store, script)
end

scripts.aura_myriath_ult = {}

function scripts.aura_myriath_ult.update(this, store, script)
	this.aura.ts = store.tick_ts

	local last_hit_ts = 0
	local cycles_count = 0

	this.aura.excluded_entities = {}

	local clones = 0

	while true do
		if this.aura.cycles then
			if cycles_count >= this.aura.cycles then
				break
			end
		elseif this.aura.duration >= 0 and store.tick_ts - this.aura.ts >= this.aura.duration + this.aura.level * this.aura.duration_inc then
			break
		end

		if this.aura.track_source and this.aura.source_id then
			local te = store.entities[this.aura.source_id]

			if not te or te.health and te.health.dead then
				queue_remove(store, this)

				return
			end

			if te and te.pos then
				this.pos.x, this.pos.y = te.pos.x, te.pos.y
			end
		end

		if store.tick_ts - last_hit_ts >= this.aura.cycle_time then
			cycles_count = cycles_count + 1
			last_hit_ts = store.tick_ts

			local targets = table.filter(store.entities, function(k, v)
				return v.unit and v.vis and v.health and not v.health.dead and band(v.vis.flags, this.aura.vis_bans) == 0 and band(v.vis.bans, this.aura.vis_flags) == 0 and U.is_inside_ellipse(v.pos, this.pos, this.aura.radius) and (not this.aura.allowed_templates or table.contains(this.aura.allowed_templates, v.template_name)) and (not this.aura.excluded_templates or not table.contains(this.aura.excluded_templates, v.template_name)) and (not this.aura.excluded_entities or not table.contains(this.aura.excluded_entities, v.id))
			end)

			for _, target in pairs(targets) do
				local d = E:create_entity("damage")

				d.source_id = this.id
				d.target_id = target.id

				local dmin, dmax = this.aura.damage_min, this.aura.damage_max

				if this.aura.damage_inc then
					dmin = dmin + this.aura.damage_inc * this.aura.level
					dmax = dmax + this.aura.damage_inc * this.aura.level
				end

				d.value = math.random(dmin, dmax)
				d.damage_type = this.aura.damage_type
				d.track_damage = this.aura.track_damage
				d.xp_dest_id = this.aura.xp_dest_id
				d.xp_gain_factor = this.aura.xp_gain_factor

				queue_damage(store, d)
				table.insert(this.aura.excluded_entities, #this.aura.excluded_entities + 1, target.id)

				if clones < this.clone_count then
					clones = clones + 1

					local clone = E:create_entity(this.clone_t)
					local clone_melee_slot = E:get_template(this.clone_t).soldier.melee_slot_offset
					local pos_x = V.vclone(target.pos).x + (target.enemy.melee_slot.x + clone_melee_slot.x) * (target.render.sprites[1].flip_x and -1 or 1)
					local pos_y = V.vclone(target.pos).y + (target.enemy.melee_slot.y + clone_melee_slot.y)

					clone.pos = v(pos_x, pos_y)
					clone.hero_myriath_id = this.hero_myriath_id
					clone.target_block = target
					clone.animation_spawn = "in"

					queue_insert(store, clone)
				end

				local mods = this.aura.mods or {
					this.aura.mod
				}

				for _, mod_name in pairs(mods) do
					local m = E:create_entity(mod_name)

					m.modifier.level = this.aura.level
					m.modifier.target_id = target.id
					m.modifier.source_id = this.id

					if this.aura.hide_source_fx and target.id == this.aura.source_id then
						m.render = nil
					end

					queue_insert(store, m)
				end

				if this.aura.hit_fx then
					local fx = E:create_entity(this.aura.hit_fx)

					fx.pos.x, fx.pos.y = target.pos.x + target.unit.hit_offset.x, target.pos.y + target.unit.hit_offset.y
					fx.render.sprites[1].ts = store.tick_ts

					queue_insert(store, fx)
				end
			end
		end

		coroutine.yield()
	end

	queue_remove(store, this)
end

scripts.hero_connor = {}

function scripts.hero_connor.level_up(this, store, initial)
	if not initial then
		S:queue(this.sound_events.level_up)
	end

	local hl = this.hero.level
	local ls = this.hero.level_stats

	this.health.hp_max = ls.hp_max[hl]
	this.regen.health = ls.regen_health[hl]
	this.health.armor = ls.armor[hl]
	this.melee.attacks[1].damage_min = ls.melee_damage_min[hl]
	this.melee.attacks[1].damage_max = ls.melee_damage_max[hl]

	for i = 1, #this.ultimate_melee.attacks do
		this.ultimate_melee.attacks[i].damage_min = ls.melee_damage_min[hl]
		this.ultimate_melee.attacks[i].damage_max = ls.melee_damage_max[hl]
	end

	this.health.hp = this.health.hp_max
	this.hero.melee_active_status = {}

	for index, attack in ipairs(this.melee.attacks) do
		this.hero.melee_active_status[index] = attack.disabled
	end
end

function scripts.hero_connor.insert(this, store)
	this.hero.fn_level_up(this, store, true)

	this.melee.order = U.attack_order(this.melee.attacks)
	this.timed_attacks.list[4].disabled = not this.hero.skills.ultimate.active

	return true
end

function scripts.hero_connor.update(this, store)
	local h = this.health
	local r = this.nav_rally
	local brk, sta
	local old_tombstone_time = this.hero.tombstone_show_time
	local old_tombstone_respawn_animation = this.hero.tombstone_respawn_animation
	local ready_to_block = false
	local blocked = false
	local started_block_ts
	local in_ult = false
	local ult_mod, ult_spark_c, ult_ts, ult_spd_mod
	local st1_mod = {}

	this.health_bar.hidden = false

	local sa, sb, sc, su, st1, st2 = this.hero.skills.skill_a, this.hero.skills.skill_b, this.hero.skills.skill_c, this.hero.skills.ultimate, this.hero.skills.talent_1, this.hero.skills.talent_2
	local st2_respawn_ts = store.tick_ts - st2.cooldown + st2.starting_cooldown
	local saa = this.timed_attacks.list[1]

	saa.ts = store.tick_ts - saa.cooldown

	local sba = this.timed_attacks.list[2]
	local sba_ts = store.tick_ts - sba.cooldown
	local sca = this.timed_attacks.list[3]

	sca.ts = store.tick_ts - sca.cooldown

	local ua = this.timed_attacks.list[4]

	ua.ts = store.tick_ts - ua.cooldown

	local ult_start_cd = store.wave_group_number == 0

	if not st1.disabled then
		st1_mod = E:create_entity(st1.mod_t)
		st1_mod.modifier.source_id = this.id

		queue_insert(store, st1_mod)
	end

	local function y_connor_do_single_melee_attack(store, this, target, attack, break_fn)
		local attack_done = false
		local start_ts = store.tick_ts
		local an, af = U.animation_name_facing_point(this, attack.animation, target.pos)

		U.animation_start(this, an, af, store.tick_ts, 1)
		S:queue(attack.sound, attack.sound_args)

		while store.tick_ts - start_ts < attack.hit_time do
			if this.health.dead or this.unit.is_stunned or this.dodge and this.dodge.active and not this.dodge.silent or not attack.ignore_rally_change and this.nav_rally and this.nav_rally.new or break_fn and break_fn() then
				goto label_445_0
			end

			coroutine.yield()
		end

		S:queue(attack.sound_hit, attack.sound_hit_args)

		attack.ts = start_ts

		if attack.shared_cooldown then
			for _, aa in pairs(this.melee.attacks) do
				if aa ~= attack and aa.shared_cooldown then
					aa.ts = attack.ts
				end
			end
		end

		if attack.signal then
			signal.emit("soldier-attack", this, attack, attack.signal)
		end

		if not SU.unit_dodges(store, target, false, attack, this) and table.contains(target.enemy.blockers, this.id) then
			if attack.damage_type ~= DAMAGE_NONE then
				local d = E:create_entity("damage")

				d.source_id = this.id
				d.target_id = target.id
				d.xp_gain_factor = attack.xp_gain_factor
				d.xp_dest_id = attack.xp_dest_id
				d.track_kills = this.track_kills ~= nil
				d.track_damage = attack.track_damage
				d.pop = attack.pop
				d.pop_chance = attack.pop_chance
				d.pop_conds = attack.pop_conds

				if IS_KR5 then
					d.reduce_armor = attack.reduce_armor
					d.reduce_magic_armor = attack.reduce_magic_armor
				end

				if attack.instakill then
					d.damage_type = DAMAGE_INSTAKILL
				elseif attack.fn_damage then
					d.damage_type = attack.damage_type
					d.value = attack.fn_damage(this, store, attack, target)
				elseif attack.damage_min then
					d.damage_type = attack.damage_type
					d.value = math.ceil(this.unit.damage_factor * math.random(attack.damage_min, attack.damage_max))
				end

				queue_damage(store, d)
			end

			local hit_pos = V.vclone(this.pos)

			if attack.hit_offset then
				hit_pos.x = hit_pos.x + (af and -1 or 1) * attack.hit_offset.x
				hit_pos.y = hit_pos.y + attack.hit_offset.y
			end

			if attack.hit_fx then
				local fx = E:create_entity(attack.hit_fx)

				fx.pos = V.vclone(hit_pos)

				for i = 1, #fx.render.sprites do
					fx.render.sprites[i].ts = store.tick_ts
				end

				queue_insert(store, fx)
			end
		end

		if target and target.dodge and target.dodge.active and target.dodge.show_pop then
			SU.show_dodge_pop(store, target)
		end

		attack_done = true

		while not U.animation_finished(this) do
			if this.health.dead or this.unit.is_stunned or this.dodge and this.dodge.active and not this.dodge.silent or not attack.ignore_rally_change and this.nav_rally and this.nav_rally.new or break_fn and break_fn() then
				break
			end

			coroutine.yield()
		end

		::label_445_0::

		S:stop(attack.sound)

		return attack_done
	end

	local function y_connor_melee_block_and_attacks(store, hero, break_fn)
		local target = SU.soldier_pick_melee_target(store, hero)

		if not target then
			return false, A_NO_TARGET
		end

		if break_fn and break_fn() then
			return false, A_DONE
		end

		if SU.soldier_move_to_slot_step(store, hero, target) then
			if hero.melee and hero.melee.forced_cooldown and hero.melee.force_cooldown_at_slot_walk then
				hero.melee.forced_ts = store.tick_ts
			end

			return true
		end

		local attack = SU.soldier_pick_melee_attack(store, hero, target)

		if not attack then
			return false, A_IN_COOLDOWN
		end

		local attack_pop = attack.pop
		local attack_pop_chance = attack.pop_chance
		local triggered_crit = attack.critical_chance and math.random() < attack.critical_chance

		if triggered_crit then
			hero.unit.damage_factor = hero.unit.damage_factor * 2
			attack.pop = {
				"pop_crit_heroes"
			}
			attack.pop_chance = 1
		end

		if attack.xp_from_skill then
			SU.hero_gain_xp_from_skill(hero, hero.hero.skills[attack.xp_from_skill])
		end

		local attack_done = y_connor_do_single_melee_attack(store, hero, target, attack, break_fn)

		if triggered_crit then
			hero.unit.damage_factor = hero.unit.damage_factor / 2
			attack.pop = attack_pop
			attack.pop_chance = attack_pop_chance
		end

		if attack_done then
			return false, A_DONE
		else
			return true
		end
	end

	local function cancel_block()
		ready_to_block = false
		blocked = false
		this.dodge.chance = 0
		this.dodge.last_doge_ts = nil
		sba_ts = store.tick_ts
	end

	local function check_for_block()
		if in_ult or sba.disabled then
			return false
		end

		if not ready_to_block and store.tick_ts - sba_ts > sba.cooldown and this.soldier.target_id ~= nil and this.motion.arrived then
			ready_to_block = true
			started_block_ts = store.tick_ts
			this.dodge.chance = 1
		end

		if ready_to_block and store.tick_ts - started_block_ts > sba.time_to_block then
			cancel_block()
		end

		local dodge_ts = this.dodge.last_doge_ts
		local dodge_age = dodge_ts and store.tick_ts - dodge_ts

		blocked = not in_ult and ready_to_block and dodge_age and dodge_age >= 0 and dodge_age <= 2 / FPS

		return blocked
	end

	local function check_end_ult()
		if in_ult and store.tick_ts - ult_ts > ua.duration then
			U.y_animation_play(this, ua.animation_out, nil, store.tick_ts, 1, 1)

			this.render.sprites[1].prefix = this._old_prefix
			this.melee.attacks = this._old_melee_attacks
			this.melee.order = U.attack_order(this.melee.attacks)
			this.melee.cooldown = this._old_melee_cooldown

			queue_remove(store, ult_mod)
			queue_remove(store, ult_spd_mod)
			queue_remove(store, ult_spark_c)

			this.health.ignore_damage = false
			in_ult = false
			ua.ts = store.tick_ts

			U.animation_start(this, "idle", nil, store.tick_ts, true)

			return true
		end

		return false
	end

	while true do
		if ult_start_cd and store.wave_group_number > 0 then
			ult_start_cd = false
			ua.ts = store.tick_ts
		end

		if h.dead then
			cancel_block()

			if not st2.disabled and store.tick_ts - st2_respawn_ts > st2.cooldown and math.random() < st2.chance_to_revive then
				h.dead = false
				this.health_bar.hidden = false
				this.ui.can_click = true
				h.hp = h.hp_max * st2.hp_ptg_on_revive
				this.force_respawn = nil
				h.ignore_damage = false

				U.y_animation_play(this, "lvl_up", nil, store.tick_ts, 1)

				st2_respawn_ts = store.tick_ts
			else
				if band(h.last_damage_types, bor(DAMAGE_EAT)) ~= 0 then
					this.hero.tombstone_show_time = nil
					this.hero.tombstone_respawn_animation = nil
				end

				SU.y_hero_death_and_respawn_kr5(store, this)

				this.hero.tombstone_show_time = old_tombstone_time
				this.hero.tombstone_respawn_animation = old_tombstone_respawn_animation
			end
		end

		if this.unit.is_stunned then
			SU.soldier_idle(store, this)
		else
			while r.new do
				check_end_ult()

				r.new = false

				U.unblock_target(store, this)

				if this.sound_events then
					S:queue(this.sound_events.change_rally_point)
				end

				local vis_bans = this.vis.bans
				local prev_immune = this.health.immune_to

				this.vis.bans = F_ALL
				this.health.immune_to = r.immune_to

				local out = SU.y_hero_walk_waypoints(store, this)

				U.animation_start(this, "idle", nil, store.tick_ts, true)

				this.vis.bans = vis_bans
				this.health.immune_to = prev_immune

				if out then
					goto label_444_1
				end
			end

			if SU.hero_level_up(store, this) then
				U.y_animation_play(this, "lvl_up", nil, store.tick_ts, 1)
			end

			if not in_ult and not ua.disabled and store.tick_ts - ua.ts > ua.cooldown and h.hp < h.hp_max * ua.hp_ptg_to_trigger and this.soldier.target_id ~= nil and this.motion.arrived then
				local a = ua
				local start_ts = store.tick_ts
				local enemies = U.find_enemies_in_range(store.entities, this.pos, a.min_range, a.max_range, a.vis_flags, a.vis_bans)

				if not enemies or #enemies < a.min_targets then
					SU.delay_attack(store, sba, fts(10))
				else
					cancel_block()

					this.health.ignore_damage = true

					U.animation_start(this, a.animation_in, nil, store.tick_ts, false)
					S:queue(a.sound, {
						delay = fts(11)
					})
					S:queue(a.ult_taunt)

					if SU.y_hero_wait(store, this, a.cast_time) then
						this.health.ignore_damage = false
						goto label_444_1
					end

					S:queue(a.sound_hit)

					ua.ts = start_ts

					SU.hero_gain_xp_from_skill(this, su)

					if a.shared_cooldown then
						for _, aa in pairs(this.timed_attacks.list) do
							if aa ~= a and aa.shared_cooldown then
								aa.ts = a.ts
							end
						end
					end

					local aura = E:create_entity(a.aura_t)

					aura.pos.x, aura.pos.y = this.pos.x, this.pos.y
					aura.aura.ts = store.tick_ts

					queue_insert(store, aura)

					local decal = E:create_entity(a.decal_t)

					decal.pos.x, decal.pos.y = this.pos.x, this.pos.y

					for i = 1, #decal.render.sprites do
						decal.render.sprites[i].ts = store.tick_ts
						decal.render.sprites[i].flip_x = this.render.sprites[i].flip_x
					end

					queue_insert(store, decal)
					SU.y_hero_animation_wait(this)

					this._old_prefix = this.render.sprites[1].prefix
					this.render.sprites[1].prefix = this.ultimate_prefix
					this._old_melee_attacks = this.melee.attacks
					this._old_melee_cooldown = this.melee.cooldown
					this.melee.attacks = this.ultimate_melee.attacks
					this.melee.order = U.attack_order(this.melee.attacks)
					ult_mod = E:create_entity(ua.mod)
					ult_mod.modifier.target_id = this.id

					queue_insert(store, ult_mod)

					ult_spd_mod = E:create_entity(ua.speed_mod)
					ult_spd_mod.modifier.target_id = this.id

					queue_insert(store, ult_spd_mod)

					ult_spark_c = E:create_entity(this.ultimate_sparks_controller_t)
					ult_spark_c.source_id = this.id

					queue_insert(store, ult_spark_c)

					in_ult = true
					ult_ts = store.tick_ts

					U.animation_start(this, "idle", nil, store.tick_ts, true)

					goto label_444_1
				end
			end

			if not in_ult and not ready_to_block and not sca.disabled and store.tick_ts - sca.ts > sca.cooldown and this.soldier.target_id == nil then
				local a = sca
				local enemies = U.find_enemies_in_range(store.entities, this.pos, a.min_range, a.max_range, a.vis_flags, a.vis_bans)

				if not enemies or #enemies < a.min_targets then
					SU.delay_attack(store, a, fts(10))

					goto label_444_0
				end

				local nearest = P:nearest_nodes(this.pos.x, this.pos.y)

				if not nearest or #nearest == 0 then
					SU.delay_attack(store, a, fts(10))

					goto label_444_0
				end

				local pi, spi, ni, distance
				local targets = table.filter(enemies, function(k, v)
					local path = v.nav_path
					local vpi = path and path.pi

					if not vpi or not path.ni or not P:is_path_active(vpi) then
						return false
					end

					local nearest = P:nearest_nodes(this.pos.x, this.pos.y, {
						vpi
					})
					local node = nearest[1]

					if not node then
						return false
					end

					local v_pi, v_spi, v_ni, v_distance = unpack(node)

					if v_distance < 50 and (not store.level.ignore_walk_backwards_paths or not table.contains(store.level.ignore_walk_backwards_paths, vpi)) and v_ni > path.ni then
						pi = v_pi
						spi = v_spi
						ni = v_ni
						distance = v_distance

						return true
					end

					return false
				end)

				if not targets or #targets < a.min_targets then
					SU.delay_attack(store, a, fts(10))

					goto label_444_0
				end

				local start_ts = store.tick_ts

				S:queue(a.sound_jump)
				S:queue(a.sound_taunt)

				st1_mod.force_hide = true

				local flip = targets[1].pos.x < this.pos.x

				U.animation_start(this, a.animation, flip, store.tick_ts, false)

				if SU.y_hero_wait(store, this, a.cast_time) then
					goto label_444_1
				end

				sca.ts = start_ts

				SU.hero_gain_xp_from_skill(this, sc)
				S:queue(a.sound_impact)

				local nodes_between_aoe = sca.node_between_aoes

				local function spawn_area_damage(pi, spi, ni, aoe_id)
					local pos = P:node_pos(pi, spi, ni)
					local mid_pos = P:node_pos(pi, 1, ni)
					local y_random = mid_pos.y > pos.y and math.random(5, 10) or math.random(-10, -5)

					pos.x = pos.x + math.random(-4, 4)
					pos.y = pos.y + y_random

					local au = E:create_entity(a.aura_t)

					au.pos = V.vclone(pos)

					queue_insert(store, au)

					local d = E:create_entity(a.decal_t)

					d.pos = V.vclone(pos)
					d.render.sprites[1].flip_x = this.render.sprites[1].flip_x
					d.render.sprites[1].ts = store.tick_ts

					queue_insert(store, d)
				end

				local initial_offset = 2

				ni = ni - initial_offset

				local count = a.aoe_count / 2
				local count_ceil = math.ceil(a.aoe_count / 2)
				local ni_aux
				local aoe_id = 1
				local d = E:create_entity(a.decal_ground)

				d.pos = V.vclone(this.pos)
				d.render.sprites[1].ts = store.tick_ts

				queue_insert(store, d)

				for i = 1, count_ceil do
					ni_aux = ni - i * nodes_between_aoe

					if P:is_node_valid(pi, ni_aux) then
						spawn_area_damage(pi, 2, ni_aux, aoe_id)

						aoe_id = aoe_id + 1

						U.y_wait(store, fts(1))
					end

					if count < i then
						break
					end

					ni_aux = ni - i * (nodes_between_aoe + 1)

					if P:is_node_valid(pi, ni_aux) then
						spawn_area_damage(pi, 3, ni_aux, aoe_id)

						aoe_id = aoe_id + 1

						U.y_wait(store, fts(1))
					end
				end

				S:queue(a.sound_out)

				st1_mod.force_hide = false

				SU.y_hero_animation_wait(this)
				U.animation_start(this, "idle", nil, store.tick_ts, true)

				goto label_444_1
			end

			::label_444_0::

			if not in_ult and not ready_to_block and not saa.disabled and store.tick_ts - saa.ts > saa.cooldown and this.motion.arrived then
				local a = saa
				local start_ts = store.tick_ts
				local enemies = U.find_enemies_in_range(store.entities, this.pos, a.min_range, a.max_range, a.vis_flags, a.vis_bans)

				if not enemies or #enemies < a.min_targets then
					SU.delay_attack(store, sba, fts(10))
				else
					st1_mod.force_hide = true

					U.animation_start(this, a.animation, nil, store.tick_ts, false)
					S:queue(a.sound)

					if SU.y_hero_wait(store, this, a.cast_time) then
						goto label_444_1
					end

					S:queue(a.sound_hit)

					saa.ts = start_ts

					SU.hero_gain_xp_from_skill(this, sa)

					local hit_pos = V.vclone(this.pos)

					if a.hit_offset then
						hit_pos.x = hit_pos.x + (this.render.sprites[1].flip_x and -1 or 1) * a.hit_offset.x
						hit_pos.y = hit_pos.y + a.hit_offset.y
					end

					local enemies = U.find_enemies_in_range(store.entities, hit_pos, 0, a.damage_radius, a.vis_flags, a.vis_bans)

					if enemies and #enemies > 0 then
						for k, v in pairs(enemies) do
							local d = E:create_entity("damage")

							d.source_id = this.id
							d.target_id = v.id
							d.damage_type = a.damage_type
							d.value = math.ceil(this.unit.damage_factor * math.random(a.damage_min, a.damage_max))

							queue_damage(store, d)

							local mod = E:create_entity(a.mod_bleed)

							mod.modifier.source_id = this.id
							mod.modifier.target_id = v.id

							queue_insert(store, mod)
						end
					end

					local decal = E:create_entity(a.decal)

					decal.pos = V.vclone(this.pos)

					for i = 1, #decal.render.sprites do
						decal.render.sprites[i].ts = store.tick_ts
						decal.render.sprites[i].flip_x = this.render.sprites[i].flip_x
					end

					queue_insert(store, decal)

					st1_mod.force_hide = false

					SU.y_hero_animation_wait(this)
					U.animation_start(this, "idle", nil, store.tick_ts, true)

					goto label_444_1
				end
			end

			if not in_ult and not sba.disabled and ready_to_block and blocked and this.soldier.target_id ~= nil and this.motion.arrived and ready_to_block and blocked and this.soldier.target_id ~= nil and this.motion.arrived then
				blocked = false
				ready_to_block = false
				this.dodge.chance = 0
				this.dodge.last_doge_ts = nil

				local a = sba
				local start_ts = store.tick_ts
				local target = store.entities[this.soldier.target_id]

				if not target or target.health.dead then
					cancel_block()
					goto label_444_1
				end

				ready_to_block = false
				this.dodge.chance = 0
				st1_mod.force_hide = true

				U.animation_start(this, a.animation, target.pos.x < this.pos.x, store.tick_ts, false)
				S:queue(a.sound, {
					delay = fts(11)
				})

				if SU.y_hero_wait(store, this, a.cast_time) then
					goto label_444_1
				end

				S:queue(a.sound_hit)

				sba_ts = start_ts

				SU.hero_gain_xp_from_skill(this, sb)

				local hit_pos = V.vclone(this.pos)

				if a.hit_offset then
					hit_pos.x = hit_pos.x + (this.render.sprites[1].flip_x and -1 or 1) * a.hit_offset.x
					hit_pos.y = hit_pos.y + a.hit_offset.y
				end

				local d = E:create_entity("damage")

				d.source_id = this.id
				d.target_id = target.id
				d.damage_type = a.damage_type
				d.value = math.ceil(this.unit.damage_factor * math.random(a.damage_min, a.damage_max))

				queue_damage(store, d)

				if a.hit_fx then
					local fx = E:create_entity(a.hit_fx)

					fx.pos = V.vclone(this.pos)

					for i = 1, #fx.render.sprites do
						fx.render.sprites[i].ts = store.tick_ts
						fx.render.sprites[i].flip_x = this.render.sprites[1].flip_x
					end

					queue_insert(store, fx)
				end

				st1_mod.force_hide = false

				SU.y_hero_animation_wait(this)
				U.animation_start(this, "idle", nil, store.tick_ts, true)

				goto label_444_1
			end

			if check_end_ult() then
				-- block empty
			else
				brk, sta = y_connor_melee_block_and_attacks(store, this, check_for_block)

				if brk or sta ~= A_NO_TARGET then
					-- block empty
				elseif SU.soldier_go_back_step(store, this) then
					-- block empty
				else
					SU.soldier_idle(store, this)
					SU.soldier_regen(store, this)
				end
			end
		end

		::label_444_1::

		coroutine.yield()
	end
end

scripts.mod_connor_ultimate_buff = {}

function scripts.mod_connor_ultimate_buff.insert(this, store, script)
	local target = store.entities[this.modifier.target_id]

	this._old_damage_factor = target.unit.damage_factor
	target.unit.damage_factor = this.base_damage_factor
	this._old_melee_cooldown = target.melee.cooldown
	target.melee.cooldown = this.ultimate_melee_cooldown

	return true
end

function scripts.mod_connor_ultimate_buff.remove(this, store, script)
	local target = store.entities[this.modifier.target_id]

	target.unit.damage_factor = this._old_damage_factor
	target.melee.cooldown = this._old_melee_cooldown

	return true
end

scripts.controller_spawn_fx_on_frames = {}

function scripts.controller_spawn_fx_on_frames.update(this, store, script)
	local target = store.entities[this.source_id]
	local sprite_id = this.sprite_id or 1

	while true do
		if not target or target.health.dead then
			queue_remove(store, this)
		end

		local target_prefix = target.render.sprites[1].prefix

		if this.frames_to_do_fx[target_prefix] then
			for anim, frames in pairs(this.frames_to_do_fx[target_prefix]) do
				for i, f in ipairs(frames) do
					local formatted_frame_name = string.format("%s_%s_%04i", target_prefix, anim, f)

					if target.render.sprites[sprite_id].frame_name == formatted_frame_name then
						local fx = E:create_entity(this.fx_t)
						local fpos = this.spawn_on_target and V.v(target.pos.x, target.pos.y) or V.v(0, 0)

						if this.spawn_offset then
							fpos.x, fpos.y = fpos.x + this.spawn_offset.x, fpos.y + this.spawn_offset.y
						end

						fx.pos.x, fx.pos.y = fpos.x, fpos.y
						fx.render.sprites[sprite_id].ts = store.tick_ts

						if this.link_flip_x then
							fx.render.sprites[sprite_id].flip_x = target.render.sprites[1].flip_x
						end

						queue_insert(store, fx)
					end
				end
			end
		end

		coroutine.yield()
	end
end

scripts.mod_connor_talent_1 = {}

function scripts.mod_connor_talent_1.update(this, store, script)
	local target = store.entities[this.modifier.source_id]
	local active = false
	local run_force = false

	this.force_hide = false

	local function hide()
		U.animation_start(this, "out", nil, store.tick_ts, nil, 1)
	end

	local function show()
		if this.render.sprites[1].hidden then
			this.render.sprites[1].hidden = false
		end

		U.animation_start(this, "in", nil, store.tick_ts, nil, 1)

		while not U.animation_finished(this, 1, 1) do
			if this.force_hide then
				goto label_457_0
			end

			coroutine.yield()
		end

		U.animation_start(this, "loop", nil, store.tick_ts, true, 1)

		::label_457_0::
	end

	local function apply_buff()
		target.timed_attacks.list[1].damage_min = target.timed_attacks.list[1].damage_min * this.skill_damage_factor
		target.timed_attacks.list[1].damage_max = target.timed_attacks.list[1].damage_max * this.skill_damage_factor
		target.timed_attacks.list[2].damage_min = target.timed_attacks.list[2].damage_min * this.skill_damage_factor
		target.timed_attacks.list[2].damage_max = target.timed_attacks.list[2].damage_max * this.skill_damage_factor

		local aura_skc = E:get_template(target.timed_attacks.list[3].aura_t)

		aura_skc.aura.damage_min = aura_skc.aura.damage_min * this.skill_damage_factor
		aura_skc.aura.damage_max = aura_skc.aura.damage_max * this.skill_damage_factor
	end

	local function remove_buff()
		target.timed_attacks.list[1].damage_min = target.timed_attacks.list[1].damage_min / this.skill_damage_factor
		target.timed_attacks.list[1].damage_max = target.timed_attacks.list[1].damage_max / this.skill_damage_factor
		target.timed_attacks.list[2].damage_min = target.timed_attacks.list[2].damage_min / this.skill_damage_factor
		target.timed_attacks.list[2].damage_max = target.timed_attacks.list[2].damage_max / this.skill_damage_factor

		local aura_skc = E:get_template(target.timed_attacks.list[3].aura_t)

		aura_skc.aura.damage_min = aura_skc.aura.damage_min / this.skill_damage_factor
		aura_skc.aura.damage_max = aura_skc.aura.damage_max / this.skill_damage_factor
	end

	local function condition()
		return target.health.hp <= target.health.hp_max * this.hp_ptg_to_trigger
	end

	this.pos = target.pos

	while true do
		if not this.force_hide and run_force then
			run_force = false

			if condition() then
				if not active then
					apply_buff()

					active = true
				end

				show()
			end
		else
			if not active and condition() then
				apply_buff()

				active = true

				show()
			end

			if active and not condition() then
				remove_buff()

				active = false

				hide()
			end

			if target.health.dead then
				if active then
					remove_buff()

					active = false
				end

				hide()

				while target.health.dead do
					coroutine.yield()
				end
			end

			if not run_force and this.force_hide then
				run_force = true

				hide()
			end
		end

		coroutine.yield()
	end
end

scripts.hero_ignus = {}

function scripts.hero_ignus.insert(this, store)
	this.hero.fn_level_up(this, store, true)

	this.melee.order = U.attack_order(this.melee.attacks)
	this.timed_attacks.list[4].disabled = not this.hero.skills.ultimate.active

	return true
end

function scripts.hero_ignus.level_up(this, store, initial)
	if not initial then
		S:queue(this.sound_events.level_up)
	end

	local hl = this.hero.level
	local ls = this.hero.level_stats

	this.health.hp_max = ls.hp_max[hl]
	this.regen.health = ls.regen_health[hl]
	this.health.armor = ls.armor[hl]
	this.melee.attacks[1].damage_min = ls.melee_damage_min[hl]
	this.melee.attacks[1].damage_max = ls.melee_damage_max[hl]
	this.health.hp = this.health.hp_max
	this.hero.melee_active_status = {}

	for index, attack in ipairs(this.melee.attacks) do
		this.hero.melee_active_status[index] = attack.disabled
	end
end

function scripts.hero_ignus.update(this, store)
	local NODES_TO_FORCE_BLOCK = 1e+99
	local TIME_FORCING_BLOCK = 0.2
	local h = this.health
	local brk, sta
	local old_tombstone_time = this.hero.tombstone_show_time
	local old_tombstone_respawn_animation = this.hero.tombstone_respawn_animation

	this.health_bar.hidden = false

	local sc_controller
	local base_speed = this.motion.max_speed
	local sa = not this.timed_attacks.list[1].disabled and this.timed_attacks.list[1] or nil

	if sa then
		sa.ts = store.tick_ts - sa.cooldown
	end

	local sb = not this.timed_attacks.list[2].disabled and this.timed_attacks.list[2] or nil

	if sb then
		sb.ts = store.tick_ts - sb.cooldown
	end

	local sc = not this.timed_attacks.list[3].disabled and this.timed_attacks.list[3] or nil

	if sc then
		sc.ts = store.tick_ts - sc.cooldown
		this.end_skill_c = false
	end

	local t1 = not this.hero.skills.talent_1.disabled and this.hero.skills.talent_1 or nil

	if t1 then
		this.t1a = E:create_entity(t1.aura)
		this.t1a.aura.track_source = true
		this.t1a.aura.source_id = this.id

		queue_insert(store, this.t1a)
	end

	local t2 = not this.hero.skills.talent_2.disabled and this.hero.skills.talent_2 or nil
	local flywalk = not this.flywalk.disabled and this.flywalk or nil
	local ult = not this.timed_attacks.list[4].disabled and this.timed_attacks.list[4] or nil

	if ult then
		ult.ts = store.tick_ts - ult.cooldown
	end

	local ult_start_cd = ult ~= nil and store.wave_group_number == 0
	local force_block_ts = 0

	local function get_nodes_im_on()
		if not this.all_paths then
			this.all_paths = {}

			for i = 1, #P.paths do
				table.insert(this.all_paths, i)
			end
		end

		local nearest_nodes = P:nearest_nodes(this.pos.x, this.pos.y, this.all_paths, nil, true)

		nearest_nodes = table.filter(nearest_nodes, function(k, v)
			local c = v[4] < P:path_width(v[1])

			return c
		end)

		local p = #nearest_nodes > 0 and {} or nil

		for i, v in ipairs(nearest_nodes) do
			table.insert(p, {
				v[1],
				v[3]
			})
		end

		return p
	end

	local function talent_2_heal()
		if t2 and not h.dead then
			local m = E:create_entity(t2.mod)

			m.hps.heal_min = this.health.hp_max * t2.heal_ptg
			m.hps.heal_max = this.health.hp_max * t2.heal_ptg
			m.modifier.target_id = this.id

			queue_insert(store, m)
		end
	end

	while true do
		if ult_start_cd and store.wave_group_number > 0 then
			ult_start_cd = false
			ult.ts = store.tick_ts
		end

		if h.dead then
			if band(h.last_damage_types, bor(DAMAGE_EAT)) ~= 0 then
				this.hero.tombstone_show_time = nil
				this.hero.tombstone_respawn_animation = nil
			end

			local t1a_cycle_time

			if this.t1a then
				t1a_cycle_time = this.t1a.aura.cycle_time
				this.t1a.aura.cycle_time = 1e+99
			end

			SU.y_hero_death_and_respawn_kr5(store, this)

			if this.t1a then
				this.t1a.aura.cycle_time = t1a_cycle_time
			end

			this.hero.tombstone_show_time = old_tombstone_time
			this.hero.tombstone_respawn_animation = old_tombstone_respawn_animation
		end

		if this.unit.is_stunned then
			SU.soldier_idle(store, this)
		else
			while this.nav_rally.new do
				local r = this.nav_rally

				if flywalk and not flywalk.disabled and V.dist(this.pos.x, this.pos.y, r.pos.x, r.pos.y) > flywalk.min_distance then
					r.new = false

					U.unblock_target(store, this)

					local vis_bans = this.vis.bans
					local immune = this.health.immune_to

					this.vis.bans = F_ALL
					this.health.immune_to = F_ALL

					local z = this.render.sprites[1].z

					this.render.sprites[1].z = Z_FLYING_HEROES
					this.motion.max_speed = this.motion.max_speed * flywalk.extra_speed_factor
					this.unit.marker_hidden = true
					this.health_bar.hidden = true

					S:queue(this.sound_events.change_rally_point)
					S:queue(flywalk.sound)

					local dest

					U.y_animation_play(this, flywalk.animations[1], r.pos.x < this.pos.x, store.tick_ts, 1, 1)
					U.set_destination(this, r.pos)

					local fd = E:create_entity(flywalk.fire_decal)

					fd.render.sprites[1].ts = store.tick_ts
					fd.render.sprites[1].flip_x = not this.render.sprites[1].flip_x
					fd.pos = V.vclone(this.pos)

					queue_insert(store, fd)

					for i = 1, 6 do
						U.walk(this, store.tick_length)
					end

					local ps = E:create_entity(flywalk.particles)

					ps.pos = V.vclone(this.pos)

					queue_insert(store, ps)

					local distance_flag, n, flip
					local new_decal = false

					flywalk.slide_distance = base_speed / 2 * fts(18)

					::label_463_0::

					dest = r.pos
					n = this.nav_grid
					flip = r.pos.x < this.pos.x and math.pi or 0
					this.render.sprites[1].flip_x = r.pos.x < this.pos.x
					this.render.sprites[1].r = V.angleTo(r.pos.x - this.pos.x, r.pos.y - this.pos.y) + flip
					distance_flag = false
					ps.particle_system.emit = true
					ps.offset.x = this.render.sprites[1].flip_x and -1 * ps.offset.x or ps.offset.x

					if new_decal then
						local fd = E:create_entity(flywalk.fire_decal)

						fd.render.sprites[1].ts = store.tick_ts
						fd.render.sprites[1].flip_x = not this.render.sprites[1].flip_x
						fd.pos = V.vclone(this.pos)

						queue_insert(store, fd)

						new_decal = false
					end

					U.animation_start(this, flywalk.animations[2], nil, store.tick_ts, true, 1)

					while not V.veq(this.pos, dest) do
						U.set_destination(this, dest)

						while not this.motion.arrived do
							if r.new and not distance_flag then
								r.new = false
								new_decal = true

								goto label_463_0
							end

							if V.dist2(this.pos.x, this.pos.y, r.pos.x, r.pos.y) <= flywalk.slide_distance * flywalk.slide_distance and not distance_flag then
								distance_flag = true
								this.motion.max_speed = this.motion.max_speed / flywalk.extra_speed_factor / 2

								U.animation_start(this, flywalk.animations[3], nil, store.tick_ts, false, 1)

								this.render.sprites[1].r = 0
								this.render.sprites[1].z = z
								ps.particle_system.emission_rate = 2
							end

							U.walk(this, store.tick_length)

							ps.pos.x = V.vclone(this.pos).x + ps.offset.x * math.cos(this.render.sprites[1].r) - ps.offset.y * math.sin(this.render.sprites[1].r)
							ps.pos.y = V.vclone(this.pos).y + ps.offset.x * math.sin(this.render.sprites[1].r) + ps.offset.y * math.cos(this.render.sprites[1].r)

							coroutine.yield()

							this.motion.speed.x, this.motion.speed.y = 0, 0
						end

						ps.particle_system.emit = false
						this.pos = V.vclone(dest)
					end

					SU.show_modifiers(store, this, true)

					this.motion.max_speed = this.motion.max_speed * 2
					this.render.sprites[1].r = 0
					this.vis.bans = vis_bans
					this.health.immune_to = immune
					this.unit.marker_hidden = nil
					this.health_bar.hidden = nil
				elseif SU.y_hero_new_rally(store, this) then
					goto label_463_1
				end

				force_block_ts = store.tick_ts
			end

			if SU.hero_level_up(store, this) then
				U.y_animation_play(this, "lvlup", nil, store.tick_ts, 1)
			end

			if TIME_FORCING_BLOCK > store.tick_ts - force_block_ts then
				-- block empty
			else
				if ult and store.tick_ts - ult.ts >= ult.cooldown then
					local targets = U.find_enemies_in_range(store.entities, this.pos, 0, ult.max_range, 0, 0)

					if not targets or #targets == 0 or #targets < ult.min_targets or not this.motion.arrived then
						SU.delay_attack(store, ult, fts(10))
					else
						local selected_e = store.entities[this.soldier.target_id] or targets[1]

						U.unblock_target(store, this)
						S:queue(ult.taunt)
						S:queue(ult.sound_cast)
						U.animation_start(this, ult.animations[1], nil, store.tick_ts, false, 1)

						if SU.y_hero_wait(store, this, ult.cast_time) then
							goto label_463_1
						end

						U.animation_start(this, ult.animations[2], nil, store.tick_ts, true, 1)
						S:queue(ult.sound_loop)

						local ts = store.tick_ts
						local bans = this.vis.bans

						this.vis.bans = F_ALL
						this.health.ignore_damage = true

						local a = E:create_entity(ult.aura)

						a.pos = V.vclone(this.pos)

						queue_insert(store, a)

						local nearest = P:nearest_nodes(this.pos.x, this.pos.y, {
							selected_e.nav_path.pi
						})[1]
						local node_pos = P:node_pos(nearest[1], 1, nearest[3])

						U.set_destination(this, node_pos)

						this.motion.max_speed = this.motion.max_speed * ult.movement_speed

						while store.tick_ts - ts < ult.duration do
							if not V.veq(this.pos, node_pos) then
								U.walk(this, store.tick_length)
							end

							coroutine.yield()
						end

						this.motion.arrived = true
						this.motion.max_speed = this.motion.max_speed / ult.movement_speed

						local d = E:create_entity(ult.ground_decal)

						d.pos = V.vclone(this.pos)
						d.render.sprites[1].ts = store.tick_ts

						queue_insert(store, d)
						S:stop(ult.sound_loop)
						S:queue(ult.sound_end)
						S:queue(this.sound_transformation_in, {
							delay = fts(13)
						})
						S:queue(this.sound_transformation_out, {
							delay = fts(39)
						})
						U.y_animation_play(this, ult.animations[3], nil, store.tick_ts, 1, 1)

						this.vis.bans = bans
						this.health.ignore_damage = false

						SU.hero_gain_xp_from_skill(this, this.hero.skills.ultimate)
						talent_2_heal()

						ult.ts = store.tick_ts

						apply_delayed_cooldowns(store, this.hero.throttled_cooldown, this.timed_attacks.list)

						goto label_463_1
					end
				end

				if sb and store.tick_ts - sb.ts >= sb.cooldown then
					local target, targets = U.find_foremost_enemy(store.entities, this.pos, 0, sb.max_range, fts(10), 0, 0)

					if not targets or #targets == 0 or #targets < sb.min_targets or not this.motion.arrived then
						SU.delay_attack(store, sb, fts(10))
					else
						S:queue(sb.sound)
						U.animation_start(this, sb.animation, nil, store.tick_ts, false, 1)

						if SU.y_hero_wait(store, this, sb.cast_time) then
							goto label_463_1
						end

						local a = E:create_entity(sb.aura)

						a.pos = V.vclone(this.pos)

						queue_insert(store, a)

						local d = E:create_entity(sb.decal_ground)

						d.pos = V.vclone(this.pos)
						d.render.sprites[1].ts = store.tick_ts

						queue_insert(store, d)
						S:queue(this.sound_transformation_in, {
							delay = fts(27)
						})
						SU.hero_gain_xp_from_skill(this, this.hero.skills.skill_b)
						talent_2_heal()
						U.y_animation_wait(this)

						sb.ts = store.tick_ts

						apply_delayed_cooldowns(store, this.hero.throttled_cooldown, this.timed_attacks.list)

						goto label_463_1
					end
				end

				if sc and store.tick_ts - sc.ts >= sc.cooldown and (this.soldier.target_id == nil or this.soldier.target_id ~= nil and (not store.entities[this.soldier.target_id] or band(store.entities[this.soldier.target_id].vis.flags, F_BOSS) == 0)) then
					local t, targets, _ = U.find_foremost_enemy(store.entities, this.pos, 0, sc.detection_range, fts(20), 0, sc.bans, function(v, o)
						return v.id ~= this.soldier.target_id
					end)

					if not t or not targets or #targets == 0 or not this.motion.arrived then
						SU.delay_attack(store, sc, fts(10))
					else
						U.animation_start(this, sc.animation_in, t.pos.x < this.pos.x, store.tick_ts, false, 1)

						if SU.y_hero_wait(store, this, sc.dissapear_time) then
							goto label_463_1
						end

						S:queue(sc.sound)

						this.health_bar.hidden = true

						local mod

						if this.soldier.target_id ~= nil then
							mod = E:create_entity(sc.mod_stun)
							mod.modifier.source_id = this.id
							mod.modifier.target_id = this.soldier.target_id

							queue_insert(store, mod)
						end

						local bans = this.vis.bans

						this.vis.bans = F_ALL
						this.health.ignore_damage = true

						if mod ~= nil then
							local target = store.entities[this.soldier.target_id]
							local fx = E:create_entity(sc.fx_stun)
							local flip = this.render.sprites[1].flip_x and -1 or 1
							local posx = V.vclone(this.pos).x + this.melee.attacks[1].hit_offset.x * flip
							local posy = V.vclone(this.pos).y + this.melee.attacks[1].hit_offset.y

							fx.pos = v(posx, posy)
							fx.render.sprites[1].ts = store.tick_ts
							fx.render.sprites[1].flip_x = this.render.sprites[1].flip_x

							queue_insert(store, fx)
						end

						local t, targets, pred_pos = U.find_foremost_enemy(store.entities, this.pos, 0, sc.detection_range, fts(20), 0, sc.bans, function(v, o)
							return v.id ~= this.soldier.target_id
						end)

						if t then
							local b = E:create_entity(sc.bullet)

							b.bullet.target_id = t.id
							b.pos = V.vclone(this.pos)
							b.bullet.from = b.pos

							local flip = t.pos.x < this.pos.x and 1 or -1

							b.bullet.to = pred_pos
							b.bullet.to.x = pred_pos.x + flip * (t.unit.hit_offset.x + this.soldier.melee_slot_offset.x)
							b.bullet.to.y = pred_pos.y + t.unit.hit_offset.y + this.soldier.melee_slot_offset.y
							b.bullet.source_id = this.id

							if this.soldier.target_id ~= nil then
								b.blocked_id = this.soldier.target_id
							end

							queue_insert(store, b)

							while not this.end_skill_c do
								coroutine.yield()
							end

							SU.hero_gain_xp_from_skill(this, this.hero.skills.skill_c)
							talent_2_heal()
						else
							U.y_wait(store, fts(10))
						end

						this.end_skill_c = false
						this.health_bar.hidden = false
						this.vis.bans = bans
						this.health.ignore_damage = false

						U.animation_start(this, sc.animation_out, nil, store.tick_ts, false, 1)
						S:queue(this.sound_transformation_in, {
							delay = fts(8)
						})
						S:queue(this.sound_transformation_out, {
							delay = fts(28)
						})
						U.y_wait(store, sc.invincible_time)

						if mod ~= nil and store.entities[mod.id] then
							store.entities[mod.id].modifier.duration = 0
						end

						U.y_animation_wait(this)

						sc.ts = store.tick_ts

						apply_delayed_cooldowns(store, this.hero.throttled_cooldown, this.timed_attacks.list)

						goto label_463_1
					end
				end

				if sa and store.tick_ts - sa.ts >= sa.cooldown then
					local target, targets, pred_pos = U.find_foremost_enemy(store.entities, this.pos, sa.min_range, sa.max_range, sa.prediction, sa.vis_flags, sa.vis_bans)

					if not target or not this.motion.arrived then
						SU.delay_attack(store, sa, fts(10))
					else
						this.render.sprites[1].flip_x = target.pos.x < this.pos.x

						U.animation_start(this, sa.animation, nil, store.tick_ts, false, 1)

						if SU.y_hero_wait(store, this, sa.cast_time) then
							goto label_463_1
						end

						S:queue(sa.sound)

						local b = E:create_entity(sa.bullet)

						b.bullet.target_id = target.id
						b.bullet.source_id = this.id
						b.bullet.xp_dest_id = this.id
						b.pos.x, b.pos.y = this.pos.x + sa.offset.x, this.pos.y + sa.offset.y
						b.bullet.from = V.vclone(b.pos)
						b.bullet.to = v(pred_pos.x + target.unit.hit_offset.x, pred_pos.y + target.unit.hit_offset.y)

						queue_insert(store, b)

						local fx = E:create_entity(sa.fx)

						fx.render.sprites[1].ts = store.tick_ts
						fx.render.sprites[1].r = V.angleTo(this.pos.x, this.pos.y, target.pos.x, target.pos.y)
						fx.pos = V.vclone(b.pos)

						queue_insert(store, fx)
						SU.hero_gain_xp_from_skill(this, this.hero.skills.skill_a)
						talent_2_heal()

						sa.ts = store.tick_ts

						apply_delayed_cooldowns(store, this.hero.throttled_cooldown, this.timed_attacks.list)
						SU.y_hero_animation_wait(this)

						goto label_463_1
					end
				end
			end

			brk, sta = y_hero_melee_block_and_attacks(store, this)

			if not brk and sta == A_DONE then
				U.y_animation_play(this, "attack_out", nil, store.tick_ts, 1, 1)
			end

			if brk or sta ~= A_NO_TARGET then
				-- block empty
			elseif SU.soldier_go_back_step(store, this) then
				-- block empty
			else
				SU.soldier_idle(store, this)
				SU.soldier_regen(store, this)
			end
		end

		::label_463_1::

		coroutine.yield()
	end
end

scripts.fx_ignus_hit = {}

function scripts.fx_ignus_hit.insert(this, store, script)
	local source = store.entities[this.source_id]
	local flip = this.render.sprites[1].flip_x and -1 or 1
	local iht = this.hit_idx

	for i = 1, #this.render.sprites do
		this.render.sprites[i].ts = store.tick_ts
		this.render.sprites[i].flip_x = source.render.sprites[1].flip_x
	end

	if iht == 2 then
		for i = 1, #this.render.sprites do
			this.render.sprites[i].r = -math.pi / 4 * flip
		end

		this.pos.y = this.pos.y - 5
	end

	if iht == 3 then
		for i = 1, #this.render.sprites do
			this.render.sprites[i].r = math.pi / 4 * flip
		end

		this.pos.y = this.pos.y + 5
	end

	return true
end

scripts.bullet_ignus_skill_c = {}

function scripts.bullet_ignus_skill_c.update(this, store, script)
	local b = this.bullet
	local dist_y = math.abs(b.from.y - b.to.y)
	local mspeed = dist_y / b.travel_time - b.acceleration * b.travel_time * 0.5
	local prefix = 0
	local already_hit = {}

	if this.blocked_id then
		table.insert(already_hit, #already_hit + 1, this.blocked_id)
	end

	local ignus = store.entities[b.source_id]
	local hits = 0
	local original_pos = V.vclone(b.from)
	local original_flip = ignus.render.sprites[1].flip_x and -1 or 1

	original_pos.x = original_pos.x + this.return_offset.x * original_flip
	original_pos.y = original_pos.y + this.return_offset.y

	local function generate_return_points(startX, startY, endX, endY, arcHeight, side)
		local dx = endX - startX
		local dy = endY - startY
		local len = math.sqrt(dx * dx + dy * dy)
		local dirX = dx / len
		local dirY = dy / len
		local perpX = -dirY * side
		local perpY = dirX * side
		local p1x = startX + dx * 0.25 + perpX * arcHeight * 0.5
		local p1y = startY + dy * 0.25 + perpY * arcHeight * 0.5
		local p2x = startX + dx * 0.5 + perpX * arcHeight
		local p2y = startY + dy * 0.5 + perpY * arcHeight
		local p3x = startX + dx * 0.75 + perpX * arcHeight * 0.5
		local p3y = startY + dy * 0.75 + perpY * arcHeight * 0.5

		return {
			{
				weight = 1,
				x = startX,
				y = startY
			},
			{
				weight = 5,
				x = p1x,
				y = p1y
			},
			{
				weight = 10,
				x = p2x,
				y = p2y
			},
			{
				weight = 35,
				x = p3x,
				y = p3y
			},
			{
				weight = 1,
				x = endX,
				y = endY
			}
		}
	end

	local particle = E:create_entity(b.particles_name)

	particle.particle_system.track_id = this.id

	queue_insert(store, particle)

	::label_470_0::

	particle.particle_system.emit = true

	while V.dist(this.pos.x, this.pos.y, b.to.x, b.to.y) > mspeed * store.tick_length do
		mspeed = mspeed + 1 / FPS * b.acceleration
		mspeed = km.clamp(b.min_speed, b.max_speed, mspeed)
		b.speed.x, b.speed.y = V.mul(mspeed, V.normalize(b.to.x - this.pos.x, b.to.y - this.pos.y))
		this.pos.x, this.pos.y = this.pos.x + b.speed.x * store.tick_length, this.pos.y + b.speed.y * store.tick_length

		coroutine.yield()
	end

	this.pos.x, this.pos.y = b.to.x, b.to.y
	prefix = prefix + 1

	if prefix > 3 then
		prefix = 1
	end

	particle.particle_system.emit = false

	local p = E:create_entity(b.payload)

	p.pos = V.vclone(this.pos)
	p.render.sprites[1].prefix = "skill0" .. prefix .. "Def"
	p.render.sprites[1].ts = store.tick_ts
	p.render.sprites[1].flip_x = ignus.render.sprites[1].flip_x
	p.ignus = ignus
	p.target_id = b.target_id

	queue_insert(store, p)
	U.y_wait(store, fts(8))
	table.insert(already_hit, #already_hit + 1, b.target_id)

	hits = hits + 1

	local t, targets, pred_pos = U.find_foremost_enemy(store.entities, this.pos, 0, this.bounce_range, fts(20), 0, this.bans, function(e, o)
		local result = true

		for k, v in pairs(already_hit) do
			if e.id == v then
				result = false
			end
		end

		return result
	end)

	if t and hits < this.max_hits then
		b.target_id = t.id

		local flip = t.pos.x < this.pos.x and 1 or -1

		b.to = pred_pos
		b.to.x = pred_pos.x + flip * (t.unit.hit_offset.x + ignus.soldier.melee_slot_offset.x)
		b.to.y = pred_pos.y + t.unit.hit_offset.y + ignus.soldier.melee_slot_offset.y
		b.from = V.vclone(this.pos)

		goto label_470_0
	end

	particle.particle_system.emit = true

	local points = generate_return_points(this.pos.x, this.pos.y, original_pos.x, original_pos.y, 50, original_flip)
	local curve = generate_bezier_curve(points, 6)
	local dr = E:create_entity(this.decal_return)

	dr.pos = V.vclone(this.pos)
	dr.render.sprites[1].flip_x = this.pos.x < original_pos.x
	dr.render.sprites[1].ts = store.tick_ts

	queue_insert(store, dr)

	for k, v in pairs(curve) do
		b.to = v

		while V.dist(this.pos.x, this.pos.y, b.to.x, b.to.y) > mspeed * store.tick_length do
			mspeed = mspeed + 1 / FPS * b.acceleration
			mspeed = km.clamp(b.min_speed, b.max_speed, mspeed)
			b.speed.x, b.speed.y = V.mul(mspeed, V.normalize(b.to.x - this.pos.x, b.to.y - this.pos.y))
			this.pos.x, this.pos.y = this.pos.x + b.speed.x * store.tick_length, this.pos.y + b.speed.y * store.tick_length

			coroutine.yield()
		end
	end

	particle.particle_system.source_lifetime = 0
	this.pos.x = original_pos.x
	this.pos.y = original_pos.y
	ignus.end_skill_c = true

	queue_remove(store, this)
end

scripts.decal_ignus_hit_skill_c = {}

function scripts.decal_ignus_hit_skill_c.update(this, store, script)
	U.y_wait(store, this.hit_time)

	local d = E:create_entity("damage")

	d.source_id = this.id
	d.target_id = this.target_id
	d.value = math.random(this.damage_min * this.ignus.unit.damage_factor, this.damage_max * this.ignus.unit.damage_factor)
	d.damage_type = this.damage_type

	queue_damage(store, d)

	local decal = E:create_entity(this.hit_fx)

	decal.render.sprites[1].ts = store.tick_ts
	decal.render.sprites[1].flip_x = this.render.sprites[1].flip_x
	decal.pos.x, decal.pos.y = V.add(this.pos.x, this.pos.y, this.hit_offset.x, this.hit_offset.y)

	queue_insert(store, decal)
	S:queue(this.sound)
	U.y_animation_wait(this)
	queue_remove(store, this)
end

scripts.hero_oni = {}

function scripts.hero_oni.level_up(this, store, initial)
	if not initial then
		S:queue(this.sound_events.level_up)
	end

	local hl = this.hero.level
	local ls = this.hero.level_stats

	this.health.hp_max = ls.hp_max[hl]
	this.regen.health = ls.regen_health[hl]
	this.health.armor = ls.armor[hl]
	this.melee.attacks[1].damage_min = ls.melee_damage_min[hl]
	this.melee.attacks[1].damage_max = ls.melee_damage_max[hl]
	this.melee.attacks[2].damage_min = ls.melee_damage_min[hl] * this.hero.skills.talent_1.damage_factor
	this.melee.attacks[2].damage_max = ls.melee_damage_max[hl] * this.hero.skills.talent_1.damage_factor

	if not this.hero.skills.talent_2.disabled then
		this.melee.attacks[1].mod = this.hero.skills.talent_2.lifesteal_mod_pre .. hl
	end

	this.health.hp = this.health.hp_max
	this.hero.melee_active_status = {}

	for index, attack in ipairs(this.melee.attacks) do
		this.hero.melee_active_status[index] = attack.disabled
	end
end

function scripts.hero_oni.fn_can_skill_a(this, store, a, target)
	local sa = not this.timed_attacks.list[1].disabled and this.timed_attacks.list[1] or nil

	return sa and not sa.disabled and store.tick_ts - sa.ts > sa.cooldown
end

function scripts.hero_oni.fn_can_talent_1(this, store, a, target)
	if this.hero.skills.talent_1.disabled then
		return false
	end

	if this.used_skill then
		this.used_skill = false

		return true
	else
		return false
	end
end

function scripts.hero_oni.insert(this, store)
	this.hero.fn_level_up(this, store, true)

	this.melee.order = {
		3,
		2,
		1
	}
	this.timed_attacks.list[4].disabled = not this.hero.skills.ultimate.active

	return true
end

function scripts.hero_oni.update(this, store)
	local h = this.health
	local brk, sta
	local old_tombstone_time = this.hero.tombstone_show_time
	local old_tombstone_respawn_animation = this.hero.tombstone_respawn_animation

	this.health_bar.hidden = false

	local sa = not this.timed_attacks.list[1].disabled and this.timed_attacks.list[1] or nil

	if sa then
		sa.ts = store.tick_ts - sa.cooldown
	end

	local sb = not this.timed_attacks.list[2].disabled and this.timed_attacks.list[2] or nil

	if sb then
		sb.ts = store.tick_ts - sb.cooldown
	end

	local sc = not this.timed_attacks.list[3].disabled and this.timed_attacks.list[3] or nil

	if sc then
		sc.ts = store.tick_ts - sc.cooldown
	end

	local ult = not this.timed_attacks.list[4].disabled and this.timed_attacks.list[4] or nil

	if ult then
		ult.ts = store.tick_ts - ult.cooldown
	end

	local ult_start_cd = ult ~= nil and store.wave_group_number == 0
	local t1 = not this.hero.skills.talent_1.disabled and this.hero.skills.talent_1 or nil
	local t2 = not this.hero.skills.talent_2.disabled and this.hero.skills.talent_2 or nil
	local lifesteal_mod = t2 and t2.lifesteal_mod

	this.blocking_time_ts = store.tick_ts

	local blocked_id
	local SKILL_A_ATTACK = 3
	local TALENT_1_ATTACK = 2

	this.melee.attacks[SKILL_A_ATTACK].disabled = sa == nil
	this.melee.attacks[TALENT_1_ATTACK].disabled = t1 == nil

	local function spawn_swords(count, center, radius, angle, delay, decal)
		for i = 1, count do
			local p = U.point_on_ellipse(center, radius - math.random(0, 5), angle + i * 2 * math.pi / count)
			local e = E:create_entity(decal)

			e.pos.x, e.pos.y = p.x, p.y
			e.render.sprites[1].ts = store.tick_ts

			queue_insert(store, e)
		end
	end

	while true do
		if ult_start_cd and store.wave_group_number > 0 then
			ult_start_cd = false
			ult.ts = store.tick_ts
		end

		if h.dead then
			local spawn_decal = true

			if band(h.last_damage_types, bor(DAMAGE_EAT)) ~= 0 then
				this.hero.tombstone_show_time = nil
				this.hero.tombstone_respawn_animation = nil
				spawn_decal = false
			end

			if spawn_decal then
				local decal_respawn = E:create_entity(this.decal_respawn)

				decal_respawn.pos = V.vclone(this.pos)
				decal_respawn.delay = this.health.dead_lifetime + fts(25)
				decal_respawn.flip_x = this.render.sprites[1].flip_x or false

				queue_insert(store, decal_respawn)
			end

			SU.y_hero_death_and_respawn_kr5(store, this)

			this.hero.tombstone_show_time = old_tombstone_time
			this.hero.tombstone_respawn_animation = old_tombstone_respawn_animation
		end

		if this.unit.is_stunned then
			SU.soldier_idle(store, this)
		else
			while this.nav_rally.new do
				if SU.y_hero_new_rally(store, this) then
					goto label_478_2
				end
			end

			if SU.hero_level_up(store, this) then
				U.y_animation_play(this, "lvlup", nil, store.tick_ts, 1)
			end

			brk, sta = y_hero_melee_block_and_attacks(store, this)

			if sta == A_DONE then
				local last = this.melee.last_attack and this.melee.last_attack.attack

				if last == this.melee.attacks[SKILL_A_ATTACK] then
					sa.ts = store.tick_ts

					apply_delayed_cooldowns(store, this.hero.throttled_cooldown, this.timed_attacks.list)

					this.used_skill = true
				end

				SU.soldier_idle(store, this)
			end

			if ult and store.tick_ts - ult.ts > ult.cooldown then
				local _, triggers = U.find_foremost_enemy(store.entities, this.pos, 0, ult.max_range, ult.prediction, ult.flags, ult.bans)

				if not triggers or #triggers < ult.min_targets then
					SU.delay_attack(store, ult, fts(10))
				else
					S:queue(ult.sound)
					S:queue(ult.taunt)
					U.animation_start(this, ult.animation_in, this.render.sprites[1].flip_x, store.tick_ts, false, 1)

					if SU.y_hero_wait(store, this, ult.cast_time) then
						S:stop(ult.sound)

						goto label_478_2
					end

					U.animation_start(this, ult.animation_loop, this.render.sprites[1].flip_x, store.tick_ts, true, 1)

					local flip = this.render.sprites[1].flip_x and -1 or 1
					local pos_x, pos_y = V.vclone(this.pos).x + ult.offset * flip, V.vclone(this.pos).y
					local decal_ground = E:create_entity(ult.decal_ground)

					decal_ground.pos = v(pos_x, pos_y)
					decal_ground.render.sprites[1].ts = store.tick_ts

					queue_insert(store, decal_ground)

					local decal_aura = E:create_entity(ult.decal_aura)

					decal_aura.pos = v(pos_x, pos_y)
					decal_aura.render.sprites[1].ts = store.tick_ts

					queue_insert(store, decal_aura)
					U.y_wait(store, fts(2))

					local aura = E:create_entity(ult.aura)

					aura.pos = V.vclone(this.pos)

					queue_insert(store, aura)

					for _, s in pairs(ult.torment_swords) do
						local d, r, c = unpack(s)

						spawn_swords(c, v(pos_x, pos_y), r, math.random(0, 2) * math.pi, d, ult.decal_swords[math.random(1, 2)])
						U.y_wait(store, fts(1))
					end

					U.y_wait(store, ult.duration)
					SU.hero_gain_xp_from_skill(this, this.hero.skills.ultimate)
					U.y_animation_play(this, ult.animation_out, this.render.sprites[1].flip_x, store.tick_ts, 1, 1)

					ult.ts = store.tick_ts

					apply_delayed_cooldowns(store, this.hero.throttled_cooldown, this.timed_attacks.list)

					this.used_skill = true

					goto label_478_2
				end
			end

			if sb and store.tick_ts - sb.ts > sb.cooldown and h.hp <= h.hp_max * sb.threshold then
				S:queue(sb.sound, sb.sound_args)
				U.animation_start(this, sb.animation, this.render.sprites[1].flip_x, store.tick_ts, false, 1)
				S:queue(sb.sound)

				local ts = store.tick_ts

				if SU.y_hero_wait(store, this, sb.cast_time) then
					goto label_478_2
				end

				local mod = E:create_entity(sb.mod)

				mod.modifier.source_id = this.id
				mod.modifier.target_id = this.id
				mod.hps.heal_min = h.hp_max * sb.heal_ptg
				mod.hps.heal_max = h.hp_max * sb.heal_ptg

				queue_insert(store, mod)
				SU.hero_gain_xp_from_skill(this, this.hero.skills.skill_b)

				local heal_start_ts = store.tick_ts

				while store.tick_ts - ts < sb.duration - sb.cast_time do
					if SU.soldier_interrupted(this) then
						if store.entities[mod.id] then
							queue_remove(store, mod)
						end

						if store.tick_ts - heal_start_ts < sb.cancel_time_refund then
							goto label_478_1
						else
							goto label_478_0
						end
					end

					coroutine.yield()
				end

				U.animation_start(this, "idle", this.render.sprites[1].flip_x, store.tick_ts, true, 1)

				::label_478_0::

				sb.ts = store.tick_ts

				::label_478_1::

				apply_delayed_cooldowns(store, this.hero.throttled_cooldown, this.timed_attacks.list)

				this.used_skill = true

				goto label_478_2
			end

			if sc and store.tick_ts - sc.ts > sc.cooldown then
				local t, _, pred_pos = U.find_foremost_enemy(store.entities, this.pos, sc.min_detection_range, sc.detection_range, sc.prediction, sc.flags, sc.bans)

				if not t then
					SU.delay_attack(store, sc, fts(10))
				else
					U.animation_start(this, sc.animation_in, this.pos.x > t.pos.x, store.tick_ts, false, 1)

					this.health_bar.hidden = true

					S:queue(sc.sound)

					if SU.y_hero_wait(store, this, sc.decal_cast_time) then
						goto label_478_2
					end

					local mod

					if this.soldier.target_id ~= nil then
						mod = E:create_entity(sc.mod_stun)
						mod.modifier.source_id = this.id
						mod.modifier.target_id = this.soldier.target_id

						queue_insert(store, mod)
					end

					local bans = this.vis.bans

					this.vis.bans = F_ALL
					this.health.ignore_damage = true

					local decal = E:create_entity(sc.decal_cast)

					decal.render.sprites[1].ts = store.tick_ts
					decal.pos = V.vclone(this.pos)

					queue_insert(store, decal)
					U.y_wait(store, sc.disappear_time)

					local flip = t.pos.x < this.pos.x and 1 or -1
					local pos_x = t.pos.x + flip * (t.unit.hit_offset.x + 50)
					local pos_y = t.pos.y
					local d = E:create_entity(sc.decal)

					d.pos = v(pos_x, pos_y)
					d.oni = this
					d.target_id = t.id
					d.render.sprites[1].ts = store.tick_ts

					queue_insert(store, d)

					while not this.end_skill_c do
						coroutine.yield()
					end

					SU.hero_gain_xp_from_skill(this, this.hero.skills.skill_c)

					this.end_skill_c = false
					this.health_bar.hidden = false
					this.vis.bans = bans
					this.health.ignore_damage = false

					U.animation_start(this, sc.animation_out, nil, store.tick_ts, false, 1)
					U.y_wait(store, sc.invincible_time)

					if mod ~= nil and store.entities[mod.id] then
						store.entities[mod.id].modifier.duration = 0
					end

					U.y_animation_wait(this)

					this.used_skill = true
					sc.ts = store.tick_ts

					apply_delayed_cooldowns(store, this.hero.throttled_cooldown, this.timed_attacks.list)

					goto label_478_2
				end
			end

			if this.soldier.target_id ~= nil then
				if blocked_id == nil then
					blocked_id = this.soldier.target_id
				end

				if blocked_id ~= this.soldier.target_id then
					this.blocking_time_ts = store.tick_ts
					blocked_id = this.soldier.target_id
				end
			else
				blocked_id = nil
				this.blocking_time_ts = store.tick_ts
			end

			if brk or sta ~= A_NO_TARGET then
				-- block empty
			elseif SU.soldier_go_back_step(store, this) then
				-- block empty
			else
				SU.soldier_idle(store, this)
				SU.soldier_regen(store, this)
			end
		end

		::label_478_2::

		coroutine.yield()
	end
end

scripts.mod_oni_lifesteal_talent_2 = {}

function scripts.mod_oni_lifesteal_talent_2.insert(this, store, script)
	local source = store.entities[this.modifier.source_id]

	if source and source.health and store.tick_ts - source.blocking_time_ts >= this.block_time then
		source.health.hp = km.clamp(0, source.health.hp_max, source.health.hp + this.heal_hp)
	end

	return false
end

scripts.decals_oni = {}

function scripts.decals_oni.update(this, store, script)
	if this.delay then
		U.y_wait(store, this.delay)
	end

	for _, v in pairs(this.decals) do
		local d = E:create_entity(v)

		d.render.sprites[1].ts = store.tick_ts
		d.render.sprites[1].flip_x = this.flip_x
		d.pos = V.vclone(this.pos)

		queue_insert(store, d)
	end

	queue_remove(store, this)
end

scripts.decal_oni_skill_c = {}

function scripts.decal_oni_skill_c.update(this, store, script)
	local first = true
	local target = store.entities[this.target_id]

	if not target then
		this.oni.end_skill_c = true

		queue_remove(store, this)

		return
	end

	U.animation_start(this, this.render.sprites[1].name, this.pos.x > target.pos.x, store.tick_ts, false, 1, true)

	for i, v in pairs(this.hit_times) do
		U.y_wait(store, v)

		if first then
			first = false

			local mod = E:create_entity(this.mod_stun)

			mod.modifier.source_id = this.id
			mod.modifier.target_id = this.target_id
			mod.modifier.duration = fts(26)

			queue_insert(store, mod)
			S:queue(this.sound_hit)
		end

		local d = E:create_entity("damage")

		d.source_id = this.oni.id
		d.target_id = this.target_id
		d.value = math.random(this.damage_min[i] * this.oni.unit.damage_factor, this.damage_max[i] * this.oni.unit.damage_factor)
		d.damage_type = this.damage_type

		queue_damage(store, d)

		local mod = E:create_entity(this.mod_armor_sunder)

		mod.modifier.source_id = this.oni.id
		mod.modifier.target_id = this.target_id

		queue_insert(store, mod)

		local decal = E:create_entity(this.hit_fx)

		decal.render.sprites[1].ts = store.tick_ts
		decal.render.sprites[1].flip_x = this.render.sprites[1].flip_x
		decal.pos.x, decal.pos.y = V.add(this.pos.x, this.pos.y, this.hit_offset.x * (this.render.sprites[1].flip_x and -1 or 1), this.hit_offset.y)

		queue_insert(store, decal)
	end

	S:queue(this.sound_out)
	U.y_animation_wait(this)

	this.oni.end_skill_c = true

	queue_remove(store, this)
end

scripts.hero_illiana = {}

function scripts.hero_illiana.level_up(this, store, initial)
	if not initial then
		S:queue(this.sound_events.level_up)
	end

	local hl = this.hero.level
	local ls = this.hero.level_stats

	this.health.hp_max = ls.hp_max[hl]
	this.regen.health = ls.regen_health[hl]
	this.health.armor = ls.armor[hl]
	this.melee.attacks[1].damage_min = ls.melee_damage_min[hl]
	this.melee.attacks[1].damage_max = ls.melee_damage_max[hl]

	local bt = E:get_template(this.ranged.attacks[1].bullet)

	bt.bullet.damage_min = ls.ranged_damage_min[hl]
	bt.bullet.damage_max = ls.ranged_damage_max[hl]

	if this.dragon then
		local dbt = E:get_template(this.dragon.ranged.attacks[1].bullet)

		dbt.bullet.damage_min = this.dragon_ranged_damage_min[hl]
		dbt.bullet.damage_max = this.dragon_ranged_damage_max[hl]
	end

	this.health.hp = this.health.hp_max
	this.hero.melee_active_status = {}

	for index, attack in ipairs(this.melee.attacks) do
		this.hero.melee_active_status[index] = attack.disabled
	end
end

function scripts.hero_illiana.insert(this, store)
	this.dragon = E:create_entity(this.dragon_t)
	this.dragon.id_illiana = this.id
	this.dragon.pos = V.vclone(this.pos)

	queue_insert(store, this.dragon)
	this.hero.fn_level_up(this, store, true)

	this.melee.order = U.attack_order(this.melee.attacks)
	this.ranged.order = U.attack_order(this.ranged.attacks)
	this.timed_attacks.list[3].disabled = not this.hero.skills.ultimate.active

	return true
end

function scripts.hero_illiana.update(this, store)
	local h = this.health
	local brk, sta

	this.health_bar.hidden = false

	local casting_ult = false
	local tr = this.transfer
	local ps
	local original_damage_factor = this.unit.damage_factor
	local transfering = false
	local og_z = this.render.sprites[1].z
	local og_animation = this.ranged.attacks[1].animation
	local vis_bans = this.vis.bans
	local prev_immune = this.health.immune_to
	local old_damage_factor = this.unit.damage_factor
	local n = this.nav_grid
	local ska = not this.timed_attacks.list[1].disabled and this.timed_attacks.list[1] or nil
	local skb = not this.timed_attacks.list[2].disabled and this.timed_attacks.list[2] or nil

	if skb then
		skb.ts = store.tick_ts - skb.cooldown
	end

	local ult = not this.timed_attacks.list[3].disabled and this.timed_attacks.list[3] or nil

	if ult then
		ult.ts = store.tick_ts - ult.cooldown
	end

	local ult_start_cd = ult ~= nil and store.wave_group_number == 0
	local t2 = not this.hero.skills.talent_2.disabled and this.hero.skills.talent_2 or nil

	this.can_transfer = true
	this.teleport.disabled = false

	local function find_most_populated_path(enemies, min_enemies)
		local paths_count = {}
		local found_paths = {}

		for k, v in pairs(enemies) do
			if not table.contains(found_paths, v.nav_path.pi) then
				table.insert(found_paths, v.nav_path.pi)
				table.insert(paths_count, {
					v.nav_path.pi,
					1
				})
			else
				local i = index_at(paths_count, v, function(tv, iv)
					return iv.nav_path.pi == tv[1]
				end)

				paths_count[i][2] = paths_count[i][2] + 1
			end
		end

		table.sort(paths_count, function(v1, v2)
			return v1[2] > v2[2]
		end)

		return paths_count
	end

	local function sort_paths_by_distance(paths, min_distance)
		local available_paths = table.filter(paths, function(k, v)
			local count = 0
			local n = P:nearest_nodes(this.pos.x, this.pos.y, {
				v[1]
			})[1][3]
			local first_node = P:get_visible_start_node(v)

			for i = 0, min_distance do
				if first_node <= n - i then
					return true
				end

				if P:is_node_valid(v, first_node < n - i and n - i or first_node, 0) and not table.contains(store.level.ignore_walk_backwards_paths, v[1]) then
					count = count + 1

					if count >= min_distance then
						return true
					end
				else
					return false
				end
			end
		end)

		return available_paths
	end

	local function y_illiana_death_and_respawn_kr5(store, this)
		local h = this.health
		local he = this.hero

		this.ui.can_click = false

		local death_ts = store.tick_ts
		local dead_lifetime = h.dead_lifetime

		U.unblock_target(store, this)

		if this.selfdestruct and not this.selfdestruct.disabled and band(h.last_damage_types, bor(DAMAGE_EAT, DAMAGE_HOST, DAMAGE_DISINTEGRATE_BOSS)) == 0 then
			local sd = this.selfdestruct

			this.unit.hide_after_death = true
			this.health_bar.hidden = true
			dead_lifetime = sd.dead_lifetime or dead_lifetime

			U.animation_start(this, sd.animation, nil, store.tick_ts)
			S:queue(this.sound_events.death, this.sound_events.death_args)
			S:queue(sd.sound, sd.sound_args)
			U.y_wait(store, sd.hit_time)
			S:queue(sd.sound_hit)

			if sd.hit_fx then
				SU.insert_sprite(store, sd.hit_fx, this.pos)
			end

			if sd.xp_from_skill then
				SU.hero_gain_xp_from_skill(this, this.hero.skills[sd.xp_from_skill])
			end

			local targets = U.find_enemies_in_range(store.entities, this.pos, 0, sd.damage_radius, sd.vis_flags, sd.vis_bans)

			if targets then
				for _, t in pairs(targets) do
					local d = E:create_entity("damage")

					d.damage_type = sd.damage_type
					d.value = sd.damage and sd.damage or math.random(sd.damage_min, sd.damage_max)
					d.source_id = this.id
					d.target_id = t.id

					queue_damage(store, d)
				end
			end

			U.y_animation_wait(this)
		elseif band(h.last_damage_types, bor(DAMAGE_DISINTEGRATE_BOSS)) ~= 0 then
			this.unit.hide_after_death = true

			local fx = E:create_entity("fx_soldier_desintegrate")

			fx.pos.x, fx.pos.y = this.pos.x, this.pos.y
			fx.render.sprites[1].ts = store.tick_ts

			queue_insert(store, fx)
		elseif band(h.last_damage_types, bor(DAMAGE_EAT)) ~= 0 then
			this.unit.hide_after_death = true
		elseif band(h.last_damage_types, bor(DAMAGE_HOST)) ~= 0 then
			this.unit.hide_after_death = true

			S:queue("DeathEplosion")

			local fx = E:create_entity("fx_unit_explode")

			fx.pos.x, fx.pos.y = this.pos.x, this.pos.y
			fx.render.sprites[1].ts = store.tick_ts
			fx.render.sprites[1].name = fx.render.sprites[1].size_names[this.unit.size]

			queue_insert(store, fx)

			if this.unit.show_blood_pool and this.unit.blood_color ~= BLOOD_NONE then
				local decal = E:create_entity("decal_blood_pool")

				decal.pos = V.vclone(this.pos)
				decal.render.sprites[1].ts = store.tick_ts
				decal.render.sprites[1].name = this.unit.blood_color

				queue_insert(store, decal)
			end
		else
			S:queue(this.sound_events.death, this.sound_events.death_args)

			if this.unit.death_animation then
				U.animation_start(this, this.unit.death_animation, nil, store.tick_ts, false)
			else
				U.animation_start(this, "death", nil, store.tick_ts, false)
			end
		end

		if not he.tombstone_concurrent_with_death then
			if not U.flag_has(h.last_damage_types, bor(DAMAGE_EAT, DAMAGE_DISINTEGRATE_BOSS)) then
				U.y_animation_wait(this)
			end

			this.health.death_finished_ts = store.tick_ts

			if this.unit.hide_after_death then
				for _, s in pairs(this.render.sprites) do
					s.hidden = true
				end
			end
		end

		local tombstone

		if he and he.tombstone_show_time then
			while store.tick_ts - death_ts < he.tombstone_show_time do
				coroutine.yield()
			end

			tombstone = E:create_entity(he.tombstone_decal)

			if he.tombstone_force_over_path then
				local nodes = P:nearest_nodes(this.pos.x, this.pos.y, nil, {
					1,
					2,
					3
				}, true)
				local pi, spi, ni = unpack(nodes[1])
				local npos = P:node_pos(pi, spi, ni)

				tombstone.pos = npos
			else
				tombstone.pos = this.pos
			end

			for _, s in pairs(tombstone.render.sprites) do
				s.ts = store.tick_ts
				s.flip_x = this.render.sprites[1].flip_x
			end

			queue_insert(store, tombstone)
		end

		if he.tombstone_concurrent_with_death then
			if not U.flag_has(h.last_damage_types, bor(DAMAGE_EAT, DAMAGE_DISINTEGRATE_BOSS)) then
				U.y_animation_wait(this)
			end

			this.health.death_finished_ts = store.tick_ts
		end

		if this.unit.hide_after_death then
			for _, s in pairs(this.render.sprites) do
				s.hidden = true
			end
		end

		while dead_lifetime > store.tick_ts - death_ts do
			if this.trigger_death_animation then
				U.animation_start(this, "death_dragon_in", nil, store.tick_ts, false, 1)

				this.trigger_death_animation = false
			end

			if this.force_respawn then
				this.force_respawn = nil

				break
			end

			coroutine.yield()
		end

		this.health.death_finished_ts = nil

		if he and he.tombstone_force_over_path then
			he.respawn_point = tombstone.pos
		end

		if tombstone and tombstone.tween then
			tombstone.tween.disabled = false
			tombstone.tween.ts = store.tick_ts
		end

		if he and he.tombstone_respawn_animation then
			U.animation_start(tombstone, he.tombstone_respawn_animation, nil, store.tick_ts)
		end

		if he and he.respawn_point then
			local p = he.respawn_point

			this.pos.x, this.pos.y = p.x, p.y
			this.nav_rally.pos.x, this.nav_rally.pos.y = p.x, p.y
			this.nav_rally.center.x, this.nav_rally.center.y = p.x, p.y
			this.nav_rally.new = false
		end

		for _, s in pairs(this.render.sprites) do
			if this.use_hidden_count_on_respawn and s.hidden_count then
				s.hidden = s.hidden_count > 0
			else
				s.hidden = false
			end
		end

		h.ignore_damage = true

		S:queue(this.sound_events.respawn)

		if he.remove_tombstone_before_respawn and tombstone then
			queue_remove(store, tombstone)

			tombstone = nil
		end

		h.dead = false

		U.animation_start(this, this.respawn_animation, nil, store.tick_ts, false, 1)

		this.dragon.trigger_respawn_animation = true
		this.trigger_death_animation = false

		if tombstone then
			queue_remove(store, tombstone)
		end

		this.health_bar.hidden = false
		this.ui.can_click = true
		this.force_respawn = nil
		h.hp = h.hp_max
		h.ignore_damage = false

		U.y_animation_wait(this)
	end

	local function illiana_will_transfer(this, new_rally_pos)
		local r = new_rally_pos

		return tr and not tr.disabled and V.dist(r.x, r.y, this.pos.x, this.pos.y) > tr.min_distance
	end

	local function mount_start()
		U.animation_start(this, "walk_2_in", this.dragon.render.sprites[1].flip_x, this.mount_ts - this.dragon.pickup_contact_time, false, 1, true)
	end

	local function mount_finish()
		this.render.sprites[1].hidden = true
		this.pos = this.dragon.pos
		this.motion.speed.x, this.motion.speed.y = 0, 0
		n.waypoints = {}

		if tr.particles_name then
			ps = E:create_entity(tr.particles_name)
			ps.particle_system.track_id = this.id

			queue_insert(store, ps)
		end

		if t2 then
			this.unit.damage_factor = t2.damage_factor
		end

		this.ranged.attacks[1].animation = "walk_2_attack"
		transfering = true
	end

	local function ride_begin()
		this.render.sprites[1].prefix = "hero_illiana_walk2Def"
		this.render.sprites[1].offset = v(0, this.dragon.flight_height)
		this.render.sprites[1].z = Z_FLYING_HEROES
		this.dragon.render.sprites[1].z = Z_FLYING_HEROES

		U.animation_start(this, "walk_2", nil, this.ride_anim_ts, true, 1, true)

		this.render.sprites[1].hidden = false
	end

	local function mount_abort()
		this.mount_ts = nil
		this.ride_anim_ts = nil
		this.render.sprites[1].hidden = false
		this.dragon.cancel_transfer = true
	end

	local function transfer_out()
		if not transfering then
			return
		end

		this.pos = V.vclone(this.pos)
		this.unit.damage_factor = old_damage_factor
		this.ride_anim_ts = nil

		if tr.particles_name then
			ps.particle_system.emit = false
			ps.particle_system.source_lifetime = 1
		end

		this.render.sprites[1].prefix = "hero_illianaDef"
		this.render.sprites[1].offset = v(0, 0)
		this.render.sprites[1].z = og_z
		this.render.sprites[1].hidden = false
		this.dragon.render.sprites[1].z = og_z
		this.ranged.attacks[1].animation = og_animation
		transfering = false

		U.animation_start(this, "walk_2_out", nil, store.tick_ts, false, 1, true)

		while not U.animation_finished(this, 1) do
			if this.nav_rally.new or this.health.dead and not this.health.ignore_damage then
				break
			end

			coroutine.yield()
		end
	end

	local function y_illiana_walk()
		local animation = "walk"
		local r = this.nav_rally
		local dest = r.pos
		local want_ride = false
		local mounting = false
		local last_af, w, unsnap
		local x_to_flip = IS_SEQUEL and 2 or 0
		local og_vis_bans = this.vis.bans
		local og_immune_to = this.health.immune_to

		::label_498_0::

		dest = r.pos
		r.new = false
		w, unsnap = nil
		this.transfer_arrived = false

		U.unblock_target(store, this)

		if this.sound_events then
			S:queue(this.sound_events.change_rally_point)
		end

		this.vis.bans = F_ALL
		this.health.immune_to = r.immune_to

		if transfering then
			this.dragon.ride_to = dest
			this.dragon.carry_to = dest
		else
			want_ride = illiana_will_transfer(this, dest)

			local wp = GR:find_waypoints(this.pos, nil, dest, n.valid_terrains, true)

			n.waypoints = wp and table.deepclone(wp) or {}

			if mounting and not want_ride then
				mounting = false

				mount_abort()
			end

			if mounting then
				this.dragon.ride_to = dest
			else
				this.dragon.ride_to = want_ride and dest or nil
				this.dragon.chase = want_ride

				if not want_ride then
					this.dragon.cancel_transfer = true
				end
			end
		end

		while not V.veq(this.pos, dest) and not this.transfer_arrived do
			if this.health.dead and not this.health.ignore_damage then
				break
			end

			if r.new then
				goto label_498_0
			end

			if this.mount_ts and not mounting then
				mounting = true

				mount_start()
			end

			if transfering then
				if this.ride_anim_ts and store.tick_ts >= this.ride_anim_ts then
					ride_begin()

					this.ride_anim_ts = nil
				end

				if not this.render.sprites[1].hidden then
					local target, attack, pred_pos = SU.soldier_pick_ranged_target_and_attack(store, this)

					if target and attack then
						SU.y_soldier_do_ranged_attack(store, this, target, attack, pred_pos)
					end
				end
			elseif mounting and store.tick_ts >= this.mount_ts then
				mounting = false
				this.mount_ts = nil

				mount_finish()
			else
				if not w or this.motion.arrived then
					w = table.remove(n.waypoints, 1) or dest
					unsnap = #n.waypoints > 0

					U.set_destination(this, w)

					if not mounting then
						local an, af = U.animation_name_facing_point(this, animation, this.motion.dest)
						local new_af = af

						if last_af and x_to_flip > math.abs(this.pos.x - this.motion.dest.x) then
							new_af = last_af
						end

						U.animation_start(this, an, new_af, store.tick_ts, true)

						last_af = new_af
					end
				end

				U.walk(this, store.tick_length, nil, unsnap)

				this.motion.speed.x, this.motion.speed.y = 0, 0

				if this.motion.arrived and #n.waypoints == 0 then
					if mounting then
						mounting = false

						mount_abort()
						U.animation_start(this, "idle", nil, store.tick_ts, true)
					end

					break
				end
			end

			coroutine.yield()
		end

		this.dragon.chase = false

		if mounting then
			mounting = false

			mount_abort()
		end

		if not transfering or this.health.dead then
			this.dragon.cancel_transfer = true
		end

		transfer_out()

		this.motion.speed.x, this.motion.speed.y = 0, 0
		this.motion.arrived = false
		this.vis.bans = og_vis_bans
		this.health.immune_to = og_immune_to
	end

	local function y_illiana_walk_waypoints(store, this, animation)
		local animation = animation or "walk"
		local r = this.nav_rally
		local n = this.nav_grid
		local dest = r.pos

		this.dragon.max_speed = this.motion.max_speed + this.transfer.extra_speed

		local old_damage_factor = this.unit.damage_factor

		if t2 then
			this.unit.damage_factor = t2.damage_factor
		end

		local og_animation = this.ranged.attacks[1].animation

		this.ranged.attacks[1].animation = "walk_2_attack"
		this.pos = this.dragon.pos

		local function update_shadow(store, this)
			local has_no_shadow = GR:cell_is(this.pos.x, this.pos.y, TERRAIN_NO_SHADOW)
			local target_alpha = has_no_shadow and 0 or 255

			this.render.sprites[this.render.sid_shadow].hidden = has_no_shadow
		end

		::label_499_0::

		dest = r.pos
		this.dragon.transfer_dest = dest
		this.transfer_arrived = false

		while not this.transfer_arrived do
			if this.health.dead and not this.health.ignore_damage then
				break
			end

			if r.new then
				r.new = false

				goto label_499_0
				break
			end

			if this.render.sid_shadow then
				update_shadow(store, this)
			end

			local target, attack, pred_pos = SU.soldier_pick_ranged_target_and_attack(store, this)

			if target and attack then
				SU.y_soldier_do_ranged_attack(store, this, target, attack, pred_pos)
			end

			coroutine.yield()
		end

		this.motion.speed.x, this.motion.speed.y = 0, 0
		this.motion.arrived = false
		r.new = false
		this.unit.damage_factor = old_damage_factor
		this.ranged.attacks[1].animation = og_animation
		this.pos = V.vclone(this.dragon.pos)
	end

	local function y_illiana_new_rally(store, this)
		local r = this.nav_rally

		if r.new then
			r.new = false

			U.unblock_target(store, this)

			if this.sound_events then
				S:queue(this.sound_events.change_rally_point)
			end

			if illiana_will_transfer(this, r.pos) then
				local tr = this.transfer
				local interrupt = false
				local ps
				local vis_bans = this.vis.bans

				this.vis.bans = F_ALL
				this.health.ignore_damage = true
				this.dragon.transfer = true

				while not this.begin_transfer do
					coroutine.yield()
				end

				this.begin_transfer = false
				this.dragon.start_transfer_anim = true

				U.y_animation_play(this, "walk_2_in", this.dragon.flip_x, store.tick_ts, 1, 1)

				this.render.sprites[1].prefix = "hero_illiana_walk2Def"

				U.animation_start(this, "walk_2", nil, store.tick_ts, true, 1)

				this.render.sprites[1].offset = v(0, this.dragon.flight_height)

				local og_z = this.render.sprites[1].z

				this.render.sprites[1].z = Z_FLYING_HEROES
				this.dragon.render.sprites[1].z = Z_FLYING_HEROES

				if tr.particles_name then
					ps = E:create_entity(tr.particles_name)
					ps.particle_system.track_id = this.id

					queue_insert(store, ps)
				end

				y_illiana_walk_waypoints(store, this, "walk_2")

				if tr.particles_name then
					ps.particle_system.emit = false
					ps.particle_system.source_lifetime = 1
				end

				this.render.sprites[1].prefix = "hero_illianaDef"
				this.render.sprites[1].offset = v(0, 0)
				this.render.sprites[1].z = og_z
				this.dragon.render.sprites[1].z = og_z

				U.y_animation_play(this, "walk_2_out", nil, store.tick_ts, 1, 1)

				this.vis.bans = vis_bans
				this.health.ignore_damage = false

				return interrupt
			else
				local vis_bans = this.vis.bans
				local prev_immune = this.health.immune_to

				this.vis.bans = F_ALL
				this.health.immune_to = r.immune_to

				local out = SU.y_hero_walk_waypoints(store, this)

				U.animation_start(this, "idle", nil, store.tick_ts, true)

				this.vis.bans = vis_bans
				this.health.immune_to = prev_immune

				return out
			end
		end
	end

	local function should_block()
		local target = SU.soldier_pick_melee_target(store, this)

		return target ~= nil
	end

	while true do
		if ult_start_cd and store.wave_group_number > 0 then
			ult_start_cd = false
			ult.ts = store.tick_ts
		end

		if h.dead then
			if band(h.last_damage_types, bor(DAMAGE_EAT)) ~= 0 then
				this.respawn_animation = "respawn_instakill"
			else
				this.unit.hide_after_death = false
				this.respawn_animation = "respawn"
			end

			y_illiana_death_and_respawn_kr5(store, this)
		end

		if this.unit.is_stunned then
			SU.soldier_idle(store, this)
		else
			while this.nav_rally.new do
				if y_illiana_walk(store, this) then
					goto label_485_1
				end
			end

			if SU.hero_level_up(store, this) then
				U.y_animation_play(this, "lvl_up", nil, store.tick_ts, 1)
			end

			if ult and store.tick_ts - ult.ts > ult.cooldown and not this.dragon_skill_c_in_progress then
				local nearest = P:nearest_nodes(this.pos.x, this.pos.y)
				local targets = U.find_enemies_in_range(store.entities, this.pos, 0, ult.detection_range, ult.flags, ult.bans, function(v, o)
					for _, p in pairs(nearest) do
						if p[1] == v.nav_path.pi and v.nav_path.ni < p[3] then
							return true
						else
							return false
						end
					end
				end)

				if not targets or #targets < ult.min_targets then
					SU.delay_attack(store, ult, fts(10))

					goto label_485_0
				end

				local paths = find_most_populated_path(targets, 0)

				paths = sort_paths_by_distance(paths, ult.distance)

				if #paths == 0 then
					SU.delay_attack(store, ult, fts(10))

					goto label_485_0
				end

				this.dragon.cast_ult = true
				casting_ult = true

				while not this.cast_ult do
					if SU.soldier_interrupted(this) or should_block() then
						this.dragon.cast_ult = false
						casting_ult = false
						this.cast_ult = false

						SU.delay_attack(store, ult, 1)

						goto label_485_1
					end

					SU.soldier_idle(store, this)
					coroutine.yield()
				end

				S:queue(ult.taunt)
				U.animation_start(this, ult.animation, nil, store.tick_ts, false, 1)

				local start_ts = store.tick_ts

				while store.tick_ts - start_ts < ult.shoot_time do
					if SU.soldier_interrupted(this) then
						this.dragon.cast_ult = false
						casting_ult = false
						this.cast_ult = false

						SU.delay_attack(store, ult, 1)

						goto label_485_1
					end

					coroutine.yield()
				end

				S:queue(ult.sound)

				local n = P:nearest_nodes(this.pos.x, this.pos.y, {
					paths[1][1]
				})

				this.dragon.ult_path = {}
				this.dragon.ult_path.pi = n[1][1]
				this.dragon.ult_path.spi = 1
				this.dragon.ult_path.ni = n[1][3] - 3

				local flip = this.render.sprites[1].flip_x and -1 or 1
				local dragon_flip = this.dragon.render.sprites[1].flip_x and -1 or 1
				local treat = E:create_entity(ult.bullet)

				treat.pos.x, treat.pos.y = this.pos.x + ult.shoot_offset.x * flip, this.pos.y + ult.shoot_offset.y
				treat.bullet.from = V.vclone(treat.pos)
				treat.bullet.to = v(this.dragon.pos.x + this.dragon.mouth_offset.x * dragon_flip, this.dragon.pos.y + this.dragon.flight_height)
				this.dragon.treat = treat

				queue_insert(store, treat)
				SU.y_soldier_animation_wait(this)

				casting_ult = false
				this.cast_ult = false
				ult.ts = store.tick_ts
			end

			::label_485_0::

			if skb and store.tick_ts - skb.ts > skb.cooldown and not casting_ult then
				local _, targets = U.find_foremost_enemy(store.entities, this.pos, 0, skb.max_range, 0, skb.flags, skb.bans)

				if not targets or #targets == 0 or #targets < skb.min_targets then
					SU.delay_attack(store, skb, fts(5))
				else
					local flight_time = E:get_template(skb.bullet).bullet.flight_time
					local shoot_pos_prev = find_center_of_group(targets, flight_time)
					local f = this.pos.x > shoot_pos_prev.x

					U.animation_start(this, skb.animation, f, store.tick_ts, false, 1)

					if SU.y_hero_wait(store, this, skb.shoot_time) then
						goto label_485_1
					end

					local shoot_pos = find_center_of_group(targets, flight_time)
					local flip = this.render.sprites[1].flip_x and -1 or 1
					local b = E:create_entity(skb.bullet)

					b.pos.x, b.pos.y = V.vclone(this.pos).x + skb.offset.x * flip, V.vclone(this.pos).y + skb.offset.y
					b.bullet.from = V.vclone(b.pos)
					b.bullet.to = shoot_pos
					b.bullet.source_id = this.id

					queue_insert(store, b)
					SU.hero_gain_xp_from_skill(this, this.hero.skills.skill_b)
					SU.y_hero_animation_wait(this)

					skb.ts = store.tick_ts

					goto label_485_1
				end
			end

			brk, sta = y_hero_melee_block_and_attacks(store, this)

			if brk or sta ~= A_NO_TARGET then
				-- block empty
			elseif SU.soldier_go_back_step(store, this) then
				-- block empty
			else
				brk, sta = y_hero_ranged_attacks(store, this)

				if brk then
					-- block empty
				else
					SU.soldier_idle(store, this)
					SU.soldier_regen(store, this)
				end
			end
		end

		::label_485_1::

		coroutine.yield()
	end
end

scripts.decal_illiana_dragon = {}

function scripts.decal_illiana_dragon.update(this, store, script)
	local sd = this.render.sprites[1]
	local ba = this.ranged.attacks[1]

	ba.ts = store.tick_ts - ba.cooldown

	local sa = not this.ranged.attacks[2].disabled and this.ranged.attacks[2] or nil

	if sa then
		sa.ts = store.tick_ts - sa.cooldown
	end

	local sc = not this.timed_attacks.list[1].disabled and this.timed_attacks.list[1] or nil

	if sc then
		sc.ts = store.tick_ts - sc.cooldown
	end

	local ult = not this.timed_attacks.list[2].disabled and this.timed_attacks.list[2] or nil
	local fm = this.force_motion
	local illiana = store.entities[this.id_illiana]
	local dest = V.v(this.pos.x, this.pos.y)
	local dist, flip
	local death_anim_flag = true
	local og_max_v = this.force_motion.max_v
	local og_a_step = this.force_motion.a_step
	local og_max_a = this.force_motion.max_a

	fm.a_step = fm.a_step + math.random(-3, 3)

	local function hold_position()
		fm.v.x, fm.v.y = 0, 0
		fm.a.x, fm.a.y = 0, 0
	end

	local function shoot(attack)
		local target, targets, pred_pos = U.find_foremost_enemy(store.entities, this.pos, 0, attack.max_range, attack.node_prediction, attack.vis_flags, attack.vis_bans)

		if store.tick_ts - attack.ts > attack.cooldown and target and not target.health.dead and (not attack.min_targets or #targets >= attack.min_targets) then
			local start_ts = store.tick_ts

			hold_position()

			local an, af, ai = U.animation_name_facing_point(this, attack.animation, pred_pos)

			U.animation_start(this, an, af, store.tick_ts)
			S:queue(attack.start_sound, attack.start_sound_args)

			if U.y_wait(store, attack.shoot_time, function(store, time)
				return this.chase
			end) then
				return
			end

			S:queue(attack.sound)

			local hoffset = target and V.vclone(target.unit.hit_offset) or v(0, 0)
			local b = E:create_entity(attack.bullet)

			b.bullet.target_id = target.id
			b.bullet.source_id = this.id
			b.bullet.xp_dest_id = this.id
			b.pos = V.vclone(this.pos)
			b.pos.x = b.pos.x + (af and -1 or 1) * attack.bullet_start_offset.x
			b.pos.y = b.pos.y + attack.bullet_start_offset.y + this.flight_height
			b.bullet.from = V.vclone(b.pos)
			b.bullet.to = v(pred_pos.x + hoffset.x, pred_pos.y + hoffset.y)

			queue_insert(store, b)

			while not U.animation_finished(this) do
				if this.chase then
					return
				end

				coroutine.yield()
			end

			if attack == sa then
				SU.hero_gain_xp_from_skill(illiana, illiana.hero.skills.skill_a)
			end

			attack.ts = store.tick_ts

			U.animation_start(this, this.idle_flip.last_animation, nil, store.tick_ts, this.idle_flip.loop, nil, true)
		end
	end

	local function spawn_ground_fire(pi, pos, fires_spawned)
		local start_i, end_i

		if fires_spawned % 2 == 0 then
			start_i = 1
			end_i = 1
		else
			start_i = 2
			end_i = 3
		end

		for i = start_i, end_i do
			local nearest = P:nearest_nodes(pos.x, pos.y, {
				pi
			})
			local pi, spi, ni = unpack(nearest[1])
			local pos = P:node_pos(pi, i, ni + math.random(-ult.random_for_node, ult.random_for_node))
			local decal = E:create_entity(ult.decal_fire_ground)

			decal.render.sprites[1].ts = store.tick_ts
			decal.pos = pos

			queue_insert(store, decal)

			local aura = E:create_entity(ult.decal_fire_ground_aura)

			aura.pos = pos

			queue_insert(store, aura)
		end
	end

	local normal_death

	while true do
		if illiana.health.dead then
			normal_death = band(illiana.health.last_damage_types, DAMAGE_EAT) == 0

			if normal_death and death_anim_flag then
				U.y_animation_play(this, "death_in", nil, store.tick_ts, 1, 1)

				this.force_motion.max_v = og_max_v / 4
				this.force_motion.a_step = og_a_step / 4
				this.force_motion.max_a = og_max_a / 4

				repeat
					U.animation_start(this, "death_walk", nil, store.tick_ts, true)

					dest.x, dest.y = illiana.pos.x, illiana.pos.y
					sd.flip_x = dest.x < this.pos.x

					U.force_motion_step(this, store.tick_length, dest)
					coroutine.yield()

					dist = V.dist(this.pos.x, this.pos.y, dest.x, dest.y)
				until dist < 5

				this.force_motion.max_v = og_max_v
				this.force_motion.a_step = og_a_step
				this.force_motion.max_a = og_max_a

				U.y_wait(store, fts(10))
				U.y_animation_play(this, "death_out", nil, store.tick_ts, 1, 1)

				illiana.trigger_death_animation = true
				this.render.sprites[1].hidden = true
				death_anim_flag = false
			elseif not normal_death then
				repeat
					U.animation_start(this, "death_walk", nil, store.tick_ts, true)

					dest.x, dest.y = illiana.pos.x, illiana.pos.y
					sd.flip_x = dest.x < this.pos.x

					U.force_motion_step(this, store.tick_length, dest)
					coroutine.yield()

					dist = V.dist(this.pos.x, this.pos.y, dest.x, dest.y)
				until dist < 5
			end
		else
			if this.trigger_respawn_animation and normal_death then
				U.animation_start(this, "respawn", not illiana.render.sprites[1].fip_x, store.tick_ts, false, 1)

				this.render.sprites[1].hidden = false
				this.trigger_respawn_animation = false

				U.y_animation_wait(this)
			end

			death_anim_flag = true

			if this.chase then
				this.cancel_transfer = false

				local fm = this.force_motion
				local contact_time = this.pickup_contact_time

				fm.max_v = og_max_v * 2
				fm.a_step = og_a_step * 2
				fm.max_a = og_max_a * 2

				local cancelled = false

				repeat
					U.animation_start(this, "walk_1", nil, store.tick_ts, true)

					dest.x, dest.y = illiana.pos.x, illiana.pos.y
					sd.flip_x = dest.x < this.pos.x

					U.force_motion_step(this, store.tick_length, dest)
					coroutine.yield()

					dist = V.dist(this.pos.x, this.pos.y, dest.x, dest.y)
					cancelled = this.cancel_transfer or illiana.health.dead or not this.ride_to
				until cancelled or dist < 5 or dist <= V.len(fm.v.x, fm.v.y) * contact_time

				this.chase = false

				if cancelled then
					this.cancel_transfer = false
					fm.max_v = og_max_v
					fm.a_step = og_a_step
					fm.max_a = og_max_a

					goto label_504_0
				end

				local carry_v = og_max_v * 1.5
				local exit_speed = math.min(carry_v, math.max(V.len(fm.v.x, fm.v.y), illiana.motion.max_speed))
				local contact_ts = store.tick_ts + contact_time
				local ride_anim_ts = store.tick_ts + this.pickup_anim_time
				local cx, cy = this.pos.x, this.pos.y

				illiana.mount_ts = contact_ts
				illiana.ride_anim_ts = ride_anim_ts
				sd.flip_x = this.ride_to.x < this.pos.x

				U.animation_start(this, "walk_2_in", sd.flip_x, store.tick_ts, false, 1, true)

				while contact_ts > store.tick_ts do
					local dt = store.tick_length
					local rem = contact_ts - store.tick_ts
					local ivx, ivy = 0, 0

					if not illiana.motion.arrived then
						ivx, ivy = V.mul(illiana.motion.max_speed, V.normalize(V.sub(illiana.motion.dest.x, illiana.motion.dest.y, illiana.pos.x, illiana.pos.y)))
					end

					cx, cy = illiana.pos.x + ivx * rem, illiana.pos.y + ivy * rem

					local evx, evy = V.mul(exit_speed, V.normalize(V.sub(this.ride_to.x, this.ride_to.y, cx, cy)))

					if rem <= dt then
						this.pos.x, this.pos.y = cx, cy
						fm.v.x, fm.v.y = evx, evy
					else
						local s = dt / rem
						local s2 = s * s
						local s3 = s2 * s
						local h00 = 2 * s3 - 3 * s2 + 1
						local h10 = s3 - 2 * s2 + s
						local h01 = -2 * s3 + 3 * s2
						local h11 = s3 - s2
						local nx = h00 * this.pos.x + h10 * rem * fm.v.x + h01 * cx + h11 * rem * evx
						local ny = h00 * this.pos.y + h10 * rem * fm.v.y + h01 * cy + h11 * rem * evy

						fm.v.x, fm.v.y = (nx - this.pos.x) / dt, (ny - this.pos.y) / dt
						this.pos.x, this.pos.y = nx, ny
					end

					fm.a.x, fm.a.y = 0, 0

					coroutine.yield()

					if this.cancel_transfer or illiana.health.dead then
						illiana.mount_ts = nil
						illiana.ride_anim_ts = nil
						this.cancel_transfer = false
						fm.max_v = og_max_v
						fm.a_step = og_a_step
						fm.max_a = og_max_a

						goto label_504_0
					end
				end

				this.carry_to = this.ride_to
				fm.max_v = carry_v
				fm.a_step = og_a_step * 1.5
				fm.max_a = og_max_a * 1.5

				while ride_anim_ts > store.tick_ts do
					if this.cancel_transfer or illiana.health.dead then
						break
					end

					dest.x, dest.y = this.carry_to.x, this.carry_to.y
					sd.flip_x = dest.x < this.pos.x

					U.force_motion_step(this, store.tick_length, dest)
					coroutine.yield()
				end

				U.animation_start(this, "walk_2", nil, ride_anim_ts, true, 1, true)
			end

			if this.carry_to then
				this.force_motion.max_v = og_max_v * 1.5
				this.force_motion.a_step = og_a_step * 1.5
				this.force_motion.max_a = og_max_a * 1.5

				repeat
					U.animation_start(this, "walk_2", nil, store.tick_ts, true)

					dest.x, dest.y = this.carry_to.x, this.carry_to.y
					sd.flip_x = dest.x < this.pos.x

					U.force_motion_step(this, store.tick_length, dest)
					coroutine.yield()

					dist = V.dist(this.pos.x, this.pos.y, dest.x, dest.y)
				until dist < 5 or this.cancel_transfer

				this.force_motion.max_v = og_max_v
				this.force_motion.a_step = og_a_step
				this.force_motion.max_a = og_max_a
				this.carry_to = nil
				this.ride_to = nil

				if this.cancel_transfer then
					this.cancel_transfer = false
				else
					illiana.transfer_arrived = true
				end
			end

			repeat
				U.animation_start(this, "walk_1", nil, store.tick_ts, true)

				dest.x, dest.y = illiana.pos.x + this.offset.x, illiana.pos.y + this.offset.y
				sd.flip_x = dest.x < this.pos.x

				U.force_motion_step(this, store.tick_length, dest)
				coroutine.yield()

				dist = V.dist(this.pos.x, this.pos.y, dest.x, dest.y)
			until dist < this.follow_distance or this.cast_ult or this.chase

			illiana.can_transfer = true
			illiana.teleport.disabled = false

			if this.chase then
				-- block empty
			else
				if sa then
					shoot(sa)
				end

				if sc and store.tick_ts - sc.ts > sc.cooldown then
					local targets = U.find_enemies_in_range(store.entities, this.pos, 0, sc.detection_range, 0, 0, function(v, o)
						return v.unit.is_stunned
					end)

					if not targets or #targets == 0 then
						SU.delay_attack(store, sc, fts(10))
					else
						illiana.dragon_skill_c_in_progress = true

						local s = this.render.sprites[1]
						local fh = this.flight_height
						local target = targets[1]
						local og_speed = this.force_motion.max_v
						local flip = this.pos.x < target.pos.x and -1 or 1

						this.force_motion.max_v = this.force_motion.max_v * 2

						repeat
							U.animation_start(this, "walk_1", nil, store.tick_ts, true)

							dest.x, dest.y = target.pos.x + target.enemy.melee_slot.x * flip, target.pos.y
							sd.flip_x = dest.x < this.pos.x

							U.force_motion_step(this, store.tick_length, dest)
							coroutine.yield()

							dist = V.dist(this.pos.x, this.pos.y, dest.x, dest.y)

							if this.chase then
								SU.delay_attack(store, sc, fts(10))

								goto label_504_0
							end
						until dist < 10

						hold_position()
						U.animation_start(this, sc.animation, this.pos.x > target.pos.x, store.tick_ts, false, 1)

						if U.y_wait(store, sc.lower_time, function(store, time)
							return this.chase
						end) then
							SU.delay_attack(store, sc, fts(10))

							illiana.dragon_skill_c_in_progress = false

							goto label_504_0
						end

						illiana.can_transfer = false
						illiana.teleport.disabled = true
						s.offset = v(0, sc.flight_heights[2])

						U.y_wait(store, sc.bite_time)

						s.offset = v(0, sc.flight_heights[3])

						S:queue(sc.sound)

						local d = E:create_entity("damage")

						d.source_id = this.id
						d.target_id = target.id
						d.value = math.ceil(U.frandom(sc.damage_min, sc.damage_max))
						d.damage_type = sc.damage_type

						queue_damage(store, d)

						flip = this.pos.x < target.pos.x and 1 or -1

						local fx = E:create_entity(sc.hit_fx)

						fx.render.sprites[1].ts = store.tick_ts
						fx.pos.x, fx.pos.y = V.vclone(this.pos).x + sc.hit_fx_offset.x * flip, V.vclone(this.pos).y + sc.hit_fx_offset.y

						queue_insert(store, fx)
						U.y_wait(store, sc.return_time)
						U.y_ease_key(store, s.offset, "y", s.offset.y, sc.flight_heights[1], sc.return_duration, sc.easing)
						U.y_animation_wait(this)
						SU.hero_gain_xp_from_skill(illiana, illiana.hero.skills.skill_c)

						this.force_motion.max_v = og_speed
						illiana.can_transfer = true
						illiana.teleport.disabled = false
						sc.ts = store.tick_ts
						illiana.dragon_skill_c_in_progress = false

						goto label_504_0
					end
				end

				if this.cast_ult and ult then
					illiana.can_transfer = false
					illiana.teleport.disabled = true

					U.y_animation_play(this, ult.anim_in, nil, store.tick_ts, 1, 1)
					U.animation_start(this, ult.anim_wait, nil, store.tick_ts, true, 1)

					local s = this.render.sprites[1]

					illiana.cast_ult = true

					while not this.treat and not this.ult_path do
						if illiana.health.dead or not this.cast_ult then
							this.cast_ult = false

							goto label_504_0
						end

						coroutine.yield()
					end

					U.animation_start(this, ult.anim_bite, nil, store.tick_ts, false, 1)
					U.y_wait(store, ult.bite_time)

					local flip = s.flip_x and -1 or 1
					local fx = E:create_entity(ult.bite_fx)

					fx.pos.x, fx.pos.y = this.pos.x + this.mouth_offset.x * flip, this.pos.y + this.flight_height + this.mouth_offset.y
					fx.render.sprites[1].ts = store.tick_ts

					queue_insert(store, fx)
					U.y_wait(store, ult.fire_start_fx_time)

					local fire_start_fx = E:create_entity(ult.fire_start_fx)

					fire_start_fx.pos.x, fire_start_fx.pos.y = this.pos.x + this.mouth_offset.x * flip, this.pos.y + this.flight_height + this.mouth_offset.y
					fire_start_fx.render.sprites[1].ts = store.tick_ts

					queue_insert(store, fire_start_fx)
					U.y_animation_wait(this)

					local n = P:node_pos(this.ult_path.pi, this.ult_path.spi, this.ult_path.ni)
					local flip_x = n.x < this.pos.x

					U.animation_start(this, ult.anim_walk, flip_x, store.tick_ts, true, 1)

					local ps_fire = E:create_entity(ult.fire_particles)

					ps_fire.particle_system.track_id = this.id

					queue_insert(store, ps_fire)

					local ps_breath = E:create_entity(ult.breath_particles)

					ps_breath.particle_system.track_id = this.id

					queue_insert(store, ps_breath)

					local dfsh = E:create_entity(ult.decal_fire_stream_hit)

					dfsh.render.sprites[1].ts = store.tick_ts
					dfsh.pos = v(this.pos.x + ult.fire_stream_hit_offset.x * (flip_x and -1 or 1), this.pos.y + ult.fire_stream_hit_offset.y)

					queue_insert(store, dfsh)

					local aura = E:create_entity(ult.stream_aura)

					aura.pos = v(this.pos.x + ult.fire_stream_hit_offset.x * (flip_x and -1 or 1), this.pos.y + ult.fire_stream_hit_offset.y)

					queue_insert(store, aura)
					S:queue(ult.sound)

					local fire_spawn_delay = fts(7)
					local start_ts = store.tick_ts
					local dbn = ult.distance_between_nodes
					local last_node_spawned = -1
					local fires_spawned = 0
					local node_pos, particle_node_pos, angle
					local traversed = 0
					local distance = 0
					local fire_spawn_pos
					local end_flag = true
					local emit_direction, track_offset

					while traversed < ult.distance do
						U.animation_start(this, ult.anim_walk, nil, store.tick_ts, true)

						node_pos = P:node_pos(this.ult_path.pi, this.ult_path.spi, this.ult_path.ni)
						dest = node_pos
						sd.flip_x = dest.x < this.pos.x

						U.force_motion_step(this, store.tick_length, dest)

						local nearest = P:nearest_nodes(this.pos.x + ult.fire_stream_hit_offset.x * (s.flip_x and -1 or 1), this.pos.y + ult.fire_stream_hit_offset.y, {
							this.ult_path.pi
						})[1]

						aura.pos = P:node_pos(nearest[1], nearest[2], nearest[3])
						particle_node_pos = P:node_pos(this.ult_path.pi, this.ult_path.spi, this.ult_path.ni - 10)
						angle = V.angleTo(particle_node_pos.x - this.pos.x, particle_node_pos.y - (this.pos.y + this.flight_height))
						emit_direction = angle
						track_offset = v(ult.fire_stream_cast_offset.x * (s.flip_x and -1 or 1), ult.fire_stream_cast_offset.y)
						ps_fire.particle_system.emit_direction = emit_direction
						ps_fire.particle_system.track_offset = track_offset
						ps_breath.particle_system.emit_direction = emit_direction
						ps_breath.particle_system.track_offset = track_offset

						if fire_spawn_delay <= store.tick_ts - start_ts and dbn <= math.abs(this.ult_path.ni - last_node_spawned) then
							fire_spawn_pos = P:node_pos(this.ult_path.pi, this.ult_path.spi, this.ult_path.ni - 2)

							spawn_ground_fire(this.ult_path.pi, fire_spawn_pos, fires_spawned)

							fires_spawned = fires_spawned + 1
							last_node_spawned = this.ult_path.ni
						end

						distance = V.dist2(node_pos.x, node_pos.y, this.pos.x, this.pos.y)

						if distance < 400 then
							this.ult_path.ni = this.ult_path.ni - 3
							traversed = traversed + 3
						end

						if ult.distance - traversed <= 9 and end_flag then
							ps_fire.particle_system.emit = false
							ps_breath.particle_system.emit = false
							aura.aura.duration = 0
							fire_spawn_delay = 1e+99
							end_flag = false

							break
						end

						coroutine.yield()
					end

					local ts = store.tick_ts

					U.animation_start(this, ult.anim_end, nil, store.tick_ts, false, 1)

					this.force_motion.max_v = og_max_v / 4
					this.force_motion.a_step = og_a_step / 4
					this.force_motion.max_a = og_max_a / 4

					local ps_smoke = E:create_entity(ult.smoke_particles)

					ps_smoke.particle_system.track_id = this.id
					ps_smoke.particle_system.emit = false

					queue_insert(store, ps_smoke)

					repeat
						node_pos = P:node_pos(this.ult_path.pi, this.ult_path.spi, this.ult_path.ni)
						dest = node_pos
						sd.flip_x = dest.x < this.pos.x

						U.force_motion_step(this, store.tick_length, dest)

						distance = V.dist2(node_pos.x, node_pos.y, this.pos.x, this.pos.y)

						if distance < 400 then
							this.ult_path.ni = this.ult_path.ni - 3
						end

						if store.tick_ts - ts > fts(18) then
							ps_smoke.particle_system.emit = true
							ps_smoke.particle_system.emit_direction = s.flip_x and 180 * math.pi / 180 or 360 * math.pi / 180
							ps_smoke.particle_system.track_offset = v(ult.smoke_offset.x * (s.flip_x and -1 or 1), ult.smoke_offset.y)
						end

						if store.tick_ts - ts > fts(30) then
							ps_smoke.particle_system.emit = false
						end

						coroutine.yield()
					until store.tick_ts - ts > fts(39)

					this.force_motion.max_v = og_max_v
					this.force_motion.a_step = og_a_step
					this.force_motion.max_a = og_max_a

					queue_remove(store, ps_fire)
					queue_remove(store, ps_breath)
					queue_remove(store, ps_smoke)
					SU.hero_gain_xp_from_skill(illiana, illiana.hero.skills.ultimate)

					this.cast_ult = false
					this.ult_path = nil
					this.treat = nil
					illiana.can_transfer = true
					illiana.teleport.disabled = false

					goto label_504_0
				end

				shoot(ba)
				U.animation_start(this, "idle", nil, store.tick_ts, true)
			end
		end

		::label_504_0::

		coroutine.yield()
	end
end

scripts.hero_illiana_mod_skill_a = {}

function scripts.hero_illiana_mod_skill_a.insert(this, store, script)
	local target = store.entities[this.modifier.target_id]

	if not target or target.health.dead or not target.enemy then
		return false
	end

	local s = this.render.sprites[1]

	if s and s.prefix_names then
		s.prefix = s.prefix_names[target.unit.size]
	end

	if this.custom_offsets then
		s.offset = V.vclone(this.custom_offsets[target.template_name] or this.custom_offsets.default)
		s.offset.x = s.offset.x * (s.flip_x and -1 or 1)

		if target.unit and target.unit.mod_offset and this.modifier.use_mod_offset then
			s.offset.x = s.offset.x + target.unit.mod_offset.x
			s.offset.y = s.offset.y + target.unit.mod_offset.y
		end
	end

	SU.armor_dec(target, this.armor_red)
	SU.magic_armor_dec(target, this.magic_armor_red)
	signal.emit("mod-applied", this, target)

	return true
end

function scripts.hero_illiana_mod_skill_a.remove(this, store, script)
	local target = store.entities[this.modifier.target_id]

	if target then
		SU.armor_inc(target, this.armor_red)
		SU.magic_armor_inc(target, this.magic_armor_red)
	end

	return scripts.tween_utils.reverse_remove
end

scripts.soldier_reinforcement_kr6 = {}

function scripts.soldier_reinforcement_kr6.update(this, store, script)
	local brk, stam, star

	this.reinforcement.ts = store.tick_ts
	this.render.sprites[1].ts = store.tick_ts

	signal.emit("spawned-reinforcement", this)

	if this.render.sprites[1].name == "in" then
		if this.sound_events and this.sound_events.raise then
			S:queue(this.sound_events.raise)
		end

		this.health_bar.hidden = true

		U.y_animation_play(this, "in", nil, store.tick_ts, 1)

		if not this.health.dead then
			this.health_bar.hidden = nil
		end
	elseif this.reinforcement.fade or this.reinforcement.fade_in then
		SU.y_reinforcement_fade_in(store, this)
	end

	while true do
		if this.health.dead then
			this.reinforcement.fade = false
			this.reinforcement.fade_out = false
			this.ui.can_click = false
			this.tween = nil

			SU.y_soldier_death(store, this)

			return
		end

		if this.reinforcement.duration and store.tick_ts - this.reinforcement.ts > this.reinforcement.duration then
			if this.health.hp > 0 then
				this.reinforcement.hp_before_timeout = this.health.hp
			end

			this.health.hp = 0
			this.ui.can_click = false

			SU.remove_modifiers(store, this)
			SU.y_soldier_death(store, this)

			return
		end

		if this.unit.is_stunned then
			SU.soldier_idle(store, this)
		else
			SU.soldier_courage_upgrade(store, this)

			while this.nav_rally.new do
				if this.nav_rally.move_order then
					U.y_wait(store, this.nav_rally.move_order * math.random() * 0.3)
				end

				if SU.y_hero_new_rally(store, this) then
					goto label_513_1
				end
			end

			if this.dodge and this.dodge.active then
				this.dodge.active = false

				if this.dodge.animation then
					U.animation_start(this, this.dodge.animation, nil, store.tick_ts, 1)

					while not U.animation_finished(this) do
						coroutine.yield()
					end
				end

				signal.emit("soldier-dodge", this)
			end

			if this.melee then
				brk, stam = SU.y_soldier_melee_block_and_attacks(store, this)

				if brk or stam == A_DONE or stam == A_IN_COOLDOWN and not this.melee.continue_in_cooldown then
					goto label_513_1
				end
			end

			if this.ranged then
				brk, star = SU.y_soldier_ranged_attacks(store, this)

				if brk or star == A_DONE then
					goto label_513_1
				elseif star == A_IN_COOLDOWN then
					goto label_513_0
				end
			end

			if this.melee.continue_in_cooldown and stam == A_IN_COOLDOWN then
				goto label_513_1
			end

			if SU.soldier_go_back_step(store, this) then
				goto label_513_1
			end

			::label_513_0::

			SU.soldier_idle(store, this)
			SU.soldier_regen(store, this)
		end

		::label_513_1::

		coroutine.yield()
	end
end

scripts.soldier_reinforcement_special_kr6 = {}

function scripts.soldier_reinforcement_special_kr6.update(this, store, script)
	local e = E:create_entity(this.aura_in_t)

	e.render.sprites[1].ts = store.tick_ts
	e.pos.x, e.pos.y = this.pos.x, this.pos.y

	queue_insert(store, e)

	local e = E:create_entity(this.aura_buff_t)

	e.aura.source_id = this.id

	queue_insert(store, e)
	scripts.soldier_reinforcement_kr6.update(this, store, script)
end

scripts.mod_armor_buff_soldier_reinforcement_special = {}

function scripts.mod_armor_buff_soldier_reinforcement_special.remove(this, store, script)
	if not this.tween.disabled then
		return true
	end

	scripts.mod_armor_buff.remove(this, store, script)

	return scripts.tween_utils.reverse_remove(this, store, script)
end

scripts.soldier_soaring_shop = {}

function scripts.soldier_soaring_shop.get_info(this)
	local stats = this.stats

	return {
		type = STATS_TYPE_SOLDIER,
		hp = stats.hp,
		hp_max = stats.hp_max,
		damage_min = stats.damage_min,
		damage_max = stats.damage_max,
		armor = stats.armor,
		respawn = stats.cooldown
	}
end

function scripts.soldier_soaring_shop.insert(this, store)
	return true
end

function scripts.soldier_soaring_shop.update(this, store)
	this.ts = store.tick_ts

	local attack = this.ranged.attacks[1]
	local attack2 = this.timed_attacks.list[1]
	local attack3 = this.timed_attacks.list[2]

	attack.ts = store.tick_ts - attack.cooldown
	attack2.ts = store.tick_ts - attack2.cooldown
	attack3.ts = store.tick_ts

	local basic_flight_time = E:get_template(this.attack_bullets.attack).bullet.flight_time + attack.prediction
	local attack_3_flight_time = E:get_template(attack3.bullet).bullet.flight_time + attack3.prediction
	local attacks = 1

	local function get_attack_bullet_and_anim()
		if attacks % this.special_1_rate == 0 then
			return this.attack_bullets.attack_special_1, "attack_special_1"
		elseif attacks % this.special_2_rate == 0 then
			return this.attack_bullets.attack_special_2, "attack_special_2"
		else
			return this.attack_bullets.attack, "attack"
		end
	end

	local s = this.render.sprites[1]
	local start_y = s.offset.y

	s.offset = v(s.offset.x, s.offset.y + this.spawn_flight_height)

	U.animation_start(this, "in", nil, store.tick_ts, 1, 1)

	while not U.animation_finished(this, 1) do
		s.offset = v(s.offset.x, s.offset.y - this.spawn_speed)

		coroutine.yield()
	end

	U.animation_start(this, "idle", nil, store.tick_ts, 1, 1)

	this.controller = E:create_entity(this.controller_float_anim)
	this.controller.sprite = this.render.sprites[1]
	this.controller.flight_height = this.flight_height

	queue_insert(store, this.controller)

	while true do
		if this.duration and store.tick_ts - this.ts > this.duration then
			this.health.dead = true

			U.animation_start(this, "out", nil, store.tick_ts, 1, 1)

			while not U.animation_finished(this, 1) do
				s.offset = v(s.offset.x, s.offset.y + this.spawn_speed)

				coroutine.yield()
			end

			queue_remove(store, this)

			return
		end

		while this.nav_rally.new do
			this.controller.moving = true

			if this.nav_rally.move_order then
				U.y_wait(store, this.nav_rally.move_order * math.random() * 0.3)
			end

			if SU.y_hero_new_rally(store, this) then
				goto label_518_0
			end
		end

		this.controller.moving = false

		if not attack3.disabled and not this.nav_rally.new and store.tick_ts - attack3.ts > attack3.cooldown then
			local enemy, enemies, enemy_pos = U.find_foremost_enemy(store.entities, this.pos, 0, attack3.range, attack_3_flight_time, attack.vis_flags, attack.vis_bans)

			if not enemy or enemy.health.dead then
				-- block empty
			else
				this.render.sprites[1].flip_x = enemy.pos.x < this.pos.x

				local flip = this.render.sprites[1].flip_x and -1 or 1

				U.animation_start(this, "attack_3", nil, store.tick_ts, false, 1)
				U.y_wait(store, attack3.hit_time)

				local b = E:create_entity(attack3.bullet)

				b.pos.x, b.pos.y = this.pos.x + attack3.offset.x * flip, this.pos.y + attack3.offset.y
				b.bullet.from = V.vclone(b.pos)
				b.bullet.to = V.vclone(enemy_pos)
				b.bullet.target_id = enemy.id
				b.bullet.source_id = this.id
				b.render.sprites[1].flip_x = this.render.sprites[1].flip_x

				queue_insert(store, b)

				while not U.animation_finished(this, 1) do
					coroutine.yield()
				end

				attack3.ts = store.tick_ts
			end
		end

		if not attack2.disabled and not this.nav_rally.new and store.tick_ts - attack2.ts > attack2.cooldown then
			local enemy, enemies, enemy_pos = U.find_foremost_enemy(store.entities, this.pos, 0, attack.range, basic_flight_time, attack.vis_flags, attack.vis_bans)

			if not enemy or enemy.health.dead then
				-- block empty
			else
				U.animation_start(this, "attack_2", nil, store.tick_ts, false, 1)

				for i = 0, #attack2.hit_times - 1 do
					U.y_wait(store, attack2.hit_times[i + 1])

					if not P:is_node_valid(enemy.nav_path.pi, enemy.nav_path.ni - i * 10) then
						-- block empty
					else
						local e_pos = P:node_pos(enemy.nav_path.pi, enemy.nav_path.spi, enemy.nav_path.ni - i * 10)

						this.render.sprites[1].flip_x = e_pos.x < this.pos.x

						local flip = this.render.sprites[1].flip_x and -1 or 1
						local b = E:create_entity(attack2.bullet)

						b.pos.x, b.pos.y = this.pos.x + attack.offset.x * flip, this.pos.y + s.offset.y
						b.bullet.from = V.vclone(b.pos)
						b.bullet.to = V.vclone(e_pos)
						b.bullet.target_id = enemy.id
						b.bullet.source_id = this.id

						queue_insert(store, b)
					end
				end

				while not U.animation_finished(this, 1) do
					coroutine.yield()
				end

				attack2.ts = store.tick_ts
			end
		end

		if not this.nav_rally.new and store.tick_ts - attack.ts > attack.cooldown then
			local enemy, enemies, enemy_pos = U.find_foremost_enemy(store.entities, this.pos, 0, attack.range, basic_flight_time, attack.vis_flags, attack.vis_bans)

			if not enemy or enemy.health.dead then
				-- block empty
			else
				this.render.sprites[1].flip_x = enemy.pos.x < this.pos.x

				local bullet, anim = get_attack_bullet_and_anim()
				local flip = this.render.sprites[1].flip_x and -1 or 1

				attacks = attacks + 1

				U.animation_start(this, anim, nil, store.tick_ts, false, 1)
				U.y_wait(store, attack.hit_time)

				local b = E:create_entity(bullet)

				b.pos.x, b.pos.y = this.pos.x + attack.offset.x * flip, this.pos.y + s.offset.y
				b.bullet.from = V.vclone(b.pos)
				b.bullet.to = V.vclone(enemy_pos)
				b.bullet.target_id = enemy.id
				b.bullet.source_id = this.id

				queue_insert(store, b)

				while not U.animation_finished(this, 1) do
					coroutine.yield()
				end

				attack.ts = store.tick_ts
			end
		end

		::label_518_0::

		SU.soldier_idle(store, this)
		coroutine.yield()
	end
end

function scripts.soldier_soaring_shop.remove(this, store)
	queue_remove(store, this.controller)

	if game.game_gui.selected_entity and game.game_gui.selected_entity.id == this.id then
		signal.emit("hide-bottom-info")
	end

	return true
end

scripts.controller_soaring_shop = {}

function scripts.controller_soaring_shop.insert(this, store)
	return true
end

function scripts.controller_soaring_shop.update(this, store)
	while true do
		if not this.moving then
			this.sprite.offset = v(V.add(this.sprite.offset.x, this.sprite.offset.y, 0, this.speed))

			if this.sprite.offset.y - this.flight_height <= this.min_y or this.sprite.offset.y - this.flight_height >= this.max_y then
				this.speed = this.speed * -1
			end
		end

		coroutine.yield()
	end
end

scripts.soldier_aspect_of_sol = {}

function scripts.soldier_aspect_of_sol.insert(this, store)
	this.original_attack_min = this.melee.attacks[1].damage_min
	this.original_attack_max = this.melee.attacks[1].damage_max
	this.original_special_attack_min = this.melee.attacks[2].damage_min
	this.original_special_attack_max = this.melee.attacks[2].damage_max

	if this.spawn_with_beam then
		S:queue(this.sound_entrance_lvl3)
	else
		S:queue(this.sound_entrance_lvl1)
	end

	this.melee.order = U.attack_order(this.melee.attacks)

	return true
end

function scripts.soldier_aspect_of_sol.update(this, store)
	this.reinforcement.ts = store.tick_ts

	local enemy = this.id_enemy and store.entities[this.id_enemy] or nil
	local number_of_attacks = 0
	local a1 = this.melee.attacks[1]
	local a2 = this.melee.attacks[2]
	local sa = this.timed_attacks.list[1]

	a1.ts = store.tick_ts - a1.cooldown
	sa.ts = store.tick_ts - sa.cooldown

	local brk, stam

	local function y_warcry()
		if sa.disabled then
			return
		end

		local soldiers = U.find_soldiers_in_range(store.entities, this.pos, sa.min_range, sa.max_range, sa.vis_flags, sa.vis_bans)

		if soldiers and #soldiers > 0 then
			for k, v in pairs(soldiers) do
				local mod = E:create_entity(sa.mod_dmg_inc)

				mod.modifier.source_id = this.id
				mod.modifier.target_id = v.id

				queue_insert(store, mod)

				local mod = E:create_entity(sa.mod_armor_inc)

				mod.modifier.source_id = this.id
				mod.modifier.target_id = v.id

				queue_insert(store, mod)
			end
		end

		if sa.mod_slow then
			local enemies = U.find_enemies_in_range(store.entities, this.pos, sa.min_range, sa.max_range, sa.vis_flags, sa.vis_bans)

			if enemies and #enemies > 0 then
				for k, v in pairs(enemies) do
					local mod = E:create_entity(sa.mod_slow)

					mod.modifier.source_id = this.id
					mod.modifier.target_id = v.id

					queue_insert(store, mod)
				end
			end
		end

		S:queue(sa.sound)
		U.y_animation_play(this, sa.animation, nil, store.tick_ts, 1, 1)
	end

	local function summon()
		if this.spawn_with_beam then
			local beam = E:create_entity(this.decal_beam)

			beam.pos = V.vclone(this.pos)
			beam.render.sprites[1].ts = store.tick_ts

			queue_insert(store, beam)
			S:queue(this.sound_entrance_lvl3)
			U.y_wait(store, this.beam_delay)
		end

		U.animation_start(this, "summon", nil, store.tick_ts, 1, 1)

		this.render.sprites[1].hidden = false
		this.render.sprites[1].z = Z_OBJECTS

		U.y_wait(store, this.crack_delay)

		local crack = E:create_entity(this.decal_crack)

		crack.pos = V.vclone(this.pos)
		crack.render.sprites[1].ts = store.tick_ts

		queue_insert(store, crack)

		local smoke = E:create_entity(this.decal_smoke)

		smoke.pos = V.vclone(this.pos)
		smoke.render.sprites[1].ts = store.tick_ts

		queue_insert(store, smoke)

		if enemy then
			local d = E:create_entity("damage")

			d.source_id = this.id
			d.target_id = enemy.id
			d.damage_type = this.on_select_enemy.damage_type

			if band(enemy.vis.flags, F_BOSS) ~= 0 then
				d.value = this.on_select_enemy.max_boss_damage
			elseif band(enemy.vis.flags, F_MINIBOSS) ~= 0 then
				d.value = this.on_select_enemy.max_miniboss_damage
			else
				d.value = this.on_select_enemy.damage
			end

			queue_damage(store, d)
		end

		if this.spawn_aura then
			local aura = E:create_entity(this.spawn_aura)

			aura.boss_damage_cap = this.on_summon.boss_damage_cap
			aura.miniboss_damage_cap = this.on_summon.miniboss_damage_cap
			aura.pos = V.vclone(this.pos)

			queue_insert(store, aura)
		end

		while not U.animation_finished(this, 1) do
			coroutine.yield()
		end

		U.animation_start(this, "idle", nil, store.tick_ts, 1, 1)

		this.render.sprites[1].z = Z_OBJECTS
	end

	local function leave()
		U.unblock_target(store, this)

		this.ui.can_click = false

		if game.game_gui.selected_entity and game.game_gui.selected_entity.id == this.id then
			signal.emit("hide-bottom-info")
		end

		local beam = E:create_entity(this.decal_beam)

		beam.pos = V.vclone(this.pos)
		beam.render.sprites[1].ts = store.tick_ts

		queue_insert(store, beam)

		local smoke = E:create_entity(this.decal_crack)

		smoke.pos = V.vclone(this.pos)
		smoke.render.sprites[1].ts = store.tick_ts

		queue_insert(store, smoke)

		local smoke = E:create_entity(this.decal_smoke)

		smoke.pos = V.vclone(this.pos)
		smoke.render.sprites[1].ts = store.tick_ts

		queue_insert(store, smoke)
		S:queue(this.sound_out)
		U.y_animation_play(this, "leave", nil, store.tick_ts, 1, 1)
		SU.remove_modifiers(store, this)
		queue_remove(store, this)
	end

	local function adjust_damage()
		local target = store.entities[this.soldier.target_id]

		if not target then
			return
		end

		if band(target.vis.flags, F_BOSS) ~= 0 then
			this.melee.attacks[1].damage_min = this.melee.attacks[1].damage_min * this.melee.attacks[1].boss_damage_cap
			this.melee.attacks[1].damage_max = this.melee.attacks[1].damage_max * this.melee.attacks[1].boss_damage_cap
			this.melee.attacks[2].damage_min = this.melee.attacks[2].damage_min * this.melee.attacks[2].boss_damage_cap
			this.melee.attacks[2].damage_max = this.melee.attacks[2].damage_max * this.melee.attacks[2].boss_damage_cap
		elseif band(target.vis.flags, F_MINIBOSS) ~= 0 then
			this.melee.attacks[1].damage_min = this.melee.attacks[1].damage_min * this.melee.attacks[1].miniboss_damage_cap
			this.melee.attacks[1].damage_max = this.melee.attacks[1].damage_max * this.melee.attacks[1].miniboss_damage_cap
			this.melee.attacks[2].damage_min = this.melee.attacks[2].damage_min * this.melee.attacks[2].miniboss_damage_cap
			this.melee.attacks[2].damage_max = this.melee.attacks[2].damage_max * this.melee.attacks[2].miniboss_damage_cap
		else
			this.melee.attacks[1].damage_min = this.original_attack_min
			this.melee.attacks[1].damage_max = this.original_attack_max
			this.melee.attacks[2].damage_min = this.original_special_attack_min
			this.melee.attacks[2].damage_max = this.original_special_attack_max
		end
	end

	summon()

	while true do
		if this.health.dead or this.reinforcement.duration and store.tick_ts - this.reinforcement.ts > this.reinforcement.duration then
			leave()

			return
		end

		if this.unit.is_stunned then
			SU.soldier_idle(store, this)
		else
			if enemy and enemy.health.dead then
				y_warcry()

				enemy = nil
			end

			if not this.l5b_disabled and store.tick_ts - sa.ts > sa.cooldown then
				y_warcry()

				sa.ts = store.tick_ts
			end

			while this.nav_rally.new do
				if SU.y_hero_new_rally(store, this) then
					goto label_524_0
				end
			end

			adjust_damage()

			brk, stam = SU.y_soldier_melee_block_and_attacks(store, this)

			if brk then
				-- block empty
			else
				if stam == A_DONE then
					number_of_attacks = number_of_attacks + 1

					if a2.has_upgrade and number_of_attacks % 3 == 0 then
						a2.disabled = false
						a1.disabled = true
					else
						a2.disabled = true
						a1.disabled = false
					end
				end

				if brk or stam ~= A_NO_TARGET then
					-- block empty
				elseif SU.soldier_go_back_step(store, this) then
					-- block empty
				else
					SU.soldier_idle(store, this)
				end
			end
		end

		::label_524_0::

		coroutine.yield()
	end
end

scripts.aura_power_aspect_of_sol_summon = {}

function scripts.aura_power_aspect_of_sol_summon.update(this, store)
	local targets = table.filter(store.entities, function(k, v)
		return v.unit and v.vis and v.health and not v.health.dead and band(v.vis.flags, this.aura.vis_bans) == 0 and band(v.vis.bans, this.aura.vis_flags) == 0 and U.is_inside_ellipse(v.pos, this.pos, this.aura.radius) and (not this.aura.allowed_templates or table.contains(this.aura.allowed_templates, v.template_name)) and (not this.aura.excluded_templates or not table.contains(this.aura.excluded_templates, v.template_name)) and (not this.aura.excluded_entities or not table.contains(this.aura.excluded_entities, v.id))
	end)

	for _, target in pairs(targets) do
		local d = E:create_entity("damage")

		d.source_id = this.id
		d.target_id = target.id

		local dmin, dmax = this.aura.damage_min, this.aura.damage_max

		if this.aura.damage_inc then
			dmin = dmin + this.aura.damage_inc * this.aura.level
			dmax = dmax + this.aura.damage_inc * this.aura.level
		end

		if band(target.vis.flags, F_BOSS) ~= 0 then
			dmin = dmin * this.boss_damage_cap
			dmax = dmax * this.boss_damage_cap
		elseif band(target.vis.flags, F_MINIBOSS) ~= 0 then
			dmin = dmin * this.miniboss_damage_cap
			dmax = dmax * this.miniboss_damage_cap
		end

		d.value = math.random(dmin, dmax)
		d.damage_type = this.aura.damage_type
		d.track_damage = this.aura.track_damage
		d.xp_dest_id = this.aura.xp_dest_id
		d.xp_gain_factor = this.aura.xp_gain_factor

		queue_damage(store, d)

		local mods = this.aura.mods or {
			this.aura.mod
		}

		for _, mod_name in pairs(mods) do
			local m = E:create_entity(mod_name)

			m.modifier.level = this.aura.level
			m.modifier.target_id = target.id
			m.modifier.source_id = this.id

			if this.aura.hide_source_fx and target.id == this.aura.source_id then
				m.render = nil
			end

			queue_insert(store, m)
		end

		if this.aura.hit_fx then
			local fx = E:create_entity(this.aura.hit_fx)

			fx.pos.x, fx.pos.y = target.pos.x + target.unit.hit_offset.x, target.pos.y + target.unit.hit_offset.y
			fx.render.sprites[1].ts = store.tick_ts

			queue_insert(store, fx)
		end
	end

	queue_remove(store, this)
end

scripts.tower_wizard = {}

function scripts.tower_wizard.update(this, store)
	local shooter_sid = this.render.sid_shooter
	local scroll_sid = this.render.sid_scroll
	local a = this.attacks
	local ar = this.attacks.list[1]

	this._loading = false
	this.time = 0

	local atof = this.attacks.list[2]
	local ae = this.attacks.list[3]
	local asc = this.attacks.list[4]
	local ulti = this.attacks.list[5]
	local ult_start_cd = ulti ~= nil and store.wave_group_number == 0
	local pow_a = this.powers and this.powers.skill_a or nil
	local pow_b = this.powers and this.powers.skill_b or nil
	local pow_c = this.powers and this.powers.skill_c or nil
	local pow_ulti = this.powers and this.powers.ultimate or nil
	local last_ts = store.tick_ts - ar.cooldown

	ar.ts = store.tick_ts - ar.cooldown + a.attack_delay_on_spawn

	local attacks = {
		atof,
		asc,
		ae,
		ulti,
		ar
	}
	local pows = {
		pow_a,
		pow_c,
		pow_b,
		pow_ulti
	}
	local empowerments_previews
	local ar_count = 0

	if ulti then
		ulti.ts = store.tick_ts
		ulti.disabled = not pow_ulti.active
	end

	local function find_target(aa)
		local target, targets, pred_pos = U.find_foremost_enemy(store.entities, tpos(this), 0, a.range, 0, aa.vis_flags, aa.vis_bans, function(e)
			if aa.excluded_templates and table.contains(aa.excluded_templates, e.template_name) then
				return false
			end

			if aa.ignored_terrains then
				local current_t = GR:cell_type(e.pos.x, e.pos.y)

				for _, flag in ipairs(aa.ignored_terrains) do
					if band(current_t, flag) ~= 0 then
						return false
					end
				end
			end

			local node_offset = P:predict_enemy_node_advance(e, aa.node_prediction)
			local e_ni = e.nav_path.ni + node_offset

			return P:is_node_valid(e.nav_path.pi, e_ni)
		end)

		return target, targets, pred_pos
	end

	local function shoot_bolt(target, i, side)
		local b = E:create_entity(ar.bullet)

		b.bullet.damage_factor = this.tower.damage_factor
		b.pos.x, b.pos.y = this.pos.x + ar.bullet_start_offset[i].x, this.pos.y + ar.bullet_start_offset[i].y
		b.bullet.from = V.vclone(b.pos)
		b.bullet.to = V.vclone(target.pos)
		b.bullet.target_id = target.id
		b.bullet.source_id = this.id
		b.initial_impulse_angle_abs = b.initial_impulse_angle_abs - math.pi / 4 * side
		b.force_motion.v.x = 100 * side

		queue_insert(store, b)
	end

	::label_531_0::

	while true do
		if ult_start_cd and store.wave_group_number > 0 then
			ult_start_cd = false
			ulti.ts = store.tick_ts
		end

		if this.tower.blocked then
			coroutine.yield()
		else
			if this.powers then
				for k, pow in pairs(this.powers) do
					if pow.changed then
						pow.changed = nil

						if pow == pow_a then
							atof.cooldown = pow.cooldown[pow.level]
							atof.damage_min = pow.damage_min[pow.level]
							atof.damage_max = pow.damage_max[pow.level]

							if pow.level == 1 then
								atof.ts = store.tick_ts - atof.cooldown
							end

							atof.disabled = false
						end

						if pow == pow_b then
							ae.cooldown = pow.cooldown[pow.level]

							if pow.level == 1 then
								ae.ts = store.tick_ts - ae.cooldown
							end

							ae.disabled = false
						end

						if pow == pow_c then
							asc.cooldown = pow.cooldown[pow.level]

							if pow.level == 1 then
								asc.ts = store.tick_ts - asc.cooldown
							end

							asc.disabled = false
						end
					end
				end
			end

			if this._loading then
				this.time = this.time + store.tick_length
				this.render.sprites[shooter_sid].offset.y = 10 + 2.5 * math.sin(this.time * 1.5)
			end

			if this.ui.hover_active and this.ui.args == "skill_b" and not empowerments_previews and pow_b and pow_b.level == 0 then
				empowerments_previews = {}

				local targets = U.find_towers(store.entities, tpos(this), 0, a.range + ae.extra_range, function(v, o)
					return v.tower.type == "holder" and v.ui.can_click or v.id ~= this.id and (not ae.excluded_templates or not table.contains(ae.excluded_templates, v.template_name)) and v.vis and band(v.vis.flags, ae.vis_bans) == 0 and band(v.vis.bans, ae.vis_flags) == 0 and not table.contains(ae.exclude_tower_kind, v.tower.kind) and not U.has_modifiers(store, v, ae.mod) and v.tower.can_be_mod
				end)

				if targets then
					for _, target in pairs(targets) do
						local decal = E:create_entity("decal_tower_wizard_empowerment_preview")

						decal.pos.x, decal.pos.y = target.pos.x, target.pos.y - 0.1
						decal.render.sprites[1].ts = store.tick_ts

						queue_insert(store, decal)
						table.insert(empowerments_previews, decal)
					end
				end
			elseif empowerments_previews and (not this.ui.hover_active or this.ui.args ~= "skill_b") then
				for _, decal in pairs(empowerments_previews) do
					queue_remove(store, decal)
				end

				empowerments_previews = nil
			end

			for i, aa in pairs(attacks) do
				do
					local pow = pows[i]

					if (not pow or pow.level > 0) and aa.cooldown and store.tick_ts - aa.ts > aa.cooldown and store.tick_ts - last_ts > a.min_cooldown and not aa.disabled then
						if aa == ae then
							local towers = U.find_towers(store.entities, tpos(this), 0, a.range + aa.extra_range, function(v, o)
								return v.id ~= this.id and v.tower.can_be_mod and (not aa.excluded_templates or not table.contains(aa.excluded_templates, v.template_name))
							end)

							if not towers or #towers <= 0 then
								SU.delay_attack(store, aa, 5)

								goto label_531_1
							end

							local enemies = U.find_enemies_in_range(store.entities, tpos(this), 0, aa.enemy_check_range, 0, 0)

							if not enemies or #enemies <= 0 then
								SU.delay_attack(store, aa, 2)

								goto label_531_1
							end

							S:queue(aa.sound)

							if not this._loading then
								this._loading = true

								local soffset = this.shooter_offset

								U.y_animation_play(this, "shootstart", false, store.tick_ts, 1, shooter_sid)
							end

							local start_ts = store.tick_ts

							U.animation_start(this, "buff", false, store.tick_ts, 1, scroll_sid)
							U.animation_start(this, "buff", false, store.tick_ts, 1, shooter_sid)
							U.y_wait(store, aa.shoot_time)

							last_ts = store.tick_ts

							for _, tower in ipairs(towers) do
								local m = E:create_entity(ae.mod_fx)

								m.modifier.source_id = this.id
								m.modifier.target_id = tower.id
								m.modifier.level = pow.level
								m.pos.x, m.pos.y = tower.pos.x, tower.pos.y - 1
								m.modifier.duration = ae.duration[pow.level]

								queue_insert(store, m)

								local decal = E:create_entity(ae.decal)

								decal.render.sprites[1].ts = store.tick_ts
								decal.pos.x, decal.pos.y = tower.pos.x, tower.pos.y - 1.01
								decal.tween.ts = store.tick_ts
								decal.duration = ae.duration[pow.level]

								queue_insert(store, decal)

								local m = E:create_entity(ae.mod)

								m.modifier.source_id = this.id
								m.modifier.target_id = tower.id
								m.modifier.level = pow.level
								m.damage_factor = ae.damage_factor[pow.level]
								m.modifier.duration = ae.duration[pow.level]

								queue_insert(store, m)
							end

							while U.y_animation_wait(this, shooter_sid, 1) do
								coroutine.yield()
							end

							U.animation_start(this, "idle", false, store.tick_ts, true, scroll_sid)

							aa.ts = last_ts

							goto label_531_1
						end

						local enemy, enemies, pred_pos = find_target(aa)

						if not enemy then
							if this._loading then
								U.y_animation_play(this, "shootend", false, store.tick_ts, 1, shooter_sid)
								U.animation_start(this, "idle", false, store.tick_ts, true, shooter_sid, true)

								this._loading = false
							end

							SU.delay_attack(store, aa, fts(10))
						else
							local enemy_id = enemy.id
							local enemy_pos = enemy.pos

							if not this._loading then
								this._loading = true

								local soffset = this.shooter_offset
								local an, af, ai = U.animation_name_facing_point(this, "shootstart", enemy.pos, shooter_sid, soffset)

								U.y_animation_play(this, an, false, store.tick_ts, 1, shooter_sid)
							end

							last_ts = store.tick_ts

							if aa == atof then
								local an, af, ai = U.animation_name_facing_point(this, "firebook", enemy.pos, shooter_sid)

								S:queue(aa.sound)
								U.animation_start(this, an, false, store.tick_ts, 1, shooter_sid)
								U.y_wait(store, 0.5)

								local b = E:create_entity(aa.bullet)

								b.bullet.damage_min = aa.damage_min
								b.bullet.damage_max = aa.damage_max
								b.pos.x, b.pos.y = this.pos.x + aa.bullet_start_offset.x, this.pos.y + aa.bullet_start_offset.y
								b.bullet.from = V.vclone(b.pos)
								b.bullet.to = V.vclone(enemy_pos)
								b.bullet.target_id = enemy.id
								b.bullet.source_id = this.id
								b.bullet.level = pow and pow.level or 1

								queue_insert(store, b)

								aa.ts = last_ts
							elseif aa == asc then
								local an, af, ai = U.animation_name_facing_point(this, "throwbook", enemy.pos, shooter_sid)

								U.animation_start(this, an, af, store.tick_ts, 1, shooter_sid)
								S:queue(asc.sound)
								U.y_wait(store, aa.shoot_time)

								local b = E:create_entity(aa.bullet)

								b.bullet.damage_min = aa.hit_min_damage
								b.bullet.damage_max = aa.hit_max_damage
								b.pos.x, b.pos.y = this.pos.x + aa.bullet_start_offset.x, this.pos.y + aa.bullet_start_offset.y
								b.bullet.from = V.vclone(b.pos)
								b.bullet.to = V.v(enemy.pos.x + enemy.unit.hit_offset.x, enemy.pos.y + enemy.unit.hit_offset.y)
								b.bullet.target_id = enemy.id
								b.bullet.source_id = this.id
								b.bullet.level = pow and pow.level or 1

								queue_insert(store, b)

								aa.ts = last_ts
							elseif aa == ar then
								local an, af, ai = U.animation_name_facing_point(this, "shootloop", enemy.pos, shooter_sid)

								U.animation_start(this, an, false, store.tick_ts, 1, shooter_sid)

								aa.ts = last_ts

								local book_side = {
									-1,
									1
								}
								local targets = {
									enemy,
									enemy
								}

								if math.random(1, 2) == 1 and #enemies > 1 and V.dist2(enemy.pos.x, enemy.pos.y, enemies[2].pos.x, enemies[2].pos.y) < 2500 then
									targets[2] = enemies[2]
								end

								for i, side in ipairs(book_side) do
									local target = targets[i]

									shoot_bolt(target, i, side)
									U.y_wait(store, 0.15)
								end

								if this._attacks_for_xtra_attack then
									ar_count = ar_count + 1

									if ar_count >= this._attacks_for_xtra_attack then
										ar_count = 0

										local r = math.random(1, 2)

										shoot_bolt(targets[r], r, book_side[r])
									end
								end

								goto label_531_0
							elseif aa == ulti then
								U.animation_start(this, aa.animation, false, store.tick_ts, 1, shooter_sid)
								U.animation_start(this, "ult", false, store.tick_ts, 1, scroll_sid)
								S:queue(aa.sound)
								U.y_wait(store, aa.shoot_time)
								signal.emit("tower-ultimate-used", this)

								local m = E:create_entity(aa.mod)

								m.modifier.target_id = enemy.id
								m.modifier.source_id = this.id
								m.modifier.level = 1

								queue_insert(store, m)

								while U.y_animation_wait(this, shooter_sid, 1) do
									coroutine.yield()
								end

								aa.ts = last_ts
							end
						end
					end
				end

				::label_531_1::
			end

			if store.tick_ts - ar.ts > this.tower.long_idle_cooldown then
				local soffset = this.shooter_offset
				local an, af, ai = U.animation_name_facing_point(this, "idle", this.tower.long_idle_pos, shooter_sid, soffset)

				U.animation_start_group(this, an, false, store.tick_ts, true, "layers")
			end

			coroutine.yield()
		end
	end
end

scripts.controller_tower_wizard_book_bounce = {}

function scripts.controller_tower_wizard_book_bounce.update(this, store)
	local b = E:create_entity(this._bullet)

	b.bullet.level = this.level
	b.bullet.source_id = this.id
	b.pos.x, b.pos.y = this.pos.x, this.pos.y
	b.bullet.from = V.vclone(b.pos)
	b.bullet.source_id = this.id
	b.bullet.level = this.aura.level or 1

	local r_x = math.random(10, 30)

	if math.random() > 0.5 then
		r_x = r_x * -1
	end

	local r_y = math.random(10, 30)

	if math.random() > 0.5 then
		r_y = r_y * -1
	end

	local nearest_nodes = P:nearest_nodes(this.pos.x + r_x, this.pos.y + r_y)
	local pi, spi, ni = unpack(nearest_nodes[1])
	local pred = P:node_pos(pi, spi, ni)

	b.bullet.to = V.vclone(pred)

	queue_insert(store, b)
	queue_remove(store, this)
end

scripts.aura_wizard_skill_c = {}

function scripts.aura_wizard_skill_c.update(this, store)
	U.y_animation_play(this, "land", false, store.tick_ts, 1)

	local cooldown = 0.5
	local last_ts = store.tick_ts
	local bullets = this.bullet_count[this.aura.level]

	while bullets > 0 do
		U.animation_start(this, "idle", false, store.tick_ts, 1)

		if cooldown < store.tick_ts - last_ts then
			U.animation_start(this, "shoot", false, store.tick_ts, false)

			last_ts = store.tick_ts - cooldown

			U.y_wait(store, 0.5)

			local enemies = U.find_enemies_in_range(store.entities, this.pos, 0, this._range, 0, 0)
			local b = E:create_entity(this._bullet)

			b.bullet.damage_min = this.min_damage[this.aura.level]
			b.bullet.damage_max = this.max_damage[this.aura.level]
			b.pos.x, b.pos.y = this.pos.x, this.pos.y
			b.bullet.from = V.vclone(b.pos)
			b.bullet.source_id = this.id

			if enemies and #enemies > 0 then
				local enemy = enemies[1]

				b.bullet.to = V.vclone(enemy.pos)
				b.bullet.target_id = enemy.id
			else
				local spread = 30
				local r_x = math.random(10, 30)

				if math.random() > 0.5 then
					r_x = r_x * -1
				end

				local r_y = math.random(10, 30)

				if math.random() > 0.5 then
					r_y = r_y * -1
				end

				local pos = V.v(r_x + this.pos.x, r_y + this.pos.y)

				b.bullet.to = V.vclone(pos)
				b.bullet.target_id = nil
			end

			queue_insert(store, b)

			bullets = bullets - 1
		else
			coroutine.yield()
		end
	end

	U.animation_start(this, "idle", false, store.tick_ts, 1)
	U.y_wait(store, 1)

	this.tween.disabled = false
	this.tween.ts = store.tick_ts

	U.y_wait(store, 2)
	queue_remove(store, this)
end

scripts.mod_wizard_ultimate = {}

function scripts.mod_wizard_ultimate.update(this, store, script)
	local m = this.modifier

	this.modifier.ts = store.tick_ts

	local target = store.entities[m.target_id]
	local time_hit = this.time_hit
	local decal_spawn_time = this.decal_spawn_time
	local damaged = false
	local decal_spawned = false

	if not target or not target.pos then
		queue_remove(store, this)

		return
	end

	this.pos = target.pos

	S:queue(this.sound)

	while true do
		target = store.entities[m.target_id]

		if m.duration >= 0 and store.tick_ts - m.ts > m.duration or m.last_node and target.nav_path.ni > m.last_node then
			queue_remove(store, this)

			return
		end

		if not damaged and time_hit < store.tick_ts - m.ts then
			damaged = true

			if target and not target.health.dead then
				local d = E:create_entity("damage")

				d.source_id = this.id
				d.target_id = target.id
				d.value = this.damage
				d.damage_type = this.damage_type

				queue_damage(store, d)
			end

			local targets = U.find_enemies_in_range(store.entities, this.pos, 0, this.stun_range, this.stun_vis_flags, this.stun_bans)

			if targets then
				for _, target in pairs(targets) do
					local s = E:create_entity(this.mod_stun)

					s.modifier.target_id = target.id
					s.modifier.source_id = m.source_id
					s.modifier.duration = this.stun_duration

					queue_insert(store, s)
				end
			end
		end

		if not decal_spawned and decal_spawn_time < store.tick_ts - m.ts then
			decal_spawned = true

			local decal = E:create_entity(this.hit_decal)

			decal.pos = V.vclone(this.pos)
			decal.render.sprites[1].ts = store.tick_ts

			queue_insert(store, decal)
		end

		coroutine.yield()
	end
end

scripts.mod_tower_arcane_wizard_power_empowerment = {}

function scripts.mod_tower_arcane_wizard_power_empowerment.update(this, store)
	local m = this.modifier
	local target = store.entities[m.target_id]

	if target then
		this.pos = target.pos
	end

	m.ts = store.tick_ts

	if this.tween then
		this.tween.ts = store.tick_ts
	end

	while store.tick_ts - m.ts < m.duration and store.entities[this.modifier.source_id] do
		coroutine.yield()
	end

	queue_remove(store, this)
end

function scripts.mod_tower_arcane_wizard_power_empowerment.remove(this, store)
	local m = this.modifier
	local target = store.entities[m.target_id]

	if not target or not target.tower then
		log.error("error removing mod_tower_factors %s", this.id)

		return true
	end

	if this.damage_factor then
		target.tower.damage_factor = target.tower.damage_factor / this.damage_factor
	end

	local source = store.entities[this.source_id]

	if source then
		source.attacks.list[3].ts = store.tick_ts
	end

	return true
end

scripts.tower_arcane_wizard_power_empowerment_mark_mod = {}

function scripts.tower_arcane_wizard_power_empowerment_mark_mod.update(this, store)
	local m = this.modifier

	m.ts = store.tick_ts

	while true do
		local target = store.entities[m.target_id]

		if not target or m.duration >= 0 and store.tick_ts - m.ts > m.duration then
			queue_remove(store, this)

			return
		end

		coroutine.yield()
	end
end

scripts.decal_tower_wizard_skill_b = {}

function scripts.decal_tower_wizard_skill_b.update(this, store)
	local s = this.render.sprites[1]

	while true do
		if this.duration >= 0 and store.tick_ts - s.ts > this.duration then
			queue_remove(store, this)

			return
		end

		coroutine.yield()
	end
end

scripts.tower_arcane_wizard_ray_disintegrate_mod = {}

function scripts.tower_arcane_wizard_ray_disintegrate_mod.update(this, store)
	local m = this.modifier
	local target = store.entities[m.target_id]

	if not target or target.health.dead then
		return
	end

	local is_boss = U.flag_has(target.vis.flags, bor(F_BOSS, F_MINIBOSS))

	if not is_boss then
		SU.stun_inc(target)
	end

	this.pos = target.pos
	m.ts = store.tick_ts

	while true do
		target = store.entities[m.target_id]

		if not target or target.health.dead then
			break
		end

		if store.tick_ts - m.ts >= m.duration then
			if is_boss then
				local d = E:create_entity("damage")

				d.source_id = this.id
				d.target_id = target.id
				d.damage_type = DAMAGE_MAGICAL
				d.value = this.boss_damage_config[m.level]

				queue_damage(store, d)

				break
			else
				local d = E:create_entity("damage")

				d.source_id = this.id
				d.target_id = target.id
				d.damage_type = m.damage_type
				d.value = m.damage
				d.pop = m.pop
				d.pop_chance = m.pop_chance
				d.pop_conds = m.pop_conds

				queue_damage(store, d)

				break
			end
		end

		if this.render and m.use_mod_offset and target.unit.hit_offset then
			this.render.sprites[1].offset.x, this.render.sprites[1].offset.y = target.unit.hit_offset.x, target.unit.hit_offset.y
		end

		coroutine.yield()
	end

	queue_remove(store, this)
end

scripts.towers_portrait = {}

function scripts.towers_portrait.get_info(this)
	return {
		type = STATS_TYPE_TEXT_PORTRAIT,
		desc = _((this.info.i18n_key or string.upper(this.template_name)) .. "_DESCRIPTION")
	}
end

scripts.tower_archers = {}

function scripts.tower_archers.update(this, store)
	local sa = this.powers and this.powers.skill_a or nil
	local sb = this.powers and this.powers.skill_b or nil
	local sc = this.powers and this.powers.skill_c or nil
	local su = this.powers and this.powers.ultimate or nil
	local a = this.attacks
	local ba = this.attacks.list[1]
	local saa = this.attacks.list[2]
	local sba = this.timed_attacks and this.timed_attacks.list[1]
	local skill_b_previews
	local skill_b_eagle_cd = 20
	local skill_b_eagle_ts = store.tick_ts - skill_b_eagle_cd

	this.skill_b_eagle = nil

	local sca = this.timed_attacks and this.timed_attacks.list[2]
	local sua = this.timed_attacks and this.timed_attacks.list[3]
	local ult_start_cd = sua ~= nil and store.wave_group_number == 0

	if sua then
		sua.ts = store.tick_ts
		sua.disabled = not su.active
	end

	local idle_ts = store.tick_ts
	local shooter_idx = 1

	if not a._last_target_pos then
		a._last_target_pos = {}
	end

	this.shooters_conts = {}

	for i = 1, #this.shooters_sids do
		if not a._last_target_pos[i] then
			a._last_target_pos[i] = v(REF_W, 0)
		end

		this.shooters_conts[i] = E:create_entity(this.shooter_controller)
		this.shooters_conts[i].tower_ref = this
		this.shooters_conts[i].shooter_id = i
		this.shooters_conts[i].shooter_sid = this.shooters_sids[i]
		this.shooters_conts[i].bow_sid = table.contains(this.front_shooters_sids, this.shooters_sids[i]) and this.bows_sids[i]
		this.shooters_conts[i].long_idle_pos = this.tower.long_idle_pos[i]

		queue_insert(store, this.shooters_conts[i])
	end

	local function shot_animation(attack, shooter_idx, pos)
		local ssid = this.shooters_sids[shooter_idx]
		local soffset = this.render.sprites[ssid].offset
		local s = this.render.sprites[ssid]
		local an, af, ai = U.animation_name_facing_point(this, attack.animation, pos, ssid, soffset)

		U.animation_start(this, an, af, store.tick_ts, 1, ssid)

		if table.contains(this.front_shooters_sids, ssid) then
			local bsid = this.bows_sids[shooter_idx]
			local s = this.render.sprites[bsid]

			s.hidden = ai == 1

			if ai == 2 then
				U.animation_start(this, an, af, store.tick_ts, 1, bsid)
			end
		end
	end

	local function shoot_bullet_armor_piercer(attack, shooter_idx, enemy, index)
		local ssid = this.shooters_sids[shooter_idx]
		local shooting_up = tpos(this).y < enemy.pos.y
		local shooting_right = tpos(this).x < enemy.pos.x
		local soffset = this.render.sprites[ssid].offset
		local boffset = attack.bullet_start_offset[shooting_up and 1 or 2]
		local hoffset = V.vclone(enemy.unit.hit_offset)

		if enemy.render.sprites[1].flip_x then
			hoffset.x = -hoffset.x
		end

		local b = E:create_entity(attack.bullet)

		b.pos.x = this.pos.x + soffset.x + boffset.x * (shooting_right and 1 or -1)
		b.pos.y = this.pos.y + soffset.y + boffset.y
		b.bullet.from = V.vclone(b.pos)
		b.bullet.to = V.v(enemy.pos.x + hoffset.x, enemy.pos.y + hoffset.y)
		b.bullet.target_id = enemy.id
		b.bullet.source_id = this.id
		b.bullet.damage_factor = this.tower.damage_factor
		b.bullet.damage_max = sa.damage_max[sa.level]
		b.bullet.damage_min = sa.damage_min[sa.level]

		if b.bullet.fixed_height then
			local height = b.bullet.fixed_height + (index - 1) * 15

			b.bullet.fixed_height = height
		end

		b.bullet.flight_time = b.bullet.flight_time + index * fts(6)

		queue_insert(store, b)
	end

	local function prepare_targets_armor_piercer(enemy, enemies)
		local reload_enemy, reload_enemies = U.find_foremost_enemy(store.entities, tpos(this), 0, a.range, false, saa.vis_flags, saa.vis_bans)

		if reload_enemy and #reload_enemies > 0 then
			enemy = reload_enemy
			enemies = reload_enemies
		end

		local targets = {
			enemy
		}
		local first_target_on_left = enemy.pos.x < this.pos.x

		for i = 2, saa.targets do
			local enemy_index = km.zmod(i, #enemies)
			local e = enemies[enemy_index]

			if first_target_on_left and e.pos.x <= this.pos.x then
				table.insert(targets, e)
			elseif not first_target_on_left and e.pos.x >= this.pos.x then
				table.insert(targets, e)
			elseif i > 1 then
				table.insert(targets, targets[i - 1])
			end
		end

		table.sort(targets, function(e1, e2)
			return V.dist2(this.pos.x, this.pos.y, e1.pos.x, e1.pos.y) > V.dist2(this.pos.x, this.pos.y, e2.pos.x, e2.pos.y)
		end)

		return targets
	end

	local function check_upgrades_purchase()
		if this.powers then
			for _, pow in pairs(this.powers) do
				if pow.changed then
					pow.changed = nil

					if pow == sa then
						saa.disabled = false
						saa.bullet = "bullet_archers_skill_a_lvl" .. pow.level

						if pow.level == 1 then
							saa.ts = store.tick_ts - saa.cooldown
						end
					elseif pow == sb then
						sba.disabled = false
						sba.max_range = sba.base_range * sb.range_factor[pow.level]

						if pow.level == 1 then
							sba.ts = store.tick_ts - sba.cooldown
						end
					elseif pow == sc then
						sca.disabled = false

						if pow.level == 1 then
							sca.ts = store.tick_ts - sca.cooldown
						end
					end
				end
			end
		end
	end

	local function skill_b_allows_tower_kind(tower)
		if not table.contains(sba.exclude_tower_kind, tower.tower.kind) then
			return true
		end

		-- The swamp monster remains registered as a barrack in both modes.
		-- Its ranged form is a real attacking tower and should receive range buffs.
		return tower.tower.type == "swamp_monster" and tower.tower_upgrade_persistent_data and tower.tower_upgrade_persistent_data.current_mode == 1
	end

	ba.ts = store.tick_ts - ba.cooldown + a.attack_delay_on_spawn

	for idx, ssid in ipairs(this.shooters_sids) do
		local soffset = this.render.sprites[ssid].offset
		local s = this.render.sprites[ssid]
		local an, af, ai = U.animation_name_facing_point(this, "idle", a._last_target_pos[idx], ssid, soffset)

		U.animation_start(this, an, af, store.tick_ts, 1, ssid)

		if table.contains(this.front_shooters_sids, ssid) then
			local bsid = this.bows_sids[shooter_idx]
			local s = this.render.sprites[bsid]

			s.hidden = ai == 1

			if ai == 2 then
				U.animation_start(this, an, af, store.tick_ts, 1, bsid)
			end
		end
	end

	::label_546_0::

	while true do
		if ult_start_cd and store.wave_group_number > 0 then
			ult_start_cd = false
			sua.ts = store.tick_ts
		end

		if this.tower.blocked then
			coroutine.yield()
		else
			check_upgrades_purchase()
			SU.towers_swaped(store, this, this.attacks.list)

			if this.ui.hover_active and this.ui.args == "skill_b" and not skill_b_previews and sb and sb.level == 0 then
				skill_b_previews = {}

				local targets = U.find_towers(store.entities, tpos(this), 0, sba.max_range, function(v, o)
					return v.tower.type == "holder" and v.ui.can_click or (not sba.excluded_templates or not table.contains(sba.excluded_templates, v.template_name)) and v.vis and band(v.vis.flags, sba.vis_bans) == 0 and band(v.vis.bans, sba.vis_flags) == 0 and skill_b_allows_tower_kind(v) and not U.has_modifiers(store, v, sba.mod) and v.tower.can_be_mod
				end)

				if targets then
					for _, target in pairs(targets) do
						local decal = E:create_entity(sba.decal_preview)

						decal.pos = target.pos
						decal.render.sprites[1].ts = store.tick_ts
						decal.tween.ts = store.tick_ts

						local mt = E:get_template(sba.mod)

						if mt.offset_per_tower[target.tower.type] then
							decal.render.sprites[1].offset = mt.offset_per_tower[target.tower.type]
						end

						queue_insert(store, decal)
						table.insert(skill_b_previews, decal)
					end
				end
			elseif skill_b_previews and (not this.ui.hover_active or this.ui.args ~= "skill_b") then
				for _, decal in pairs(skill_b_previews) do
					queue_remove(store, decal)
				end

				skill_b_previews = nil
			end

			if this.powers and sa and sa.level > 0 and store.tick_ts - saa.ts > saa.cooldown then
				local enemy, enemies, pred_pos = U.find_foremost_enemy(store.entities, tpos(this), 0, a.range, saa.shoot_time, saa.vis_flags, saa.vis_bans)

				if not enemy then
					SU.delay_attack(store, saa, fts(10))
				else
					local start_ts = store.tick_ts

					S:queue(saa.sound)

					shooter_idx = km.zmod(shooter_idx + 1, #this.shooters_sids)

					if shooter_idx > 2 then
						shooter_idx = 1
					end

					this.shooters_conts[shooter_idx].idle_ts = store.tick_ts

					shot_animation(saa, shooter_idx, enemy.pos)

					while store.tick_ts - start_ts < saa.shoot_time do
						check_upgrades_purchase()
						coroutine.yield()
					end

					local targets = prepare_targets_armor_piercer(enemy, enemies)
					local arrow_number = 1

					if targets[1].pos.x < this.pos.x then
						local ssid = this.shooters_sids[shooter_idx]

						this.render.sprites[ssid].flip_x = true
					end

					for _, enemy in pairs(targets) do
						shoot_bullet_armor_piercer(saa, shooter_idx, enemy, arrow_number)

						arrow_number = arrow_number + 1
					end

					U.y_animation_wait(this, this.shooters_sids[shooter_idx])

					saa.ts = start_ts
					ba.ts = start_ts
					this.shooters_conts[shooter_idx].idle_ts = store.tick_ts

					goto label_546_0
				end
			end

			if this.powers and sb and not sba.disabled and sb.level > 0 and store.tick_ts - sba.ts > sba.cooldown then
				if skill_b_eagle_cd < store.tick_ts - skill_b_eagle_ts then
					this.skill_b_eagle = E:create_entity(sba.eagle)
					this.skill_b_eagle.pos = this.pos
					this.skill_b_eagle.render.sprites[1].ts = store.tick_ts

					queue_insert(store, this.skill_b_eagle)

					skill_b_eagle_ts = store.tick_ts
				end

				local function filter_func(t)
					local has_mod, mods = U.has_modifiers(store, t, sba.mod)
					local max_factor = 1

					if has_mod and mods and #mods >= 1 then
						for k, v in pairs(mods) do
							if max_factor < v.range_factor then
								max_factor = v.range_factor
							end
						end
					end

					return t.tower.can_be_mod and max_factor < sb.range_factor[sb.level] and band(t.vis.flags, sba.vis_bans) == 0 and band(t.vis.bans, sba.vis_flags) == 0 and skill_b_allows_tower_kind(t)
				end

				local towers = U.find_towers(store.entities, tpos(this), sba.min_range, sba.max_range, function(v, o)
					return (not sba.excluded_templates or not table.contains(sba.excluded_templates, v.template_name)) and (not filter_func or filter_func(v))
				end)

				if not towers or #towers <= 0 then
					SU.delay_attack(store, sba, sba.cooldown)

					goto label_546_1
				end

				local start_ts = store.tick_ts

				S:queue(sba.sound)

				for _, tower in ipairs(towers) do
					local m = E:create_entity(sba.mod)

					m.modifier.source_id = this.id
					m.modifier.target_id = tower.id
					m.modifier.level = sb.level
					m.range_factor = sb.range_factor[sb.level]
					m.tween.ts = store.tick_ts

					if m.offset_per_tower[tower.tower.type] then
						m.render.sprites[1].offset = m.offset_per_tower[tower.tower.type]
						m.render.sprites[2].offset = m.offset_per_tower[tower.tower.type]
					end

					queue_insert(store, m)
				end

				sba.ts = start_ts
				ba.ts = start_ts
				idle_ts = store.tick_ts

				goto label_546_0
			end

			::label_546_1::

			if this.powers and sc and not sca.disabled and sc.level > 0 and store.tick_ts - sca.ts > sca.cooldown then
				local enemy, enemies, pred_pos = U.find_foremost_enemy(store.entities, tpos(this), 0, a.range, sca.shoot_time, sca.vis_flags, sca.vis_bans, function(e, o)
					return e.health and e.health.hp >= sca.min_hp
				end)

				if not enemy then
					SU.delay_attack(store, sca, fts(10))
				else
					local start_ts = store.tick_ts
					local eagle = E:create_entity(sca.eagle)

					eagle.render.sprites[1].ts = store.tick_ts
					eagle.pos = enemy.pos

					queue_insert(store, eagle)
					S:queue(sca.sound)

					while store.tick_ts - start_ts < sca.cast_time do
						check_upgrades_purchase()
						coroutine.yield()
					end

					local m = E:create_entity(sca.mod)

					m.modifier.source_id = this.id
					m.modifier.target_id = enemy.id
					m.modifier.level = sc.level

					queue_insert(store, m)

					sca.ts = start_ts
					idle_ts = store.tick_ts

					goto label_546_0
				end
			end

			if this.powers and su and not sua.disabled and store.tick_ts - sua.ts > sua.cooldown then
				local enemies = U.find_enemies_in_range(store.entities, tpos(this), 0, a.range, sua.vis_flags, sua.vis_bans)

				if not enemies or #enemies == 0 then
					SU.delay_attack(store, sua, fts(10))
				else
					local found_enemy = enemies and #enemies >= sua.min_targets

					if enemies and #enemies < sua.min_targets then
						for k, v in pairs(enemies) do
							if v.health.hp >= sua.min_hp then
								found_enemy = true

								break
							end
						end
					end

					if not found_enemy then
						SU.delay_attack(store, sua, fts(10))
					else
						sua.ts = store.tick_ts

						signal.emit("tower-ultimate-used", this)
						S:queue(sua.sound)

						this.ulti_decal_bg = E:create_entity(sua.decal_bg)
						this.ulti_decal_bg.pos = this.pos
						this.ulti_decal_bg.render.sprites[1].offset = this.render.sprites[2].offset

						queue_insert(store, this.ulti_decal_bg)
						U.animation_start(this.ulti_decal_bg, "start", nil, store.tick_ts, false)
						U.animation_start(this, sua.animation_in, nil, store.tick_ts, false, 4)
						U.y_wait(store, sua.cast_time)

						local old_cd = ba.cooldown

						ba.cooldown = sua.attack_cd

						local start_ts = store.tick_ts

						while store.tick_ts - start_ts < sua.duration do
							if this.tower.blocked then
								break
							end

							if this.render.sprites[4].name == sua.animation_in and U.animation_finished(this, 4) then
								U.animation_start(this, sua.animation_loop, nil, store.tick_ts, true, 4)
							end

							if this.ulti_decal_bg.render.sprites[1].name == sua.animation_in and U.animation_finished(this.ulti_decal_bg) then
								U.animation_start(this.ulti_decal_bg, "idle", nil, store.tick_ts, true)
							end

							if store.tick_ts - ba.ts > ba.cooldown then
								local enemies = U.find_enemies_in_range(store.entities, tpos(this), 0, a.range, 0, 0, function(e, o)
									return not U.has_modifiers(store, e, sua.mod)
								end)

								if not enemies or #enemies == 0 then
									enemies = U.find_enemies_in_range(store.entities, tpos(this), 0, a.range, 0, 0)
								end

								if not enemies or #enemies == 0 then
									SU.delay_attack(store, ba, fts(10))
								else
									local enemy = enemies[math.random(1, #enemies)]
									local mod = E:create_entity(sua.mod)

									mod.modifier.source_id = this.id
									mod.modifier.target_id = enemy.id

									queue_insert(store, mod)

									local node_offset = P:predict_enemy_node_advance(enemy, ba.shoot_time + fts(10))
									local e_ni = enemy.nav_path.ni + node_offset
									local e_pos = P:node_pos(enemy.nav_path.pi, enemy.nav_path.spi, e_ni)

									ba.ts = store.tick_ts
									shooter_idx = km.zmod(shooter_idx + 1, #this.shooters_sids)
									this.shooters_conts[shooter_idx].shoot = true
									this.shooters_conts[shooter_idx].attack = ba
									this.shooters_conts[shooter_idx].trigger_enemy = enemy
									this.shooters_conts[shooter_idx].pred_pos = V.vclone(e_pos)
									this.shooters_conts[shooter_idx].ultimate = true
								end
							end

							coroutine.yield()
						end

						ba.cooldown = old_cd

						U.animation_start(this.ulti_decal_bg, "leave", nil, store.tick_ts, false)
						U.y_animation_play(this, sua.animation_out, nil, store.tick_ts, 1, 4)
						queue_remove(store, this.ulti_decal_bg)

						this.ulti_decal_bg = nil
					end
				end
			end

			if store.tick_ts - ba.ts > ba.cooldown then
				local trigger_enemy, _, pred_pos = U.find_foremost_enemy(store.entities, tpos(this), 0, a.range, false, ba.vis_flags, ba.vis_bans)

				if not trigger_enemy or not pred_pos then
					SU.delay_attack(store, ba, fts(10))
				else
					ba.ts = store.tick_ts
					shooter_idx = km.zmod(shooter_idx + 1, #this.shooters_sids)
					this.shooters_conts[shooter_idx].shoot = true
					this.shooters_conts[shooter_idx].attack = ba
					this.shooters_conts[shooter_idx].trigger_enemy = trigger_enemy
					this.shooters_conts[shooter_idx].pred_pos = V.vclone(pred_pos)
				end
			end

			coroutine.yield()
		end
	end
end

function scripts.tower_archers.remove(this, store)
	for i = 1, #this.shooters_conts do
		queue_remove(store, this.shooters_conts[i])
	end

	if this.tower.level < 4 then
		return true
	end

	local sb = this.powers and this.powers.skill_b or nil
	local sba = this.timed_attacks and this.timed_attacks.list[1]

	if sb.level > 0 then
		if this.skill_b_eagle then
			queue_remove(store, this.skill_b_eagle)
		end

		local mods = SSO and SSO:get_p_list("modifiers") or store.entities

		for _, m in pairs(mods) do
			if m.template_name == sba.mod and m.modifier and m.modifier.source_id == this.id then
				queue_remove(store, m)
			end
		end
	end

	if this.ulti_decal_bg then
		queue_remove(store, this.ulti_decal_bg)
	end

	return true
end

scripts.controller_archers_shooter = {}

function scripts.controller_archers_shooter.update(this, store)
	local ss = this.tower_ref.render.sprites[this.shooter_sid]
	local sx = tpos(this.tower_ref).x + ss.offset.x
	local bs = this.bow_sid and this.tower_ref.render.sprites[this.bow_sid]
	local a = this.tower_ref.attacks
	local idle_cd = this.tower_ref.tower.long_idle_cooldown + math.random()

	this.idle_ts = store.tick_ts - idle_cd

	local function shot_animation(ts)
		local soffset = V.vclone(ss.offset)

		soffset.y = -soffset.y

		local an, af, ai = U.animation_name_facing_point(this.tower_ref, this.attack.animation, this.pred_pos, this.shooter_sid, soffset)

		U.animation_start(this.tower_ref, an, af, ts, 1, this.shooter_sid, true)

		if bs then
			bs.hidden = ai == 1

			if ai == 2 then
				U.animation_start(this.tower_ref, an, af, ts, 1, this.bow_sid, true)
			end
		end
	end

	local function shoot_bullet(enemy, pred_pos, predict_pos)
		local ssid = this.shooter_sid
		local shooting_up = tpos(this.tower_ref).y - ss.offset.y < pred_pos.y
		local shooting_right = not ss.flip_x
		local soffset = ss.offset
		local boffset = this.attack.bullet_start_offset[shooting_up and 1 or 2]
		local hoffset = enemy and V.vclone(enemy.unit.hit_offset) or V.v(0, 0)
		local b = E:create_entity(this.attack.bullet)

		b.pos.x = this.tower_ref.pos.x + soffset.x + boffset.x * (shooting_right and 1 or -1)
		b.pos.y = this.tower_ref.pos.y + soffset.y + boffset.y
		b.bullet.from = V.vclone(b.pos)
		b.bullet.to = V.v(pred_pos.x + hoffset.x, pred_pos.y + hoffset.y)
		b.bullet.target_id = enemy and enemy.id
		b.bullet.source_id = this.tower_ref.id
		b.bullet.damage_factor = this.tower_ref.tower.damage_factor or 1

		if b.bullet.critical_chance and math.random() < b.bullet.critical_chance then
			b.bullet.damage_factor = b.bullet.damage_factor * 2
			b.bullet.pop = {
				"pop_crit"
			}
			b.bullet.pop_conds = DR_DAMAGE

			if b.bullet.crit_ignores_armor then
				b.bullet.reduce_armor = 1
			end
		end

		b.bullet.flight_time = 2 * (math.sqrt(2 * b.bullet.fixed_height * b.bullet.g * -1) / b.bullet.g * -1)
		b.bullet.predict_target_pos = predict_pos

		queue_insert(store, b)
	end

	while true do
		if this.shoot then
			this.shoot = false

			local aa = this.attack

			shot_animation(store.tick_ts)
			U.y_wait(store, aa.shoot_time)

			local enemy = this.trigger_enemy
			local new_enemy

			if this.ultimate then
				local enemies = U.find_enemies_in_range(store.entities, tpos(this.tower_ref), 0, a.range, 0, 0)

				if enemies and #enemies > 0 then
					new_enemy = enemies[math.random(1, #enemies)]
				end
			else
				new_enemy = U.find_foremost_enemy(store.entities, tpos(this.tower_ref), 0, a.range, fts(10), aa.vis_flags, aa.vis_bans)
			end

			if new_enemy then
				this.pred_pos = new_enemy.pos

				shot_animation(ss.ts)

				enemy = new_enemy
			end

			shoot_bullet(enemy, this.pred_pos, new_enemy ~= nil)

			a._last_target_pos[this.shooter_id] = V.vclone(this.pred_pos)

			U.y_animation_wait(this.tower_ref, this.shooter_sid)

			this.idle_ts = store.tick_ts
			this.ultimate = false
		end

		if idle_cd < store.tick_ts - this.idle_ts then
			this.idle_ts = store.tick_ts
			idle_cd = this.tower_ref.tower.long_idle_cooldown + math.random()

			local an, af = U.animation_name_facing_point(this.tower_ref, "idle", this.long_idle_pos, this.shooter_sid)

			U.animation_start(this.tower_ref, an, af, store.tick_ts, true, this.shooter_sid)

			if bs then
				U.animation_start(this.tower_ref, an, af, store.tick_ts, true, this.bow_sid)
			end
		end

		coroutine.yield()
	end
end

scripts.decal_archers_skill_b_eagle = {}

function scripts.decal_archers_skill_b_eagle.update(this, store)
	local start_ts = store.tick_ts

	while true do
		if store.tick_ts - start_ts > fts(130) then
			this.render.sprites[1].draw_order = -1
		elseif store.tick_ts - start_ts > fts(90) then
			this.render.sprites[1].draw_order = 10
		elseif store.tick_ts - start_ts > fts(60) then
			this.render.sprites[1].draw_order = -1
		elseif store.tick_ts - start_ts > fts(12) then
			this.render.sprites[1].draw_order = 10
		else
			this.render.sprites[1].draw_order = -1
		end

		coroutine.yield()
	end
end

scripts.mod_archers_skill_c_weak = {}

function scripts.mod_archers_skill_c_weak.insert(this, store, script)
	local target = store.entities[this.modifier.target_id]

	if not target then
		return false
	end

	if band(this.modifier.vis_flags, target.vis.bans) ~= 0 or band(this.modifier.vis_bans, target.vis.flags) ~= 0 then
		log.paranoid("mod %s cannot be applied to entity %s:%s because of vis flags/bans", this.template_name, target.id, target.template_name)

		return false
	end

	local target_id = this.modifier.target_id
	local template_name = this.template_name
	local modifiers = table.filter(store.entities, function(k, v)
		return v.modifier and v.modifier.target_id == target_id and v.template_name == template_name and not v.pending_removal
	end)

	if #modifiers > 0 then
		local base_modifier = modifiers[1]

		base_modifier.modifier.ts = store.tick_ts
		this.render = nil

		if base_modifier.render then
			for i = 1, #base_modifier.render.sprites do
				base_modifier.render.sprites[i].ts = store.tick_ts
			end
		end

		if base_modifier.tween then
			base_modifier.tween.ts = store.tick_ts
		end
	end

	if not target or target.health.dead or not target.unit then
		return false
	end

	if band(target.vis.flags, F_BOSS) == 0 and this.received_damage_factor_config then
		this.received_damage_factor = this.received_damage_factor_config[this.modifier.level]
		target.health.damage_factor = target.health.damage_factor * this.received_damage_factor
	end

	local target = store.entities[target_id]

	if band(target.vis.flags, F_BOSS) ~= 0 and this.boss_received_damage_factor_config then
		this.received_damage_factor = this.boss_received_damage_factor_config[this.modifier.level]
		target.health.damage_factor = target.health.damage_factor * this.received_damage_factor
	end

	this.modifier.duration = this.modifier_duration[this.modifier.level]

	if this.render then
		for _, s in pairs(this.render.sprites) do
			s.ts = store.tick_ts

			if s.size_names then
				s.name = s.size_names[target.unit.size]
			end

			if s.size_scales then
				s.scale = s.size_scales[target.unit.size]
			end
		end

		if target.unit then
			local s = this.render.sprites[1]
			local flip_sign = 1

			if target.render then
				flip_sign = target.render.sprites[1].flip_x and -1 or 1
			end

			if this.modifier.use_mod_offset and target.unit.mod_offset then
				s.offset.x, s.offset.y = target.unit.mod_offset.x * flip_sign, target.unit.mod_offset.y
			end
		end
	end

	signal.emit("mod-applied", this, target)

	return true
end

function scripts.mod_archers_skill_c_weak.update(this, store, script)
	local m = this.modifier

	this.modifier.ts = store.tick_ts

	local target = store.entities[m.target_id]

	if not target or not target.pos then
		queue_remove(store, this)

		return
	end

	this.pos = target.pos

	U.y_animation_play(this, "start", nil, store.tick_ts, 1)
	U.animation_start(this, "idle", nil, store.tick_ts, true)

	while true do
		target = store.entities[m.target_id]

		if not target or target.health.dead or m.duration >= 0 and store.tick_ts - m.ts > m.duration or m.last_node and target.nav_path.ni > m.last_node then
			U.y_animation_play(this, "fade", nil, store.tick_ts, 1)
			queue_remove(store, this)

			return
		end

		if this.render and target.unit then
			local s = this.render.sprites[1]
			local flip_sign = 1

			if target.render then
				flip_sign = target.render.sprites[1].flip_x and -1 or 1
			end

			if m.use_mod_offset and target.unit.mod_offset then
				s.offset.x, s.offset.y = target.unit.mod_offset.x * flip_sign, target.unit.mod_offset.y
			end
		end

		coroutine.yield()
	end
end

function scripts.mod_archers_skill_c_weak.remove(this, store, script)
	local target = store.entities[this.modifier.target_id]

	if target and target.health and target.unit and this.received_damage_factor then
		target.health.damage_factor = target.health.damage_factor / this.received_damage_factor
	end

	return true
end

scripts.controller_tower_knights_tutorial = {}

function scripts.controller_tower_knights_tutorial.insert(this, store)
	local holder = table.filter(store.entities, function(k, v)
		return v.tower and v.tower.holder_id == "5"
	end)[1]
	local t = E:create_entity("tower_knights_lvl1")

	t.pos.x, t.pos.y = holder.pos.x, holder.pos.y
	t.tower.holder_id = holder.tower.holder_id
	t.tower.terrain_style = holder.tower.terrain_style
	t.tower.spent = this.cost
	t.tower.default_rally_pos = holder.tower.default_rally_pos
	t.tower.level = 1
	t.barrack.rally_pos = holder.tower.default_rally_pos
	t.ui.nav_mesh_id = holder.ui.nav_mesh_id
	t.tower.can_be_mod = false
	t.render.sprites[1].name = "terrains_0047"
	this.cloned_sound_events = table.deepclone(t.sound_events)
	t.sound_events = {}
	this.k_tower = t

	LU.queue_insert(store, t)
	LU.queue_remove(store, holder)

	if holder.ui then
		holder.ui.click_rect = r(0, 0, 0, 0)
	end

	return true
end

scripts.controller_tutorial_build_tower_sequence = {}

function scripts.controller_tutorial_build_tower_sequence.update(this, store)
	local holder = table.filter(store.entities, function(_, v)
		return v.tower and v.tower.holder_id == this.holder_id
	end)[1]
	local tower_build_indicator, archers_tower

	while true do
		if this.level.tower_menu_hiding and not holder.tower.upgrade_to then
			if not tower_build_indicator then
				tower_build_indicator = E:create_entity("stage_01_tower_build_indicator")
				tower_build_indicator.pos = holder.pos
				tower_build_indicator.tween.ts = store.tick_ts

				queue_insert(store, tower_build_indicator)

				holder.ui.can_click = true
				holder.tower.can_hover = true
			end
		elseif tower_build_indicator then
			signal.emit("show-balloon_tutorial-pos", "TB_BUILD", false, V.v(779, 396))

			holder.ui.can_click = false
			holder.tower.can_hover = false
			tower_build_indicator.tween.reverse = true
			tower_build_indicator.tween.ts = store.tick_ts
			tower_build_indicator.tween.remove = true

			U.y_wait(store, 0.5)

			tower_build_indicator = nil
		end

		local towers = table.filter(store.entities, function(k, e)
			return e.tower and not e.tower_holder
		end)

		if towers and #towers > 0 then
			for i, v in ipairs(towers) do
				archers_tower = towers[i]

				if archers_tower and archers_tower.template_name == "tower_archers_lvl1" then
					archers_tower.ui.can_click = false
					archers_tower.tower.can_hover = false

					local b = E:get_template(archers_tower.attacks.list[1].bullet)

					b._damage_min = b.bullet.damage_min
					b._damage_max = b.bullet.damage_max

					local e = E:get_template(this.enemy_health_t)

					b.bullet.damage_min = math.ceil(e.health.hp_max / 4)
					b.bullet.damage_max = math.ceil(e.health.hp_max / 4)
					archers_tower.attacks.list[1].vis_bans = F_CUSTOM

					goto label_568_0
				end
			end
		end

		coroutine.yield()
	end

	::label_568_0::

	signal.emit("ftue-step", "click_archers_build")
	queue_remove(store, this)
end

scripts.tower_knights = {}

function scripts.tower_knights.get_info(this)
	local s = E:create_entity(this.barrack.soldier_type)

	if this.powers then
		for pn, p in pairs(this.powers) do
			for i = 1, p.level do
				SU.soldier_power_upgrade(s, pn)
			end
		end
	end

	local s_info = s.info.fn(s)
	local attacks

	if s.melee and s.melee.attacks then
		attacks = s.melee.attacks
	elseif s.ranged and s.ranged.attacks then
		attacks = s.ranged.attacks
	end

	local min, max

	for _, a in pairs(attacks) do
		if a.damage_min then
			local damage_factor = this.tower.damage_factor

			min, max = a.damage_min * damage_factor, a.damage_max * damage_factor

			break
		end
	end

	if min and max then
		min, max = math.ceil(min), math.ceil(max)
	end

	return {
		type = STATS_TYPE_TOWER_BARRACK,
		hp_max = s.health.hp_max,
		damage_min = min,
		damage_max = max,
		armor = s.health.armor,
		respawn = s.health.dead_lifetime
	}
end

scripts.soldier_knights = {}

function scripts.soldier_knights.insert(this, store)
	if scripts.soldier_barrack.insert(this, store) then
		if this.powers then
			for pn, p in pairs(this.powers) do
				if p.level > 0 then
					if p == this.powers.skill_b then
						this.timed_attacks.list[1].disabled = nil
						this.timed_attacks.list[1].hp_ptg = p.hp_ptg[p.level]
					elseif p == this.powers.skill_c then
						this.melee.attacks[2].cooldown = this.melee.attacks[1].cooldown * p.cd_mult[p.level]
					elseif p == this.powers.ultimate then
						this.timed_attacks.list[2].disabled = nil
					end
				end
			end
		end

		return true
	end

	return false
end

function scripts.soldier_knights.update(this, store, script)
	local brk, sta
	local sa = this.powers and this.powers.skill_a or nil
	local sb = this.powers and this.powers.skill_b or nil
	local sc = this.powers and this.powers.skill_c or nil
	local su = this.powers and this.powers.ultimate or nil
	local sba = this.timed_attacks and this.timed_attacks.list[1]
	local sca = this.melee.attacks[2]
	local sua = this.timed_attacks and this.timed_attacks.list[2]
	local ult_start_cd = sua ~= nil and store.wave_group_number == 0

	if sua then
		sua.disabled = not su.active
	end

	local damage_factor_prev = this.health.damage_factor
	local mods = {}

	if this.vis._bans then
		this.vis.bans = this.vis._bans
		this.vis._bans = nil
	end

	this.nav_rally._first_time = true

	local aura_sa, aura_sc

	if sa and sa.level >= 1 then
		aura_sa = E:create_entity(sa.aura_t)
		aura_sa.aura.target_id = this.id
		aura_sa.aura.source_id = this.id
		aura_sa.armor_inc_per_hero = sa.extra_armor[sa.level]

		queue_insert(store, aura_sa)
	end

	if sc and sc.level >= 1 then
		aura_sc = E:create_entity(sc.aura_check)
		aura_sc.aura.target_id = this.id
		aura_sc.aura.source_id = this.id

		queue_insert(store, aura_sc)
	end

	local function walk_break_fn()
		return false
	end

	local function y_soldier_new_rally_break_attack(store, this, break_fn)
		local r = this.nav_rally
		local out = false
		local vis_bans = this.vis.bans
		local prev_immune = this.health.immune_to

		this.health.immune_to = r.immune_to
		this.vis.bans = F_ALL

		if r.new then
			r.new = false

			U.unblock_target(store, this)
			U.set_destination(this, r.pos)

			if r.delay_max then
				U.animation_start(this, this.idle_flip.last_animation, nil, store.tick_ts, this.idle_flip.loop)

				local index = this.soldier.tower_soldier_idx or 0
				local tower = store.entities[this.soldier.tower_id]
				local total = tower and tower.barrack.max_soldiers or 1

				if SU.y_soldier_wait(store, this, index / total * r.delay_max) then
					goto label_575_0
				end
			end

			local an, af = U.animation_name_facing_point(this, "walk", this.motion.dest)

			U.animation_start(this, an, af, store.tick_ts, -1)

			while not this.motion.arrived do
				if this.health.dead or this.unit.is_stunned then
					out = true

					break
				end

				if r.new then
					out = false

					U.set_destination(this, r.pos)

					local an, af = U.animation_name_facing_point(this, "walk", this.motion.dest)

					U.animation_start(this, an, af, store.tick_ts, -1)

					r.new = false
				end

				if break_fn() then
					out = false

					break
				end

				if r._first_time then
					r._first_time = false

					local target = U.find_foremost_enemy(store.entities, r.center, 0, this.melee.range, false, F_BLOCK, bit.bor(F_CLIFF), function(e)
						return (not e.enemy.max_blockers or #e.enemy.blockers == 0) and band(GR:cell_type(e.pos.x, e.pos.y), TERRAIN_NOWALK) == 0 and (not this.melee.fn_can_pick or this.melee.fn_can_pick(this, e))
					end)

					if target then
						out = false

						break
					end
				end

				U.walk(this, store.tick_length)
				coroutine.yield()

				this.motion.speed.x, this.motion.speed.y = 0, 0
			end
		end

		::label_575_0::

		this.vis.bans = vis_bans
		this.health.immune_to = prev_immune

		return out
	end

	local function check_tower_damage_factor()
		if store.entities[this.soldier.tower_id] then
			for _, a in ipairs(this.melee.attacks) do
				if not a._original_damage_min then
					a._original_damage_min = a.damage_min
				end

				if not a._original_damage_max then
					a._original_damage_max = a.damage_max
				end

				a.damage_min = a._original_damage_min * store.entities[this.soldier.tower_id].tower.damage_factor
				a.damage_max = a._original_damage_max * store.entities[this.soldier.tower_id].tower.damage_factor
			end
		end
	end

	while true do
		if ult_start_cd and store.wave_group_number > 0 then
			ult_start_cd = false
			sua.ts = store.tick_ts
		end

		if this.powers then
			for pn, p in pairs(this.powers) do
				if p.changed then
					p.changed = nil

					SU.soldier_power_upgrade(this, pn)

					if p == this.powers.skill_a then
						if not aura_sa then
							aura_sa = E:create_entity(sa.aura_t)
							aura_sa.aura.target_id = this.id
							aura_sa.aura.source_id = this.id

							queue_insert(store, aura_sa)
						end

						aura_sa.armor_inc_per_hero = sa.extra_armor[p.level]
					elseif p == this.powers.skill_b then
						sba.disabled = nil
						sba.hp_ptg = p.hp_ptg[p.level]

						if p.level == 1 then
							sba.ts = store.tick_ts - sba.cooldown
						end
					elseif p == this.powers.skill_c then
						if p.level == 1 then
							aura_sc = E:create_entity(sc.aura_check)
							aura_sc.aura.target_id = this.id
							aura_sc.aura.source_id = this.id

							queue_insert(store, aura_sc)
						end

						sca.cooldown = this.melee.attacks[1].cooldown * p.cd_mult[p.level]
					elseif p == this.powers.ultimate then
						this.timed_attacks.list[2].disabled = nil
					end
				end
			end
		end

		if this.health.dead then
			this.ui.can_click = false

			SU.y_soldier_death(store, this)

			return
		end

		if this.unit.is_stunned then
			SU.soldier_idle(store, this)
		else
			while this.nav_rally.new do
				if y_soldier_new_rally_break_attack(store, this, walk_break_fn) then
					goto label_573_0
				end
			end

			check_tower_damage_factor()

			brk, sta = SU.y_soldier_melee_block_and_attacks(store, this)

			if brk or sta ~= A_NO_TARGET then
				if sta == A_IN_COOLDOWN and sba and not sba.disabled and store.tick_ts - sba.ts > sba.cooldown and this.health.hp < this.health.hp_max then
					local start_ts = store.tick_ts

					U.animation_start(this, sba.animation, nil, store.tick_ts, false)
					S:queue(sba.sound)

					if SU.y_soldier_wait(store, this, sba.cast_times[1]) then
						goto label_573_0
					end

					sba.ts = start_ts
					this.health.hp = this.health.hp + this.health.hp_max * sba.hp_ptg / 2
					this.health.hp = km.clamp(0, this.health.hp_max, this.health.hp)

					U.y_wait(store, sba.cast_times[2] - sba.cast_times[1])

					this.health.hp = this.health.hp + this.health.hp_max * sba.hp_ptg / 2
					this.health.hp = km.clamp(0, this.health.hp_max, this.health.hp)

					U.y_animation_wait(this)
				end

				if sta == A_IN_COOLDOWN and sua and not sua.disabled and store.tick_ts - sua.ts > sua.cooldown and this.health.hp < this.health.hp_max * sua.hp_trigger then
					local start_ts = store.tick_ts

					function this.health.on_damage(this, store, damage)
						S:queue(sua.sound)
						U.animation_start(this, sua.animation_hit, nil, store.tick_ts, false)

						return false
					end

					U.animation_start(this, sua.animation_in, nil, store.tick_ts, false)

					if SU.y_soldier_wait(store, this, sua.cast_time) then
						-- block empty
					else
						sua.ts = start_ts

						signal.emit("tower-ultimate-used", this)
						U.animation_start(this, sua.animation_loop, nil, store.tick_ts, true)

						while store.tick_ts - sua.ts < sua.duration do
							if this.render.sprites[1].name == sua.animation_hit and U.animation_finished(this) then
								U.animation_start(this, sua.animation_loop, nil, store.tick_ts, true)
							end

							coroutine.yield()
						end

						this.health.on_damage = nil

						U.y_animation_play(this, sua.animation_out, nil, store.tick_ts, 1)
					end
				end
			elseif SU.soldier_go_back_step(store, this) then
				-- block empty
			else
				SU.soldier_idle(store, this)
				SU.soldier_regen(store, this)
			end
		end

		::label_573_0::

		coroutine.yield()
	end
end

scripts.aura_knights_skill_a = {}

function scripts.aura_knights_skill_a.update(this, store, script)
	local soldier = store.entities[this.aura.source_id]
	local skill_ts = store.tick_ts

	if this.aura.track_source and this.aura.source_id then
		this.pos = soldier.pos
	end

	local last_heroes_count = 0
	local last_armor_inc_per_hero = this.armor_inc_per_hero

	while true do
		if soldier.health.dead then
			queue_remove(store, this)

			return
		end

		if store.tick_ts - skill_ts > this.aura.cycle_time then
			local near_heroes = table.filter(store.entities, function(k, v)
				return v.hero and not v.health.dead and V.dist2(v.pos.x, v.pos.y, this.pos.x, this.pos.y) < this.aura.radius * this.aura.radius
			end)

			if near_heroes then
				if last_armor_inc_per_hero ~= this.armor_inc_per_hero then
					SU.armor_dec(soldier, last_armor_inc_per_hero * last_heroes_count)
					SU.armor_inc(soldier, this.armor_inc_per_hero * last_heroes_count)

					last_armor_inc_per_hero = this.armor_inc_per_hero
				end

				if #near_heroes ~= last_heroes_count then
					SU.armor_dec(soldier, this.armor_inc_per_hero * last_heroes_count)
					SU.armor_inc(soldier, this.armor_inc_per_hero * #near_heroes)

					this.tween.disabled = false

					if #near_heroes == 0 then
						this.tween.reverse = true
						this.tween.ts = store.tick_ts
					elseif last_heroes_count == 0 then
						this.tween.reverse = false
						this.tween.ts = store.tick_ts
					end

					last_heroes_count = #near_heroes
				end

				skill_ts = store.tick_ts
			end
		end

		coroutine.yield()
	end
end

scripts.aura_knights_skill_c_check = {}

function scripts.aura_knights_skill_c_check.update(this, store, script)
	local last_cycle_ts = 0

	if this.aura.track_source and this.aura.source_id then
		local ts = store.entities[this.aura.source_id]

		if ts and ts.pos then
			this.pos = ts.pos
		end
	end

	while true do
		local ts = store.entities[this.aura.source_id]

		if this.aura.track_source and this.aura.source_id and (not ts or ts.health and ts.health.dead and not this.aura.track_dead) then
			break
		end

		if store.tick_ts - last_cycle_ts >= this.aura.cycle_time then
			last_cycle_ts = store.tick_ts

			local targets = table.filter(store.entities, function(k, v)
				return v.template_name == ts.template_name and v.health and (v.health.dead or v.health.hp <= 0) and not v.health.death_finished_ts and U.is_inside_ellipse(v.pos, this.pos, this.aura.radius)
			end)

			if targets and #targets > 0 then
				ts.melee.attacks[2].disabled = false
				ts.melee.attacks[1].disabled = true

				U.y_wait(store, this.attack_duration)

				ts.melee.attacks[2].disabled = true
				ts.melee.attacks[1].disabled = false
			end
		end

		coroutine.yield()
	end

	queue_remove(store, this)
end

scripts.tower_catapult = {}

function scripts.tower_catapult.insert(this, store, script)
	local ba = this.attacks.list[1]
	local target

	if store.tick > 1 then
		target = U.find_foremost_enemy(store.entities, tpos(this), 0, this.attacks.range, 0, ba.vis_flags, ba.vis_bans)
	end

	local dir = 2

	if target then
		dir = target.pos.x > tpos(this).x and (target.pos.y > tpos(this).y and 3 or 2) or target.pos.y > tpos(this).y and 7 or 5
	end

	U.animation_start(this, "idle_" .. dir, nil, store.tick_ts, true, this.tower_sid)

	return true
end

function scripts.tower_catapult.update(this, store)
	local sa = this.powers and this.powers.skill_a or nil
	local sb = this.powers and this.powers.skill_b or nil
	local sc = this.powers and this.powers.skill_c or nil
	local su = this.powers and this.powers.ultimate or nil
	local a = this.attacks
	local ba = this.attacks.list[1]
	local saa = this.attacks.list[2]
	local sba = this.attacks.list[3]
	local sca = this.timed_attacks and this.timed_attacks.list[1]

	this.active_traps = {}

	local sua = this.timed_attacks and this.timed_attacks.list[2]
	local ult_start_cd = sua ~= nil and store.wave_group_number == 0

	if sua then
		sua.ts = store.tick_ts
		sua.disabled = not su.active
	end

	local shoot_ulti = false
	local ulti_trigger_enemy, ulti_pred_pos
	local next_attack = ba
	local bft = E:get_template(ba.bullet).bullet.flight_time
	local idle_ts = store.tick_ts

	if not a._last_target_pos then
		a._last_target_pos = {}
	end

	local function check_upgrades_purchase()
		if this.powers then
			for _, pow in pairs(this.powers) do
				if pow.changed then
					pow.changed = nil

					if pow == sa then
						saa.disabled = false
						saa.cooldown = pow.cooldown[pow.level]
						saa.bullet = sa.bullets[pow.level]

						if pow.level == 1 then
							saa.ts = store.tick_ts - saa.cooldown
						end
					elseif pow == sb then
						sba.disabled = false
						sba.ts = store.tick_ts - sba.cooldown

						U.animation_start(this, "idle_2_explosive", nil, store.tick_ts, true, this.tower_sid)
						U.animation_start(this, "idle_2", nil, store.tick_ts, false, this.balls_sid)

						if next_attack == ba then
							next_attack = sba
						end
					elseif pow == sc then
						sca.disabled = false
						sca.cooldown = pow.cooldown[pow.level]

						if pow.level == 1 then
							sca.ts = store.tick_ts - sca.cooldown
						end
					end
				end
			end
		end
	end

	local function get_direction(target_pos)
		if target_pos.x > tpos(this).x then
			if target_pos.y > tpos(this).y then
				return 1
			else
				return 2
			end
		elseif target_pos.y > tpos(this).y then
			return 4
		else
			return 3
		end
	end

	local function get_anim_name(dir, attack, mode)
		local sufix = ""

		if attack == saa then
			sufix = "_tarred_zone"
		elseif attack == sba then
			sufix = "_explosive"
		end

		if dir == 1 then
			if mode == "in" then
				return "rotation_1" .. sufix
			elseif mode == "attack" then
				return "attack_2" .. sufix
			else
				return "rotation_2" .. sufix
			end
		elseif dir == 2 then
			if mode == "in" or mode == "out" then
				return nil
			else
				return "attack_1" .. sufix
			end
		elseif dir == 3 then
			if mode == "in" then
				return "rotation_3" .. sufix
			elseif mode == "attack" then
				return "attack_3" .. sufix
			else
				return "rotation_4" .. sufix
			end
		elseif mode == "in" then
			return "rotation_5" .. sufix
		elseif mode == "attack" then
			return "attack_4" .. sufix
		else
			return "rotation_6" .. sufix
		end
	end

	local function y_aim_anim(aa, dir)
		if dir == 2 then
			U.y_wait(store, this.rotation_time)
		else
			U.y_animation_play(this, get_anim_name(dir, aa, "in"), nil, store.tick_ts, 1, this.tower_sid)
		end
	end

	local function y_return_anim(aa, dir)
		if dir == 2 then
			U.y_wait(store, this.rotation_time)
		else
			U.y_animation_play(this, get_anim_name(dir, aa, "out"), nil, store.tick_ts, 1, this.tower_sid)
		end
	end

	local function y_reload_anim()
		if this.tower.level == 4 then
			if sb and not sba.disabled then
				U.animation_start(this, "ball_reload_2", nil, store.tick_ts, false, this.balls_sid)
			else
				U.animation_start(this, "ball_reload", nil, store.tick_ts, false, this.balls_sid)
			end

			if sa and not saa.disabled and store.tick_ts - saa.ts > saa.cooldown then
				U.animation_start(this, "reload_tarred_zone", nil, store.tick_ts, false, this.loader_sid)
				U.y_animation_play(this, "reload_tarred_zone", nil, store.tick_ts, 1, this.tower_sid)
				U.animation_start(this, "idle_2_tarred_zone", nil, store.tick_ts, true, this.tower_sid)
				U.animation_start(this, "idle", nil, store.tick_ts, true, this.loader_sid)

				if sb and not sba.disabled then
					U.animation_start(this, "idle_2", nil, store.tick_ts, false, this.balls_sid)
				else
					U.animation_start(this, "idle", nil, store.tick_ts, false, this.balls_sid)
				end

				next_attack = saa
			elseif sb and not sba.disabled then
				U.animation_start(this, "reload_explosive", nil, store.tick_ts, false, this.loader_sid)
				U.y_animation_play(this, "reload_explosive", nil, store.tick_ts, 1, this.tower_sid)
				U.animation_start(this, "idle_2_explosive", nil, store.tick_ts, true, this.tower_sid)
				U.animation_start(this, "idle_2", nil, store.tick_ts, false, this.balls_sid)
				U.animation_start(this, "idle", nil, store.tick_ts, true, this.loader_sid)

				next_attack = sba
			else
				U.animation_start(this, "reload", nil, store.tick_ts, false, this.loader_sid)
				U.y_animation_play(this, "reload", nil, store.tick_ts, 1, this.tower_sid)
				U.animation_start(this, "idle_2", nil, store.tick_ts, true, this.tower_sid)
				U.animation_start(this, "idle", nil, store.tick_ts, false, this.balls_sid)
				U.animation_start(this, "idle", nil, store.tick_ts, true, this.loader_sid)

				next_attack = ba
			end
		else
			U.animation_start(this, "reload", nil, store.tick_ts, false, this.loader_sid)
			U.y_animation_play(this, "reload", nil, store.tick_ts, 1, this.tower_sid)
			U.animation_start(this, "idle_2", nil, store.tick_ts, true, this.tower_sid)
			U.animation_start(this, "idle", nil, store.tick_ts, true, this.loader_sid)

			next_attack = ba
		end
	end

	local function shoot_bullet(target_pos, aa)
		local b = E:create_entity(aa.bullet)

		b.bullet.damage_factor = this.tower.damage_factor
		b.pos.x, b.pos.y = this.pos.x + aa.bullet_start_offset.x, this.pos.y + aa.bullet_start_offset.y
		b.bullet.from = V.vclone(b.pos)
		b.bullet.to = target_pos
		b.bullet.source_id = this.id

		if aa == saa then
			b.bullet.level = sa.level
		elseif aa == sba then
			b.bullet.level = sb.level
		end

		queue_insert(store, b)
	end

	local function calculate_trap_pos(near_mines)
		local dist_sq = sca.min_dist_between_traps * sca.min_dist_between_traps
		local valid_positions = P:get_all_valid_pos(this.pos.x, this.pos.y, 0, sca.max_range, TERRAIN_LAND, function(x, y)
			for _, mine in ipairs(near_mines) do
				if V.dist2(mine.pos.x, mine.pos.y, x, y) <= dist_sq then
					return false
				end
			end

			return true
		end, nil, {
			1,
			2,
			3
		})

		return valid_positions[math.random(1, #valid_positions)]
	end

	local function find_target(aa, dir, predict)
		local pred = predict and bft or 0
		local dir_filter = dir and function(e, o)
			local future_pos = P:predict_enemy_pos(e, bft)

			return get_direction(future_pos) == dir
		end

		return U.find_foremost_enemy(store.entities, tpos(this), 0, a.range, pred, aa.vis_flags, aa.vis_bans, dir_filter)
	end

	local function can_shoot_ulti()
		if not sua or sua.disabled or store.tick_ts - sua.ts < sua.cooldown then
			return false
		end

		local enemies

		ulti_trigger_enemy, enemies, ulti_pred_pos = U.find_foremost_enemy(store.entities, tpos(this), sua.min_range, sua.max_range, sua.cast_time + fts(40), sua.vis_flags, sua.vis_bans)

		return ulti_trigger_enemy and ulti_pred_pos and #enemies >= sua.min_targets and (not store.level.ignore_walk_backwards_paths or not table.contains(store.level.ignore_walk_backwards_paths, ulti_trigger_enemy.nav_path.pi)) and P:is_path_active(ulti_trigger_enemy.nav_path.pi)
	end

	ba.ts = store.tick_ts - ba.cooldown

	::label_584_0::

	while true do
		if ult_start_cd and store.wave_group_number > 0 then
			ult_start_cd = false
			sua.ts = store.tick_ts
		end

		if this.tower.blocked then
			coroutine.yield()
		else
			check_upgrades_purchase()
			SU.towers_swaped(store, this, this.attacks.list)

			if shoot_ulti then
				shoot_ulti = false
				sua.ts = store.tick_ts
				ba.ts = store.tick_ts

				signal.emit("tower-ultimate-used", this)
				U.animation_start(this, sua.animation, nil, store.tick_ts, false, 2)
				U.y_wait(store, sua.cast_time)

				local enemy, _, new_pred_pos = U.find_foremost_enemy(store.entities, tpos(this), sua.min_range, sua.max_range, fts(40), sua.vis_flags, sua.vis_bans)

				if not enemy or not new_pred_pos then
					enemy = ulti_trigger_enemy
					new_pred_pos = ulti_pred_pos
				end

				local nearest = P:nearest_nodes(new_pred_pos.x, new_pred_pos.y)
				local pi, spi, ni = unpack(nearest[1])
				local pos = P:node_pos(pi, 1, ni)

				shoot_bullet(pos, sua)
				U.y_animation_wait(this, 2)
				check_upgrades_purchase()
				y_reload_anim()
			end

			if store.tick_ts - ba.ts > a.cooldown then
				local aa = next_attack
				local trigger_enemy, _, pred_pos = find_target(aa, nil, false)

				if not trigger_enemy or not pred_pos then
					SU.delay_attack(store, aa, fts(10))
				else
					aa.ts = store.tick_ts
					ba.ts = store.tick_ts

					local aim_pos = trigger_enemy.motion and P:predict_enemy_pos(trigger_enemy, this.rotation_time + aa.shoot_time + bft) or pred_pos
					local dir = get_direction(aim_pos)

					y_aim_anim(aa, dir)
					U.animation_start(this, get_anim_name(dir, aa, "attack"), nil, store.tick_ts, false, 2)
					U.y_wait(store, aa.shoot_time)

					local enemy, _, new_pred_pos = find_target(aa, dir, true)

					new_pred_pos = enemy and new_pred_pos or pred_pos

					shoot_bullet(new_pred_pos, aa)
					U.y_animation_wait(this, 2)
					y_return_anim(aa, dir)
					check_upgrades_purchase()

					if can_shoot_ulti() then
						shoot_ulti = true

						goto label_584_0
					end

					y_reload_anim()
				end
			end

			if sc and not sca.disabled and store.tick_ts - sca.ts > sca.cooldown and store.wave_group_number > 0 then
				if #this.active_traps >= sc.max_traps[sc.level] then
					SU.delay_attack(store, a, fts(10))
				else
					local near_traps = table.filter(store.entities, function(k, v)
						return v.template_name == "aura_catapult_skill_c_trap" and V.dist2(v.pos.x, v.pos.y, this.pos.x, this.pos.y) <= a.range * a.range
					end)
					local trap_pos = calculate_trap_pos(near_traps)

					if not trap_pos then
						SU.delay_attack(store, a, fts(10))
					else
						sca.ts = store.tick_ts

						U.animation_start(this, "traps", nil, store.tick_ts, false, 3)
						U.y_wait(store, sca.cast_time)

						local b = E:create_entity(sca.bullet)

						b.bullet.from = V.v(this.pos.x + sca.bullet_start_offset.x, this.pos.y + sca.bullet_start_offset.y)
						b.bullet.to = V.v(trap_pos.x, trap_pos.y)
						b.bullet.source_id = this.id
						b.bullet.level = sc.level
						b.pos = V.vclone(b.bullet.from)

						queue_insert(store, b)
						U.y_animation_wait(this, 2)
					end
				end
			end

			coroutine.yield()
		end
	end
end

scripts.aura_catapult_skill_a = {}

function scripts.aura_catapult_skill_a.insert(this, store, script)
	this.aura.duration = this.aura.duration_conf[this.aura.level]

	return scripts.aura_apply_mod.insert(this, store, script)
end

scripts.mod_catapult_skill_a_slow = {}

function scripts.mod_catapult_skill_a_slow.insert(this, store, script)
	this.slow.factor = this.slow_factor_config[this.modifier.level]

	return scripts.mod_slow.insert(this, store, script)
end

scripts.aura_catapult_skill_b_bomb = {}

function scripts.aura_catapult_skill_b_bomb.update(this, store, script)
	this.damage_min = this.damage_min_conf[this.aura.level]
	this.damage_max = this.damage_max_conf[this.aura.level]

	U.y_wait(store, this.explosion_delay)
	U.animation_start(this, "activate", nil, store.tick_ts, false)
	U.y_wait(store, this.cast_time)
	S:queue(this.sound_explosion)

	local enemies = U.find_enemies_in_range(store.entities, this.pos, 0, this.damage_radius, 0, 0)

	if enemies then
		for _, enemy in pairs(enemies) do
			local d = E:create_entity("damage")

			d.damage_type = this.damage_type

			local dist_factor = U.dist_factor_inside_ellipse(enemy.pos, this.pos, this.damage_radius)

			d.value = math.floor(this.damage_max - (this.damage_max - this.damage_min) * dist_factor)
			d.source_id = this.id
			d.target_id = enemy.id

			queue_damage(store, d)
		end
	end

	U.y_animation_wait(this)
	queue_remove(store, this)
end

scripts.aura_catapult_skill_c_trap = {}

function scripts.aura_catapult_skill_c_trap.insert(this, store)
	this.aura.ts = store.tick_ts

	if this.render then
		for _, s in pairs(this.render.sprites) do
			s.ts = store.tick_ts
		end
	end

	U.animation_start(this, "set", nil, store.tick_ts, false)

	this.actual_duration = this.aura.duration
	this.damage_min = this.damage_min_conf[this.aura.level]
	this.damage_max = this.damage_max_conf[this.aura.level]

	return true
end

function scripts.aura_catapult_skill_c_trap.update(this, store)
	local catapult = store.entities[this.source_id]

	if catapult then
		table.insert(catapult.active_traps, this)
	end

	S:queue(this.sound_open)
	U.y_animation_wait(this)
	U.animation_start(this, "ready", nil, store.tick_ts, true)

	while true do
		local targets = U.find_enemies_in_range(store.entities, this.pos, 0, this.aura.radius, this.aura.vis_flags, this.aura.vis_bans)

		if not targets or #targets == 0 then
			-- block empty
		else
			U.animation_start(this, "activate", nil, store.tick_ts, false)
			U.y_wait(store, fts(12))
			S:queue(this.sound_trigger)

			targets = U.find_enemies_in_range(store.entities, this.pos, 0, this.aura.radius, this.aura.vis_flags, this.aura.vis_bans)

			if targets and #targets > 0 then
				for _, enemy in ipairs(targets) do
					if enemy and not enemy.dead then
						local d = E:create_entity("damage")

						d.damage_type = this.damage_type
						d.value = math.random(this.damage_min, this.damage_max)
						d.source_id = this.id
						d.target_id = enemy.id

						queue_damage(store, d)

						local mod = E:create_entity(this.aura.mod)

						mod.modifier.target_id = enemy.id
						mod.modifier.source_id = this.id
						mod.modifier.level = this.aura.level

						queue_insert(store, mod)
					end
				end
			end

			U.y_animation_wait(this)

			this.render.sprites[1].hidden = true

			if catapult then
				for k, v in pairs(catapult.active_traps) do
					if v == this then
						table.remove(catapult.active_traps, k)

						break
					end
				end
			end

			break
		end

		coroutine.yield()
	end

	queue_remove(store, this)
end

scripts.mod_catapult_skill_c_stun = {}

function scripts.mod_catapult_skill_c_stun.insert(this, store, script)
	this.modifier.duration = this.stun_duration_config[this.modifier.level]

	return scripts.mod_stun.insert(this, store, script)
end

scripts.aura_catapult_ultimate = {}

function scripts.aura_catapult_ultimate.update(this, store, script)
	local first_hit_ts
	local last_hit_ts = 0
	local available_paths = {}

	for k, v in pairs(P.paths) do
		table.insert(available_paths, k)
	end

	if store.level.ignore_walk_backwards_paths then
		available_paths = table.filter(available_paths, function(k, v)
			return not table.contains(store.level.ignore_walk_backwards_paths, v)
		end)
	end

	local nearest_nodes = P:nearest_nodes(this.pos.x, this.pos.y, available_paths, {
		1
	}, true)
	local pi, spi, ni = unpack(nearest_nodes[1])
	local starting_ni = ni
	local distSq = 0

	last_hit_ts = store.tick_ts - this.aura.cycle_time

	if this.aura.apply_delay then
		last_hit_ts = last_hit_ts + this.aura.apply_delay
	end

	local last_fire_ni = ni + 2

	local function hit_enemies()
		local targets = U.find_enemies_in_range(store.entities, this.pos, 0, this.aura.radius, this.aura.vis_flags, this.aura.vis_bans, function(v, o)
			return (not this.aura.allowed_templates or table.contains(this.aura.allowed_templates, v.template_name)) and (not this.aura.excluded_templates or not table.contains(this.aura.excluded_templates, v.template_name)) and (not this.aura.filter_source or this.aura.source_id ~= v.id) and not U.has_modifiers(store, v, this.aura.mod)
		end)

		if targets then
			for i, target in pairs(targets) do
				if target and not target.health.dead and target.enemy then
					queue_damage(store, SU.create_attack_damage(this, target.id, this.id))

					local hit_fx = E:create_entity(this.hit_fx)

					hit_fx.pos = V.vclone(target.pos)
					hit_fx.pos.x, hit_fx.pos.y = hit_fx.pos.x + target.unit.hit_offset.x, hit_fx.pos.y + target.unit.hit_offset.y
					hit_fx.render.sprites[1].ts = store.tick_ts

					queue_insert(store, hit_fx)

					local new_mod = E:create_entity(this.aura.mod)

					new_mod.modifier.target_id = target.id
					new_mod.modifier.source_id = this.id

					queue_insert(store, new_mod)
				end
			end
		end
	end

	local target_pos = P:node_pos(pi, spi, ni)

	local function go_back_step()
		if V.veq(this.pos, target_pos) then
			this.motion.arrived = true

			return false
		else
			U.set_destination(this, target_pos)

			if U.walk(this, store.tick_length) then
				return false
			else
				local an, af = U.animation_name_facing_point(this, "run", this.motion.dest, 1, nil, true)

				U.animation_start(this, an, af, store.tick_ts, true)

				return true
			end
		end
	end

	local function run_backwards()
		local last_pos = this.pos

		distSq = V.dist2(target_pos.x, target_pos.y, this.pos.x, this.pos.y)

		if distSq < 25 then
			ni = ni - 3
			target_pos = P:node_pos(pi, spi, ni)
		end

		go_back_step()
	end

	while true do
		if this.interrupt then
			last_hit_ts = 1e+99
		end

		if ni <= 3 then
			break
		end

		if last_fire_ni - ni >= 2 then
			last_fire_ni = ni

			local pos = P:node_pos(pi, math.random(1, 3), ni + 6)
			local fire_decal = E:create_entity(this.fire_decal)

			fire_decal.pos = pos
			fire_decal.render.sprites[1].ts = store.tick_ts

			queue_insert(store, fire_decal)
		end

		if starting_ni - ni > this.max_nodes then
			local explosion_fx = E:create_entity(this.explosion_fx)

			explosion_fx.pos = V.vclone(this.pos)
			explosion_fx.render.sprites[1].ts = store.tick_ts

			queue_insert(store, explosion_fx)

			local dradius = this.explosion_damage_radius
			local dmax, dmin = this.explosion_damage_max, this.explosion_damage_min
			local enemies = U.find_enemies_in_range(store.entities, this.pos, 0, dradius, 0, 0)

			if enemies then
				for _, enemy in pairs(enemies) do
					local d = E:create_entity("damage")

					d.damage_type = this.explosion_damage_type

					local dist_factor = U.dist_factor_inside_ellipse(enemy.pos, this.pos, dradius)

					d.value = math.floor(dmax - (dmax - dmin) * dist_factor)
					d.source_id = this.id
					d.target_id = enemy.id

					queue_damage(store, d)
				end
			end

			U.y_wait(store, fts(2))

			break
		end

		if store.tick_ts - last_hit_ts >= this.aura.cycle_time then
			if this.aura.apply_duration and first_hit_ts and store.tick_ts - first_hit_ts > this.aura.apply_duration then
				goto label_604_0
			end

			first_hit_ts = first_hit_ts or store.tick_ts
			last_hit_ts = store.tick_ts

			hit_enemies()
		end

		run_backwards()

		::label_604_0::

		coroutine.yield()
	end

	queue_remove(store, this)
end

scripts.tower_ranger = {}

function scripts.tower_ranger.update(this, store)
	local shooter_sid = 3
	local shooter_idx = 1
	local a = this.attacks
	local aa = this.attacks.list[1]
	local apta = this.attacks.list[2]
	local abs = this.attacks.list[3]
	local awt = this.attacks.list[4]
	local ama = this.attacks.list[5]
	local ult_start_cd = ama ~= nil and store.wave_group_number == 0
	local pow_a = this.powers and this.powers.skill_a or nil
	local pow_b = this.powers and this.powers.skill_b or nil
	local pow_c = this.powers and this.powers.skill_c or nil
	local ult = this.powers and this.powers.ultimate or nil

	if ama then
		ama.ts = store.tick_ts
		ama.disabled = not ult.active
	end

	local idle_flip_cooldown = math.random(4, 8)
	local idle_reset_ts = store.tick_ts

	local function shoot_animation(attack, pos, name)
		local soffset = this.render.sprites[shooter_sid].offset
		local s = this.render.sprites[shooter_sid]
		local an, af = U.animation_name_facing_point(this, attack.animation, pos, shooter_sid, soffset)

		an = name == nil and an or name .. "_" .. an

		U.animation_start(this, an, af, store.tick_ts, 1, shooter_sid)

		return an
	end

	local function shoot_skill_a_arrow_in_out(animation, attack, pos)
		local soffset = this.render.sprites[shooter_sid].offset
		local s = this.render.sprites[shooter_sid]
		local an, af = U.animation_name_facing_point(this, attack.animation, pos, shooter_sid, soffset)

		an = animation .. "_" .. an

		U.animation_start(this, an, af, store.tick_ts, 1, shooter_sid)
	end

	local function shoot_skill_b_animation(animation, e_pos)
		local soffset = this.render.sprites[shooter_sid].offset
		local s = this.render.sprites[shooter_sid]
		local af = this.pos.x - e_pos.x > 0 and true or false

		U.animation_start(this, animation, af, store.tick_ts, 1, shooter_sid)
	end

	local function shoot_bullet(attack, enemy, animation_direction, spawn_fx)
		local ssid = shooter_sid
		local shooting_right = not this.render.sprites[ssid].flip_x
		local soffset = this.render.sprites[ssid].offset
		local boffset = attack.bullet_start_offset[animation_direction]
		local hoffset = V.vclone(enemy.unit.hit_offset)

		if enemy.render.sprites[1].flip_x then
			hoffset.x = -hoffset.x
		end

		local b = E:create_entity(attack.bullet)

		b.pos.x = this.pos.x + soffset.x + boffset.x * (shooting_right and 1 or -1)
		b.pos.y = this.pos.y + soffset.y + boffset.y
		b.bullet.from = V.vclone(b.pos)
		b.bullet.to = V.v(enemy.pos.x + hoffset.x, enemy.pos.y + hoffset.y)
		b.bullet.target_id = enemy.id
		b.bullet.source_id = this.id
		b.bullet.damage_factor = this.tower.damage_factor

		if b.bullet.critical_chance and math.random() < b.bullet.critical_chance then
			b.bullet.damage_factor = b.bullet.damage_factor * 2
			b.bullet.pop = {
				"pop_crit"
			}
			b.bullet.pop_conds = DR_DAMAGE

			if b.bullet.crit_ignores_armor then
				b.bullet.reduce_armor = 1
			end
		end

		if b.bullet.fixed_height then
			b.bullet.flight_time = 2 * (math.sqrt(2 * b.bullet.fixed_height * b.bullet.g * -1) / b.bullet.g * -1)
		end

		queue_insert(store, b)

		if spawn_fx then
			local fx = E:create_entity(spawn_fx)

			fx.pos = V.vclone(b.pos)
			fx.render.sprites[1].ts = store.tick_ts

			queue_insert(store, fx)
		end
	end

	local function shoot_bullet_pos(attack, target_pos, animation_direction, spawn_fx)
		local ssid = shooter_sid
		local shooting_right = not this.render.sprites[ssid].flip_x
		local soffset = this.render.sprites[ssid].offset
		local boffset = attack.bullet_start_offset[animation_direction]
		local b = E:create_entity(attack.bullet)

		b.pos.x = this.pos.x + soffset.x + boffset.x * (shooting_right and 1 or -1)
		b.pos.y = this.pos.y + soffset.y + boffset.y
		b.bullet.from = V.vclone(b.pos)
		b.bullet.to = V.v(target_pos.x, target_pos.y)
		b.bullet.source_id = this.id
		b.bullet.damage_factor = this.tower.damage_factor

		if b.bullet.fixed_height then
			b.bullet.flight_time = 2 * (math.sqrt(2 * b.bullet.fixed_height * b.bullet.g * -1) / b.bullet.g * -1)
		end

		queue_insert(store, b)

		if spawn_fx then
			local fx = E:create_entity(spawn_fx)

			fx.pos = V.vclone(b.pos)
			fx.render.sprites[1].ts = store.tick_ts

			queue_insert(store, fx)
		end
	end

	local function get_frontmost_non_poisoned_enemy(trigger_enemy, last_enemies_shot, pred_time, modifier)
		local enemy = U.find_foremost_enemy(store.entities, tpos(this), 0, a.range, pred_time, apta.vis_flags, apta.vis_bans, function(e, o)
			if last_enemies_shot then
				return not table.contains(last_enemies_shot, e.id) and not U.has_modifiers(store, e, modifier)
			end

			return not U.has_modifiers(store, e, modifier)
		end)

		enemy = enemy or trigger_enemy

		return enemy
	end

	local function get_frontmost_enemy_in_health_threshold(threshold)
		local targets = U.find_enemies_in_range(store.entities, tpos(this), 0, a.range, ama.vis_flags, ama.vis_bans, function(v)
			return v.health.hp <= v.health.hp_max * threshold
		end)

		if not targets then
			return nil
		end

		table.sort(targets, function(e1, e2)
			local p1 = e1.nav_path
			local p2 = e2.nav_path

			return P:nodes_to_goal(p1.pi, p1.spi, p1.ni) < P:nodes_to_goal(p2.pi, p2.spi, p2.ni)
		end)

		return targets and targets[1] or nil
	end

	local function check_upgrades_purchase()
		if this.powers then
			for _, pow in pairs(this.powers) do
				if pow.changed then
					pow.changed = nil

					if pow == pow_a then
						apta.cooldown = pow.cooldown[pow.level]
						apta.bullet = "bullet_ranger_skill_a_lvl" .. pow.level

						if pow.level == 1 then
							apta.ts = store.tick_ts - apta.cooldown
						end
					end

					if pow == pow_b then
						abs.cooldown = pow.cooldown[pow.level]
						abs.bullet = "bullet_ranger_skill_b_lvl" .. pow.level
						abs.ignore_mod = "mod_ranger_skill_b_ignore_lvl" .. pow.level

						if pow.level == 1 then
							abs.ts = store.tick_ts - abs.cooldown
						end
					end

					if pow == pow_c then
						awt.cooldown = aa.cooldown
						awt.bullet = "bullet_ranger_skill_c_lvl" .. pow.level
						aa = awt
					end
				end
			end
		end
	end

	local function has_ignore_mod(target, template)
		local entities = table.filter(store.entities, function(k, v)
			if v.modifier then
				-- block empty
			end

			return v.modifier and string.find(v.template_name, template) and v.modifier.target_id == target.id
		end)

		if not entities or #entities == 0 then
			return false
		end

		return true
	end

	aa.ts = store.tick_ts - aa.cooldown + a.attack_delay_on_spawn

	while true do
		if ult_start_cd and store.wave_group_number > 0 then
			ult_start_cd = false
			ama.ts = store.tick_ts
		end

		if this.tower.blocked then
			coroutine.yield()
		else
			check_upgrades_purchase()
			SU.towers_swaped(store, this, this.attacks.list)

			if this.powers and this.powers.ultimate and store.tick_ts - ama.ts > ama.cooldown and not ama.disabled then
				local trigger_enemy = get_frontmost_enemy_in_health_threshold(ult.instakill_hp_threshold)

				if not trigger_enemy then
					SU.delay_attack(store, ama, fts(10))
				else
					local aux_pos = trigger_enemy.pos

					ama.ts = store.tick_ts

					signal.emit("tower-ultimate-used", this)

					local an = shoot_animation(ama, aux_pos)

					if ama.sound_cast then
						S:queue(ama.sound_cast)
					end

					while store.tick_ts - ama.ts < ama.shoot_time do
						check_upgrades_purchase()
						coroutine.yield()
					end

					local enemy = get_frontmost_enemy_in_health_threshold(ult.instakill_hp_threshold)

					enemy = enemy or trigger_enemy

					if enemy then
						this.render.sprites[shooter_sid].flip_x = enemy.pos.x < this.pos.x

						shoot_bullet(ama, enemy, an)
					else
						this.render.sprites[shooter_sid].flip_x = aux_pos.x < this.pos.x

						shoot_bullet_pos(ama, aux_pos, an)
					end

					U.y_animation_wait(this, shooter_sid)
				end
			end

			if this.powers and this.powers.skill_a and pow_a.level > 0 and store.tick_ts - apta.ts > apta.cooldown then
				local trigger_enemy, _ = U.find_foremost_enemy(store.entities, tpos(this), 0, a.range, apta.shoot_time, apta.vis_flags, apta.vis_bans)

				if not trigger_enemy or trigger_enemy.health.dead then
					SU.delay_attack(store, apta, fts(10))
				else
					if this.powers.skill_a.start_fx then
						local fx = E:create_entity(this.powers.skill_a.start_fx)

						fx.pos.x, fx.pos.y = this.pos.x + this.render.sprites[shooter_sid].offset.x, this.pos.y + this.render.sprites[shooter_sid].offset.y
						fx.render.sprites[1].ts = store.tick_ts

						queue_insert(store, fx)
					end

					apta.ts = store.tick_ts

					shoot_skill_a_arrow_in_out("start", apta, trigger_enemy.pos)

					while U.y_animation_wait(this, shooter_sid) do
						check_upgrades_purchase()
						coroutine.yield()
					end

					local b = E:get_template(apta.bullet)
					local pred_time = 2 * (math.sqrt(2 * b.bullet.fixed_height * b.bullet.g * -1) / b.bullet.g * -1) + fts(2)
					local last_enemies_shot = {}
					local inner_ts

					for i = 1, this.powers.skill_a.arrow_count do
						local enemy = get_frontmost_non_poisoned_enemy(trigger_enemy, last_enemies_shot, pred_time, b.bullet.mod)

						inner_ts = store.tick_ts

						local an = shoot_animation(apta, trigger_enemy.pos, "loop")

						while store.tick_ts - inner_ts < apta.shoot_time do
							check_upgrades_purchase()
							coroutine.yield()
						end

						local enemy = get_frontmost_non_poisoned_enemy(trigger_enemy, last_enemies_shot, pred_time, b.bullet.mod)

						enemy = enemy or trigger_enemy
						this.render.sprites[shooter_sid].flip_x = enemy.pos.x < this.pos.x

						table.insert(last_enemies_shot, enemy.id)
						shoot_bullet(apta, enemy, an, this.powers.skill_a.poison_shot_fx)
						U.y_animation_wait(this, shooter_sid)
					end

					shoot_skill_a_arrow_in_out("end", apta, trigger_enemy.pos)
					U.y_animation_wait(this, shooter_sid)
				end
			end

			if this.powers and this.powers.skill_b and pow_b.level > 0 and store.tick_ts - abs.ts > abs.cooldown then
				local trigger_enemy, _, pred_pos = U.find_foremost_enemy(store.entities, tpos(this), 0, a.range, abs.shoot_time, abs.vis_flags, abs.vis_bans, function(e, o)
					return e.nav_path and P:is_node_valid(e.nav_path.pi, e.nav_path.ni) and not has_ignore_mod(e, "mod_ranger_skill_b_ignore_lvl")
				end)

				if not trigger_enemy then
					SU.delay_attack(store, abs, fts(10))
				else
					abs.ts = store.tick_ts

					shoot_skill_b_animation(pow_b.animation_name, pred_pos)

					while store.tick_ts - abs.ts < abs.shoot_time do
						check_upgrades_purchase()
						coroutine.yield()
					end

					local b = E:get_template(abs.bullet)
					local pred_time = 2 * (math.sqrt(2 * b.bullet.fixed_height * b.bullet.g * -1) / b.bullet.g * -1)
					local enemy, _, pred_pos = U.find_foremost_enemy(store.entities, tpos(this), 0, a.range, pred_time, abs.vis_flags, abs.vis_bans, function(e, o)
						return not has_ignore_mod(e, "mod_ranger_skill_b_ignore_lvl")
					end)

					enemy = enemy or trigger_enemy

					local ign_m = E:create_entity(abs.ignore_mod)

					ign_m.modifier.target_id = enemy.id
					ign_m.modifier.source_id = this.id

					queue_insert(store, ign_m)

					this.render.sprites[shooter_sid].flip_x = enemy.pos.x < this.pos.x

					shoot_bullet(abs, enemy, pow_b.animation_name)
					U.y_animation_wait(this, shooter_sid)
				end
			end

			if store.tick_ts - aa.ts > aa.cooldown then
				local b = E:get_template(aa.bullet)
				local pred_time = 2 * (math.sqrt(2 * b.bullet.fixed_height * b.bullet.g * -1) / b.bullet.g * -1)
				local trigger_enemy, _ = U.find_foremost_enemy(store.entities, tpos(this), 0, a.range, pred_time, aa.vis_flags, aa.vis_bans)

				if not trigger_enemy then
					SU.delay_attack(store, aa, fts(10))

					if store.tick_ts - idle_reset_ts > this.tower.long_idle_cooldown and not trigger_enemy then
						idle_reset_ts = store.tick_ts

						U.animation_start(this, "idle", false, store.tick_ts, -1, shooter_sid)
					end
				else
					aa.ts = store.tick_ts

					local an = shoot_animation(aa, trigger_enemy.pos)

					while store.tick_ts - aa.ts < aa.shoot_time do
						coroutine.yield()
					end

					local enemy, _ = U.find_foremost_enemy(store.entities, tpos(this), 0, a.range, pred_time, aa.vis_flags, aa.vis_bans)

					enemy = enemy or trigger_enemy
					this.render.sprites[shooter_sid].flip_x = enemy.pos.x < this.pos.x

					shoot_bullet(aa, enemy, an)
					U.y_animation_wait(this, shooter_sid)

					if not string.find(an, "_3") then
						U.animation_start(this, "idle", nil, store.tick_ts, -1, shooter_sid)
					end
				end
			end

			coroutine.yield()
		end
	end
end

scripts.controller_bramble_spawner = {}

function scripts.controller_bramble_spawner.insert(this, store)
	local target_pos
	local target = store.entities[this.target_id]

	if target and not target.health.dead then
		target_pos = V.v(target.pos.x, target.pos.y)
	else
		target_pos = V.v(this.pos.x, this.pos.y)
	end

	local nearest_nodes = P:nearest_nodes(target_pos.x, target_pos.y)
	local selected_node

	for i, v in ipairs(nearest_nodes) do
		if P:is_node_valid(nearest_nodes[i][1], nearest_nodes[i][3]) then
			selected_node = nearest_nodes[i]

			break
		end
	end

	if not selected_node then
		return false
	end

	local opi, ospi, oni, odist = unpack(selected_node, 1, 4)
	local pos_middle_path = P:node_pos(opi, ospi, oni)
	local sa = E:create_entity(this.slow_aura)

	sa.pos.x, sa.pos.y = pos_middle_path.x, pos_middle_path.y

	queue_insert(store, sa)

	local angle_aux = 0
	local rad_aux, bramble_round
	local bramble_spread = {
		0.5,
		0.3,
		0.2
	}
	local rad_start = sa.aura.radius * 0.85
	local pos_offset_r = {
		-6,
		6
	}
	local aux = {}

	for i = 1, 3 do
		bramble_round = math.ceil(this.bramble_count * bramble_spread[i])
		rad_aux = rad_start * (0.2 + 0.3 * i)

		local angle_inc = 2 * math.pi / bramble_round
		local delay = 0.1 * (i - 1)

		for j = 1, bramble_round do
			angle_aux = angle_aux + angle_inc

			local pos = U.point_on_ellipse(pos_middle_path, rad_aux, angle_aux)

			if not P:valid_node_nearby(pos.x, pos.y) then
				-- block empty
			else
				local brambles = E:create_entity(this.brambles .. "_" .. get_random_round_robin(aux, 5))

				brambles.pos = V.v(pos.x + U.frandom(pos_offset_r[1], pos_offset_r[2]), pos.y + U.frandom(pos_offset_r[1], pos_offset_r[2]))
				brambles.duration = sa.aura.duration
				brambles.delay_animation_start = delay

				queue_insert(store, brambles)
			end
		end
	end

	return false
end

scripts.decal_ranger_skill_b = {}

function scripts.decal_ranger_skill_b.update(this, store, script)
	local function check_validity()
		if not P:valid_node_nearby(this.pos.x, this.pos.y) then
			if this.animation_end then
				U.y_animation_play(this, this.animation_end, nil, store.tick_ts, 1, this.end_sprite_idx)
			end

			queue_remove(store, this)
		end
	end

	if not this.start_sprite_idx then
		this.start_sprite_idx = 1
	end

	if not this.idle_sprite_idx then
		this.idle_sprite_idx = 1
	end

	if not this.end_sprite_idx then
		this.end_sprite_idx = 1
	end

	if this.delay_animation_start then
		U.y_wait(store, this.delay_animation_start)
	end

	this.render.sprites[1].animated = true

	if this.animation_start then
		U.animation_start(this, this.animation_start, nil, store.tick_ts, false, 1)

		while not U.animation_finished(this) do
			check_validity()
			coroutine.yield()
		end
	end

	if this.animation_idle then
		U.animation_start(this, this.animation_idle, nil, store.tick_ts, true, this.idle_sprite_idx, this.idle_force_ts)

		this.ts = store.tick_ts

		while store.tick_ts - this.ts < this.duration do
			check_validity()
			coroutine.yield()
		end
	end

	if this.animation_end then
		U.y_animation_play(this, this.animation_end, nil, store.tick_ts, 1, this.end_sprite_idx)
	end

	queue_remove(store, this)
end

scripts.mod_ranger_skill_b_stun = {}

function scripts.mod_ranger_skill_b_stun.update(this, store, script)
	local m = this.modifier
	local target = store.entities[this.modifier.target_id]

	if not target then
		queue_remove(store, this)

		return
	end

	this.pos = target.pos

	U.y_animation_play(this, this.animation_start, nil, store.tick_ts, 1)
	U.animation_start(this, this.animation_idle, nil, store.tick_ts, false)

	while store.tick_ts - m.ts < m.duration - this.out_before and target and not target.health.dead do
		if this.render and m.use_mod_offset and target.unit.mod_offset and not m.custom_offsets then
			for i = 1, #this.render.sprites do
				local s = this.render.sprites[i]

				s.offset.x, s.offset.y = target.unit.mod_offset.x, target.unit.mod_offset.y
			end
		end

		coroutine.yield()
	end

	U.y_animation_play(this, this.animation_end, nil, store.tick_ts, 1)
	queue_remove(store, this)
end

scripts.bullet_tower_ranger_skill_c_bounce_clone = {}

function scripts.bullet_tower_ranger_skill_c_bounce_clone.insert(this, store)
	local b = this.bullet
	local already_hit = {
		this.target_id
	}
	local targets = U.find_enemies_in_range(store.entities, this.pos, 0, this.bounce_range, b.vis_flags, b.vis_bans, function(v)
		return v.id ~= this.target_id
	end)

	if not targets or #targets == 0 or this.missed then
		return false
	end

	table.sort(targets, function(e1, e2)
		return V.dist2(this.pos.x, this.pos.y, e1.pos.x, e1.pos.y) < V.dist2(this.pos.x, this.pos.y, e2.pos.x, e2.pos.y)
	end)

	local target = targets[1]

	b.from = V.vclone(this.pos)
	b.to = V.v(target.pos.x + target.unit.hit_offset.x, target.pos.y + target.unit.hit_offset.y)
	b.target_id = target.id
	b.damage_min = math.floor(b.damage_min * this.bounce_damage_mult)

	if b.damage_min < 1 then
		b.damage_min = 1
	end

	b.damage_max = math.floor(b.damage_max * this.bounce_damage_mult)

	if b.damage_max < 1 then
		b.damage_max = 1
	end

	return true
end

function scripts.bullet_tower_ranger_skill_c_bounce_clone.update(this, store)
	local b = this.bullet
	local target, ps

	this.bounces = 1

	local already_hit = {
		this.target_id
	}
	local tower = store.entities[b.source_id]
	local skill_level

	b.speed.x, b.speed.y = V.normalize(b.to.x - b.from.x, b.to.y - b.from.y)

	if b.particles_name then
		ps = E:create_entity(b.particles_name)
		ps.particle_system.track_id = this.id

		queue_insert(store, ps)
	end

	::label_633_0::

	while V.dist2(this.pos.x, this.pos.y, b.to.x, b.to.y) > b.fixed_speed * store.tick_length * (b.fixed_speed * store.tick_length) do
		target = store.entities[b.target_id]

		if target and target.health and not target.health.dead then
			b.to.x, b.to.y = target.pos.x + target.unit.hit_offset.x, target.pos.y + target.unit.hit_offset.y
		end

		b.speed.x, b.speed.y = V.mul(b.fixed_speed, V.normalize(b.to.x - this.pos.x, b.to.y - this.pos.y))
		this.pos.x, this.pos.y = this.pos.x + b.speed.x * store.tick_length, this.pos.y + b.speed.y * store.tick_length
		this.render.sprites[1].r = V.angleTo(b.to.x - this.pos.x, b.to.y - this.pos.y)

		coroutine.yield()
	end

	local will_kill

	if target and not target.health.dead then
		local d = SU.create_bullet_damage(b, target.id, this.id)

		queue_damage(store, d)

		will_kill = U.predict_damage(target, d) >= target.health.hp

		table.insert(already_hit, target.id)
		S:queue(this.sound_hit)
	end

	if b.extra_gold and b.extra_gold > 0 and will_kill then
		if b.hit_fx_coins then
			local sfx = E:create_entity(b.hit_fx_coins)

			sfx.pos = V.vclone(b.to)
			sfx.render.sprites[1].ts = store.tick_ts

			queue_insert(store, sfx)

			local gold_pos = V.v(sfx.pos.x, sfx.pos.y)
		end

		signal.emit("got-gold", b.to, b.extra_gold)
	end

	if b.hit_fx then
		local sfx = E:create_entity(b.hit_fx)

		sfx.pos = V.vclone(b.to)
		sfx.render.sprites[1].ts = store.tick_ts

		queue_insert(store, sfx)
	end

	if this.sound_events.hit then
		S:queue(this.sound_events.hit)
	end

	if this.bounces < this.max_bounces then
		local targets = U.find_enemies_in_range(store.entities, this.pos, 0, this.bounce_range, b.vis_flags, b.vis_bans, function(v)
			return not table.contains(already_hit, v.id)
		end)

		if targets then
			table.sort(targets, function(e1, e2)
				return V.dist2(this.pos.x, this.pos.y, e1.pos.x, e1.pos.y) < V.dist2(this.pos.x, this.pos.y, e2.pos.x, e2.pos.y)
			end)

			local target = targets[1]

			this.bounces = this.bounces + 1
			b.to.x, b.to.y = target.pos.x + target.unit.hit_offset.x, target.pos.y + target.unit.hit_offset.y
			b.target_id = target.id
			b.damage_min = math.floor(b.damage_min * this.bounce_damage_mult)

			if b.damage_min < 1 then
				b.damage_min = 1
			end

			b.damage_max = math.floor(b.damage_max * this.bounce_damage_mult)

			if b.damage_max < 1 then
				b.damage_max = 1
			end

			goto label_633_0
		end
	end

	queue_remove(store, this)
end

scripts.bullet_tower_ranger_ultimate = {}

function scripts.bullet_tower_ranger_ultimate.update(this, store)
	local b = this.bullet
	local s = this.render.sprites[1]
	local target = store.entities[b.target_id]
	local source = store.entities[b.source_id]
	local dest = V.vclone(b.to)

	local function update_sprite()
		if this.track_target and target and target.motion then
			local tpx, tpy = target.pos.x, target.pos.y

			if not b.ignore_hit_offset then
				tpx, tpy = tpx + target.unit.hit_offset.x, tpy + target.unit.hit_offset.y
			end

			local d = math.max(math.abs(tpx - b.to.x), math.abs(tpy - b.to.y))

			if d > b.max_track_distance then
				log.paranoid("(%s) ray_simple target (%s) out of max_track_distance", this.id, target.id)

				target = nil
			else
				dest.x, dest.y = target.pos.x, target.pos.y

				if target.unit and target.unit.hit_offset then
					dest.x, dest.y = dest.x + target.unit.hit_offset.x, dest.y + target.unit.hit_offset.y
				end
			end
		end

		local angle = V.angleTo(dest.x - this.pos.x, dest.y - this.pos.y)

		s.r = angle
		s.scale.x = V.dist(dest.x, dest.y, this.pos.x, this.pos.y) / this.image_width
	end

	local function hit_target()
		if target then
			if b.mod then
				local mod = E:create_entity(b.mod)

				mod.modifier.target_id = target.id
				mod.modifier.source_id = source.id

				queue_insert(store, mod)
			end

			local d = SU.create_bullet_damage(b, target.id, this.id)

			queue_damage(store, d)

			local will_kill = U.predict_damage(target, d) > target.health.hp

			if b.extra_gold and b.extra_gold > 0 and will_kill then
				if b.hit_fx_coins then
					local sfx = E:create_entity(b.hit_fx_coins)

					sfx.pos = V.vclone(b.to)
					sfx.render.sprites[1].ts = store.tick_ts

					queue_insert(store, sfx)

					local gold_pos = V.v(sfx.pos.x, sfx.pos.y)
				end

				signal.emit("got-gold", b.to, b.extra_gold)
			end

			local fx = E:create_entity(b.hit_fx)

			fx.pos = V.v(target.pos.x + target.unit.hit_offset.x, target.pos.y + target.unit.hit_offset.y)
			fx.render.sprites[1].ts = store.tick_ts
			fx.render.sprites[1].r = this.render.sprites[1].r

			queue_insert(store, fx)
		elseif this.missed_shot and GR:cell_is_only(this.pos.x, this.pos.y, TERRAIN_LAND) then
			local fx = E:create_entity(this.missed_arrow_decal)

			fx.pos = V.v(b.to.x, b.to.y)
			fx.render.sprites[1].ts = store.tick_ts

			queue_insert(store, fx)

			local fx = E:create_entity(this.missed_arrow_dust)

			fx.pos = V.v(b.to.x, b.to.y)
			fx.render.sprites[1].ts = store.tick_ts

			queue_insert(store, fx)

			local fx = E:create_entity(this.missed_arrow)

			fx.pos = V.v(b.to.x, b.to.y)
			fx.render.sprites[1].ts = store.tick_ts
			fx.render.sprites[1].flip_x = b.to.x > b.from.x

			queue_insert(store, fx)
		end
	end

	if not b.ignore_hit_offset and this.track_target and target and target.motion then
		b.to.x, b.to.y = target.pos.x + target.unit.hit_offset.x, target.pos.y + target.unit.hit_offset.y
	end

	s.scale = s.scale or V.v(1, 1)
	s.ts = store.tick_ts

	update_sprite()

	if b.hit_time > fts(1) then
		while store.tick_ts - s.ts < b.hit_time do
			coroutine.yield()

			if target and U.flag_has(target.vis.bans, F_RANGED) then
				target = nil
			end

			if this.track_target then
				update_sprite()
			end
		end
	end

	local already_hit_target = false

	if this.ray_duration then
		while store.tick_ts - s.ts < this.ray_duration do
			if this.track_target then
				update_sprite()
			end

			if source and not store.entities[source.id] then
				queue_remove(store, this)

				break
			end

			if not already_hit_target and store.tick_ts - s.ts > this.hit_delay then
				hit_target()

				already_hit_target = true
			end

			coroutine.yield()

			s.hidden = false
		end
	else
		while not U.animation_finished(this, 1) do
			if source and not store.entities[source.id] then
				queue_remove(store, this)

				break
			end

			if not already_hit_target and store.tick_ts - s.ts > this.hit_delay then
				hit_target(b, target)

				already_hit_target = true
			end

			coroutine.yield()
		end
	end

	queue_remove(store, this)
end

scripts.tower_culverine = {}

function scripts.tower_culverine.get_info(this, store)
	local info = scripts.tower_common.get_info(this)

	info.damage_type = this.attacks.list[1].damage_type

	return info
end

function scripts.tower_culverine.update(this, store)
	local sa = this.powers and this.powers.skill_a or nil
	local sb = this.powers and this.powers.skill_b or nil
	local sc = this.powers and this.powers.skill_c or nil
	local su = this.powers and this.powers.ultimate or nil
	local a = this.attacks
	local ba = this.attacks.list[1]
	local sba = this.attacks.list[2]
	local saa = this.timed_attacks and this.timed_attacks.list[1]
	local sca = this.timed_attacks and this.timed_attacks.list[2]
	local sua = this.timed_attacks and this.timed_attacks.list[3]
	local ult_start_cd = sua ~= nil and store.wave_group_number == 0

	if sua then
		sua.disabled = not su.active
	end

	local direct_skill_a = false
	local normal_bullet_loaded = false
	local aa_count = 0

	local function check_upgrades_purchase()
		if this.powers then
			for _, pow in pairs(this.powers) do
				if pow.changed then
					pow.changed = nil

					if pow == sa then
						saa.disabled = false
						saa.cooldown = sa.cooldown[pow.level]
						saa.bullet = "bullet_culverine_skill_a_lvl" .. pow.level

						if pow.level == 1 then
							saa.ts = store.tick_ts - saa.cooldown
						end
					elseif pow == sb then
						sba.disabled = false
						sba.bullet = "bullet_culverine_skill_b_lvl" .. pow.level

						if ba ~= sba then
							ba = sba
						end
					elseif pow == sc then
						sca.disabled = false
						sca.cooldown = sc.cooldown[pow.level]
						sca.shots = sc.shots[pow.level]
						sca.rate_of_fire = sc.rate_of_fire[pow.level]

						if pow.level == 1 then
							sca.ts = store.tick_ts - sca.cooldown
						end
					end
				end
			end
		end
	end

	local function get_quadrant(pos, angles)
		local vx, vy = V.sub(pos.x, pos.y, this.pos.x, this.pos.y)
		local v_angle = V.angleTo(vy, vx)
		local angle = v_angle * 180 / math.pi
		local as = angles
		local q, af

		af = not (angle > 0)

		local abs_angle = math.abs(angle)

		if abs_angle >= as[1] and abs_angle < as[2] then
			q = 1
		elseif abs_angle >= as[2] and abs_angle < as[3] then
			q = 2
		elseif abs_angle >= as[3] and abs_angle < as[4] then
			q = 3
		elseif abs_angle >= as[4] and abs_angle <= as[5] then
			q = 4
		end

		return q, af
	end

	local function get_animation_given_quadrant(animation, q)
		return animation .. this.anim_quadrant_suffixes[q]
	end

	local function play_cannon_animation_given_target_position(anim, pos, loops)
		local q, af = get_quadrant(pos, this.quadrant_angles)

		U.animation_start(this, get_animation_given_quadrant(anim, q), af, store.tick_ts, loops, this.cannon_sid)

		if q == 3 then
			this.render.sprites[this.shooter_sid].hidden = false

			U.animation_start(this, anim, af, store.tick_ts, loops, this.shooter_sid)
		else
			this.render.sprites[this.shooter_sid].hidden = true
		end

		return q, af
	end

	local function can_shoot_ulti()
		if this.tower.level < 4 then
			return false
		end

		return not normal_bullet_loaded and not this.tower.blocked and su and not sua.disabled and aa_count >= sua.attacks_to_trigger
	end

	local function can_shoot_skill_a(trigger_enemy, enemies)
		if this.tower.level < 4 then
			return false
		end

		local target_condition = enemies and #enemies >= saa.min_targets

		if enemies then
			target_condition = target_condition or #table.filter(enemies, function(k, v)
				return v.health.magic_armor >= saa.min_magic_res
			end) > 0
		end

		return not normal_bullet_loaded and not this.tower.blocked and trigger_enemy and sa and not saa.disabled and target_condition and store.tick_ts - saa.ts > saa.cooldown
	end

	local function can_shoot_skill_c(trigger_enemy, enemies)
		if this.tower.level < 4 then
			return false
		end

		local target_condition = enemies and #enemies >= sca.min_targets

		if enemies then
			target_condition = target_condition or #table.filter(enemies, function(k, v)
				return v.health.hp >= sca.min_health
			end) > 0
		end

		return not normal_bullet_loaded and not this.tower.blocked and trigger_enemy and sc and not sca.disabled and store.tick_ts - sca.ts > sca.cooldown and target_condition
	end

	local function shoot_ray(enemy, pred_pos, attack, q)
		local shooting_right = not this.render.sprites[this.cannon_sid].flip_x
		local boffset = attack.bullet_start_offset[q]
		local b = E:create_entity(attack.bullet)

		b.pos.x = this.pos.x + boffset.x * (shooting_right and 1 or -1)
		b.pos.y = this.pos.y + boffset.y
		b.bullet.from = V.vclone(b.pos)
		b.bullet.to = V.v(pred_pos.x, pred_pos.y)
		b.bullet.target_id = enemy and enemy.id or nil
		b.bullet.source_id = this.id
		b.bullet.damage_factor = this.tower.damage_factor

		if attack.critical_chance and math.random() < attack.critical_chance then
			b.bullet.damage_factor = b.bullet.damage_factor * 2
		end

		queue_insert(store, b)
	end

	local function shoot_bullet(target_pos, aa)
		local b = E:create_entity(aa.bullet)

		b.bullet.damage_factor = this.tower.damage_factor
		b.pos.x, b.pos.y = this.pos.x + aa.bullet_start_offset.x, this.pos.y + aa.bullet_start_offset.y
		b.bullet.from = V.vclone(b.pos)
		b.bullet.to = V.vclone(target_pos)
		b.bullet.source_id = this.id

		queue_insert(store, b)

		return b
	end

	local function ultimate(rapid_fire)
		if not rapid_fire then
			U.animation_start(this, sua.animation_reload, nil, store.tick_ts, false, this.base_sid)
		end

		S:queue(sua.sound, {
			delay = fts(25)
		})

		while not U.animation_finished(this, this.base_sid) do
			coroutine.yield()
		end

		this.render.sprites[this.shooter_sid].hidden = true

		U.animation_start(this, sua.animation, nil, store.tick_ts, false, this.base_sid)
		U.animation_start(this, sua.animation, nil, store.tick_ts, false, this.bullets_sid)
		U.animation_start(this, sua.animation, nil, store.tick_ts, false, this.cannon_sid)
		U.y_wait(store, sua.shoot_time)

		local aura, decal, inc

		if this.tower.blocked then
			-- block empty
		else
			aura = E:create_entity(sua.aura)
			aura.pos = V.vclone(tpos(this))

			queue_insert(store, aura)

			decal = E:create_entity(sua.big_explosion_decal)
			decal.pos = V.vclone(tpos(this))
			decal.render.sprites[1].ts = store.tick_ts

			queue_insert(store, decal)
			signal.emit("tower-ultimate-used", this)

			inc = math.pi / 4

			for i = 1, 8 do
				local pe = U.point_on_ellipse(this.pos, aura.aura.radius * 0.6, inc * (i - 1))
				local roffset = V.v(U.frandom(sua.min_small_explosion_offset, sua.max_small_explosion_offset), U.frandom(sua.min_small_explosion_offset, sua.max_small_explosion_offset))
				local final_pos = V.v(pe.x + roffset.x, pe.y + roffset.y)

				if P:valid_node_nearby(final_pos.x, final_pos.y) then
					local small_decal = E:create_entity(sua.small_explosion_decal)

					small_decal.pos.x, small_decal.pos.y = final_pos.x, final_pos.y
					small_decal.render.sprites[1].ts = store.tick_ts

					queue_insert(store, small_decal)
				end
			end

			U.y_animation_wait(this, this.cannon_sid)

			this.render.sprites[this.shooter_sid].hidden = false
		end

		local ve = v(this.pos.x + 1, this.pos.y)
		local trigger_enemy, enemies, pred_pos = U.find_foremost_enemy(store.entities, tpos(this), 0, a.range, fts(1), nil, a.vis_bans)

		if trigger_enemy then
			ve = pred_pos
		end

		local q, af = get_quadrant(ve, this.quadrant_angles)

		U.animation_start(this, "shoot", af, store.tick_ts - fts(28), 1, this.shooter_sid)
		U.animation_start(this, "shoot", af, store.tick_ts - fts(28), 1, this.cannon_sid)
		U.y_wait(store, fts(6))
		U.animation_start(this, "idle", af, store.tick_ts, true, this.cannon_sid)
	end

	ba.ts = store.tick_ts - ba.cooldown

	play_cannon_animation_given_target_position("idle", V.v(this.pos.x + 1, this.pos.y), true)

	::label_640_0::

	while true do
		direct_skill_a = false

		if this.tower.blocked then
			coroutine.yield()
		else
			check_upgrades_purchase()
			SU.towers_swaped(store, this, this.attacks.list)

			local trigger_enemy, enemies, pred_pos = U.find_foremost_enemy(store.entities, tpos(this), 0, a.range, fts(1), nil, a.vis_bans)

			if trigger_enemy then
				play_cannon_animation_given_target_position("idle", trigger_enemy.pos, true)
			end

			if can_shoot_skill_c(trigger_enemy, enemies) then
				local aa = sca

				S:queue(aa.sound_prep, {
					delay = fts(21)
				})
				U.animation_start(this, aa.animation_reload, nil, store.tick_ts, 1, this.base_sid)
				U.y_wait(store, aa.buff_time)

				local center_pos = tpos(this)

				this._buff_fg_sc = E:create_entity(aa.buff_fg)
				this._buff_fg_sc.pos = V.vclone(center_pos)
				this._buff_fg_sc.tween.ts = store.tick_ts
				this._buff_fg_sc.render.sprites[1].ts = store.tick_ts

				queue_insert(store, this._buff_fg_sc)

				this._buff_bg_sc = E:create_entity(aa.buff_bg)
				this._buff_bg_sc.pos = V.vclone(center_pos)
				this._buff_bg_sc.tween.ts = store.tick_ts
				this._buff_bg_sc.render.sprites[1].ts = store.tick_ts

				queue_insert(store, this._buff_bg_sc)
				U.y_animation_wait(this, this.base_sid)

				local shoot_enemy, _, pred_pos = U.find_foremost_enemy(store.entities, tpos(this), 0, a.range, fts(1), aa.vis_flags, aa.vis_bans)

				while not shoot_enemy do
					shoot_enemy, _, pred_pos = U.find_foremost_enemy(store.entities, tpos(this), 0, a.range, fts(1), aa.vis_flags, aa.vis_bans)

					coroutine.yield()
				end

				local default_pos = V.vclone(pred_pos)
				local shots = 0

				while shots < aa.shots and not this.tower.blocked do
					local shoot_enemy, _, pred_pos = U.find_foremost_enemy(store.entities, tpos(this), 0, a.range, fts(1), aa.vis_flags, aa.vis_bans)

					if not shoot_enemy then
						pred_pos = default_pos
					else
						default_pos = V.vclone(pred_pos)
					end

					local q, af = play_cannon_animation_given_target_position(ba.animation, pred_pos, false)

					U.animation_start(this, aa.animation, false, store.tick_ts, false, this.base_sid)
					U.animation_start(this, ba.animation, false, store.tick_ts, false, this.bullets_sid)
					U.y_wait(store, ba.shoot_time)

					if this.tower.blocked then
						break
					end

					this._buff_bg_sc.render.sprites[1].ts = store.tick_ts

					S:queue(aa.sound)
					shoot_ray(shoot_enemy, pred_pos, ba, q)

					normal_bullet_loaded = false

					check_upgrades_purchase()

					aa_count = aa_count + 1
					shots = shots + 1

					U.y_wait(store, aa.rest_time)

					if can_shoot_ulti(trigger_enemy) then
						aa_count = 0

						ultimate(true)
						U.y_wait(store, fts(12))
					end

					U.y_wait(store, aa.rate_of_fire)
				end

				queue_remove(store, this._buff_fg_sc)
				U.animation_start(this, ba.animation_reload, false, store.tick_ts, false, this.base_sid)

				while not U.animation_finished(this, this.base_sid) do
					local te, _, pp = U.find_foremost_enemy(store.entities, tpos(this), 0, a.range, fts(1), nil, a.vis_bans)

					if te then
						play_cannon_animation_given_target_position("idle", pp, true)
					end

					coroutine.yield()
				end

				queue_remove(store, this._buff_bg_sc)
				U.y_wait(store, ba.cooldown - ba.animation_duration)

				sca.ts = store.tick_ts
			end

			if trigger_enemy and not this.tower.blocked then
				local aa = ba
				local shoot_enemy, _, pred_pos = U.find_foremost_enemy(store.entities, tpos(this), 0, a.range, fts(1), aa.vis_flags, aa.vis_bans)

				if not shoot_enemy or not pred_pos then
					SU.delay_attack(store, aa, fts(10))
				else
					aa.ts = store.tick_ts

					local last_pos = V.vclone(pred_pos)
					local q, af = play_cannon_animation_given_target_position(aa.animation, pred_pos, false)

					U.animation_start(this, aa.animation, false, store.tick_ts, false, this.base_sid)
					U.animation_start(this, aa.animation, false, store.tick_ts, false, this.bullets_sid)
					U.y_wait(store, aa.shoot_time)

					if this.tower.blocked then
						-- block empty
					else
						S:queue(aa.sound)
						shoot_ray(shoot_enemy, last_pos, aa, q)

						normal_bullet_loaded = false

						check_upgrades_purchase()

						aa_count = aa_count + 1

						if this.tower.level == 4 then
							U.y_animation_wait(this, this.base_sid)

							trigger_enemy, enemies, pred_pos = U.find_foremost_enemy(store.entities, tpos(this), 0, a.range, fts(1), aa.vis_flags, aa.vis_bans)

							if can_shoot_ulti(trigger_enemy) then
								aa_count = 0

								ultimate(false)
							end

							if can_shoot_skill_a(trigger_enemy, enemies) then
								goto label_640_1
							end

							if can_shoot_skill_c(trigger_enemy, enemies) then
								goto label_640_0
							end

							U.animation_start(this, aa.animation_reload, nil, store.tick_ts, false, this.base_sid)
						else
							U.y_wait(store, aa.time_to_rest + fts(4))
						end

						while not U.animation_finished(this, this.base_sid) do
							local te, _, pp = U.find_foremost_enemy(store.entities, tpos(this), 0, a.range, fts(1), nil, a.vis_bans)

							if te then
								last_pos = pp
							end

							coroutine.yield()
						end

						U.y_wait(store, aa.cooldown - aa.animation_duration)

						normal_bullet_loaded = true

						play_cannon_animation_given_target_position("idle", last_pos, true)
					end
				end
			end

			direct_skill_a = true

			::label_640_1::

			if can_shoot_skill_a(trigger_enemy, enemies) then
				local aa = saa

				if direct_skill_a then
					U.y_wait(store, ba.cooldown)
				end

				local bt = E:get_template(aa.bullet)
				local pred_time = aa.anim_length + aa.cast_time + bt.bullet.flight_time
				local shoot_enemy, _, pred_pos = U.find_foremost_enemy(store.entities, tpos(this), 0, a.range, pred_time, aa.vis_flags, aa.vis_bans)

				if not shoot_enemy or not pred_pos or this.tower.blocked then
					SU.delay_attack(store, aa, fts(10))
				else
					local last_pos = V.vclone(pred_pos)

					U.y_animation_play(this, aa.animation_reload, nil, store.tick_ts, 1, this.base_sid)
					S:queue(aa.sound_prep)
					U.animation_start(this, aa.animation, nil, store.tick_ts, 1, this.cannon_sid)
					U.animation_start(this, aa.animation, nil, store.tick_ts, 1, this.base_sid)
					U.animation_start(this, aa.animation, nil, store.tick_ts, 1, this.bullets_sid)

					this.render.sprites[this.shooter_sid].hidden = true

					U.y_wait(store, aa.cast_time)

					shoot_enemy, _, pred_pos = U.find_foremost_enemy(store.entities, tpos(this), 0, a.range, bt.bullet.flight_time, aa.vis_flags, aa.vis_bans)

					if this.tower.blocked then
						-- block empty
					else
						if not shoot_enemy then
							pred_pos = last_pos
						end

						local b = shoot_bullet(pred_pos, aa)

						saa.ts = store.tick_ts
						b.render.sprites[1].z = Z_OBJECTS
						b.render.sprites[1].sort_y_offset = 1

						U.y_wait(store, fts(8))

						b.render.sprites[1].z = Z_BULLETS
						b.render.sprites[1].sort_y_offset = 0

						U.y_animation_wait(this, this.cannon_sid)

						this.render.sprites[this.shooter_sid].hidden = false

						local q, af = get_quadrant(pred_pos, this.quadrant_angles)

						U.animation_start(this, "shoot", af, store.tick_ts - fts(28), 1, this.shooter_sid)
						U.animation_start(this, "shoot", af, store.tick_ts - fts(28), 1, this.cannon_sid)
						U.y_wait(store, fts(6))
						U.animation_start(this, "idle", af, store.tick_ts, true, this.cannon_sid)
						U.y_wait(store, fts(10))

						if can_shoot_skill_c(trigger_enemy, enemies) then
							goto label_640_0
						end

						U.animation_start(this, ba.animation_reload, false, store.tick_ts, false, this.base_sid)

						while not U.animation_finished(this, this.base_sid) do
							local te, _, pp = U.find_foremost_enemy(store.entities, tpos(this), 0, a.range, fts(1), nil, a.vis_bans)

							if te then
								last_pos = pp
							end

							coroutine.yield()
						end

						U.y_wait(store, ba.cooldown - ba.animation_duration)
					end
				end
			end

			coroutine.yield()
		end
	end
end

function scripts.tower_culverine.remove(this, store)
	if this._buff_fg_sc then
		queue_remove(store, this._buff_fg_sc)
	end

	if this._buff_bg_sc then
		queue_remove(store, this._buff_bg_sc)
	end

	return true
end

scripts.mod_bullet_culverine_skill_a = {}

function scripts.mod_bullet_culverine_skill_a.insert(this, store, script)
	local target = store.entities[this.modifier.target_id]

	if not target or target.health.dead or target.enemy and not target.enemy.can_accept_magic then
		return false
	end

	if band(this.modifier.vis_flags, target.vis.bans) ~= 0 or band(this.modifier.vis_bans, target.vis.flags) ~= 0 then
		log.paranoid("mod %s cannot be applied to entity %s:%s because of vis flags/bans", this.template_name, target.id, target.template_name)

		return false
	end

	local red = target.health.magic_armor * this.magic_armor_red_factor

	SU.magic_armor_dec(target, red)

	this._magic_armor_lost = red

	signal.emit("mod-applied", this, target)

	return true
end

function scripts.mod_bullet_culverine_skill_a.remove(this, store, script)
	local target = store.entities[this.modifier.target_id]

	if target then
		SU.magic_armor_inc(target, this._magic_armor_lost)

		this._magic_armor_lost = 0
	end

	return true
end

function scripts.mod_bullet_culverine_skill_a.update(this, store, script)
	local m = this.modifier
	local last_ts = store.tick_ts
	local target = store.entities[m.target_id]

	if not target then
		queue_remove(store, this)

		return
	end

	this.pos = target.pos

	while true do
		target = store.entities[m.target_id]

		if not target or target.health.dead or store.tick_ts - m.ts >= m.duration then
			queue_remove(store, this)

			return
		end

		if this.render and m.use_mod_offset and target.unit.mod_offset then
			this.render.sprites[1].offset.x, this.render.sprites[1].offset.y = target.unit.mod_offset.x, target.unit.mod_offset.y
		end

		coroutine.yield()
	end
end

scripts.tower_sunray_master = {}

function scripts.tower_sunray_master.get_info(this)
	local info = scripts.tower_common.get_info(this)

	if this.tower_upgrade_persistent_data.current_mode == 0 then
		local bullet = E:get_template(this.attacks.list[1].bullet)
		local aura_dmg = E:get_template(bullet.bullet.hit_payload)

		info.damage_min = aura_dmg.aura.damage_min * this.tower.damage_factor
		info.damage_max = aura_dmg.aura.damage_max * this.tower.damage_factor
		info.cooldown = 2
	else
		local bullet = E:get_template(this.attacks.list[2].bullet)

		info.damage_min = bullet.bullet.damage_min * this.tower.damage_factor
		info.damage_max = bullet.bullet.damage_max * this.tower.damage_factor
		info.cooldown = this.attacks.list[2].cooldown
	end

	info.type = STATS_TYPE_TOWER_MAGE
	info.range = this.attacks.range

	return info
end

function scripts.tower_sunray_master.update(this, store)
	local last_ts = store.tick_ts
	local a_name, a_flip, angle_idx, target, pred_pos
	local s = this.render.sprites
	local attk_index = 1
	local fragments_up = false
	local did_overcharge = false
	local gem_broken = false
	local fragments = false
	local beam_attack = this.attacks.list[1]
	local beam_attack_duration = E:get_template(beam_attack.bullet).ray_duration
	local rapid_fire_attack = this.attacks.list[2]
	local ult_attack = this.attacks.list[3] or nil
	local ult_start_cd = ult_attack ~= nil and store.wave_group_number == 0
	local pow_a = this.powers and this.powers.skill_a or nil
	local pow_b = this.powers and this.powers.skill_b or nil
	local pow_c = this.powers and this.powers.skill_c or nil

	if this.powers and this.powers.ultimate.active then
		ult_attack.ts = store.tick_ts
	end

	local MODE_BEAM = 0
	local MODE_RAPID_FIRE = 1
	local attacking = false
	local switched_mode_while_attacking = false

	this.spawn_golem_flag = false
	this.can_spawn_golem = true

	local shots = 0

	local function create_gem_glow()
		this.decal_glow = E:create_entity(this.decal_gem_glow)
		this.decal_glow.tween.ts = store.tick_ts

		if this.tower.level == 1 then
			this.decal_glow.pos = v(tpos(this).x + 2, tpos(this).y + 55)
		elseif this.tower.level == 2 then
			this.decal_glow.pos = v(tpos(this).x + 2, tpos(this).y + 60)
		elseif this.tower.level == 3 then
			this.decal_glow.pos = v(tpos(this).x + 2, tpos(this).y + 65)
		else
			this.decal_glow.pos = v(tpos(this).x + 2, tpos(this).y + 70)
		end

		queue_insert(store, this.decal_glow)
	end

	local function destroy_gem_glow()
		if this.decal_glow then
			this.decal_glow.tween.disabled = true

			queue_remove(store, this.decal_glow)

			this.decal_glow = nil
		end
	end

	local function create_gem_fx()
		this.gem_fx = E:create_entity(this.decal_beam_gem_fx)
		this.gem_fx.pos = v(this.pos.x + beam_attack.offset.x, this.pos.y + beam_attack.offset.y)
		this.gem_fx.render.sprites[1].ts = store.tick_ts

		queue_insert(store, this.gem_fx)
	end

	local function destroy_gem_fx()
		if this.gem_fx ~= nil then
			queue_remove(store, this.gem_fx)

			this.gem_fx = nil
		end
	end

	local function check_change_mode()
		if this.change_mode then
			if attacking then
				return false
			end

			this.change_mode = false
			attacking = false

			if this.tower_upgrade_persistent_data.current_mode == MODE_BEAM then
				this.tower_upgrade_persistent_data.current_mode = MODE_RAPID_FIRE

				if not gem_broken then
					S:queue(this.sound_change_rapid_fire)
					U.y_animation_play(this, "gem_break", nil, store.tick_ts, 1, this.render.sid_gem)
				end

				if not fragments then
					U.y_animation_play(this, "fragments", nil, store.tick_ts, 1, this.render.sid_gem)
				end

				destroy_gem_glow()
			else
				this.tower_upgrade_persistent_data.current_mode = MODE_BEAM

				if string.find(s[this.render.sid_mage].name, "attack_2") then
					U.animation_start(this, this.last_an .. "_end", nil, store.tick_ts, false, this.render.sid_mage)
				end

				S:queue(this.sound_change_beam, {
					delay = fts(9)
				})
				U.y_animation_play(this, "gem_form", nil, store.tick_ts, 1, this.render.sid_gem)
				U.animation_start(this, "idle_gem", nil, store.tick_ts, true, this.render.sid_gem)

				gem_broken = false
				fragments = false

				create_gem_glow()
			end

			return true
		end

		return false
	end

	local function check_upgrades_purchase()
		if this.powers then
			for _, pow in pairs(this.powers) do
				if pow.changed then
					pow.changed = nil

					if pow == pow_a then
						if not this.controller_soldiers then
							if not this.barrack.rally_pos and this.tower.default_rally_pos then
								this.barrack.rally_pos = V.vclone(this.tower.default_rally_pos)
							end

							this.controller_soldiers = E:create_entity(this.controller_soldiers_template)
							this.controller_soldiers.tower_ref = this
							this.controller_soldiers.pos = this.pos

							queue_insert(store, this.controller_soldiers)
						end

						this.controller_soldiers.pow_level = pow.level
						this.controller_soldiers.upgraded = true
						this.barrack.soldier_type = this.barrack.soldier_prefix .. pow.level
					elseif pow == pow_b then
						beam_attack.aura_skill_b = "aura_sunray_master_skill_b_lvl" .. pow.level
						beam_attack.aura_skill_b_decal = "decal_sunray_master_skill_b_explosion"
						beam_attack.skill_b_disabled = false
					elseif pow == pow_c then
						rapid_fire_attack.skill_c_bullet = "bullet_sunray_master_skill_c_lvl" .. pow.level
						rapid_fire_attack.skill_c_spawn_fx = "fx_sunray_master_skill_c_spawn"
						rapid_fire_attack.skill_c_disabled = false
					end
				end
			end
		end
	end

	local function find_target()
		local attack
		local node_prediction = 0

		if this.tower_upgrade_persistent_data.current_mode == MODE_BEAM then
			attack = beam_attack
			node_prediction = beam_attack.shoot_time + fts(3)
		else
			attack = rapid_fire_attack
			node_prediction = E:get_template(rapid_fire_attack.bullet).bullet.flight_time
		end

		local target, targets, pred_pos = U.find_foremost_enemy(store.entities, tpos(this), 0, this.attacks.range, node_prediction, attack.vis_flags, attack.vis_bans)

		return target, targets, pred_pos
	end

	local function map_animation_rapid_fire(an, random)
		local attack = string.sub(an, -1)

		if this.tower.level == 1 then
			if attack == "a" then
				return random == 0 and "a" or "c"
			end

			if attack == "b" then
				return "b"
			end
		elseif this.tower.level == 2 then
			if attack == "a" then
				return "a"
			end

			if attack == "b" then
				return random == 0 and "b" or "d"
			end
		else
			if attack == "a" then
				return random == 0 and "a" or "c"
			end

			if attack == "b" then
				return random == 0 and "b" or "d"
			end
		end
	end

	local function map_bullet_to_spawn_offset(an, random)
		local attack = string.sub(an, -1)

		if this.tower.level == 1 then
			if attack == "a" then
				return random == 0 and 4 or 3
			end

			if attack == "b" then
				return 1
			end
		elseif this.tower.level == 2 then
			if attack == "a" then
				return 3
			end

			if attack == "b" then
				return random == 0 and 1 or 2
			end
		else
			if attack == "a" then
				return random == 0 and 3 or 4
			end

			if attack == "b" then
				return random == 0 and 1 or 2
			end
		end
	end

	local function check_conditions_animation()
		check_upgrades_purchase()
		check_change_mode()

		if this.tower.blocked then
			local an, af = U.animation_name_facing_point(this, "idle", this.attacks._last_target_pos, this.render.sid_mage)

			U.animation_start(this, an, nil, store.tick_ts, false, this.render.sid_mage)

			if this.mod_target then
				queue_remove(store, this.mod_target)
			end
		end
	end

	if this.tower_upgrade_persistent_data.last_ts then
		last_ts = this.tower_upgrade_persistent_data.last_ts
		beam_attack.ts = this.tower_upgrade_persistent_data.last_ts
	else
		beam_attack.ts = store.tick_ts - beam_attack.cooldown
		rapid_fire_attack.ts = store.tick_ts - rapid_fire_attack.cooldown
	end

	if not this.attacks._last_target_pos then
		this.attacks._last_target_pos = {}
		this.attacks._last_target_pos = v(REF_W, 0)
	end

	if this.tower_upgrade_persistent_data.current_mode == 0 then
		U.animation_start(this, "idle_gem", nil, store.tick_ts, true, this.render.sid_gem)
		U.animation_start(this, "gem_form_glow", nil, store.tick_ts, true, this.render.sid_tower_glow)
		create_gem_glow()
	else
		U.animation_start(this, "idle_1", nil, store.tick_ts, true, this.render.sid_gem)
	end

	U.animation_start(this, "idle_1", nil, store.tick_ts, true, this.render.sid_mage)

	while true do
		if ult_start_cd and store.wave_group_number > 0 then
			ult_start_cd = false
			ult_attack.ts = store.tick_ts
		end

		if this.tower.blocked then
			coroutine.yield()
		else
			check_upgrades_purchase()
			check_change_mode()
			SU.towers_swaped(store, this, this.attacks.list)

			if this.spawn_golem_flag then
				this.spawn_golem_flag = false
				this.can_spawn_golem = false

				U.animation_start(this, "golem_spawn", nil, store.tick_ts, 1, this.render.sid_mage)
				U.animation_start(this, "golem_spawn", nil, store.tick_ts, 1, this.render.sid_tower_glow)

				while not U.animation_finished(this, this.render.sid_mage, 1) do
					check_conditions_animation()
					coroutine.yield()
				end
			end

			if this.powers and this.powers.ultimate.active and store.tick_ts - ult_attack.ts > ult_attack.cooldown then
				local enemy, enemies, _ = U.find_foremost_enemy(store.entities, tpos(this), 0, ult_attack.range, ult_attack.cast_time, ult_attack.vis_flags, ult_attack.vis_bans)

				if not enemies or #enemies < ult_attack.min_targets then
					-- block empty
				else
					U.animation_start(this, "solarblast", nil, store.tick_ts, false, this.render.sid_mage)
					U.animation_start(this, "solarblast_glow", nil, store.tick_ts, false, this.render.sid_tower_glow)
					S:queue(ult_attack.sound)
					U.y_wait(store, ult_attack.cast_time)

					local enemy, enemies, _ = U.find_foremost_enemy(store.entities, tpos(this), 0, ult_attack.range, ult_attack.cast_time, ult_attack.vis_flags, ult_attack.vis_bans)

					if not enemies or #enemies < ult_attack.min_targets then
						-- block empty
					else
						local start_ts = store.tick_ts

						for i = 1, ult_attack.number_of_beams do
							local spread = math.random(ult_attack.min_spread, ult_attack.max_spread)
							local pos = enemy.pos
							local decal = E:create_entity(ult_attack.decal)

							decal.render.sprites[1].ts = store.tick_ts

							local rand_pos = V.v(pos.x + math.random(-spread, spread), pos.y + math.random(-spread, spread))

							decal.pos = rand_pos

							if i == 1 or band(GR:cell_type(rand_pos.x, rand_pos.y), TERRAIN_NOWALK) ~= 0 then
								decal.pos = pos
							end

							decal.source_id = this.id

							queue_insert(store, decal)
							U.y_wait(store, ult_attack.delay_between_shots)
						end

						while not U.animation_finished(this, this.render.sid_mage, 1) do
							coroutine.yield()
						end

						ult_attack.ts = store.tick_ts

						signal.emit("tower-ultimate-used", this)

						last_ts = start_ts
					end
				end
			end

			if this.tower_upgrade_persistent_data.current_mode == MODE_BEAM then
				if store.tick_ts - beam_attack.ts > beam_attack.cooldown then
					local target, _, pred_pos = find_target()

					if not target or this.tower_upgrade_persistent_data.current_mode == MODE_RAPID_FIRE or band(GR:cell_type(target.pos.x, target.pos.y), TERRAIN_NOWALK) ~= 0 then
						SU.delay_attack(store, beam_attack, fts(10))

						goto label_658_0
					end

					this.attacks._last_target_pos = pred_pos

					local an, af = U.animation_name_facing_point(this, "attack_1", this.attacks._last_target_pos, this.render.sid_mage)

					U.animation_start(this, an .. "_start", nil, store.tick_ts, false, this.render.sid_mage)
					U.animation_start(this, "attack_1_gem_start", nil, store.tick_ts, false, this.render.sid_gem)
					U.animation_start(this, "attack_1_glow_start", nil, store.tick_ts, false, this.render.sid_tower_glow)
					S:queue(beam_attack.sfx_start)
					create_gem_fx()

					while not U.animation_finished(this, this.render.sid_mage, 1) do
						check_conditions_animation()
						coroutine.yield()
					end

					if this.tower_upgrade_persistent_data.current_mode == MODE_RAPID_FIRE then
						destroy_gem_fx()

						goto label_658_0
					end

					attacking = true
					this.can_spawn_golem = false

					local start_ts = store.tick_ts

					U.animation_start(this, an .. "_loop", nil, store.tick_ts, true, this.render.sid_mage)
					U.animation_start(this, "attack_1_gem_loop", nil, store.tick_ts, true, this.render.sid_gem)
					U.animation_start(this, "attack_1_glow_loop", nil, store.tick_ts, true, this.render.sid_tower_glow)
					S:queue(beam_attack.sfx_loop)

					local bullet = E:create_entity(beam_attack.bullet)
					local pos_x, pos_y = this.pos.x + beam_attack.offset.x, this.pos.y + beam_attack.offset.y

					bullet.pos = V.v(pos_x, pos_y)
					bullet.bullet.from = V.vclone(bullet.pos)
					bullet.bullet.to = V.vclone(pred_pos)
					bullet.bullet.target_id = nil
					bullet.bullet.source_id = this.id
					bullet.bullet.damage_factor = this.tower.damage_factor
					bullet.bullet.max_track_distance = beam_attack.range

					if target.pos.y > tpos(this).y + beam_attack.offset.y then
						bullet.render.sprites[1].z = Z_OBJECTS_COVERS
					end

					queue_insert(store, bullet)

					local hit_fx = E:create_entity(beam_attack.hit_fx)

					hit_fx.pos = V.vclone(pred_pos)
					hit_fx.render.sprites[1].ts = store.tick_ts

					queue_insert(store, hit_fx)
					U.y_wait(store, beam_attack_duration)

					while not U.animation_finished(this, this.render.sid_mage, 1) do
						check_upgrades_purchase()
						check_change_mode()
						coroutine.yield()
					end

					if this.powers and not beam_attack.skill_b_disabled then
						S:stop(beam_attack.sfx_loop)
						S:queue(beam_attack.sfx_end)
						destroy_gem_fx()
						U.animation_start(this, "overcharge", nil, store.tick_ts, false, this.render.sid_mage)
						U.animation_start(this, "overcharge", nil, store.tick_ts, false, this.render.sid_gem)
						U.animation_start(this, "overcharge_glow", nil, store.tick_ts, false, this.render.sid_tower_glow)
						U.y_wait(store, fts(67))

						if this.overcharge_sfx then
							S:queue(this.overcharge_sfx)
						end

						local aura = E:create_entity(beam_attack.aura_skill_b)

						aura.pos = V.vclone(tpos(this))

						queue_insert(store, aura)

						local decal = E:create_entity(beam_attack.aura_skill_b_decal)

						decal.pos = V.vclone(tpos(this))
						decal.render.sprites[1].ts = store.tick_ts

						queue_insert(store, decal)

						did_overcharge = true
					else
						U.animation_start(this, an .. "_end", nil, store.tick_ts, false, this.render.sid_mage)
						U.animation_start(this, "attack_1_gem_end", nil, store.tick_ts, false, this.render.sid_gem)
						U.animation_start(this, "attack_1_glow_end", nil, store.tick_ts, false, this.render.sid_tower_glow)
						destroy_gem_fx()
						S:stop(beam_attack.sfx_loop)
						S:queue(beam_attack.sfx_end)
					end

					last_ts = start_ts

					if not this.change_mode then
						if not did_overcharge then
							U.y_animation_play(this, "gem_break", nil, store.tick_ts, 1, this.render.sid_gem)

							gem_broken = true
						else
							did_overcharge = false
						end

						destroy_gem_glow()
						U.y_animation_play(this, "fragments", nil, store.tick_ts, 1, this.render.sid_gem)

						fragments = true

						if not this.change_mode then
							U.y_animation_play(this, "gem_form", nil, store.tick_ts, 1, this.render.sid_gem)

							gem_broken = false
							fragments = false

							U.animation_start(this, "idle_gem", nil, store.tick_ts, true, this.render.sid_gem, false)
							create_gem_glow()
						end
					end

					beam_attack.ts = store.tick_ts
					attacking = false
				end
			elseif store.tick_ts - rapid_fire_attack.ts > rapid_fire_attack.cooldown then
				local attacks
				local target, _, pred_pos = find_target()

				if not target or this.tower_upgrade_persistent_data.current_mode == MODE_BEAM then
					SU.delay_attack(store, rapid_fire_attack, fts(10))

					if fragments_up then
						U.animation_start(this, this.last_an .. "_end", nil, store.tick_ts, false, this.render.sid_mage)
						U.animation_start(this, "attack_2_end", nil, store.tick_ts, false, this.render.sid_gem)

						fragments_up = false
					end

					goto label_658_0
				end

				local an, _ = U.animation_name_facing_point(this, "attack_2", pred_pos, this.render.sid_mage)

				this.attacks._last_target_pos = pred_pos
				this.last_an = an

				if not fragments_up then
					U.animation_start(this, an .. "_start", nil, store.tick_ts, false, this.render.sid_mage)
					U.animation_start(this, "attack_2_start", nil, store.tick_ts, false, this.render.sid_gem)
					U.animation_start(this, "attack_2_start", nil, store.tick_ts, false, this.render.sid_tower_glow)

					fragments_up = true
				end

				while not U.animation_finished(this, this.render.sid_mage, 1) do
					check_conditions_animation()
					coroutine.yield()
				end

				if this.tower_upgrade_persistent_data.current_mode == MODE_BEAM then
					goto label_658_0
				end

				if not target or target.health.dead then
					SU.delay_attack(store, beam_attack, fts(10))
					U.animation_start(this, an .. "_end", nil, store.tick_ts, false, this.render.sid_mage)
					U.animation_start(this, "attack_2_end", nil, store.tick_ts, false, this.render.sid_gem)

					fragments_up = false

					goto label_658_0
				end

				attacking = true
				this.can_spawn_golem = false

				local start_ts = store.tick_ts
				local an, _, offset, bullet
				local random = math.random(0, 1)

				an, _ = U.animation_name_facing_point(this, "attack_2", this.attacks._last_target_pos, this.render.sid_mage)
				target, _, pred_pos = find_target()

				if not target then
					SU.delay_attack(store, rapid_fire_attack, fts(10))
				else
					this.attacks._last_target_pos = pred_pos

					if attk_index % 2 == 0 then
						an = an .. "_a"
					else
						an = an .. "_b"
					end

					attk_index = attk_index + 1
					shots = shots + 1

					U.animation_start(this, an, nil, store.tick_ts, false, this.render.sid_mage)
					U.animation_start(this, "attack_2_" .. map_animation_rapid_fire(an, random), nil, store.tick_ts, false, this.render.sid_gem)

					if this.powers and not rapid_fire_attack.skill_c_disabled and shots % rapid_fire_attack.skill_c_rate == 0 then
						U.animation_start(this, "exoburst", nil, store.tick_ts, false, this.render.sid_tower_glow)
					else
						U.animation_start(this, "attack_2", nil, store.tick_ts, false, this.render.sid_tower_glow)
					end

					offset = rapid_fire_attack.bullet_spawn_offsets[map_bullet_to_spawn_offset(an, random)]

					if rapid_fire_attack.spawn_fx then
						local sfx

						if this.powers and not rapid_fire_attack.skill_c_disabled and shots % rapid_fire_attack.skill_c_rate == 0 then
							sfx = E:create_entity(rapid_fire_attack.skill_c_spawn_fx)
						else
							sfx = E:create_entity(rapid_fire_attack.spawn_fx)
						end

						sfx.pos = V.v(this.pos.x + offset.x, this.pos.y + offset.y)
						sfx.render.sprites[1].ts = store.tick_ts

						local r = V.angleTo(target.pos.x - (this.pos.x + offset.x), target.pos.y - (this.pos.y + offset.y))

						sfx.render.sprites[1].r = r

						queue_insert(store, sfx)
					end

					if this.powers and not rapid_fire_attack.skill_c_disabled and shots % rapid_fire_attack.skill_c_rate == 0 then
						bullet = E:create_entity(rapid_fire_attack.skill_c_bullet)
						bullet.bullet.mod = rapid_fire_attack.skill_c_mod .. this.powers.skill_c.level
					else
						bullet = E:create_entity(rapid_fire_attack.bullet)
					end

					bullet.pos = V.v(this.pos.x + offset.x, this.pos.y + offset.y)
					bullet.bullet.from = V.vclone(bullet.pos)
					bullet.bullet.to = V.vclone(pred_pos)
					bullet.bullet.target_id = target.id
					bullet.bullet.source_id = this.id
					bullet.bullet.damage_factor = this.tower.damage_factor

					queue_insert(store, bullet)
				end

				attacking = false
				rapid_fire_attack.ts = store.tick_ts
				last_ts = start_ts
			end

			this.tower_upgrade_persistent_data.last_ts = last_ts

			if store.tick_ts - last_ts > this.tower.long_idle_cooldown then
				U.animation_start(this, "idle_1", false, store.tick_ts, -1, this.render.sid_mage)
			end

			coroutine.yield()
		end

		::label_658_0::

		this.can_spawn_golem = true
	end
end

function scripts.tower_sunray_master.remove(this, store)
	local beam = table.filter(store.entities, function(k, v)
		return v.template_name == "bullet_sunray_master_beam_lvl" .. this.tower.level and v.bullet and v.bullet.source_id == this.id
	end)
	local beam_decal = table.filter(store.entities, function(k, v)
		return v.template_name == "decal_sunray_master_beam_ground" and v.source_id and v.source_id == this.id
	end)
	local aura = table.filter(store.entities, function(k, v)
		return v.template_name == "aura_sunray_master_beam_lvl" .. this.tower.level and v.aura and v.aura.source_id == this.id
	end)

	if #beam > 0 then
		queue_remove(store, beam[1])
	end

	if #beam_decal > 0 then
		beam_decal[1].tween.disabled = false

		queue_remove(store, beam_decal[1])
	end

	if #aura > 0 then
		queue_remove(store, aura[1])
	end

	if this.decal_glow then
		queue_remove(store, this.decal_glow)
	end

	if this.controller_soldiers then
		queue_remove(store, this.controller_soldiers)
	end

	if this.gem_fx ~= nil then
		queue_remove(store, this.gem_fx)

		this.gem_fx = nil
	end

	return true
end

