scripts.controller_tower_sunray_master_soldiers = {}

function scripts.controller_tower_sunray_master_soldiers.update(this, store)
	local b = this.tower_ref.barrack
	local tower_id = this.tower_ref.id

	while true do
		if this.upgraded then
			this.upgraded = false

			local temp = E:get_template(b.soldier_prefix .. this.pow_level)

			for i = 1, #b.soldiers do
				local s = b.soldiers[i]

				s.health.hp_max = temp.health.hp_max
				s.health.hp = s.health.hp_max
				s.health.armor = temp.health.armor
				s.health.dead_lifetime = temp.health.dead_lifetime
				s.regen.health = temp.regen.health
				s.melee.attacks[1].damage_min = temp.melee.attacks[1].damage_min
				s.melee.attacks[1].damage_max = temp.melee.attacks[1].damage_max
			end
		end

		if not this.tower_ref.tower.blocked and this.tower_ref.can_spawn_golem then
			for i = 1, b.max_soldiers[this.pow_level] do
				local s = b.soldiers[i]

				if not s or s.health.dead and not store.entities[s.id] then
					this.tower_ref.spawn_golem_flag = true
					s = E:create_entity(b.soldier_prefix .. this.pow_level)
					s.soldier.tower_id = tower_id
					s.soldier.tower_soldier_idx = i
					s.nav_rally.pos, s.nav_rally.center = U.rally_formation_position(i, b, b.max_soldiers[this.pow_level], math.pi * 0.25)
					s.pos = V.vclone(s.nav_rally.pos)
					s.source_id = this.tower_ref.id

					queue_insert(store, s)

					b.soldiers[i] = s

					goto label_675_0
				end
			end
		end

		if b.rally_new then
			b.rally_new = false

			signal.emit("rally-point-changed", this)

			local all_dead = true

			for i, s in ipairs(b.soldiers) do
				s.nav_rally.pos, s.nav_rally.center = U.rally_formation_position(i, b, b.max_soldiers[this.pow_level], math.pi * 0.25)
				s.nav_rally.new = true
				all_dead = all_dead and s.health.dead
			end

			if not all_dead then
				S:queue(this.tower_ref.sound_events.change_rally_point)
			end
		end

		::label_675_0::

		coroutine.yield()
	end

	queue_remove(store, this)
end

function scripts.controller_tower_sunray_master_soldiers.remove(this, store)
	if this.tower_ref then
		local b = this.tower_ref.barrack

		for i = 1, b.max_soldiers[this.pow_level] do
			local s = b.soldiers[i]

			if s and store.entities[s.id] then
				s.health.dead = true

				queue_remove(store, s)
			end
		end
	end

	return true
end

scripts.tower_wildcat = {}

function scripts.tower_wildcat.update(this, store, script)
	local tower_sid = 2
	local door_sid = 3
	local sra_ts = store.tick_ts

	this.skill_c_ts = store.tick_ts

	local ult = this.powers and this.powers.ultimate.active and this.timed_attacks.list[1] or nil
	local ult_start_cd = ult ~= nil and store.wave_group_number == 0

	if ult then
		ult.ts = store.tick_ts
		this.controller_ult = E:create_entity(ult.controller)
		this.controller_ult.pos = tpos(this)
		this.controller_ult.info_tower = this

		queue_insert(store, this.controller_ult)
	end

	while true do
		if ult_start_cd and store.wave_group_number > 0 then
			ult_start_cd = false
			ult.ts = store.tick_ts
		end

		local b = this.barrack

		if this.powers then
			for pn, p in pairs(this.powers) do
				if p.changed then
					p.changed = nil

					for _, s in pairs(b.soldiers) do
						s.powers[pn].level = p.level
						s.powers[pn].changed = true
					end
				end
			end
		end

		if not this.tower.blocked then
			for i = 1, b.max_soldiers do
				local s = b.soldiers[i]

				if not s or s.health.dead and not store.entities[s.id] then
					if not b.door_open then
						S:queue("GUITowerOpenDoor")
						U.animation_start(this, "open", nil, store.tick_ts, 1, door_sid)

						while not U.animation_finished(this, door_sid) do
							coroutine.yield()
						end

						b.door_open = true
						b.door_open_ts = store.tick_ts
					end

					s = E:create_entity(b.soldier_type)
					s.soldier.tower_id = this.id
					s.soldier.tower_soldier_idx = i
					s.pos = V.v(V.add(this.pos.x, this.pos.y, b.respawn_offset.x, b.respawn_offset.y))
					s.nav_rally.pos, s.nav_rally.center = U.rally_formation_position(i, b, b.max_soldiers, b.rally_angle_offset)
					s.nav_rally.new = true

					if this.powers then
						for pn, p in pairs(this.powers) do
							s.powers[pn].level = p.level
						end
					end

					queue_insert(store, s)

					b.soldiers[i] = s

					signal.emit("tower-spawn", this, s)
				end
			end
		end

		if b.door_open and store.tick_ts - b.door_open_ts > b.door_hold_time then
			U.animation_start(this, "close", nil, store.tick_ts, 1, door_sid)

			while not U.animation_finished(this, door_sid) do
				coroutine.yield()
			end

			b.door_open = false
		end

		if b.rally_new then
			b.rally_new = false

			signal.emit("rally-point-changed", this)

			local all_dead = true

			for i, s in ipairs(b.soldiers) do
				s.nav_rally.pos, s.nav_rally.center = U.rally_formation_position(i, b, b.max_soldiers, b.rally_angle_offset)
				s.nav_rally.new = true
				s.nav_rally.delay_max = this.delay_max
				all_dead = all_dead and s.health.dead
			end

			if not all_dead then
				S:queue(this.sound_events.change_rally_point)
			end
		end

		if ult and store.tick_ts - ult.ts > ult.cooldown then
			local enemy, _, __ = U.find_foremost_enemy(store.entities, tpos(this), 0, ult.range, nil, nil, nil)

			if not enemy or enemy.health.dead then
				SU.delay_attack(store, ult, fts(5))
			else
				this.controller_ult.cast_ult = true
				this.controller_ult.enemy = enemy
				ult.ts = store.tick_ts

				signal.emit("tower-ultimate-used", this)
			end
		end

		coroutine.yield()
	end
end

function scripts.tower_wildcat.remove(this, store, script)
	for _, s in pairs(this.barrack.soldiers) do
		if s.health then
			s.health.dead = true
		end

		queue_remove(store, s)
	end

	if this.controller_ult ~= nil then
		queue_remove(store, this.controller_ult)
	end

	return true
end

scripts.soldier_wildcat = {}

function scripts.soldier_wildcat.insert(this, store)
	if scripts.soldier_barrack.insert(this, store) then
		if this.powers then
			for pn, p in pairs(this.powers) do
				if p.level > 0 then
					if p == this.powers.skill_a then
						this.timed_attacks.list[1].disabled = false
						this.timed_attacks.list[1].bullet = "bullet_wildcat_skill_a_lvl" .. p.level
						this.timed_attacks.list[1].cooldown = this.powers.skill_a.cooldown[p.level]
						this.timed_attacks.list[1].ts = store.tick_ts - this.timed_attacks.list[1].cooldown
					elseif p == this.powers.skill_b then
						this.timed_attacks.list[2].disabled = false
						this.timed_attacks.list[2].damage_min = this.powers.skill_b.damage_min[p.level]
						this.timed_attacks.list[2].damage_max = this.powers.skill_b.damage_max[p.level]
						this.timed_attacks.list[2].cooldown = this.powers.skill_b.cooldown[p.level]
					elseif p == this.powers.skill_c then
						this.timed_attacks.list[3].disabled = false
						this.timed_attacks.list[3].bullet = "bullet_wildcat_skill_c_lvl" .. p.level
						this.timed_attacks.list[3].cooldown = this.powers.skill_c.cooldown[p.level]
					end
				end
			end
		end

		if this.info and this.info.random_name_format then
			this.info.i18n_key = string.format(string.gsub(this.info.random_name_format, "_NAME", ""), math.random(this.info.random_name_count))
		end

		return true
	end

	return false
end

function scripts.soldier_wildcat.update(this, store, script)
	local brk, stam, star
	local r = this.nav_rally
	local sa = this.timed_attacks and this.timed_attacks.list[1]
	local sb = this.timed_attacks and this.timed_attacks.list[2]
	local sc = this.timed_attacks and this.timed_attacks.list[3]
	local sc_prediction_time
	local tower = store.entities[this.soldier.tower_id]

	this.can_cast = true

	if sa and not sa.disabled then
		sa.ts = store.tick_ts
	end

	if sb and not sb.disabled then
		sb.ts = store.tick_ts
	end

	if sc and not sc.disabled then
		sc.ts = store.tick_ts
		sc_prediction_time = E:get_template(sc.bullet).bullet.flight_time - fts(30)
	end

	if this.vis._bans then
		this.vis.bans = this.vis._bans
		this.vis._bans = nil
	end

	this.nav_rally._first_time = true

	local function walk_break_fn()
		return false
	end

	local tower_damage_factor = 1

	local function check_tower_damage_factor()
		if tower and tower.tower.damage_factor ~= tower_damage_factor then
			this.unit.damage_factor = this.unit.damage_factor / tower_damage_factor * tower.tower.damage_factor
			tower_damage_factor = tower.tower.damage_factor
		end
	end

	while true do
		if this.powers then
			for pn, p in pairs(this.powers) do
				if p.level > 0 then
					if p == this.powers.skill_a then
						this.timed_attacks.list[1].disabled = false
						this.timed_attacks.list[1].bullet = "bullet_wildcat_skill_a_lvl" .. p.level
						this.timed_attacks.list[1].cooldown = this.powers.skill_a.cooldown[p.level]
					elseif p == this.powers.skill_b then
						this.timed_attacks.list[2].disabled = false
						this.timed_attacks.list[2].damage_min = this.powers.skill_b.damage_min[p.level]
						this.timed_attacks.list[2].damage_max = this.powers.skill_b.damage_max[p.level]
						this.timed_attacks.list[2].cooldown = this.powers.skill_b.cooldown[p.level]
					elseif p == this.powers.skill_c then
						this.timed_attacks.list[3].disabled = false
						this.timed_attacks.list[3].bullet = "bullet_wildcat_skill_c_lvl" .. p.level
						this.timed_attacks.list[3].cooldown = this.powers.skill_c.cooldown[p.level]
					end
				end

				if p.changed then
					if p.level == 1 then
						if p == this.powers.skill_a then
							sa.ts = store.tick_ts - sa.cooldown
						elseif p == this.powers.skill_b then
							sb.ts = store.tick_ts - sb.cooldown
						elseif p == this.powers.skill_c then
							sc.ts = store.tick_ts - sc.cooldown

							if tower.skill_c_ts then
								tower.skill_c_ts = store.tick_ts - sc.cooldown
							end

							sc_prediction_time = E:get_template(sc.bullet).bullet.flight_time - fts(30)
						end
					end

					p.changed = nil
				end
			end
		end

		if this.health.dead then
			this.ui.can_click = false

			SU.y_soldier_death(store, this)

			return
		end

		if this.unit.is_stunned then
			SU.soldier_idle(store, this)
		else
			while this.nav_rally.new do
				if SU.y_soldier_new_rally(store, this) then
					goto label_680_1
				end
			end

			check_tower_damage_factor()

			if sa and not sa.disabled and store.tick_ts - sa.ts >= sa.cooldown then
				local target, _, pred_pos = U.find_foremost_enemy(store.entities, this.pos, sa.min_range, sa.max_range, sa.node_prediction, sa.vis_flags, sa.vis_bans, nil, F_FLYING)

				if not pred_pos then
					SU.delay_attack(store, sa, fts(5))
				else
					local attack_done = SU.y_soldier_do_ranged_attack(store, this, target, sa, target.pos)

					if attack_done then
						sa.ts = store.tick_ts
					end
				end
			end

			if sb and not sb.disabled and store.tick_ts - sb.ts >= sb.cooldown and this.soldier.target_id ~= nil then
				local target = store.entities[this.soldier.target_id]

				if target and not SU.soldier_move_to_slot_step(store, this, target) then
					local attack_done = SU.y_soldier_do_single_melee_attack(store, this, target, sb)

					if attack_done then
						sb.ts = store.tick_ts
					end
				end
			end

			if sc and not sc.disabled and tower.skill_c_ts and store.tick_ts - tower.skill_c_ts > sc.cooldown then
				local enemy, enemies, pred_pos = U.find_foremost_enemy(store.entities, this.pos, sc.min_range, sc.max_range, sc_prediction_time, sc.vis_flags, sc.vis_bans, function(e, o)
					if store.level.ignore_walk_backwards_paths and table.contains(store.level.ignore_walk_backwards_paths, e.nav_path.pi) then
						return false
					end

					return true
				end)

				if not enemies or #enemies < sc.min_targets then
					SU.delay_attack(store, sc, fts(10))
				else
					tower.skill_c_ts = store.tick_ts

					local enemy, enemies, pred_pos = U.find_foremost_enemy(store.entities, this.pos, sc.min_range, sc.max_range * 1.2, sc_prediction_time, sc.vis_flags, sc.vis_bans)
					local average_x = 0
					local average_y = 0

					for _, v in pairs(enemies) do
						if v.__ffe_pos then
							average_x = average_x + v.__ffe_pos.x
							average_y = average_y + v.__ffe_pos.y
						else
							local node_offset = P:predict_enemy_node_advance(v, sc_prediction_time)
							local e_ni = v.nav_path.ni + node_offset
							local v_pos = P:node_pos(v.nav_path.pi, v.nav_path.spi, e_ni)

							average_x = average_x + v_pos.x
							average_y = average_y + v_pos.y
						end
					end

					local shoot_pos = v(average_x / #enemies, average_y / #enemies)
					local flip = enemy.pos.x < this.pos.x

					U.animation_start(this, sc.animation, flip, store.tick_ts, false, 1)
					U.y_wait(store, sc.cast_time)

					local bullet = E:create_entity(sc.bullet)

					bullet.pos = V.vclone(this.pos)

					if sc.bullet_start_offset then
						local offset = sc.bullet_start_offset[1]

						bullet.pos.x, bullet.pos.y = bullet.pos.x + (this.render.sprites[1].flip_x and -1 or 1) * offset.x, bullet.pos.y + offset.y
					end

					bullet.bullet.from = V.vclone(bullet.pos)
					bullet.bullet.to = shoot_pos
					bullet.bullet.target_id = enemies[1].id
					bullet.enemies = enemies
					bullet.default_pi = enemies[1].nav_path.pi

					queue_insert(store, bullet)
					S:queue(sc.sound)

					while not U.animation_finished(this, 1) do
						coroutine.yield()
					end
				end
			end

			if this.melee then
				brk, stam = SU.y_soldier_melee_block_and_attacks(store, this)

				if brk or stam == A_DONE or stam == A_IN_COOLDOWN and not this.melee.continue_in_cooldown then
					goto label_680_1
				end
			end

			if this.ranged then
				brk, star = SU.y_soldier_ranged_attacks(store, this)

				if brk or star == A_DONE then
					goto label_680_1
				elseif star == A_IN_COOLDOWN then
					goto label_680_0
				end
			end

			if SU.soldier_go_back_step(store, this) then
				goto label_680_1
			end

			::label_680_0::

			SU.soldier_idle(store, this)
			SU.soldier_regen(store, this)
		end

		::label_680_1::

		coroutine.yield()
	end
end

scripts.bullet_skill_a_wildcat = {}

function scripts.bullet_skill_a_wildcat.update(this, store)
	local b = this.bullet
	local target, ps

	this.bounces = 0

	local already_hit = {}
	local tower = store.entities[b.source_id]
	local skill_level
	local bounce_damage = -1

	b.speed.x, b.speed.y = V.normalize(b.to.x - b.from.x, b.to.y - b.from.y)

	if b.particles_name then
		ps = E:create_entity(b.particles_name)
		ps.particle_system.track_id = this.id

		queue_insert(store, ps)
	end

	if b.damage_min_config then
		skill_level = tower.powers.skill_gold.level
		b.damage_min = b.damage_min_config[skill_level]
		b.damage_max = b.damage_max_config[skill_level]
	end

	::label_684_0::

	while V.dist2(this.pos.x, this.pos.y, b.to.x, b.to.y) > b.fixed_speed * store.tick_length * (b.fixed_speed * store.tick_length) do
		target = store.entities[b.target_id]

		if target and target.health and not target.health.dead then
			b.to.x, b.to.y = target.pos.x + target.unit.hit_offset.x, target.pos.y + target.unit.hit_offset.y
		end

		b.speed.x, b.speed.y = V.mul(b.fixed_speed, V.normalize(b.to.x - this.pos.x, b.to.y - this.pos.y))
		this.pos.x, this.pos.y = this.pos.x + b.speed.x * store.tick_length, this.pos.y + b.speed.y * store.tick_length
		this.render.sprites[1].r = V.angleTo(b.to.x - this.pos.x, b.to.y - this.pos.y)

		coroutine.yield()
	end

	local will_kill

	if target and not target.health.dead then
		local d = SU.create_bullet_damage(b, target.id, this.id)

		if bounce_damage == -1 then
			bounce_damage = d.value
		else
			d.value = bounce_damage
		end

		queue_damage(store, d)

		will_kill = U.predict_damage(target, d) >= target.health.hp

		table.insert(already_hit, target.id)
		S:queue(this.sound_hit)
	end

	if this.gold_chance and will_kill then
		local stole_gold = math.random(0, 100) <= this.gold_chance * 100

		if stole_gold then
			local sfx = E:create_entity(b.hit_fx_coins)

			sfx.pos = V.vclone(b.to)
			sfx.render.sprites[1].ts = store.tick_ts

			queue_insert(store, sfx)

			local gold_pos = V.v(sfx.pos.x, sfx.pos.y)

			signal.emit("got-gold", gold_pos, this.gold_extra[skill_level])
		end
	end

	if b.hit_fx then
		local sfx = E:create_entity(b.hit_fx)

		sfx.pos = V.vclone(b.to)
		sfx.render.sprites[1].ts = store.tick_ts

		queue_insert(store, sfx)
	end

	S:queue(this.sound)

	if this.bounces < this.max_bounces then
		local targets = U.find_enemies_in_range(store.entities, this.pos, 0, this.bounce_range, b.vis_flags, b.vis_bans, function(v)
			return not table.contains(already_hit, v.id)
		end)

		if not targets then
			if target and not target.health.dead then
				already_hit = {
					target.id
				}
			else
				already_hit = {}
			end

			targets = U.find_enemies_in_range(store.entities, this.pos, 0, this.bounce_range, b.vis_flags, b.vis_bans, function(v)
				return not table.contains(already_hit, v.id)
			end)
		end

		if targets then
			table.sort(targets, function(e1, e2)
				return V.dist2(this.pos.x, this.pos.y, e1.pos.x, e1.pos.y) < V.dist2(this.pos.x, this.pos.y, e2.pos.x, e2.pos.y)
			end)

			local target = targets[1]

			this.bounces = this.bounces + 1
			b.to.x, b.to.y = target.pos.x + target.unit.hit_offset.x, target.pos.y + target.unit.hit_offset.y
			b.target_id = target.id
			b.fixed_speed = b.fixed_speed * this.bounce_speed_mult
			b.damage_min = bounce_damage * this.bounce_damage_mult
			b.damage_max = bounce_damage * this.bounce_damage_mult
			bounce_damage = bounce_damage * this.bounce_damage_mult

			goto label_684_0
		end
	end

	queue_remove(store, this)
end

scripts.bullet_skill_c_wildcat = {}

function scripts.bullet_skill_c_wildcat.update(this, store)
	local b = this.bullet
	local s = this.render.sprites[1]
	local bullet_fly = true
	local ps
	local start_x = this.pos.x

	local function spawn_arrows()
		local targets = table.filter(this.enemies, function(k, v)
			local vpi = v and v.nav_path.pi or nil

			if store.level.ignore_walk_backwards_paths and table.contains(store.level.ignore_walk_backwards_paths, vpi) or not P:is_path_active(vpi) or not v or v and v.health and v.health.dead then
				return false
			end

			return true
		end)
		local path = targets[1] and targets[1].nav_path.pi or this.default_pi

		local function spawn_arrow(pi, spi, ni)
			local pos = P:node_pos(pi, spi, ni)

			pos.x = pos.x + math.random(-4, 4)
			pos.y = pos.y + math.random(-5, 5)

			local s = E:create_entity(this.arrow_t)

			s.pos = V.vclone(this.pos)
			s.to = pos

			queue_insert(store, s)
		end

		local nearest = P:nearest_nodes(this.bullet.to.x, this.bullet.to.y, {
			path
		})

		if #nearest > 0 then
			local pi, spi, ni = unpack(nearest[1])
			local flip = this.pos.x > start_x
			local initial_offset = 1

			ni = ni - initial_offset

			local ni_aux
			local arrow_id = 1

			for i = 1, this.arrow_count do
				if i == 1 then
					spawn_arrow(pi, 1, ni)
					spawn_arrow(pi, 1, ni)
				else
					ni_aux = ni - i * this.nodes_between_arrows

					if P:is_node_valid(pi, ni_aux) then
						spawn_arrow(pi, math.random(3), ni_aux)
					end

					ni_aux = ni + i * (this.nodes_between_arrows + 1)

					if P:is_node_valid(pi, ni_aux) then
						spawn_arrow(pi, math.random(3), ni_aux)
					end
				end

				U.y_wait(store, fts(1))
			end
		end
	end

	local function position_in_parabola(t, from, speed, g)
		local x = speed.x * t + from.x
		local y = g * t * t / 2 + speed.y * t + from.y
		local max = -speed.y / g

		return x, y, max
	end

	if b.particles_name then
		ps = E:create_entity(b.particles_name)
		ps.particle_system.track_id = this.id

		queue_insert(store, ps)
	end

	local ts = store.tick_ts

	while bullet_fly do
		coroutine.yield()

		b.last_pos.x, b.last_pos.y = this.pos.x, this.pos.y
		this.pos.x, this.pos.y = SU.position_in_parabola(store.tick_ts - b.ts, b.from, b.speed, b.g)

		if b.rotation_speed then
			s.r = s.r + b.rotation_speed * store.tick_length
		else
			s.r = V.angleTo(this.pos.x - b.last_pos.x, this.pos.y - b.last_pos.y)

			if b.asymmetrical and math.abs(s.r) > math.pi / 2 then
				s.flip_y = true
			end
		end

		if ps then
			ps.particle_system.emit_direction = s.r
		end

		if b.hide_radius then
			local at_start = V.dist(this.pos.x, this.pos.y, b.from.x, b.from.y) < b.hide_radius
			local at_end = V.dist(this.pos.x, this.pos.y, b.to.x, b.to.y) < b.hide_radius

			s.hidden = at_start or at_end

			if ps then
				if b.extend_particles_cutoff then
					ps.particle_system.emit = not at_start
				else
					ps.particle_system.emit = not s.hidden
				end
			end
		end

		if store.tick_ts - ts > b.flight_time / 2 then
			bullet_fly = false
		end
	end

	if b.hit_fx then
		local fx = E:create_entity(b.hit_fx)

		fx.pos = V.vclone(this.pos)
		fx.render.sprites[1].ts = store.tick_ts

		queue_insert(store, fx)
	end

	this.render.sprites[1].hidden = true

	spawn_arrows()
	queue_remove(store, ps)
	queue_remove(store, this)
end

scripts.bullet_skill_c_wildcat_arrows = {}

function scripts.bullet_skill_c_wildcat_arrows.insert(this, store, script)
	this.render.sprites[1].ts = store.tick_ts

	return true
end

function scripts.bullet_skill_c_wildcat_arrows.update(this, store, script)
	local s = this.render.sprites[1]
	local flip_x = this.pos.x > this.to.x
	local mspeed = this.min_speed

	this.speed = {}
	s.r = V.angleTo(this.pos.x - this.to.x, this.pos.y - this.to.y) + math.pi

	while V.dist2(this.pos.x, this.pos.y, this.to.x, this.to.y) > mspeed * store.tick_length * mspeed * store.tick_length do
		coroutine.yield()

		mspeed = mspeed + FPS * math.ceil(mspeed * (1 / FPS) * this.acceleration_factor)
		mspeed = km.clamp(this.min_speed, this.max_speed, mspeed)
		this.speed.x, this.speed.y = V.mul(mspeed, V.normalize(this.to.x - this.pos.x, this.to.y - this.pos.y))
		this.pos.x, this.pos.y = this.pos.x + this.speed.x * store.tick_length, this.pos.y + this.speed.y * store.tick_length
	end

	local enemies = U.find_enemies_in_range(store.entities, this.pos, 0, this.damage_radius, this.vis_flags, this.vis_bans)

	if enemies and #enemies > 0 then
		for i = 1, #enemies do
			local d = E:create_entity("damage")

			d.damage_type = this.damage_type
			d.value = math.random(this.damage_min, this.damage_max)
			d.source_id = this.id
			d.target_id = enemies[i].id

			queue_damage(store, d)
		end
	end

	S:queue(this.sound)

	s.r = 0
	s.prefix = "wildcat_huntresses_tower_raining_arrows_floor"
	s.z = Z_DECALS
	s.flip_x = flip_x

	U.y_animation_play(this, "run", nil, store.tick_ts, 1, 1)
	U.y_wait(store, fts(30))
	queue_remove(store, this)
end

scripts.decal_wildcat_ult_panther = {}

function scripts.decal_wildcat_ult_panther.update(this, store, script)
	S:queue(this.sound, {
		delay = fts(7)
	})
	U.y_wait(store, this.hit_time)

	local hit_fx = E:create_entity(this.hit_fx)
	local flip = this.render.sprites[1].flip_x and -1 or 1

	hit_fx.pos = v(this.pos.x + this.hit_offset.x * flip, this.pos.y + this.hit_offset.y)
	hit_fx.render.sprites[1].ts = store.tick_ts

	queue_insert(store, hit_fx)

	local d = E:create_entity("damage")

	d.source_id = this.source_id
	d.target_id = this.enemy_id
	d.damage_type = this.damage_type

	local vmin = this.damage_min * this.damage_factor
	local vmax = this.damage_max * this.damage_factor
	local value = math.ceil(U.frandom(vmin, vmax))

	d.value = value

	queue_damage(store, d)

	while not U.animation_finished(this, 1) do
		coroutine.yield()
	end

	queue_remove(store, this)
end

scripts.controller_wildcat_ult = {}

function scripts.controller_wildcat_ult.update(this, store, script)
	local ult_duration = fts(41) + (this.attacks - 1) * this.wait_time

	while true do
		if this.cast_ult and this.enemy ~= nil and not this.enemy.health.dead then
			local elf = E:create_entity(this.decal_elf)

			elf.pos = v(tpos(this).x + this.elf_offset.x, tpos(this).y + this.elf_offset.y)
			elf.render.sprites[1].ts = store.tick_ts

			queue_insert(store, elf)
			S:queue(this.sound)
			U.y_wait(store, this.cast_time)

			if this.enemy.health.dead then
				-- block empty
			else
				local mod = E:create_entity(this.mod)

				mod.modifier.ts = store.tick_ts
				mod.modifier.target_id = this.enemy.id
				mod.modifier.source_id = this.source_id
				mod.modifier.duration = ult_duration

				queue_insert(store, mod)

				local target = E:create_entity(this.decal_target)

				target.pos = this.enemy.pos
				target.render.sprites[1].ts = store.tick_ts
				target.render.sprites[1].loop = true
				target.duration = ult_duration

				queue_insert(store, target)

				for i = 1, this.attacks do
					if this.enemy.health.dead then
						break
					end

					local side = i % 2 == 0
					local panther = E:create_entity(this.decal_panther)

					panther.pos = v(side and this.enemy.pos.x + this.enemy.enemy.melee_slot.x or this.enemy.pos.x - this.enemy.enemy.melee_slot.x, this.enemy.pos.y + this.enemy.enemy.melee_slot.y + math.random(-5, 5))
					panther.render.sprites[1].ts = store.tick_ts
					panther.render.sprites[1].flip_x = side
					panther.enemy_id = this.enemy.id
					panther.source_id = this.id
					panther.damage_factor = this.info_tower.tower.damage_factor

					queue_insert(store, panther)
					U.y_wait(store, this.wait_time)
				end
			end
		end

		this.enemy = nil
		this.cast_ult = false

		coroutine.yield()
	end
end

