scripts.tower_light_priestess = {}

function scripts.tower_mage.get_info(this)
	local info = scripts.tower_common.get_info(this)
	local bullet = E:get_template(this.attacks.list[1].bullet)

	info.damage_min = bullet.bullet.damage_min * this.tower.damage_factor
	info.damage_max = bullet.bullet.damage_max * this.tower.damage_factor
	info.cooldown = this.attacks.list[1].cooldown
	info.type = STATS_TYPE_TOWER_MAGE
	info.range = this.attacks.range

	return info
end

function scripts.tower_light_priestess.update(this, store)
	local range = this.attacks.range
	local a = this.attacks.list[1]
	local sa = this.timed_attacks and this.timed_attacks.list[1] or nil
	local sb = this.timed_attacks and this.timed_attacks.list[2] or nil
	local sc = this.timed_attacks and this.timed_attacks.list[3] or nil
	local ult = this.timed_attacks and this.timed_attacks.list[4] or nil
	local ult_start_cd = ult ~= nil and store.wave_group_number == 0
	local pow_a = this.powers and this.powers.skill_a or nil
	local pow_b = this.powers and this.powers.skill_b or nil
	local pow_c = this.powers and this.powers.skill_c or nil
	local last_ts = store.tick_ts

	a.ts = store.tick_ts - a.cooldown

	if ult and this.powers.ultimate.active then
		ult.ts = store.tick_ts
	end

	local function find_ally_damaged(aa, vis_flags, vis_bans)
		local soldiers = U.find_soldiers_in_range(store.entities, tpos(this), 0, aa.aura_range, vis_flags, vis_bans, function(e, _)
			return e.health and e.health.hp < e.health.hp_max and e.health.hp / e.health.hp_max <= aa.threshold
		end)

		if soldiers and #soldiers > 0 then
			local _, surrounded_soldiers = U.find_entity_most_surrounded(soldiers)

			for _, soldier in ipairs(surrounded_soldiers) do
				local enemies_melee = U.find_enemies_in_range(store.entities, soldier.pos, 0, aa.aura_range, vis_flags, vis_bans)

				if enemies_melee and #enemies_melee > 0 then
					return soldier
				end
			end

			return surrounded_soldiers[1]
		end

		return nil
	end

	if this.passive_aura then
		this.passive_aura_instance = E:create_entity(this.passive_aura)
		this.passive_aura_instance.pos = V.vclone(tpos(this))

		queue_insert(store, this.passive_aura_instance)
	end

	while true do
		if ult_start_cd and store.wave_group_number > 0 then
			ult_start_cd = false
			ult.ts = store.tick_ts
		end

		if this.passive_aura_instance then
			this.passive_aura_instance.aura.radius = this.attacks.range
		end

		if this.tower.blocked then
			coroutine.yield()
		else
			if this.powers then
				for k, pow in pairs(this.powers) do
					if pow.changed then
						pow.changed = nil

						if pow == pow_a then
							sa.cooldown = pow.cooldown[pow.level]
							sa.disabled = false
							E:get_template(sa.decal).aura = "aura_light_priestess_skill_a_lvl" .. pow.level
							sa.threshold = pow.threshold[pow.level]

							if pow.level == 1 then
								sa.ts = store.tick_ts - sa.cooldown
							end
						end

						if pow == pow_b then
							sb.cooldown = pow.cooldown[pow.level]
							sb.disabled = false
							sb.aura = "aura_light_priestess_skill_b_lvl" .. pow.level

							if pow.level == 1 then
								sb.ts = store.tick_ts - sb.cooldown
							end
						end

						if pow == pow_c then
							sc.cooldown = pow.cooldown[pow.level]
							sc.disabled = false
							sc.mod = "mod_light_priestess_skill_c_lvl" .. pow.level
							sc.detection_range = pow.detection_range[pow.level]

							if pow.level == 1 then
								sc.ts = store.tick_ts - sc.cooldown
							end
						end
					end
				end
			end

			if store.tick_ts - a.ts > a.cooldown then
				local attacks
				local target, _, pred_pos = U.find_foremost_enemy(store.entities, tpos(this), 0, range, 0, this.vis_flags, this.vis_bans)

				if not target then
					SU.delay_attack(store, a, fts(5))

					goto label_699_1
				end

				this.attacks._last_target_pos = pred_pos

				local an, _ = U.animation_name_facing_point(this, "attack", target.pos, this.sid_priestess)

				U.animation_start(this, an, nil, store.tick_ts, false, this.sid_priestess)

				if not target or target.health.dead then
					SU.delay_attack(store, a, fts(5))

					goto label_699_1
				end

				U.y_wait(store, a.shoot_time)
				S:queue(a.sound)

				local b = E:create_entity(a.bullet)

				b.bullet.damage_factor = this.tower.damage_factor
				b.pos.x, b.pos.y = tpos(this).x + a.bullet_start_offset[an].x, tpos(this).y + a.bullet_start_offset[an].y
				b.bullet.from = v(tpos(this).x + a.bullet_start_offset[an].x, tpos(this).y + a.bullet_start_offset[an].y)
				b.bullet.to = V.vclone(pred_pos)
				b.bullet.source_id = this.id
				b.bullet.target_id = target.id

				queue_insert(store, b)

				a.ts = store.tick_ts
				last_ts = store.tick_ts
			end

			if sa and not sa.disabled and store.tick_ts - sa.ts > sa.cooldown then
				local ally = find_ally_damaged(sa, sa.vis_flags, sa.vis_bans)

				if not ally then
					SU.delay_attack(store, sa, fts(5))

					goto label_699_1
				end

				local an, _ = U.animation_name_facing_point(this, "skill_a", ally.pos, this.sid_priestess)

				U.animation_start(this, an, nil, store.tick_ts, false, this.sid_priestess)
				U.y_wait(store, sa.hit_time)
				S:queue(sa.sound)

				local decal = E:create_entity(sa.decal)

				decal.pos = ally.pos
				decal.render.sprites[1].ts = store.tick_ts

				queue_insert(store, decal)

