			end

			if sb and not sb.disabled and store.tick_ts - sb.ts > sb.cooldown then
				local enemies = U.find_enemies_in_range(store.entities, tpos(this), 0, sb.range, sb.vis_flags, sb.vis_bans)

				if not enemies or #enemies == 0 or #enemies < sb.min_targets then
