				queue_insert(store, decal)

				local bell = E:create_entity(sb.decal_bell)

				bell.pos = v(tpos(this).x + sb.bell_offset.x, tpos(this).y + sb.bell_offset.y)

				for i = 1, #bell.render.sprites do
					bell.render.sprites[i].ts = store.tick_ts
				end

				this.sb_bell = bell

				queue_insert(store, bell)

				while not U.animation_finished(this, this.sid_priestess) do
					coroutine.yield()
				end

				sb.ts = store.tick_ts
				last_ts = store.tick_ts
			end

			if sc and not sc.disabled and store.tick_ts - sc.ts > sc.cooldown then
				local enemies = U.find_enemies_in_range(store.entities, tpos(this), 0, sc.detection_range, 0, 0)

				if not enemies or #enemies == 0 then
					SU.delay_attack(store, sc, fts(5))

					goto label_699_1
				end

				local towers = U.find_towers(store.entities, tpos(this), 0, sc.range, function(v, o)
					return v.id ~= this.id and v.tower.can_be_mod and (not sc.excluded_templates or not table.contains(sc.excluded_templates, v.template_name))
				end)

				if not towers or #towers == 0 then
					SU.delay_attack(store, sc, fts(5))

					goto label_699_1
				end

				table.sort(towers, function(e1, e2)
					return V.dist(tpos(e1).x, tpos(e1).y, enemies[1].pos.x, enemies[1].pos.y) < V.dist(tpos(e2).x, tpos(e2).y, enemies[1].pos.x, enemies[1].pos.y)
				end)

				local tower_index = 1

