						break
					end
				end

				local an, _ = U.animation_name_facing_point(this, "skill_c", tpos(towers[1]), this.sid_priestess)

				U.animation_start(this, an, nil, store.tick_ts, false, this.sid_priestess)
				U.y_wait(store, sc.hit_time)
				S:queue(sc.sound)

				local m = E:create_entity(sc.mod)

				m.modifier.source_id = this.id
				m.modifier.target_id = towers[tower_index].id

				queue_insert(store, m)

