				queue_insert(store, decal)

				while not U.animation_finished(this, this.sid_priestess) do
					coroutine.yield()
				end

				sc.ts = store.tick_ts
				last_ts = store.tick_ts
			end

			if ult and this.powers.ultimate.active and store.tick_ts - ult.ts > ult.cooldown then
				local target, _, pred_pos = U.find_foremost_enemy(store.entities, tpos(this), 0, ult.range, 0, ult.vis_flags, ult.vis_bans)

				if not target then
					SU.delay_attack(store, ult, fts(5))

					goto label_699_1
				end

				local an, _ = U.animation_name_facing_point(this, "ult", target.pos, this.sid_priestess)

				S:queue(ult.sound)
				U.y_animation_play(this, "ulti_in" .. an, nil, store.tick_ts, 1, this.sid_priestess)

				local target, _, pred_pos = U.find_foremost_enemy(store.entities, tpos(this), 0, ult.range, 0, ult.vis_flags, ult.vis_bans)

				if not target then
					U.y_animation_play(this, "ulti_out" .. an, nil, store.tick_ts, 1, this.sid_priestess)
					SU.delay_attack(store, ult, fts(5))

					goto label_699_1
				end

				local an, _ = U.animation_name_facing_point(this, "ult", target.pos, this.sid_priestess)

				if not target then
					U.y_animation_play(this, "ulti_out" .. an, nil, store.tick_ts, 1, this.sid_priestess)
					SU.delay_attack(store, ult, fts(5))

					goto label_699_1
				end

				U.animation_start(this, "ulti_loop" .. an, nil, store.tick_ts, true, this.sid_priestess)

				local start_ts = store.tick_ts
				local aura = E:create_entity(ult.aura)

				aura.pos = V.vclone(tpos(this))
				this.tower_upgrade_persistent_data.ult_aura = aura

				queue_insert(store, aura)

				::label_699_0::

				local bullet = E:create_entity(ult.bullet)
				local pos_x, pos_y = tpos(this).x + ult.offset.x, tpos(this).y + ult.offset.y

				bullet.pos = V.v(pos_x, pos_y)
				bullet.bullet.from = V.vclone(bullet.pos)
				bullet.bullet.to = V.vclone(target.pos)
				bullet.bullet.target_id = target.id
				bullet.bullet.source_id = this.id
				bullet.bullet.damage_factor = this.tower.damage_factor
				bullet.bullet.max_track_distance = ult.range
				this.tower_upgrade_persistent_data.ult_bullet = bullet

				queue_insert(store, bullet)

				while store.tick_ts - start_ts < ult.duration do
					if target.pos.y > tpos(this).y + ult.offset.y then
						bullet.render.sprites[1].z = Z_OBJECTS_COVERS
					end

					if this.tower.blocked then
						break
					end

					if not target or target.health.dead or band(target.vis.bans, ult.vis_flags) ~= 0 or band(target.vis.flags, ult.vis_bans) ~= 0 then
						target, _, pred_pos = U.find_foremost_enemy(store.entities, tpos(this), 0, ult.range, 0, ult.vis_flags, ult.vis_bans)

						if not target then
							break
						end

						queue_remove(store, this.tower_upgrade_persistent_data.ult_bullet)

						this.tower_upgrade_persistent_data.ult_bullet = nil
						an, _ = U.animation_name_facing_point(this, "ult", target.pos, this.sid_priestess)

						U.animation_start(this, "ulti_loop" .. an, nil, store.tick_ts, true, this.sid_priestess)

						goto label_699_0
					end

					coroutine.yield()
				end

				if this.tower_upgrade_persistent_data.ult_bullet ~= nil then
					queue_remove(store, this.tower_upgrade_persistent_data.ult_bullet)

					this.tower_upgrade_persistent_data.ult_bullet = nil
				end

				if this.tower_upgrade_persistent_data.ult_aura ~= nil then
					queue_remove(store, this.tower_upgrade_persistent_data.ult_aura)

					this.tower_upgrade_persistent_data.ult_aura = nil
				end

				U.y_animation_play(this, "ulti_out" .. an, nil, store.tick_ts, 1, this.sid_priestess)

				ult.ts = store.tick_ts

				signal.emit("tower-ultimate-used", this)

				last_ts = store.tick_ts
			end

			if store.tick_ts - last_ts > this.tower.long_idle_cooldown then
				U.animation_start(this, "idle", nil, store.tick_ts, true, this.sid_priestess)
			end
		end

		::label_699_1::

		coroutine.yield()
	end
end

function scripts.tower_light_priestess.remove(this, store)
	if this.tower_upgrade_persistent_data.ult_bullet ~= nil then
		queue_remove(store, this.tower_upgrade_persistent_data.ult_bullet)

		this.tower_upgrade_persistent_data.ult_bullet = nil
	end

	if this.tower_upgrade_persistent_data.ult_aura ~= nil then
		queue_remove(store, this.tower_upgrade_persistent_data.ult_aura)

		this.tower_upgrade_persistent_data.ult_aura = nil
	end

	if this.passive_aura_instance ~= nil then
		queue_remove(store, this.passive_aura_instance)

		this.passive_aura_instance = nil
	end

	if this.sb_aura ~= nil then
		queue_remove(store, this.sb_aura)

		this.sb_aura = nil
	end

	if this.sb_decal ~= nil then
		queue_remove(store, this.sb_decal)

		this.sb_decal = nil
	end

	if this.sb_bell ~= nil then
		queue_remove(store, this.sb_bell)

		this.sb_bell = nil
	end

	if this.sc_decal ~= nil then
		queue_remove(store, this.sc_decal)

		this.sc_decal = nil
	end

	return true
end

scripts.mod_armor_inc_light_priestess = {}

function scripts.mod_armor_inc_light_priestess.insert(this, store, script)
	local target = store.entities[this.modifier.target_id]

	if not target or target.health.dead then
		return false
	end

	if band(this.modifier.vis_flags, target.vis.bans) ~= 0 or band(this.modifier.vis_bans, target.vis.flags) ~= 0 then
		log.paranoid("mod %s cannot be applied to entity %s:%s because of vis flags/bans", this.template_name, target.id, target.template_name)

		return false
	end

	SU.armor_inc(target, this.armor_inc)
	SU.magic_armor_inc(target, this.armor_inc)
	signal.emit("mod-applied", this, target)

	local s = this.render.sprites[1]

	if target and target.unit and this.render then
		if s.prefix_names then
			s.prefix = s.prefix_names[target.unit.size]

			if target.unit.size == UNIT_SIZE_LARGE then
				s.scale = V.vv(1.5)
			end
		end

		U.animation_start(this, "in", nil, store.tick_ts, false, 1, true)
	end

	if this.passive then
		this.render.sprites[1].prefix = "light_priestess_FX_passive_decal"

		if this.shield_decal and target.health_bar then
			this.shield = E:create_entity(this.shield_decal)
			this.shield.pos = target.pos
			this.shield.render.sprites[1].offset = v(0, target.health_bar.offset.y + 10)

			queue_insert(store, this.shield)
			U.animation_start(this.shield, "in", nil, store.tick_ts, false, 1, true)
		end
	end

	return true
end

function scripts.mod_armor_inc_light_priestess.update(this, store, script)
	local m = this.modifier
	local target = store.entities[m.target_id]

	if not target then
		queue_remove(store, this)

		return
	end

	this.pos = target.pos

	while not U.animation_finished(this, 1) or this.shield and not U.animation_finished(this.shield, 1) do
		coroutine.yield()
	end

	U.animation_start(this, "idle", nil, store.tick_ts, true, 1)

	if this.shield then
		U.animation_start(this.shield, "Idle", nil, store.tick_ts, true, 1)
	end

	while true do
		target = store.entities[m.target_id]

		if not target or target.health.dead or store.tick_ts - m.ts >= m.duration then
			if this.shield then
				U.animation_start(this.shield, "out", nil, store.tick_ts, false, 1)
			end

			U.y_animation_play(this, "out", nil, store.tick_ts, 1, 1)
			queue_remove(store, this)

			return
		end

		if this.render and m.use_mod_offset and target.unit.mod_offset and band(target.vis.flags, F_FLYING) ~= 0 then
			for i = 1, #this.render.sprites do
				local s = this.render.sprites[i]

				if not s.exclude_mod_offset then
					s.offset.x, s.offset.y = target.unit.mod_offset.x, target.unit.mod_offset.y
				end
			end
		end

		coroutine.yield()
	end
end

function scripts.mod_armor_inc_light_priestess.remove(this, store, script)
	local target = store.entities[this.modifier.target_id]

	if target then
		SU.armor_dec(target, this.armor_inc)
		SU.magic_armor_dec(target, this.armor_inc)
	end

	if this.shield then
		queue_remove(store, this.shield)

		this.shield = nil
	end

	return true
end

scripts.decal_light_priestess_skill_a = {}

function scripts.decal_light_priestess_skill_a.update(this, store, script)
	U.y_wait(store, this.hit_time)

	local hit = E:create_entity(this.hit_decal)

	hit.pos = V.vclone(this.pos)
	hit.render.sprites[1].ts = store.tick_ts

	queue_insert(store, hit)

	local aura = E:create_entity(this.aura)

	aura.pos = V.vclone(this.pos)

	queue_insert(store, aura)
	U.y_animation_wait(this, 1, 1)
	queue_remove(store, this)
end

scripts.mod_silence_light_priestess = {}

function scripts.mod_silence_light_priestess.insert(this, store, script)
	local target = store.entities[this.modifier.target_id]

	if not target or target.health.dead or not target.enemy then
		return false
	end

	target.enemy.can_do_magic = false
	target.enemy.can_accept_magic = false

	local s = this.render.sprites[1]

	s.ts = store.tick_ts

	if s.prefix_names then
		s.prefix = s.prefix_names[target.unit.size]
	end

	if this.custom_offsets then
		s.offset = V.vclone(this.custom_offsets[target.template_name] or this.custom_offsets.default)
		s.offset.x = s.offset.x * (s.flip_x and -1 or 1)

		if target.unit and target.unit.mod_offset and this.modifier.use_mod_offset then
			s.offset.x = s.offset.x + target.unit.mod_offset.x
			s.offset.y = s.offset.y + target.unit.mod_offset.y
		end
	end

	signal.emit("mod-applied", this, target)

	return true
end

scripts.mod_slow_light_priestess = {}

function scripts.mod_slow_light_priestess.update(this, store, script)
	local m = this.modifier

	this.modifier.ts = store.tick_ts

	local target = store.entities[m.target_id]

	if not target or not target.pos then
		queue_remove(store, this)

		return
	end

	this.pos = target.pos

	local s = this.render.sprites[1]

	if s.prefix_names then
		s.prefix = s.prefix_names[target.unit.size]
	end

	U.y_animation_play(this, "in", nil, store.tick_ts, 1, 1)
	U.animation_start(this, "loop", nil, store.tick_ts, true, 1)

	while true do
		target = store.entities[m.target_id]

		if not target or target.health.dead or m.duration >= 0 and store.tick_ts - m.ts > m.duration or m.last_node and target.nav_path.ni > m.last_node then
			U.y_animation_play(this, "out", nil, store.tick_ts, 1, 1)
			queue_remove(store, this)

			return
		end

		if this.render and target.unit then
			local s = this.render.sprites[1]
			local flip_sign = 1

			if target.render then
				flip_sign = target.render.sprites[1].flip_x and -1 or 1
			end

			if m.health_bar_offset and target.health_bar then
				local hb = target.health_bar.offset
				local hbo = m.health_bar_offset

				s.offset.x, s.offset.y = hb.x + hbo.x * flip_sign, hb.y + hbo.y
			elseif m.use_mod_offset and target.unit.mod_offset then
				s.offset.x, s.offset.y = target.unit.mod_offset.x * flip_sign, target.unit.mod_offset.y
			end
		end

		coroutine.yield()
	end
end

function scripts.mod_silence_light_priestess.remove(this, store, script)
	local target = store.entities[this.modifier.target_id]

	if target and target.enemy then
		target.enemy.can_do_magic = true
		target.enemy.can_accept_magic = true
	end

	return true
end

scripts.mod_damage_tower_inc_light_priestess = {}

function scripts.mod_damage_tower_inc_light_priestess.insert(this, store)
	local m = this.modifier
	local target = store.entities[m.target_id]

	if not target or not target.tower then
		if not target then
			log.error("cannot insert mod_tower_factors, target not found")
		elseif not target.tower then
			log.error("cannot insert mod_tower_factors to entity %s - ", target.id, target.template_name)
		end

		return false
	end

	if this.range_factor then
		if target.attacks then
			target.attacks.range = target.attacks.range * this.range_factor
		end

		if target.barrack then
			target.barrack.rally_range = target.barrack.rally_range * this.range_factor
		end
	end

	if this.damage_factor then
		target.tower.damage_factor = target.tower.damage_factor * this.damage_factor
	end

	signal.emit("mod-applied", this, target)

	return true
end

function scripts.mod_damage_tower_inc_light_priestess.remove(this, store)
	local m = this.modifier
	local target = store.entities[m.target_id]

	if not target or not target.tower then
		log.error("error removing mod_tower_factors %s", this.id)

		return true
	end

	if this.range_factor then
		if target.attacks then
			target.attacks.range = target.attacks.range / this.range_factor
		end

		if target.barrack then
			target.barrack.rally_range = target.barrack.rally_range / this.range_factor
		end
	end

	if this.damage_factor then
		target.tower.damage_factor = target.tower.damage_factor / this.damage_factor
	end

	return true
end

function scripts.mod_damage_tower_inc_light_priestess.update(this, store)
	local m = this.modifier
	local target = store.entities[m.target_id]
	local ogid = m.target_id

	if target then
		this.pos = target.pos
	end

	U.y_animation_play(this, "in", nil, store.tick_ts, 1, 1)
	U.animation_start(this, "idle", nil, store.tick_ts, true, 1)

	m.ts = store.tick_ts

	if this.tween then
		this.tween.ts = store.tick_ts
	end

	while store.tick_ts - m.ts < m.duration do
		if m.target_id ~= ogid then
			ogid = m.target_id
			target = store.entities[m.target_id]

			if this.range_factor then
				if target.attacks then
					target.attacks.range = target.attacks.range * this.range_factor
				end

				if target.barrack then
					target.barrack.rally_range = target.barrack.rally_range * this.range_factor
				end
			end

			if this.damage_factor then
				target.tower.damage_factor = target.tower.damage_factor * this.damage_factor
			end
		end

		coroutine.yield()
	end

	U.y_animation_play(this, "out", nil, store.tick_ts, 1, 1)
	queue_remove(store, this)
end

