scripts.tower_alchemist = {}

function scripts.tower_alchemist.get_info(this)
	local b_t = E:get_template(this.attacks.list[1].bullet)
	local d_t = E:get_template(b_t.bullet.hit_payload)
	local a_t = E:get_template(d_t.dmg_aura)
	local o = scripts.tower_common.get_info(this)

	o.type = STATS_TYPE_TOWER

	local min = math.ceil(a_t.aura.damage_min * this.tower.damage_factor)
	local max = math.ceil(a_t.aura.damage_max * this.tower.damage_factor)

	o.damage_min = min
	o.damage_max = max
	o.damage_type = DAMAGE_TRUE

	return o
end

function scripts.tower_alchemist.update(this, store, script)
	local sid_alchemist = this.render.sid_alchemist
	local sid_fx_cauldron = this.render.sid_fx_cauldron
	local sid_cauldron = this.render.sid_cauldron
	local sid_book = this.render.sid_book
	local sid_bubbles = this.render.sid_bubbles
	local range = this.attacks.range
	local last_ts = store.tick_ts
	local ska_proj_count = 0
	local as = this.attacks
	local a = this.attacks.list[1]

	a.ts = store.tick_ts - a.cooldown

	local pow_a = this.powers and this.powers.skill_a or nil
	local pow_b = this.powers and this.powers.skill_b or nil
	local pow_c = this.powers and this.powers.skill_c or nil
	local sa = this.timed_attacks and this.timed_attacks.list[1] or nil
	local ult_active = this.timed_attacks and this.timed_attacks.list[2] and this.powers.ultimate.active
	local ult = ult_active and this.timed_attacks.list[2] or nil
	local ult_start_cd = ult ~= nil and store.wave_group_number == 0

	if ult then
		ult.ts = store.tick_ts
	end

	local ca = this.common_animations
	local sids = this.render_sids
	local splash_sids = this.splash_sids
	local suffix = "green"

	if this.tower.level == 4 then
		this.idle_animation = "idle_" .. suffix
	end

	local b_t, d_t, a_t
	local dmg_factor_applied = false

	local function get_mod_slow()
		local bullet = E:get_template(this.attacks.list[1].bullet)
		local payload = E:get_template(bullet.bullet.hit_payload)
		local aura = E:get_template(payload.dmg_aura)

		return aura.aura.mods[1]
	end

	local function find_foremost_non_slowed_enemy(entities, pos, min_range, max_range, prediction, flags, bans)
		local _, targets, __ = U.find_foremost_enemy(entities, pos, min_range, max_range, prediction, flags, bans)

		if not targets or #targets == 0 then
			return nil, nil
		end

		local mod_slow = get_mod_slow()
		local target

		for k, t in pairs(targets) do
			if not SU.has_modifiers(store, t, mod_slow) then
				target = t

				break
			end
		end

		if target == nil then
			target = targets[1]
		end

		local node_offset = P:predict_enemy_node_advance(target, prediction)
		local t_ni = target.nav_path.ni + node_offset
		local pred_pos = P:node_pos(target.nav_path.pi, target.nav_path.spi, t_ni)

		return target, pred_pos
	end

	local function y_anim(name, wait, exclude)
		if this.tower.level ~= 4 then
			return
		end

		for k, v in pairs(sids) do
			local anim = ca[name]

			if string.find(anim, "_", #anim) then
				anim = anim .. suffix
			end

			if not exclude or not table.contains(exclude, k) then
				U.animation_start(this, anim, nil, store.tick_ts, false, v)
			end
		end

		if wait then
			U.y_animation_wait(this, sids.alchemist)
		end
	end

	local function y_reload_anim()
		if this.tower.level ~= 4 then
			return
		end

		for k, v in pairs(sids) do
			local anim = ca.reload

			if string.find(anim, "_") then
				anim = anim .. suffix
			end

			U.animation_start(this, anim, nil, store.tick_ts, false, v)
		end

		U.y_wait(store, this.reload_splash_time)
		U.animation_start(this, "run", nil, store.tick_ts, false, splash_sids[suffix])
		U.y_animation_wait(this, sids.alchemist)
	end

	local function assign_basic_attack_variables()
		b_t = E:get_template(a.bullet)
		d_t = E:get_template(b_t.bullet.hit_payload)
		a_t = E:get_template(d_t.dmg_aura)
		this.og_damage_min_basic = a_t.aura.damage_min
		this.og_damage_max_basic = a_t.aura.damage_max
	end

	assign_basic_attack_variables()

	local function apply_tower_dmg_factor_to_bullet()
		if this.tower.damage_factor ~= 1 and not dmg_factor_applied then
			a_t.aura.damage_min = a_t.aura.damage_min * this.tower.damage_factor
			a_t.aura.damage_max = a_t.aura.damage_max * this.tower.damage_factor
			dmg_factor_applied = true
		elseif this.tower.damage_factor == 1 then
			a_t.aura.damage_min = this.og_damage_min_basic
			a_t.aura.damage_max = this.og_damage_max_basic
			dmg_factor_applied = false
		end
	end

	local function reset_dmg_factor()
		local b_t = E:get_template(a.bullet)
		local d_t = E:get_template(b_t.bullet.hit_payload)
		local a_t = E:get_template(d_t.dmg_aura)

		a_t.aura.damage_min = this.og_damage_min_basic
		a_t.aura.damage_max = this.og_damage_max_basic
	end

	while true do
		if ult_start_cd and store.wave_group_number > 0 then
			ult_start_cd = false
			ult.ts = store.tick_ts
		end

		if this.tower.blocked then
			coroutine.yield()
		else
			if this.powers then
				for k, pow in pairs(this.powers) do
					if pow.changed then
						pow.changed = nil

						if pow == pow_a then
							sa.cooldown = pow.cooldown[pow.level]
							sa.disabled = false
							sa.bullet = "bullet_alchemist_skill_a_lvl" .. pow.level
							ska_proj_count = pow.projectile_count[pow.level]

							if pow.level == 1 then
								sa.ts = store.tick_ts - sa.cooldown
							end
						end

						if pow == pow_b then
							if not this.controller_skill_b then
								this.controller_skill_b = E:create_entity(this.controller_skill_b_t)
								this.controller_skill_b.pos = V.vclone(this.pos)
								this.controller_skill_b.tower_alchemist = this
								this.controller_skill_b.tower_id = this.id
								this.controller_skill_b.book_sid = sid_book

								queue_insert(store, this.controller_skill_b)
							end

							this.controller_skill_b.cooldown = pow.cooldown[pow.level]
							this.controller_skill_b.soldier_t = "soldier_alchemist_skill_b_lvl" .. pow.level
						end

						if pow == pow_c then
							if suffix == "green" then
								suffix = "purple"
								this.idle_animation = ca.idle .. suffix

								S:queue(this.skill_c_sound, {
									delay = fts(19)
								})
								y_anim("purple_swap")
								U.y_wait(store, this.skill_c_switch_time)
								U.animation_start(this, "idle_purple", nil, store.tick_ts, true, sid_bubbles)
								U.y_animation_wait(this, sids.alchemist, 1)
								y_anim("idle")
								U.animation_start(this, "idle_purple", nil, store.tick_ts, true, sid_alchemist, true)
							end

							reset_dmg_factor()

							a.bullet = "bullet_alchemist_skill_c_lvl" .. pow.level

							assign_basic_attack_variables()
						end
					end
				end
			end

			::label_719_0::

			if store.tick_ts - a.ts > as.cooldown then
				local target, pred_pos = find_foremost_non_slowed_enemy(store.entities, tpos(this), 0, range, a.node_prediction, a.vis_flags, a.vis_bans)

				if not target then
					SU.delay_attack(store, a, fts(5))
				else
					if this.tower.level ~= 4 then
						U.animation_start(this, a.animation, nil, store.tick_ts, false, sid_alchemist)
					else
						y_anim("attack")
					end

					U.y_wait(store, a.shoot_time)
					apply_tower_dmg_factor_to_bullet()

					local b = E:create_entity(a.bullet)

					b.bullet.damage_factor = this.tower.damage_factor
					b.pos.x, b.pos.y = tpos(this).x + a.bullet_start_offset.x, tpos(this).y + a.bullet_start_offset.y
					b.bullet.from = V.vclone(b.pos)
					b.bullet.to = V.vclone(pred_pos)
					b.bullet.source_id = this.id
					b.bullet.target_id = target.id

					queue_insert(store, b)
					U.y_animation_wait(this, sid_alchemist, 1)

					if this.tower.level ~= 4 then
						U.animation_start(this, a.reload_animation, nil, store.tick_ts, false, sid_alchemist)
						U.y_wait(store, this.reload_splash_time)
						U.animation_start(this, "run", nil, store.tick_ts, false, sid_fx_cauldron)
						U.y_animation_wait(this, sid_alchemist, 1)
						U.animation_start(this, this.idle_animation, nil, store.tick_ts, true, sid_alchemist)
					else
						y_reload_anim()
					end

					if a.double_proj_chance and math.random() <= a.double_proj_chance then
						goto label_719_0
					end

					a.ts = store.tick_ts
					last_ts = store.tick_ts
				end
			end

			if sa and not sa.disabled and store.tick_ts - sa.ts > sa.cooldown then
				local targets = U.find_enemies_in_range(store.entities, this.pos, sa.min_range, sa.max_range, sa.flags, sa.bans)

				if not targets or #targets == 0 or #targets < sa.min_targets then
					SU.delay_attack(store, sa, fts(5))
				else
					y_anim("sticky_spillage", false, {
						"alchemist",
						"cauldron"
					})

					local enemy_positions = {}
					local additional_positions = {}

					for k, v in pairs(targets) do
						local node_offset = P:predict_enemy_node_advance(v, E:get_template(sa.bullet).bullet.flight_time)
						local ni = v.nav_path.ni + node_offset
						local pos = P:node_pos(v.nav_path.pi, v.nav_path.spi, ni)

						table.insert(enemy_positions, pos)

						local v_ni = v.nav_path.ni + node_offset + sa.distance_between_shots
						local v_pos = P:node_pos(v.nav_path.pi, math.random(1, 3), v_ni + math.random(-2, 2))

						if point_in_valid_path(v_pos.x, v_pos.y, {
							v.nav_path.pi
						}) then
							table.insert(additional_positions, v_pos)
						end

						local v_ni = v.nav_path.ni + node_offset - sa.distance_between_shots
						local v_pos = P:node_pos(v.nav_path.pi, math.random(1, 3), v_ni + math.random(-2, 2))

						if point_in_valid_path(v_pos.x, v_pos.y, {
							v.nav_path.pi
						}) then
							table.insert(additional_positions, v_pos)
						end
					end

					local cast_decal = E:create_entity(sa.cast_decal)

					cast_decal.pos = v(V.add(this.pos.x, this.pos.y, sa.cast_decal_offset.x, sa.cast_decal_offset.y))
					cast_decal.render.sprites[1].ts = store.tick_ts

					queue_insert(store, cast_decal)

					local count = 0
					local temp = table.deepclone(additional_positions)

					while count < ska_proj_count do
						local point = enemy_positions[count + 1]

						if not point and #temp > 0 then
							point = get_random_round_robin(temp, 1, #temp)
						end

						point = point or enemy_positions[count % #enemy_positions + 1]

						local b = E:create_entity(sa.bullet)

						b.pos.x, b.pos.y = tpos(this).x + sa.bullet_start_offset.x, tpos(this).y + sa.bullet_start_offset.y
						b.bullet.from = V.vclone(b.pos)
						b.bullet.to = v(point.x, point.y)
						b.bullet.source_id = this.id
						b.bullet.level = pow_a.level

						queue_insert(store, b)
						S:queue(sa.sound)
						U.y_wait(store, fts(5))

						count = count + 1

						if #temp == 0 then
							temp = table.deepclone(additional_positions)
						end
					end

					y_anim("idle")

					sa.ts = store.tick_ts
				end
			end

			if ult and store.tick_ts - ult.ts > ult.cooldown then
				local _, targets, __ = U.find_foremost_enemy(store.entities, this.pos, 0, ult.max_range, ult.node_prediction, ult.vis_flags, ult.vis_bans)

				if not targets or #targets == 0 then
					SU.delay_attack(store, ult, fts(5))
				else
					local enemy_hp = 0

					for k, v in pairs(targets) do
						enemy_hp = enemy_hp + v.health.hp
					end

					if enemy_hp < ult.min_total_hp then
						SU.delay_attack(store, ult, fts(5))
					else
						table.sort(targets, function(e1, e2)
							return e1.health.hp < e2.health.hp
						end)

						local new_targets = {}
						local total_hp = 0

						for i = 1, #targets do
							if targets[i].health.hp + total_hp <= ult.hp_cap and not table.contains(new_targets, targets[i]) then
								total_hp = total_hp + targets[i].health.hp

								table.insert(new_targets, targets[i])
							end

							if targets[#targets - i + 1].health.hp + total_hp <= ult.hp_cap and not table.contains(new_targets, targets[#targets - i + 1]) then
								total_hp = total_hp + targets[#targets - i + 1].health.hp

								table.insert(new_targets, targets[#targets - i + 1])
							end
						end

						if not new_targets or #new_targets == 0 or total_hp < ult.min_total_hp then
							SU.delay_attack(store, ult, fts(5))
						else
							local average_x = 0
							local average_y = 0

							for _, v in pairs(new_targets) do
								if v.__ffe_pos then
									average_x = average_x + v.__ffe_pos.x
									average_y = average_y + v.__ffe_pos.y
								else
									local node_offset = P:predict_enemy_node_advance(v, ult.node_prediction)
									local e_ni = v.nav_path.ni + node_offset
									local v_pos = P:node_pos(v.nav_path.pi, v.nav_path.spi, e_ni)

									average_x = average_x + v_pos.x
									average_y = average_y + v_pos.y
								end
							end

							local shoot_pos = v(average_x / #new_targets, average_y / #new_targets)

							S:queue(ult.sound)
							y_anim(ca.gold, false, {
								"cauldron"
							})
							U.y_wait(store, ult.sprite_times[1])

							this.render.sprites[sid_cauldron].hidden = true
							this.render.sprites[sid_bubbles].hidden = true

							U.y_wait(store, ult.cast_time)

							local b = E:create_entity(ult.bullet)

							b.pos.x, b.pos.y = tpos(this).x + ult.bullet_start_offset.x, tpos(this).y + ult.bullet_start_offset.y
							b.bullet.from = V.vclone(b.pos)
							b.bullet.to = shoot_pos
							b.bullet.source_id = this.id
							b.bullet.target_id = new_targets[1].id
							b.ult_targets = new_targets

							queue_insert(store, b)

							this.render.sprites[sid_cauldron].hidden = false
							this.render.sprites[sid_bubbles].hidden = false

							U.y_animation_wait(this, sid_alchemist, 1)
							y_anim("idle")

							ult.ts = store.tick_ts

							signal.emit("tower-ultimate-used", this)
						end
					end
				end
			end

			if store.tick_ts - last_ts > this.tower.long_idle_cooldown then
				U.animation_start(this, this.idle_animation, nil, store.tick_ts, true, sid_alchemist)

				last_ts = store.tick_ts
			end
		end

		coroutine.yield()
	end
end

function scripts.tower_alchemist.remove(this, store, script)
	if this.controller_skill_b then
		queue_remove(store, this.controller_skill_b)
	end

	if this.soldier_id then
		queue_remove(store, store.entities[this.soldier_id])
	end

	local b_t = E:get_template(this.attacks.list[1].bullet)
	local d_t = E:get_template(b_t.bullet.hit_payload)
	local a_t = E:get_template(d_t.dmg_aura)

	a_t.aura.damage_min = this.og_damage_min_basic
	a_t.aura.damage_max = this.og_damage_max_basic

	return true
end

scripts.bullet_alchemist = {}

function scripts.bullet_alchemist.update(this, store, script)
	this.render.sprites[1].hidden = true

	U.y_wait(store, this.delay_animation_start)

	this.render.sprites[1].hidden = false

	local ts = store.tick_ts
	local a = E:create_entity(this.dmg_aura)

	a.pos = V.vclone(this.pos)

	queue_insert(store, a)
	U.y_animation_play(this, this.animation_start, nil, store.tick_ts, 1, 1)
	U.animation_start(this, this.animation_idle, nil, store.tick_ts, true, 1)

	while store.tick_ts - ts < this.duration do
		coroutine.yield()
	end

	queue_remove(store, a)
	queue_remove(store, this)
end

scripts.mod_slow_alchemist = {}

function scripts.mod_slow_alchemist.insert(this, store, script)
	local target = store.entities[this.modifier.target_id]

	if not target or target.health.dead or not target.motion or target.motion.invulnerable then
		return false
	end

	if this.modifier.excluded_templates and table.contains(this.modifier.excluded_templates, target.template_name) then
		return false
	end

	if this.modifier.vis_flags and this.modifier.vis_bans and (band(this.modifier.vis_flags, target.vis.bans) ~= 0 or band(this.modifier.vis_bans, target.vis.flags) ~= 0) then
		return false
	end

	target.motion.max_speed = target.motion.max_speed * this.slow.factor
	this.modifier.ts = store.tick_ts

	signal.emit("mod-applied", this, target)

	return true
end

scripts.controller_alchemist_skill_b = {}

function scripts.controller_alchemist_skill_b.update(this, store, script)
	local tower = store.entities[this.tower_id]

	if not tower then
		queue_remove(store, this)

		return
	end

	local ts = store.tick_ts - this.cooldown
	local b_sid = this.book_sid
	local s = tower.render.sprites[b_sid]
	local soldier_spawned = false
	local death_ts = store.tick_ts

	S:queue(this.sound_spawn, {
		delay = fts(18)
	})
	U.y_animation_play(tower, this.animation_subject_spawn, nil, store.tick_ts, 1, b_sid)
	U.animation_start(tower, this.animation_subject_idle, nil, store.tick_ts, true, b_sid)

	while true do
		if store.tick_ts - ts > this.cooldown and not soldier_spawned and not this.tower_alchemist.tower.blocked then
			if s.name == this.animation_idle then
				S:queue(this.sound_spawn, {
					delay = fts(18)
				})
				U.y_animation_play(tower, this.animation_subject_spawn, nil, store.tick_ts, 1, b_sid)
				U.animation_start(tower, this.animation_subject_idle, nil, store.tick_ts, true, b_sid)
			end

			local targets = U.find_enemies_in_range(store.entities, this.pos, 0, this.max_range, this.flags, this.bans)

			if not targets or #targets < this.min_targets then
				goto label_731_0
			end

			local nearest = P:nearest_nodes(this.pos.x, this.pos.y, {
				targets[1].nav_path.pi
			})
			local pi, spi, ni = unpack(nearest[1])
			local pos = P:node_pos(pi, 1, ni)

			if not point_in_valid_path(pos.x, pos.y, {
				pi
			}) or targets[1].nav_path.ni > ni - 5 then
				goto label_731_0
			end

			S:queue(this.sound_drink, {
				delay = fts(19)
			})
			U.y_animation_play(tower, this.animation_soldier_spawn, nil, store.tick_ts, 1, b_sid)
			U.animation_start(tower, this.animation_idle, nil, store.tick_ts, true, b_sid)

			local d = E:create_entity(this.soldier_spawn_decal)

			d.pos = pos
			d.render.sprites[1].ts = store.tick_ts

			queue_insert(store, d)
			U.y_wait(store, this.spawn_time)

			local st = E:create_entity(this.soldier_t)

			st.pos = V.vclone(pos)
			st.controller = this
			st.pi = targets[1].nav_path.pi
			this.tower_alchemist.soldier_id = st.id

			queue_insert(store, st)
			U.y_animation_wait(tower, b_sid, 1)

			soldier_spawned = true
			this.soldier_dead = false
		end

		if this.soldier_dead and soldier_spawned then
			ts = store.tick_ts
			soldier_spawned = false
			this.tower_alchemist.soldier_id = nil
			death_ts = store.tick_ts

			U.animation_start(tower, this.animation_idle, nil, store.tick_ts, true, b_sid)
		end

		::label_731_0::

		coroutine.yield()
	end
end

scripts.soldier_alchemist_skill_b = {}

function scripts.soldier_alchemist_skill_b.update(this, store, script)
	this.reinforcement.ts = store.tick_ts
	this.render.sprites[1].ts = store.tick_ts
	this.hp = this.hp_max
	this.nav_rally.center = nil
	this.nav_rally.pos = V.vclone(this.pos)

	if this.sound_events and this.sound_events.raise then
		S:queue(this.sound_events.raise)
	end

	this.vis.bans = F_ALL

	for i = 1, 2 do
		U.y_animation_play(this, this.animation_pecs, nil, store.tick_ts, 1)
	end

	U.animation_start(this, this.animation_idle, this.render.sprites[1].flip_x, store.tick_ts, true, 1)

	this.vis.bans = F_NONE

	local brk, stam, distance
	local path_ni = 1
	local path_spi = 1
	local path_pi = 1
	local node_pos
	local nearest = P:nearest_nodes(this.pos.x, this.pos.y, {
		this.pi
	})

	if #nearest > 0 then
		path_pi, path_spi, path_ni = unpack(nearest[1])
	end

	path_spi = 1
	path_ni = path_ni - 3

	local function valid_pos()
		local pi, spi, ni, dist = unpack(P:nearest_nodes(this.pos.x, this.pos.y, {
			this.pi
		})[1])
		local node_pos = P:node_pos(pi, spi, ni)

		return P:is_node_valid(pi, ni) and GR:cell_is(node_pos.x, node_pos.y, bor(TERRAIN_LAND, TERRAIN_ICE)) and P:is_path_active(pi)
	end

	while true do
		if this.health.dead or not valid_pos() or not P:is_node_valid(path_pi, path_ni) or store.tick_ts - this.reinforcement.ts > this.reinforcement.duration then
			this.health_bar.hidden = true

			U.unblock_target(store, this)
			S:queue(this.sound_remove_1, {
				delay = fts(7)
			})
			S:queue(this.sound_remove, {
				delay = fts(59)
			})
			U.y_animation_play(this, this.animation_death, this.render.sprites[1].flip_x, store.tick_ts, 1, 1)

			this.controller.soldier_dead = true

			queue_remove(store, this)

			return
		end

		if this.unit.is_stunned then
			SU.soldier_idle(store, this)
		else
			brk, stam = SU.y_soldier_melee_block_and_attacks(store, this)

			if brk or stam == A_DONE or stam == A_IN_COOLDOWN and not this.melee.continue_in_cooldown then
				-- block empty
			else
				node_pos = this.nav_rally.pos
				distance = V.dist2(node_pos.x, node_pos.y, this.pos.x, this.pos.y)

				if distance < 25 then
					path_ni = path_ni - 3
					this.nav_rally.pos = P:node_pos(path_pi, path_spi, path_ni)
				end

				if SU.soldier_go_back_step(store, this) then
					-- block empty
				else
					SU.soldier_regen(store, this)
				end
			end
		end

		coroutine.yield()
	end
end

scripts.bullet_alchemist_ult = {}

function scripts.bullet_alchemist_ult.update(this, store, script)
	local b = this.bullet
	local dmin, dmax = b.damage_min, b.damage_max
	local dradius = b.damage_radius

	if b.level and b.level > 0 then
		if b.damage_radius_inc then
			dradius = dradius + b.level * b.damage_radius_inc
		end

		if b.damage_min_inc then
			dmin = dmin + b.level * b.damage_min_inc
		end

		if b.damage_max_inc then
			dmax = dmax + b.level * b.damage_max_inc
		end
	end

	if b.damages_min and b.damages_max and b.level then
		dmin = b.damages_min[b.level]
		dmax = b.damages_max[b.level]
	end

	local ps

	if b.particles_name then
		ps = E:create_entity(b.particles_name)
		ps.particle_system.track_id = this.id

		queue_insert(store, ps)
	end

	local shadow, shadow_start_pos

	if this.decal_shadow then
		shadow = E:create_entity(this.decal_shadow)
		shadow.pos = V.vclone(b.from)
		shadow.pos.y = b.from.y - 70

		queue_insert(store, shadow)

		shadow_start_pos = V.vclone(shadow.pos)
	end

	while store.tick_ts - b.ts + store.tick_length < b.flight_time do
		coroutine.yield()

		b.last_pos.x, b.last_pos.y = this.pos.x, this.pos.y
		this.pos.x, this.pos.y = SU.position_in_parabola(store.tick_ts - b.ts, b.from, b.speed, b.g)

		if b.align_with_trajectory then
			this.render.sprites[1].r = V.angleTo(this.pos.x - b.last_pos.x, this.pos.y - b.last_pos.y)
		elseif b.rotation_speed then
			this.render.sprites[1].r = this.render.sprites[1].r + b.rotation_speed * store.tick_length
		end

		if b.hide_radius then
			this.render.sprites[1].hidden = V.dist(this.pos.x, this.pos.y, b.from.x, b.from.y) < b.hide_radius or V.dist(this.pos.x, this.pos.y, b.to.x, b.to.y) < b.hide_radius
		end

		if b.anim_rising or b.anim_falling then
			if this.pos.y - b.last_pos.y >= 0 then
				if b.anim_rising and this.render.sprites[1].name ~= b.anim_rising then
					U.animation_start(this, b.anim_rising, nil, store.tick_ts, b.anim_rising_loops, 1)
				end
			elseif b.anim_falling and this.render.sprites[1].name ~= b.anim_falling then
				U.animation_start(this, b.anim_falling, nil, store.tick_ts, b.anim_falling_loops, 1)
			end
		end

		if b.switch_z_time and this.render.sprites[1].z ~= Z_BULLETS and store.tick_ts - b.ts > b.switch_z_time then
			this.render.sprites[1].z = Z_BULLETS
		end

		if shadow then
			shadow.pos.x = shadow_start_pos.x + (b.to.x - shadow_start_pos.x) * ((store.tick_ts - b.ts) / b.flight_time)
			shadow.pos.y = shadow_start_pos.y + (b.to.y - shadow_start_pos.y) * ((store.tick_ts - b.ts) / b.flight_time)

			local height = this.pos.y - shadow.pos.y
			local s = km.clamp(0.6, 1, 40 / height)

			shadow.render.sprites[1].scale = V.vv(s)
		end
	end

	local enemies = U.find_enemies_in_range(store.entities, b.to, 0, dradius, b.damage_flags, b.damage_bans)

	if enemies and dmax and dmax > 0 then
		for _, enemy in pairs(enemies) do
			local d = E:create_entity("damage")

			d.damage_type = b.damage_type
			d.reduce_armor = b.reduce_armor
			d.reduce_magic_armor = b.reduce_magic_armor

			if b.damage_decay_random then
				d.value = U.frandom(dmin, dmax)
			else
				local upg = UP:get_upgrade("towers_improved_formulas")
				local source = store.entities[b.source_id]

				if upg and source and source.tower then
					d.value = dmax
				else
					local dist_factor = U.dist_factor_inside_ellipse(enemy.pos, b.to, dradius)

					d.value = math.floor(dmax - (dmax - dmin) * dist_factor)
				end
			end

			d.value = math.ceil(b.damage_factor * d.value)
			d.source_id = this.id
			d.target_id = enemy.id

			if b.xp_gain_factor and b.xp_dest_id then
				d.xp_gain_factor = b.xp_gain_factor
				d.xp_dest_id = b.source_id
			end

			queue_damage(store, d)
			log.paranoid("bomb id:%s, radius:%s, enemy id:%s, dist:%s, damage:%s damage_type:%x", this.id, dradius, enemy.id, V.dist(enemy.pos.x, enemy.pos.y, b.to.x, b.to.y), d.value, d.damage_type)

			if this.up_shock_and_awe_chance and band(enemy.vis.bans, F_STUN) == 0 and band(enemy.vis.flags, bor(F_BOSS, F_CLIFF, F_FLYING)) == 0 and math.random() < this.up_shock_and_awe_chance then
				local mod = E:create_entity("mod_shock_and_awe")

				mod.modifier.target_id = enemy.id

				queue_insert(store, mod)
			end

			if b.mod then
				local mod = E:create_entity(b.mod)

				mod.modifier.target_id = enemy.id
				mod.modifier.source_id = this.id
				mod.modifier.level = b.level or 1

				queue_insert(store, mod)
			end
		end
	end

	local p = SU.create_bullet_pop(store, this)

	queue_insert(store, p)

	local cell_type = GR:cell_type(b.to.x, b.to.y)

	if b.hit_fx_water and band(cell_type, TERRAIN_WATER) ~= 0 then
		S:queue(this.sound_events.hit_water)

		local water_fx = E:create_entity(b.hit_fx_water)

		water_fx.pos.x, water_fx.pos.y = b.to.x, b.to.y
		water_fx.render.sprites[1].ts = store.tick_ts
		water_fx.render.sprites[1].sort_y_offset = b.hit_fx_sort_y_offset

		queue_insert(store, water_fx)
	elseif b.hit_fx then
		S:queue(this.sound_events.hit)

		local sfx = E:create_entity(b.hit_fx)

		sfx.pos = V.vclone(b.to)

		for i = 1, #sfx.render.sprites do
			sfx.render.sprites[i].ts = store.tick_ts
			sfx.render.sprites[i].sort_y_offset = b.hit_fx_sort_y_offset
		end

		queue_insert(store, sfx)
	end

	if b.hit_decal and band(cell_type, TERRAIN_WATER) == 0 then
		local decal = E:create_entity(b.hit_decal)

		decal.pos = V.vclone(b.to)

		for i = 1, #decal.render.sprites do
			decal.render.sprites[i].ts = store.tick_ts
		end

		queue_insert(store, decal)
	end

	if b.hit_payload then
		local hp

		if type(b.hit_payload) == "string" then
			hp = E:create_entity(b.hit_payload)
		else
			hp = b.hit_payload
		end

		hp.pos.x, hp.pos.y = b.to.x, b.to.y
		hp.source_id = b.source_id
		hp.ult_targets = this.ult_targets

		if hp.aura then
			hp.aura.level = this.bullet.level
		end

		queue_insert(store, hp)
	end

	if this.screenshake_amplitude then
		local shake = E:create_entity("aura_screen_shake")

		shake.aura.amplitude = this.screenshake_amplitude
		shake.aura.duration = this.screenshake_duration
		shake.aura.freq_factor = this.screenshake_freq_factor

		queue_insert(store, shake)
	end

	if shadow then
		queue_remove(store, shadow)
	end

	queue_remove(store, this)
end

scripts.aura_alchemist_ult = {}

function scripts.aura_alchemist_ult.update(this, store, script)
	local first_hit_ts
	local last_hit_ts = 0
	local cycles_count = 0
	local victims_count = 0

	if this.aura.track_source and this.aura.source_id then
		local te = store.entities[this.aura.source_id]

		if te and te.pos then
			this.pos = te.pos
		end
	end

	last_hit_ts = store.tick_ts - this.aura.cycle_time

	if this.aura.apply_delay then
		last_hit_ts = last_hit_ts + this.aura.apply_delay
	end

	while true do
		if this.interrupt then
			last_hit_ts = 1e+99
		end

		if this.aura.cycles and cycles_count >= this.aura.cycles or this.aura.duration >= 0 and store.tick_ts - this.aura.ts > this.actual_duration then
			break
		end

		if this.aura.stop_on_max_count and this.aura.max_count and victims_count >= this.aura.max_count then
			break
		end

		if this.aura.track_source and this.aura.source_id then
			local te = store.entities[this.aura.source_id]

			if not te or te.health and te.health.dead and not this.aura.track_dead then
				break
			end
		end

		if this.aura.requires_magic then
			local te = store.entities[this.aura.source_id]

			if not te or not te.enemy then
				goto label_735_0
			end

			if this.render then
				this.render.sprites[1].hidden = not te.enemy.can_do_magic
			end

			if not te.enemy.can_do_magic then
				goto label_735_0
			end
		end

		if this.aura.source_vis_flags and this.aura.source_id then
			local te = store.entities[this.aura.source_id]

			if te and te.vis and band(te.vis.bans, this.aura.source_vis_flags) ~= 0 then
				goto label_735_0
			end
		end

		if this.aura.requires_alive_source and this.aura.source_id then
			local te = store.entities[this.aura.source_id]

			if te and te.health and te.health.dead then
				goto label_735_0
			end
		end

		if not (store.tick_ts - last_hit_ts >= this.aura.cycle_time) or this.aura.apply_duration and first_hit_ts and store.tick_ts - first_hit_ts > this.aura.apply_duration then
			-- block empty
		else
			if this.render and this.aura.cast_resets_sprite_id then
				this.render.sprites[this.aura.cast_resets_sprite_id].ts = store.tick_ts
			end

			first_hit_ts = first_hit_ts or store.tick_ts
			last_hit_ts = store.tick_ts
			cycles_count = cycles_count + 1

			for i, target in ipairs(this.ult_targets) do
				if this.aura.targets_per_cycle and i > this.aura.targets_per_cycle then
					break
				end

				if this.aura.max_count and victims_count >= this.aura.max_count then
					break
				end

				if U.is_inside_ellipse(target.pos, this.pos, this.aura.radius) then
					local mods = this.aura.mods or {
						this.aura.mod
					}

					for _, mod_name in pairs(mods) do
						local new_mod = E:create_entity(mod_name)

						new_mod.modifier.level = this.aura.level
						new_mod.modifier.target_id = target.id
						new_mod.modifier.source_id = this.id

						if this.aura.hide_source_fx and target.id == this.aura.source_id then
							new_mod.render = nil
						end

						queue_insert(store, new_mod)

						victims_count = victims_count + 1
					end
				end
			end
		end

		::label_735_0::

		coroutine.yield()
	end

	signal.emit("aura-apply-mod-victims", this, victims_count)
	queue_remove(store, this)
end

scripts.mod_alchemist_ult_polymorph = {}

function scripts.mod_alchemist_ult_polymorph.insert(this, store)
	local target = store.entities[this.modifier.target_id]

	if target and not target.health.dead then
		this.target_ref = target

		for _, s in ipairs(target.render.sprites) do
			s.hidden = true
		end

		this.polymorph_enemy = {
			enemy = target
		}

		SU.remove_modifiers(store, target)
		SU.remove_auras(store, target)
		queue_remove(store, target)
		U.unblock_all(store, target)

		target.main_script.co = nil
		target.main_script.runs = 0

		if target.count_group then
			target.count_group.in_limbo = true
		end

		target.trigger_deselect = true

		local pig = E:create_entity(this.entity_t)

		pig.pos = target.pos
		pig.nav_path = target.nav_path
		pig.health.hp_max = target.health.hp_max
		pig.health.hp = target.health.hp
		pig.enemy.gold = target.enemy.gold + pig.extra_gold
		pig.earnings_bonuses = target.earnings_bonuses and table.deepclone(target.earnings_bonuses) or nil
		earnings_stats.adjust_enemy_bonus(pig, "tower_alchemist", pig.extra_gold)

		queue_insert(store, pig)

		this.polymorph_enemy.pig = pig

		return true
	end

	return false
end

function scripts.mod_alchemist_ult_polymorph.update(this, store, script)
	local m = this.modifier

	this.modifier.ts = store.tick_ts

	local target = this.target_ref

	this.pos = target.pos

	while true do
		if m.duration >= 0 and store.tick_ts - m.ts > m.duration then
			queue_remove(store, this)

			return
		end

		coroutine.yield()
	end
end

function scripts.mod_alchemist_ult_polymorph.remove(this, store)
	local target = this.polymorph_enemy.enemy
	local pig = this.polymorph_enemy.pig

	if pig and store.entities[pig.id] and not pig.health.dead then
		for _, s in ipairs(target.render.sprites) do
			s.hidden = false
		end

		target.main_script.runs = 1
		target.pos = V.vclone(pig.pos)
		target.nav_path = pig.nav_path
		target.health.hp = pig.health.hp

		queue_insert(store, target)

		pig.trigger_deselect = true

		S:queue(this.sound_transform_out)

		local sfx = E:create_entity(this.transform_fx)

		sfx.pos = V.v(target.pos.x + target.unit.hit_offset.x, target.pos.y + target.unit.hit_offset.y)
		sfx.render.sprites[1].ts = store.tick_ts
		sfx.render.sprites[1].runs = 0

		if target and sfx.render.sprites[1].size_names then
			sfx.render.sprites[1].name = sfx.render.sprites[1].size_names[target.unit.size]
		end

		queue_insert(store, sfx)
		queue_remove(store, pig)
	end

	return true
end

scripts.tower_tree = {}

function scripts.tower_tree.get_info(this)
	local info = scripts.tower_common.get_info(this)

	info.damage_type = this.attacks.list[1].damage_type

	return info
end

function scripts.tower_tree.update(this, store)
	local MODE_TOWER = 0
	local MODE_UNIT = 1
	local a = this.attacks
	local aa = this.attacks.list[1]
	local saa = this.timed_attacks and this.timed_attacks.list[1] or nil
	local sca = this.timed_attacks and this.timed_attacks.list[2] or nil
	local sua = this.timed_attacks and this.timed_attacks.list[3] or nil
	local ult_start_cd = sua ~= nil and store.wave_group_number == 0
	local sba = this.timed_attacks and this.timed_attacks.list[4] or nil
	local pow_a = this.powers and this.powers.skill_a or nil
	local pow_b = this.powers and this.powers.skill_b or nil
	local pow_c = this.powers and this.powers.skill_c or nil
	local ult = this.powers and this.powers.ultimate or nil

	if sua and ult then
		sba.ts = store.tick_ts
		sua.disabled = not ult.active
	end

	local tree_unit

	this._first_frame_dead = true

	local revive_ts, old_prefix, old_offset, old_rect

	if not this.tower_upgrade_persistent_data.soldier_name_key then
		this.tower_upgrade_persistent_data.soldier_name_key = string.format(string.gsub(this.soldier_random_name_format, "_NAME", ""), math.random(this.soldier_random_name_count))
	end

	local function check_upgrades_purchase()
		if this.powers then
			for i, pow in pairs(this.powers) do
				if pow.changed then
					pow.changed = nil

					if pow == pow_a then
						saa.disabled = false
						saa.cooldown = pow_a.cooldown[pow.level]
						saa.aura = "aura_tree_tower_skill_a_blind_lvl" .. pow.level

						if pow.level == 1 then
							saa.ts = store.tick_ts - saa.cooldown
						end
					end

					if pow == pow_c then
						sca.disabled = false
						sca.cooldown = pow_c.cooldown[pow.level]
						sca.aura = "aura_tree_skill_c_root_lvl" .. pow.level

						if pow.level == 1 then
							sca.ts = store.tick_ts - sca.cooldown
						end
					end

					if pow == pow_b and pow.level == 1 then
						local cd = 0
						local s_t = E:get_template(this.barrack.soldier_type)

						if s_t.timed_attacks then
							cd = s_t.timed_attacks.list[2].cooldown
						end

						sba.ts = store.tick_ts - cd
					end

					for _, s in pairs(this.barrack.soldiers) do
						if s.powers and s.powers[i] then
							s.powers[i].level = pow.level
							s.powers[i].changed = true
						end
					end
				end
			end

			for _, s in pairs(this.barrack.soldiers) do
				s.powers.ultimate.active = ult.active
			end
		end
	end

	local function spawn_cover()
		local fx = E:create_entity(this.spawn_fx)

		fx.pos.x, fx.pos.y = this.pos.x, this.pos.y
		fx.render.sprites[1].scale = this.spawn_fx_scale
		fx.render.sprites[1].ts = store.tick_ts

		queue_insert(store, fx)
	end

	local function spawn_unit()
		tree_unit = E:create_entity(this.barrack.soldier_type)
		tree_unit.soldier.tower_id = this.id
		tree_unit.nav_rally.pos, tree_unit.nav_rally.center = this.barrack.rally_pos, this.barrack.rally_pos
		tree_unit.nav_rally.new = true
		tree_unit.pos.x, tree_unit.pos.y = this.pos.x + this.render.sprites[this.tree_sid].offset.x, this.pos.y + this.render.sprites[this.tree_sid].offset.y
		this.barrack.soldiers = {
			tree_unit
		}

		if tree_unit.powers and this.powers then
			for i, pow in pairs(this.powers) do
				if tree_unit.powers[i] then
					tree_unit.powers[i].level = pow.level
					tree_unit.powers[i].changed = true
				end
			end
		end

		queue_insert(store, tree_unit)
		signal.emit("tower-spawn", this, tree_unit)
		spawn_cover()
	end

	local function cmd_return_tree_unit_to_tower()
		this.tower_upgrade_persistent_data.returning_to_tower = true
		this.tower_upgrade_persistent_data.soldier_return_to_tower = true
		tree_unit.return_to_tower = true
		tree_unit.nav_rally.pos = V.v(this.pos.x + this.render.sprites[this.tree_sid].offset.x, this.pos.y + this.render.sprites[this.tree_sid].offset.y)
		tree_unit.nav_rally.new = true
	end

	local function cmd_rally_tree_unit(p)
		this.tower_upgrade_persistent_data.returning_to_tower = false
		this.tower_upgrade_persistent_data.soldier_return_to_tower = false
		tree_unit.return_to_tower = false
		tree_unit.nav_rally.pos = p
		tree_unit.nav_rally.new = true
	end

	local function sprite_offsets_click_rect_enter_unit()
		old_offset = this.render.sprites[this.tree_sid].offset
		this.render.sprites[this.tree_sid].offset = this.unit_idle_offset
		this.render.sprites[this.tree_sid].sort_y_offset = this.unit_idle_offset.y
		old_rect = this.ui.click_rect
		this.ui.click_rect = this.unit_idle_click_rect
	end

	local function check_mode_change()
		if this.change_mode then
			this.change_mode = false

			if this.tower_upgrade_persistent_data.current_mode == MODE_TOWER then
				this.tower.show_rally = true
				this.tower_upgrade_persistent_data.current_mode = MODE_UNIT

				spawn_unit()
				S:queue(this.sound_unit)

				this.render.sprites[this.tree_sid].name = this.unit_idle_anim

				sprite_offsets_click_rect_enter_unit()
			elseif this.tower_upgrade_persistent_data.current_mode == MODE_UNIT then
				if not this.tower_upgrade_persistent_data.returning_to_tower then
					cmd_return_tree_unit_to_tower()
				else
					cmd_rally_tree_unit(this.barrack.rally_pos)
				end
			end
		end
	end

	local function check_transition()
		if this.tower_upgrade_persistent_data.returning_to_tower and tree_unit.arrived_to_tower then
			this.tower_upgrade_persistent_data.returning_to_tower = false
			this.tower_upgrade_persistent_data.current_mode = MODE_TOWER
			this.tower.show_rally = false

			spawn_cover()
			S:queue(this.sound_tower)

			if game.game_gui.selected_entity and game.game_gui.selected_entity.id == tree_unit.id then
				signal.emit("hide-bottom-info")
			end

			queue_remove(store, tree_unit)

			this.barrack.soldiers = {}
			this.render.sprites[this.tree_sid].name = this.idle_anim
			this.render.sprites[this.tree_sid].offset = old_offset
			this.render.sprites[this.tree_sid].sort_y_offset = 0
			this.ui.click_rect = old_rect
		end
	end

	local function setup_tower_from_upgrade()
		if this.tower_upgrade_persistent_data.current_mode == MODE_UNIT then
			this.render.sprites[this.tree_sid].name = this.unit_idle_anim
			this.tower.show_rally = true
			tree_unit = table.filter(store.entities, function(k, v)
				return v.template_name == this.barrack.soldier_type and v.soldier.tower_id == this.id
			end)[1]

			sprite_offsets_click_rect_enter_unit()

			if this.tower_upgrade_persistent_data.returning_to_tower then
				tree_unit.return_to_tower = this.tower_upgrade_persistent_data.soldier_return_to_tower
				tree_unit.arrived_to_tower = false
				tree_unit.nav_rally.new = true
			end

			if this.tower_upgrade_persistent_data.dead then
				this._first_frame_dead = true
				this.tower_upgrade_persistent_data.dead = false
				this.render.sprites[this.tree_sid].name = this.unit_idle_anim

				spawn_unit()
			end
		end
	end

	local function shoot_bullet(attack, target_pos)
		local b = E:create_entity(attack.bullet)

		b.bullet.damage_factor = this.tower.damage_factor
		b.pos.x, b.pos.y = this.pos.x + attack.bullet_start_offset.x, this.pos.y + attack.bullet_start_offset.y
		b.bullet.from = V.vclone(b.pos)
		b.bullet.to = target_pos
		b.bullet.source_id = this.id
		b.bullet.level = 1

		S:queue(attack.sound)
		queue_insert(store, b)
	end

	local b = this.barrack
	local last_idle_ts = store.tick_ts
	local on_optional_idle = false

	setup_tower_from_upgrade()

	while true do
		if ult_start_cd and store.wave_group_number > 0 then
			ult_start_cd = false
			sua.ts = store.tick_ts
		end

		if this.tower.blocked then
			coroutine.yield()
		else
			check_upgrades_purchase()
			check_mode_change()
			check_transition()

			if this.tower_upgrade_persistent_data.current_mode == MODE_TOWER then
				if store.tick_ts - aa.ts > a.cooldown then
					local aa = aa
					local tower_pos = tpos(this)
					local target_enemy = U.find_foremost_enemy(store.entities, tower_pos, 0, a.range, 0, aa.vis_flags, aa.vis_bans)

					if not target_enemy then
						SU.delay_attack(store, aa, fts(10))
					else
						U.animation_start(this, aa.animation, false, store.tick_ts, false, this.tree_sid)
						S:queue(aa.sound, {
							delay = fts(4)
						})
						U.y_wait(store, aa.hit_time, function()
							return this.tower.blocked
						end)

						if this.tower.blocked then
							goto label_740_0

							S:stop(aa.sound)
						end

						aa.ts = store.tick_ts

						local aura = E:create_entity(aa.damage_aura)

						aura.pos.x, aura.pos.y = tower_pos.x, tower_pos.y
						aura.aura.damage_factor = this.tower.damage_factor
						aura.aura.radius = a.range

						queue_insert(store, aura)

						local r_aura = E:create_entity(aa.hit_aura)

						r_aura.pos.x, r_aura.pos.y = tower_pos.x, tower_pos.y

						queue_insert(store, r_aura)

						local inc = math.pi / 5

						for i = 1, 10 do
							local pe = U.point_on_ellipse(tpos(this), aura.aura.radius * 0.6, inc * (i - 1))
							local random = math.random(aa.min_random_position_offset, aa.max_random_position_offset)

							pe.x = pe.x + random
							pe.y = pe.y + random

							if P:valid_node_nearby(pe.x, pe.y) then
								local small_decal = E:create_entity(aa.hit_decal)

								small_decal.pos = pe
								small_decal.render.sprites[1].ts = store.tick_ts
								small_decal.render.sprites[1].scale = v(1.1, 1.1)
								small_decal.render.sprites[1].flip_x = math.random() > 0.7 and true or false
								small_decal.render.sprites[2].ts = store.tick_ts
								small_decal.render.sprites[2].scale = v(1.1, 1.1)
								small_decal.render.sprites[2].flip_x = math.random() > 0.7 and true or false

								queue_insert(store, small_decal)
							end
						end

						check_upgrades_purchase()
						U.y_animation_wait(this, this.tree_sid)
						U.animation_start(this, this.idle_anim, nil, store.tick_ts, true, this.tree_sid)
					end
				end

				::label_740_0::

				if saa and not saa.disabled and store.tick_ts - saa.ts > saa.cooldown then
					local aa = saa
					local tower_pos = tpos(this)
					local trigger_enemy, enemies, pred_pos = U.find_foremost_enemy(store.entities, tower_pos, 0, aa.range, 0, aa.vis_flags, aa.vis_bans)

					if not trigger_enemy or enemies and #enemies < aa.min_targets then
						SU.delay_attack(store, aa, fts(10))
					elseif this.tower.blocked then
						-- block empty
					else
						U.animation_start(this, aa.animation, nil, store.tick_ts, false, this.tree_sid)
						S:queue(aa.sound, {
							delay = fts(4)
						})
						U.y_wait(store, aa.cast_time)

						local aura = E:create_entity(aa.aura)

						aura.pos.x, aura.pos.y = tower_pos.x, tower_pos.y

						queue_insert(store, aura)

						local inc = math.pi / 4

						for i = 1, 8 do
							local pe = U.point_on_ellipse(tpos(this), aura.aura.radius * 0.8, inc * (i - 1))

							if P:valid_node_nearby(pe.x, pe.y) then
								local small_decal = E:create_entity(aa.decal)
								local p = {}

								for i, v in ipairs(P.paths) do
									table.insert(p, i)
								end

								local nn = P:nearest_nodes(pe.x, pe.y, p)[1]
								local np = P:node_pos(nn[1], nn[2], nn[3] + math.random(aa.min_cloud_node_offset, aa.max_cloud_node_offset))

								small_decal.pos.x, small_decal.pos.y = np.x, np.y
								small_decal.render.sprites[1].ts = store.tick_ts
								small_decal.render.sprites[1].alpha = 150

								queue_insert(store, small_decal)
							end
						end

						saa.ts = store.tick_ts

						U.y_animation_wait(this, this.tree_sid)

						last_idle_ts = store.tick_ts
					end
				end

				if sca and not sca.disabled and store.tick_ts - sca.ts > sca.cooldown then
					local aa = sca
					local tower_pos = tpos(this)
					local trigger_enemy, enemies, pred_pos = U.find_foremost_enemy(store.entities, tower_pos, 0, aa.range, 0, aa.vis_flags, aa.vis_bans)

					if not trigger_enemy or enemies and #enemies < aa.min_targets then
						SU.delay_attack(store, aa, fts(10))
					elseif this.tower.blocked then
						-- block empty
					else
						U.animation_start(this, aa.animation, nil, store.tick_ts, false, this.tree_sid)
						S:queue(aa.sound)
						U.y_wait(store, aa.cast_time)

						local aura = E:create_entity(aa.aura)

						aura.pos.x, aura.pos.y = tower_pos.x, tower_pos.y

						queue_insert(store, aura)

						sca.ts = store.tick_ts

						U.y_animation_wait(this, this.tree_sid)

						last_idle_ts = store.tick_ts
					end
				end

				if sua and not sua.disabled and store.tick_ts - sua.ts > sua.cooldown then
					local aa = sua
					local t_bullet = E:get_template(aa.bullet)
					local t_seed = E:get_template(t_bullet.bullet.hit_payload)
					local tower_pos = tpos(this)
					local pred_time = aa.shoot_time + t_bullet.bullet.flight_time
					local target_enemy, _, pred_pos = U.find_foremost_enemy(store.entities, tower_pos, 0, aa.range, pred_time, aa.vis_flags, aa.vis_bans)

					if not target_enemy then
						SU.delay_attack(store, aa, fts(10))
					else
						U.animation_start(this, aa.animation, false, store.tick_ts, false, this.tree_sid)
						U.y_wait(store, aa.shoot_time, function()
							return this.tower.blocked
						end)

						if this.tower.blocked then
							-- block empty
						else
							shoot_bullet(aa, pred_pos)

							sua.ts = store.tick_ts

							signal.emit("tower-ultimate-used", this)
							U.y_animation_wait(this, this.tree_sid)

							last_idle_ts = store.tick_ts
						end
					end
				end

				if this.idle_variations and this.idle_var_cd and store.tick_ts - last_idle_ts > this.idle_var_cd then
					if not this._idle_vars then
						this._idle_vars = {}
					end

					local v = get_random_round_robin(this._idle_vars, 1, #this.idle_variations)

					U.animation_start(this, this.idle_anim .. this.idle_variations[v], nil, store.tick_ts, false, this.tree_sid)

					last_idle_ts = store.tick_ts
					on_optional_idle = true
				end

				if on_optional_idle and U.animation_finished(this, this.tree_sid) then
					U.animation_start(this, this.idle_anim, nil, store.tick_ts, true, this.tree_sid)
				end
			elseif this.tower_upgrade_persistent_data.current_mode == MODE_UNIT then
				this.tower_upgrade_persistent_data.disable_change_mode = tree_unit and tree_unit.health.dead

				if this._first_frame_dead and tree_unit and tree_unit.health.dead then
					revive_ts = store.tick_ts + tree_unit.health.dead_lifetime
					this._first_frame_dead = false
					this.tower_upgrade_persistent_data.dead = true

					U.y_wait(store, 2)

					old_prefix = this.render.sprites[this.tree_sid].prefix
					this.render.sprites[this.tree_sid].prefix = this.tower_dead_prefix

					U.y_animation_play(this, this.tower_dead_anims.die, nil, store.tick_ts, 1, this.tree_sid)
					U.animation_start(this, this.tower_dead_anims.idle, nil, store.tick_ts, true, this.tree_sid)
				end

				if b.rally_new then
					b.rally_new = false

					signal.emit("rally-point-changed", this)

					tree_unit.nav_rally.center = b.rally_pos

					cmd_rally_tree_unit(b.rally_pos)
				end

				if not this.tower_upgrade_persistent_data.dead and this.idle_when_unit_cd and store.tick_ts - last_idle_ts > this.idle_when_unit_cd then
					U.animation_start(this, this.idle_when_unit_anim, nil, store.tick_ts, false, this.tree_sid)

					last_idle_ts = store.tick_ts
					on_optional_idle = true
				end

				if not this.tower_upgrade_persistent_data.dead and on_optional_idle and U.animation_finished(this, this.tree_sid) then
					U.animation_start(this, this.unit_idle_anim, nil, store.tick_ts, false, this.tree_sid)
				end

				if this.tower_upgrade_persistent_data.dead and store.tick_ts - last_idle_ts > this.idle_when_dead_cd then
					U.animation_start(this, this.tower_dead_anims.dead_idle2, nil, store.tick_ts, false, this.tree_sid)

					last_idle_ts = store.tick_ts
				end

				if this.tower_upgrade_persistent_data.dead and revive_ts - store.tick_ts < this.tower_dead_revive_anim_duration then
					U.y_animation_play(this, this.tower_dead_anims.revive, nil, store.tick_ts, 1, this.tree_sid)

					this.render.sprites[this.tree_sid].prefix = old_prefix
					this.render.sprites[this.tree_sid].name = this.unit_idle_anim
					this.tower_upgrade_persistent_data.dead = false
					this._first_frame_dead = true

					spawn_unit()
				end
			end

			coroutine.yield()
		end
	end
end

scripts.soldier_tree = {}

function scripts.soldier_tree.insert(this, store)
	local tower_base = store.entities[this.soldier.tower_id]

	if tower_base.tower_upgrade_persistent_data.soldier_name_key then
		this.info.i18n_key = tower_base.tower_upgrade_persistent_data.soldier_name_key
	end

	return true
end

function scripts.soldier_tree.update(this, store, script)
	local tower_base = store.entities[this.soldier.tower_id]
	local brk, sta
	local pow_a = this.powers and this.powers.skill_a or nil
	local pow_b = this.powers and this.powers.skill_b or nil
	local pow_c = this.powers and this.powers.skill_c or nil
	local saa = this.timed_attacks and this.timed_attacks.list[1] or nil
	local sba = this.timed_attacks and this.timed_attacks.list[2] or nil
	local sua = this.timed_attacks and this.timed_attacks.list[3] or nil
	local tb_saa = tower_base.timed_attacks and tower_base.timed_attacks.list[1] or nil
	local tb_sba = tower_base.timed_attacks and tower_base.timed_attacks.list[4] or nil
	local tb_sua = tower_base.timed_attacks and tower_base.timed_attacks.list[3] or nil

	if sua then
		sua.disabled = not tower_base.powers.ultimate.active
	end

	local damage_factor_prev = this.health.damage_factor
	local mods = {}

	if this.vis._bans then
		this.vis.bans = this.vis._bans
		this.vis._bans = nil
	end

	this.nav_rally._first_time = not this.return_to_tower

	local aura_sa, aura_sc

	local function walk_break_fn()
		return false
	end

	local function y_soldier_new_rally_break_attack(store, this, break_fn)
		local r = this.nav_rally
		local out = false
		local vis_bans = this.vis.bans
		local prev_immune = this.health.immune_to

		this.health.immune_to = r.immune_to
		this.vis.bans = F_ALL

		local function on_change_rally()
			out = false

			U.set_destination(this, r.pos)

			local an, af = U.animation_name_facing_point(this, "walk", this.motion.dest)

			U.animation_start(this, an, af, store.tick_ts, -1)

			r.new = false
		end

		if r.new then
			r.new = false

			U.unblock_target(store, this)
			U.set_destination(this, r.pos)

			local an, af = U.animation_name_facing_point(this, "walk", this.motion.dest)

			U.animation_start(this, an, af, store.tick_ts, -1)

			while not this.motion.arrived do
				if this.health.dead or this.unit.is_stunned then
					out = true

					goto label_757_0
				end

				if r.new then
					on_change_rally()
				end

				if break_fn() then
					out = false

					goto label_757_0
				end

				if r._first_time then
					r._first_time = false

					local target = U.find_foremost_enemy(store.entities, r.center, 0, this.melee.range, false, F_BLOCK, bit.bor(F_CLIFF), function(e)
						return (not e.enemy.max_blockers or #e.enemy.blockers == 0) and band(GR:cell_type(e.pos.x, e.pos.y), TERRAIN_NOWALK) == 0 and (not this.melee.fn_can_pick or this.melee.fn_can_pick(this, e))
					end)

					if target then
						out = false

						goto label_757_0
					end
				end

				U.walk(this, store.tick_length)
				coroutine.yield()

				if r.new then
					on_change_rally()
				end

				this.motion.speed.x, this.motion.speed.y = 0, 0
			end

			if tower_base.tower_upgrade_persistent_data.returning_to_tower and this.return_to_tower and not this.arrived_to_tower then
				this.return_to_tower = false
				this.arrived_to_tower = true
			end
		end

		::label_757_0::

		this.vis.bans = vis_bans
		this.health.immune_to = prev_immune

		return out
	end

	local function check_tower_damage_factor()
		if store.entities[this.soldier.tower_id] then
			for _, a in ipairs(this.melee.attacks) do
				if not a._original_damage_min then
					a._original_damage_min = a.damage_min
				end

				if not a._original_damage_max then
					a._original_damage_max = a.damage_max
				end

				a.damage_min = a._original_damage_min * store.entities[this.soldier.tower_id].tower.damage_factor
				a.damage_max = a._original_damage_max * store.entities[this.soldier.tower_id].tower.damage_factor
			end
		end
	end

	local function spawn_skill_a_pool(a, pi, spi, ni)
		local decal = E:create_entity(a.decal)
		local aura = E:create_entity(a.aura)
		local np = P:node_pos(pi, spi, ni + math.random(a.min_cloud_node_offset, a.max_cloud_node_offset))

		aura.pos.x, aura.pos.y = np.x, np.y

		queue_insert(store, aura)

		decal.pos.x, decal.pos.y = np.x, np.y
		decal.render.sprites[1].ts = store.tick_ts

		queue_insert(store, decal)
	end

	local function check_power_upgrades()
		if this.powers then
			for pn, p in pairs(this.powers) do
				if p.changed then
					p.changed = nil

					SU.soldier_power_upgrade(this, pn)

					if p.level > 0 then
						if p == this.powers.skill_a then
							saa.disabled = false
							saa.cooldown = pow_a.cooldown[p.level]
							saa.aura = "aura_tree_unit_skill_a_blind_lvl" .. p.level
						elseif p == this.powers.skill_b then
							sba.disabled = false
							sba.cooldown = pow_b.cooldown[p.level]
							sba.min_hp_max = pow_b.min_hp_max[p.level]
							sba.max_hp_max = pow_b.max_hp_max[p.level]
						end
					end
				end
			end
		end
	end

	local function shoot_bullet(attack, target_pos)
		local b = E:create_entity(attack.bullet)

		b.bullet.damage_factor = store.entities[this.soldier.tower_id].tower.damage_factor
		b.pos.x, b.pos.y = this.pos.x + (this.render.sprites[1].flip_x and -1 or 1) * attack.bullet_start_offset.x, this.pos.y + attack.bullet_start_offset.y
		b.bullet.from = V.vclone(b.pos)
		b.bullet.to = target_pos
		b.bullet.source_id = this.id
		b.bullet.level = 1

		queue_insert(store, b)
	end

	while true do
		check_power_upgrades()

		if this.health.dead then
			this.ui.can_click = false

			SU.y_soldier_death(store, this)

			return
		end

		if this.unit.is_stunned then
			SU.soldier_idle(store, this)
		else
			while this.nav_rally.new do
				if y_soldier_new_rally_break_attack(store, this, walk_break_fn) then
					goto label_755_0
				end
			end

			check_tower_damage_factor()

			brk, sta = SU.y_soldier_melee_block_and_attacks(store, this)

			if not brk then
				if saa and not saa.disabled and tb_saa and store.tick_ts - tb_saa.ts > saa.cooldown then
					local aa = saa
					local trigger_enemy, enemies, pred_pos = U.find_foremost_enemy(store.entities, this.pos, 0, aa.range, 0, aa.vis_flags, aa.vis_bans)

					if not trigger_enemy or enemies and #enemies < aa.min_targets then
						SU.delay_attack(store, aa, fts(10))
					elseif enemies and #enemies < aa.min_targets then
						SU.delay_attack(store, aa, fts(10))
					else
						U.animation_start(this, aa.animation, nil, store.tick_ts, false, this.tree_sid)
						S:queue(aa.sound, {
							delay = fts(4)
						})
						U.y_wait(store, aa.cast_time)

						local p = {
							trigger_enemy.nav_path.pi
						}
						local nn = P:nearest_nodes(this.pos.x, this.pos.y, p, {
							1
						})[1]

						if aa.aura_count % 2 == 0 then
							for i = 1, aa.aura_count / 2 do
								local aux = nn[3] + i * aa.node_separation * (i == 1 and 0.5 or 1)

								spawn_skill_a_pool(aa, nn[1], nn[2], aux)

								aux = nn[3] - i * aa.node_separation * (i == 1 and 0.5 or 1)

								spawn_skill_a_pool(aa, nn[1], nn[2], aux)
								U.y_wait(store, aa.wait_between_clouds)
							end
						else
							local aux = nn[3]

							spawn_skill_a_pool(aa, nn[1], nn[2], aux)
							U.y_wait(store, aa.wait_between_clouds)

							for i = 1, (aa.aura_count - 1) / 2 do
								aux = nn[3] + i * aa.node_separation

								spawn_skill_a_pool(aa, nn[1], nn[2], aux)

								aux = nn[3] - i * aa.node_separation

								spawn_skill_a_pool(aa, nn[1], nn[2], aux)
								U.y_wait(store, aa.wait_between_clouds)
							end
						end

						tb_saa.ts = store.tick_ts

						U.y_animation_wait(this, this.tree_sid)
					end
				end

				if sba and not sba.disabled and tb_sba and store.tick_ts - tb_sba.ts > sba.cooldown and this.soldier.target_id ~= nil and this.motion.arrived and store.entities[this.soldier.target_id] and not store.entities[this.soldier.target_id].health.dead and store.entities[this.soldier.target_id].health.hp_max >= sba.min_hp_max and store.entities[this.soldier.target_id].health.hp_max <= sba.max_hp_max and band(store.entities[this.soldier.target_id].health.immune_to, DAMAGE_INSTAKILL) == 0 and band(store.entities[this.soldier.target_id].vis.flags, F_MINIBOSS) == 0 then
					local aa = sba

					U.animation_start(this, aa.animation, nil, store.tick_ts, false, this.tree_sid)
					S:queue(aa.sound, {
						delay = fts(5)
					})
					U.y_wait(store, aa.hit_time)

					local attack = E:create_entity(aa.instakill)

					attack.damage_type = aa.damage_type
					attack.target_id = this.soldier.target_id
					attack.source_id = this.id

					queue_insert(store, attack)

					tb_sba.ts = store.tick_ts

					U.y_animation_wait(this, this.tree_sid)
				end

				if sua and not sua.disabled and tb_sua and store.tick_ts - tb_sua.ts > sua.cooldown then
					local aa = sua
					local t_bullet = E:get_template(aa.bullet)
					local t_seed = E:get_template(t_bullet.bullet.hit_payload)
					local pred_time = aa.shoot_time + t_bullet.bullet.flight_time
					local target_enemy, _, pred_pos = U.find_foremost_enemy(store.entities, this.pos, 0, aa.range, pred_time, aa.vis_flags, aa.vis_bans)

					if not target_enemy then
						SU.delay_attack(store, aa, fts(10))
					else
						U.animation_start(this, aa.animation, false, store.tick_ts, false, this.tree_sid)
						U.y_wait(store, aa.shoot_time)
						shoot_bullet(aa, pred_pos)
						S:queue(aa.sound)

						tb_sua.ts = store.tick_ts

						signal.emit("tower-ultimate-used", this)
						U.y_animation_wait(this, this.tree_sid)
					end
				end
			end

			if brk or sta ~= A_NO_TARGET then
				-- block empty
			elseif SU.soldier_go_back_step(store, this) then
				-- block empty
			else
				SU.soldier_idle(store, this)
				SU.soldier_regen(store, this)
			end
		end

		::label_755_0::

		coroutine.yield()
	end
end

scripts.aura_tree_attack_roots = {}

function scripts.aura_tree_attack_roots.update(this, store, script)
	local enemies = U.find_targets_in_range(store.entities, this.pos, 0, this.aura.radius, this.aura.vis_flags, this.aura.vis_bans)

	if not enemies then
		queue_remove(store, this)

		return
	end

	local i = 0

	for k, e in pairs(enemies) do
		i = i + 1

		if i > this.max_enemies_to_show_roots then
			break
		end

		local aura = E:create_entity(this.t_aura)

		aura.pos.x, aura.pos.y = e.pos.x, e.pos.y

		queue_insert(store, aura)
	end

	queue_remove(store, this)
end

scripts.aura_tree_unit_roots_hit = {}

function scripts.aura_tree_unit_roots_hit.update(this, store, script)
	local positions = generate_blue_noise_cluster(math.random(this.amount_min, this.amount_max), 10, random_point_in_ellipse, this.pos.x, this.pos.y, this.aura.radius, this.aura.radius * 0.7)

	shuffle_table(positions)

	local h = {}

	for i, p in ipairs(positions) do
		if not this.within_path or P:valid_node_nearby(p.x, p.y) then
			local root = E:create_entity(this.to_spawn[get_random_round_robin(h, 1, #this.to_spawn)])

			root.pos.x, root.pos.y = p.x, p.y
			root.render.sprites[1].ts = store.tick_ts

			queue_insert(store, root)
			U.y_wait(store, U.frandom(this.wait_between_roots_min, this.wait_between_roots_max))
		end
	end

	queue_remove(store, this)
end

scripts.decal_tree_skill_b_instakill = {}

function scripts.decal_tree_skill_b_instakill.insert(this, store, script)
	local target = store.entities[this.target_id]

	U.animation_start(target, "idle", nil, store.tick_ts, true, 1)

	target.render.sprites[1].track_attach_point = "hand"
	target.render.sprites[1].track_sprite_id = 1
	target.render.sprites[1].track_id = this.id

	local flip_i = target.render.sprites[1].flip_x and -1 or 1

	target.render.sprites[1].offset = V.v(target.render.sprites[1].offset.x + flip_i * this.offset_pos_unit.x, target.render.sprites[1].offset.y + this.offset_pos_unit.y)
	target.render.sprites[1].r = target.render.sprites[1].r + flip_i * this.offset_rot_unit

	SU.stun_inc(target)

	this.pos.x, this.pos.y = target.pos.x, target.pos.y
	this.render.sprites[1].draw_order = target.render.sprites[1].draw_order and target.render.sprites[1].draw_order + 1 or 1

	return true
end

function scripts.decal_tree_skill_b_instakill.update(this, store, script)
	U.animation_start(this, "run", nil, store.tick_ts, nil, 1)
	U.y_wait(store, this.time_to_kill)

	local fx = E:create_entity(this.cover)

	fx.pos.x, fx.pos.y = this.pos.x, this.pos.y
	fx.render.sprites[1].scale = this.cover_scale
	fx.render.sprites[1].ts = store.tick_ts

	queue_insert(store, fx)

	local d = E:create_entity("damage")

	d.damage_type = bor(this.damage_type, DAMAGE_FX_NOT_EXPLODE, DAMAGE_NO_SPAWNS)
	d.target_id = this.target_id
	d.source_id = this.source_id

	queue_damage(store, d)

	local target = store.entities[this.target_id]

	target.render.sprites[1].hidden = true
	target.render.sprites[1].track_attach_point = nil
	target.render.sprites[1].track_sprite_id = nil
	target.render.sprites[1].track_id = nil
	target.unit.show_blood_pool = false

	U.y_animation_wait(this, 1, 1)
	queue_remove(store, this)
end

scripts.decal_tree_ultimate_bomb = {}

function scripts.decal_tree_ultimate_bomb.update(this, store, script)
	U.animation_start(this, "landandspawnunit", nil, store.tick_ts, nil, 1)
	U.y_wait(store, this.time_to_blow)

	local aura = E:create_entity(this.t_aura)

	aura.pos.x, aura.pos.y = this.pos.x, this.pos.y

	queue_insert(store, aura)

	for i = 1, this.spawn_count do
		local s = E:create_entity(this.t_seedling)
		local a = 2 * math.pi / this.spawn_count

		s.nav_rally.pos, s.nav_rally.center = U.point_on_ellipse(this.pos, this.rally_radius, (i - 1) * a - math.pi / 2 + math.pi / 4), this.pos
		s.pos.x, s.pos.y = s.nav_rally.pos.x, s.nav_rally.pos.y
		s.reinforcement.squad_id = this.source_id

		queue_insert(store, s)
	end

	S:queue(this.sound)
	U.y_animation_wait(this, 1, 1)
	queue_remove(store, this)
end

scripts.decal_stage_16_treant_killer_bomb = {}

function scripts.decal_stage_16_treant_killer_bomb.update(this, store)
	U.animation_start(this, "run", nil, store.tick_ts, nil, 1)
	U.y_wait(store, this.spawn_time)

	if this.t_enemy then
		local nodes = P:nearest_nodes(this.pos.x, this.pos.y, nil, {
			1,
			2,
			3
		}, true)
		local n = nodes and nodes[1]

		if n and P:is_node_valid(n[1], n[3]) then
			local e = E:create_entity(this.t_enemy)

			e.nav_path.pi = n[1]
			e.nav_path.spi = n[2]
			e.nav_path.ni = n[3]

			queue_insert(store, e)

			if not U.is_seen(store, this.t_enemy) then
				signal.emit("wave-notification", "icon", this.t_enemy)
				U.mark_seen(store, this.t_enemy)
			end
		end
	end

	S:queue(this.sound)
	U.y_wait(store, this.time_to_blow - this.spawn_time)

	local aura = E:create_entity(this.t_aura)

	aura.pos.x, aura.pos.y = this.pos.x, this.pos.y

	queue_insert(store, aura)
	U.y_animation_wait(this, 1, 1)
	queue_remove(store, this)
end

scripts.bullet_stage_16_treant_killer_bomb = {}

function scripts.bullet_stage_16_treant_killer_bomb.insert(this, store, script)
	if not scripts.bomb_KR6.insert(this, store, script) then
		return false
	end

	local angle = V.angleTo(this.bullet.speed.x, this.bullet.speed.y)

	this.render.sprites[1].r = angle

	U.animation_start(this, "run", nil, store.tick_ts, true, 1)

	return true
end

scripts.soldier_tree_ultimate_seedling = {}

function scripts.soldier_tree_ultimate_seedling.insert(this, store, script)
	if this.melee then
		this.melee.order = U.attack_order(this.melee.attacks)
	end

	if this.info and this.info.random_name_format then
		this.info.i18n_key = string.format(string.gsub(this.info.random_name_format, "_NAME", ""), math.random(this.info.random_name_count))
	end

	return true
end

function scripts.soldier_tree_ultimate_seedling.update(this, store, script)
	local brk, stam, star, on_optional_idle
	local last_idle_ts = store.tick_ts
	local idle_cd = U.frandom(this.idle_when_cd * 0.5, this.idle_when_cd)

	this.reinforcement.ts = store.tick_ts
	this.render.sprites[1].ts = store.tick_ts

	U.y_animation_play(this, "spawn", nil, store.tick_ts, 1)

	if not this.health.dead then
		this.health_bar.hidden = nil
	end

	while true do
		if this.health.dead or this.reinforcement.duration and store.tick_ts - this.reinforcement.ts > this.reinforcement.duration then
			if not this.health.dead then
				this.health.hp = 0
				this.health.dead = true
				this.health.death_ts = store.tick_ts
				this.health.delete_after = store.tick_ts + this.health.dead_lifetime
			end

			this.health_bar.hidden = true

			SU.y_soldier_death(store, this)

			return
		end

		if this.unit.is_stunned then
			SU.soldier_idle(store, this)
		else
			if this.melee then
				brk, stam = SU.y_soldier_melee_block_and_attacks(store, this)

				if brk or stam == A_DONE or stam == A_IN_COOLDOWN and not this.melee.continue_in_cooldown then
					goto label_772_0
				end
			end

			if this.melee.continue_in_cooldown and stam == A_IN_COOLDOWN then
				-- block empty
			elseif SU.soldier_go_back_step(store, this) then
				-- block empty
			else
				if this.idle_when_cd and idle_cd < store.tick_ts - last_idle_ts then
					U.animation_start(this, this.idle_when_anim, nil, store.tick_ts, false, 1)

					last_idle_ts = store.tick_ts
					idle_cd = U.frandom(0, this.idle_when_cd)
					on_optional_idle = true
				end

				if not on_optional_idle and U.animation_finished(this, 1) then
					SU.soldier_idle(store, this)
				end

				SU.soldier_regen(store, this)
			end
		end

		::label_772_0::

		coroutine.yield()
	end
end

scripts.tower_miners = {}

function scripts.tower_miners.insert(this, store, script)
	local res = scripts.tower_barrack.insert(this, store, script)

	if not res then
		return false
	end

	this.gold_cap_controller = store.ephemeral.miners_gold_cap_controller or find_all_t(store, this.gold_cap_controller_t)[1]

	if not this.gold_cap_controller then
		this.gold_cap_controller = E:create_entity(this.gold_cap_controller_t)

		queue_insert(store, this.gold_cap_controller)
	end

	store.ephemeral.miners_gold_cap_controller = this.gold_cap_controller

	scripts.controller_miners_global_gold_cap.sync_wave(this.gold_cap_controller, store)

	return res
end

function scripts.tower_miners.update(this, store, script)
	local WORKING_MODE = 1
	local CAPPED_MODE = 2
	local DISABLED_MODE = 3
	local FIGHTING_MODE = 4
	local NO_SOLDIERS_MODE = 5

	this.mode_animation_map = {
		[WORKING_MODE] = {
			"farm_loop",
			true
		},
		[CAPPED_MODE] = {
			"idle",
			true
		},
		[DISABLED_MODE] = {
			"idle",
			true
		},
		[FIGHTING_MODE] = {
			"idle",
			true
		},
		[NO_SOLDIERS_MODE] = {
			"idle",
			true
		}
	}

	local td = this.tower_upgrade_persistent_data
	local b = this.barrack
	local gg = this.gold_generation
	local tower_sid = 2
	local gate_sid = 3
	local whistle_sid = this.tower.level == 4 and 4 or 3
	local pow_a = this.powers and this.powers.skill_a or nil
	local pow_b = this.powers and this.powers.skill_b or nil
	local pow_c = this.powers and this.powers.skill_c or nil
	local ult = this.powers and this.powers.ultimate or nil
	local gold_tick_reduction = 0
	local gold_tick_bonus = 0
	local ts_idx = 2
	local ts = this.render.sprites[ts_idx]
	local spawn_soldier_ts = store.tick_ts - this.spawn_soldier_interval
	local boss_spawn_soldier_ts = store.tick_ts - this.boss_spawn_soldier_interval
	local mode_pre_block = WORKING_MODE
	local soldier_t = E:get_template(b.soldier_type)
	local respawn_time = soldier_t.health.dead_lifetime * 0.7
	local tunnel_return_time = soldier_t.tunneling_time + fts(15)

	local function change_animation(mode, ts)
		U.animation_start(this, this.mode_animation_map[mode][1], nil, ts, this.mode_animation_map[mode][2], ts_idx)
	end

	local function gold_generation_capped()
		scripts.controller_miners_global_gold_cap.sync_wave(this.gold_cap_controller, store)

		return this.gold_cap_controller and this.gold_cap_controller.gold_accum >= this.gold_cap_controller.gold_cap_per_wave
	end

	local function prune_soldiers()
		for i = #b.soldiers, 1, -1 do
			local s = b.soldiers[i]

			if not store.entities[s.id] or s.health.dead and store.tick_ts - (s.health.death_ts or 0) >= respawn_time then
				table.remove(b.soldiers, i)
			end
		end
	end

	local function check_spawn_soldier()
		prune_soldiers()

		if store.tick_ts - spawn_soldier_ts <= this.spawn_soldier_interval then
			return
		end

		if #b.soldiers >= b.max_soldiers then
			return
		end

		local e = U.find_foremost_enemy(store.entities, tpos(this), 0, b.rally_range, nil, F_BLOCK, bit.bor(F_FLYING, F_CLIFF), function(e)
			return #e.enemy.blockers == 0 and band(GR:cell_type(e.pos.x, e.pos.y), TERRAIN_NOWALK) == 0 and (band(e.vis.flags, F_BOSS) == 0 or store.tick_ts - boss_spawn_soldier_ts > this.boss_spawn_soldier_interval)
		end)

		if not e then
			return
		end

		spawn_soldier_ts = store.tick_ts

		if band(e.vis.flags, F_BOSS) ~= 0 then
			boss_spawn_soldier_ts = store.tick_ts
		end

		local s = E:create_entity(b.soldier_type)

		s.soldier.tower_id = this.id
		s.first_enemy_id = e.id
		s.pos = V.v(V.add(this.pos.x, this.pos.y, b.respawn_offset.x, b.respawn_offset.y))
		s.nav_rally.pos, s.nav_rally.center = V.vv(0), V.vv(0)

		if pow_b and pow_b.level > 0 then
			s.powers.skill_b.level = pow_b.level
		end

		b.soldiers[#b.soldiers + 1] = s

		queue_insert(store, s)
		signal.emit("tower-spawn", this, s)
	end

	local function y_enter_fighting_mode()
		if this.render.sprites[whistle_sid] then
			U.animation_start(this, "unit_deploy", nil, store.tick_ts, false, whistle_sid)
		end
	end

	local function y_leave_fighting_mode()
		local waiting = false

		for _, s in pairs(this.barrack.soldiers) do
			if not s.health.dead then
				s._tower_will_remove = true

				if not s._burrowed and not s.unit.is_stunned then
					U.animation_start(s, "buriedIn", nil, store.tick_ts, false, 1)

					s.health_bar.hidden = true

					U.y_wait(store, fts(math.random(1, 10)))
				end

				waiting = true
			end
		end

		while waiting do
			local finished = true

			for _, s in pairs(this.barrack.soldiers) do
				if store.entities[s.id] and not s.health.dead and not U.animation_finished(s, 1) then
					finished = false

					break
				end
			end

			if finished then
				break
			end

			coroutine.yield()
		end

		for _, s in pairs(this.barrack.soldiers) do
			if s.health and s.health.dead then
				-- block empty
			else
				if s.health then
					s.health.dead = true
				end

				s.render.sprites[1].hidden = true

				queue_remove(store, s)
			end
		end

		if waiting then
			U.y_wait(store, tunnel_return_time)
		end
	end

	local function change_mode(nm)
		td.gold_rush = nil

		if td.mode == FIGHTING_MODE then
			y_leave_fighting_mode()
		end

		if nm == FIGHTING_MODE then
			y_enter_fighting_mode()
		end

		td.mode = nm
		td.gold_ts = store.tick_ts
		td.mode_switch_ts = store.tick_ts

		change_animation(td.mode, store.tick_ts)
	end

	local DETECT_SCAN_INTERVAL = fts(6)
	local detect_last_ts, detect_last_result = nil, false

	local function detect_enemies_to_block()
		if detect_last_ts and store.tick_ts - detect_last_ts < DETECT_SCAN_INTERVAL then
			return detect_last_result
		end

		detect_last_ts = store.tick_ts

		local e, enemies = U.find_foremost_enemy(store.entities, tpos(this), 0, b.rally_range, nil, F_BLOCK, bit.bor(F_FLYING, F_CLIFF), function(e)
			return (not e.enemy.max_blockers or #e.enemy.blockers == 0) and band(GR:cell_type(e.pos.x, e.pos.y), TERRAIN_NOWALK) == 0
		end)

		detect_last_result = e and enemies and #enemies > 0

		return detect_last_result
	end

	local function detect_soldiers_blocking()
		for _, s in pairs(this.barrack.soldiers) do
			if s.health and not s.health.dead and (s.soldier.target_id or s._in_transit or s.unit.is_stunned) then
				return true
			end
		end

		return false
	end

	local function generate_gold(value)
		local diff_to_max = this.gold_cap_controller.gold_cap_per_wave - this.gold_cap_controller.gold_accum
		local final_value = km.clamp(1, diff_to_max, km.round(value))
		local v = V.v(this.pos.x + this.gold_effect_offset.x, this.pos.y + this.gold_effect_offset.y)

		signal.emit("got-gold", v, final_value, "tower_miners")

		this.gold_cap_controller.gold_accum = this.gold_cap_controller.gold_accum + final_value
	end

	local function check_generate_gold(factor)
		local tick_cooldown = td.gold_rush and ult.tick_cooldown or gg.tick_cooldown

		if not gold_generation_capped() and tick_cooldown <= store.tick_ts - td.gold_ts then
			local min_gold, max_gold = gg.min_gold, gg.max_gold

			if td.gold_rush then
				min_gold, max_gold = ult.min_gold, ult.max_gold
			end

			local v = U.frandom(min_gold * factor, max_gold * factor)

			generate_gold(v)

			td.gold_ts = store.tick_ts
		end
	end

	local function apply_tower_upgrade()
		change_animation(td.mode, td.mode_switch_ts)
	end

	local carried_over = {}

	for i = 1, b.max_soldiers do
		if b.soldiers[i] then
			carried_over[#carried_over + 1] = b.soldiers[i]
		end
	end

	b.soldiers = carried_over

	apply_tower_upgrade()

	if not td.gold_ts then
		td.gold_ts = store.tick_ts
	end

	if not td.ult_acum then
		td.ult_acum = 0
	end

	td.gold_rush = nil

	while true do
		if this.powers then
			for k, pow in pairs(this.powers) do
				if pow.changed then
					pow.changed = nil

					if pow == pow_a then
						if not this.controller_skill_a then
							this.controller_skill_a = E:create_entity(pow_a.controller_t)
							this.controller_skill_a.pos = V.vclone(this.pos)
							this.controller_skill_a.tower_miners = this

							queue_insert(store, this.controller_skill_a)
						end

						this.controller_skill_a.cooldown = pow.cooldown[pow.level]
						this.controller_skill_a.soldier_t = pow.templates_levels[pow.level]
						this.controller_skill_a.cart_level = pow.level
					end

					if pow == pow_c then
						U.animation_start(this, "reserve miners loop", nil, store.tick_ts, true, 5)
					end
				end
			end
		end

		if td.mode ~= DISABLED_MODE and this.tower.blocked then
			mode_pre_block = td.mode

			change_mode(DISABLED_MODE)
		end

		if td.mode == DISABLED_MODE then
			if store.wave_group_number > 0 and not this.tower.blocked then
				change_mode(mode_pre_block)
			end
		else
			if ult and ult.active and not td.gold_rush and not gold_generation_capped() then
				if td.mode == WORKING_MODE then
					td.ult_acum = td.ult_acum + store.tick_length

					if td.ult_acum >= ult.cooldown then
						td.ult_acum = 0
						td.gold_rush = true
						td.gold_rush_acum = 0

						U.animation_start(this, "ultimate", nil, store.tick_ts, false, tower_sid)
						signal.emit("tower-ultimate-used", this)
					end
				elseif pow_c and pow_c.level > 0 then
					td.ult_acum = td.ult_acum + store.tick_length * ult.skill_c_cooldown_factor
				end
			end

			if td.mode == WORKING_MODE then
				check_generate_gold(1)

				if detect_enemies_to_block() then
					change_mode(FIGHTING_MODE)

					goto label_774_0
				end

				if gold_generation_capped() then
					change_mode(CAPPED_MODE)

					goto label_774_0
				end

				if td.gold_rush then
					td.gold_rush_acum = td.gold_rush_acum + store.tick_length

					if td.gold_rush_acum >= ult.duration then
						td.gold_rush = false
						td.ult_acum = 0
						td.gold_rush_acum = 0

						U.animation_start(this, "farm_loop", nil, store.tick_ts, true, tower_sid)
					end
				end
			end

			if td.mode == CAPPED_MODE then
				if detect_enemies_to_block() then
					change_mode(FIGHTING_MODE)

					goto label_774_0
				end

				if not gold_generation_capped() then
					change_mode(WORKING_MODE)

					goto label_774_0
				end
			end

			if td.mode == FIGHTING_MODE then
				if pow_c and pow_c.level > 0 then
					check_generate_gold(pow_c.gold_factor[pow_c.level])
				end

				check_spawn_soldier()

				if not detect_enemies_to_block() and not detect_soldiers_blocking() then
					change_mode(WORKING_MODE)
				end
			end
		end

		::label_774_0::

		coroutine.yield()
	end
end

function scripts.tower_miners.remove(this, store, script)
	if this.controller_skill_a then
		queue_remove(store, this.controller_skill_a)
	end

	local skill_a_spawns = table.filter(store.entities, function(k, v)
		return v.tower_id == this.id and (v.template_name == "decal_miners_cart_skill_a" or string.find(v.template_name, "soldier_miners_skill_a_lvl"))
	end)

	for k, v in pairs(skill_a_spawns) do
		queue_remove(store, v)
	end

	return scripts.tower_barrack.remove(this, store, script)
end

scripts.controller_miners_global_gold_cap = {}

function scripts.controller_miners_global_gold_cap.sync_wave(this, store)
	if this.wave ~= store.wave_group_number then
		this.wave = store.wave_group_number
		this.gold_accum = 0
	end
end

function scripts.controller_miners_global_gold_cap.update(this, store, script)
	while true do
		scripts.controller_miners_global_gold_cap.sync_wave(this, store)
		coroutine.yield()
	end
end

scripts.controller_miners_skill_a = {}

function scripts.controller_miners_skill_a.update(this, store, script)
	local ts = store.tick_ts - this.cooldown
	local cart_launched = false
	local tower = this.tower_miners
	local tower_sid = 2
	local tower_base_sid = 3
	local valid_paths = {}
	local nearest_nodes_per_path = P:nearest_nodes(tower.pos.x, tower.pos.y, nil, nil, true)

	for _, nn in ipairs(nearest_nodes_per_path) do
		if nn[4] <= this.path_detection_range then
			table.insert(valid_paths, nn[1])
		end
	end

	while true do
		if store.tick_ts - ts > this.cooldown and not cart_launched and tower.tower_upgrade_persistent_data.mode ~= 3 then
			local targets = U.find_enemies_in_range(store.entities, this.pos, 0, this.max_range, 0, this.bans, function(v, o)
				return table.contains(valid_paths, v.nav_path.pi)
			end)

			if not targets or #targets < this.min_targets then
				goto label_793_0
			end

			local pi, ni

			for _, t in ipairs(targets) do
				local nearest = P:nearest_nodes(this.pos.x, this.pos.y, {
					t.nav_path.pi
				})

				if nearest and #nearest > 0 then
					local npi, nspi, nni = unpack(nearest[1])

					if nni > t.nav_path.ni then
						pi, ni = npi, nni

						break
					end
				end
			end

			if not pi then
				goto label_793_0
			end

			local pos = P:node_pos(pi, 1, ni)

			if not point_in_valid_path(pos.x, pos.y, {
				pi
			}) then
				goto label_793_0
			end

			U.y_animation_play(tower, "skill03", nil, store.tick_ts, 1, tower_base_sid)
			U.animation_start(tower, "idle", nil, store.tick_ts, true, tower_base_sid)

			local c = E:create_entity(this.cart_t)

			c.pos = V.v(tower.pos.x + tower.cart_start_offset.x, tower.pos.y + tower.cart_start_offset.y)
			c.nav_path.pi = pi
			c.nav_path.spi = 1
			c.nav_path.ni = ni
			c.nav_path.dir = -1
			c.damage_min = this.cart_damage_min[this.cart_level]
			c.damage_max = this.cart_damage_max[this.cart_level]
			c.soldier_t = this.soldier_t
			c.controller = this
			c.tower_id = tower.id

			queue_insert(store, c)

			cart_launched = true
			this.cart_done = false
		end

		if this.cart_done and cart_launched then
			ts = store.tick_ts
			cart_launched = false
		end

		::label_793_0::

		coroutine.yield()
	end
end

scripts.decal_miners_cart_skill_a = {}

function scripts.decal_miners_cart_skill_a.update(this, store, script)
	local nodes_traveled = 0
	local last_an, last_af
	local diag_tan = math.tan(math.rad(22.5))
	local ps = E:create_entity(this.ps_trail)

	ps.particle_system.track_id = this.id
	ps.particle_system.emit = true

	queue_insert(store, ps)

	local function update_cart_animation()
		local dx = this.motion.dest.x - this.pos.x
		local dy = this.motion.dest.y - this.pos.y

		if dx == 0 and dy == 0 then
			return
		end

		local adx, ady = math.abs(dx), math.abs(dy)
		local an, af

		if adx <= diag_tan * ady then
			an, af = dy > 0 and "up" or "down", false
		elseif ady <= diag_tan * adx then
			an, af = "left", dx < 0
		else
			an, af = dy > 0 and "diagonal_up" or "diagonal_down", dx < 0
		end

		if an ~= last_an or af ~= last_af then
			U.animation_start(this, an, af, store.tick_ts, true, 1)

			last_an, last_af = an, af

			local ps_offset = v(this.render.sprites[1].flip_x and this.particles_offsets[an].x or -this.particles_offsets[an].x, this.particles_offsets[an].y)

			ps.particle_system.track_offset = ps_offset

			if string.find(an, "down") then
				ps.particle_system.z = Z_DECALS
			else
				ps.particle_system.z = Z_OBJECTS
			end
		end
	end

	local function spawn_soldiers()
		for i = 1, this.soldiers_count do
			local ni_offset = i % 2 == 0 and 2 or -2
			local spos = P:node_pos(this.nav_path.pi, 1, this.nav_path.ni + ni_offset)
			local s = E:create_entity(this.soldier_t)

			s.pos = spos
			s.nav_rally.pos = V.vclone(spos)
			s.nav_rally.center = V.v(this.pos.x, this.pos.y)
			s.nav_rally.new = false
			s.tower_id = this.tower_id
			s.reinforcement.squad_id = this.id

			queue_insert(store, s)
		end
	end

	local function explode()
		local fx = E:create_entity(this.explosion_fx_t)

		fx.pos = V.vclone(this.pos)
		fx.render.sprites[1].ts = store.tick_ts

		queue_insert(store, fx)

		local enemies = table.filter(store.entities, function(k, v)
			return v.enemy and v.vis and v.unit and v.health and not v.health.dead and band(v.vis.flags, bor(F_FLYING, F_CLIFF)) == 0 and U.is_inside_ellipse(V.v(v.pos.x + v.unit.hit_offset.x, v.pos.y + v.unit.hit_offset.y), this.pos, this.damage_radius)
		end)

		for _, enemy in pairs(enemies) do
			local enemy_pos = V.v(enemy.pos.x + enemy.unit.hit_offset.x, enemy.pos.y + enemy.unit.hit_offset.y)
			local d = E:create_entity("damage")

			d.source_id = this.id
			d.target_id = enemy.id
			d.damage_type = this.damage_type

			local dist_factor = U.dist_factor_inside_ellipse(enemy_pos, this.pos, this.damage_radius)

			d.value = math.floor(this.damage_max - (this.damage_max - this.damage_min) * dist_factor)

			queue_damage(store, d)
		end

		spawn_soldiers()

		if this.controller then
			this.controller.cart_done = true
		end

		queue_remove(store, this)
	end

	while true do
		local next_node, new_node = P:next_entity_node(this, store.tick_length)

		if not next_node or not P:is_node_valid(this.nav_path.pi, this.nav_path.ni, NF_NO_BACKWARDS) or GR:cell_is(next_node.x, next_node.y, this.banned_terrains) then
			explode()

			return
		end

		if new_node then
			nodes_traveled = nodes_traveled + 1

			if nodes_traveled >= this.max_nodes then
				explode()

				return
			end
		end

		U.set_destination(this, next_node)
		update_cart_animation()
		U.walk(this, store.tick_length)

		local hits = U.find_enemies_in_range(store.entities, this.pos, 0, this.hit_radius, 0, bor(F_FLYING, F_CLIFF))

		if hits then
			explode()

			return
		end

		coroutine.yield()

		this.motion.speed.x, this.motion.speed.y = 0, 0
	end
end

scripts.soldier_miners_skill_a = {}

function scripts.soldier_miners_skill_a.update(this, store, script)
	if this.auras then
		for _, a in pairs(this.auras.list) do
			if a.cooldown == 0 then
				local e = E:create_entity(a.name)

				e.pos = V.vclone(this.pos)
				e.aura.level = this.unit.level
				e.aura.source_id = this.id
				e.aura.ts = store.tick_ts

				queue_insert(store, e)

				this._spawned_auras = this._spawned_auras or {}

				table.insert(this._spawned_auras, e)
			end
		end
	end

	this.health_bar.hidden = true

	U.y_animation_play(this, "spawn", nil, store.tick_ts, 1, 1)

	if not this.health.dead then
		this.health_bar.hidden = nil
	end

	return scripts.soldier_reinforcement_kr6.update(this, store, script)
end

function scripts.soldier_miners_skill_a.remove(this, store, script)
	if this._spawned_auras then
		for _, a in ipairs(this._spawned_auras) do
			if store.entities[a.id] then
				queue_remove(store, a)
			end
		end

		this._spawned_auras = nil
	end

	return true
end

scripts.soldier_miners = {}

function scripts.soldier_miners.get_info(this)
	local stats = scripts.soldier_barrack.get_info(this)
	local tower = E:get_template(this.tower_t)

	stats.respawn = tower.spawn_soldier_interval

	return stats
end

function scripts.soldier_miners.update(this, store)
	local brk, sta
	local tower = store.entities[this.soldier.tower_id]
	local ps_dust = E:create_entity(this.ps_trail_dust)

	ps_dust.particle_system.track_id = this.id

	queue_insert(store, ps_dust)

	local ps_ground = E:create_entity(this.ps_trail_ground)

	ps_ground.particle_system.track_id = this.id

	queue_insert(store, ps_ground)

	if this.vis._bans then
		this.vis.bans = this.vis._bans
		this.vis._bans = nil
	end

	this.nav_rally.pos = V.vv(0)
	this.nav_rally.center = V.vv(0)

	local unburrow_time = fts(15)
	local tunnel_cycle_time = unburrow_time + this.tunneling_time + unburrow_time
	local walk_range = this.normal_speed * tunnel_cycle_time
	local leaving_mine = V.dist2(this.pos.x, this.pos.y, tower.pos.x + tower.barrack.respawn_offset.x, tower.pos.y + tower.barrack.respawn_offset.y) < 4

	local function transferred_underground()
		local n = this.render.sprites[1].name

		if n == this.bury_in_anim then
			return true
		end

		for _, a in ipairs(this.render.sprites[1].angles.bury) do
			if n == a then
				return true
			end
		end

		return false
	end

	local underground = leaving_mine or transferred_underground()

	this._burrowed = underground
	this._in_transit = underground or nil

	if underground and not this.vis._bans then
		this.vis._bans = this.vis.bans
		this.vis.bans = F_ALL
	end

	local function other_soldiers_blocking()
		for _, s in pairs(tower.barrack.soldiers) do
			if not s.health.dead and s.soldier.target_id ~= nil and store.entities[s.soldier.target_id] and not store.entities[s.soldier.target_id].health.dead then
				return s.soldier.target_id
			end
		end

		return nil
	end

	local function predict_enemy_slot(target, pred)
		local p_offset = P:predict_enemy_node_advance(target, pred)
		local p_ni = target.nav_path.ni + p_offset
		local p_pos = P:node_pos(target.nav_path.pi, target.nav_path.spi, p_ni, true)
		local p_angle = target.heading.angle

		if p_offset > 0 then
			local next_p_pos = P:node_pos(target.nav_path.pi, target.nav_path.spi, p_ni + 1, true)

			p_angle = V.angleTo(next_p_pos.x - p_pos.x, next_p_pos.y - p_pos.y)
		end

		local rank = table.keyforobject(target.enemy.blockers, this.id) or 1
		local idx = km.zmod(rank, 3)
		local x_off, y_off = 0, 0

		if idx ~= 1 then
			x_off = this.soldier.melee_slot_spread and this.soldier.melee_slot_spread.x or -3
			y_off = this.soldier.melee_slot_spread and this.soldier.melee_slot_spread.y or -6

			if idx == 3 then
				y_off = -1 * y_off
			end
		end

		local on_the_right = math.abs(km.signed_unroll(p_angle)) < math.pi / 2

		return V.v(p_pos.x + (target.enemy.melee_slot.x + x_off + this.soldier.melee_slot_offset.x) * (on_the_right and 1 or -1), p_pos.y + target.enemy.melee_slot.y + y_off + this.soldier.melee_slot_offset.y)
	end

	local function go_underground(this)
		if not this.vis._bans then
			this.vis._bans = this.vis.bans
			this.vis.bans = F_ALL
		end
	end

	local function surface(this)
		this._burrowed = nil

		if this.vis._bans then
			this.vis.bans = this.vis._bans
			this.vis._bans = nil
		end

		if ps_dust then
			ps_dust.particle_system.emit = false
		end

		if ps_ground then
			ps_ground.particle_system.emit = false
		end

		if this.sound_surface and not this._skill_b_pending then
			S:queue(this.sound_surface)
		end
	end

	local function trigger_skill_b()
		if not this.powers or not this.powers.skill_b then
			return
		end

		local sb = this.powers.skill_b

		if sb.level <= 0 then
			return
		end

		local aura = E:create_entity(sb.auras[sb.level])

		aura.pos.x, aura.pos.y = this.pos.x, this.pos.y

		queue_insert(store, aura)

		for i, vi in ipairs(sb.visuals) do
			local visuals = E:create_entity(vi)

			visuals.pos.x, visuals.pos.y = this.pos.x, this.pos.y
			visuals.render.sprites[1].ts = store.tick_ts

			queue_insert(store, visuals)
		end
	end

	local function y_soldier_tunnel_or_walk_to_slot_step(store, this, target)
		if not leaving_mine and V.dist2(this.pos.x, this.pos.y, target.pos.x, target.pos.y) <= walk_range * walk_range then
			if this._burrowed then
				surface(this)
				U.y_animation_play(this, this.bury_out_anim, nil, store.tick_ts, 1, 1)

				this._in_transit = nil
			end

			return SU.soldier_move_to_slot_step(store, this, target), target
		end

		leaving_mine = false

		if not this._burrowed and not this._tower_will_remove then
			this._burrowed = true
			this._in_transit = true

			go_underground(this)
			U.y_animation_play(this, this.bury_in_anim, nil, store.tick_ts, 1, 1)
		end

		local dig_ts = store.tick_ts
		local dig_dest

		while true do
			if this._tower_will_remove then
				return true, target
			end

			if this.health.dead then
				return true, target
			end

			local remaining = this.tunneling_time - (store.tick_ts - dig_ts)
			local e_pos

			if target and store.entities[target.id] and not target.health.dead then
				e_pos = predict_enemy_slot(target, math.max(remaining, 0))

				if #target.enemy.blockers == 0 and not U.is_inside_ellipse(e_pos, tpos(tower), tower.barrack.rally_range) then
					e_pos = nil
				end
			end

			if not e_pos then
				e_pos = dig_dest or target and V.v(target.pos.x, target.pos.y) or V.v(this.pos.x, this.pos.y)

				if target then
					U.unblock_target(store, this)

					target = nil
				end
			end

			dig_dest = e_pos

			U.set_destination(this, e_pos)

			if target then
				U.block_enemy(store, this, target)
			end

			if remaining <= store.tick_length then
				this.pos.x, this.pos.y = e_pos.x, e_pos.y
				this.motion.arrived = true

				break
			end

			local an, af = U.animation_name_facing_point(this, "bury", this.motion.dest)

			U.animation_start(this, an, af, store.tick_ts, -1)

			this.motion.max_speed = V.dist(this.pos.x, this.pos.y, e_pos.x, e_pos.y) / remaining

			U.walk(this, store.tick_length)
			coroutine.yield()
		end

		this._skill_b_pending = this.powers and this.powers.skill_b and this.powers.skill_b.level and this.powers.skill_b.level > 0 or nil

		surface(this)

		this._skill_b_pending = nil

		trigger_skill_b()
		U.y_animation_play(this, this.bury_out_anim, nil, store.tick_ts, 1, 1)

		this._in_transit = nil
		this.motion.max_speed = this.normal_speed

		if not target then
			return false, nil
		end

		return SU.soldier_move_to_slot_step(store, this, target), target
	end

	local function y_burrow_idle_in_place_then_remove(store, this)
		if this._removing or this._tower_will_remove then
			return
		end

		this.motion.speed.x, this.motion.speed.y = 0, 0

		if not this._burrowed and not this._tower_will_remove then
			this._burrowed = true

			go_underground(this)
			U.y_animation_play(this, this.bury_in_anim, nil, store.tick_ts, 1, 1)

			this.render.sprites[1].hidden = true
		end

		this._removing = true

		queue_remove(store, this)
	end

	local function y_soldier_melee_tunnels_blocks_first_enemy(store, this)
		local on_route
		local target = store.entities[this.first_enemy_id]

		if not target then
			local target_id = other_soldiers_blocking()

			if target_id then
				target = store.entities[target_id]
			else
				if this._burrowed then
					surface(this)
					U.y_animation_play(this, this.bury_out_anim, nil, store.tick_ts, 1, 1)
				end

				this._in_transit = nil

				return false, A_NO_TARGET
			end
		end

		on_route, target = y_soldier_tunnel_or_walk_to_slot_step(store, this, target)

		if on_route or not target then
			return true
		end

		local attack = SU.soldier_pick_melee_attack(store, this, target)

		if not attack then
			return false, A_IN_COOLDOWN
		end

		local attack_done

		if attack.loops then
			attack_done = SU.y_soldier_do_loopable_melee_attack(store, this, target, attack)
		elseif attack.type == "area" then
			attack_done = SU.y_soldier_do_single_area_attack(store, this, target, attack)
		else
			attack_done = SU.y_soldier_do_single_melee_attack(store, this, target, attack)
		end

		if attack_done then
			return false, A_DONE
		else
			return true
		end
	end

	local tower_damage_factor = 1

	local function check_tower_damage_factor()
		if tower and tower.tower.damage_factor ~= tower_damage_factor then
			this.unit.damage_factor = this.unit.damage_factor / tower_damage_factor * tower.tower.damage_factor
			tower_damage_factor = tower.tower.damage_factor
		end
	end

	if underground then
		if not this.first_enemy_id then
			this.first_enemy_id = this.soldier.target_id
		end

		y_soldier_melee_tunnels_blocks_first_enemy(store, this)
	end

	this.nav_rally.pos, this.nav_rally.center = V.vclone(this.pos), V.vclone(this.pos)

	local idle_ts = store.tick_ts
	local idle = false

	while true do
		if this._tower_will_remove then
			-- block empty
		else
			if not this.health.dead or SU.y_soldier_revive(store, this) then
				-- block empty
			else
				SU.y_soldier_death(store, this)

				return
			end

			if this.unit.is_stunned then
				SU.soldier_idle(store, this)
			else
				check_tower_damage_factor()

				if this.dodge and this.dodge.active then
					this.dodge.active = false

					if this.dodge.counter_attack and this.powers[this.dodge.counter_attack.power_name].level > 0 then
						this.dodge.counter_attack_pending = true
					elseif this.dodge.animation then
						U.animation_start(this, this.dodge.animation, nil, store.tick_ts, 1)

						while not U.animation_finished(this) do
							coroutine.yield()
						end
					end

					signal.emit("soldier-dodge", this)
				end

				if this.melee then
					brk, sta = SU.y_soldier_melee_block_and_attacks(store, this)

					if not idle and sta == A_NO_TARGET then
						idle = true
						idle_ts = store.tick_ts
					end

					if brk or sta ~= A_NO_TARGET then
						idle = false

						goto label_803_0
					end
				end

				if SU.soldier_go_back_step(store, this) then
					-- block empty
				else
					if idle and store.tick_ts - idle_ts > 1.5 then
						y_burrow_idle_in_place_then_remove(store, this)
					end

					SU.soldier_regen(store, this)
					SU.soldier_idle(store, this)
				end
			end
		end

		::label_803_0::

		coroutine.yield()
	end
end

function scripts.soldier_miners.remove(this, store)
	return true
end

scripts.tower_forger = {}

function scripts.tower_forger.get_info(this)
	local info = scripts.tower_common.get_info(this)
	local bullet = E:get_template(this.attacks.list[1].bullet)

	info.damage_min = bullet.bullet.damage_min * this.tower.damage_factor
	info.damage_max = bullet.bullet.damage_max * this.tower.damage_factor
	info.cooldown = this.info.stat_cooldown
	info.type = STATS_TYPE_TOWER_MAGE
	info.range = this.attacks.range

	return info
end

function scripts.tower_forger.update(this, store)
	local pow_a = this.powers and this.powers.skill_a or nil
	local pow_b = this.powers and this.powers.skill_b or nil
	local pow_c = this.powers and this.powers.skill_c or nil
	local sa = this.timed_attacks and this.timed_attacks.list[1] or nil
	local sb = this.timed_attacks and this.timed_attacks.list[2] or nil
	local sc = this.timed_attacks and this.timed_attacks.list[3] or nil
	local ult_active = this.timed_attacks and this.timed_attacks.list[4] and this.powers.ultimate.active
	local ult = ult_active and this.timed_attacks.list[4] or nil
	local ult_start_cd = ult ~= nil and store.wave_group_number == 0

	if ult then
		ult.ts = store.tick_ts
	end

	local ba = this.attacks.list[1]

	ba.ts = store.tick_ts - ba.cooldown

	local last_ts = store.tick_ts
	local max_bullets = #ba.bullet_spawn_positions
	local sid_mage = this.render.sid_mage
	local bullets_suffixes = table.deepclone(ba.bullets_suffixes)
	local current_suffixes = {}

	this.discs = {}

	if not this.tower_upgrade_persistent_data.current_bullets then
		this.tower_upgrade_persistent_data.current_bullets = {}
	end

	local function get_last_bullet_index()
		local index = 1

		if this.tower_upgrade_persistent_data.current_bullets then
			for _ in ipairs(this.tower_upgrade_persistent_data.current_bullets) do
				index = index + 1
			end
		end

		if index > max_bullets then
			index = nil
		end

		return index
	end

	local function get_first_bullet_available()
		local index = get_last_bullet_index()

		if index == nil then
			return max_bullets
		else
			return index - 1
		end
	end

	local function create_bullet()
		if not current_suffixes or #current_suffixes == 0 then
			current_suffixes = get_random_round_robin(bullets_suffixes, 1, #bullets_suffixes)
		end

		if not bullets_suffixes or #bullets_suffixes == 0 then
			bullets_suffixes = table.deepclone(ba.bullets_suffixes)
		end

		local index = get_last_bullet_index()

		if not index then
			return
		end

		local b_pos = v(this.pos.x + ba.bullet_spawn_positions[index].x, this.pos.y + ba.bullet_spawn_positions[index].y)
		local fx = E:create_entity(ba.spawn_fx)

		fx.render.sprites[1].ts = store.tick_ts
		fx.pos = V.vclone(b_pos)

		queue_insert(store, fx)
		U.y_wait(store, ba.spawn_time)

		local b = E:create_entity(ba.bullet)

		b.pos = b_pos
		b.bullet.from = V.vclone(b.pos)
		b.bullet.to = V.vclone(b.pos)
		b.bullet.source_id = this.id
		b.bullet.level = this.tower.level
		b.bullet.target_id = nil
		b.suffix = current_suffixes[index]
		b.render.sprites[1].z = Z_OBJECTS
		b.render.sprites[1].sort_y_offset = -ba.bullet_spawn_positions[index].y - 0.1

		queue_insert(store, b)

		this.tower_upgrade_persistent_data.current_bullets[index] = b
	end

	local function shoot_bullet(target, total_predicted_damage, pred_pos)
		local index = get_first_bullet_available()

		if index == 0 or not target then
			return false
		end

		local b = this.tower_upgrade_persistent_data.current_bullets[index]
		local d = SU.create_bullet_damage(b.bullet, target.id, this.id)
		local pd = U.predict_damage(target, d)

		total_predicted_damage = total_predicted_damage + pd
		this.tower_upgrade_persistent_data.current_bullets[index].target = target
		this.tower_upgrade_persistent_data.current_bullets[index] = nil
		b.bullet.damage_factor = this.tower.damage_factor
		b.bullet.target_id = target.id
		b.bullet.to = v(V.add(pred_pos.x, pred_pos.y, target.unit.hit_offset.x, target.unit.hit_offset.y))
		current_suffixes = nil

		return true
	end

	local function find_most_populated_path(enemies)
		local paths_count = {}
		local found_paths = {}

		for k, v in pairs(enemies) do
			if not table.contains(found_paths, v.nav_path.pi) then
				table.insert(found_paths, v.nav_path.pi)
				table.insert(paths_count, {
					v.nav_path.pi,
					1,
					v
				})
			else
				local i = index_at(paths_count, v, function(tv, iv)
					return iv.nav_path.pi == tv[1]
				end)

				paths_count[i][2] = paths_count[i][2] + 1
			end
		end

		table.sort(paths_count, function(v1, v2)
			return v1[2] > v2[2]
		end)

		return paths_count
	end

	local function sort_paths_by_distance(paths, min_distance)
		local available_paths = table.filter(paths, function(k, v)
			local count = 0
			local n = P:nearest_nodes(this.pos.x, this.pos.y, {
				v[1]
			})[1][3]
			local first_node = P:get_visible_start_node(v)

			for i = 0, min_distance do
				if first_node <= n - i then
					return true
				end

				if P:is_node_valid(v, first_node < n - i and n - i or first_node, 0) and not table.contains(store.level.ignore_walk_backwards_paths, v[1]) then
					count = count + 1

					if count >= min_distance then
						return true
					end
				else
					return false
				end
			end
		end)

		return available_paths
	end

	if this.tower_upgrade_persistent_data.current_bullets then
		for k, v in ipairs(this.tower_upgrade_persistent_data.current_bullets) do
			local b = E:create_entity(ba.bullet)

			b.pos = V.vclone(v.pos)
			b.bullet.from = V.vclone(b.pos)
			b.bullet.to = V.vclone(b.pos)
			b.bullet.source_id = this.id
			b.bullet.level = this.tower.level
			b.bullet.target_id = nil
			b.suffix = v.suffix
			b.render.sprites[1].z = v.render.sprites[1].z
			b.render.sprites[1].sort_y_offset = v.render.sprites[1].sort_y_offset

			queue_insert(store, b)

			local old_bullet = v

			this.tower_upgrade_persistent_data.current_bullets[k] = b

			queue_remove(store, old_bullet)
		end

		for i = 1, #this.tower_upgrade_persistent_data.current_bullets do
			local b_pos = v(this.pos.x + ba.bullet_spawn_positions[i].x, this.pos.y + ba.bullet_spawn_positions[i].y)
			local b = this.tower_upgrade_persistent_data.current_bullets[i]

			b.pos = b_pos
			b.bullet.from = b_pos
		end
	end

	while true do
		if ult_start_cd and store.wave_group_number > 0 then
			ult_start_cd = false
			ult.ts = store.tick_ts
		end

		if this.tower.blocked then
			coroutine.yield()
		else
			if this.powers then
				for _, pow in pairs(this.powers) do
					if pow.changed then
						pow.changed = nil

						if pow == pow_a then
							sa.cooldown = pow.cooldown[pow.level]
							sa.disabled = false
							sa.disc = sa.disc_t .. pow.level

							if pow.level == 1 then
								sa.ts = store.tick_ts - sa.cooldown
							end
						elseif pow == pow_b then
							sb.cooldown = pow.cooldown[pow.level]
							sb.disabled = false
							sb.crystal = sb.crystal_t .. pow.level

							if pow.level == 1 then
								sb.ts = store.tick_ts - sb.cooldown
							end
						elseif pow == pow_c then
							sc.cooldown = pow.cooldown[pow.level]
							sc.disabled = false
							sc.mod_stun = sc.mod_stun_t .. pow.level
							sc.min_targets = sc.minimum_targets[pow.level]
							sc.max_targets = sc.maximum_targets[pow.level]

							if pow.level == 1 then
								sc.ts = store.tick_ts - sc.cooldown
							end
						end
					end
				end
			end

			if sa and not sa.disabled and store.tick_ts - sa.ts > sa.cooldown then
				local nearest = P:nearest_nodes(this.pos.x, this.pos.y)
				local _, targets = U.find_foremost_enemy(store.entities, this.pos, 0, sa.detection_range, sa.prediction, sa.flags, sa.bans)

				if not targets or #targets < sa.min_targets then
					SU.delay_attack(store, sa, fts(10))
				else
					local paths = find_most_populated_path(targets, 0)

					paths = sort_paths_by_distance(paths, sa.distance)
					paths = table.filter(paths, function(k, v)
						if store.level.ignore_walk_backwards_paths and table.contains(store.level.ignore_walk_backwards_paths, v[1]) then
							return false
						else
							return true
						end
					end)

					if not paths or #paths == 0 then
						SU.delay_attack(store, sa, fts(10))
					else
						local n = P:nearest_nodes(this.pos.x, this.pos.y, {
							paths[1][1]
						})
						local spawn_pos = P:node_pos(n[1][1], 1, targets[1].nav_path.ni + sa.distance_from_enemy + 2)

						if V.dist2(spawn_pos.x, spawn_pos.y, this.pos.x, this.pos.y) > sa.max_spawn_distance * sa.max_spawn_distance then
							SU.delay_attack(store, sa, fts(10))
						else
							S:queue(sa.sound)
							U.animation_start(this, "spinning_blades", nil, store.tick_ts, false, sid_mage)

							for k, v in pairs(this.render.sids_lights) do
								U.animation_start(this, "run", nil, store.tick_ts, false, v)
							end

							U.y_wait(store, sa.cast_time)

							local valid_nodes = P:get_valid_nodes(n[1][1])
							local last_valid_node = valid_nodes[#valid_nodes]

							for i = 1, sa.discs do
								local ni = math.min(targets[1].nav_path.ni + sa.distance_from_enemy + 2 * i, last_valid_node)
								local disc = E:create_entity(sa.disc)

								disc.pos = P:node_pos(n[1][1], i, ni)
								disc.pi = n[1][1]
								disc.spi = i
								disc.ni = ni
								disc.render.sprites[1].flip_x = disc.pos.x > targets[1].pos.x
								disc.render.sprites[1].ts = store.tick_ts

								queue_insert(store, disc)

								disc.tower_id = this.id

								U.y_wait(store, fts(3))
							end

							U.y_animation_wait(this, sid_mage, 1)

							sa.ts = store.tick_ts
						end
					end
				end
			end

			if sb and not sb.disabled and store.tick_ts - sb.ts > sb.cooldown then
				local t, targets = U.find_foremost_enemy(store.entities, this.pos, 0, sb.detection_range, fts(15), sb.flags, sb.bans)

				if not targets or #targets < sb.min_targets then
					SU.delay_attack(store, sb, fts(10))
				else
					local paths = find_most_populated_path(targets)

					if not paths or #paths == 0 then
						SU.delay_attack(store, sb, fts(10))
					else
						S:queue(sb.sound)
						U.animation_start(this, "crystals", nil, store.tick_ts, false, sid_mage)

						for k, v in pairs(this.render.sids_lights) do
							U.animation_start(this, "run", nil, store.tick_ts, false, v)
						end

						U.y_wait(store, sb.cast_time)

						this.crystals = {}

						local pi = paths[1][1]
						local enemy = paths[1][3]
						local spawn_pos

						for i = 1, sb.max_crystals do
							local node = enemy.nav_path.ni + sb.spawn_distance + i * 2

							if P:is_node_valid(pi, node) then
								spawn_pos = P:node_pos(pi, i, node)
							else
								local nearest = P:nearest_nodes(this.pos.x, this.pos.y, {
									pi
								})[1]
								local n_pi, n_spi, n_ni = unpack(nearest)

								spawn_pos = P:node_pos(pi, i, n_ni + i * 2)
							end

							local c = E:create_entity(sb.crystal)

							c.pos = spawn_pos
							c.tower_id = this.id

							queue_insert(store, c)
							table.insert(this.crystals, c)
							U.y_wait(store, fts(1))
						end

						U.y_animation_wait(this, sid_mage, 1)

						sb.ts = store.tick_ts
					end
				end
			end

			if sc and not sc.disabled and store.tick_ts - sc.ts > sc.cooldown then
				local _, targets = U.find_foremost_enemy(store.entities, this.pos, 0, sc.detection_range, fts(15), sc.flags, sc.bans)

				if not targets or #targets < sc.min_targets then
					SU.delay_attack(store, sc, fts(10))
				else
					U.animation_start(this, "stun", nil, store.tick_ts, false, sid_mage)

					for k, v in pairs(this.render.sids_lights) do
						U.animation_start(this, "run", nil, store.tick_ts, false, v)
					end

					U.y_wait(store, sc.cast_time)
					S:queue(sc.sound)

					targets = table.random_order(targets)
					targets = table.slice(targets, 1, sc.max_targets)

					for k, v in pairs(targets) do
						local m = E:create_entity(sc.mod_stun)

						m.modifier.target_id = v.id
						m.modifier.source_id = this.id

						if v.unit.size ~= 1 then
							m.render.sprites[1].prefix = m.prefix_big
						end

						queue_insert(store, m)

						local mf = E:create_entity(sc.mod_floor)

						mf.modifier.target_id = v.id
						mf.modifier.source_id = this.id
						mf.modifier.duration = m.modifier.duration

						if v.unit.size ~= 1 then
							mf.render.sprites[1].prefix = mf.prefix_big
						end

						queue_insert(store, mf)
					end

					U.y_animation_wait(this, sid_mage)

					sc.ts = store.tick_ts
				end
			end

			if ult and store.tick_ts - ult.ts > ult.cooldown then
				local _, targets = U.find_foremost_enemy(store.entities, this.pos, 0, ult.detection_range, ult.node_prediction, ult.flags, ult.bans)

				if not targets or #targets == 0 then
					SU.delay_attack(store, ult, fts(10))
				else
					local best_count = -1
					local best_group = {
						targets[1]
					}

					for _, target in pairs(targets) do
						local nearby = U.find_enemies_in_range(store.entities, target.pos, 0, ult.grouping_range, ult.flags, ult.bans)

						if nearby and best_count < #nearby then
							best_group = nearby
							best_count = #nearby
						end
					end

					local new_targets = {}
					local total_hp = 0

					for i = 1, #best_group do
						if best_group[i].health.hp + total_hp <= ult.hp_cap and not table.contains(new_targets, best_group[i]) then
							total_hp = total_hp + best_group[i].health.hp

							table.insert(new_targets, best_group[i])
						end

						if best_group[#best_group - i + 1].health.hp + total_hp <= ult.hp_cap and not table.contains(new_targets, best_group[i]) then
							total_hp = total_hp + best_group[#best_group - i + 1].health.hp

							table.insert(new_targets, best_group[#best_group - i + 1])
						end
					end

					if not new_targets or #new_targets == 0 or total_hp < ult.min_total_hp then
						SU.delay_attack(store, ult, fts(10))
					else
						U.animation_start(this, "ultimate", nil, store.tick_ts, false, sid_mage)

						for k, v in pairs(this.render.sids_lights) do
							U.animation_start(this, "run", nil, store.tick_ts, false, v)
						end

						U.y_wait(store, ult.cast_time)

						local t = targets[1]
						local decal = E:create_entity(ult.decal)

						decal.render.sprites[1].ts = store.tick_ts
						decal.pos = find_center_of_group(new_targets, ult.node_prediction)
						decal.source_id = this.id
						decal.targets = new_targets

						queue_insert(store, decal)
						U.y_animation_wait(this, sid_mage)

						ult.ts = store.tick_ts

						signal.emit("tower-ultimate-used", this)
					end
				end
			end

			if store.tick_ts - ba.ts > ba.cooldown then
				local target, _, pred_pos = U.find_foremost_enemy(store.entities, tpos(this), 0, this.attacks.range, ba.node_prediction, ba.vis_flags, ba.vis_bans)

				if not target and get_last_bullet_index() == nil then
					SU.delay_attack(store, ba, fts(10))
				else
					if #this.tower_upgrade_persistent_data.current_bullets == 0 or not target then
						U.animation_start(this, "reload", nil, store.tick_ts, false, sid_mage)
						U.y_wait(store, ba.reload_time)
						create_bullet()
						U.y_animation_wait(this, sid_mage, 1)
					end

					target, _, pred_pos = U.find_foremost_enemy(store.entities, tpos(this), 0, this.attacks.range, ba.node_prediction, ba.vis_flags, ba.vis_bans)

					if target then
						local total_predicted_damage = 0
						local an, _ = U.animation_name_facing_point(this, "attack", target.pos, sid_mage)

						U.animation_start(this, an, nil, store.tick_ts, false, sid_mage)
						U.y_wait(store, ba.shoot_time)

						for i = 1, #this.tower_upgrade_persistent_data.current_bullets do
							shoot_bullet(target, total_predicted_damage, pred_pos)
							S:queue(ba.sound)
							U.y_wait(store, fts(5))
						end

						U.y_animation_wait(this, sid_mage, 1)

						local an, _ = U.animation_name_facing_point(this, "idle", target.pos, sid_mage)

						U.animation_start(this, an, nil, store.tick_ts, true, sid_mage)
					end

					ba.ts = store.tick_ts
					last_ts = store.tick_ts
				end
			end

			if store.tick_ts - last_ts > this.tower.long_idle_cooldown then
				last_ts = store.tick_ts

				U.animation_start(this, "idle", nil, store.tick_ts, true, sid_mage)
			end

			coroutine.yield()
		end
	end
end

function scripts.tower_forger.remove(this, store)
	if this.tower_upgrade_persistent_data.current_bullets and this.tower.sell then
		for _, bullet in pairs(this.tower_upgrade_persistent_data.current_bullets) do
			if bullet then
				queue_remove(store, bullet)
			end
		end
	end

	if this.discs and #this.discs > 0 then
		for k, v in pairs(this.discs) do
			if v then
				v.remove_disc = true
			end
		end
	end

	if this.crystals and #this.crystals > 0 then
		for k, v in pairs(this.crystals) do
			if v then
				v.duration = 0
			end
		end
	end

	return true
end

scripts.bullet_forger = {}

function scripts.bullet_forger.update(this, store)
	local b = this.bullet
	local fm = this.force_motion
	local s = this.render.sprites[1]

	s.prefix = s.prefix:sub(1, -2) .. this.suffix

	local function move_step(dest)
		local dx, dy = V.sub(dest.x, dest.y, this.pos.x, this.pos.y)
		local dist = V.len(dx, dy)
		local nx, ny = V.mul(fm.max_v, V.normalize(dx, dy))
		local stx, sty = V.sub(nx, ny, fm.v.x, fm.v.y)

		if dist <= 4 * fm.max_v * store.tick_length then
			stx, sty = V.mul(fm.max_a, V.normalize(stx, sty))
		end

		fm.a.x, fm.a.y = V.add(fm.a.x, fm.a.y, V.trim(fm.max_a, V.mul(fm.a_step, stx, sty)))
		fm.v.x, fm.v.y = V.trim(fm.max_v, V.add(fm.v.x, fm.v.y, V.mul(store.tick_length, fm.a.x, fm.a.y)))
		this.pos.x, this.pos.y = V.add(this.pos.x, this.pos.y, V.mul(store.tick_length, fm.v.x, fm.v.y))
		fm.a.x, fm.a.y = 0, 0

		return dist <= fm.max_v * store.tick_length
	end

	U.y_wait(store, fts(math.random(0, 3)))
	U.animation_start(this, "loop", nil, store.tick_ts, true, 1, true)

	local iix, iiy = V.normalize(b.to.x - this.pos.x, b.to.y - this.pos.y)
	local start_ts = store.tick_ts
	local props = {
		offset_x = {
			easing = "quad",
			to = 1,
			from = -1,
			reverse = false,
			duration = 3.5,
			ts = start_ts
		},
		r = {
			easing = "linear",
			reverse = false,
			duration = 1.5,
			from = -4 * math.pi / 180,
			to = 4 * math.pi / 180,
			ts = start_ts
		}
	}

	while b.target_id == nil do
		for _, p in pairs(props) do
			local dt = store.tick_ts - p.ts
			local phase = km.clamp(0, 1, dt / p.duration)
			local from, to = p.from, p.to

			if p.reverse then
				from, to = to, from
			end

			p.value = U.ease_value(from, to, phase, p.easing)

			if phase >= 1 then
				p.ts = store.tick_ts
				p.reverse = not p.reverse
			end
		end

		s.offset.x = props.offset_x.value
		s.r = props.r.value

		coroutine.yield()
	end

	local ps

	if b.particles_name then
		ps = E:create_entity(b.particles_name)
		ps.particle_system.emit = true
		ps.particle_system.track_id = this.id
		ps.particle_system.name = ps.particle_system.name:gsub("(weapon_)%a(_projectile)", "%1" .. this.suffix .. "%2")

		queue_insert(store, ps)
	end

	s.name = s.prefix .. this.fly_suffix
	s.prefix = nil
	s.animated = false
	s.z = Z_BULLETS
	s.sort_y_offset = 0

	while true do
		if move_step(b.to) then
			break
		end

		if b.rotation_speed then
			s.r = s.r + b.rotation_speed * store.tick_length
		end

		coroutine.yield()
	end

	local target = store.entities[b.target_id]
	local targets = U.find_enemies_in_range(store.entities, target and target.pos or b.to, 0, b.damage_radius, b.vis_flags, b.vis_bans, function(v, o)
		return not v.health.dead
	end)

	if targets then
		for _, target in pairs(targets) do
			local mods = b.mods or {
				b.mod
			}

			for _, mod_name in pairs(mods) do
				local mod = E:create_entity(mod_name)

				mod.modifier.target_id = target.id
				mod.modifier.source_id = b.source_.id

				queue_insert(store, mod)
			end

			local d = SU.create_bullet_damage(b, target.id, b.source_id)

			queue_damage(store, d)
		end
	end

	local fx = E:create_entity(b.hit_fx)

	fx.render.sprites[1].ts = store.tick_ts
	fx.pos = V.vclone(this.pos)

	queue_insert(store, fx)

	if ps and ps.particle_system.emit then
		ps.particle_system.emit = false
	end

	S:queue(this.sound_impact)
	queue_remove(store, this)
	coroutine.yield()
end

scripts.decal_forger_skill_a_cast = {}

function scripts.decal_forger_skill_a_cast.update(this, store, script)
	U.y_wait(store, this.wait_time)

	local s = E:create_entity(this.soldier_t)

	s.pos = V.vclone(this.pos)
	s.pi = this.pi
	s.spi = this.spi
	s.ni = this.ni
	s.render.sprites[1].flip_x = this.render.sprites[1].flip_x

	queue_insert(store, s)

	s.tower_id = this.tower_id

	U.y_animation_wait(this)
	queue_remove(store, this)
end

scripts.soldier_forger_skill_a = {}

function scripts.soldier_forger_skill_a.update(this, store, script)
	local function disc_go_back_step(store, this)
		local dest = this.nav_rally.pos

		if V.veq(this.pos, dest) then
			this.motion.arrived = true

			return false
		else
			U.set_destination(this, dest)

			if U.walk(this, store.tick_length) then
				return false
			else
				local an, af = U.animation_name_facing_point(this, "walk", this.motion.dest)

				U.animation_start(this, an, af, store.tick_ts, -1)

				return true
			end
		end
	end

	local function get_ps_offset(anim_name, particles)
		local ps_offset = v(this.render.sprites[1].flip_x and this.particles_offsets[anim_name].x or -this.particles_offsets[anim_name].x, this.particles_offsets[anim_name].y)

		for _, ps in pairs(particles) do
			ps.particle_system.track_offset = ps_offset

			if string.find(anim_name, "down") then
				ps.particle_system.z = Z_DECALS
			else
				ps.particle_system.z = Z_OBJECTS
			end
		end
	end

	local tower = store.entities[this.tower_id]

	if not tower then
		queue_remove(store, this)
	else
		table.insert(tower.discs, this)
	end

	local node_pos, distance
	local path_pi = this.pi
	local path_spi = this.spi
	local path_ni = this.ni
	local traversed = 0

	path_ni = path_ni - 3
	this.nav_rally.pos = P:node_pos(path_pi, path_spi, path_ni)

	local aura = E:create_entity(this.damage_aura)

	aura.aura.track_source = true
	aura.aura.source_id = this.id

	queue_insert(store, aura)

	local particles = {}
	local ps_ground = E:create_entity(this.particles_ground)

	ps_ground.particle_system.track_id = this.id

	queue_insert(store, ps_ground)
	table.insert(particles, ps_ground)

	local ps_debris = E:create_entity(this.particles_debris)

	ps_debris.particle_system.track_id = this.id

	queue_insert(store, ps_debris)
	table.insert(particles, ps_debris)

	while true do
		if this.duration and store.tick_ts - this.ts > this.duration or not GR:cell_is(this.pos.x, this.pos.y, bor(TERRAIN_LAND, TERRAIN_ICE)) or GR:cell_is(this.pos.x, this.pos.y, bor(TERRAIN_NOWALK)) or not P:is_node_valid(path_pi, path_ni) or traversed >= this.distance or this.remove_disc then
			local de = E:create_entity(this.decal_end)

			de.pos = V.vclone(this.pos)
			de.render.sprites[1].ts = store.tick_ts

			queue_insert(store, de)

			aura.duration = 0

			queue_remove(store, ps_ground)
			queue_remove(store, ps_debris)
			queue_remove(store, this)

			return
		end

		node_pos = this.nav_rally.pos
		distance = V.dist2(node_pos.x, node_pos.y, this.pos.x, this.pos.y)

		if distance < 25 then
			path_ni = path_ni - 3
			traversed = traversed + 3
			this.nav_rally.pos = P:node_pos(path_pi, path_spi, path_ni)
		end

		get_ps_offset(this.render.sprites[1].name, particles)

		if disc_go_back_step(store, this) then
			-- block empty
		end

		coroutine.yield()
	end
end

scripts.crystal_forger_skill_b = {}

function scripts.crystal_forger_skill_b.update(this, store, script)
	local fx = E:create_entity(this.spawn_fx)

	fx.pos = V.vclone(this.pos)
	fx.render.sprites[1].ts = store.tick_ts

	queue_insert(store, fx)
	U.y_wait(store, fts(11))

	this.render.sprites[1].hidden = false
	this.damage_dealt = 0

	local ts = store.tick_ts
	local tower = store.entities[this.tower_id]
	local target, bullet

	while store.tick_ts - ts < this.duration and this.damage_dealt < this.max_damage do
		target = U.find_foremost_enemy(store.entities, this.pos, 0, this.range, 0, this.flags, this.bans)

		if not target then
			-- block empty
		else
			bullet = E:create_entity(this.bullet)
			bullet.pos = v(this.pos.x + this.bullet_offset.x, this.pos.y + this.bullet_offset.y)
			bullet.bullet.from = V.vclone(bullet.pos)
			bullet.bullet.to = V.vclone(target.pos)
			bullet.bullet.target_id = target.id
			bullet.bullet.source_id = this.tower_id
			bullet.bullet.damage_factor = tower.tower.damage_factor
			bullet.crystal = this.id
			bullet.bullet.max_track_distance = this.range
			bullet.ray_duration = 1e+99
			this.still_tracking = true

			if target.pos.y < this.pos.y then
				bullet.render.sprites[1].sort_y_offset = -this.bullet_offset.y - 1
			end

			queue_insert(store, bullet)

			while target and not target.health.dead and this.still_tracking do
				if store.tick_ts - ts > this.duration or this.damage_dealt > this.max_damage then
					bullet.fade_out = true
					bullet = nil

					break
				end

				coroutine.yield()
			end
		end

		if bullet then
			bullet.ray_duration = 0
		end

		coroutine.yield()
	end

	this.render.sprites[1].prefix = this.destroy_prefix

	U.y_animation_play(this, this.destroy_anim, nil, store.tick_ts, 1, 1)
	queue_remove(store, this)
end

scripts.bullet_forger_skill_b = {}

function scripts.bullet_forger_skill_b.update(this, store)
	local b = this.bullet
	local s = this.render.sprites[1]
	local target = store.entities[b.target_id]
	local source = store.entities[this.crystal]
	local dest = V.vclone(b.to)
	local tower = this.tower_ref
	local hit_counter = 0
	local mods_added = {}
	local fx, sfx
	local start_fx = E:create_entity(this.ray_start_fx)

	start_fx.render.sprites[1].ts = store.tick_ts
	start_fx.render.sprites[1].sort_y_offset = this.render.sprites[1].sort_y_offset
	start_fx.pos = V.vclone(b.from)

	queue_insert(store, start_fx)

	local function create_fx(hfx)
		sfx = E:create_entity(hfx)
		sfx.render.sprites[1].ts = store.tick_ts

		local is_air = target and band(target.vis.flags, F_FLYING) ~= 0

		if b.hit_fx_ignore_hit_offset and target and not is_air then
			sfx.pos.x, sfx.pos.y = target.pos.x, target.pos.y
		elseif target then
			local hoffset = target.unit.hit_offset

			sfx.pos.x, sfx.pos.y = target.pos.x + hoffset.x, target.pos.y + hoffset.y
		end

		if sfx.allow_rotation and target and source then
			local vx, vy = V.sub(target.pos.x, target.pos.y, source.pos.x, source.pos.y)
			local r = km.unroll(V.angleTo(vx, vy))

			sfx.render.sprites[1].r = r
		end

		queue_insert(store, sfx)
	end

	local function update_sprite()
		if this.track_target and target and target.motion then
			local tpx, tpy = target.pos.x, target.pos.y

			if not b.ignore_hit_offset then
				tpx, tpy = tpx + target.unit.hit_offset.x, tpy + target.unit.hit_offset.y
			end

			local d = math.max(math.abs(tpx - b.to.x), math.abs(tpy - b.to.y))

			if d > b.max_track_distance then
				log.paranoid("(%s) ray_simple target (%s) out of max_track_distance", this.id, target.id)

				target = nil
				source.still_tracking = false

				return
			else
				dest.x, dest.y = target.pos.x, target.pos.y

				if target.unit and target.unit.hit_offset then
					dest.x, dest.y = dest.x + target.unit.hit_offset.x, dest.y + target.unit.hit_offset.y
				end
			end
		else
			dest.x, dest.y = b.to.x, b.to.y
		end

		local a_override_x = this.a_override and this.a_override.x or 1
		local a_override_y = this.a_override and this.a_override.y or 0
		local angle = V.angleTo(dest.x - this.pos.x, dest.y - this.pos.y, a_override_x, a_override_y)

		s.r = angle

		local dist_offset = 0

		if this.dist_offset then
			dist_offset = this.dist_offset
		end

		if this.scale_y then
			s.scale.y = (V.dist(dest.x, dest.y, this.pos.x, this.pos.y) + dist_offset) / this.image_width
		else
			s.scale.x = (V.dist(dest.x, dest.y, this.pos.x, this.pos.y) + dist_offset) / this.image_width
		end
	end

	local function hit()
		hit_counter = hit_counter + 1

		if target and b.damage_type ~= DAMAGE_NONE then
			local d = SU.create_bullet_damage(b, target.id, b.source_id)

			source.damage_dealt = source.damage_dealt + d.value

			queue_damage(store, d)
		end

		if target and (b.mod or b.mods) then
			local mods = b.mods or {
				b.mod
			}

			for _, mod_name in pairs(mods) do
				local m = E:create_entity(mod_name)

				m.modifier.target_id = b.target_id

				if m.damage_from_bullet then
					if m.dps then
						m.dps.damage_min = b.damage_min * b.damage_factor
						m.dps.damage_max = b.damage_max * b.damage_factor
					else
						m.modifier.damage_min = b.damage_min * b.damage_factor
						m.modifier.damage_max = b.damage_max * b.damage_factor
					end
				else
					local level

					if not tower then
						level = this.bullet.level
					else
						level = tower.level
						level = level or this.bullet.level
					end

					m.modifier.level = level
				end

				table.insert(mods_added, m)
				queue_insert(store, m)
			end
		end

		if b.hit_payload then
			local hp

			if type(b.hit_payload) == "string" then
				hp = E:create_entity(b.hit_payload)
			else
				hp = b.hit_payload
			end

			if hp.aura then
				hp.aura.level = this.bullet.level
				hp.aura.source_id = this.id

				if target then
					hp.pos.x, hp.pos.y = target.pos.x, target.pos.y
				else
					hp.pos.x, hp.pos.y = dest.x, dest.y
				end

				if hp.aura.damage_factor then
					hp.aura.damage_factor = b.damage_factor
				end
			else
				hp.pos.x, hp.pos.y = dest.x, dest.y
			end

			queue_insert(store, hp)
		end

		local disable_hit = false

		if this.hit_fx_only_no_target then
			disable_hit = target ~= nil and not target.health.dead
		end

		local hfx

		if b.hit_fxs and #b.hit_fxs > 0 and not disable_hit then
			for i = 1, #b.hit_fxs do
				create_fx(b.hit_fxs[i])
			end
		elseif b.hit_fx and not disable_hit then
			create_fx(b.hit_fx)
		end

		if b.hit_decal then
			local produce_hit_decal = false

			if this.hit_decal_times == -1 then
				produce_hit_decal = hit_counter == 1
			else
				produce_hit_decal = not this.hit_decal_times or hit_counter % this.hit_decal_times == 0
			end

			if produce_hit_decal then
				local decal = E:create_entity(b.hit_decal)

				if this.hit_decal_offset then
					decal.pos.x = dest.x + math.random(-this.hit_decal_offset.x, this.hit_decal_offset.x)
					decal.pos.y = dest.y + math.random(-this.hit_decal_offset.y, this.hit_decal_offset.y)
				else
					decal.pos.x = dest.x
					decal.pos.y = dest.y
				end

				decal.render.sprites[1].ts = store.tick_ts
				decal.source_id = b.source_id

				queue_insert(store, decal)
			end
		end
	end

	if not b.ignore_hit_offset and this.track_target and target and target.motion then
		b.to.x, b.to.y = target.pos.x + target.unit.hit_offset.x, target.pos.y + target.unit.hit_offset.y
	end

	s.scale = s.scale or V.v(1, 1)
	s.ts = store.tick_ts

	update_sprite()

	s.hidden = this.hide_during_trajectory == nil and true or this.hide_during_trajectory

	S:queue(this.sound_loop)

	if b.hit_time > fts(1) then
		local hit_ts = store.tick_ts

		while store.tick_ts - hit_ts < b.hit_time do
			coroutine.yield()

			if target and U.flag_has(target.vis.bans, F_RANGED) then
				target = nil
			end

			if this.track_target then
				update_sprite()
			end
		end
	end

	hit()

	if this.ray_duration then
		local ray_ts = store.tick_ts
		local hit_ts = store.tick_ts

		while store.tick_ts - ray_ts < this.ray_duration do
			if this.track_target then
				update_sprite()
			end

			if tower and not store.entities[tower.id] then
				queue_remove(store, this)

				if fx then
					queue_remove(store, fx)
				end

				for key, value in pairs(mods_added) do
					queue_remove(store, value)
				end

				break
			end

			if this.hit_over_duration then
				update_sprite()

				if store.tick_ts - hit_ts > this.hit_cycle_time then
					hit_ts = store.tick_ts

					hit()
				end
			end

			if this.fade_out then
				U.animation_start(sfx, "fade", nil, store.tick_ts, false, 1)
				U.animation_start(start_fx, "fade", nil, store.tick_ts, false, 1)
				U.y_animation_play(this, "end", nil, store.tick_ts, 1, 1)

				break
			end

			coroutine.yield()

			s.hidden = false
		end
	else
		while not U.animation_finished(this, 1) do
			if tower and not store.entities[tower.id] then
				queue_remove(store, this)

				break
			end

			coroutine.yield()
		end
	end

	if this.end_animation then
		U.y_animation_play(this, this.end_animation, s.flip_x, store.tick_ts, 1, 1)
	end

	S:stop(this.sound_loop)
	queue_remove(store, start_fx)
	queue_remove(store, this)
end

scripts.decal_forger_ult = {}

function scripts.decal_forger_ult.update(this, store, script)
	local maw = E:create_entity(this.decal_maw)

	maw.pos = V.vclone(this.pos)
	maw.render.sprites[1].ts = store.tick_ts

	queue_insert(store, maw)
	U.y_wait(store, this.damage_time)

	for _, t in pairs(this.targets) do
		local d = E:create_entity("damage")

		d.source_id = this.source_id
		d.target_id = t.id
		d.damage_type = bor(DAMAGE_INSTAKILL, DAMAGE_NO_SPAWNS)

		queue_damage(store, d)
	end

	U.y_animation_wait(this)
	queue_remove(store, this)
end

scripts.tower_crossbows = {}

function scripts.tower_crossbows.update(this, store)
	local pow_a = this.powers and this.powers.skill_a or nil
	local pow_b = this.powers and this.powers.skill_b or nil
	local pow_c = this.powers and this.powers.skill_c or nil
	local sa = this.timed_attacks and this.timed_attacks.list[1] or nil
	local sb = this.timed_attacks and this.timed_attacks.list[2] or nil
	local sc = this.timed_attacks and this.timed_attacks.list[3] or nil
	local ba = this.attacks.list[1]

	ba.ts = store.tick_ts - ba.cooldown

	local s = this.render.sprites
	local s_sids = this.shooters_sids
	local c_sids = this.crossbows_sids
	local shooter_idx = 1
	local last_ts = store.tick_ts

	local function animation_start(anim, use_af, pred_pos, wait_for_anim, all_shooters, loop)
		local point = pred_pos or v(REF_W, 0)
		local shooters = all_shooters and s_sids or {
			shooter_idx
		}
		local an, af

		for v = 1, #shooters do
			local idx = #shooters ~= 1 and v or shooter_idx

			an, af = U.animation_name_facing_point(this, anim, point, s_sids[idx])
			s[c_sids[idx]].hidden = string.find(an, "back")

			if not use_af then
				af = nil
			end

			U.animation_start(this, an, af, store.tick_ts, loop, s_sids[idx])

			if not s[c_sids[idx]].hidden then
				U.animation_start(this, an, af, store.tick_ts, loop, c_sids[idx])
			end
		end

		if wait_for_anim then
			U.y_animation_wait(this, s_sids[shooter_idx], 1)
		end

		return an
	end

	if this.powers and this.powers.ultimate.active then
		local ult = this.timed_attacks.list[4]

		this.controller_ult = E:create_entity(ult.controller)
		this.controller_ult.tower_id = this.id
		this.controller_ult.soldier_spawn_pos = v(this.pos.x + ult.soldier_spawn_pos.x, this.pos.y + ult.soldier_spawn_pos.y)
		this.controller_ult.pos = V.vclone(this.pos)

		queue_insert(store, this.controller_ult)
	end

	::label_841_0::

	while true do
		if this.tower.blocked then
			coroutine.yield()
		else
			if this.powers then
				for _, pow in pairs(this.powers) do
					if pow.changed then
						pow.changed = nil

						if pow == pow_a then
							sa.cooldown = pow.cooldown[pow.level]
							sa.disabled = false
							sa.bullet = sa.bullet_t .. pow.level
							sa.duration = sa.durations[pow.level]

							if pow.level == 1 then
								sa.ts = store.tick_ts - sa.cooldown
							end
						elseif pow == pow_b then
							sb.mod = sb.mod_t .. pow.level

							if this.controller_ult then
								this.controller_ult.mod = sb.mod
							end

							if this.soldier_id then
								local soldier = store.entities[this.soldier_id]

								if soldier then
									soldier.melee.attacks[1].mod = sb.mod
								end
							end
						elseif pow == pow_c then
							sc.cooldown = pow.cooldown[pow.level]
							sc.disabled = false
							sc.bullet = sc.bullet_t .. pow.level
							sc.instakill_chance = sc.instakill_chances[pow.level]

							if pow.level == 1 then
								sc.ts = store.tick_ts - sc.cooldown
							end
						end
					end
				end
			end

			if store.tick_ts - ba.ts > ba.cooldown then
				local target, _, pred_pos = U.find_foremost_enemy(store.entities, tpos(this), 0, this.attacks.range, ba.node_prediction, ba.vis_flags, ba.vis_bans)

				if not target then
					SU.delay_attack(store, ba, fts(5))
				else
					local an = animation_start("shoot", true, pred_pos)

					for i = 1, 3 do
						U.y_wait(store, ba.shoot_times[i])

						if not target or target and target.health.dead then
							local new_target = U.find_foremost_enemy(store.entities, pred_pos, 0, ba.retarget_range, ba.node_prediction, ba.vis_flags, ba.vis_bans)

							if new_target then
								target = new_target
							end
						end

						if target and not target.health.dead then
							local node_offset = P:predict_enemy_node_advance(target, ba.node_prediction)
							local ni = target.nav_path.ni + node_offset

							pred_pos = P:node_pos(target.nav_path.pi, target.nav_path.spi, ni)
						end

						local hoffset = target and V.vclone(target.unit.hit_offset) or v(0, 0)
						local b = E:create_entity(ba.bullet)

						b.bullet.damage_factor = this.tower.damage_factor
						b.pos.x = tpos(this).x + s[s_sids[shooter_idx]].offset.x + ba.bullet_start_offset[an].x * (s[s_sids[shooter_idx]].flip_x and -1 or 1)
						b.pos.y = tpos(this).y + s[s_sids[shooter_idx]].offset.y + ba.bullet_start_offset[an].y
						b.bullet.from = V.vclone(b.pos)
						b.bullet.to = v(pred_pos.x + hoffset.x, pred_pos.y + hoffset.y)
						b.bullet.to.x = b.bullet.to.x + math.random(-1, 1)
						b.bullet.to.y = b.bullet.to.y + math.random(-1, 1)
						b.bullet.source_id = this.id
						b.bullet.target_id = target and target.id or nil

						if sb and sb.mod then
							b.bullet.mod = sb.mod
						end

						b.render.sprites[1].r = V.angleTo(b.bullet.to.x - this.pos.x, b.bullet.to.y - this.pos.y)

						queue_insert(store, b)

						if this.tower.blocked then
							break
						end
					end

					U.y_animation_wait(this, s_sids[shooter_idx], 1)
					animation_start("idle", true, pred_pos)

					shooter_idx = km.zmod(shooter_idx + 1, #s_sids)
					ba.ts = store.tick_ts
					last_ts = store.tick_ts

					goto label_841_0
				end
			end

			if sa and not sa.disabled and store.tick_ts - sa.ts > sa.cooldown then
				local _, targets, pred_pos = U.find_foremost_enemy(store.entities, this.pos, 0, sa.detection_range, sa.prediction, sa.flags, sa.bans)

				if not targets or #targets < sa.min_targets then
					SU.delay_attack(store, sa, fts(5))
				else
					S:queue(sa.sound)
					animation_start("skill_a_in", false, targets[1].pos, true, true)
					animation_start("skill_a_idle", true, targets[1].pos, false, true, true)

					local ts = store.tick_ts
					local last_shot_ts = 0

					while store.tick_ts - ts < sa.duration do
						if this.tower.blocked then
							break
						end

						if store.tick_ts - last_shot_ts > sa.attack_cooldown then
							local target, _, pred_pos = U.find_foremost_enemy(store.entities, tpos(this), 0, this.attacks.range, ba.node_prediction, ba.vis_flags, ba.vis_bans)

							if target then
								for i = 1, sa.shots_per_attack do
									local an = animation_start("shoot_skill_a", true, pred_pos)

									U.y_wait(store, sa.shoot_time)

									if not target or target and target.health.dead then
										local new_target = U.find_foremost_enemy(store.entities, pred_pos, 0, sa.retarget_range, ba.node_prediction, ba.vis_flags, ba.vis_bans)

										if new_target then
											target = new_target
										end
									end

									if target and not target.health.dead then
										local node_offset = P:predict_enemy_node_advance(target, ba.node_prediction)
										local ni = target.nav_path.ni + node_offset

										pred_pos = P:node_pos(target.nav_path.pi, target.nav_path.spi, ni)
									end

									local hoffset = target and V.vclone(target.unit.hit_offset) or v(0, 0)
									local b = E:create_entity(sa.bullet)

									b.bullet.damage_factor = this.tower.damage_factor
									b.pos.x = tpos(this).x + s[s_sids[shooter_idx]].offset.x + ba.bullet_start_offset[an].x * (s[s_sids[shooter_idx]].flip_x and -1 or 1)
									b.pos.y = tpos(this).y + s[s_sids[shooter_idx]].offset.y + ba.bullet_start_offset[an].y
									b.bullet.from = V.vclone(b.pos)
									b.bullet.to = v(pred_pos.x + hoffset.x, pred_pos.y + hoffset.y)
									b.bullet.to.x = b.bullet.to.x + math.random(-1, 1)
									b.bullet.to.y = b.bullet.to.y + math.random(-1, 1)
									b.bullet.source_id = this.id
									b.bullet.target_id = target.id

									if sb and sb.mod then
										b.bullet.mod = sb.mod
									end

									b.render.sprites[1].r = V.angleTo(b.bullet.to.x - this.pos.x, b.bullet.to.y - this.pos.y)

									queue_insert(store, b)
									U.y_wait(store, sa.time_between_shots)

									if this.tower.blocked then
										break
									end
								end

								U.y_animation_wait(this, s_sids[shooter_idx], 1)
								animation_start("skill_a_idle", true, pred_pos, false, false, true)

								shooter_idx = km.zmod(shooter_idx + 1, #s_sids)
								last_shot_ts = store.tick_ts
							end
						end

						coroutine.yield()
					end

					sa.ts = store.tick_ts

					animation_start("skill_a_out", false, nil, true, true)

					goto label_841_0
				end
			end

			if sc and not sc.disabled and store.tick_ts - sc.ts > sc.cooldown then
				local target, _, pred_pos = U.find_foremost_enemy(store.entities, tpos(this), 0, this.attacks.range, sc.node_prediction, sc.vis_flags, sc.vis_bans)

				if not target then
					SU.delay_attack(store, sc, fts(5))
				else
					local an = animation_start("skill_c", true, pred_pos)

					S:queue(sc.sound)
					U.y_wait(store, sc.shoot_time)

					local hoffset = target and V.vclone(target.unit.hit_offset) or v(0, 0)
					local b = E:create_entity(sc.bullet)

					b.bullet.damage_factor = this.tower.damage_factor
					b.pos.x = tpos(this).x + s[s_sids[shooter_idx]].offset.x + ba.bullet_start_offset[an].x * (s[s_sids[shooter_idx]].flip_x and -1 or 1)
					b.pos.y = tpos(this).y + s[s_sids[shooter_idx]].offset.y + ba.bullet_start_offset[an].y
					b.bullet.from = V.vclone(b.pos)
					b.bullet.to = v(pred_pos.x + hoffset.x, pred_pos.y + hoffset.y)
					b.bullet.source_id = this.id
					b.bullet.target_id = target.id

					if sb and sb.mod then
						b.bullet.mod = sb.mod
					end

					local r = math.random()

					if band(target.vis.flags, bor(F_BOSS, F_MINIBOSS)) == 0 and band(target.vis.bans, F_INSTAKILL) == 0 and r < sc.instakill_chance then
						b.bullet.damage_min = 1e+99
						b.bullet.damage_max = 1e+99
						b.bullet.damage_type = DAMAGE_INSTAKILL
					end

					queue_insert(store, b)
					U.y_animation_wait(this, s_sids[shooter_idx], 1)
					animation_start("idle", true, pred_pos)

					shooter_idx = km.zmod(shooter_idx + 1, #s_sids)
					sc.ts = store.tick_ts
					last_ts = store.tick_ts

					goto label_841_0
				end
			end

			if store.tick_ts - last_ts > this.tower.long_idle_cooldown then
				animation_start("idle", true, nil, nil, true, true)

				last_ts = store.tick_ts
			end

			coroutine.yield()
		end
	end
end

function scripts.tower_crossbows.remove(this, store, script)
	if this.controller_ult then
		queue_remove(store, this.controller_ult)
	end

	if this.soldier_id then
		queue_remove(store, store.entities[this.soldier_id])
	end

	return true
end

scripts.mod_crossbows_skill_b = {}

function scripts.mod_crossbows_skill_b.update(this, store, script)
	local m = this.modifier

	this.modifier.ts = store.tick_ts

	local target = store.entities[m.target_id]

	if not target or not target.pos then
		queue_remove(store, this)

		return
	end

	this.pos = target.pos

	while true do
		target = store.entities[m.target_id]

		if target and target.health.dead then
			local pos

			if target and band(target.vis.flags, F_FLYING) ~= 0 then
				pos = v(target.pos.x + target.unit.mod_offset.x, target.pos.y + target.unit.mod_offset.y)
			else
				pos = V.vclone(target.pos)
			end

			local dh = E:create_entity(this.decal_hit)

			dh.render.sprites[1].ts = store.tick_ts
			dh.pos = pos

			queue_insert(store, dh)

			local dg = E:create_entity(this.decal_ground)

			dg.render.sprites[1].ts = store.tick_ts
			dg.pos = pos

			queue_insert(store, dg)

			local aura = E:create_entity(this.aura)

			aura.pos = V.vclone(target.pos)

			queue_insert(store, aura)
			queue_remove(store, this)

			return
		end

		if m.duration >= 0 and store.tick_ts - m.ts > m.duration or m.last_node and target.nav_path.ni > m.last_node or not target then
			queue_remove(store, this)

			return
		end

		coroutine.yield()
	end
end

scripts.mod_weak_crossbows = {}

function scripts.mod_weak_crossbows.insert(this, store, script)
	local target = store.entities[this.modifier.target_id]

	if not target or target.health.dead or not target.unit then
		return false
	end

	if this.received_damage_factor then
		target.health.damage_factor = target.health.damage_factor * this.received_damage_factor
	end

	if this.inflicted_damage_factor then
		if band(target.vis.flags, F_BOSS) ~= 0 and this.boss_inflicted_damage_factor then
			target.unit.damage_factor = target.unit.damage_factor * this.boss_inflicted_damage_factor
		else
			target.unit.damage_factor = target.unit.damage_factor * this.inflicted_damage_factor
		end
	end

	if IS_KR5 and (band(this.modifier.vis_flags, target.vis.bans) ~= 0 or band(this.modifier.vis_bans, target.vis.flags) ~= 0) then
		log.paranoid("mod %s cannot be applied to entity %s:%s because of vis flags/bans", this.template_name, target.id, target.template_name)

		return false
	end

	if this.render then
		for _, s in pairs(this.render.sprites) do
			s.ts = store.tick_ts

			if s.size_prefixes then
				s.prefix = s.size_prefixes[target.unit.size]
			end

			if s.size_names then
				s.name = s.size_names[target.unit.size]
			end

			if s.size_scales then
				s.scale = s.size_scales[target.unit.size]
			end
		end
	end

	signal.emit("mod-applied", this, target)

	return true
end

scripts.controller_crossbows_ult = {}

function scripts.controller_crossbows_ult.update(this, store, script)
	local ts = store.tick_ts - this.cooldown
	local soldier_spawned = false
	local death_ts = store.tick_ts
	local tower = store.entities[this.tower_id]
	local soldier
	local path_set = false

	while true do
		if store.tick_ts - ts > this.cooldown and not soldier_spawned and not tower.tower.blocked then
			soldier = E:create_entity(this.soldier_t)
			soldier.pos = V.vclone(this.soldier_spawn_pos)
			soldier.controller = this
			soldier.melee.attacks[1].mod = this.mod

			queue_insert(store, soldier)

			soldier_spawned = true
			tower.soldier_id = soldier.id
		else
			if soldier_spawned and not this.soldier_dead and not path_set then
				local enemies = U.find_enemies_in_range(store.entities, this.pos, 0, this.detection_range, this.flags, this.bans)

				if enemies and #enemies > 0 and store.level.ignore_walk_backwards_paths then
					enemies = table.filter(enemies, function(k, v)
						return not table.contains(store.level.ignore_walk_backwards_paths, v.nav_path.pi)
					end)
				end

				if not enemies or #enemies < this.min_targets then
					goto label_846_1
				end

				local available_paths = {}

				for k, v in pairs(P.paths) do
					table.insert(available_paths, k)
				end

				if store.level.ignore_walk_backwards_paths then
					available_paths = table.filter(available_paths, function(k, v)
						return not table.contains(store.level.ignore_walk_backwards_paths, v)
					end)
				end

				local enemy_paths = find_most_populated_path(enemies)

				if not enemy_paths or #enemy_paths == 0 then
					goto label_846_1
				end

				if enemy_paths then
					for k, v in ipairs(available_paths) do
						for _, e in ipairs(enemy_paths) do
							if v == e[1] then
								available_paths = {
									v
								}

								goto label_846_0
							end
						end
					end
				end

				::label_846_0::

				local nearest = P:nearest_nodes(this.pos.x, this.pos.y, available_paths)

				if #nearest > 0 then
					local path_pi, path_spi, path_ni = unpack(nearest[1])

					soldier.pi = path_pi
					soldier.spi = 1
					soldier.ni = path_ni
					soldier.move = true
					soldier.tower_id = this.tower_id
					path_set = true
				end
			end

			if soldier_spawned and (this.soldier_dead or not store.entities[soldier.id]) then
				ts = store.tick_ts
				soldier_spawned = false
				death_ts = store.tick_ts
				soldier = nil
				path_set = false
				this.soldier_dead = false
			end
		end

		::label_846_1::

		coroutine.yield()
	end
end

scripts.soldier_crossbows_ult = {}

function scripts.soldier_crossbows_ult.update(this, store, script)
	local function valid_pos()
		local pi, spi, ni, dist = unpack(P:nearest_nodes(this.pos.x, this.pos.y, {
			this.pi
		})[1])
		local node_pos = P:node_pos(pi, spi, ni)

		return P:is_node_valid(pi, ni) and GR:cell_is(node_pos.x, node_pos.y, bor(TERRAIN_LAND, TERRAIN_ICE)) and P:is_path_active(pi)
	end

	this.hp = this.hp_max
	this.vis.bans = F_ALL
	this.health.ignore_damage = true

	U.y_animation_play(this, "in_armor", nil, store.tick_ts, 1, 1)
	U.animation_start(this, "idle_armor", nil, store.tick_ts, true, 1)

	while not this.move do
		coroutine.yield()
	end

	this.reinforcement.ts = store.tick_ts

	if this.sound_events and this.sound_events.raise then
		S:queue(this.sound_events.raise)
	end

	U.y_animation_play(this, "in_spectre", nil, store.tick_ts, 1, 1)

	this.ui.click_rect = this.click_rect_soldier
	this.health.ignore_damage = false
	this.vis.bans = F_NONE

	local brk, stam, distance
	local path_pi = this.pi
	local path_spi = 1
	local path_ni = this.ni - 3
	local node_pos = P:node_pos(path_pi, path_spi, path_ni)

	this.nav_rally.center = nil
	this.nav_rally.pos = V.vclone(node_pos)

	while true do
		if this.health.dead or not valid_pos() or not P:is_node_valid(path_pi, path_ni) or store.tick_ts - this.reinforcement.ts > this.reinforcement.duration then
			this.health.hp = 0
			this.vis.bans = F_ALL
			this.ui.can_click = false
			this.health_bar.hidden = true

			SU.remove_modifiers(store, this)
			SU.y_soldier_death(store, this)
			U.y_wait(store, 2)

			this.controller.soldier_dead = true

			queue_remove(store, this)

			return
		end

		if this.unit.is_stunned then
			SU.soldier_idle(store, this)
		else
			brk, stam = SU.y_soldier_melee_block_and_attacks(store, this)

			if brk or stam == A_DONE or stam == A_IN_COOLDOWN and not this.melee.continue_in_cooldown then
				-- block empty
			else
				node_pos = this.nav_rally.pos
				distance = V.dist2(node_pos.x, node_pos.y, this.pos.x, this.pos.y)

				if distance < 25 then
					path_ni = path_ni - 3
					this.nav_rally.pos = P:node_pos(path_pi, path_spi, path_ni)
				end

				if SU.soldier_go_back_step(store, this) then
					-- block empty
				else
					SU.soldier_regen(store, this)
				end
			end
		end

		SU.soldier_idle(store, this)
		coroutine.yield()
	end
end

scripts.tower_sniper = {}

function scripts.tower_sniper.update(this, store)
	this.tower_upgrade_persistent_data.disable_change_mode = false

	local s_sids = {
		this.render.bottom_sid,
		this.render.top_sid
	}
	local ba = this.attacks.list[1]

	ba.ts = store.tick_ts

	local sba = this.tower.level == 4 and this.attacks.list[2] or nil
	local sba_min_hp
	local sa = false
	local ult = this.powers and this.powers.ultimate.active and this.attacks.list[3] or nil
	local ult_start_cd = ult ~= nil and store.wave_group_number == 0

	if ult then
		ult.ts = store.tick_ts
	end

	local MODE_FOREMOST = 0
	local MODE_HP = 1
	local ba_cd_red_factor = 0
	local bullet_skill_a
	local ba_bullet_t = ba.bullet
	local ignore_nodes_start = this.ignore_nodes_start
	local ignore_nodes_end = this.ignore_nodes_end
	local coordinated_targeting = this.coordinated_targeting
	local coordinated_wasted_damage_factor = this.coordinated_wasted_damage_factor

	local function filter_fn(e, o)
		local pi = e.nav_path.pi
		local ni = e.nav_path.ni

		return P:is_node_valid(pi, ni, NF_RANGE) and ni - P:get_visible_start_node(pi) >= ignore_nodes_start and P:get_visible_end_node(pi) - ni >= ignore_nodes_end
	end

	local function filter_skill_b(e, o)
		return e.health and e.health.hp >= sba_min_hp and filter_fn(e, o)
	end

	ba.filter_fn = filter_fn

	if sba then
		sba.filter_fn = filter_fn
	end

	if ult then
		ult.filter_fn = filter_fn
	end

	local function do_anim(anim_group, y_play, pos, loop)
		local an, af = U.animation_name_facing_point(this, anim_group, pos, this.render.bottom_sid)

		for k, v in ipairs(s_sids) do
			if table.contains(this.render.sprites[v].angles[anim_group], an) then
				this.render.sprites[v].hidden = false

				U.animation_start(this, an, af, store.tick_ts, loop, v)
			else
				this.render.sprites[v].hidden = true
			end
		end

		if y_play then
			while not U.animation_finished(this, s_sids[1]) do
				coroutine.yield()
			end
		end

		return an, af
	end

	local function shoot(attack)
		local reduce_cd = false
		local dummy_dmg
		local base_filter = attack == sba and filter_skill_b or attack.filter_fn
		local filter = base_filter

		if coordinated_targeting then
			local bt = E:get_template(attack.bullet)

			dummy_dmg = E:create_entity("damage")
			dummy_dmg.damage_type = bt.bullet.damage_type
			dummy_dmg.reduce_armor = bt.bullet.reduce_armor
			dummy_dmg.reduce_magic_armor = bt.bullet.reduce_magic_armor
			dummy_dmg.value = math.max(1, math.ceil(bt.bullet.damage_min * this.tower.damage_factor))

			function filter(e, o)
				if base_filter and not base_filter(e, o) then
					return false
				end

				local incoming = e._sniper_pred_damage or 0

				if incoming == 0 then
					return true
				end

				return incoming + U.predict_damage(e, dummy_dmg) <= coordinated_wasted_damage_factor * e.health.hp
			end
		end

		local _, enemies, pred_pos = U.find_foremost_enemy(store.entities, tpos(this), attack.min_range, attack.max_range, attack.node_prediction, attack.vis_flags, attack.vis_bans, filter)

		if not enemies or #enemies == 0 then
			SU.delay_attack(store, attack, fts(5))

			return
		end

		if this.tower_upgrade_persistent_data.current_mode == MODE_HP then
			table.sort(enemies, function(v1, v2)
				return v1.health.hp_max > v2.health.hp_max
			end)
		end

		local enemy = enemies[1]
		local node_offset = P:predict_enemy_node_advance(enemy, attack.node_prediction)
		local ni = enemy.nav_path.ni + node_offset

		pred_pos = P:node_pos(enemy.nav_path.pi, enemy.nav_path.spi, ni)

		local last_pos = pred_pos
		local aim_mod = E:create_entity(attack.mod_crosshair)

		aim_mod.modifier.target_id = enemy.id
		aim_mod.modifier.duration = 1e+99
		aim_mod.render.sprites[1].ts = store.tick_ts

		if dummy_dmg then
			aim_mod.pred_damage = U.predict_damage(enemy, dummy_dmg)
		end

		queue_insert(store, aim_mod)

		this.mod_aim = aim_mod
		this.tower_upgrade_persistent_data.disable_change_mode = true

		U.y_animation_play(this, "aimstart", last_pos.x < tpos(this).x, store.tick_ts, 1, this.render.bottom_sid)
		do_anim("aim", true, last_pos)

		local ts = store.tick_ts

		while store.tick_ts - ts < attack.crosshair_time do
			if not enemy or enemy.health.dead then
				_, enemies, pred_pos = U.find_foremost_enemy(store.entities, last_pos, 0, attack.max_retarget_range, attack.node_prediction, attack.vis_flags, attack.vis_bans, filter)

				if not enemies or #enemies == 0 then
					enemy = nil
				else
					if this.tower_upgrade_persistent_data.current_mode == MODE_HP then
						table.sort(enemies, function(v1, v2)
							return v1.health.hp_max > v2.health.hp_max
						end)
					end

					enemy = enemies[1]

					local node_offset = P:predict_enemy_node_advance(enemy, attack.node_prediction)

					last_pos = P:node_pos(enemy.nav_path.pi, enemy.nav_path.spi, enemy.nav_path.ni + node_offset)

					if aim_mod then
						queue_remove(store, aim_mod)
					end

					aim_mod = E:create_entity(attack.mod_crosshair)
					aim_mod.modifier.target_id = enemy.id
					aim_mod.modifier.duration = 1e+99
					aim_mod.render.sprites[1].ts = store.tick_ts
					aim_mod.render.sprites[1].name = "idle"

					if dummy_dmg then
						aim_mod.pred_damage = U.predict_damage(enemy, dummy_dmg)
					end

					queue_insert(store, aim_mod)

					this.mod_aim = aim_mod
				end
			end

			coroutine.yield()
		end

		local an, af = do_anim("shoot", false, last_pos)
		local hoffset = enemy and enemy.unit.hit_offset or v(0, 0)
		local flip = af and -1 or 1
		local b = E:create_entity(attack.bullet)

		b.pos.x = this.pos.x + attack.bullet_start_offset[an].x * flip
		b.pos.y = this.pos.y + attack.bullet_start_offset[an].y
		b.bullet.from = V.vclone(b.pos)
		b.bullet.to = enemy and V.v(enemy.pos.x + hoffset.x * (enemy.render.sprites[1].flip_x and -1 or 1), enemy.pos.y + hoffset.y) or last_pos
		b.bullet.target_id = enemy and enemy.id or nil
		b.bullet.source_id = this.id
		b.bullet.level = this.tower.level
		b.bullet.damage_factor = this.tower.damage_factor

		queue_insert(store, b)

		local casing = E:create_entity(this.casing_t)

		casing.pos.x = this.pos.x + attack.casing_offset[an].x * flip
		casing.pos.y = this.pos.y + attack.casing_offset[an].y
		casing.render.sprites[1].ts = store.tick_ts
		casing.render.sprites[1].flip_x = af

		queue_insert(store, casing)
		U.y_wait(store, fts(2))

		if attack == ba and sa and this.track_kills and #this.track_kills.killed > 0 then
			local decal = E:create_entity(this.decal_reload)

			decal.pos.x = this.pos.x + this.decal_reload_offset.x
			decal.pos.y = this.pos.y + this.decal_reload_offset.y
			decal.render.sprites[1].ts = store.tick_ts

			queue_insert(store, decal)
			S:queue(this.sound_skill_a)

			reduce_cd = true
		end

		U.y_animation_wait(this, this.render.bottom_sid)

		if this.mod_aim then
			this.mod_aim.modifier.duration = 0
		end

		local an, af = do_anim("to_reload", false, last_pos)
		local smoke = E:create_entity(this.smoke_t)

		smoke.pos.x = this.pos.x + this.render.sprites[this.render.top_sid].offset.x + attack.smoke_offset[an].x * flip
		smoke.pos.y = this.pos.y + this.render.sprites[this.render.top_sid].offset.y + attack.smoke_offset[an].y
		smoke.render.sprites[1].ts = store.tick_ts
		smoke.render.sprites[1].name = an
		smoke.render.sprites[1].flip_x = af

		queue_insert(store, smoke)

		while not U.animation_finished(this, this.render.bottom_sid) do
			coroutine.yield()
		end

		this.tower_upgrade_persistent_data.disable_change_mode = false

		do_anim("reload", true, last_pos)

		if attack == ba then
			if reduce_cd then
				attack.ts = store.tick_ts - attack.crosshair_time - attack.cooldown * ba_cd_red_factor
				ba.bullet = bullet_skill_a
			else
				ba.bullet = ba_bullet_t
				attack.ts = store.tick_ts - attack.crosshair_time
			end
		else
			attack.ts = store.tick_ts - attack.crosshair_time
		end

		if this.track_kills then
			this.track_kills.killed = {}
		end

		do_anim("idle", false, last_pos, true)
	end

	local function shoot_ult(enemy, pos, crosshair_anim)
		local an, af = do_anim("shoot", false, pos)
		local hoffset = enemy and enemy.unit.hit_offset or v(0, 0)
		local flip = af and -1 or 1
		local b = E:create_entity(ult.bullet)

		b.pos.x = this.pos.x + ult.bullet_start_offset[an].x * flip
		b.pos.y = this.pos.y + ult.bullet_start_offset[an].y
		b.bullet.from = V.vclone(b.pos)
		b.bullet.to = V.v(pos.x + hoffset.x * (enemy and enemy.render.sprites[1].flip_x and -1 or 1), pos.y + hoffset.y)
		b.bullet.target_id = enemy and enemy.id
		b.bullet.source_id = this.id
		b.bullet.level = this.tower.level
		b.bullet.damage_factor = this.tower.damage_factor * ult.damage_factor

		queue_insert(store, b)

		local casing = E:create_entity(this.casing_t)

		casing.pos.x = this.pos.x + ult.casing_offset[an].x * flip
		casing.pos.y = this.pos.y + ult.casing_offset[an].y
		casing.render.sprites[1].ts = store.tick_ts
		casing.render.sprites[1].flip_x = af

		queue_insert(store, casing)

		if this.mod_aim_ult then
			U.animation_start(this.mod_aim_ult, crosshair_anim, nil, store.tick_ts, false, 1)
		end
	end

	local function check_change_mode()
		if this.change_mode then
			this.change_mode = false

			if this.tower_upgrade_persistent_data.current_mode == MODE_FOREMOST then
				this.tower_upgrade_persistent_data.current_mode = MODE_HP

				U.animation_start(this, "enter", nil, store.tick_ts, false, this.render.banner_sid)
			else
				this.tower_upgrade_persistent_data.current_mode = MODE_FOREMOST

				U.animation_start(this, "leave", nil, store.tick_ts, false, this.render.banner_sid)
			end
		end
	end

	if this.tower_upgrade_persistent_data.current_mode == MODE_FOREMOST then
		U.animation_start(this, "idlenothing", nil, store.tick_ts, false, this.render.banner_sid)
	else
		U.animation_start(this, "idle", nil, store.tick_ts, false, this.render.banner_sid)
	end

	::label_851_0::

	while true do
		if ult_start_cd and store.wave_group_number > 0 then
			ult_start_cd = false
			ult.ts = store.tick_ts
		end

		if this.tower.blocked then
			coroutine.yield()
		else
			if this.powers then
				for _, pow in pairs(this.powers) do
					if pow.changed then
						pow.changed = nil

						if pow == this.powers.skill_a then
							sa = true
							ba_cd_red_factor = this.powers.skill_a.cd_red_factor[pow.level]
							bullet_skill_a = this.bullet_skill_a_t .. pow.level
						elseif pow == this.powers.skill_b then
							sba.bullet = sba.bullet_t .. pow.level
							sba.cooldown = this.powers.skill_b.cooldown[pow.level]
							sba.disabled = false
							sba_min_hp = this.powers.skill_b.min_hp[pow.level]

							if pow.level == 1 then
								sba.ts = store.tick_ts - sba.cooldown
							end
						elseif pow == this.powers.skill_c then
							if not this.decal_skill_c then
								this.decal_skill_c = E:create_entity(this.decal_skill_c_t)
								this.decal_skill_c.pos.x = this.pos.x
								this.decal_skill_c.pos.y = this.pos.y
								this.decal_skill_c.tower_id = this.id

								queue_insert(store, this.decal_skill_c)
							end

							this.decal_skill_c.cooldown = this.powers.skill_c.cooldown[pow.level]
							this.decal_skill_c.damage_min = this.powers.skill_c.damage_min[pow.level]
							this.decal_skill_c.damage_max = this.powers.skill_c.damage_max[pow.level]
							this.decal_skill_c.damage_type = this.powers.skill_c.damage_type
							this.decal_skill_c.range = ba.min_range
						end
					end
				end
			end

			check_change_mode()

			if ult and store.tick_ts - ult.ts > ult.cooldown then
				local last_enemy, _, enemies, pred_pos
				local delay_before_shot = 3 * ult.time_between_shots / 4
				local delay_after_shot = ult.time_between_shots / 4
				local ult_dummy

				if coordinated_targeting then
					local ult_bt = E:get_template(ult.bullet)

					ult_dummy = E:create_entity("damage")
					ult_dummy.damage_type = ult_bt.bullet.damage_type
					ult_dummy.reduce_armor = ult_bt.bullet.reduce_armor
					ult_dummy.reduce_magic_armor = ult_bt.bullet.reduce_magic_armor
					ult_dummy.value = math.max(1, math.ceil(3 * ult_bt.bullet.damage_min * this.tower.damage_factor * ult.damage_factor))
				end

				for i = 1, 3 do
					if i == 1 then
						_, enemies, pred_pos = U.find_foremost_enemy(store.entities, tpos(this), ult.min_range, ult.max_range, ult.shoot_time, ult.vis_flags, ult.vis_bans, ult.filter_fn)

						if not enemies or #enemies == 0 then
							SU.delay_attack(store, ult, fts(5))

							goto label_851_1
						end

						if this.tower_upgrade_persistent_data.current_mode == MODE_HP then
							table.sort(enemies, function(v1, v2)
								return v1.health.hp_max > v2.health.hp_max
							end)
						end

						last_enemy = enemies[1]

						local node_offset = P:predict_enemy_node_advance(last_enemy, ult.node_prediction + fts(20))
						local e_ni = last_enemy.nav_path.ni + node_offset

						pred_pos = P:node_pos(last_enemy.nav_path.pi, last_enemy.nav_path.spi, e_ni)
						this.tower_upgrade_persistent_data.disable_change_mode = true
						this.decal_flare_ult = E:create_entity(ult.flare_decal)
						this.decal_flare_ult.pos.x = tpos(this).x + ult.flare_offset.x
						this.decal_flare_ult.pos.y = tpos(this).y + ult.flare_offset.y
						this.decal_flare_ult.render.sprites[1].ts = store.tick_ts

						queue_insert(store, this.decal_flare_ult)

						this.mod_aim_ult = E:create_entity(ult.mod_crosshair)
						this.mod_aim_ult.modifier.target_id = last_enemy.id
						this.mod_aim_ult.modifier.duration = 1e+99
						this.mod_aim_ult.render.sprites[1].ts = store.tick_ts

						if ult_dummy then
							this.mod_aim_ult.pred_damage = U.predict_damage(last_enemy, ult_dummy)
						end

						queue_insert(store, this.mod_aim_ult)
					elseif not last_enemy or last_enemy.health.dead then
						local prediction = ult.shoot_time + delay_before_shot
						local _, enemies, pos = U.find_foremost_enemy(store.entities, pred_pos, 0, ult.retarget_range, prediction, ult.vis_flags, ult.vis_bans, ult.filter_fn)

						if enemies and #enemies ~= 0 then
							if this.tower_upgrade_persistent_data.current_mode == MODE_HP then
								table.sort(enemies, function(v1, v2)
									return v1.health.hp_max > v2.health.hp_max
								end)
							end

							last_enemy = enemies[1]
							pred_pos = pos

							if this.mod_aim_ult then
								queue_remove(store, this.mod_aim_ult)
							end

							this.mod_aim_ult = E:create_entity(ult.mod_crosshair)
							this.mod_aim_ult.modifier.target_id = last_enemy.id
							this.mod_aim_ult.modifier.duration = 1e+99
							this.mod_aim_ult.render.sprites[1].ts = store.tick_ts
							this.mod_aim_ult.render.sprites[1].name = "idle" .. i

							if ult_dummy then
								this.mod_aim_ult.pred_damage = U.predict_damage(last_enemy, ult_dummy)
							end

							queue_insert(store, this.mod_aim_ult)
						else
							last_enemy = nil
						end
					else
						local node_offset = P:predict_enemy_node_advance(last_enemy, ult.node_prediction)
						local e_ni = last_enemy.nav_path.ni + node_offset

						pred_pos = P:node_pos(last_enemy.nav_path.pi, last_enemy.nav_path.spi, e_ni)
					end

					if i == 1 then
						U.y_wait(store, fts(15))
						U.y_animation_play(this, "aimstart", pred_pos.x < tpos(this).x, store.tick_ts, 1, this.render.bottom_sid)
						do_anim("aim", true, pred_pos)
						shoot_ult(last_enemy, pred_pos, "shot")
					else
						U.y_wait(store, delay_before_shot)
						shoot_ult(last_enemy, pred_pos, "shot" .. i)
					end

					U.y_wait(store, delay_after_shot)
				end

				this.mod_aim_ult.modifier.duration = 0

				U.y_animation_wait(this, this.render.bottom_sid)

				local an, af = do_anim("to_reload", false, pred_pos)
				local flip = af and -1 or 1
				local smoke = E:create_entity(this.smoke_t)

				smoke.pos.x = this.pos.x + this.render.sprites[this.render.top_sid].offset.x + ult.smoke_offset[an].x * flip
				smoke.pos.y = this.pos.y + this.render.sprites[this.render.top_sid].offset.y + ult.smoke_offset[an].y
				smoke.render.sprites[1].ts = store.tick_ts
				smoke.render.sprites[1].name = an
				smoke.render.sprites[1].flip_x = af

				queue_insert(store, smoke)

				while not U.animation_finished(this, this.render.bottom_sid) do
					coroutine.yield()
				end

				this.tower_upgrade_persistent_data.disable_change_mode = false

				do_anim("reload", true, pred_pos)

				ult.ts = store.tick_ts - ult.crosshair_time

				signal.emit("tower-ultimate-used", this)
				do_anim("idle", false, pred_pos, true)

				goto label_851_0
			end

			::label_851_1::

			if sba and not sba.disabled and store.tick_ts - sba.ts > sba.cooldown then
				shoot(sba)
			elseif store.tick_ts - ba.ts > ba.cooldown then
				shoot(ba)
			else
				coroutine.yield()
			end
		end
	end
end

function scripts.tower_sniper.remove(this, store)
	this.tower_upgrade_persistent_data.disable_change_mode = false

	if this.mod_aim then
		this.mod_aim.modifier.duration = 0
	end

	if this.mod_aim_ult then
		this.mod_aim_ult.modifier.duration = 0
	end

	if this.decal_flare_ult then
		queue_remove(store, this.decal_flare_ult)
	end

	if this.decal_skill_c then
		queue_remove(store, this.decal_skill_c)
	end

	return true
end

scripts.mod_sniper_aim = {}

function scripts.mod_sniper_aim.queue(this, store, insertion)
	local target = store.entities[this.modifier.target_id]

	if not target then
		return
	end

	local dmg = this.pred_damage or 0

	if insertion then
		target._sniper_pred_damage = (target._sniper_pred_damage or 0) + dmg
		this._applied_damage = dmg
	elseif this._applied_damage then
		target._sniper_pred_damage = (target._sniper_pred_damage or 0) - this._applied_damage
		this._applied_damage = nil
	end
end

function scripts.mod_sniper_aim.dequeue(this, store, insertion)
	local target = store.entities[this.modifier.target_id]

	if not target then
		return
	end

	if insertion and this._applied_damage then
		target._sniper_pred_damage = (target._sniper_pred_damage or 0) - this._applied_damage
		this._applied_damage = nil
	end
end

scripts.decal_sniper_skill_c = {}

function scripts.decal_sniper_skill_c.update(this, store, script)
	local home = V.vclone(this.pos)
	local return_point = v(this.pos.x, this.pos.y - 5)
	local return_point_back = v(this.pos.x, this.pos.y + 5)
	local attack_ts = store.tick_ts - this.cooldown
	local idle_ts = store.tick_ts
	local tower = store.entities[this.tower_id]

	if not tower then
		queue_remove(store, this)

		return
	end

	local function y_run_to(pos, anim)
		local flip = pos.x < this.pos.x

		U.set_destination(this, pos)
		U.animation_start(this, anim, flip, store.tick_ts, true, 1)

		while not U.walk(this, store.tick_length) do
			coroutine.yield()
		end

		if pos == return_point or pos == return_point_back then
			this.pos = V.vclone(home)
		end

		return flip
	end

	while true do
		if store.tick_ts - idle_ts > this.idle_cd then
			U.animation_start(this, "inhouseeveryxseconds", false, store.tick_ts, false, 1)

			while not U.animation_finished(this) do
				if store.tick_ts - attack_ts > this.cooldown and U.find_foremost_enemy(store.entities, this.pos, 0, this.range, 0, this.vis_flags, this.vis_bans) ~= nil then
					idle_ts = store.tick_ts

					goto label_866_0
				end

				coroutine.yield()
			end

			idle_ts = store.tick_ts

			U.animation_start(this, "inhouse", false, store.tick_ts, true, 1)
		end

		::label_866_0::

		if store.tick_ts - attack_ts > this.cooldown and not tower.tower.blocked then
			local target = U.find_foremost_enemy(store.entities, this.pos, 0, this.range, 0, this.vis_flags, this.vis_bans)

			if not target then
				-- block empty
			else
				S:queue(this.sound_cast)

				local anim = target.pos.y <= this.pos.y and "abouttogoout" or "abouttogoout2"

				U.y_animation_play(this, anim, false, store.tick_ts, 1, 1)

				local mod_duration = V.dist(this.pos.x, this.pos.y, target.pos.x, target.pos.y) / this.motion.max_speed + fts(45)
				local mod = E:create_entity(this.mod_stun)

				mod.modifier.source_id = this.id
				mod.modifier.target_id = target.id
				mod.modifier.duration = mod_duration

				queue_insert(store, mod)

				local front = math.abs(km.signed_unroll(target.heading.angle)) < math.pi / 2 and 1 or -1
				local slot = V.v(target.pos.x + (target.enemy.melee_slot.x + this.attack_offset.x) * front, target.pos.y + target.enemy.melee_slot.y + this.attack_offset.y)
				local flip = y_run_to(slot, "run")

				target = store.entities[target.id]

				if target and not target.health.dead then
					U.animation_start(this, "attack", target.pos.x < this.pos.x, store.tick_ts, false, 1)
					S:queue(this.sound_dmg)

					local anim_ts = store.tick_ts

					for _, v in ipairs(this.hit_times) do
						while v > store.tick_ts - anim_ts do
							coroutine.yield()
						end

						if target and not target.health.dead then
							local d = E:create_entity("damage")

							d.source_id = this.id
							d.target_id = target.id
							d.damage_type = this.damage_type
							d.value = math.ceil(U.frandom(this.damage_min * tower.tower.damage_factor, this.damage_max * tower.tower.damage_factor))

							queue_damage(store, d)
						end
					end

					while not U.animation_finished(this, 1) do
						coroutine.yield()
					end
				end

				local return_anim = string.find(anim, "2") and "goback2" or "goback"
				local return_to = string.find(anim, "2") and return_point_back or return_point

				y_run_to(return_to, "run")
				U.y_animation_play(this, return_anim, false, store.tick_ts, 1, 1)

				attack_ts = store.tick_ts
				idle_ts = store.tick_ts

				U.animation_start(this, "inhouse", false, store.tick_ts, true, 1)
			end
		end

		coroutine.yield()
	end
end

scripts.aura_upgrades_barracks_l4b = {}

function scripts.aura_upgrades_barracks_l4b.update(this, store, script)
	local target = store.entities[this.aura.source_id]

	local function condition()
		return target.health.hp <= target.health.hp_max * this.hp_ptg_to_trigger
	end

	local ts = store.tick_ts
	local mod

	while true do
		if store.tick_ts - ts > this.aura.cycle_time then
			if condition() and not mod then
				mod = E:create_entity(this.aura.mod)
				mod.modifier.target_id = this.aura.source_id

				queue_insert(store, mod)
			end

			if not condition() and mod then
				queue_remove(store, mod)

				mod = nil
			end
		end

		if not target or target.health.dead then
			queue_remove(store, this)
		end

		coroutine.yield()
	end
end

scripts.mod_track_fx = {}

function scripts.mod_track_fx.update(this, store, script)
	local m = this.modifier

	this.modifier.ts = store.tick_ts

	local target = store.entities[m.target_id]

	if not target or not target.pos then
		queue_remove(store, this)

		return
	end

	this.pos = target.pos

	if this.tween then
		this.tween.ts = store.tick_ts
		this.tween.disabled = false

		U.animation_start(this, this.animation_loop, nil, store.tick_ts, true)
		U.y_wait(store, this.tween.props[1].keys[2][1])
	else
		U.y_animation_play(this, this.animation_start, nil, store.tick_ts, 1)
	end

	if this.sound_events.insert then
		S:queue(this.sound_events.insert)
	end

	while true do
		target = store.entities[m.target_id]

		if not target or target.health.dead or m.duration >= 0 and store.tick_ts - m.ts > m.duration or m.last_node and target.nav_path.ni > m.last_node then
			if this.tween then
				this.tween.ts = store.tick_ts
				this.tween.reverse = true
				this.tween.disabled = false

				U.y_wait(store, this.tween.props[1].keys[2][1])
			else
				U.y_animation_play(this, this.animation_end, nil, store.tick_ts, 1)
			end

			queue_remove(store, this)

			return
		end

		if this.render and target.unit then
			local s = this.render.sprites[1]
			local flip_sign = 1

			if target.render then
				flip_sign = target.render.sprites[1].flip_x and -1 or 1
			end

			if m.health_bar_offset and target.health_bar then
				local hb = target.health_bar.offset
				local hbo = m.health_bar_offset

				s.offset.x, s.offset.y = hb.x + hbo.x * flip_sign, hb.y + hbo.y
			elseif m.use_mod_offset and target.unit.mod_offset then
				s.offset.x, s.offset.y = target.unit.mod_offset.x * flip_sign, target.unit.mod_offset.y
			end
		end

		U.animation_start(this, this.animation_loop, nil, store.tick_ts, true)
		coroutine.yield()
	end
end

scripts.arrow_KR6_fixed_height = {}

function scripts.arrow_KR6_fixed_height.insert(this, store, script)
	this.bullet.flight_time = 2 * (math.sqrt(2 * this.bullet.fixed_height * this.bullet.g * -1) / this.bullet.g * -1)

	return scripts.arrow.insert(this, store, script)
end

scripts.arrow_KR6_45_degrees = {}

function scripts.arrow_KR6_45_degrees.insert(this, store, script)
	local dist = V.dist(this.bullet.to.x, this.bullet.to.y, this.bullet.from.x, this.bullet.from.y)

	this.bullet.flight_time = math.sqrt(2 * dist / -this.bullet.g)

	if this.bullet.flight_time_variance then
		this.bullet.flight_time = this.bullet.flight_time + fts(math.random(0, this.bullet.flight_time_variance))
	end

	return scripts.arrow.insert(this, store, script)
end

scripts.arrow_KR6 = {}

function scripts.arrow_KR6.update(this, store, script)
	local b = this.bullet
	local ps
	local s = this.render.sprites[1]
	local bullet_fly = true

	if b.particles_name then
		ps = E:create_entity(b.particles_name)
		ps.particle_system.track_id = this.id

		queue_insert(store, ps)
	end

	local target = store.entities[b.target_id]

	while bullet_fly and store.tick_ts - b.ts + store.tick_length <= b.flight_time do
		coroutine.yield()

		b.last_pos.x, b.last_pos.y = this.pos.x, this.pos.y
		this.pos.x, this.pos.y = SU.position_in_parabola(store.tick_ts - b.ts, b.from, b.speed, b.g)

		if b.rotation_speed then
			s.r = s.r + b.rotation_speed * store.tick_length
		else
			s.r = V.angleTo(this.pos.x - b.last_pos.x, this.pos.y - b.last_pos.y)

			if b.asymmetrical and math.abs(s.r) > math.pi / 2 then
				s.flip_y = true
			end
		end

		if ps then
			ps.particle_system.emit_direction = s.r
		end

		if b.hide_radius then
			local at_start = V.dist(this.pos.x, this.pos.y, b.from.x, b.from.y) < b.hide_radius
			local at_end = V.dist(this.pos.x, this.pos.y, b.to.x, b.to.y) < b.hide_radius

			s.hidden = at_start or at_end

			if ps then
				if b.extend_particles_cutoff then
					ps.particle_system.emit = not at_start
				else
					ps.particle_system.emit = not s.hidden
				end
			end
		end

		local _, future_pos_y = SU.position_in_parabola(store.tick_ts - b.ts + store.tick_length, b.from, b.speed, b.g)

		if future_pos_y - this.pos.y < 0 and target and (target.unit and future_pos_y < target.pos.y + target.unit.hit_offset.y or future_pos_y < target.pos.y) and math.abs(this.pos.x - b.to.x) < b.hit_distance then
			bullet_fly = false
		end
	end

	local hit = false
	local target = store.entities[b.target_id]

	if target and target.health and not target.health.dead then
		local target_pos = V.vclone(target.pos)

		if target.unit and target.unit.hit_offset and not b.ignore_hit_offset then
			target_pos.x, target_pos.y = target_pos.x + target.unit.hit_offset.x, target_pos.y + target.unit.hit_offset.y
		end

		if V.dist(this.pos.x, this.pos.y, target_pos.x, target_pos.y) < b.hit_distance and not SU.unit_dodges(store, target, true) and (not b.hit_chance or math.random() < b.hit_chance) then
			hit = true

			if b.disabled_dmg_factor and b.disabled_dmg_factor ~= 1 and is_disabled(store, target) then
				b.damage_min = b.damage_min * b.disabled_dmg_factor
				b.damage_max = b.damage_max * b.disabled_dmg_factor
			end

			if b.max_dmg_unarmored and target.health.armor == 0 then
				b.damage_min = b.damage_max
			end

			local d = SU.create_bullet_damage(b, target.id, this.id)

			queue_damage(store, d)

			local will_kill = U.predict_damage(target, d) > target.health.hp

			if b.extra_gold and b.extra_gold > 0 and will_kill then
				if b.hit_fx_coins then
					local sfx = E:create_entity(b.hit_fx_coins)

					sfx.pos = V.vclone(b.to)
					sfx.render.sprites[1].ts = store.tick_ts

					queue_insert(store, sfx)

					local gold_pos = V.v(sfx.pos.x, sfx.pos.y)
				end

				signal.emit("got-gold", b.to, b.extra_gold)
			end

			if b.mod then
				local mods = type(b.mod) == "table" and b.mod or {
					b.mod
				}

				for _, mod_name in pairs(mods) do
					local mod = E:create_entity(mod_name)

					mod.modifier.source_id = this.id
					mod.modifier.target_id = target.id
					mod.modifier.level = b.level
					mod.modifier.source_damage = d

					queue_insert(store, mod)
				end
			end

			if b.hit_fx then
				local fx = E:create_entity(b.hit_fx)

				fx.pos = V.vclone(target_pos)
				fx.render.sprites[1].ts = store.tick_ts

				if b.flip_hit_fx then
					fx.render.sprites[1].flip_x = b.to.x < b.from.x
				end

				queue_insert(store, fx)
			end

			if b.hit_blood_fx and target.unit.blood_color ~= BLOOD_NONE then
				local sfx = E:create_entity(b.hit_blood_fx)

				sfx.pos = V.vclone(target_pos)
				sfx.render.sprites[1].ts = store.tick_ts

				if sfx.use_blood_color and target.unit.blood_color then
					sfx.render.sprites[1].name = target.unit.blood_color
					sfx.render.sprites[1].r = s.r
				end

				queue_insert(store, sfx)
			end
		end

		if target and target.dodge and target.dodge.active and target.dodge.show_pop then
			SU.show_dodge_pop(store, target)
		end
	end

	if this.sound_events.hit then
		S:queue(this.sound_events.hit)
	end

	if not hit then
		if GR:cell_is(this.pos.x, this.pos.y, TERRAIN_WATER) then
			if b.miss_fx_water then
				local water_fx = E:create_entity(b.miss_fx_water)

				water_fx.pos.x, water_fx.pos.y = b.to.x, b.to.y
				water_fx.render.sprites[1].ts = store.tick_ts

				queue_insert(store, water_fx)
			end
		else
			if b.miss_fx then
				local fx = E:create_entity(b.miss_fx)

				fx.pos.x, fx.pos.y = b.to.x, b.to.y
				fx.render.sprites[1].ts = store.tick_ts
				fx.render.sprites[1].flip_x = b.from.x > this.pos.x

				queue_insert(store, fx)
			end

			if b.miss_decal and (GR:cell_is(b.to.x, b.to.y, TERRAIN_LAND) or GR:cell_is(b.to.x, b.to.y, TERRAIN_ICE)) then
				if #E:search_entity(b.miss_decal) > 0 then
					local decal = E:create_entity(b.miss_decal)

					decal.pos = V.vclone(b.to)
					decal.render.sprites[1].ts = store.tick_ts
					decal.render.sprites[1].flip_x = b.from.x > this.pos.x

					queue_insert(store, decal)
				else
					local decal = E:create_entity("decal_tween")

					decal.pos = V.vclone(b.to)
					decal.tween.props[1].keys = {
						{
							0,
							255
						},
						{
							2.1,
							0
						}
					}
					decal.render.sprites[1].ts = store.tick_ts
					decal.render.sprites[1].name = b.miss_decal
					decal.render.sprites[1].animated = false
					decal.render.sprites[1].z = Z_DECALS

					if b.rotation_speed then
						decal.render.sprites[1].flip_x = b.rotation_speed > 0
					elseif this.render.sprites[1].r then
						decal.render.sprites[1].r = this.render.sprites[1].r
					else
						decal.render.sprites[1].r = -math.pi / 2 * (1 + (0.5 - math.random()) * 0.35)
					end

					if b.miss_decal_anchor then
						decal.render.sprites[1].anchor = b.miss_decal_anchor
					end

					queue_insert(store, decal)
				end
			end
		end
	end

	if b.payload then
		local p = E:create_entity(b.payload)

		p.pos.x, p.pos.y = b.to.x, b.to.y
		p.target_id = b.target_id
		p.source_id = this.id
		p.missed = not hit

		if p.aura then
			p.aura.level = b.level
		end

		if b.transfer_payload_r and p.render then
			for i = 1, #p.render.sprites do
				p.render.sprites[i].r = s.r
			end
		end

		queue_insert(store, p)
	end

	if ps then
		if b.extend_particles_cutoff then
			ps.particle_system.emit = true

			coroutine.yield()
		end

		if ps.particle_system.emit then
			s.hidden = true
			ps.particle_system.emit = false

			U.y_wait(store, ps.particle_system.particle_lifetime[2])
		end
	end

	queue_remove(store, this)
end

scripts.bullet_ricochet = {}

function scripts.bullet_ricochet.update(this, store)
	local b = this.bullet
	local target, ps

	this.bounces = 0

	local already_hit = {}
	local tower = store.entities[b.source_id]
	local skill_level
	local bounce_damage = -1

	b.speed.x, b.speed.y = V.normalize(b.to.x - b.from.x, b.to.y - b.from.y)

	if b.particles_name then
		ps = E:create_entity(b.particles_name)
		ps.particle_system.track_id = this.id

		queue_insert(store, ps)
	end

	if b.damage_min_config then
		skill_level = tower.powers.skill_gold.level
		b.damage_min = b.damage_min_config[skill_level]
		b.damage_max = b.damage_max_config[skill_level]
	end

	::label_874_0::

	while V.dist2(this.pos.x, this.pos.y, b.to.x, b.to.y) > b.fixed_speed * store.tick_length * (b.fixed_speed * store.tick_length) do
		target = store.entities[b.target_id]

		if target and target.health and not target.health.dead then
			b.to.x, b.to.y = target.pos.x + target.unit.hit_offset.x, target.pos.y + target.unit.hit_offset.y
		end

		b.speed.x, b.speed.y = V.mul(b.fixed_speed, V.normalize(b.to.x - this.pos.x, b.to.y - this.pos.y))
		this.pos.x, this.pos.y = this.pos.x + b.speed.x * store.tick_length, this.pos.y + b.speed.y * store.tick_length
		this.render.sprites[1].r = V.angleTo(b.to.x - this.pos.x, b.to.y - this.pos.y)

		coroutine.yield()
	end

	local will_kill

	if target and not target.health.dead then
		local d = SU.create_bullet_damage(b, target.id, this.id)

		if b.bounce_damage_mult then
			if bounce_damage == -1 then
				bounce_damage = d.value
			else
				d.value = bounce_damage
			end
		end

		queue_damage(store, d)

		will_kill = U.predict_damage(target, d) >= target.health.hp

		table.insert(already_hit, target.id)

		local mods = b.mods or {
			b.mod
		}

		for _, mod_name in pairs(mods) do
			local new_mod = E:create_entity(mod_name)

			new_mod.modifier.level = this.bullet.level
			new_mod.modifier.target_id = target.id
			new_mod.modifier.source_id = this.id

			queue_insert(store, new_mod)
		end

		S:queue(this.sound_hit)
	end

	if this.gold_chance and will_kill then
		local stole_gold = math.random(0, 100) <= this.gold_chance * 100

		if stole_gold then
			local sfx = E:create_entity(b.hit_fx_coins)

			sfx.pos = V.vclone(b.to)
			sfx.render.sprites[1].ts = store.tick_ts

			queue_insert(store, sfx)

			local gold_pos = V.v(sfx.pos.x, sfx.pos.y)

			signal.emit("got-gold", gold_pos, this.gold_extra[skill_level])
		end
	end

	if b.hit_fx then
		local sfx = E:create_entity(b.hit_fx)

		sfx.pos = V.vclone(b.to)
		sfx.render.sprites[1].ts = store.tick_ts

		queue_insert(store, sfx)
	end

	S:queue(this.sound)

	if this.bounces < this.max_bounces then
		local targets = U.find_enemies_in_range(store.entities, this.pos, 0, this.bounce_range, b.vis_flags, b.vis_bans, function(v)
			return not table.contains(already_hit, v.id)
		end)

		if not targets and this.repeat_targets then
			if target and not target.health.dead then
				already_hit = {
					target.id
				}
			else
				already_hit = {}
			end

			targets = U.find_enemies_in_range(store.entities, this.pos, 0, this.bounce_range, b.vis_flags, b.vis_bans, function(v)
				return not table.contains(already_hit, v.id)
			end)
		end

		if targets then
			table.sort(targets, function(e1, e2)
				return V.dist2(this.pos.x, this.pos.y, e1.pos.x, e1.pos.y) < V.dist2(this.pos.x, this.pos.y, e2.pos.x, e2.pos.y)
			end)

			local target = targets[1]

			this.bounces = this.bounces + 1
			b.to.x, b.to.y = target.pos.x + target.unit.hit_offset.x, target.pos.y + target.unit.hit_offset.y
			b.target_id = target.id

			if this.bounce_speed_mult then
				b.fixed_speed = b.fixed_speed * this.bounce_speed_mult
			end

			if this.bounce_damage_mult then
				b.damage_min = bounce_damage * this.bounce_damage_mult
				b.damage_max = bounce_damage * this.bounce_damage_mult
				bounce_damage = bounce_damage * this.bounce_damage_mult
			end

			S:queue(this.sound_bounce)

			goto label_874_0
		end
	end

	queue_remove(store, this)
end

scripts.bullet_demon_flareon = {}

function scripts.bullet_demon_flareon.update(this, store, script)
	local b = this.bullet
	local s = this.render.sprites[1]
	local ps

	if b.particles_name then
		ps = E:create_entity(b.particles_name)
		ps.particle_system.track_id = this.id

		queue_insert(store, ps)
	end

	while store.tick_ts - b.ts + store.tick_length <= b.flight_time do
		coroutine.yield()

		local target = store.entities[b.target_id]

		if target and not target.health.dead then
			local ho = target.unit.hit_offset

			b.to.x, b.to.y = target.pos.x + ho.x, target.pos.y + ho.y
			b.speed = SU.initial_parabola_speed(b.from, b.to, b.flight_time, b.g)
		end

		b.last_pos.x, b.last_pos.y = this.pos.x, this.pos.y
		this.pos.x, this.pos.y = SU.position_in_parabola(store.tick_ts - b.ts, b.from, b.speed, b.g)
		s.r = V.angleTo(this.pos.x - b.last_pos.x, this.pos.y - b.last_pos.y)

		if ps then
			ps.particle_system.emit_direction = s.r
		end
	end

	local target = store.entities[b.target_id]

	if target and not target.health.dead then
		local d = SU.create_bullet_damage(b, target.id, this.id)

		queue_damage(store, d)

		if b.mod then
			local m = E:create_entity(b.mod)

			m.modifier.target_id = target.id
			m.modifier.source_id = b.source_id

			queue_insert(store, m)
		end
	end

	if b.hit_fx then
		local fx = E:create_entity(b.hit_fx)

		fx.pos.x, fx.pos.y = b.to.x, b.to.y
		fx.render.sprites[1].ts = store.tick_ts

		queue_insert(store, fx)
	end

	if this.sound_events.hit then
		S:queue(this.sound_events.hit)
	end

	queue_remove(store, this)
end

scripts.missile_KR6 = {}

function scripts.missile_KR6.update(this, store, script)
	local b = this.bullet
	local target = store.entities[b.target_id]
	local mspeed = b.min_speed
	local rot_dir = 1
	local follow = false
	local max_seek_angle = b.max_seek_angle or 0.2

	local function is_target_valid(target)
		return target and (not target.health or not target.health.dead) and band(target.vis.bans, b.vis_flags) == 0 and P:is_node_valid(target.nav_path.pi, target.nav_path.ni)
	end

	if this.render.sprites[1].animated then
		U.animation_start(this, "flying", nil, store.tick_ts, -1)
	end

	while V.dist2(this.pos.x, this.pos.y, b.to.x, b.to.y) > mspeed * store.tick_length * (mspeed * store.tick_length) do
		b.speed.x, b.speed.y = V.mul(mspeed, V.normalize(b.to.x - this.pos.x, b.to.y - this.pos.y))
		this.pos.x, this.pos.y = this.pos.x + b.speed.x * store.tick_length, this.pos.y + b.speed.y * store.tick_length
		this.render.sprites[1].r = V.angleTo(b.speed.x, b.speed.y)

		if b.rot_dir_from_long_angle and target then
			rot_dir = target.pos.x < this.pos.x and -1 or 1
		elseif b.speed.x < 0 then
			rot_dir = -1
		end

		coroutine.yield()
	end

	if not is_target_valid(target) then
		local ref_pos = target and target.pos or this.pos

		target = U.find_foremost_enemy(store.entities, ref_pos, 0, b.retarget_range, false, b.vis_flags)
	end

	if target then
		b.to.x, b.to.y = target.pos.x, target.pos.y

		if target.unit.hit_offset then
			b.to.x, b.to.y = b.to.x + target.unit.hit_offset.x, b.to.y + target.unit.hit_offset.y
		end
	end

	while V.dist2(this.pos.x, this.pos.y, b.to.x, b.to.y) > mspeed * store.tick_length * (mspeed * store.tick_length) do
		if not is_target_valid(target) then
			local ref_pos = target and target.pos or this.pos

			target = U.find_foremost_enemy(store.entities, ref_pos, 0, b.retarget_range, false, b.vis_flags)

			if b.rot_dir_from_long_angle and target then
				rot_dir = target.pos.x < this.pos.x and -1 or 1
			end
		end

		if target then
			b.to.x, b.to.y = target.pos.x, target.pos.y

			if target.unit.hit_offset then
				b.to.x, b.to.y = b.to.x + target.unit.hit_offset.x, b.to.y + target.unit.hit_offset.y
			end
		end

		local d_angle = V.angleTo(b.speed.x, b.speed.y, b.to.x - this.pos.x, b.to.y - this.pos.y)

		if max_seek_angle < math.abs(d_angle) then
			local rot = b.turn_speed * store.tick_length * rot_dir
			local dir = V.angleTo(b.speed.x, b.speed.y)

			if dir > math.pi / 3 and dir < 2 * math.pi / 3 then
				rot = rot * (b.turn_helicoidal_factor or 1.5)
			end

			b.speed.x, b.speed.y = V.rotate(rot, b.speed.x, b.speed.y)
		else
			mspeed = mspeed + 30 * math.ceil(mspeed * 0.03333333333333333 * b.acceleration_factor)
			mspeed = km.clamp(b.min_speed, b.max_speed, mspeed)
			b.speed.x, b.speed.y = V.mul(mspeed, V.normalize(b.to.x - this.pos.x, b.to.y - this.pos.y))
		end

		this.pos.x, this.pos.y = this.pos.x + b.speed.x * store.tick_length, this.pos.y + b.speed.y * store.tick_length
		this.render.sprites[1].r = V.angleTo(b.speed.x, b.speed.y)

		coroutine.yield()
	end

	if b.damage_radius and b.damage_radius > 0 then
		local enemies = U.find_enemies_in_range(store.entities, b.to, 0, b.damage_radius, b.damage_flags, b.damage_bans)

		if enemies then
			for _, enemy in pairs(enemies) do
				local enemy_pos = V.v(enemy.pos.x + enemy.unit.hit_offset.x, enemy.pos.y + enemy.unit.hit_offset.y)
				local d = E:create_entity("damage")

				d.source_id = this.id
				d.target_id = enemy.id
				d.damage_type = b.damage_type
				d.reduce_armor = b.reduce_armor
				d.reduce_magic_armor = b.reduce_magic_armor

				local dist_factor = U.dist_factor_inside_ellipse(enemy_pos, this.pos, b.damage_radius)

				d.value = math.floor(b.damage_max - (b.damage_max - b.damage_min) * dist_factor)
				d.value = math.ceil(b.damage_factor * d.value)

				queue_damage(store, d)

				if b.mod then
					local mod = E:create_entity(b.mod)

					mod.modifier.target_id = enemy.id

					queue_insert(store, mod)
				end
			end
		end
	elseif target then
		local d = SU.create_bullet_damage(b, target.id, this.id)

		queue_damage(store, d)

		if b.mod then
			local mod = E:create_entity(b.mod)

			mod.modifier.target_id = target.id

			queue_insert(store, mod)
		end
	end

	local fx

	if b.hit_fx_air and target and band(target.vis.flags, F_FLYING) ~= 0 then
		fx = b.hit_fx_air

		S:queue(this.sound_events.hit)
	elseif b.hit_fx_water and not target and band(GR:cell_type(b.to.x, b.to.y), TERRAIN_WATER) ~= 0 then
		fx = b.hit_fx_water

		S:queue(this.sound_events.hit_water)
	elseif b.hit_fx then
		fx = b.hit_fx

		S:queue(this.sound_events.hit)
	end

	if fx then
		local is_air = target and band(target.vis.flags, F_FLYING) ~= 0
		local sfx = E:create_entity(fx)

		if b.hit_fx_ignore_hit_offset and target and not is_air then
			sfx.pos.x, sfx.pos.y = target.pos.x, target.pos.y
		else
			sfx.pos.x, sfx.pos.y = this.pos.x, this.pos.y
		end

		sfx.render.sprites[1].ts = store.tick_ts

		queue_insert(store, sfx)
	end

	queue_remove(store, this)
end

scripts.mod_ray_arcane = {}

function scripts.mod_ray_arcane.update(this, store)
	local cycles, total_damage = 0, 0
	local m = this.modifier
	local dps = this.dps
	local target = store.entities[m.target_id]

	if not target or target.health.dead then
		queue_remove(store, this)

		return
	end

	local function apply_damage(value)
		local d = E:create_entity("damage")

		d.source_id = this.id
		d.target_id = target.id
		d.value = value
		d.damage_type = dps.damage_type
		d.pop = dps.pop
		d.pop_chance = dps.pop_chance
		d.pop_conds = dps.pop_conds

		queue_damage(store, d)

		total_damage = total_damage + value
	end

	local raw_damage = math.random(this.dps.damage_min, this.dps.damage_max)
	local extra_damage = math.max(0, raw_damage - target.health.hp)
	local total_cycles = m.duration / dps.damage_every
	local dps_damage = math.floor((raw_damage - extra_damage) / total_cycles)
	local first_damage = raw_damage - extra_damage - dps_damage * total_cycles

	this.pos = target.pos
	dps.ts = store.tick_ts
	m.ts = store.tick_ts

	while true do
		target = store.entities[m.target_id]

		if not target or target.health.dead then
			break
		end

		if total_cycles <= cycles then
			log.paranoid(">>>>> id:%s - mod_ray_arcane cycles:%s raw_damage:%s dps_damage:%s first_damage:%s total_damage:%s", this.id, cycles, raw_damage, dps_damage, first_damage, total_damage)
			apply_damage(extra_damage)

			break
		end

		if this.render and m.use_mod_offset and target.unit.hit_offset then
			for _, s in ipairs(this.render.sprites) do
				s.offset.x, s.offset.y = target.unit.hit_offset.x, target.unit.hit_offset.y
			end
		end

		if dps.damage_every and store.tick_ts - dps.ts >= dps.damage_every then
			cycles = cycles + 1
			dps.ts = dps.ts + dps.damage_every

			apply_damage(dps_damage + (cycles == 1 and first_damage or 0))
		end

		coroutine.yield()
	end

	queue_remove(store, this)
end

scripts.click_play_and_idle = {}

function scripts.click_play_and_idle.update(this, store, script)
	local s = this.render.sprites[1]
	local c = this.click_play
	local clicks = 0
	local already_played = false

	while true do
		if this.ui.clicked then
			this.ui.clicked = nil
			clicks = clicks + 1
		end

		if c.play_once and already_played then
			-- block empty
		elseif clicks >= c.required_clicks then
			if this.tween then
				this.tween.disabled = false
			elseif not c.idle_animation then
				s.hidden = false
			end

			S:queue(c.clicked_sound)
			U.y_animation_play(this, c.click_animation, nil, store.tick_ts, 1)

			this.ui.clicked = nil
			clicks = 0
			already_played = true

			if not c.idle_animation then
				s.hidden = true
			else
				U.animation_start(this, c.idle_animation, nil, store.tick_ts, true)
			end

			if c.achievement then
				AC:got(c.achievement)
			end

			if c.achievement_flag then
				AC:flag_check(unpack(c.achievement_flag))
			end
		end

		coroutine.yield()
	end
end

scripts.decal_scripted_loop_play = {}

function scripts.decal_scripted_loop_play.update(this, store, script)
	while true do
		for _, anim_data in ipairs(this.animations) do
			local anim = anim_data[1]
			local wait_time = anim_data[2]
			local loops = 1

			if anim_data[3] then
				loops = anim_data[3]
			end

			U.y_animation_play(this, anim, nil, store.tick_ts, loops)
			U.y_wait(store, wait_time)
		end

		coroutine.yield()
	end
end

scripts.ray5_simple = {}

function scripts.ray5_simple.update(this, store)
	local b = this.bullet
	local s = this.render.sprites[1]
	local target = store.entities[b.target_id]
	local source = store.entities[b.source_id]
	local dest = V.vclone(b.to)
	local tower = this.tower_ref
	local hit_counter = 0
	local mods_added = {}
	local fx

	local function create_fx(hfx)
		local sfx = E:create_entity(hfx)

		sfx.render.sprites[1].ts = store.tick_ts

		local is_air = target and band(target.vis.flags, F_FLYING) ~= 0

		if b.hit_fx_ignore_hit_offset and target and not is_air then
			sfx.pos.x, sfx.pos.y = target.pos.x, target.pos.y
		elseif target then
			local hoffset = target.unit.hit_offset

			sfx.pos.x, sfx.pos.y = target.pos.x + hoffset.x, target.pos.y + hoffset.y
		end

		if sfx.allow_rotation and target and source then
			local vx, vy = V.sub(target.pos.x, target.pos.y, source.pos.x, source.pos.y)
			local r = km.unroll(V.angleTo(vx, vy))

			sfx.render.sprites[1].r = r
		end

		queue_insert(store, sfx)
	end

	local function update_sprite()
		if this.track_target and target and target.motion then
			local tpx, tpy = target.pos.x, target.pos.y

			if not b.ignore_hit_offset then
				tpx, tpy = tpx + target.unit.hit_offset.x, tpy + target.unit.hit_offset.y
			end

			local d = math.max(math.abs(tpx - b.to.x), math.abs(tpy - b.to.y))

			if d > b.max_track_distance then
				log.paranoid("(%s) ray_simple target (%s) out of max_track_distance", this.id, target.id)

				target = nil
			else
				dest.x, dest.y = target.pos.x, target.pos.y

				if target.unit and target.unit.hit_offset then
					dest.x, dest.y = dest.x + target.unit.hit_offset.x, dest.y + target.unit.hit_offset.y
				end
			end
		else
			dest.x, dest.y = b.to.x, b.to.y
		end

		local a_override_x = this.a_override and this.a_override.x or 1
		local a_override_y = this.a_override and this.a_override.y or 0
		local angle = V.angleTo(dest.x - this.pos.x, dest.y - this.pos.y, a_override_x, a_override_y)

		s.r = angle

		local dist_offset = 0

		if this.dist_offset then
			dist_offset = this.dist_offset
		end

		if this.scale_y then
			s.scale.y = (V.dist(dest.x, dest.y, this.pos.x, this.pos.y) + dist_offset) / this.image_width
		else
			s.scale.x = (V.dist(dest.x, dest.y, this.pos.x, this.pos.y) + dist_offset) / this.image_width
		end

		if this.sort_front_of_target and target then
			this.render.sprites[1].sort_y_offset = target.pos.y - this.pos.y - 1
		end
	end

	local function hit()
		hit_counter = hit_counter + 1

		if target and b.damage_type ~= DAMAGE_NONE then
			local d = SU.create_bullet_damage(b, target.id, b.track_kills and b.source_id or this.id)

			d.track_kills = b.track_kills ~= nil

			queue_damage(store, d)
		end

		if target and (b.mod or b.mods) then
			local mods = b.mods or {
				b.mod
			}

			for _, mod_name in pairs(mods) do
				local m = E:create_entity(mod_name)

				m.modifier.target_id = b.target_id

				if m.damage_from_bullet then
					if m.dps then
						m.dps.damage_min = b.damage_min * b.damage_factor
						m.dps.damage_max = b.damage_max * b.damage_factor
					else
						m.modifier.damage_min = b.damage_min * b.damage_factor
						m.modifier.damage_max = b.damage_max * b.damage_factor
					end
				else
					local level

					if not tower then
						level = this.bullet.level
					else
						level = tower.level
						level = level or this.bullet.level
					end

					m.modifier.level = level
				end

				table.insert(mods_added, m)
				queue_insert(store, m)
			end
		end

		if b.hit_payload then
			local hp

			if type(b.hit_payload) == "string" then
				hp = E:create_entity(b.hit_payload)
			else
				hp = b.hit_payload
			end

			if hp.aura then
				hp.aura.level = this.bullet.level
				hp.aura.source_id = this.id

				if target then
					hp.pos.x, hp.pos.y = target.pos.x, target.pos.y
				else
					hp.pos.x, hp.pos.y = dest.x, dest.y
				end

				if hp.aura.damage_factor then
					hp.aura.damage_factor = b.damage_factor
				end
			else
				hp.pos.x, hp.pos.y = dest.x, dest.y
			end

			queue_insert(store, hp)
		end

		local disable_hit = false

		if this.hit_fx_only_no_target then
			disable_hit = target ~= nil and not target.health.dead
		end

		if (not target or target.health.dead) and b.miss_fx then
			local mfx = E:create_entity(b.miss_fx)

			if target then
				mfx.pos.x, mfx.pos.y = target.pos.x, target.pos.y
			else
				mfx.pos.x, mfx.pos.y = dest.x, dest.y
			end

			mfx.render.sprites[1].ts = store.tick_ts

			queue_insert(store, mfx)
		else
			local hfx

			if b.hit_fxs and #b.hit_fxs > 0 and not disable_hit then
				for i = 1, #b.hit_fxs do
					create_fx(b.hit_fxs[i])
				end
			elseif b.hit_fx and not disable_hit then
				create_fx(b.hit_fx)
			end
		end

		if b.hit_decal then
			local produce_hit_decal = false

			if this.hit_decal_times == -1 then
				produce_hit_decal = hit_counter == 1
			else
				produce_hit_decal = not this.hit_decal_times or hit_counter % this.hit_decal_times == 0
			end

			if produce_hit_decal then
				local decal = E:create_entity(b.hit_decal)

				if this.hit_decal_offset then
					decal.pos.x = dest.x + math.random(-this.hit_decal_offset.x, this.hit_decal_offset.x)
					decal.pos.y = dest.y + math.random(-this.hit_decal_offset.y, this.hit_decal_offset.y)
				else
					decal.pos.x = dest.x
					decal.pos.y = dest.y
				end

				decal.render.sprites[1].ts = store.tick_ts
				decal.source_id = b.source_id

				queue_insert(store, decal)
			end
		end
	end

	if not b.ignore_hit_offset and this.track_target and target and target.motion then
		b.to.x, b.to.y = target.pos.x + target.unit.hit_offset.x, target.pos.y + target.unit.hit_offset.y
	end

	s.scale = s.scale or V.v(1, 1)
	s.ts = store.tick_ts

	update_sprite()

	s.hidden = this.hide_during_trajectory == nil and true or this.hide_during_trajectory

	if b.hit_time > fts(1) then
		local hit_ts = store.tick_ts

		while store.tick_ts - hit_ts < b.hit_time do
			coroutine.yield()

			if target and U.flag_has(target.vis.bans, F_RANGED) then
				target = nil
			end

			if this.track_target then
				update_sprite()
			end
		end
	end

	hit()

	if this.ray_duration then
		local ray_ts = store.tick_ts
		local hit_ts = store.tick_ts

		while store.tick_ts - ray_ts < this.ray_duration do
			if this.track_target then
				update_sprite()
			end

			if tower and not store.entities[tower.id] then
				queue_remove(store, this)

				if fx then
					queue_remove(store, fx)
				end

				for key, value in pairs(mods_added) do
					queue_remove(store, value)
				end

				break
			end

			if this.hit_over_duration then
				update_sprite()

				if store.tick_ts - hit_ts > this.hit_cycle_time then
					hit_ts = store.tick_ts

					hit()
				end
			end

			coroutine.yield()

			s.hidden = false
		end
	else
		while not U.animation_finished(this, 1) do
			if tower and not store.entities[tower.id] then
				queue_remove(store, this)

				break
			end

			coroutine.yield()
		end
	end

	if this.end_animation then
		U.y_animation_play(this, this.end_animation, s.flip_x, store.tick_ts, 1, 1)
	end

	queue_remove(store, this)
end

scripts.decal_soldier_shadow = {}

function scripts.decal_soldier_shadow.update(this, store, script)
	while true do
		if this.entity.health.dead then
			if not this.entity.health.last_damage_types == 0 then
				U.y_wait(store, fts(this.dissapear_time))
			end

			queue_remove(store, this)

			return
		end

		local offset_y = this.entity.render.sprites[1].offset.y
		local shadow_scale = 1 - this.shadow_shrink * offset_y / this.max_height

		this.render.sprites[1].scale = v(shadow_scale, shadow_scale)

		coroutine.yield()
	end
end

scripts.background_sounds_kr5 = {}

function scripts.background_sounds_kr5.update(this, store, script)
	while true do
		local delay = math.random(this.min_delay, this.max_delay)

		U.y_wait(store, delay)

		if store.wave_group_number > 0 and this.only_on_preparation then
			queue_remove(store, this)

			return
		end

		S:queue(this.sounds[math.random(#this.sounds)])
	end
end

scripts.tower_holder_capture = {}

function scripts.tower_holder_capture.insert(this, store, script)
	this.tween.props[1].keys[2][1] = this.capture_duration

	local a = E:create_entity(this.aura_capture)

	a.aura.source_id = this.id
	a.capture_duration = this.capture_duration
	a.enable_waves = this.enable_waves
	a.spawn_delay = this.spawn_delay
	a.enabled_sprite = this.enabled_sprite
	a.disabled_sprite = this.disabled_sprite
	a.capture_default_increment = a.aura.cycle_time
	a.capture_default_decrement = a.capture_default_increment * a.capture_default_decrement_multiplier

	queue_insert(store, a)

	return true
end

scripts.power_control_KR6 = {}

function scripts.power_control_KR6.update(this, store, script)
	coroutine.yield()
	queue_remove(store, this)
end

scripts.power_rain_of_fire = {}

function scripts.power_rain_of_fire.can_select_point(this, x, y, store)
	return GR:cell_is(x, y, bor(TERRAIN_LAND, TERRAIN_ICE)) and P:valid_node_nearby(x, y, nil, NF_RALLY)
end

function scripts.power_rain_of_fire.update(this, store)
	local start_y = store.visible_coords and store.visible_coords.top or REF_H
	local ts
	local burst_interval = 0.33

	local function get_random_position(margin, valid_terrains, node_flags, margin_from_defend)
		if margin and type(margin) == "number" then
			margin = {
				margin,
				margin
			}
		end

		local available_paths = {}

		for i = 1, #P.paths do
			if P:is_path_active(i) then
				table.insert(available_paths, i)
			end
		end

		local pi = available_paths[math.random(1, #available_paths)]
		local spi = math.random(1, 3)
		local valid_nodes = P:get_valid_nodes(pi, node_flags)

		if #valid_nodes < 1 then
			return nil
		end

		local ni, found, tries = nil, false, 0

		while not found and tries < 5 do
			tries = tries + 1
			found = true
			ni = valid_nodes[math.random(1, #valid_nodes)]

			if margin and #margin > 0 then
				if not P:is_node_valid(pi, ni - margin[1], node_flags) then
					found = false
				end

				if P:is_node_valid(pi, ni + margin[2], node_flags) then
					if margin_from_defend and (not P:get_defend_point_node(pi) or ni + margin[2] > P:get_defend_point_node(pi)) then
						found = false
					end
				else
					found = false
				end
			end

			if valid_terrains then
				local npos = P:node_pos(pi, spi, ni)
				local rt = GR:cell_type(npos.x, npos.y)

				if bor(band(rt, valid_terrains), 0) == 0 then
					found = false
				end
			end
		end

		if not found then
			log.debug("could not find random node")

			return nil
		else
			return P:node_pos(pi, spi, ni), pi, spi, ni
		end
	end

	for i = 1, math.max(this.meteor_count, this.cataclysm_count) do
		if i <= this.meteor_count then
			local e = E:create_entity(this.bullet)
			local p, found, tries = nil, nil, 0
			local spread = math.random(this.min_spread, this.max_spread)

			if i == 1 then
				p = V.v(this.pos.x, this.pos.y)
			else
				p = V.v(this.pos.x + math.random(-spread, spread), this.pos.y + math.random(-spread, spread))
			end

			e.pos.x, e.pos.y = p.x, start_y
			e.bullet.from = V.vclone(e.pos)
			e.bullet.to = V.v(p.x, p.y)

			queue_insert(store, e)
		end

		local upg = this.upgrade_cataclysm

		if upg and i <= this.cataclysm_count then
			local dest = get_random_position(10, bor(TERRAIN_LAND))

			if dest then
				local e = E:create_entity(this.bullet)

				e.pos.x = dest.x
				e.pos.y = start_y
				e.bullet.from = V.vclone(e.pos)
				e.bullet.to = V.vclone(dest)
				e.bullet.level = this.user_power.level

				queue_insert(store, e)
			end
		end

		ts = store.tick_ts

		while burst_interval > store.tick_ts - ts do
			coroutine.yield()
		end
	end

	queue_remove(store, this)
end

scripts.bullet_power_rain_of_fire = {}

function scripts.bullet_power_rain_of_fire.update(this, store, script)
	local b = this.bullet
	local mspeed = 10 * FPS
	local particle = E:create_entity(this.particles)

	particle.particle_system.track_id = this.id

	queue_insert(store, particle)

	while V.dist(this.pos.x, this.pos.y, b.to.x, b.to.y) > mspeed * store.tick_length do
		mspeed = mspeed + FPS * math.ceil(mspeed * (1 / FPS) * b.acceleration_factor)
		mspeed = km.clamp(b.min_speed, b.max_speed, mspeed)
		b.speed.x, b.speed.y = V.mul(mspeed, V.normalize(b.to.x - this.pos.x, b.to.y - this.pos.y))
		this.pos.x, this.pos.y = this.pos.x + b.speed.x * store.tick_length, this.pos.y + b.speed.y * store.tick_length
		this.render.sprites[1].r = V.angleTo(b.to.x - this.pos.x, b.to.y - this.pos.y)

		coroutine.yield()
	end

	this.pos.x, this.pos.y = b.to.x, b.to.y
	particle.particle_system.source_lifetime = 0

	local enemies = {}

	for _, v in pairs(store.entities) do
		if v.enemy and v.vis and v.health and not v.health.dead and band(v.vis.flags, b.damage_bans) == 0 and band(v.vis.bans, b.damage_flags) == 0 and U.is_inside_ellipse(v.pos, b.to, b.damage_radius) then
			table.insert(enemies, v)
		elseif v.template_name == "hero_lava" and v.health.hp > 0 and U.is_inside_ellipse(v.pos, b.to, b.damage_radius) then
			v._death_by_ultimate = true
			v.health.hp = 0
		end
	end

	local damage_value = math.ceil(b.damage_factor * math.random(b.damage_min, b.damage_max))

	for _, enemy in ipairs(enemies) do
		local d = E:create_entity("damage")

		d.source_id = this.id
		d.target_id = enemy.id
		d.value = damage_value
		d.damage_type = b.damage_type

		queue_damage(store, d)
	end

	S:queue(this.sound_events.hit)

	local cell_type = GR:cell_type(b.to.x, b.to.y)

	if band(cell_type, TERRAIN_WATER) ~= 0 then
		local fx = E:create_entity("fx_explosion_water")

		fx.pos.x, fx.pos.y = b.to.x, b.to.y
		fx.render.sprites[1].ts = store.tick_ts

		queue_insert(store, fx)

		if this.scorch_earth then
			local scorched = E:create_entity("power_scorched_water")

			scorched.pos.x, scorched.pos.y = b.to.x, b.to.y

			for i = 1, #scorched.render.sprites do
				scorched.render.sprites[i].ts = store.tick_ts
			end

			queue_insert(store, scorched)
		end
	else
		if b.hit_decal then
			local decal = E:create_entity(b.hit_decal)

			decal.pos.x, decal.pos.y = b.to.x, b.to.y
			decal.render.sprites[1].ts = store.tick_ts

			queue_insert(store, decal)
		end

		local upg = this.upgrade_scorching_floor

		if upg then
			local scorched = E:create_entity(this.dmg_aura)

			scorched.pos.x, scorched.pos.y = b.to.x, b.to.y

			queue_insert(store, scorched)
		end

		local upg = this.upgrade_slow_floor

		if upg then
			local slow = E:create_entity(this.slow_aura)

			slow.pos.x, slow.pos.y = b.to.x, b.to.y

			queue_insert(store, slow)
		end

		if b.hit_fx then
			local fx = E:create_entity(b.hit_fx)

			fx.pos.x, fx.pos.y = b.to.x, b.to.y
			fx.render.sprites[1].ts = store.tick_ts

			queue_insert(store, fx)
		end

		local upg = this.upgrade_extra_explosion

		if upg and b.hit_payload then
			local hp

			if type(b.hit_payload) == "string" then
				hp = E:create_entity(b.hit_payload)
			else
				hp = b.hit_payload
			end

			hp.pos.x, hp.pos.y = b.to.x, b.to.y

			queue_insert(store, hp)
		end
	end

	queue_remove(store, this)
end

scripts.decal_rain_of_fire_scorching = {}

function scripts.decal_rain_of_fire_scorching.update(this, store, script)
	U.y_wait(store, this.duration)

	this.tween.ts = store.tick_ts
	this.tween.disabled = false
end

scripts.decal_rain_of_fire_extra_explosion = {}

function scripts.decal_rain_of_fire_extra_explosion.update(this, store, script)
	U.animation_start(this, "hit", nil, store.tick_ts, false)
	U.y_wait(store, this.explosion_delay)

	local enemies = U.find_targets_in_range(store.entities, this.pos, 0, this.aura.radius, this.aura.vis_flags, this.aura.vis_bans)

	if enemies then
		for _, enemy in pairs(enemies) do
			local d = E:create_entity("damage")

			d.damage_type = this.damage_type

			if this.reduce_armor then
				d.reduce_armor = this.reduce_armor
			end

			if not this.ignore_dist_factor then
				local dist_factor = U.dist_factor_inside_ellipse(enemy.pos, this.pos, this.aura.radius)

				d.value = math.floor(this.damage_max - (this.damage_max - this.damage_min) * dist_factor)
			else
				d.value = math.random(this.damage_min, this.damage_max)
			end

			if this.damage_factor then
				d.value = math.ceil(d.value * this.damage_factor)
			end

			d.source_id = this.id
			d.target_id = enemy.id

			queue_damage(store, d)

			if this.aura.mod or this.aura.mods then
				local mods = this.aura.mods or {
					this.aura.mod
				}

				for _, mod_name in pairs(mods) do
					local m = E:create_entity(mod_name)

					m.modifier.target_id = enemy.id
					m.modifier.level = this.aura.level

					queue_insert(store, m)
				end
			end
		end
	end

	U.y_animation_wait(this)
	queue_remove(store, this)
end

scripts.power_royal_edict = {}

local function reset_royal_edict_attack_cooldowns(attacks, tick_ts, first_skill_index)
	for i, a in ipairs(attacks or {}) do
		if i >= (first_skill_index or 1) and not a.basic_attack and not a.static_cooldown and type(a.cooldown) == "number" then
			-- Make the skill ready without leaving an effectively infinite elapsed time
			-- for tower scripts that process missed cooldowns when a block ends.
			a.ts = tick_ts - math.max(a.cooldown, 0) - 1e-06
		end
	end
end

local function reset_royal_edict_tower_cooldowns(target, store)
	if not target.powers then
		return
	end

	local tick_ts = store.tick_ts

	if target.attacks then
		reset_royal_edict_attack_cooldowns(target.attacks.list, tick_ts)
	end

	if target.timed_attacks then
		reset_royal_edict_attack_cooldowns(target.timed_attacks.list, tick_ts)
	end

	if target.barrack then
		local tower_type = target.tower.type
		local mobile_tower = tower_type == "mecha" or tower_type == "balloon" or tower_type == "wicked_sisters"

		for _, soldier in ipairs(target.barrack.soldiers or {}) do
			if soldier.melee then
				reset_royal_edict_attack_cooldowns(soldier.melee.attacks, tick_ts)
			end

			if soldier.timed_attacks then
				reset_royal_edict_attack_cooldowns(soldier.timed_attacks.list, tick_ts)
			end

			if soldier.ranged then
				reset_royal_edict_attack_cooldowns(soldier.ranged.attacks, tick_ts)
			end

			if mobile_tower and soldier.attacks then
				reset_royal_edict_attack_cooldowns(soldier.attacks.list, tick_ts, 2)
			end
		end
	end
end

function scripts.power_royal_edict.can_select_point(this, x, y, store)
	return GR:cell_is(x, y, bor(TERRAIN_LAND, TERRAIN_ICE)) and not GR:cell_is(x, y, bor(TERRAIN_NOWALK)) and P:valid_node_nearby(x, y, nil, NF_RALLY)
end

function scripts.power_royal_edict.insert(this, store)
	local towers = U.find_towers(store.entities, this.pos, 0, this.range, function(v, o)
		return v.tower.can_be_mod and not v.tower.upgrade_to and v.tower.type ~= "holder" and v.tower.type ~= "build_animation" and (not v.tower_holder or not v.tower_holder.blocked)
	end)

	if this.is_global then
		towers = table.filter(store.entities, function(_, e)
			return not e.pending_removal and e.tower and e.tower.can_be_mod and not e.tower.blocked and not e.tower.upgrade_to and e.tower.type ~= "holder" and e.tower.type ~= "build_animation" and (not e.tower_holder or not e.tower_holder.blocked)
		end)
	end

	if towers then
		local reset_skills_cd = this.mods[1] and E:get_template(this.mods[1]).reset_skills_cd

		for _, t in pairs(towers) do
			if reset_skills_cd then
				reset_royal_edict_tower_cooldowns(t, store)
			end

			for i, m in ipairs(this.mods) do
				local nm = E:create_entity(m)

				nm.modifier.target_id = t.id
				nm.modifier.source_id = this.id
				nm.pos.x, nm.pos.y = t.pos.x, t.pos.y - 0.1

				queue_insert(store, nm)
			end
		end
	end

	return true
end

function scripts.power_royal_edict.update(this, store)
	local k = E:create_entity(this.king_decal)

	k.pos.x, k.pos.y = this.pos.x, this.pos.y

	queue_insert(store, k)

	local k = E:create_entity(this.rug_decal)

	k.pos.x, k.pos.y = this.pos.x, this.pos.y

	queue_insert(store, k)

	local kd = E:create_entity(this.area_decal)

	kd.pos.x, kd.pos.y = this.pos.x, this.pos.y
	kd.tween.ts = store.tick_ts
	kd.render.sprites[1].ts = store.tick_ts

	queue_insert(store, kd)

	if this.is_global then
		signal.emit("royal-edict-trumpet-sequence", fts(40), fts(58))
		S:queue(this.sound_cast_upgraded)
	else
		S:queue(this.sound_cast)
	end

	if this.gold_mod then
		local duration = E:get_template(this.mods[1]).modifier.duration
		local ts = store.tick_ts
		local buffed = {}
		local l_entities = SSO and SSO:get_p_list("alive_enemies") or store.entities

		local function apply_gold_mod(e, remaining)
			buffed[e.id] = true

			local gm = E:create_entity(this.gold_mod)

			gm.modifier.target_id = e.id
			gm.modifier.source_id = this.id
			gm.modifier.duration = remaining

			queue_insert(store, gm)
		end

		local check_interval = fts(10)

		while duration > store.tick_ts - ts do
			local remaining = duration - (store.tick_ts - ts)

			if this.is_global then
				for _, e in pairs(l_entities) do
					if not buffed[e.id] and e.enemy and e.health and not e.health.dead then
						apply_gold_mod(e, remaining)
					end
				end
			else
				local enemies = U.find_enemies_in_range(store.entities, this.pos, 0, this.range, 0, 0)

				if enemies then
					for _, e in ipairs(enemies) do
						if not buffed[e.id] then
							apply_gold_mod(e, remaining)
						end
					end
				end
			end

			U.y_wait(store, check_interval)
		end
	end

	queue_remove(store, this)
end

scripts.mod_power_royal_edict_towerbuff = {}

function scripts.mod_power_royal_edict_towerbuff.insert(this, store)
	local m = this.modifier
	local target = store.entities[m.target_id]

	if not target or not target.tower then
		if not target then
			log.error("cannot insert mod_tower_factors, target not found")
		elseif not target.tower then
			log.error("cannot insert mod_tower_factors to entity %s - ", target.id, target.template_name)
		end

		return false
	end

	-- A tower can be blocked after the power selected it but before this
	-- queued modifier is inserted during the same simulation tick.
	if target.pending_removal or target.tower.blocked or target.tower.upgrade_to or target.tower_holder and target.tower_holder.blocked then
		return false
	end

	if this.range_factor then
		if target.attacks then
			target.attacks.range = target.attacks.range * this.range_factor
		end

		if target.barrack then
			target.barrack.rally_range = target.barrack.rally_range * this.range_factor
		end
	end

	if this.damage_factor then
		target.tower.damage_factor = target.tower.damage_factor * this.damage_factor
	end

	if this.respawn_barracks and target.barrack then
		for _, e in pairs(target.barrack.soldiers) do
			if e.health and e.health.hp <= 0 then
				e.health.dead = true

				queue_remove(store, e)
			end
		end
	end

	signal.emit("mod-applied", this, target)

	return true
end

function scripts.mod_power_royal_edict_towerbuff.update(this, store)
	local m = this.modifier
	local ogid = m.target_id

	::label_907_0::

	for i, v in ipairs(this.animations) do
		if v[2] then
			if i == #this.animations then
				U.animation_start(this, v[1], nil, store.tick_ts, true)
			elseif v[3] then
				U.animation_start(this, v[1], nil, store.tick_ts, v[3])
			else
				U.animation_start(this, v[1], nil, store.tick_ts, 1)
			end
		else
			U.y_animation_play(this, v[1], nil, store.tick_ts)
		end
	end

	local m = this.modifier
	local fade_out_time = this.tween.props[1].keys[2][1]

	m.ts = store.tick_ts

	local cycle_ts = store.tick_ts

	while store.tick_ts - m.ts < m.duration - fade_out_time do
		if this.confetti and store.tick_ts - cycle_ts > this.confetti_cycle_time then
			local r = v(U.frandom(-this.confetti_range, this.confetti_range), U.frandom(-this.confetti_range, this.confetti_range))
			local c = E:create_entity(this.confetti)
			local s = this.render.sprites[1]

			c.pos.x, c.pos.y = this.pos.x + s.offset.x + r.x, this.pos.y + s.offset.y + r.y

			queue_insert(store, c)

			cycle_ts = store.tick_ts
		end

		if m.target_id ~= ogid then
			ogid = m.target_id

			local target = store.entities[m.target_id]

			if this.range_factor then
				if target.attacks then
					target.attacks.range = target.attacks.range * this.range_factor
				end

				if target.barrack then
					target.barrack.rally_range = target.barrack.rally_range * this.range_factor
				end
			end

			if this.damage_factor then
				target.tower.damage_factor = target.tower.damage_factor * this.damage_factor
			end
		end

		coroutine.yield()
	end

	this.tween.disabled = false
	this.tween.reverse = true
	this.tween.ts = store.tick_ts

	local fade_ts = store.tick_ts

	while fade_out_time > store.tick_ts - fade_ts do
		if m.resets_same and store.tick_ts - m.ts < m.duration - fade_out_time then
			this.tween.reverse = false
			this.tween.ts = store.tick_ts

			goto label_907_0
		end

		coroutine.yield()
	end

	queue_remove(store, this)
end

function scripts.mod_power_royal_edict_towerbuff.remove(this, store)
	local m = this.modifier
	local target = store.entities[m.target_id]

	if not target or not target.tower then
		log.error("error removing mod_tower_factors %s", this.id)

		return true
	end

	if this.range_factor then
		if target.attacks then
			target.attacks.range = target.attacks.range / this.range_factor
		end

		if target.barrack then
			target.barrack.rally_range = target.barrack.rally_range / this.range_factor
		end
	end

	if this.damage_factor then
		target.tower.damage_factor = target.tower.damage_factor / this.damage_factor
	end

	return true
end

scripts.mod_power_royal_edict_golddebuff = {}

function scripts.mod_power_royal_edict_golddebuff.insert(this, store)
	local target = store.entities[this.modifier.target_id]

	if not target or not target.enemy then
		return false
	end

	return true
end

function scripts.mod_power_royal_edict_golddebuff.update(this, store)
	local ts = store.tick_ts
	local target = store.entities[this.modifier.target_id]

	if not target then
		queue_remove(store, this)

		return
	end

	while store.tick_ts - ts < this.modifier.duration do
		if target.health and target.health.dead then
			ts = store.tick_ts + this.modifier.duration

			signal.emit("got-gold", target.pos, this.extra_gold, "spell_royal_edict")
			queue_remove(store, this)

			return
		end

		coroutine.yield()
	end

	queue_remove(store, this)
end

scripts.power_time_prison = {}

function scripts.power_time_prison.can_select_point(this, x, y, store)
	return GR:cell_is(x, y, bor(TERRAIN_LAND, TERRAIN_ICE)) and P:valid_node_nearby(x, y, nil, NF_RALLY)
end

function scripts.power_time_prison.update(this, store)
	local function spawn_aura(pi, spi, ni)
		local pos = P:node_pos(pi, spi, ni)
		local a = E:create_entity(this.entity)

		a.pos = pos

		queue_insert(store, a)

		local d = E:create_entity(this.decal)

		d.pos = pos
		d.render.sprites[1].ts = store.tick_ts

		queue_insert(store, d)
	end

	local nearest = P:nearest_nodes(this.pos.x, this.pos.y, nil, nil, true)

	if #nearest > 0 then
		local pi, spi, ni = unpack(nearest[1])

		if P:is_node_valid(pi, ni) then
			spawn_aura(pi, 1, ni)
		end
	end

	queue_remove(store, this)
end

scripts.mod_power_time_prison = {}

function scripts.mod_power_time_prison.queue(this, store, insertion)
	local target = store.entities[this.modifier.target_id]

	if not target then
		return
	end

	if insertion then
		log.debug("%s (%s) queue/insertion", this.template_name, this.id)

		if U.flags_pass(target.vis, this.modifier) then
			this._pushed_bans = U.push_bans(target.vis, F_ALL)
			target.health.ignore_damage = true
		end
	else
		log.debug("%s (%s) queue/removal", this.template_name, this.id)

		if this._pushed_bans then
			U.pop_bans(target.vis, this._pushed_bans)

			target.health.ignore_damage = false
		end

		if this._decal_timelapse then
			queue_remove(store, this._decal_timelapse)

			if target.ui then
				target.ui.can_click = true
			end

			if target.health_bar then
				target.health_bar.hidden = nil
			end

			U.sprites_show(target, nil, nil, true)
			SU.show_modifiers(store, target, true, this)
			SU.show_auras(store, target, true)
		end
	end
end

function scripts.mod_power_time_prison.dequeue(this, store, insertion)
	local target = store.entities[this.modifier.target_id]

	if not target then
		return
	end

	if insertion then
		log.debug("%s (%s) dequeue/insertion", this.template_name, this.id)

		if this._pushed_bans then
			U.pop_bans(target.vis, this._pushed_bans)

			target.health.ignore_damage = false
		end
	end
end

function scripts.mod_power_time_prison.insert(this, store)
	local target = store.entities[this.modifier.target_id]

	if target and target.health and not target.health.dead and this._pushed_bans ~= nil then
		SU.stun_inc(target)

		return true
	else
		return false
	end
end

function scripts.mod_power_time_prison.remove(this, store)
	local target = store.entities[this.modifier.target_id]

	if target then
		SU.stun_dec(target)
	end

	return true
end

function scripts.mod_power_time_prison.update(this, store)
	local m = this.modifier
	local target = store.entities[m.target_id]

	if not target or not target.health or target.health.dead then
		queue_remove(store, this)

		return
	end

	m.ts = store.tick_ts
	this.pos.x, this.pos.y = target.pos.x, target.pos.y
	this.render.sprites[1].offset.y = target.unit.hit_offset.y

	local s = this.render.sprites[1]

	if s.size_names then
		s.prefix = s.prefix .. "_" .. s.size_names[target.unit.size]
	end

	s.hidden = true

	local es = E:create_entity(this.decal)

	if not target.render.sprites[1].exo then
		this._decal_timelapse = es
		es.pos.x, es.pos.y = target.pos.x, target.pos.y
		es.render = table.deepclone(target.render)

		local tween_keys = es.tween.props[1].keys

		for i, s in ipairs(es.render.sprites) do
			es.tween.props[i] = E:clone_c("tween_prop")
			es.tween.props[i].keys = tween_keys
			es.tween.props[i].sprite_id = i
		end

		queue_insert(store, es)
		U.y_wait(store, fts(1))
	end

	U.unblock_all(store, target)

	if target.ui then
		target.ui.can_click = false
	end

	if target.health_bar then
		target.health_bar.hidden = true
	end

	U.sprites_hide(target, nil, nil, true)
	SU.hide_modifiers(store, target, true, this)
	SU.hide_auras(store, target, true)

	this.tween.ts = store.tick_ts

	local tween_levitate = this.tween.props[2]

	es.tween.ts = store.tick_ts
	es.tween.disabled = false

	U.y_wait(store, fts(math.random(1, 8)))

	s.hidden = false

	U.animation_start(this, "in", nil, store.tick_ts, false, 1)
	U.y_animation_wait(this)

	tween_levitate.keys[1][2].y = this.render.sprites[1].offset.y
	tween_levitate.keys[2][2].y = this.render.sprites[1].offset.y + tween_levitate.keys[2][2].y
	tween_levitate.keys[3][2].y = this.render.sprites[1].offset.y
	tween_levitate.keys[2][1] = fts(math.random(30, 40))
	tween_levitate.keys[3][1] = tween_levitate.keys[2][1] * 2
	tween_levitate.ts = store.tick_ts
	tween_levitate.disabled = false

	U.animation_start(this, "idle", nil, store.tick_ts, true, 1)
	U.y_wait(store, m.duration - (store.tick_ts - m.ts) - fts(10), function(store, time)
		return this.interrupt
	end)

	tween_levitate.disabled = true

	U.animation_start(this, "out", nil, store.tick_ts, false, 1)

	this.tween.ts = store.tick_ts
	this.tween.reverse = true

	U.y_wait(store, fts(23))

	es.tween.reverse = true
	es.tween.ts = store.tick_ts

	S:queue(this.out_sfx)
	U.y_animation_wait(this)

	if target.ui then
		target.ui.can_click = true
	end

	if target.health_bar then
		target.health_bar.hidden = nil
	end

	U.sprites_show(target, nil, nil, true)
	SU.show_modifiers(store, target, true, this)
	SU.show_auras(store, target, true)
	queue_remove(store, es)

	this._decal_timelapse = nil

	queue_remove(store, this)

	if this.interrupt then
		target.health.hp = 0

		if target.death_spawns then
			target.health.last_damage_types = DAMAGE_NO_SPAWNS
		end
	end

	signal.emit("mod-applied", this, target)
end

