scripts.power_aspect_of_sol_control = {}

function scripts.power_aspect_of_sol_control.can_select_point(this, x, y, store)
	local valid_pos = GR:cell_is(x, y, bor(TERRAIN_LAND, TERRAIN_ICE)) and not GR:cell_is(x, y, bor(TERRAIN_NOWALK)) and P:valid_node_nearby(x, y, nil, NF_RALLY)
	local enemies = filter_t(store.entities, v(x, y), this.summon_target_radius, function(v, o)
		return v.enemy and v.nav_path and not v.health.dead and band(v.vis.flags, this.vis_bans) == 0 and U.is_inside_ellipse(v.pos, V.v(x, y), this.summon_target_radius)
	end)

	if not valid_pos then
		return false
	end

	if #enemies == 0 then
		return true
	end

	local max_hp_enemy = 0
	local id_enemy

	for _, enemy in pairs(enemies) do
		if max_hp_enemy < enemy.health.hp then
			max_hp_enemy = enemy.health.hp
			id_enemy = enemy.id
		end
	end

	this.id_enemy = id_enemy

	return true
end

