scripts.aura_teleportation_sigil = {}

function scripts.aura_teleportation_sigil.update(this, store, script)
	local max_times_applied = E:get_template(this.mod_teleport).max_times_applied
	local count = 0

	this.ts = store.tick_ts

	S:queue(this.sound_in_out)

	local decal

	if this.portal_decal then
		decal = E:create_entity(this.portal_decal)
		decal.pos.x, decal.pos.y = this.pos.x, this.pos.y
		decal.render.sprites[1].ts = store.tick_ts
		decal.duration = this.duration

		queue_insert(store, decal)
	end

	if this.portal_fx then
		this.ps = E:create_entity(this.portal_fx)
		this.ps.pos.x, this.ps.pos.y = this.pos.x, this.pos.y - 20
		this.ps.render.sprites[1].ts = store.tick_ts

		queue_insert(store, this.ps)
	end

	U.animation_start(this.ps, "idle", nil, store.tick_ts, true, 1)

	if this.wait_before_teleport then
		U.y_wait(this, this.wait_before_teleport)
	end

	while true do
		if store.tick_ts - this.ts >= this.duration or count >= this.max_count then
			S:queue(this.sound_in_out)
			U.y_animation_play(this.ps, "out", nil, store.tick_ts, 1, 1)

			decal.duration = 0

			queue_remove(store, this.ps)
			queue_remove(store, this)

			return
		end

		local targets = U.find_enemies_in_range(store.entities, this.pos, 0, this.range, F_TELEPORT, this.vis_bans)

		if not targets or #targets == 0 then
			-- block empty
		else
			for _, v in pairs(targets) do
				if v and not v.health.dead and (not v.enemy.counts or not v.enemy.counts.mod_teleport or max_times_applied > v.enemy.counts.mod_teleport) then
					S:queue(this.sound_teleport)

					local mod_teleport = E:create_entity(this.mod_teleport)

					mod_teleport.modifier.target_id = v.id
					mod_teleport.modifier.source_id = this.id

					queue_insert(store, mod_teleport)
					U.y_wait(store, fts(2))

					count = count + 1
				end
			end
		end

		coroutine.yield()
	end
end

scripts.power_teleportation_sigil_mod = {}

function scripts.power_teleportation_sigil_mod.update(this, store)
	local m = this.modifier
	local should_stun = false
	local instakill = false
	local second_tp = false

	if this.begin_wait then
		U.y_wait(store, this.begin_wait)
	end

	local target = store.entities[m.target_id]

	if not target or not target.health or target.health.dead then
		queue_remove(store, this)

		return
	end

	if this.instakill_chance and target.health and target.health.hp >= this.instakill_min_hp and band(target.vis.flags, bor(F_MINIBOSS, F_BOSS)) == 0 then
		local kill_chance = math.random()

		if kill_chance < this.instakill_chance then
			instakill = true
		end
	end

	if not instakill and this.second_tp_chance then
		local tp_chance = math.random()

		if tp_chance < this.second_tp_chance then
			should_stun = true
			second_tp = true
		end
	end

	if this.max_times_applied then
		if not target.enemy.counts.mod_teleport then
			target.enemy.counts.mod_teleport = 0
		end

		target.enemy.counts.mod_teleport = target.enemy.counts.mod_teleport + 1

		if target.enemy.counts.mod_teleport > this.max_times_applied then
			queue_remove(store, this)

			return
		end
	end

	local fx

	if instakill and not second_tp and this.fx_instakill then
		fx = E:create_entity(this.fx_instakill)

		S:queue(this.instakill_sound)
	elseif second_tp and not instakill and this.fx_second_tp then
		fx = E:create_entity(this.fx_second_tp)
	elseif this.fx_default then
		fx = E:create_entity(this.fx_default)
	end

	if fx ~= nil then
		if m.use_mod_offset and target.unit.mod_offset then
			fx.pos.x, fx.pos.y = target.pos.x + target.unit.mod_offset.x, target.pos.y + target.unit.mod_offset.y
		else
			fx.pos.x, fx.pos.y = target.pos.x, target.pos.y
		end

		fx.render.sprites[1].ts = store.tick_ts

		if bor(target.vis.flags, F_FLYING) ~= 0 then
			fx.render.sprites[1].z = Z_FLYING_HEROES
		end

		queue_insert(store, fx)
	end

	if this.decal_start then
		local decal = E:create_entity(this.decal_start)

		if fx.render.sprites[1].size_names and target.unit then
			fx.render.sprites[1].name = fx.render.sprites[1].size_names[target.unit.size]
		end

		if fx.render.sprites[1].size_scales then
			fx.render.sprites[1].scale = fx.render.sprites[1].size_scales[target.unit.size]
		end

		decal.pos.x, decal.pos.y = target.pos.x, target.pos.y
		decal.render.sprites[1].ts = store.tick_ts

		queue_insert(store, decal)
	end

	if this.delay_start then
		U.y_wait(store, this.delay_start)
	end

	local health_bar_hidden

	U.unblock_all(store, target)

	if target.ui then
		target.ui.can_click = false
	end

	if target.health_bar then
		health_bar_hidden = target.health_bar.hidden
		target.health_bar.hidden = true
	end

	U.sprites_hide(target, nil, nil, true)
	SU.hide_modifiers(store, target, true)
	SU.hide_auras(store, target, true)
	U.y_wait(store, this.hold_time)

	if target.motion then
		target.motion.forced_waypoint = nil
	end

	if this.jump_connection then
		target.nav_path.prev_pis = target.nav_path.prev_pis or {}

		table.insert(target.nav_path.prev_pis, target.nav_path.pi)

		local npi = P:get_next_pi(target.nav_path.pi)

		target.nav_path.pi = npi
		target.nav_path.ni = 1
	else
		local n_off

		if this.nodes_offset_min and this.nodes_offset_max then
			local omin, omax = this.nodes_offset_min, this.nodes_offset_max

			if this.nodes_offset_inc then
				omin = omin + this.nodes_offset_inc * m.level
				omax = omax + this.nodes_offset_inc * m.level
			end

			n_off = math.random(omin, omax)
		else
			n_off = U.flag_has(target.vis.flags, F_BOSS) and this.boss_nodes_offset or this.nodes_offset
		end

		if second_tp and not instakill then
			n_off = n_off * 2
		end

		local n_ni = target.nav_path.ni + n_off
		local n_limit = this.nodeslimit

		if n_ni < 1 and target.nav_path.prev_pis and #target.nav_path.prev_pis > 0 then
			target.nav_path.pi = table.remove(target.nav_path.prev_pis, #target.nav_path.prev_pis)
			target.nav_path.ni = P:get_end_node(target.nav_path.pi)
			n_ni = target.nav_path.ni + n_ni
		end

		if this.dest_valid_node then
			local dpi, dni = P:find_valid_node(target.nav_path.pi, n_ni, this.dest_node_valid_dir or 1, this.dest_node_valid_flags or NF_ALL)

			if dni then
				target.nav_path.ni = dni
			end
		else
			target.nav_path.ni = km.clamp(n_limit, P:get_end_node(target.nav_path.pi) - n_limit, n_ni)
		end
	end

	local npos = P:node_pos(target.nav_path)

	target.pos.x, target.pos.y = npos.x, npos.y

	local fx

	if instakill and not second_tp and this.fx_instakill then
		fx = E:create_entity(this.fx_instakill)
		fx.render.sprites[1].name = "instakill_out"
		fx.render.sprites[1].ts = store.tick_ts

		if m.use_mod_offset and target.unit.mod_offset then
			fx.pos.x, fx.pos.y = target.pos.x + target.unit.mod_offset.x, target.pos.y + target.unit.mod_offset.y
		else
			fx.pos.x, fx.pos.y = target.pos.x, target.pos.y
		end

		if bor(target.vis.flags, F_FLYING) ~= 0 then
			fx.render.sprites[1].z = Z_FLYING_HEROES
		end

		queue_insert(store, fx)
		U.y_wait(store, fts(44))

		local fx_ashes = E:create_entity(this.fx_instakill_ashes)

		fx_ashes.render.sprites[1].ts = store.tick_ts
		fx_ashes.pos = target.pos

		queue_insert(store, fx_ashes)
	elseif second_tp and not instakill and this.fx_second_tp then
		fx = E:create_entity(this.fx_second_tp)
		fx.render.sprites[1].ts = store.tick_ts

		if m.use_mod_offset and target.unit.mod_offset then
			fx.pos.x, fx.pos.y = target.pos.x + target.unit.mod_offset.x, target.pos.y + target.unit.mod_offset.y
		else
			fx.pos.x, fx.pos.y = target.pos.x, target.pos.y
		end

		if bor(target.vis.flags, F_FLYING) ~= 0 then
			fx.render.sprites[1].z = Z_FLYING_HEROES
		end

		queue_insert(store, fx)
	elseif this.fx_default then
		fx = E:create_entity(this.fx_default)
		fx.render.sprites[1].ts = store.tick_ts

		if m.use_mod_offset and target.unit.mod_offset then
			fx.pos.x, fx.pos.y = target.pos.x + target.unit.mod_offset.x, target.pos.y + target.unit.mod_offset.y
		else
			fx.pos.x, fx.pos.y = target.pos.x, target.pos.y
		end

		if bor(target.vis.flags, F_FLYING) ~= 0 then
			fx.render.sprites[1].z = Z_FLYING_HEROES
		end

		queue_insert(store, fx)
	end

	if instakill and not second_tp then
		target.health.ignore_damage = false
		target.unit.show_blood_pool = false

		local d = E:create_entity("damage")

		d.source_id = this.id
		d.target_id = target.id
		d.damage_type = bor(DAMAGE_INSTAKILL, DAMAGE_DISINTEGRATE, DAMAGE_NO_SPAWNS)
		d.value = 1e+99

		queue_damage(store, d)
		signal.emit("mod-applied", this, target)
		queue_remove(store, this)

		return
	end

	if this.decal_end then
		local decal = E:create_entity(this.decal_end)

		if fx.render.sprites[1].size_names and target.unit then
			fx.render.sprites[1].name = fx.render.sprites[1].size_names[target.unit.size]
		end

		if fx.render.sprites[1].size_scales then
			fx.render.sprites[1].scale = fx.render.sprites[1].size_scales[target.unit.size]
		end

		if m.use_mod_offset and target.unit.mod_offset then
			decal.pos.x, decal.pos.y = target.pos.x + target.unit.mod_offset.x, target.pos.y + target.unit.mod_offset.y
		else
			decal.pos.x, decal.pos.y = target.pos.x, target.pos.y
		end

		decal.render.sprites[1].ts = store.tick_ts

		queue_insert(store, decal)
	end

	if this.delay_end then
		U.y_wait(store, this.delay_end)
	end

	if target.ui then
		target.ui.can_click = true
	end

	if target.health_bar then
		target.health_bar.hidden = health_bar_hidden
	end

	U.sprites_show(target, nil, nil, true)
	SU.show_modifiers(store, target, true)
	SU.show_auras(store, target, true)

	local nn, new = P:next_entity_node(target, store.tick_length)

	if nn then
		local vx, vy = V.sub(nn.x, nn.y, target.pos.x, target.pos.y)
		local v_angle = V.angleTo(vx, vy)

		if target.heading then
			target.heading.angle = v_angle
		end
	end

	if this.mod_slow then
		local mod_slow = E:create_entity(this.mod_slow)

		mod_slow.modifier.target_id = target.id
		mod_slow.modifier.source_id = this.id

		queue_insert(store, mod_slow)
	end

	if this.mod_silence and this.mod_damage_red then
		local mod_silence = E:create_entity(this.mod_silence)

		mod_silence.modifier.target_id = target.id
		mod_silence.modifier.source_id = this.id

		queue_insert(store, mod_silence)

		local mod_damage_red = E:create_entity(this.mod_damage_red)

		mod_damage_red.modifier.target_id = target.id
		mod_damage_red.modifier.source_id = this.id

		queue_insert(store, mod_damage_red)
	end

	if should_stun and this.mod_stun then
		local mod_stun = E:create_entity(this.mod_stun)

		mod_stun.modifier.target_id = target.id
		mod_stun.modifier.source_id = this.id

		queue_insert(store, mod_stun)
	end

	signal.emit("mod-applied", this, target)
	queue_remove(store, this)
end

scripts.power_thunder_zapper_control = {}

function scripts.power_thunder_zapper_control.can_select_point(this, x, y, store)
	return GR:cell_is(x, y, bor(TERRAIN_LAND, TERRAIN_ICE)) and not GR:cell_is(x, y, bor(TERRAIN_NOWALK)) and P:valid_node_nearby(x, y, nil, NF_RALLY)
end

function scripts.power_thunder_zapper_control.insert(this, store, script)
	local nearest = P:nearest_nodes(this.pos.x, this.pos.y)[1]
	local pi, spi, ni = unpack(nearest)

	this.pos = P:node_pos(pi, 1, ni)

	local e = E:create_entity(this.tz_template)

	e.pos = v(this.pos.x, this.pos.y)

	queue_insert(store, e)

	local e = E:create_entity(this.ray_decal)

	e.pos = v(this.pos.x, this.pos.y)
	e.render.sprites[1].ts = store.tick_ts
	e.aura = this.summon_aura

	queue_insert(store, e)

	return true
end

scripts.thunder_zapper = {}

function scripts.thunder_zapper.update(this, store, script)
	local ra = not this.timed_attacks.list[1].disabled and this.timed_attacks.list[1] or nil

	if ra then
		ra.ts = store.tick_ts - ra.cooldown
	end

	local la = not this.timed_attacks.list[2].disabled and this.timed_attacks.list[2] or nil

	this.ts = store.tick_ts
	this.render.sprites[1].ts = store.tick_ts

	if this.sound_events and this.sound_events.raise then
		S:queue(this.sound_events.raise)
	end

	this.health_bar.hidden = true
	this.aura = E:create_entity(this.damage_aura)
	this.aura.pos = this.pos

	queue_insert(store, this.aura)

	this.decal_damage_range = E:create_entity(this.decal_damage_range)
	this.decal_damage_range.pos = this.pos
	this.decal_damage_range.render.sprites[1].ts = store.tick_ts

	queue_insert(store, this.decal_damage_range)

	local distance = 0
	local path_ni = 1
	local path_spi = 1
	local path_pi = 1
	local node_pos
	local available_paths = {}

	for k, v in pairs(P.paths) do
		table.insert(available_paths, k)
	end

	if store.level.ignore_walk_backwards_paths then
		available_paths = table.filter(available_paths, function(k, v)
			return not table.contains(store.level.ignore_walk_backwards_paths, v)
		end)
	end

	available_paths = table.filter(available_paths, function(k, v)
		return P:is_path_active(v)
	end)

	local enemies = U.find_enemies_in_range(store.entities, this.pos, 0, this.spawn_detection_range, 0, 0)
	local enemy_paths = find_most_populated_path(enemies)

	if enemy_paths then
		for _, e in ipairs(enemy_paths) do
			if table.contains(available_paths, e[1]) then
				available_paths = {
					e[1]
				}

				break
			end
		end
	end

	local nearest = P:nearest_nodes(this.pos.x, this.pos.y, available_paths)

	if #nearest > 0 then
		for k, v in ipairs(nearest) do
			if GR:find_waypoints(this.pos, nil, P:node_pos(v[1], v[2], v[3]), bor(TERRAIN_LAND, TERRAIN_ICE)) ~= nil then
				path_pi, path_spi, path_ni = unpack(v)

				break
			end
		end
	end

	this.nav_rally.pos = P:node_pos(path_pi, path_spi, path_ni - 3)

	U.y_animation_play(this, "in", this.pos.x > this.nav_rally.pos.x, store.tick_ts, 1, 1)

	while true do
		if this.duration and store.tick_ts - this.ts > this.duration or path_ni <= P:get_start_node(path_pi) then
			S:queue(this.sound_out)
			U.y_animation_play(this, "out", nil, store.tick_ts, 1, 1)
			queue_remove(store, this)

			return
		end

		node_pos = this.nav_rally.pos
		distance = V.dist2(node_pos.x, node_pos.y, this.pos.x, this.pos.y)

		if distance < 25 then
			path_ni = path_ni - 3
			this.nav_rally.pos = P:node_pos(path_pi, path_spi, path_ni)
		end

		if ra and store.tick_ts - ra.ts >= ra.cooldown then
			local enemies = U.find_enemies_in_range(store.entities, this.pos, 0, ra.range, 0, 0)

			if not enemies or #enemies == 0 or #enemies < ra.min_targets then
				SU.delay_attack(store, ra, fts(2))
			else
				table.sort(enemies, function(e1, e2)
					return V.dist(e1.pos.x, e1.pos.y, this.pos.x, this.pos.y) < V.dist(e2.pos.x, e2.pos.y, this.pos.x, this.pos.y)
				end)

				local flip = enemies[1].pos.x < this.pos.x and 1 or -1

				this.unit.hit_offset.x = this.unit.hit_offset.x * flip

				local b = E:create_entity(ra.bullet)

				b.pos.x, b.pos.y = this.pos.x, this.pos.y
				b.bullet.from = V.vclone(b.pos)
				b.bullet.to = V.v(enemies[1].pos.x + enemies[1].unit.hit_offset.x, enemies[1].pos.y + enemies[1].unit.hit_offset.y)
				b.bullet.target_id = enemies[1].id
				b.bullet.source_id = this.id

				queue_insert(store, b)

				ra.ts = store.tick_ts
			end
		end

		if la and store.tick_ts - la.ts >= la.cooldown then
			local e = E:create_entity(la.decal)

			e.pos = V.vclone(this.pos)
			e.aura = la.aura
			e.render.sprites[1].ts = store.tick_ts

			queue_insert(store, e)

			la.ts = store.tick_ts
		end

		if SU.soldier_go_back_step(store, this) then
			-- block empty
		end

		coroutine.yield()
	end
end

function scripts.thunder_zapper.remove(this, store, script)
	if this.aura then
		queue_remove(store, this.aura)
	end

	if this.decal_damage_range then
		this.decal_damage_range.remove = true
	end

	return true
end

scripts.thunder_zapper_lightning = {}

function scripts.thunder_zapper_lightning.update(this, store, script)
	if this.aura then
		local a = E:create_entity(this.aura)

		a.pos = V.vclone(this.pos)

		queue_insert(store, a)
	end

	local e = E:create_entity(this.decal_damage)

	e.pos = V.vclone(this.pos)
	e.render.sprites[1].ts = store.tick_ts

	queue_insert(store, e)
	U.y_animation_wait(this, 1, 1)
	queue_remove(store, this)
end

scripts.thunder_zapper_aura_range = {}

function scripts.thunder_zapper_aura_range.update(this, store, script)
	U.y_animation_play(this, this.anim_in, nil, store.tick_ts, 1, 1)
	U.animation_start(this, this.anim_loop, nil, store.tick_ts, true, 1)

	while not this.remove do
		coroutine.yield()
	end

	U.y_animation_play(this, this.anim_out, nil, store.tick_ts, 1, 1)
	queue_remove(store, this)
end

scripts.power_wintersongs_wrath_control = {}

function scripts.power_wintersongs_wrath_control.insert(this, store, script)
	local nearest = P:nearest_nodes(this.pos.x, this.pos.y)[1]
	local pi, spi, ni = unpack(nearest)
	local pos = P:node_pos(pi, 1, ni)
	local e = E:create_entity(this.decal_elora)

	e.pos.x, e.pos.y = pos.x, pos.y + 30

	queue_insert(store, e)

	return true
end

scripts.wintersongs_wrath = {}

function scripts.wintersongs_wrath.insert(this, store, script)
	this.render.sprites[1].ts = store.tick_ts

	return true
end

function scripts.wintersongs_wrath.update(this, store, script)
	local spikes = {}
	local ts = store.tick_ts

	local function spike_too_close(new_pos)
		for _, spike in ipairs(spikes) do
			local dist = V.dist(new_pos.x, new_pos.y, spike.x, spike.y)

			if dist < 20 then
				return true
			end
		end

		return false
	end

	local function create_spike(entity, pi, spi, ni, random_x, random_y)
		local pos = P:node_pos(pi, spi, ni)
		local final_pos = v(pos.x + U.frandom(-random_x, random_x), pos.y + U.frandom(-random_y, random_y))

		if not spike_too_close(final_pos) and point_in_valid_path(final_pos.x, final_pos.y, {
			pi
		}) then
			local random_scale = U.frandom(0.9, 1)
			local spike = E:create_entity(entity)
			local random_angle = 5 * math.pi / 180
			local angle = U.frandom(-random_angle, random_angle)

			spike.pos = final_pos
			spike.render.sprites[1].ts = store.tick_ts
			spike.render.sprites[1].flip_x = this.pos.x > spike.pos.x
			spike.render.sprites[1].r = angle
			spike.render.sprites[1].scale = v(random_scale, random_scale)

			queue_insert(store, spike)
			table.insert(spikes, #spikes + 1, final_pos)

			local aura = E:create_entity(this.aura_l3)

			aura.pos = P:node_pos(pi, 1, ni)
			aura.aura.cycle_time = fts(12)

			queue_insert(store, aura)
		end
	end

	if this.l6_disabled then
		S:queue(this.sound_cast_base, this.sound_cast_base_args)
	else
		S:queue(this.sound_cast_l6, this.sound_cast_l6_args)
	end

	local a = E:create_entity(this.aura)

	a.aura.source_id = this.id
	a.aura.track_source = true

	queue_insert(store, a)

	local ps_wind, ps_snow

	if not this.l6_disabled then
		this.aura_l6 = E:create_entity(this.aura_l6)
		this.aura_l6.aura.source_id = this.id
		this.aura_l6.aura.track_source = true

		queue_insert(store, this.aura_l6)
		signal.emit("wintersongs-ice-sequence-start")

		ps_wind = E:create_entity(this.ps_wind_l6)
		ps_wind.pos = v(-800, REF_H / 2)

		queue_insert(store, ps_wind)

		ps_snow = E:create_entity(this.ps_snow_l6)
		ps_snow.pos = v(-50, REF_H / 2)

		queue_insert(store, ps_snow)
	end

	local d = E:create_entity(this.decal_tornado[1])

	d.pos.x, d.pos.y = V.add(this.pos.x, this.pos.y, this.decal_tornado[2].x, this.decal_tornado[2].y)
	d.render.sprites[1].ts = store.tick_ts
	d.duration = this.duration

	queue_insert(store, d)

	local d = E:create_entity(this.decal_ice_ground[1])

	d.pos.x, d.pos.y = V.add(this.pos.x, this.pos.y, this.decal_ice_ground[2].x, this.decal_ice_ground[2].y)
	d.render.sprites[1].ts = store.tick_ts
	d.duration = this.duration

	queue_insert(store, d)

	if this.l6_disabled then
		S:queue(this.sound_loop_base, this.sound_loop_base_args)
	else
		S:queue(this.sound_loop_l6, this.sound_loop_l6_args)
	end

	if not this.l3_disabled then
		U.y_wait(store, this.delay_cast)

		local available_paths = {}

		for k, v in pairs(P.paths) do
			table.insert(available_paths, k)
		end

		if store.level.ignore_walk_backwards_paths then
			available_paths = table.filter(available_paths, function(k, v)
				return not table.contains(store.level.ignore_walk_backwards_paths, v)
			end)
		end

		local nearest = P:nearest_nodes(this.pos.x, this.pos.y, available_paths, nil, nil, NF_RALLY)
		local dbn = this.distance_between_spikes
		local spikes_per_subpath = {
			1,
			2,
			2
		}

		for i = 1, this.spike_count do
			for k, v in pairs(nearest) do
				local pi, ni, dist = v[1], v[3], v[4]

				if dist < 100 then
					local spike = this.spikes[i <= 2 and 1 or i <= 4 and 2 or 3]
					local positions = {}
					local path_ni_forward = ni + dbn * i
					local path_ni_backward = ni - dbn * i

					if i % 2 == 0 then
						table.insert(positions, {
							path_spi = 1,
							path_ni = path_ni_forward
						})
						table.insert(positions, {
							path_spi = 1,
							path_ni = path_ni_backward
						})
					else
						table.insert(positions, {
							path_spi = 2,
							path_ni = path_ni_forward
						})
						table.insert(positions, {
							path_spi = 2,
							path_ni = path_ni_backward
						})
						table.insert(positions, {
							path_spi = 3,
							path_ni = path_ni_forward
						})
						table.insert(positions, {
							path_spi = 3,
							path_ni = path_ni_backward
						})
					end

					for _, v in ipairs(positions) do
						create_spike(spike, pi, v.path_spi, v.path_ni, 10, 10)
					end

					S:queue(this.sound_spike_cast)
				end
			end

			U.y_wait(store, this.delay_between_spikes)
		end
	end

	U.y_animation_wait(this)
	U.animation_start(this, this.animation_idle, nil, store.tick_ts, true, 1, true)

	local d = E:create_entity(this.decal_fume[1])

	d.pos.x, d.pos.y = V.add(this.pos.x, this.pos.y, this.decal_fume[2].x, this.decal_fume[2].y)
	d.render.sprites[1].ts = store.tick_ts

	queue_insert(store, d)

	local ui_flag = false

	while true do
		if store.tick_ts - ts > this.duration then
			if this.l6_disabled then
				S:stop(this.sound_loop_base)
				S:queue(this.sound_end_base, this.sound_end_base_args)
			else
				S:stop(this.sound_loop_l6)
				S:queue(this.sound_end_l6, this.sound_end_l6_args)
			end

			U.y_animation_play(this, this.animation_end, nil, store.tick_ts, 1, 1)
			queue_remove(store, this)
		end

		if not this.l6_disabled and store.entities[this.aura_l6.id] == nil and not ui_flag then
			signal.emit("wintersongs-ice-sequence-end")

			if ps_wind ~= nil then
				ps_wind.particle_system.emit = false
			end

			if ps_snow ~= nil then
				ps_snow.particle_system.emit = false
			end

			ui_flag = true
		end

		coroutine.yield()
	end
end

scripts.mod_wintersongs_wrath_global_ice = {}

function scripts.mod_wintersongs_wrath_global_ice.insert(this, store, script)
	local target = store.entities[this.modifier.target_id]

	if not target then
		return false
	end

	if band(target.vis.flags, this.modifier.vis_bans) ~= 0 then
		return false
	end

	this._entity_frame_names = {}

	for _, es in pairs(target.render.sprites) do
		if es.animated then
			table.insert(this._entity_frame_names, es.frame_name)
		else
			table.insert(this._entity_frame_names, es.name)
		end
	end

	SU.stun_inc(target)

	if this.render then
		for _, s in pairs(this.render.sprites) do
			s.ts = store.tick_ts

			if s.size_names then
				s.name = s.size_names[target.unit.size]
			end

			if s.size_prefixes then
				s.prefix = s.size_prefixes[target.unit.size]
			end

			if s.size_scales then
				s.scale = s.size_scales[target.unit.size]
			end
		end
	end

	signal.emit("mod-applied", this, target)

	return true
end

function scripts.mod_wintersongs_wrath_global_ice.update(this, store, script)
	local m = this.modifier

	this.modifier.ts = store.tick_ts

	local target = store.entities[m.target_id]

	if not target or not target.pos then
		queue_remove(store, this)

		return
	end

	this.pos = target.pos

	U.y_animation_play(this, this.animation_start, nil, store.tick_ts, 1, 1)
	U.animation_start(this, this.animation_idle, nil, store.tick_ts, true, 1)

	while true do
		target = store.entities[m.target_id]

		if not target or target.health.dead or m.duration >= 0 and store.tick_ts - m.ts > m.duration or m.last_node and target.nav_path.ni > m.last_node then
			U.y_animation_play(this, this.animation_end, nil, store.tick_ts, 1, 1)
			queue_remove(store, this)

			return
		end

		if this.render and target.unit then
			local s = this.render.sprites[1]
			local flip_sign = 1

			if target.render then
				flip_sign = target.render.sprites[1].flip_x and -1 or 1
			end

			if m.health_bar_offset and target.health_bar then
				local hb = target.health_bar.offset
				local hbo = m.health_bar_offset

				s.offset.x, s.offset.y = hb.x + hbo.x * flip_sign, hb.y + hbo.y
			elseif m.use_mod_offset and target.unit.mod_offset then
				s.offset.x, s.offset.y = target.unit.mod_offset.x * flip_sign, target.unit.mod_offset.y
			elseif m.use_head_offset and target.unit.head_offset then
				s.offset.x, s.offset.y = target.unit.head_offset.x * flip_sign, target.unit.head_offset.y
			end
		end

		coroutine.yield()
	end
end

scripts.decal_wintersongs_wrath_fume = {}

function scripts.decal_wintersongs_wrath_fume.update(this, store, script)
	this.tween.disabled = false
	this.tween.ts = store.tick_ts
	this.tween.run_once = false
	this.tween.remove = false

	for i = 1, #this.tween.props do
		this.tween.props[i].disabled = false
	end

	local ts = store.tick_ts

	while store.tick_ts - ts < this.duration do
		coroutine.yield()
	end

	this.tween.disabled = true

	queue_remove(store, this)
end

scripts.mod_slow_wintersongs_wrath = {}

function scripts.mod_slow_wintersongs_wrath.insert(this, store, script)
	local target = store.entities[this.modifier.target_id]

	if not target or target.health.dead or not target.motion or target.motion.invulnerable then
		return false
	end

	if this.modifier.excluded_templates and table.contains(this.modifier.excluded_templates, target.template_name) then
		log.paranoid("mod_slow.insert not inserted to %s because of excluded_templates", target.id)

		return false
	end

	if band(this.modifier.vis_flags, target.vis.bans) ~= 0 or band(this.modifier.vis_bans, target.vis.flags) ~= 0 then
		log.paranoid("mod %s cannot be applied to entity %s:%s because of vis flags/bans", this.template_name, target.id, target.template_name)

		return false
	end

	log.paranoid("mod_slow.insert (%s)-%s for (%s)-%s", this.id, this.template_name, target.id, target.template_name)

	target.motion.max_speed = target.motion.max_speed * this.slow.factor
	this.modifier.ts = store.tick_ts

	signal.emit("mod-applied", this, target)

	return true
end

scripts.power_musketeers_control = {}

function scripts.power_musketeers_control.insert(this, store, script)
	local x, y = this.pos.x, this.pos.y
	local special_spawn_radius = 30
	local special_angle_offset = 15
	local variants = 3

	for j = 1, 2 do
		local i = math.random(1, variants)
		local e = E:create_entity(this.soldier_t)

		e.pos.x = j == 1 and x + 10 or x - 10
		e.pos.y = j == 1 and y - 10 or y + 10
		e.nav_rally.center = V.v(x, y)
		e.nav_rally.pos = V.vclone(e.pos)
		e.reinforcement.squad_id = this.id

		if j == 1 then
			e.wait_time = fts(5)
		end

		queue_insert(store, e)
	end

	return true
end

scripts.soldier_musketeers = {}

function scripts.soldier_musketeers.get_info(this)
	local min, max
	local bullet = E:get_template(this.bullet_basic)

	min = bullet.bullet.damage_min
	max = bullet.bullet.damage_max

	if this.unit and min then
		min, max = min * this.unit.damage_factor, max * this.unit.damage_factor
	end

	if min and max then
		min, max = math.ceil(min), math.ceil(max)
	end

	return {
		type = STATS_TYPE_SOLDIER,
		hp = this.health.hp,
		hp_max = this.health.hp_max,
		damage_min = min,
		damage_max = max,
		damage_icon = this.info.damage_icon,
		armor = this.health.armor
	}
end

function scripts.soldier_musketeers.update(this, store, script)
	local brk, stam, star

	this.reinforcement.ts = store.tick_ts
	this.render.sprites[1].ts = store.tick_ts

	signal.emit("spawned-reinforcement", this)
	SU.y_reinforcement_fade_in(store, this)

	local l6_shot = false
	local ra = this.ranged.attacks[1]

	if this.l4b_active then
		local bullet = E:get_template(this.bullet_basic)

		bullet.bullet.reduce_armor = this.l4b_reduce_armor
	end

	local function y_do_ranged_attack(store, this, target, attack, pred_pos)
		local attack_done = false
		local start_ts = store.tick_ts
		local bullet
		local bullet_to = pred_pos or target.pos
		local bullet_to_start = V.vclone(bullet_to)
		local casing = E:create_entity(this.casing)
		local random_y = U.frandom(-3, 3)
		local flip = this.render.sprites[1].flip_x and 1 or -1
		local an, af, ai = U.animation_name_facing_point(this, attack.animation, bullet_to)
		local animation_duration = A:duration(this.render.sprites[1].prefix .. "_" .. an) or fts(36)

		U.animation_start(this, an, af, store.tick_ts, false)
		S:queue(attack.sound, attack.sound_args)

		local bt = E:get_template(attack.bullet)

		if bt.bullet.damage_type == DAMAGE_INSTAKILL then
			local mod = E:create_entity(this.instakill_aim)

			mod.render.sprites[1].ts = store.tick_ts
			mod.modifier.target_id = target.id

			queue_insert(store, mod)
		end

		while store.tick_ts - start_ts < attack.shoot_time do
			if this.unit.is_stunned or this.health.dead or this.nav_rally and this.nav_rally.new then
				goto label_953_0
			end

			coroutine.yield()
		end

		if attack.check_target_before_shot and (target.health.dead or not store.entities[target.id]) then
			log.debug("target (%s) is dead or removed from store", target.id)
		elseif attack.max_track_distance and V.dist(target.pos.x, target.pos.y, bullet_to_start.x, bullet_to_start.y) > attack.max_track_distance then
			log.debug("target (%s) at %s,%s  exceeds attack.max_track_distance %s to %s,%s", target.id, target.pos.x, target.pos.y, attack.max_track_distance, bullet_to_start.x, bullet_to_start.y)
		else
			S:queue(attack.sound_shoot)

			bullet = E:create_entity(attack.bullet)
			bullet.pos = V.vclone(this.pos)

			if attack.bullet_start_offset then
				local offset = attack.bullet_start_offset[ai]

				bullet.pos.x, bullet.pos.y = bullet.pos.x + (af and -1 or 1) * offset.x, bullet.pos.y + offset.y
			end

			bullet.bullet.from = V.vclone(bullet.pos)
			bullet.bullet.to = V.vclone(bullet_to)

			if not attack.ignore_hit_offset then
				bullet.bullet.to.x = bullet.bullet.to.x + target.unit.hit_offset.x
				bullet.bullet.to.y = bullet.bullet.to.y + target.unit.hit_offset.y
			end

			if bullet.bullet.damage_type == DAMAGE_INSTAKILL and target.unit.head_offset then
				bullet.bullet.to.x = V.vclone(target.pos).x + target.unit.head_offset.x
				bullet.bullet.to.y = V.vclone(target.pos).y + target.unit.head_offset.y
			end

			bullet.bullet.target_id = target.id
			bullet.bullet.source_id = this.id
			bullet.bullet.xp_dest_id = this.id

			if attack.xp_gain_factor then
				bullet.bullet.xp_gain_factor = attack.xp_gain_factor
			end

			bullet.bullet.level = attack.level

			if bullet.bullet.use_unit_damage_factor then
				bullet.bullet.damage_factor = this.unit.damage_factor
			end

			queue_insert(store, bullet)

			casing.pos = v(V.add(this.pos.x, this.pos.y, this.casing_spawn_pos[ai].x, this.casing_spawn_pos[ai].y))
			casing.pos.y = casing.pos.y + random_y
			casing.y_origin = this.pos.y

			if not this.render.sprites[1].flip_x then
				casing.initial_direction_v.x = casing.initial_direction_v.x * -1
			end

			queue_insert(store, casing)

			attack_done = true

			-- Animation runs are updated by rendering, which may lag behind simulation ticks.
			while store.tick_ts - start_ts < animation_duration do
				if this.unit.is_stunned or this.health.dead or this.nav_rally and this.nav_rally.new then
					break
				end

				coroutine.yield()
			end
		end

		::label_953_0::

		return attack_done
	end

	local function y_ranged_attacks(store, this)
		local target, attack, pred_pos = SU.soldier_pick_ranged_target_and_attack(store, this)

		if not target then
			return false, A_NO_TARGET
		end

		if not attack then
			return false, A_IN_COOLDOWN
		end

		local start_ts = store.tick_ts
		local attack_done

		U.set_destination(this, this.pos)

		if attack.loops then
			attack_done = SU.y_soldier_do_loopable_ranged_attack(store, this, target, attack)
		else
			if this.l6_active and not l6_shot then
				ra.animation = "special_attack"
				ra.bullet = this.bullet_l6
			elseif this.l4a_active and is_disabled(store, target) then
				ra.bullet = this.bullet_l4a
			elseif this.l5b_active and band(target.vis.flags, F_MINIBOSS) == 0 and band(target.vis.flags, F_BOSS) == 0 and band(target.vis.flags, F_INSTAKILL) == 0 and target.health.hp <= target.health.hp_max * this.instakill_threshold and math.random() <= this.instakill_chance then
				ra.bullet = this.bullet_l5b
			else
				ra.bullet = this.bullet_basic
			end

			attack_done = y_do_ranged_attack(store, this, target, attack, pred_pos)
		end

		if attack_done then
			attack.ts = start_ts

			if attack.shared_cooldown then
				for _, aa in pairs(this.ranged.attacks) do
					if aa ~= attack and aa.shared_cooldown then
						aa.ts = attack.ts
					end
				end
			end

			if this.ranged.forced_cooldown then
				this.ranged.forced_ts = start_ts
			end
		end

		if attack_done then
			if this.l6_active and not l6_shot then
				l6_shot = true
				ra.animation = "ranged_attack"
			end

			if ra.bullet == this.bullet_5b then
				-- block empty
			end

			return false, A_DONE
		else
			return true
		end
	end

	if this.wait_time then
		U.y_wait(store, this.wait_time)
	end

	while true do
		if this.health.dead then
			this.reinforcement.fade = false
			this.reinforcement.fade_out = false
			this.ui.can_click = false
			this.tween = nil

			SU.y_soldier_death(store, this)

			return
		end

		if this.reinforcement.duration and store.tick_ts - this.reinforcement.ts > this.reinforcement.duration then
			if this.health.hp > 0 then
				this.reinforcement.hp_before_timeout = this.health.hp
			end

			this.health.hp = 0
			this.ui.can_click = false

			SU.remove_modifiers(store, this)
			SU.y_soldier_death(store, this)

			return
		end

		if this.unit.is_stunned then
			SU.soldier_idle(store, this)
		else
			SU.soldier_courage_upgrade(store, this)

			while this.nav_rally.new do
				if this.nav_rally.move_order then
					U.y_wait(store, this.nav_rally.move_order * math.random() * 0.3)
				end

				if SU.y_hero_new_rally(store, this) then
					goto label_952_1
				end
			end

			if this.melee then
				brk, stam = SU.y_soldier_melee_block_and_attacks(store, this)

				if brk or stam == A_DONE or stam == A_IN_COOLDOWN and not this.melee.continue_in_cooldown then
					goto label_952_1
				end
			end

			if this.ranged then
				brk, star = y_ranged_attacks(store, this)

				if brk or star == A_DONE then
					goto label_952_1
				elseif star == A_IN_COOLDOWN then
					goto label_952_0
				end
			end

			if this.melee.continue_in_cooldown and stam == A_IN_COOLDOWN then
				goto label_952_1
			end

			if SU.soldier_go_back_step(store, this) then
				goto label_952_1
			end

			::label_952_0::

			SU.soldier_idle(store, this)
			SU.soldier_regen(store, this)
		end

		::label_952_1::

		coroutine.yield()
	end
end

scripts.musketeers_l6_bullet = {}

function scripts.musketeers_l6_bullet.update(this, store, script)
	local b = this.bullet
	local s = this.render.sprites[1]
	local target = store.entities[b.target_id]
	local source = store.entities[b.source_id]
	local dest = V.vclone(b.to)
	local tower = this.tower_ref
	local hit_counter = 0
	local mods_added = {}
	local fx

	local function create_fx(hfx)
		local sfx = E:create_entity(hfx)

		sfx.render.sprites[1].ts = store.tick_ts

		local is_air = target and band(target.vis.flags, F_FLYING) ~= 0

		if b.hit_fx_ignore_hit_offset and target and not is_air then
			sfx.pos.x, sfx.pos.y = target.pos.x, target.pos.y
		elseif target then
			local hoffset = target.unit.hit_offset

			sfx.pos.x, sfx.pos.y = target.pos.x + hoffset.x, target.pos.y + hoffset.y
		end

		if sfx.allow_rotation and target and source then
			local vx, vy = V.sub(target.pos.x, target.pos.y, source.pos.x, source.pos.y)
			local r = km.unroll(V.angleTo(vx, vy))

			sfx.render.sprites[1].r = r
		end

		queue_insert(store, sfx)
	end

	local function update_sprite()
		if this.track_target and target and target.motion then
			local tpx, tpy = target.pos.x, target.pos.y

			if not b.ignore_hit_offset then
				tpx, tpy = tpx + target.unit.hit_offset.x, tpy + target.unit.hit_offset.y
			end

			local d = math.max(math.abs(tpx - b.to.x), math.abs(tpy - b.to.y))

			if d > b.max_track_distance then
				log.paranoid("(%s) ray_simple target (%s) out of max_track_distance", this.id, target.id)

				target = nil
			else
				dest.x, dest.y = target.pos.x, target.pos.y

				if target.unit and target.unit.hit_offset then
					dest.x, dest.y = dest.x + target.unit.hit_offset.x, dest.y + target.unit.hit_offset.y
				end
			end
		else
			dest.x, dest.y = b.to.x, b.to.y
		end

		local a_override_x = this.a_override and this.a_override.x or 1
		local a_override_y = this.a_override and this.a_override.y or 0
		local angle = V.angleTo(dest.x - this.pos.x, dest.y - this.pos.y, a_override_x, a_override_y)

		s.r = angle

		local dist_offset = 0

		if this.dist_offset then
			dist_offset = this.dist_offset
		end

		if this.scale_y then
			s.scale.y = (V.dist(dest.x, dest.y, this.pos.x, this.pos.y) + dist_offset) / this.image_width
		else
			s.scale.x = (V.dist(dest.x, dest.y, this.pos.x, this.pos.y) + dist_offset) / this.image_width
		end
	end

	local function hit()
		hit_counter = hit_counter + 1

		if target and b.damage_type ~= DAMAGE_NONE then
			local d = SU.create_bullet_damage(b, target.id, this.id)

			queue_damage(store, d)
		end

		if target and (b.mod or b.mods) then
			local mods = b.mods or {
				b.mod
			}

			for _, mod_name in pairs(mods) do
				local m = E:create_entity(mod_name)

				m.modifier.target_id = b.target_id

				if m.damage_from_bullet then
					if m.dps then
						m.dps.damage_min = b.damage_min * b.damage_factor
						m.dps.damage_max = b.damage_max * b.damage_factor
					else
						m.modifier.damage_min = b.damage_min * b.damage_factor
						m.modifier.damage_max = b.damage_max * b.damage_factor
					end
				else
					local level

					if not tower then
						level = this.bullet.level
					else
						level = tower.level
						level = level or this.bullet.level
					end

					m.modifier.level = level
				end

				table.insert(mods_added, m)
				queue_insert(store, m)
			end
		end

		if b.hit_payload then
			local hp

			if type(b.hit_payload) == "string" then
				hp = E:create_entity(b.hit_payload)
			else
				hp = b.hit_payload
			end

			if hp.aura then
				hp.aura.level = this.bullet.level
				hp.aura.source_id = this.id

				if target then
					hp.pos.x, hp.pos.y = target.pos.x, target.pos.y
				else
					hp.pos.x, hp.pos.y = dest.x, dest.y
				end

				if hp.aura.damage_factor then
					hp.aura.damage_factor = b.damage_factor
				end
			else
				hp.pos.x, hp.pos.y = dest.x, dest.y
			end

			queue_insert(store, hp)
		end

		local disable_hit = false

		if this.hit_fx_only_no_target then
			disable_hit = target ~= nil and not target.health.dead
		end

		local hfx

		if b.hit_fxs and #b.hit_fxs > 0 and not disable_hit then
			for i = 1, #b.hit_fxs do
				create_fx(b.hit_fxs[i])
			end
		elseif b.hit_fx and not disable_hit then
			create_fx(b.hit_fx)
		end

		if b.hit_decal then
			local produce_hit_decal = false

			if this.hit_decal_times == -1 then
				produce_hit_decal = hit_counter == 1
			else
				produce_hit_decal = not this.hit_decal_times or hit_counter % this.hit_decal_times == 0
			end

			if produce_hit_decal then
				local decal = E:create_entity(b.hit_decal)

				if this.hit_decal_offset then
					decal.pos.x = dest.x + math.random(-this.hit_decal_offset.x, this.hit_decal_offset.x)
					decal.pos.y = dest.y + math.random(-this.hit_decal_offset.y, this.hit_decal_offset.y)
				else
					decal.pos.x = dest.x
					decal.pos.y = dest.y
				end

				decal.render.sprites[1].ts = store.tick_ts
				decal.source_id = b.source_id

				queue_insert(store, decal)
			end
		end

		if target and not U.flag_has(target.vis.flags, F_FLYING) then
			local points = generate_blue_noise_cluster(math.random(3, 5), 1, random_point_in_ellipse, dest.x, dest.y, 20, 20)

			for _, p in pairs(points) do
				local d = E:create_entity(this.decals[math.random(1, 2)])

				d.pos = v(p.x, p.y - 10)
				d.render.sprites[1].ts = store.tick_ts
				d.duration = math.random(3, 5)

				queue_insert(store, d)
			end
		end
	end

	if not b.ignore_hit_offset and this.track_target and target and target.motion then
		b.to.x, b.to.y = target.pos.x + target.unit.hit_offset.x, target.pos.y + target.unit.hit_offset.y
	end

	s.scale = s.scale or V.v(1, 1)
	s.ts = store.tick_ts

	update_sprite()

	s.hidden = this.hide_during_trajectory == nil and true or this.hide_during_trajectory

	if b.hit_time > fts(1) then
		local hit_ts = store.tick_ts

		while store.tick_ts - hit_ts < b.hit_time do
			coroutine.yield()

			if target and U.flag_has(target.vis.bans, F_RANGED) then
				target = nil
			end

			if this.track_target then
				update_sprite()
			end
		end
	end

	hit()

	if this.ray_duration then
		local ray_ts = store.tick_ts
		local hit_ts = store.tick_ts

		while store.tick_ts - ray_ts < this.ray_duration do
			if this.track_target then
				update_sprite()
			end

			if tower and not store.entities[tower.id] then
				queue_remove(store, this)

				if fx then
					queue_remove(store, fx)
				end

				for key, value in pairs(mods_added) do
					queue_remove(store, value)
				end

				break
			end

			if this.hit_over_duration then
				update_sprite()

				if store.tick_ts - hit_ts > this.hit_cycle_time then
					hit_ts = store.tick_ts

					hit()
				end
			end

			coroutine.yield()

			s.hidden = false
		end
	else
		while not U.animation_finished(this, 1) do
			if tower and not store.entities[tower.id] then
				queue_remove(store, this)

				break
			end

			coroutine.yield()
		end
	end

	if this.end_animation then
		U.y_animation_play(this, this.end_animation, s.flip_x, store.tick_ts, 1, 1)
	end

	queue_remove(store, this)
end

scripts.tower_holder_animated = {}

function scripts.tower_holder_animated.remove(this, store, script)
	local fx = E:create_entity(this.tower_holder.unblock_fx)

	fx.pos = V.vclone(this.pos)
	fx.render.sprites[1].ts = store.tick_ts

	queue_insert(store, fx)

	return true
end

scripts.tunnel_KR6 = {}

function scripts.tunnel_KR6.insert(this, store, script)
	local tu = this.tunnel

	if not tu.pick_ni then
		tu.pick_ni = P:get_end_node(tu.pick_pi) - 1
	end

	if not tu.place_ni then
		tu.place_ni = 1
	end

	local pick_end = P:get_end_node(tu.pick_pi)
	local place_start = P:get_start_node(tu.place_pi)
	local pick_start = pick_end - this.untargetable_distance
	local place_end = place_start + this.untargetable_distance

	P:add_invalid_range(tu.pick_pi, pick_start, pick_end)
	P:add_invalid_range(tu.place_pi, place_start, place_end)

	return scripts.aura_apply_mod.insert(this, store, script)
end

function scripts.tunnel_KR6.update(this, store, script)
	local tu = this.tunnel

	if not tu.pick_ni then
		tu.pick_ni = P:get_end_node(tu.pick_pi) - 1
	end

	if not tu.place_ni then
		tu.place_ni = 1
	end

	local pf = P:node_pos(tu.pick_pi, 1, tu.pick_ni)
	local pt = P:node_pos(tu.place_pi, 1, tu.place_ni)
	local length = V.dist(pf.x, pf.y, pt.x, pt.y)
	local picked_enemies = tu.picked_enemies

	tu.length = length
	this.total_picked_enemies = 0

	local l_entities = SSO and SSO:get_p_list("alive_enemies") or store.entities

	while true do
		local enemies = table.filter(l_entities, function(_, e)
			return e and e.enemy and e.health and not e.health.dead and e.main_script and e.main_script.co ~= nil and e.nav_path and e.nav_path.pi == tu.pick_pi and e.nav_path.ni >= tu.pick_ni and (tu.pick_pi ~= tu.place_pi or e.nav_path.ni < tu.place_ni)
		end)

		for _, enemy in pairs(enemies) do
			if tu.pick_fx then
				local fx = E:create_entity(tu.pick_fx)

				fx.pos = V.v(enemy.pos.x, enemy.pos.y)

				if tu.fx_use_unit_offset then
					fx.pos.x, fx.pos.y = fx.pos.x + enemy.unit.mod_offset.x, fx.pos.y + enemy.unit.mod_offset.y
				end

				fx.render.sprites[1].ts = store.tick_ts

				queue_insert(store, fx)
			end

			if tu.pick_sound then
				S:queue(tu.pick_sound)
			end

			local release_ts = store.tick_ts + length / (tu.speed_factor * enemy.motion.max_speed)

			log.debug("tunnel %s picked %s", this.id, enemy.id)

			if this.transformer and this.transformer[enemy.template_name] then
				table.insert(picked_enemies, {
					release_ts = release_ts,
					entity = enemy,
					transform_to = this.transformer[enemy.template_name]
				})
			else
				table.insert(picked_enemies, {
					release_ts = release_ts,
					entity = enemy
				})
			end

			SU.remove_modifiers(store, enemy)
			SU.remove_auras(store, enemy)
			queue_remove(store, enemy)
			U.unblock_all(store, enemy)

			if enemy.ui then
				enemy.ui.can_click = false
			end

			enemy.main_script.co = nil
			enemy.main_script.runs = 0

			if enemy.count_group then
				enemy.count_group.in_limbo = true
			end

			this.total_picked_enemies = this.total_picked_enemies + 1
		end

		for i = #picked_enemies, 1, -1 do
			local p = picked_enemies[i]

			if p.release_ts > store.tick_ts then
				-- block empty
			else
				local enemy

				if not p.transform_to then
					enemy = p.entity
				else
					enemy = E:create_entity(p.transform_to)
				end

				enemy.nav_path.pi = tu.place_pi
				enemy.nav_path.ni = tu.place_ni
				enemy.pos = P:node_pos(enemy.nav_path)
				enemy.main_script.runs = 1
				enemy._placed_from_tunnel = true

				if enemy.ui then
					enemy.ui.can_click = true
				end

				if store.kill_tunnel_releases then
					enemy.health.hp = 0

					if enemy.death_spawns then
						enemy.health.last_damage_types = DAMAGE_NO_SPAWNS
					end

					if enemy.enemy then
						enemy.enemy.gold = 0
					end
				end

				queue_insert(store, enemy)

				if p.transform_to and not U.is_seen(store, p.transform_to) then
					signal.emit("wave-notification", "icon", p.transform_to)
					U.mark_seen(store, p.transform_to)
				end

				table.remove(picked_enemies, i)

				if tu.place_fx then
					local fx = E:create_entity(tu.place_fx)

					fx.pos = V.v(enemy.pos.x, enemy.pos.y)

					if enemy.vis and band(enemy.vis.flags, F_FLYING) ~= 0 and enemy.unit and enemy.unit.hit_offset then
						fx.render.sprites[1].offset = V.v(enemy.unit.hit_offset.x, enemy.unit.hit_offset.y)
					end

					fx.render.sprites[1].ts = store.tick_ts

					queue_insert(store, fx)
				end

				log.debug("tunnel %s placed %s", this.id, enemy.id)
			end
		end

		coroutine.yield()
	end
end

scripts.tunnel_KR6_destructible = {}

function scripts.tunnel_KR6_destructible.update(this, store, script)
	local tu = this.tunnel

	if not tu.pick_ni then
		tu.pick_ni = P:get_end_node(tu.pick_pi) - 1
	end

	if not tu.place_ni then
		tu.place_ni = 1
	end

	local pf = P:node_pos(tu.pick_pi, 1, tu.pick_ni)
	local pt = P:node_pos(tu.place_pi, 1, tu.place_ni)
	local length = V.dist(pf.x, pf.y, pt.x, pt.y)
	local picked_enemies = tu.picked_enemies

	tu.length = length
	this.total_picked_enemies = 0

	local l_entities = SSO and SSO:get_p_list("alive_enemies") or store.entities

	while true do
		if not this.destroyed then
			local enemies = table.filter(l_entities, function(_, e)
				return e and e.enemy and e.health and not e.health.dead and e.main_script and e.main_script.co ~= nil and e.nav_path and e.nav_path.pi == tu.pick_pi and e.nav_path.ni >= tu.pick_ni and (tu.pick_pi ~= tu.place_pi or e.nav_path.ni < tu.place_ni)
			end)

			for _, enemy in pairs(enemies) do
				if tu.pick_fx then
					local fx = E:create_entity(tu.pick_fx)

					fx.pos = V.v(enemy.pos.x, enemy.pos.y)
					fx.render.sprites[1].ts = store.tick_ts

					queue_insert(store, fx)
				end

				local picked_ts = store.tick_ts
				local release_ts = store.tick_ts + length / (tu.speed_factor * enemy.motion.max_speed)

				log.debug("tunnel %s picked %s", this.id, enemy.id)
				table.insert(picked_enemies, {
					picked_ts = picked_ts,
					release_ts = release_ts,
					entity = enemy
				})
				SU.remove_modifiers(store, enemy)
				SU.remove_auras(store, enemy)
				queue_remove(store, enemy)
				U.unblock_all(store, enemy)

				if enemy.ui then
					enemy.ui.can_click = false
				end

				enemy.main_script.co = nil
				enemy.main_script.runs = 0

				if enemy.count_group then
					enemy.count_group.in_limbo = true
				end

				this.total_picked_enemies = this.total_picked_enemies + 1
			end
		end

		for i = #picked_enemies, 1, -1 do
			local p = picked_enemies[i]

			if p.release_ts > store.tick_ts and not this.destroyed then
				-- block empty
			else
				local enemy = p.entity

				enemy.nav_path.pi = tu.place_pi

				if this.destroyed and tu.pick_pi == tu.place_pi then
					local duration = p.release_ts - p.picked_ts
					local elapsed = store.tick_ts - p.picked_ts
					local percentage_done = math.min(elapsed / duration, 1)
					local desired_ni = tu.pick_ni + math.floor((tu.place_ni - tu.pick_ni) * percentage_done)

					enemy.nav_path.ni = desired_ni
				else
					enemy.nav_path.ni = tu.place_ni
				end

				enemy.pos = P:node_pos(enemy.nav_path)
				enemy.main_script.runs = 1
				enemy._placed_from_tunnel = true

				if enemy.ui then
					enemy.ui.can_click = true
				end

				queue_insert(store, enemy)
				table.remove(picked_enemies, i)

				if tu.place_fx then
					local fx = E:create_entity(tu.place_fx)

					fx.pos = V.v(enemy.pos.x, enemy.pos.y)
					fx.render.sprites[1].ts = store.tick_ts

					queue_insert(store, fx)
				end

				log.debug("tunnel %s placed %s", this.id, enemy.id)
			end
		end

		if this.destroyed then
			break
		end

		coroutine.yield()
	end

	queue_remove(store, this)
end

scripts.aura_shake_entity = {}

function scripts.aura_shake_entity.update(this, store, script)
	local target = store.entities[this.aura.target_id]
	local phase = math.random(0, 2 * math.pi)
	local shake_ts = store.tick_ts
	local move_ts = 0
	local amp = this.aura.amplitude

	while store.tick_ts - shake_ts < this.aura.duration do
		local t = store.tick_ts - shake_ts
		local wox, woy = U.screen_shake_step(t, amp, this.aura.freq_factor, phase, this.aura.duration)

		for i, sp in ipairs(this.aura.sprites_to_shake) do
			target.render.sprites[sp].offset.x, target.render.sprites[sp].offset.y = wox, woy
		end

		coroutine.yield()
	end

	queue_remove(store, this)
end

scripts.bomb_KR6 = {}

function scripts.bomb_KR6.insert(this, store, script)
	local b = this.bullet

	b.speed = SU.initial_parabola_speed(b.from, b.to, b.flight_time, b.g)
	b.ts = store.tick_ts
	b.last_pos = V.vclone(b.from)

	if b.rotation_speed then
		if b.starting_rotation then
			this.render.sprites[1].r = b.starting_rotation
		else
			this.render.sprites[1].r = (math.random() - 0.5) * math.pi
		end

		b.rotation_speed = b.rotation_speed * (b.to.x > b.from.x and -1 or 1)
	end

	if b.hide_radius then
		this.render.sprites[1].hidden = true
	end

	if this.tween then
		for i = 1, #this.tween.props do
			this.tween.props[i].ts = store.tick_ts
		end
	end

	return true
end

function scripts.bomb_KR6.update(this, store, script)
	local b = this.bullet
	local dmin, dmax = b.damage_min, b.damage_max
	local dradius = b.damage_radius

	if b.level and b.level > 0 then
		if b.damage_radius_inc then
			dradius = dradius + b.level * b.damage_radius_inc
		end

		if b.damage_min_inc then
			dmin = dmin + b.level * b.damage_min_inc
		end

		if b.damage_max_inc then
			dmax = dmax + b.level * b.damage_max_inc
		end
	end

	if b.damages_min and b.damages_max and b.level then
		dmin = b.damages_min[b.level]
		dmax = b.damages_max[b.level]
	end

	local ps

	if b.particles_name then
		ps = E:create_entity(b.particles_name)
		ps.particle_system.track_id = this.id

		queue_insert(store, ps)
	end

	local shadow, shadow_start_pos

	if this.decal_shadow then
		shadow = E:create_entity(this.decal_shadow)
		shadow.pos = V.vclone(b.from)
		shadow.pos.y = b.from.y - 70

		queue_insert(store, shadow)

		shadow_start_pos = V.vclone(shadow.pos)
	end

	while store.tick_ts - b.ts + store.tick_length < b.flight_time do
		coroutine.yield()

		b.last_pos.x, b.last_pos.y = this.pos.x, this.pos.y
		this.pos.x, this.pos.y = SU.position_in_parabola(store.tick_ts - b.ts, b.from, b.speed, b.g)

		if b.align_with_trajectory then
			this.render.sprites[1].r = V.angleTo(this.pos.x - b.last_pos.x, this.pos.y - b.last_pos.y)
		elseif b.rotation_speed then
			this.render.sprites[1].r = this.render.sprites[1].r + b.rotation_speed * store.tick_length
		end

		if b.hide_radius then
			this.render.sprites[1].hidden = V.dist(this.pos.x, this.pos.y, b.from.x, b.from.y) < b.hide_radius or V.dist(this.pos.x, this.pos.y, b.to.x, b.to.y) < b.hide_radius
		end

		if b.anim_rising or b.anim_falling then
			if this.pos.y - b.last_pos.y >= 0 then
				if b.anim_rising and this.render.sprites[1].name ~= b.anim_rising then
					U.animation_start(this, b.anim_rising, nil, store.tick_ts, b.anim_rising_loops, 1)
				end
			elseif b.anim_falling and this.render.sprites[1].name ~= b.anim_falling then
				U.animation_start(this, b.anim_falling, nil, store.tick_ts, b.anim_falling_loops, 1)
			end
		end

		if b.switch_z_time and this.render.sprites[1].z ~= Z_BULLETS and store.tick_ts - b.ts > b.switch_z_time then
			this.render.sprites[1].z = Z_BULLETS
		end

		if shadow then
			shadow.pos.x = shadow_start_pos.x + (b.to.x - shadow_start_pos.x) * ((store.tick_ts - b.ts) / b.flight_time)
			shadow.pos.y = shadow_start_pos.y + (b.to.y - shadow_start_pos.y) * ((store.tick_ts - b.ts) / b.flight_time)

			local height = this.pos.y - shadow.pos.y
			local s = km.clamp(0.6, 1, 40 / height)

			shadow.render.sprites[1].scale = V.vv(s)
		end
	end

	local enemies = U.find_enemies_in_range(store.entities, b.to, 0, dradius, b.damage_flags, b.damage_bans)

	if enemies and dmax and dmax > 0 then
		local upg = UP:get_upgrade("engineer_efficiency")
		local source = store.entities[b.source_id]
		local upg_valid = upg and source and source.tower
		local ignore_dist_factor = upg_valid or this.bullet.chance_ignore_dist_factor and math.random() <= this.bullet.chance_ignore_dist_factor

		for _, enemy in pairs(enemies) do
			local d = E:create_entity("damage")

			d.damage_type = b.damage_type
			d.reduce_armor = b.reduce_armor
			d.reduce_magic_armor = b.reduce_magic_armor

			if b.damage_decay_random then
				d.value = U.frandom(dmin, dmax)
			elseif ignore_dist_factor then
				d.value = dmax
			else
				local dist_factor = U.dist_factor_inside_ellipse(enemy.pos, b.to, dradius)

				d.value = math.floor(dmax - (dmax - dmin) * dist_factor)
			end

			if (d.damage_type == DAMAGE_EXPLOSION or d.damage_type == DAMAGE_ELECTRICAL) and this.bullet.explosive_factor then
				d.explosive_factor = this.bullet.explosive_factor
			end

			d.value = math.ceil(b.damage_factor * d.value)
			d.source_id = this.id
			d.target_id = enemy.id

			if b.xp_gain_factor and b.xp_dest_id then
				d.xp_gain_factor = b.xp_gain_factor
				d.xp_dest_id = b.source_id
			end

			queue_damage(store, d)
			log.paranoid("bomb id:%s, radius:%s, enemy id:%s, dist:%s, damage:%s damage_type:%x", this.id, dradius, enemy.id, V.dist(enemy.pos.x, enemy.pos.y, b.to.x, b.to.y), d.value, d.damage_type)

			if b.mod or b.mods then
				local mods = b.mods or {
					b.mod
				}

				if b.mod and b.mods then
					mods = table.merge(b.mods, {
						b.mod
					})
				end

				for _, mod_name in pairs(mods) do
					local m = E:create_entity(mod_name)

					m.modifier.target_id = enemy.id
					m.modifier.source_id = b.source_id
					m.modifier.level = b.level or 1

					queue_insert(store, m)
				end
			end
		end
	end

	local p = SU.create_bullet_pop(store, this)

	queue_insert(store, p)

	local cell_type = GR:cell_type(b.to.x, b.to.y)

	if b.hit_fx_water and band(cell_type, TERRAIN_WATER) ~= 0 then
		S:queue(this.sound_events.hit_water)

		local water_fx = E:create_entity(b.hit_fx_water)

		water_fx.pos.x, water_fx.pos.y = b.to.x, b.to.y
		water_fx.render.sprites[1].ts = store.tick_ts
		water_fx.render.sprites[1].sort_y_offset = b.hit_fx_sort_y_offset

		queue_insert(store, water_fx)
	elseif b.hit_fx then
		S:queue(this.sound_events.hit)

		local sfx = E:create_entity(b.hit_fx)

		sfx.pos = V.vclone(b.to)

		for i = 1, #sfx.render.sprites do
			sfx.render.sprites[i].ts = store.tick_ts
			sfx.render.sprites[i].sort_y_offset = b.hit_fx_sort_y_offset
		end

		queue_insert(store, sfx)
	end

	if b.hit_decal and band(cell_type, TERRAIN_WATER) == 0 then
		local decal = E:create_entity(b.hit_decal)

		decal.pos = V.vclone(b.to)

		for i = 1, #decal.render.sprites do
			decal.render.sprites[i].ts = store.tick_ts
		end

		queue_insert(store, decal)
	end

	if b.hit_payload then
		local hp

		if type(b.hit_payload) == "string" then
			hp = E:create_entity(b.hit_payload)
		else
			hp = b.hit_payload
		end

		hp.pos.x, hp.pos.y = b.to.x, b.to.y
		hp.source_id = b.source_id

		if hp.aura then
			hp.aura.level = this.bullet.level
		end

		queue_insert(store, hp)
	end

	if this.screenshake_amplitude then
		local shake = E:create_entity("aura_screen_shake")

		shake.aura.amplitude = this.screenshake_amplitude
		shake.aura.duration = this.screenshake_duration
		shake.aura.freq_factor = this.screenshake_freq_factor

		queue_insert(store, shake)
	end

	if shadow then
		queue_remove(store, shadow)
	end

	queue_remove(store, this)
end

scripts.controller_path_direction = {}

function scripts.controller_path_direction.update(this, store)
	local markers_pool = {}

	local function add_markers_to_pool()
		for i = 1, this.pool_batch_size do
			local path_marker = E:create_entity(this.path_marker_entity)

			path_marker.render.sprites[1].hidden = true

			table.insert(markers_pool, path_marker)
			queue_insert(store, path_marker)
		end
	end

	local function clear_markers()
		for _, m in ipairs(markers_pool) do
			m.render.sprites[1].hidden = true
		end
	end

	while true do
		if this.selected_entity then
			clear_markers()

			local dist = V.dist(this.start_pos.x, this.start_pos.y, this.end_pos.x, this.end_pos.y)

			if dist < this.distance_between then
				-- block empty
			else
				this.start_pos = this.selected_entity.pos

				local start_pos = V.vclone(this.start_pos)

				if this.selected_entity.reinforcement and this.selected_entity.reinforcement.squad_id then
					local middle = V.v(0, 0)
					local c = 0

					for _, e in pairs(store.entities) do
						if e.nav_rally and e.reinforcement and e.reinforcement.squad_id == this.selected_entity.reinforcement.squad_id then
							middle.x = middle.x + e.pos.x
							middle.y = middle.y + e.pos.y
							c = c + 1
						end
					end

					start_pos.x, start_pos.y = middle.x / c, middle.y / c
				elseif this.selected_entity.soldier and this.selected_entity.soldier.tower_id then
					local middle = V.v(0, 0)
					local c = 0

					for _, e in pairs(store.entities) do
						if e.soldier and e.soldier.tower_id == this.selected_entity.soldier.tower_id and e.health and not e.health.dead then
							middle.x = middle.x + e.pos.x
							middle.y = middle.y + e.pos.y
							c = c + 1
						end
					end

					start_pos.x, start_pos.y = middle.x / c, middle.y / c
				elseif this.selected_entity.health and this.selected_entity.health.dead then
					this.selected_entity = nil

					goto label_968_0
				end

				if this.selected_entity.drag_line_origin_offset then
					local o = this.selected_entity.drag_line_origin_offset

					start_pos.x, start_pos.y = start_pos.x + o.x, start_pos.y + o.y
				end

				dist = V.dist(start_pos.x, start_pos.y, this.end_pos.x, this.end_pos.y)

				local markers_amount = math.floor(dist / this.distance_between)

				while markers_amount > #markers_pool do
					add_markers_to_pool()
				end

				for i = 1, markers_amount do
					local pos = V.v(this.end_pos.x - start_pos.x, this.end_pos.y - start_pos.y)

					pos.x, pos.y = V.normalize(pos.x, pos.y)

					local marker_pos = V.v(start_pos.x + pos.x * (i * this.distance_between), start_pos.y + pos.y * (i * this.distance_between))

					markers_pool[i].pos = V.vclone(marker_pos)
					markers_pool[i].render.sprites[1].hidden = false
					markers_pool[i].render.sprites[1].r = V.angleTo(marker_pos.x - start_pos.x, marker_pos.y - start_pos.y)
				end
			end
		else
			clear_markers()
		end

		::label_968_0::

		coroutine.yield()
	end
end

scripts.power_reinforcements_control = {}

function scripts.power_reinforcements_control.can_select_point(this, x, y, store)
	return GR:cell_is(x, y, bor(TERRAIN_LAND, TERRAIN_ICE)) and not GR:cell_is(x, y, bor(TERRAIN_NOWALK)) and P:valid_node_nearby(x, y, nil, NF_RALLY)
end

function scripts.power_reinforcements_control.insert(this, store, script)
	local function set_name_if_female(variant, e)
		if e.level == 1 and variant == 1 or (e.level == 2 or e.level == 3) and variant == 2 then
			e.info.random_name_format = "SOLDIER_REINFORCEMENTS_F_%i_NAME"
			e.info.random_name_count = 4
		end
	end

	local x, y = this.pos.x, this.pos.y
	local spawned_special = false
	local special_spawn_radius = 30
	local special_angle_offset = 15
	local upg = this.upgrade_special_unit

	if upg then
		local e = E:create_entity("soldier_reinforcement_special")
		local spawn_pos = U.point_on_ellipse(V.v(x, y), special_spawn_radius, -math.pi / 2 + special_angle_offset)

		e.pos = V.vclone(spawn_pos)
		e.nav_rally.center = V.v(x, y)
		e.nav_rally.pos = V.vclone(e.pos)
		e.reinforcement.squad_id = this.id

		queue_insert(store, e)

		spawned_special = true
	end

	local variants = 3

	for j = 1, 2 do
		local i = math.random(1, variants)
		local e = E:create_entity("re_current")

		e.render.sprites[1].prefix = e.render.sprites[1].prefix .. i

		if spawned_special then
			local a = 2 * math.pi / 3
			local spawn_pos = U.point_on_ellipse(V.v(x, y), special_spawn_radius, (j == 1 and 1 or 2) * a - math.pi / 2 + special_angle_offset)

			e.pos = V.vclone(spawn_pos)
		else
			e.pos.x = j == 1 and x + 10 or x - 10
			e.pos.y = j == 1 and y - 10 or y + 10
		end

		-- e.info.portrait = string.format("gui_bottom_info_image_soldiers_%04i", (e.level - 1) * #e.portrait_idxs + e.portrait_idxs[i])

		set_name_if_female(i, e)

		e.nav_rally.center = V.v(x, y)
		e.nav_rally.pos = V.vclone(e.pos)
		e.reinforcement.squad_id = this.id

		queue_insert(store, e)
	end

	return true
end

function scripts.power_reinforcements_control.update(this, store, script)
	coroutine.yield()
