scripts.aura_stage_03_jenkins_enraged = {}

function scripts.aura_stage_03_jenkins_enraged.update(this, store, script)
	local first_hit_ts
	local last_hit_ts = 0
	local path_ni = this.node_id
	local path_spi = 1
	local distSq = 0

	last_hit_ts = store.tick_ts - this.aura.cycle_time

	if this.aura.apply_delay then
		last_hit_ts = last_hit_ts + this.aura.apply_delay
	end

	local function hit_enemies()
		local targets = U.find_enemies_in_range(store.entities, this.pos, 0, this.aura.radius, this.aura.vis_flags, this.aura.vis_bans, function(v, o)
			return (not this.aura.allowed_templates or table.contains(this.aura.allowed_templates, v.template_name)) and (not this.aura.excluded_templates or not table.contains(this.aura.excluded_templates, v.template_name)) and (not this.aura.filter_source or this.aura.source_id ~= v.id) and not U.has_modifiers(store, v, this.aura.mod)
		end)

		if targets then
			for i, target in pairs(targets) do
				if target and not target.health.dead and target.enemy then
					queue_damage(store, SU.create_attack_damage(this, target.id, this.id))

					local hit_fx = E:create_entity(this.hit_fx)

					hit_fx.pos = V.vclone(target.pos)
					hit_fx.pos.x, hit_fx.pos.y = hit_fx.pos.x + target.unit.hit_offset.x, hit_fx.pos.y + target.unit.hit_offset.y
					hit_fx.render.sprites[1].ts = store.tick_ts

					queue_insert(store, hit_fx)

					local new_mod = E:create_entity(this.aura.mod)

					new_mod.modifier.target_id = target.id
					new_mod.modifier.source_id = this.id

					queue_insert(store, new_mod)
				end
			end

			if #targets > 0 then
				S:queue(this.sound_hit)
			end
		end
	end

	local target_pos = P:node_pos(this.path_id, path_spi, path_ni)

	local function go_back_step()
		if V.veq(this.pos, target_pos) then
			this.motion.arrived = true

			return false
		else
			U.set_destination(this, target_pos)

			if U.walk(this, store.tick_length) then
				return false
			else
				U.animation_start(this, "run", nil, store.tick_ts, true)

				return true
			end
		end
	end

	local function run_backwards()
		local last_pos = this.pos

		distSq = V.dist2(target_pos.x, target_pos.y, this.pos.x, this.pos.y)

		if distSq < 25 then
			path_ni = path_ni - 3
			target_pos = P:node_pos(this.path_id, path_spi, path_ni)
		end

		go_back_step()
	end

	while true do
		if this.interrupt then
			last_hit_ts = 1e+99
		end

		if path_ni <= 3 then
			break
		end

		if store.tick_ts - last_hit_ts >= this.aura.cycle_time then
			if this.aura.apply_duration and first_hit_ts and store.tick_ts - first_hit_ts > this.aura.apply_duration then
				goto label_1022_0
			end

			first_hit_ts = first_hit_ts or store.tick_ts
			last_hit_ts = store.tick_ts

			hit_enemies()
		end

		run_backwards()

		::label_1022_0::

		coroutine.yield()
	end

	queue_remove(store, this)
end

scripts.tower_stage_04_crane = {}

function scripts.tower_stage_04_crane.can_select_point(this, x, y)
	return P:valid_node_nearby(x, y)
end

function scripts.tower_stage_04_crane.update(this, store)
	local ab = this.attacks.list[1]
	local times_repaired = 0
	local bubble_ts = store.tick_ts
	local tap_bubble_cd = 5
	local explosion_c

	for _, v in pairs(store.entities) do
		if v.template_name == "controller_stage_04_wall_explosion" then
			explosion_c = v
		end
	end

	U.animation_start(this, "idle_1", false, store.tick_ts, true)

	this.bubble = E:create_entity(this.bubble_t)
	this.bubble.pos = V.vclone(this.pos)
	this.bubble.render.sprites[1].alpha = 0

	queue_insert(store, this.bubble)

	local function activate()
		this.repair.active = true
		times_repaired = times_repaired + 1

		S:queue(this.repair.sound, {
			delay = fts(20)
		})
		U.y_animation_play(this, "reload", false, store.tick_ts)
		U.animation_start(this, "idle_2", false, store.tick_ts, true)

		ab.disabled = false
	end

	local function find_target(aa)
		local target, _, pred_pos = U.find_foremost_enemy(store.entities, tpos(this), 0, this.attacks.range, aa.node_prediction, aa.vis_flags, aa.vis_bans)

		return target, pred_pos
	end

	while true do
		if store.wave_group_number > 0 and tap_bubble_cd < store.tick_ts - bubble_ts and this.bubble.render.sprites[1].alpha <= 0 and not explosion_c.trigger_explosion and store.player_gold >= this.repair.cost then
			this.bubble.render.sprites[1].ts = store.tick_ts
			this.bubble.tween.ts = store.tick_ts
			this.bubble.tween.reverse = false
			this.bubble.tween.disabled = false
			bubble_ts = store.tick_ts
		end

		if not this.repair.active then
			-- block empty
		elseif not ab.disabled then
			local enemy, pred_pos = find_target(ab)

			if not enemy then
				-- block empty
			else
				local enemy_id = enemy.id
				local enemy_pos = V.vclone(enemy.pos)
				local soffset = this.shooter_offset

				S:queue(ab.sound)
				U.animation_start(this, ab.animation, nil, store.tick_ts, false)
				U.y_wait(store, ab.shoot_time)

				local start_offset = ab.bullet_start_offset

				enemy, pred_pos = find_target(ab)

				local b = E:create_entity(ab.bullet)

				b.bullet.damage_factor = this.tower.damage_factor
				b.pos.x, b.pos.y = this.pos.x + start_offset.x, this.pos.y + start_offset.y
				b.bullet.from = V.vclone(b.pos)
				b.bullet.to = enemy and pred_pos or enemy_pos

				local nearest = P:nearest_nodes(b.bullet.to.x, b.bullet.to.y, nil, {
					1
				}, true)[1]
				local pi, spi, ni = unpack(nearest)

				b.bullet.to = P:node_pos(pi, spi, ni)
				b.bullet.source_id = this.id

				queue_insert(store, b)
				U.y_animation_wait(this)
				U.animation_start(this, "idle_1", nil, store.tick_ts, true)

				this.repair.active = false
				this.user_selection.allowed = true
				ab.disabled = true
			end
		end

		if not this.bubble.tween.reverse and (this.user_selection.menu_shown or this.bubble.render.sprites[1].alpha > 0 and store.tick_ts - bubble_ts > 5) then
			this.bubble.tween.ts = store.tick_ts
			this.bubble.tween.reverse = true
			bubble_ts = store.tick_ts
			tap_bubble_cd = this.user_selection.menu_shown and 30 or 10
		end

		if this.user_selection.in_progress and not this.repair.active then
			this.user_selection.in_progress = nil
			this.user_selection.allowed = false
			store.player_gold = store.player_gold - this.repair.cost

			activate()
		end

		coroutine.yield()
	end
end

function scripts.tower_stage_04_crane.remove(this, store)
	queue_remove(store, this.bubble)

	return true
end

scripts.controller_stage_04_wall_explosion = {}

function scripts.controller_stage_04_wall_explosion.update(this, store)
	local mask1, mask3, mask4, crane

	for _, v in pairs(store.entities) do
		if v.template_name == "decal_stage_04_mask_1" then
			mask1 = v
		end

		if v.template_name == "decal_stage_04_mask_3" then
			mask3 = v
		end

		if v.template_name == "decal_stage_04_mask_4" then
			mask4 = v
		end

		if v.template_name == "tower_stage_04_crane" then
			crane = v
		end
	end

	while not this.trigger_explosion do
		coroutine.yield()
	end

	if (store.level_mode_6 or store.level_mode) == GAME_MODE_CAMPAIGN then
		signal.emit("pan-zoom-camera", 2, {
			x = 300,
			y = 450
		}, 1.3)
		signal.emit("show-curtains")
		signal.emit("hide-gui")
		signal.emit("start-cinematic")
	end

	crane.bubble.tween.disabled = true
	crane.bubble.render.sprites[1].alpha = 0

	local decal_explotion = E:create_entity("decal_stage_04_wall_explosion")

	decal_explotion.pos = V.v(512, 384)

	LU.queue_insert(store, decal_explotion)
	U.animation_start(decal_explotion, "start", nil, store.tick_ts, false)
	U.y_wait(store, fts(275))

	local shake = E:create_entity("aura_screen_shake")

	shake.aura.amplitude = 0.4
	shake.aura.duration = 2
	shake.aura.freq_factor = 4

	LU.queue_insert(store, shake)
	U.y_wait(store, fts(15))

	mask1.render.sprites[1].z = Z_OBJECTS_COVERS

	LU.queue_remove(store, mask3)

	local holder_crane = E:create_entity("tower_holder_blocked_terrain_1_3")

	holder_crane.ui.can_click = true
	holder_crane.tower.can_hover = true
	holder_crane.tower.default_rally_pos = V.vclone(crane.tower.default_rally_pos)
	holder_crane.tower.holder_id = crane.tower.holder_id
	holder_crane.ui.nav_mesh_id = crane.ui.nav_mesh_id
	holder_crane.pos = V.vclone(crane.pos)

	LU.queue_insert(store, holder_crane)

	crane.trigger_deselect = true

	LU.queue_remove(store, crane)
	U.y_wait(store, fts(5))
	LU.queue_remove(store, mask4)
	P:activate_path(3)

	for k, v in pairs(store.level.ignore_walk_backwards_paths) do
		if v == 3 then
			store.level.ignore_walk_backwards_paths[k] = nil
		end
	end

	signal.emit("wall_explosion_end")
	U.y_animation_wait(decal_explotion)
	U.animation_start(decal_explotion, "idle", nil, store.tick_ts, true)

	if (store.level_mode_6 or store.level_mode) == GAME_MODE_CAMPAIGN then
		signal.emit("hide-curtains")
