function scripts.decal_stage_05_lamp.update(this, store, script)
	this.tree_stun = false

	while true do
		if this.ui.clicked then
			S:queue(this.sound_in)

			this.ui.clicked = nil
			this.ui.can_click = false

			S:queue(this.sound_break)
			U.y_animation_play(this, "tap", nil, store.tick_ts, 1)
			U.animation_start(this, "idlebreak", nil, store.tick_ts, true)
		end

		if this.tree_stun then
			this.tree_stun = false

			if this.ui.can_click then
				U.animation_start(this, "treestun", nil, store.tick_ts, false)
			else
				U.animation_start(this, "treestunbreak", nil, store.tick_ts, false)
			end
		end

		if this.render.sprites[1].name == "treestun" and U.animation_finished(this) then
			U.animation_start(this, "idle", nil, store.tick_ts, true)
		end

		if this.render.sprites[1].name == "treestunbreak" and U.animation_finished(this) then
			U.animation_start(this, "idlebreak", nil, store.tick_ts, true)
		end

		coroutine.yield()
	end
end

scripts.decal_stage_05_upper_path = {}

function scripts.decal_stage_05_upper_path.update(this, store, script)
	local idle_ts = store.tick_ts
	local idle_cd = math.random(3, 7)

	while not this.goblin_out do
		if this.ui.clicked then
			this.ui.clicked = nil
			this.ui.can_click = false

			S:queue(this.sound_rustle)
			U.y_animation_play(this, "tap", nil, store.tick_ts, 1)
			U.animation_start(this, "idlestart", nil, store.tick_ts, true)

			idle_ts = store.tick_ts
			idle_cd = math.random(3, 7)
			this.ui.can_click = true
		end

		if this.ui.can_click and idle_cd < store.tick_ts - idle_ts then
			idle_ts = store.tick_ts
			idle_cd = math.random(3, 7)

			U.animation_start(this, "anim", nil, store.tick_ts, false)
		end

		if this.render.sprites[1].name == "action" and U.animation_finished(this) then
			U.animation_start(this, "idlestart", nil, store.tick_ts, true)
		end

		coroutine.yield()
	end

	U.animation_start(this, "goblinout", nil, store.tick_ts, 1)
	U.y_wait(store, fts(134))
	S:queue(this.sound_barrel)

	while not U.animation_finished(this) do
		coroutine.yield()
	end

	U.animation_start(this, "idlebarrel", nil, store.tick_ts, true)

	while not this.open_path do
		coroutine.yield()
	end

	U.animation_start(this, "openpath", nil, store.tick_ts, 1)
	U.y_wait(store, fts(44))
	S:queue(this.sound_fling)
	U.y_wait(store, fts(45))
	S:queue(this.sound_explosion)

	while not U.animation_finished(this) do
		coroutine.yield()
	end

	queue_remove(store, this)
end

scripts.controller_stage_05_leaves = {}

function scripts.controller_stage_05_leaves.update(this, store, script)
	local tree

	for k, v in pairs(store.entities) do
		if v.template_name == this.tree_t then
			tree = v

			break
		end
	end

	while true do
		if tree.render.sprites[1].name == "idle" then
			local leaf = E:create_entity(this.leaf_t)

			leaf.pos = V.v(this.pos.x + math.random(-this.spawn_width / 2, this.spawn_width / 2), this.pos.y)
			leaf.render.sprites[1].flip_x = math.random(1, 2) == 1
			leaf.render.sprites[1].ts = store.tick_ts

			queue_insert(store, leaf)
			U.y_wait(store, fts(math.random(this.spawn_cd_min * 30, this.spawn_cd_max * 30)))
		end

		coroutine.yield()
	end

	queue_remove(store, this)
end

scripts.decal_stage_05_kodama = {}

function scripts.decal_stage_05_kodama.update(this, store, script)
	U.y_wait(store, U.frandom(0, 5))

	local c = find_all_t(store, this.controller_t)[1]
	local appeared = false
	local out_ts = store.tick_ts
	local appeared_ts = store.tick_ts
	local tweening_ts = store.tick_ts
	local disappearing = false
	local fadein_wait = U.frandom(this.fadein_min_wait, this.fadein_max_wait)

	while c do
		if fadein_wait < store.tick_ts - out_ts and not appeared then
			appeared_ts = store.tick_ts
			appeared = true
			this.ui.can_click = true

			U.animation_start(this, "idle", nil, store.tick_ts, true)

			this.tween.reverse = false
			this.tween.run_once = false
			this.tween.disabled = false
			this.tween.ts = store.tick_ts
		end

		if store.tick_ts - appeared_ts > this.appeared_wait and appeared then
			out_ts = store.tick_ts
			appeared = false
			disappearing = true
			tweening_ts = store.tick_ts
			this.tween.reverse = true
			this.tween.run_once = true
			this.tween.ts = store.tick_ts
		end

		if disappearing and store.tick_ts - tweening_ts > this.tween.props[1].keys[2][1] then
			disappearing = false
			this.ui.can_click = false
		end

		if this.ui.clicked then
			this.ui.clicked = nil
			this.tween.reverse = false
			this.tween.run_once = true
			this.tween.ts = store.tick_ts
			this.tween.props[1].keys[1][1] = 0
			this.tween.props[1].keys[1][2] = this.render.sprites[1].alpha
			this.tween.props[1].keys[2][1] = 1
			this.tween.props[1].keys[2][2] = 255

			U.y_wait(store, 1.75)
			U.y_animation_play(this, "fadeout", nil, store.tick_ts, 1)
			U.animation_start(this, "idlefadeout", nil, store.tick_ts, true)

			c.kodama_tapped = c.kodama_tapped + 1

			break
		end

		coroutine.yield()
	end

	this.render.sprites[1].alpha = 255

	while not this.final_animation do
		coroutine.yield()
	end

	U.y_wait(store, this.random_wait)
	U.y_animation_play(this, "fadein", nil, store.tick_ts, 1)
	U.y_animation_play(this, "tap", nil, store.tick_ts, 1)
	queue_remove(store, this)
end

scripts.controller_stage_05_kodama = {}

function scripts.controller_stage_05_kodama.update(this, store, script)
	local kodamas = find_all_t(store, this.kodama_t, true)

	while this.kodama_tapped < #kodamas do
		coroutine.yield()
	end

	local max_wait = 0

	for i, ko in ipairs(kodamas) do
		ko.final_animation = true

		local rf = math.random(2, 12)

		ko.random_wait = fts(rf)
		max_wait = math.max(max_wait, rf)
	end

	U.y_wait(store, fts(132 + max_wait))
	signal.emit("frenzied-spirits-stage05")
	queue_remove(store, this)
end

scripts.controller_stage_05_tree = {}

function scripts.controller_stage_05_tree.update(this, store, script)
	local tree, zone
	local lamps = {}

	if (store.level_mode_6 or store.level_mode) == GAME_MODE_IRON then
		this.cooldown = this.cooldown_iron
	end

	for k, v in pairs(store.entities) do
		if v.template_name == this.tree_t then
			tree = v
		end

		if v.template_name == this.zone_t then
			zone = v
		end

		if v.template_name == this.lamp_t or v.template_name == this.lamp_t .. "_f" then
			table.insert(lamps, v)
		end
	end

	this.pos = V.vclone(tree.pos)

	local aura_pos = V.vclone(tree.pos)

	aura_pos.y = aura_pos.y - 20

	local decal_buff = E:create_entity(this.decal_buff_t)

	decal_buff.render.sprites[1].ts = store.tick_ts
	decal_buff.pos = V.v(609, 340)
	decal_buff.tween.ts = store.tick_ts

	queue_insert(store, decal_buff)

	local souls = E:create_entity(this.souls_t)

	souls.render.sprites[1].ts = store.tick_ts
	souls.pos = V.v(609, 340)
	souls.tween.ts = store.tick_ts

	queue_insert(store, souls)
	U.animation_start(tree, "idlecharging", nil, store.tick_ts, true, 1)

	while store.wave_group_number == 0 do
		coroutine.yield()
	end

	local decal_ready = E:create_entity(this.decal_ready_t)

	decal_ready.render.sprites[1].ts = store.tick_ts
	decal_ready.pos = V.v(609, 340)

	queue_insert(store, decal_ready)

	if this.recover_sound then
		S:queue(this.recover_sound, {
			delay = fts(this.recover_sound_frame)
		})
	end

	U.y_animation_play(tree, "backtoidle", nil, store.tick_ts, 1)
	U.animation_start(tree, "idle", nil, store.tick_ts, true, 1, true)

	this.ui.clicked = nil

	local aura = E:create_entity(this.aura_t)

	aura.pos = aura_pos

	queue_insert(store, aura)
	U.y_animation_play(zone, "appear2", nil, store.tick_ts, 1)
	U.animation_start(zone, "idle2", nil, store.tick_ts, 1)

	this.path_unlocked = false

	while true do
		if this.ui.clicked then
			this.ui.clicked = nil
			this.ui.can_click = false
			decal_buff.tween.reverse = true
			decal_buff.tween.remove = true
			souls.tween.reverse = true
			souls.tween.remove = true

			queue_remove(store, aura)

			aura = nil

			if this.path_unlocked then
				U.animation_start(zone, "disappear", nil, store.tick_ts, false)
			else
				U.animation_start(zone, "disappear2", nil, store.tick_ts, false)
			end

			local decal_stun = E:create_entity(this.decal_stun_t)

			decal_stun.render.sprites[1].ts = store.tick_ts
			decal_stun.pos = V.vclone(this.pos)

			queue_insert(store, decal_stun)
			S:queue(this.sound_activation)
			U.animation_start(tree, "stun", nil, store.tick_ts, false)
			U.y_wait(store, this.stun_delay)

			for k, v in pairs(lamps) do
				v.tree_stun = true
			end

			local shake = E:create_entity("aura_screen_shake")

			shake.aura.amplitude = 1
			shake.aura.duration = 0.4
			shake.aura.freq_factor = 2

			queue_insert(store, shake)

			local enemies = {}

			for _, enemy in pairs(store.entities) do
				if enemy.enemy and enemy.nav_path and enemy.pos and enemy.vis and enemy.health
					and not enemy.pending_removal and not enemy.health.dead
					and band(enemy.vis.flags, this.vis_bans) == 0
					and band(enemy.vis.bans, this.vis_flags) == 0
					and U.is_inside_ellipse(enemy.pos, aura_pos, this.radius) then
					enemies[#enemies + 1] = enemy
				end
			end

			if #enemies > 0 then
				for k, v in pairs(enemies) do
					local mod = E:create_entity(this.mod_stun)

					mod.modifier.target_id = v.id
					mod.modifier.source_id = this.id

					queue_insert(store, mod)

					local d = E:create_entity("damage")

					d.value = math.random(this.damage_min, this.damage_max)
					d.source_id = this.id
					d.target_id = v.id
					d.damage_type = this.damage_type

					queue_damage(store, d)
				end
			end

			U.y_animation_wait(tree)
			U.animation_start(tree, "idlecharging", nil, store.tick_ts, true)
			U.y_wait(store, this.cooldown)

			if this.path_unlocked then
				U.animation_start(zone, "appear", nil, store.tick_ts, 1)
			else
				U.animation_start(zone, "appear2", nil, store.tick_ts, 1)
			end

			aura = E:create_entity(this.aura_t)
			aura.pos = aura_pos

			queue_insert(store, aura)

			decal_buff = E:create_entity(this.decal_buff_t)
			decal_buff.render.sprites[1].ts = store.tick_ts
			decal_buff.pos = V.v(609, 340)
			decal_buff.tween.ts = store.tick_ts

			queue_insert(store, decal_buff)

			souls = E:create_entity(this.souls_t)
			souls.render.sprites[1].ts = store.tick_ts
			souls.pos = V.v(609, 340)
			souls.tween.ts = store.tick_ts

			queue_insert(store, souls)

			decal_ready = E:create_entity(this.decal_ready_t)
			decal_ready.render.sprites[1].ts = store.tick_ts
			decal_ready.pos = V.v(609, 340)

			queue_insert(store, decal_ready)

			if this.recover_sound then
				S:queue(this.recover_sound, {
					delay = fts(this.recover_sound_frame)
				})
			end

			U.y_animation_play(tree, "backtoidle", nil, store.tick_ts, 1)
			U.animation_start(tree, "idle", nil, store.tick_ts, true, 1, true)

			this.ui.can_click = true
		end

		if zone.render.sprites[1].name == "appear2" and U.animation_finished(zone) then
			U.animation_start(zone, "idle2", nil, store.tick_ts, true)
		end

		if zone.render.sprites[1].name == "appear" and U.animation_finished(zone) then
			U.animation_start(zone, "idle", nil, store.tick_ts, true)
		end

		if zone.render.sprites[1].name == "thirdpathspawn" and U.animation_finished(zone) then
			U.animation_start(zone, "idle", nil, store.tick_ts, true)
		end

		if this.path_unlocked and zone.render.sprites[1].name == "idle2" then
			U.animation_start(zone, "thirdpathspawn", nil, store.tick_ts, false)
		end

		coroutine.yield()
	end
end

scripts.mod_stage_05_tree_stun = {}

function scripts.mod_stage_05_tree_stun.insert(this, store, script)
	local m = this.modifier
	local target = store.entities[m.target_id]

	if not target or target.health.dead then
		return false
	end

	if target.vis and not U.flags_pass(target.vis, this.modifier) then
		log.paranoid("mod %s cannot be applied to entity %s:%s because of vis flags/bans", this.template_name, target.id, target.template_name)

		return false
	end

	if target and target.unit and this.render then
		for i = 1, #this.render.sprites do
			local s = this.render.sprites[i]

			if s.size_names then
				s.prefix = s.prefix .. s.size_names[target.unit.size]
			end
		end
	end

	m.ts = store.tick_ts

	SU.stun_inc(target)
	log.paranoid("mod_stun.insert (%s)-%s for target (%s)-%s", this.id, this.template_name, target.id, target.template_name)
	signal.emit("mod-applied", this, target)

	return true
end

function scripts.mod_stage_05_tree_stun.update(this, store, script)
	local start_ts, target_hidden
	local m = this.modifier
	local target = store.entities[this.modifier.target_id]

	if not target then
		queue_remove(store, this)

		return
	end

	this.pos = target.pos

	U.y_animation_play(this, this.animation_start, nil, store.tick_ts, 1)
	U.animation_start(this, this.animation_idle, nil, store.tick_ts, false)

	while store.tick_ts - m.ts < m.duration - this.out_before and target and not target.health.dead do
		if this.render and m.use_mod_offset and target.unit.mod_offset and not m.custom_offsets then
			for i = 1, #this.render.sprites do
				local s = this.render.sprites[i]

				s.offset.x, s.offset.y = target.unit.mod_offset.x, target.unit.mod_offset.y
			end
		end

		coroutine.yield()
	end

	U.y_animation_play(this, this.animation_end, nil, store.tick_ts, 1)
	queue_remove(store, this)
end

scripts.aura_stage_05_tree = {}

function scripts.aura_stage_05_tree.update(this, store, script)
	local first_hit_ts
	local last_hit_ts = 0

	last_hit_ts = store.tick_ts - this.aura.cycle_time

	while true do
		if this.aura.duration >= 0 and store.tick_ts - this.aura.ts > this.actual_duration then
			break
		end

		if not (store.tick_ts - last_hit_ts >= this.aura.cycle_time) or this.aura.apply_duration and first_hit_ts and store.tick_ts - first_hit_ts > this.aura.apply_duration then
			-- block empty
		else
			first_hit_ts = first_hit_ts or store.tick_ts
			last_hit_ts = store.tick_ts

			local targets = U.find_soldiers_in_range(store.entities, this.pos, 0, this.aura.radius, 0, 0, function(v, o)
				return not this.aura.allowed_templates or table.contains(this.aura.allowed_templates, v.template_name)
			end)

			if targets then
				for i, target in ipairs(targets) do
					local new_mod = E:create_entity(this.aura.mod)

					new_mod.modifier.level = this.aura.level
					new_mod.modifier.target_id = target.id
					new_mod.modifier.source_id = this.id

					queue_insert(store, new_mod)
				end
			end
		end

		coroutine.yield()
	end

	queue_remove(store, this)
end

scripts.mod_stage_05_tree_buff = {}

function scripts.mod_stage_05_tree_buff.insert(this, store, script)
	local m = this.modifier
	local target = store.entities[m.target_id]

	if not target or target.health.dead then
		return false
	end

	if band(this.modifier.vis_flags, target.vis.bans) ~= 0 or band(this.modifier.vis_bans, target.vis.flags) ~= 0 then
		log.paranoid("mod %s cannot be applied to entity %s:%s because of vis flags/bans", this.template_name, target.id, target.template_name)

		return false
	end

	this.tween.ts = store.tick_ts

	if target.template_name == "hero_stage_05_alleria" then
		target.motion.max_speed = target.motion.max_speed * this.alleria_speed_buff
		target.regen.health = target.regen.health * this.alleria_regen_buff
		target.timed_attacks.list[1]._shots = target.timed_attacks.list[1].shots
		target.timed_attacks.list[1].shots = this.alleria_multishots_buff
	elseif target.template_name ~= "soldier_alleria_cat" then
		return false
	end

	return true
end

function scripts.mod_stage_05_tree_buff.update(this, store, script)
	local m = this.modifier

	this.modifier.ts = store.tick_ts

	local target = store.entities[m.target_id]

	if not target or not target.pos then
		queue_remove(store, this)

		return
	end

	this.pos = target.pos

	while true do
		target = store.entities[m.target_id]

		if not target or target.health.dead or m.duration >= 0 and store.tick_ts - m.ts > m.duration then
			this.tween.ts = store.tick_ts
			this.tween.reverse = true
			this.tween.remove = true

			return
		end

		if this.render and target.unit then
			local s = this.render.sprites[1]
			local flip_sign = 1

			if target.render then
				flip_sign = target.render.sprites[1].flip_x and -1 or 1
			end

			if m.health_bar_offset and target.health_bar then
				local hb = target.health_bar.offset
				local hbo = m.health_bar_offset

				s.offset.x, s.offset.y = hb.x + hbo.x * flip_sign, hb.y + hbo.y
			elseif m.use_mod_offset and target.unit.mod_offset then
				s.offset.x, s.offset.y = target.unit.mod_offset.x * flip_sign, target.unit.mod_offset.y
			end
		end

		coroutine.yield()
	end
end

function scripts.mod_stage_05_tree_buff.remove(this, store, script)
	local m = this.modifier
	local target = store.entities[m.target_id]

	if target.template_name == "hero_stage_05_alleria" then
		target.motion.max_speed = target.motion.max_speed / this.alleria_speed_buff
		target.regen.health = target.regen.health / this.alleria_regen_buff
		target.timed_attacks.list[1].shots = target.timed_attacks.list[1]._shots
	end

	return true
end

scripts.decal_stage_06_mushroom_mage = {}

function scripts.decal_stage_06_mushroom_mage.update(this, store, script)
	while not this.ui.clicked do
		coroutine.yield()
	end

	local smoke = find_all_t(store, this.smoke_t)[1]
	local lights = find_all_t(store, this.lights_t)[1]

	U.animation_start(smoke, "out", nil, store.tick_ts, 1)
	U.animation_start(lights, "out", nil, store.tick_ts, 1)
	U.animation_start(this, "tap", nil, store.tick_ts, 1)

	for i, v in ipairs(this.sounds) do
		U.y_wait(store, this.waits_sound[i])
		S:queue(v)
	end
end

scripts.decal_stage_06_flush_stick = {}

function scripts.decal_stage_06_flush_stick.update(this, store, script)
	while not this.ui.clicked do
		coroutine.yield()
	end

	U.animation_start(this, "tap", nil, store.tick_ts, 1)
	S:queue(this.sound_flush)
	U.y_wait(store, fts(15))

	local wave = find_all_t(store, this.wave_t)[1]

	queue_remove(store, wave)

	local mage = find_all_t(store, this.mage_t)[1]

	U.y_animation_play(mage, "flush", nil, store.tick_ts, 1)
	U.animation_start(mage, "loop_2", nil, store.tick_ts, true)
end

scripts.controller_stage_06_nivus = {}

function scripts.controller_stage_06_nivus.update(this, store)
	local current_mode = 1
	local spells = {
		this.books,
		this.disintegrate,
		this.brooms
	}
	local nivus, bubble

	local function find_target(spell, ignore_fail)
		local pred_time = spell.time_to_hit

		if spell == this.disintegrate then
			pred_time = 0
		end

		local target, targets, pred_pos = U.find_foremost_enemy(store.entities, v(512, 350), spell.min_range, spell.max_range, pred_time, spell.vis_flags, spell.vis_bans, function(e, o)
			if spell == this.disintegrate then
				return e.health.hp >= this.disintegrate.min_hp and e.health.hp <= this.disintegrate.max_hp and e.nav_path and P:is_node_valid(e.nav_path.pi, e.nav_path.ni)
			else
				return e.nav_path and P:is_node_valid(e.nav_path.pi, e.nav_path.ni)
			end
		end)

		if spell == this.brooms then
			target, targets, pred_pos = U.find_foremost_enemy(store.entities, v(512, 350), spell.min_range, spell.max_range, pred_time, spell.vis_flags, spell.vis_bans, function(e, o)
				return e.nav_path and P:is_node_valid(e.nav_path.pi, e.nav_path.ni) and P:nodes_to_goal(e.nav_path) >= spell.min_nodes
			end)

			if not targets or #targets == 0 then
				target, targets, pred_pos = U.find_foremost_enemy(store.entities, v(512, 350), spell.min_range, spell.max_range, pred_time, spell.vis_flags, spell.vis_bans, function(e, o)
					return e.nav_path and P:is_node_valid(e.nav_path.pi, e.nav_path.ni)
				end)
			end
		end

		if spell == this.disintegrate and not target then
			target, targets, pred_pos = U.find_foremost_enemy(store.entities, v(512, 350), spell.min_range, spell.max_range, pred_time, spell.vis_flags, spell.vis_bans)

			if targets then
				table.sort(targets, function(v1, v2)
					return v1.health.hp > v2.health.hp
				end)

				target = targets[1]
				pred_pos = target.__ffe_pos
			end
		end

		if not ignore_fail and (not target or not pred_pos) then
			nivus.tween.disabled = false
			nivus.tween.ts = store.tick_ts
		end

		return target, targets, pred_pos
	end

	local function y_shoot_magic_missiles()
		local target, targets, pred_pos = find_target(this.magic_missiles, true)

		if not target then
			return
		end

		local enemies = U.find_enemies_in_range(store.entities, target.pos, 0, 100, this.magic_missiles.vis_flags, this.magic_missiles.vis_bans)

		if not enemies or #enemies <= 0 then
			return
		end

		local target_idx = 1

		U.y_animation_play(nivus, this.magic_missiles.animation_in, nil, store.tick_ts, 1)

		for i = 1, this.magic_missiles.count do
			target = enemies[target_idx]

			U.animation_start(nivus, this.magic_missiles.animation_shoot, nil, store.tick_ts, false)
			U.y_wait(store, this.magic_missiles.shoot_time)

			local b = E:create_entity(this.magic_missiles.bullet)

			b.pos = V.vclone(nivus.pos)

			local offset = this.magic_missiles.bullet_start_offset

			b.pos.x, b.pos.y = b.pos.x + offset.x, b.pos.y + offset.y
			b.bullet.from = V.vclone(b.pos)
			b.bullet.to = V.v(target.pos.x + target.unit.hit_offset.x, target.pos.y + target.unit.hit_offset.y)
			b.bullet.target_id = target.id
			b.bullet.shot_index = 1
			b.bullet.loop_index = i
			b.bullet.source_id = this.id

			queue_insert(store, b)
			U.y_animation_wait(nivus)

			target_idx = target_idx + 1

			if target_idx > #enemies then
				target_idx = 1
			end
		end

		U.y_animation_play(nivus, this.magic_missiles.animation_out, nil, store.tick_ts, 1)
		U.animation_start(nivus, "idle", nil, store.tick_ts, true)
	end

	while true do
		local current_spell = spells[current_mode]

		nivus = E:create_entity(this.nivus_t)
		nivus.pos = V.vclone(current_spell.spawn_pos)
		nivus.render.sprites[1].sort_y_offset = 384 - nivus.pos.y + this.nivus_sort_y_offset
		nivus.render.sprites[1].ts = store.tick_ts
		nivus.render.sprites[1].hidden = false

		queue_insert(store, nivus)
		U.y_animation_play(nivus, "in", nil, store.tick_ts, 1)
		U.animation_start(nivus, "idle", nil, store.tick_ts, true)

		bubble = E:create_entity(current_spell.bubble_t)
		bubble.pos = V.vclone(nivus.pos)
		bubble.pos.x = bubble.pos.x + this.bubble_offset.x
		bubble.pos.y = bubble.pos.y + this.bubble_offset.y
		bubble.render.sprites[1].hidden = true
		bubble.tween.ts = store.tick_ts

		queue_insert(store, bubble)

		this.ui.click_rect.pos.x = nivus.pos.x - this.pos.x - this.ui.click_rect.size.x / 2
		this.ui.click_rect.pos.y = nivus.pos.y - this.pos.y

		local books = {}
		local target_picked, _, pred_pos

		this.ui.clicked = nil

		if current_mode == 1 then
			for i = 1, 3 do
				local start_ts = store.tick_ts

				U.animation_start(nivus, this.books.animation_charge, nil, store.tick_ts, false)
				U.y_wait(store, fts(11))

				local fx = E:create_entity(this.books.book_charge_fx_t)

				fx.pos = V.v(nivus.pos.x, nivus.pos.y + 50)
				fx.render.sprites[1].ts = store.tick_ts

				queue_insert(store, fx)

				local book = E:create_entity(this.books.book_charge_t)

				book.pos = V.v(nivus.pos.x + this.books.offsets[i].x, nivus.pos.y + this.books.offsets[i].y)
				book.tween.ts = store.tick_ts

				local starting_offset = V.v(fx.pos.x - book.pos.x, fx.pos.y - book.pos.y)

				book.tween.props[5] = E:clone_c("tween_prop")
				book.tween.props[5].keys = {
					{
						0,
						starting_offset
					},
					{
						1,
						v(0, 0)
					}
				}
				book.tween.props[5].name = "offset"
				book.tween.props[6] = table.deepclone(book.tween.props[5])
				book.tween.props[6].sprite_id = 2

				queue_insert(store, book)
				table.insert(books, book)

				if i == 2 then
					book.tween.props[2].keys = {
						{
							0,
							0
						},
						{
							1,
							1.9 * math.pi
						}
					}
					book.tween.props[4].keys = {
						{
							0,
							0
						},
						{
							1,
							1.9 * math.pi
						}
					}
				elseif i == 3 then
					book.render.sprites[1].flip_x = true
					book.render.sprites[2].flip_x = true
					book.tween.props[2].keys = {
						{
							0,
							0
						},
						{
							1,
							-1.8 * math.pi
						}
					}
					book.tween.props[4].keys = {
						{
							0,
							0
						},
						{
							1,
							-1.8 * math.pi
						}
					}
				end

				U.y_animation_wait(nivus)
				U.animation_start(nivus, "idle", nil, store.tick_ts, true)

				local et = store.tick_ts - start_ts

				U.y_wait(store, 1 - et + fts(11))

				book.tween.props[1].disabled = false

				for i = 2, 6 do
					book.tween.props[i].disabled = true
				end

				book.tween.ts = store.tick_ts
				et = store.tick_ts - start_ts

				if this.ui.clicked then
					this.ui.clicked = nil
					target_picked, _, pred_pos = find_target(this.books)

					if target_picked then
						break
					end
				end

				U.y_wait(store, this.books.delay_between_books - et)

				if this.ui.clicked then
					this.ui.clicked = nil
					target_picked, _, pred_pos = find_target(this.books)

					if target_picked then
						break
					end
				end
			end
		end

		local wait_ts = store.tick_ts
		local bubble_ts = store.tick_ts
		local bubble_cd = 2
		local near_target, _, _ = find_target(current_spell, true)

		if near_target and (not target_picked or not pred_pos) then
			bubble.render.sprites[1].hidden = false
			bubble.tween.ts = store.tick_ts
		end

		bubble.tween.reverse = true

		while not this.ui.clicked do
			if store.tick_ts - wait_ts > this.magic_missiles.cooldown then
				wait_ts = store.tick_ts

				y_shoot_magic_missiles()
			end

			if bubble_cd < store.tick_ts - bubble_ts then
				near_target, _, pred_pos = find_target(current_spell, true)

				if near_target or not bubble.tween.reverse then
					bubble.render.sprites[1].hidden = false
					bubble_cd = bubble.tween.reverse and 3 or 8
					bubble.tween.ts = store.tick_ts
					bubble.tween.reverse = not bubble.tween.reverse
					bubble_ts = store.tick_ts
				end
			end

			coroutine.yield()
		end

		this.ui.clicked = nil
		target_picked, _, pred_pos = find_target(current_spell, true)

		queue_remove(store, bubble)

		if current_mode == 1 then
			U.animation_start(nivus, this.books.animation_shoot, nil, store.tick_ts, false)
			U.y_wait(store, this.books.cast_time)

			if not target_picked or not pred_pos then
				target_picked, _, pred_pos = find_target(current_spell, true)
			end

			pred_pos = pred_pos or V.v(575, 242)

			for i = 1, #books do
				local fx = E:create_entity(this.books.book_charge_fx_t)

				fx.pos = books[i].pos
				fx.render.sprites[1].ts = store.tick_ts

				queue_insert(store, fx)

				local b = E:create_entity(this.books.bullet_t)

				b.pos = books[i].pos
				b.bullet.from = V.vclone(b.pos)
				b.bullet.to = pred_pos

				local nearest = P:nearest_nodes(b.bullet.to.x, b.bullet.to.y, nil, {
					1
				}, true)[1]
				local pi, spi, ni = unpack(nearest)

				spi = i

				if i == 2 or i == 3 then
					ni = ni + 3
				end

				b.bullet.to = P:node_pos(pi, spi, ni)
				b.bullet.source_id = this.id

				queue_insert(store, b)
				queue_remove(store, books[i])
				U.y_wait(store, fts(3))
			end

			local c = E:create_entity(this.books.squad_controller_t)

			c.books_spawned = #books

			queue_insert(store, c)
			U.y_animation_wait(nivus)
		elseif current_mode == 2 then
			local target_pos = target_picked and target_picked.pos or V.v(575, 242)

			if target_picked then
				local m = E:create_entity(this.disintegrate.mod_stun)

				m.modifier.target_id = target_picked.id
				m.modifier.source_id = this.id

				queue_insert(store, m)

				target_picked.health.ignore_damage = true

				U.y_wait(store, fts(1))

				target_picked.vis.bans = F_ALL

				local nivus_on_the_right = math.abs(km.signed_unroll(target_picked.heading.angle)) < math.pi / 2

				target_pos = V.v(target_picked.pos.x + (target_picked.enemy.melee_slot.x + 20) * (nivus_on_the_right and 1 or -1), target_picked.pos.y + target_picked.enemy.melee_slot.y)
			end

			S:queue(this.disintegrate.sound_teleport)
			U.y_animation_play(nivus, this.disintegrate.animation_out, nil, store.tick_ts, 1)
			U.y_wait(store, fts(10))

			nivus.pos = target_pos
			nivus.render.sprites[1].flip_x = target_picked and math.abs(km.signed_unroll(target_picked.heading.angle)) < math.pi / 2
			nivus.render.sprites[1].z = Z_OBJECTS
			nivus.render.sprites[1].sort_y_offset = 0

			S:queue(this.disintegrate.sound_teleport)
			U.y_animation_play(nivus, this.disintegrate.animation_in, nil, store.tick_ts, 1)
			U.animation_start(nivus, this.disintegrate.animation_cast, nil, store.tick_ts, false)
			U.y_wait(store, this.disintegrate.cast_time)
			S:queue(this.disintegrate.sound_cast)

			if target_picked then
				target_picked.health.ignore_damage = false

				local d = E:create_entity("damage")

				d.damage_type = DAMAGE_EAT
				d.source_id = this.id
				d.target_id = target_picked.id
				d.value = 1e+99

				queue_damage(store, d)

				local fx = E:create_entity(this.disintegrate.vanish_fx_t)

				fx.pos = v(target_picked.pos.x + target_picked.unit.hit_offset.x, target_picked.pos.y + target_picked.unit.hit_offset.y)
				fx.render.sprites[1].ts = store.tick_ts

				queue_insert(store, fx)
			end

			U.y_animation_wait(nivus)
			U.y_wait(store, fts(10))
			S:queue(this.disintegrate.sound_teleport)
			U.y_animation_play(nivus, this.disintegrate.animation_out, nil, store.tick_ts, 1)

			nivus.pos = V.vclone(this.disintegrate.spawn_pos)
			nivus.render.sprites[1].flip_x = false
			nivus.render.sprites[1].z = Z_FLYING_HEROES
			nivus.render.sprites[1].sort_y_offset = 384 - nivus.pos.y - 101

			S:queue(this.disintegrate.sound_teleport)
			U.y_animation_play(nivus, this.disintegrate.animation_in, nil, store.tick_ts, 1)
		else
			U.animation_start(nivus, this.brooms.animation, nil, store.tick_ts, false)
			U.y_wait(store, this.brooms.cast_time)

			local new_target, _, _ = find_target(this.brooms, true)

			if new_target then
				target_picked = new_target
			end

			local target_pos = V.v(575, 242)

			if target_picked then
				target_pos = V.v(target_picked.pos.x + target_picked.unit.hit_offset.x, target_picked.pos.y + target_picked.unit.hit_offset.y)
			end

			this.chain_targets = {}

			local b = E:create_entity(this.brooms.ray_t)
			local start_offset = this.brooms.bullet_start_offset

			b.pos.x, b.pos.y = nivus.pos.x + start_offset.x, nivus.pos.y + start_offset.y
			b.bullet.from = V.vclone(b.pos)
			b.bullet.to = target_pos
			b.bullet.target_id = target_picked and target_picked.id
			b.bullet.source_id = this.id
			b.chain_pos = 1

			queue_insert(store, b)

			if target_picked then
				table.insert(this.chain_targets, target_picked.id, target_picked.id)
			end

			local dist = V.dist(b.bullet.from.x, b.bullet.from.y, target_pos.x, target_pos.y)
			local fxs = math.floor(dist / 80)
			local dist_v = V.v(target_pos.x - b.bullet.from.x, target_pos.y - b.bullet.from.y)

			for i = 1, fxs - 1 do
				local dist_v_aux = V.v(i / fxs * dist_v.x, i / fxs * dist_v.y)
				local fx = E:create_entity(this.brooms.magic_fx_t)

				fx.pos.x, fx.pos.y = V.add(b.bullet.from.x, b.bullet.from.y, dist_v_aux.x, dist_v_aux.y)
				fx.render.sprites[1].ts = store.tick_ts

				if math.random(1, 2) == 1 then
					fx.render.sprites[1].flip_x = true
				end

				queue_insert(store, fx)
				U.y_wait(store, fts(1))
			end

			U.y_animation_wait(nivus)
		end

		U.animation_start(nivus, "idle", nil, store.tick_ts, true)
		U.y_wait(store, fts(15))
		U.y_animation_play(nivus, "out", nil, store.tick_ts, 1)

		nivus.render.sprites[1].hidden = true

		U.y_wait(store, this.delay_between_spells)

		current_mode = current_mode + 1

		if current_mode > 3 then
			current_mode = 1
		end
	end
end

scripts.controller_stage_06_nivus_books_squads = {}

function scripts.controller_stage_06_nivus_books_squads.update(this, store)
	local books

	repeat
		coroutine.yield()

		books = find_all_t(store, this.books_t)
	until books and #books >= this.books_spawned

	for i, b in ipairs(books) do
		b.reinforcement.squad_id = this.id

		local a = 2 * math.pi / 3
		local pos = U.point_on_ellipse(books[1].pos, 25, (i - 1) * a - math.pi / 2 + math.pi / 4)
		local center = V.vclone(books[1].pos)

		b.nav_rally.pos, b.nav_rally.center = pos, center
	end

	queue_remove(store, this)
end

scripts.bullet_nivus_magic_missiles = {}

function scripts.bullet_nivus_magic_missiles.insert(this, store)
	local b = this.bullet

	if not store.entities[b.target_id] then
