	end

	b.to = V.v(this.pos.x + math.random(10, 90) * (math.random() < 0.5 and -1 or 1), this.pos.y + math.random(100, 300))

	local ps = E:create_entity(b.particles_name)

	ps.particle_system.track_id = this.id

	queue_insert(store, ps)

	return true
end

scripts.soldier_nivus_book = {}

function scripts.soldier_nivus_book.insert(this, store, script)
	this.nav_rally.center = V.vclone(this.pos)
	this.nav_rally.pos = V.vclone(this.pos)

	return scripts.soldier_reinforcement.insert(this, store, script)
end

scripts.bullet_nivus_brooms = {}

function scripts.bullet_nivus_brooms.update(this, store)
	local b = this.bullet
	local s = this.render.sprites[1]
	local target = store.entities[b.target_id]
	local source = store.entities[b.source_id]
	local dest = V.vclone(b.to)

	local function update_sprite()
		if this.track_target and target and target.motion then
			local tpx, tpy = target.pos.x, target.pos.y

			tpx, tpy = tpx + target.unit.hit_offset.x, tpy + target.unit.hit_offset.y
			dest.x, dest.y = tpx, tpy
			b.to.x, b.to.y = target.pos.x + target.unit.hit_offset.x, target.pos.y + target.unit.hit_offset.y
		end

		local angle = V.angleTo(dest.x - this.pos.x, dest.y - this.pos.y)

		s.r = angle

		local dist_offset = 0

		if this.dist_offset then
			dist_offset = this.dist_offset
		end

		s.scale.x = (V.dist(dest.x, dest.y, this.pos.x, this.pos.y) + dist_offset) / this.image_width
	end

	s.scale = s.scale or V.vv(1)

	U.animation_start(this, "run", nil, store.tick_ts, false)
	update_sprite()

	if b.hit_fx then
		local is_air = target and band(target.vis.flags, F_FLYING) ~= 0
		local fx = E:create_entity(b.hit_fx)

		fx.pos = target and target.pos or b.to
		fx.render.sprites[1].ts = store.tick_ts
		fx.render.sprites[1].offset = target and target.unit.hit_offset or V.v(0, 0)

		queue_insert(store, fx)
	end

	if b.hit_time > fts(1) then
		while store.tick_ts - s.ts < b.hit_time do
			coroutine.yield()

			if target and U.flag_has(target.vis.bans, F_RANGED) then
				target = nil
			end

			if this.track_target then
				update_sprite()
			end
		end
	end

	U.y_wait(store, fts(1))

	if this.chain_pos < this.max_chain_length and target then
		local chain_target, targets, _ = U.find_nearest_enemy(store.entities, target.pos, 0, this.chain_range, this.vis_flags, this.vis_bans, function(e, o)
			return not table.contains(source.chain_targets, e.id) and e.template_name ~= "enemy_nivus_broom" and e.template_name ~= "enemy_nivus_broom_flying"
		end)

		if chain_target then
			local chain = E:create_entity(this.chain_ray_t)
			local start_offset = target.unit.hit_offset

			chain.pos.x, chain.pos.y = target.pos.x + start_offset.x, target.pos.y + start_offset.y
			chain.bullet.from = V.vclone(chain.pos)

			local end_offset = chain_target.unit.hit_offset

			chain.bullet.to = V.vclone(chain_target.pos)
			chain.bullet.to.x, chain.bullet.to.y = chain.bullet.to.x + end_offset.x, chain.bullet.to.y + end_offset.y
			chain.bullet.target_id = chain_target.id
			chain.bullet.source_id = b.source_id
			chain.chain_pos = this.chain_pos + 1

			queue_insert(store, chain)
			table.insert(source.chain_targets, chain_target.id, chain_target.id)
		end
	end

	::label_1074_0::

	U.y_wait(store, fts(5))

	local mods_added = {}

	if not target then
		goto label_1074_0
	end

	if b.mod or b.mods then
		local mods = b.mods or {
			b.mod
		}

		for _, mod_name in pairs(mods) do
			local m = E:create_entity(mod_name)

			m.modifier.target_id = b.target_id
			m.modifier.source_id = b.source_id

			table.insert(mods_added, m)
			queue_insert(store, m)
		end
	end

	local fx = E:create_entity(this.transform_fx)

	fx.pos = V.v(target.pos.x + target.unit.hit_offset.x, target.pos.y + target.unit.hit_offset.y)
	fx.render.sprites[1].ts = store.tick_ts

	queue_insert(store, fx)
	U.y_wait(store, fts(4))

	this.render.sprites[1].hidden = true

	queue_remove(store, this)
end

scripts.mod_nivus_brooms_polymorph = {}

function scripts.mod_nivus_brooms_polymorph.insert(this, store)
	local target = store.entities[this.modifier.target_id]

	if target then
		this.target_ref = target

		for _, s in ipairs(target.render.sprites) do
			s.hidden = true
		end

		this.polymorph_enemy = {
			enemy = target
		}

		SU.remove_modifiers(store, target)
		SU.remove_auras(store, target)
		queue_remove(store, target)
		U.unblock_all(store, target)

		if target.ui then
			target.ui.can_click = false
		end

		target.main_script.co = nil
		target.main_script.runs = 0

		if target.count_group then
			target.count_group.in_limbo = true
		end

		target.trigger_deselect = true

		local is_flying = U.flag_has(target.vis.flags, F_FLYING)
		local broom = E:create_entity(is_flying and this.entity_t_flying or this.entity_t)

		broom.pos = target.pos
		broom.nav_path = target.nav_path
		broom.health.hp_max = target.health.hp_max * this.hp_mult
		broom.health.hp = target.health.hp * this.hp_mult

		if broom.grant_original_enemy_gold then
			broom.enemy.gold = target.enemy.gold
		end

		queue_insert(store, broom)

		this.polymorph_enemy.broom = broom

		return true
	end

	return false
end

function scripts.mod_nivus_brooms_polymorph.update(this, store, script)
	local m = this.modifier

	this.modifier.ts = store.tick_ts

	local target = this.target_ref

	this.pos = target.pos

	while true do
		if m.duration >= 0 and store.tick_ts - m.ts > m.duration then
			queue_remove(store, this)

			return
		end

		coroutine.yield()
	end
end

function scripts.mod_nivus_brooms_polymorph.remove(this, store)
	local target = this.polymorph_enemy.enemy
	local broom = this.polymorph_enemy.broom

	if broom and store.entities[broom.id] and not broom.health.dead then
		for _, s in ipairs(target.render.sprites) do
			s.hidden = false
		end

		target.main_script.runs = 1

		if target.ui then
			target.ui.can_click = true
		end

		target.pos = V.vclone(broom.pos)
		target.nav_path = broom.nav_path
		target.health.hp = target.health.hp_max * broom.health.hp / broom.health.hp_max

		queue_insert(store, target)

		broom.trigger_deselect = true

		S:queue(this.sound_transform_out)

		local sfx = E:create_entity(this.transform_fx)

		sfx.pos = V.v(target.pos.x + target.unit.hit_offset.x, target.pos.y + target.unit.hit_offset.y)
		sfx.render.sprites[1].ts = store.tick_ts
		sfx.render.sprites[1].runs = 0

		if target and sfx.render.sprites[1].size_names then
			sfx.render.sprites[1].name = sfx.render.sprites[1].size_names[target.unit.size]
		end

		queue_insert(store, sfx)
		queue_remove(store, broom)
	end

	return true
end

scripts.controller_stage_07_bushes = {}

function scripts.controller_stage_07_bushes.update(this, store)
	local bushes = {}
	local conts = {}

	for i, v in pairs(store.entities) do
		if v.template_name == this.bush_t then
			table.insert(bushes, v)

			local cont = E:create_entity(this.cont_t)

			cont.bush_ref = v

			queue_insert(store, cont)
			table.insert(conts, cont)
		end
	end

	table.sort(bushes, function(b1, b2)
		return b1.pos.x < b2.pos.x
	end)
	table.sort(conts, function(c1, c2)
		return c1.bush_ref.pos.x < c2.bush_ref.pos.x
	end)

	while true do
		if this.spawn_blades then
			conts[this.bush_id].do_spawn = true
			conts[this.bush_id].path_id = this.path_id
			conts[this.bush_id].enemies_count = this.enemies_count
			this.spawn_blades = false
		end

		coroutine.yield()
	end
end

function scripts.controller_stage_07_bushes.on_event(this, store, action, bush_id, path_id, count)
	this.spawn_blades = true
	this.bush_id = tonumber(bush_id)
	this.path_id = tonumber(path_id)
	this.enemies_count = tonumber(count)

	log.info("EVENT BUSH SPAWN. COUNT: " .. this.enemies_count)
end

scripts.controller_stage_07_bush_spawner = {}

function scripts.controller_stage_07_bush_spawner.update(this, store)
	while true do
		if this.do_spawn then
			local bush = this.bush_ref
			local start_ts = store.tick_ts

			U.animation_start(bush, "action", nil, store.tick_ts, 1)
			U.y_wait(store, fts(3))
			S:queue(this.sound_rustle)
			U.y_wait(store, fts(44))
			S:queue(this.sound_rustle)
			U.y_wait(store, fts(34))
			S:queue(this.sound_rustle)

			while not U.animation_finished(bush) do
				coroutine.yield()
			end

			U.animation_start(bush, "idle", nil, store.tick_ts, true)
			U.y_wait(store, this.spawn_delay - (store.tick_ts - start_ts))

			local nearest_nodes = P:nearest_nodes(bush.pos.x, bush.pos.y, {
				this.path_id
			}, {
				1
			})
			local pi, spi, ni = unpack(nearest_nodes[1])

			S:queue(this.sound_exit)

			for i = 1, this.enemies_count do
				local fx = E:create_entity(this.spawn_fx)

				fx.pos = V.vclone(bush.pos)
				fx.render.sprites[1].ts = store.tick_ts

				queue_insert(store, fx)

				local enemy = E:create_entity(this.enemy_t)

				enemy.nav_path.pi = this.path_id
				enemy.nav_path.ni = ni + 5
				enemy.nav_path.spi = math.random(1, 3)
				enemy.pos = V.vclone(bush.pos)
				enemy.source_id = this.id

				queue_insert(store, enemy)
				U.y_wait(store, this.delay_between)
			end

			this.do_spawn = false
		end

		coroutine.yield()
	end
end

scripts.tower_spawn_soldier_on_path = {}

function scripts.tower_spawn_soldier_on_path.can_select_point(this, x, y)
	return P:valid_node_nearby(x, y)
end

function scripts.tower_spawn_soldier_on_path.update(this, store)
	this.soldiers_alive = 0

	local function activate()
		this.soldiers_alive = km.clamp(0, this.max_soldiers, this.soldiers_alive + 1)

		S:queue(this.tower_action.sound)

		local soldier = E:create_entity(this.soldier_t)

		soldier.path_id = this.path_id
		soldier.pos = P:node_pos(this.path_id, 1, 1)
		soldier.source_id = this.id

		queue_insert(store, soldier)
		S:queue(this.tower_action.post_sound)
	end

	local function on_soldier_died()
		this.soldiers_alive = km.clamp(0, this.max_soldiers, this.soldiers_alive - 1)
	end

	this.on_soldier_died = on_soldier_died

	while true do
		this.tower_action.active = store.wave_group_number == 0 or this.soldiers_alive >= this.max_soldiers

		if this.user_selection.in_progress and not this.tower_action.active then
			this.user_selection.in_progress = nil
			this.user_selection.allowed = false
			store.player_gold = store.player_gold - this.tower_action.cost

			activate()
		end

		if this.user_selection.in_progress then
			this.user_selection.in_progress = nil
		end

		coroutine.yield()
	end
end

scripts.soldier_walk_to_objective = {}

function scripts.soldier_walk_to_objective.update(this, store)
	local brk, sta
	local path_ni = 1
	local path_spi = 1
	local target_pos = P:node_pos(this.path_id, path_spi, path_ni)

	this.vis.bans = 0

	local function do_step()
		if V.veq(this.pos, target_pos) then
			this.motion.arrived = true

			return false
		else
			U.set_destination(this, target_pos)

			if U.walk(this, store.tick_length) then
				return false
			else
				local an, af = U.animation_name_facing_point(this, "walk", this.motion.dest, 1)

				U.animation_start(this, an, af, store.tick_ts, true)

				return true
			end
		end
	end

	local function run_to_objective()
		local distSq = V.dist2(target_pos.x, target_pos.y, this.pos.x, this.pos.y)

		if distSq < this.distance_sqd then
			path_ni = path_ni + 2
			target_pos = P:node_pos(this.path_id, path_spi, path_ni)
		end

		do_step()
	end

	while true do
		if P:nodes_to_goal(this.path_id, 1, path_ni) < 3 then
			break
		end

		if this.health.dead then
			local tower = store.entities[this.source_id]

			if tower.on_soldier_died then
				tower.on_soldier_died()
			end

			SU.y_soldier_death(store, this)

			return
		end

		brk, sta = SU.y_soldier_melee_block_and_attacks(store, this)

		if brk or sta ~= A_NO_TARGET then
			if sta == A_DONE then
				local nearest = P:nearest_nodes(this.pos.x, this.pos.y, {
					this.path_id
				})
				local pi, spi, ni = unpack(nearest[1])

				path_ni = ni + 2
				target_pos = P:node_pos(this.path_id, path_spi, path_ni)
			end
		else
			run_to_objective()
		end

		coroutine.yield()
	end

	this.on_arrived(this, store)
	queue_remove(store, this)
end

scripts.soldier_stage_07_barn = {}

function scripts.soldier_stage_07_barn.on_arrived(this, store)
	local barn = find_all_t(store, "controller_stage_07_barn")[1]

	barn.soldier_arrived = true
end

scripts.controller_stage_07_barn = {}

function scripts.controller_stage_07_barn.update(this, store)
	local barn, tower
	local horse_conts = {}

	for k, v in pairs(store.entities) do
		if v.template_name == this.barn_t then
			barn = v
		end

		if v.template_name == this.tower_t then
			tower = v
		end

		if v.template_name == this.horse_controller_t then
			table.insert(horse_conts, v)
		end
	end

	for i = 1, #horse_conts do
		horse_conts[i].horse_id = i
		horse_conts[i].barn_cont = this
	end

	this.ui.can_click = false

	while true do
		if this.soldier_arrived then
			this.soldier_arrived = nil

			S:queue(this.sound_arrive)

			for i = 1, #horse_conts do
				if not horse_conts[i].horse_ready then
					horse_conts[i].soldier_arrived = true

					break
				end
			end
		end

		if this.ui.clicked then
			this.ui.clicked = nil

			for i = 1, #horse_conts do
				if horse_conts[i].horse_ready then
					S:queue(this.sound_release)

					horse_conts[i].release_horse = true
					tower.soldiers_alive = km.clamp(0, 3, tower.soldiers_alive - 1)

					signal.emit("four-horsemen-stage07")

					break
				end
			end

			coroutine.yield()

			for i = 1, #horse_conts do
				if horse_conts[i].horse_ready then
					goto label_1093_0
				end
			end

			queue_remove(store, this.bubble)

			this.bubble = nil
			this.ui.can_click = false
		end

		::label_1093_0::

		if this.ui.clicked then
			this.ui.clicked = nil
		end

		coroutine.yield()
	end
end

scripts.controller_stage_07_horse = {}

function scripts.controller_stage_07_horse.update(this, store)
	local horses = find_all_t(store, this.horse_t_prefix, true)

	table.sort(horses, function(h1, h2)
		return h1.idx < h2.idx
	end)

	local barn_c = find_all_t(store, this.barn_controller_t)[1]

	while true do
		if this.soldier_arrived then
			this.soldier_arrived = nil
			this.horse_ready = true
			horses[this.horse_id].can_do_anim = false

			U.y_animation_play(horses[this.horse_id], "action", nil, store.tick_ts, 1)
			U.animation_start(horses[this.horse_id], "idle_2", nil, store.tick_ts, true)

			if not this.barn_cont.bubble then
				this.barn_cont.bubble = E:create_entity(this.bubble_t)
				this.barn_cont.bubble.pos.x, this.barn_cont.bubble.pos.y = horses[this.horse_id].pos.x + barn_c.bubble_offset.x, horses[this.horse_id].pos.y + barn_c.bubble_offset.y
				this.barn_cont.bubble.render.sprites[1].ts = store.tick_ts

				queue_insert(store, this.barn_cont.bubble)

				this.barn_cont.ui.can_click = true
			end
		end

		if this.release_horse then
			this.release_horse = nil
			this.horse_ready = false

			U.y_animation_play(horses[this.horse_id], "out", nil, store.tick_ts, 1)

			local nearest_nodes = P:nearest_nodes(this.pos.x, this.pos.y, {
				this.knight_path
			}, {
				1
			})
			local pi, spi, ni = unpack(nearest_nodes[1])
			local knight = E:create_entity(this.knight_t)

			knight.pos = V.vclone(this.pos)
			knight.path_id = this.knight_path
			knight.node_id = ni - 5

			queue_insert(store, knight)
			U.y_animation_play(horses[this.horse_id], "in", nil, store.tick_ts, 1)
			U.animation_start(horses[this.horse_id], "idle", nil, store.tick_ts, true)

			horses[this.horse_id].can_do_anim = true
		end

		coroutine.yield()
	end
end

scripts.decal_stage_07_horse = {}

function scripts.decal_stage_07_horse.update(this, store, script)
	this.can_do_anim = true

	while true do
		if this.ui.clicked then
			this.ui.clicked = nil

			if this.can_do_anim then
				S:queue(this.tap_sfx)
				U.y_animation_play(this, "tap", nil, store.tick_ts, 1, 1)
			end
		end

		coroutine.yield()
	end
end

scripts.aura_stage_07_knight = {}

function scripts.aura_stage_07_knight.update(this, store, script)
	local first_hit_ts
	local last_hit_ts = 0
	local path_ni = this.node_id
	local path_spi = 1
	local distSq = 0
	local ps1, ps2

	last_hit_ts = store.tick_ts - this.aura.cycle_time

	if this.aura.apply_delay then
		last_hit_ts = last_hit_ts + this.aura.apply_delay
	end

	local function already_hit_enemy(enemy)
		local _, mark_mods = U.has_modifiers(store, enemy, this.aura.mod)

		if not mark_mods or #mark_mods == 0 then
			return false
		end

		for k, v in pairs(mark_mods) do
			if v.modifier.source_id == this.id then
				return true
			end
		end

		return false
	end

	local function hit_enemies()
		local targets = U.find_enemies_in_range(store.entities, this.pos, 0, this.aura.radius, this.aura.vis_flags, this.aura.vis_bans, function(v, o)
			return (not this.aura.allowed_templates or table.contains(this.aura.allowed_templates, v.template_name)) and (not this.aura.excluded_templates or not table.contains(this.aura.excluded_templates, v.template_name)) and (not this.aura.filter_source or this.aura.source_id ~= v.id) and not already_hit_enemy(v)
		end)

		if targets then
			for i, target in pairs(targets) do
				if target and not target.health.dead and target.enemy then
					queue_damage(store, SU.create_attack_damage(this, target.id, this.id))

					local hit_fx = E:create_entity(this.hit_fx)

					hit_fx.pos = V.vclone(target.pos)
					hit_fx.pos.x, hit_fx.pos.y = hit_fx.pos.x + target.unit.hit_offset.x, hit_fx.pos.y + target.unit.hit_offset.y
					hit_fx.render.sprites[1].ts = store.tick_ts

					queue_insert(store, hit_fx)

					local new_mod = E:create_entity(this.aura.mod)

					new_mod.modifier.target_id = target.id
					new_mod.modifier.source_id = this.id

					queue_insert(store, new_mod)
				end
			end

			if #targets > 0 then
				S:queue(this.sound_hit)
			end
		end
	end

	local target_pos = P:node_pos(this.path_id, path_spi, path_ni)

	local function go_back_step()
		if V.veq(this.pos, target_pos) then
			this.motion.arrived = true

			return false
		else
			U.set_destination(this, target_pos)

			if U.walk(this, store.tick_length) then
				return false
			else
				U.animation_start(this, "run", nil, store.tick_ts, true)

				return true
			end
		end
	end

	local function run_backwards()
		local last_pos = this.pos

		distSq = V.dist2(target_pos.x, target_pos.y, this.pos.x, this.pos.y)

		if distSq < 25 then
			path_ni = path_ni - 3
			target_pos = P:node_pos(this.path_id, path_spi, path_ni)
		end

		go_back_step()
	end

	local start_ts = store.tick_ts

	while true do
		if this.interrupt then
			last_hit_ts = 1e+99
		end

		if path_ni <= 10 and ps1.particle_system.emit then
			ps1.particle_system.emit = false
			ps2.particle_system.emit = false
		end

		if path_ni <= 3 then
			break
		end

		if store.tick_ts - start_ts > 0.5 and not ps1 then
			if this.particles_name_1 then
				ps1 = E:create_entity(this.particles_name_1)
				ps1.particle_system.emit = true
				ps1.particle_system.track_id = this.id

				queue_insert(store, ps1)
			end

			if this.particles_name_2 then
				ps2 = E:create_entity(this.particles_name_2)
				ps2.particle_system.emit = true
				ps2.particle_system.track_id = this.id

				queue_insert(store, ps2)
			end
		end

		if store.tick_ts - last_hit_ts >= this.aura.cycle_time then
			if this.aura.apply_duration and first_hit_ts and store.tick_ts - first_hit_ts > this.aura.apply_duration then
				goto label_1097_0
			end

			first_hit_ts = first_hit_ts or store.tick_ts
			last_hit_ts = store.tick_ts

			hit_enemies()
		end

		run_backwards()

		::label_1097_0::

		coroutine.yield()
	end

	if ps1 and ps1.particle_system.emit then
		ps1.particle_system.emit = false
		ps2.particle_system.emit = false

		U.y_wait(store, ps1.particle_system.particle_lifetime[2])
	end

	queue_remove(store, this)
end

scripts.decal_stage_07_bonfire = {}

function scripts.decal_stage_07_bonfire.update(this, store, script)
	while true do
		if this.ui.clicked then
			this.ui.clicked = nil
			this.ui.can_click = false

			S:queue(this.sound_extinguish)
			U.y_animation_play(this, "action", nil, store.tick_ts, 1)
			U.animation_start(this, "idle_ashes", nil, store.tick_ts, true)

			break
		end

		coroutine.yield()
	end

	while true do
		coroutine.yield()
	end

	queue_remove(store, this)
end

scripts.controller_stage_08_phases = {}

function scripts.controller_stage_08_phases.link_entities(this, store)
	this.wall_1_masks = {}
	this.wall_2_masks = {}
	this.no_walls_masks = {}
	this.city_masks = {}
	this.holders_phase_1 = {}
	this.holders_phase_2 = {}
	this.holders_phase_3 = {}
	this.flags_phase_1 = {}
	this.flags_phase_2 = {}
	this.flags_phase_3 = {}
	this.defend_points_per_phase = {
		{},
		{},
		{}
	}
	this.archers_wall_1 = {}
	this.archers_wall_2 = {}
	this.archers_auras = {}

	for k, v in pairs(store.entities) do
		if v.template_name == this.wall_1_t then
			this.wall_1 = v
		end

		if v.template_name == this.wall_2_t then
			this.wall_2 = v
		end

		if v.template_name == this.wall_2_broken_t then
			this.wall_2_broken = v
		end

		if v.template_name == this.no_walls_t then
			this.no_walls = v
		end

		if table.contains(this.wall_1_masks_t, v.template_name) then
			table.insert(this.wall_1_masks, v)
		end

		if table.contains(this.wall_2_masks_t, v.template_name) then
			table.insert(this.wall_2_masks, v)
		end

		if table.contains(this.no_walls_masks_t, v.template_name) then
			table.insert(this.no_walls_masks, v)
		end

		if table.contains(this.city_masks_t, v.template_name) then
			table.insert(this.city_masks, v)
		end

		if v.tower_holder then
			if v.pos.x < this.holders_limits_x[1] then
				table.insert(this.holders_phase_1, v)
			elseif v.pos.x < this.holders_limits_x[2] then
				table.insert(this.holders_phase_2, v)
			else
				table.insert(this.holders_phase_3, v)
			end
		end

		if v.template_name == "decal_defense_flag5" or v.template_name == "decal_defend_point5" then
			if v.pos.x < this.flags_limits_x[1] then
				table.insert(this.flags_phase_1, v)
			elseif v.pos.x < this.flags_limits_x[2] then
				table.insert(this.flags_phase_2, v)
			else
				table.insert(this.flags_phase_3, v)
			end
		end

		if v.template_name == "decal_defend_point5" then
			local phase = v.pos.x < this.flags_limits_x[1] and 1 or v.pos.x < this.flags_limits_x[2] and 2 or 3

			table.insert(this.defend_points_per_phase[phase], v)
		end

		if v.template_name == this.templar_archers_t then
			if v.editor and v.editor.wall_id == 1 then
				table.insert(this.archers_wall_1, v)

				if v.nav_rally.pos.y > 500 then
					v.pos.x = v.nav_rally.pos.x - (v.pos.x - v.nav_rally.pos.x)
					v.pos.y = v.nav_rally.pos.y - (v.pos.y - v.nav_rally.pos.y)
				end

				v.motion.max_speed = 0
			else
				table.insert(this.archers_wall_2, v)

				if v.editor and v.editor.balcony == 1 then
					v.pos.x, v.pos.y = v.nav_rally.pos.x, v.nav_rally.pos.y
					v.render.sprites[1].z = Z_OBJECTS_COVERS + 2
				end
			end
		end

		if v.template_name == this.archers_aura_t then
			table.insert(this.archers_auras, v)
		end

		if v.template_name == this.catapult_t then
			this.catapult = v
		end
	end
end

function scripts.controller_stage_08_phases.register_defend_points(this, store)
	for phase, decals in ipairs(this.defend_points_per_phase) do
		for _, d in pairs(decals) do
			for _, item in pairs(P:nearest_nodes(d.pos.x, d.pos.y, this.paths_per_phase[phase])) do
				local pi, spi, ni, dist = unpack(item, 1, 4)

				if dist < P:path_width(pi) / 2 then
					P:set_defend_point_node(pi, ni)
				end
			end
		end
	end
end

function scripts.controller_stage_08_phases.refresh_phase_elements(this, store)
	this.wall_1.render.sprites[1].hidden = this.current_phase > 1
	this.wall_2.render.sprites[1].hidden = this.current_phase > 2
	this.wall_2_broken.render.sprites[1].hidden = this.current_phase ~= 2
	this.no_walls.render.sprites[1].hidden = this.current_phase < 3
	this.catapult.render.sprites[1].hidden = this.current_phase > 2
	this.catapult.attacks.list[1].disabled = this.current_phase ~= 2

	for k, v in pairs(this.wall_1_masks) do
		v.render.sprites[1].hidden = this.current_phase ~= 1
	end

	for k, v in pairs(this.wall_2_masks) do
		v.render.sprites[1].hidden = this.current_phase ~= 2
	end

	for k, v in pairs(this.no_walls_masks) do
		v.render.sprites[1].hidden = this.current_phase < 3
	end

	for k, v in pairs(this.city_masks) do
		v.render.sprites[1].hidden = this.current_phase ~= 1
	end

	this.city_masks[2].tween.ts = store.tick_ts
	this.city_masks[2].tween.disabled = false

	for k, v in pairs(this.holders_phase_2) do
		v.render.sprites[1].hidden = this.current_phase < 2
		v.ui.can_click = this.current_phase >= 2
		v.tower.can_hover = this.current_phase >= 2
	end

	for k, v in pairs(this.holders_phase_3) do
		v.render.sprites[1].hidden = this.current_phase < 3
		v.ui.can_click = this.current_phase == 3
		v.tower.can_hover = this.current_phase == 3
	end

	for k, v in pairs(this.flags_phase_1) do
		v.render.sprites[1].hidden = this.current_phase > 1
	end

	for k, v in pairs(this.flags_phase_2) do
		v.render.sprites[1].hidden = this.current_phase ~= 2
	end

	for k, v in pairs(this.flags_phase_3) do
		v.render.sprites[1].hidden = this.current_phase ~= 3
	end

	for k, v in pairs(this.archers_wall_1) do
		v.render.sprites[1].hidden = this.current_phase ~= 1
		v.ranged.attacks[1].disabled = this.current_phase ~= 1
		v.motion.max_speed = this.current_phase ~= 1 and 0 or 75
	end

	for k, v in pairs(this.archers_wall_2) do
		v.render.sprites[1].hidden = true
		v.ranged.attacks[1].disabled = this.current_phase ~= 2
		v.motion.max_speed = this.current_phase ~= 2 and 0 or 75
	end

	for k, v in pairs(this.archers_auras) do
		v.enabled = this.current_phase == 2
	end
end

function scripts.controller_stage_08_phases.patch_nav_mesh(this, store, phase)
	for h_id, dirs in pairs(this.nav_mesh_patches[phase]) do
		for dir, target_id in pairs(dirs) do
			store.level.nav_mesh[h_id][dir] = target_id
		end
	end
end

function scripts.controller_stage_08_phases.restore_nav_mesh(this, store)
	local nav_mesh = store.level.nav_mesh
	local original = store.level._stage_08_nav_mesh_original

	if not original then
		original = {}

		for _, patch in pairs(this.nav_mesh_patches) do
			for h_id, dirs in pairs(patch) do
				original[h_id] = original[h_id] or {}

				for dir in pairs(dirs) do
					original[h_id][dir] = nav_mesh[h_id][dir] or false
				end
			end
		end

		store.level._stage_08_nav_mesh_original = original
	end

	for h_id, dirs in pairs(original) do
		for dir, target_id in pairs(dirs) do
			nav_mesh[h_id][dir] = target_id or nil
		end
	end
end

function scripts.controller_stage_08_phases.update_editor(this, store)
	this.current_phase = this.editor.phase

	scripts.controller_stage_08_phases.link_entities(this, store)
	scripts.controller_stage_08_phases.register_defend_points(this, store)

	while true do
		this.current_phase = this.editor.phase
		this.wall_1.render.sprites[1].name = this.current_phase == 0 and "startidle" or "idle"

		scripts.controller_stage_08_phases.refresh_phase_elements(this, store)
		coroutine.yield()
	end

	return true
end

function scripts.controller_stage_08_phases.update(this, store, script)
	this.current_phase = ((store.level_mode_6 or store.level_mode) == GAME_MODE_IRON or (store.level_mode_6 or store.level_mode) == GAME_MODE_EXTRA_HEROES or (store.level_mode_6 or store.level_mode) == GAME_MODE_BLITZ or (store.level_mode_6 or store.level_mode) == GAME_MODE_NO_HEROES) and 3 or this.current_phase

	scripts.controller_stage_08_phases.link_entities(this, store)
	scripts.controller_stage_08_phases.register_defend_points(this, store)
	scripts.controller_stage_08_phases.restore_nav_mesh(this, store)

	this.wall_1.render.sprites[1].name = this.current_phase == 0 and "startidle" or "idle"

	scripts.controller_stage_08_phases.refresh_phase_elements(this, store)

	for i = 2, 3 do
		for k, v in pairs(this.paths_per_phase[i]) do
			P:deactivate_path(v)
		end
	end

	while this.current_phase == 0 do
		coroutine.yield()
	end

	local enemies, shake, barrage

	if this.restarted then
		-- block empty
	else
		if this.current_phase >= 2 then
			goto label_1110_0
		end

		barrage = E:create_entity(this.barrage_1_t)
		barrage.pos = V.v(512, 384)
		barrage.render.sprites[1].ts = store.tick_ts

		queue_insert(store, barrage)

		if this.sound_barrage_1 then
			S:queue(this.sound_barrage_1)
		end

		U.animation_start(this.wall_1, "start", nil, store.tick_ts, false)
		U.y_wait(store, fts(8))

		shake = E:create_entity("aura_screen_shake")
		shake.aura.amplitude = 0.5
		shake.aura.duration = 1
		shake.aura.freq_factor = 3

		queue_insert(store, shake)
		U.y_wait(store, fts(16))

		shake = E:create_entity("aura_screen_shake")
		shake.aura.amplitude = 0.5
		shake.aura.duration = 1
		shake.aura.freq_factor = 3

		queue_insert(store, shake)
		U.y_wait(store, fts(16))
		scripts.controller_stage_08_phases.refresh_phase_elements(this, store)
		U.y_animation_wait(this.wall_1)
		U.animation_start(this.wall_1, "idle", nil, store.tick_ts, true)
		queue_remove(store, barrage)
	end

	if this.restarted then
		scripts.controller_stage_08_phases.refresh_phase_elements(this, store)
		U.animation_start(this.wall_1, "idle", nil, store.tick_ts, true)
	end

	while this.current_phase == 1 do
		coroutine.yield()
	end

	enemies = U.find_enemies_in_range(store.entities, this.pos, 0, 1e+99, 0, 0)

	if enemies then
		for k, v in pairs(enemies) do
			v.nav_path.pi = v.nav_path.pi == 1 and 3 or 4

			local nearest_nodes = P:nearest_nodes(this.pos.x, this.pos.y, {
				v.nav_path.pi
			})
			local pi, spi, ni = unpack(nearest_nodes[1])

			v.nav_path.spi = spi
			v.nav_path.ni = ni

			local next, new = P:next_entity_node(v, store.tick_length)

			U.set_destination(v, next)
		end
	end

	U.y_wait(store, 1.2)

	barrage = E:create_entity(this.barrage_2_t)
	barrage.pos = V.v(512, 384)
	barrage.render.sprites[1].ts = store.tick_ts

	queue_insert(store, barrage)

	if this.sound_barrage_2 then
		S:queue(this.sound_barrage_2)
	end

	U.y_wait(store, fts(10))

	shake = E:create_entity("aura_screen_shake")
	shake.aura.amplitude = 1
	shake.aura.duration = 2
	shake.aura.freq_factor = 3

	queue_insert(store, shake)
	U.y_wait(store, fts(30))

	::label_1110_0::

	scripts.controller_stage_08_phases.refresh_phase_elements(this, store)
	scripts.controller_stage_08_phases.patch_nav_mesh(this, store, 2)

	for k, v in pairs(this.paths_per_phase[1]) do
		P:deactivate_path(v)
	end

	for k, v in pairs(this.paths_per_phase[2]) do
		P:activate_path(v)
	end

	for k, v in pairs(this.archers_wall_1) do
		queue_remove(store, v)
	end

	if barrage then
		U.y_animation_wait(barrage)
		queue_remove(store, barrage)
	end

	while this.current_phase == 2 do
		coroutine.yield()
	end

	local enemies = table.filter(store.entities, function(k, v)
		if not v.enemy or not v.nav_path or v.pending_removal or not v.health or not not v.health.dead then
			return false
		end

		return v.template_name ~= "enemy_boss_stage_08"
	end)

	for k, v in pairs(this.paths_per_phase[2]) do
		P:deactivate_path(v)
	end

	for k, v in pairs(this.paths_per_phase[3]) do
		P:activate_path(v)
	end

	local keys = get_keys(this.path_change_map)

	if enemies then
		for k, v in pairs(enemies) do
			if P:nodes_to_goal(v.nav_path) < 52 then
				local d = E:create_entity("damage")

				d.source_id = this.id
				d.target_id = v.id
				d.damage_type = DAMAGE_TRUE
				d.value = 1e+99

				queue_damage(store, d)
			else
				local path_to_change_to = this.path_change_map[v.nav_path.pi]

				if path_to_change_to then
					v.nav_path.pi = path_to_change_to

					local nearest_nodes = P:nearest_nodes(v.pos.x, v.pos.y, {
						v.nav_path.pi
					}, {
						v.nav_path.spi
					}, true)
					local pi, spi, ni = unpack(nearest_nodes[1])

					v.nav_path.spi = spi
					v.nav_path.ni = ni

					local next, new = P:next_entity_node(v, store.tick_length)

					U.set_destination(v, next)
				end
			end
		end
	end

	local fixer = E:create_entity(this.path_fixer_t)

	queue_insert(store, fixer)
	scripts.controller_stage_08_phases.refresh_phase_elements(this, store)
	scripts.controller_stage_08_phases.patch_nav_mesh(this, store, 3)
	queue_remove(store, this.catapult)

	for k, v in pairs(this.archers_wall_2) do
		queue_remove(store, v)
	end

	queue_remove(store, this)
end

scripts.controller_stage_08_path_fixer = {}

function scripts.controller_stage_08_path_fixer.update(this, store)
	local run_ts = store.tick_ts - 3

	while true do
		if store.tick_ts - run_ts > 3 then
			local keys = get_keys(this.path_change_map)
			local enemies = table.filter(store.entities, function(k, v)
				if not v.enemy or not v.nav_path or v.pending_removal or not v.health or not not v.health.dead then
					return false
				end

				for i = 1, #keys do
					if keys[i] == v.nav_path.pi then
						return true
					end
				end

				return false
			end)

			if enemies then
				for k, v in pairs(enemies) do
					v.nav_path.pi = this.path_change_map[v.nav_path.pi]

					local nearest_nodes = P:nearest_nodes(v.pos.x, v.pos.y, {
						v.nav_path.pi
					}, {
						v.nav_path.spi
					}, true)
					local pi, spi, ni = unpack(nearest_nodes[1])

					v.nav_path.spi = spi
					v.nav_path.ni = ni

					local next, new = P:next_entity_node(v, store.tick_length)

					U.set_destination(v, next)
				end
			end

			run_ts = store.tick_ts
		end

		coroutine.yield()
	end
end

scripts.soldier_stage_08_templar_archer = {}

function scripts.soldier_stage_08_templar_archer.insert(this, store)
	this.nav_rally.new = true
	this.nav_rally.pos = V.vclone(this.pos)
	this.nav_rally.center = V.vclone(this.pos)
	this.motion.arrived = false

	if this.editor.wall_id == 1 then
		this.pos.x, this.pos.y = this.pos.x + 280, this.pos.y - 448
	else
		this.pos.x, this.pos.y = this.pos.x + 140, this.pos.y - 224
	end

	return scripts.soldier_barrack.insert(this, store)
end

function scripts.soldier_stage_08_templar_archer.ranged_attack_filter_fn(entity, origin)
	if not entity or not entity.nav_path then
		return false
	end

	return P:is_node_valid(entity.nav_path.pi, entity.nav_path.ni, NF_RANGE)
end

function scripts.soldier_stage_08_templar_archer.update(this, store)
	while this.nav_rally.new do
		SU.y_soldier_new_rally(store, this)
	end

	U.animation_start(this, "idle", true, store.tick_ts, true)

	return scripts.soldier_barrack.update(this, store)
end

scripts.aura_stage_08_archers_visibility = {}

function scripts.aura_stage_08_archers_visibility.update(this, store, script)
	local last_ts = 0
	local controller_phases

	for k, v in pairs(store.entities) do
		if v.template_name == "controller_stage_08_phases" then
			controller_phases = v
		end
	end

	while true do
		if this.enabled and store.tick_ts - last_ts >= this.aura.cycle_time then
			last_ts = store.tick_ts

			for k, v in pairs(store.entities) do
				if v.template_name == "soldier_stage_08_templar_archer" and V.dist2(v.pos.x, v.pos.y, this.pos.x, this.pos.y) < this.aura.radius * this.aura.radius then
					v.render.sprites[1].hidden = false
				end
			end
		end

		coroutine.yield()
	end

	queue_remove(store, this)
end

scripts.tower_stage_08_catapult = {}

function scripts.tower_stage_08_catapult.can_select_point(this, x, y)
	return P:valid_node_nearby(x, y)
end

function scripts.tower_stage_08_catapult.update(this, store)
	local ab = this.attacks.list[1]
	local bubble_ts = store.tick_ts
	local tap_bubble_cd = 4

	U.animation_start(this, "idle", false, store.tick_ts, true)

	this.bubble = E:create_entity(this.bubble_t)
	this.bubble.pos = V.vclone(this.pos)
	this.bubble.render.sprites[1].alpha = 0

	queue_insert(store, this.bubble)

	while true do
		if store.wave_group_number > 0 and tap_bubble_cd < store.tick_ts - bubble_ts and this.bubble.render.sprites[1].alpha <= 0 then
			this.bubble.render.sprites[1].ts = store.tick_ts
			this.bubble.tween.ts = store.tick_ts
			this.bubble.tween.reverse = false
			this.bubble.tween.disabled = false
			bubble_ts = store.tick_ts
		end

		if not this.bubble.tween.reverse and (this.user_selection.menu_shown or this.bubble.render.sprites[1].alpha > 0 and store.tick_ts - bubble_ts > 5) then
			this.bubble.tween.ts = store.tick_ts
			this.bubble.tween.reverse = true
			bubble_ts = store.tick_ts
			tap_bubble_cd = this.user_selection.menu_shown and 20 or 6
		end

		if this.user_selection.new_pos then
			store.player_gold = store.player_gold - ab.price

			local pos = this.user_selection.new_pos
			local nearest = P:nearest_nodes(pos.x, pos.y, nil, {
				1
			}, true)[1]
			local pi, spi, ni = unpack(nearest)

			pos = P:node_pos(pi, spi, ni)
			this.user_selection.new_pos = nil
			ab.ts = store.tick_ts

			local time_passed = store.tick_ts
			local d = E:create_entity(ab.decal)

			d.pos.x, d.pos.y = pos.x, pos.y
			d.render.sprites[1].ts = store.tick_ts

			queue_insert(store, d)

			if ab.sound_load then
				S:queue(ab.sound_load)
			end

			U.animation_start(this, "load", nil, store.tick_ts, 1)

			local ts = store.tick_ts
			local p = false

			while not U.animation_finished(this, 1) do
				if store.tick_ts - ts > this.sound_shoot_time and ab.sound_shoot and not p then
					p = true

					S:queue(ab.sound_shoot)
				end

				coroutine.yield()
			end

			U.animation_start(this, ab.animation, nil, store.tick_ts, false)
			U.y_wait(store, ab.shoot_time)

			time_passed = store.tick_ts - time_passed

			local b = E:create_entity(ab.bullet)

			b.pos.x, b.pos.y = this.pos.x + ab.bullet_start_offset.x, this.pos.y + ab.bullet_start_offset.y
			b.bullet.from = V.vclone(b.pos)
			b.bullet.to = V.vclone(pos)
			b.bullet.source_id = this.id

			queue_insert(store, b)

			d.timed.duration = time_passed + b.bullet.flight_time

			U.y_animation_wait(this)
			U.animation_start(this, "idle", false, store.tick_ts, true)
		end

		coroutine.yield()
	end
end

function scripts.tower_stage_08_catapult.remove(this, store)
	queue_remove(store, this.bubble)

	return true
end

scripts.controller_stage_08_citizens = {}

function scripts.controller_stage_08_citizens.update(this, store)
	local citizens

	for k, v in pairs(store.entities) do
		if v.template_name == this.citizens_t then
			citizens = v

			break
		end
	end

	while not this.trigger_run do
		coroutine.yield()
	end

	if this.restarted then
		-- block empty
	else
		U.y_animation_play(citizens, "run", nil, store.tick_ts, 1)
	end

	U.y_animation_play(citizens, "loop", nil, store.tick_ts, 3)
	U.y_animation_play(citizens, "end", nil, store.tick_ts, 1)
end

