scripts.decal_stage_08_goblin_catapult = {}

function scripts.decal_stage_08_goblin_catapult.update(this, store)
	local tap_count = 0
	local start_pos = V.vclone(this.pos)

	U.set_destination(this, this.stop_pos)

	this.motion.arrived = false

	local ps1 = E:create_entity(this.particles_name[1])

	ps1.particle_system.emit = true
	ps1.particle_system.track_id = this.id

	queue_insert(store, ps1)

	local ps2 = E:create_entity(this.particles_name[2])

	ps2.particle_system.emit = true
	ps2.particle_system.track_id = this.id

	queue_insert(store, ps2)

	while not U.walk(this, store.tick_length) do
		if this.ui.clicked then
			this.ui.clicked = false
			tap_count = tap_count + 1

			S:queue(this.sound_tap)

			local fx = E:create_entity(this.tap_fx_t)

			fx.pos.x = this.pos.x + 10 + math.random(-20, 20)
			fx.pos.y = this.pos.y + 20 + math.random(-20, 20)
			fx.render.sprites[1].ts = store.tick_ts

			queue_insert(store, fx)

			if tap_count >= this.taps_to_explode then
				ps1.particle_system.emit = false
				ps2.particle_system.emit = false

				S:queue(this.sound_death)
				U.y_animation_play(this, "death", nil, store.tick_ts, 1)

				goto label_1132_0
			end
		end

		coroutine.yield()
	end

	this.motion.arrived = true
	ps1.particle_system.emit = false
	ps2.particle_system.emit = false

	U.y_animation_play(this, "in", nil, store.tick_ts, 1)
	U.animation_start(this, "idle", nil, store.tick_ts, true)
	U.y_wait(store, this.delay_before_hit)
	U.animation_start(this, "attack", nil, store.tick_ts, false)
	U.y_wait(store, this.hit_time)

	do
		local so = this.bullet_spawn_offset
		local nearest = P:nearest_nodes(this.pos.x, this.pos.y, nil, nil, true)
		local pi, _, ni = unpack(nearest[1])
		local spi = 1

		if this.sound_fire then
			S:queue(this.sound_fire)
		end

		for i = 1, this.spawn_count do
			local b = E:create_entity(this.bullet_t)

			b.pos.x, b.pos.y = this.pos.x + so.x, this.pos.y + so.y
			b.bullet.from = V.vclone(b.pos)
			b.bullet.to = P:node_pos(pi, spi, ni + this.nodes_ahead + i * 2)
			b.bullet.source_id = this.id
			b.path_to_spawn = pi
			b.bullet.flight_time = b.bullet.flight_time + fts(math.random(-5, 5)) + fts(5)
			b.bullet.rotation_speed = b.bullet.rotation_speed + math.random(-5, 5)

			queue_insert(store, b)

			spi = spi + 1

			if spi > 3 then
				spi = 1
			end
		end
	end

	U.y_animation_wait(this)
	U.animation_start(this, "idle_2", nil, store.tick_ts, true)

	if this.sound_out then
		S:queue(this.sound_out)
	end

	U.y_animation_play(this, "out", nil, store.tick_ts, 1)
	U.animation_start(this, "walk_left", nil, store.tick_ts, true)
	U.set_destination(this, start_pos)

	ps1.particle_system.emit = true
	ps1.particle_system.emit_offset.x = -ps1.particle_system.emit_offset.x
	ps2.particle_system.emit = true
	ps2.particle_system.emit_offset.x = -ps2.particle_system.emit_offset.x
	this.motion.arrived = false

	while not U.walk(this, store.tick_length) do
		if this.ui.clicked then
			this.ui.clicked = false
			tap_count = tap_count + 1

			S:queue(this.sound_tap)

			local fx = E:create_entity(this.tap_fx_t)

			fx.pos.x = this.pos.x + 10 + math.random(-20, 20)
			fx.pos.y = this.pos.y + 20 + math.random(-20, 20)
			fx.render.sprites[1].ts = store.tick_ts

			queue_insert(store, fx)

			if tap_count >= this.taps_to_explode then
				ps1.particle_system.emit = false
				ps2.particle_system.emit = false

				U.y_animation_play(this, "death", true, store.tick_ts, 1)

				break
			end
		end

		coroutine.yield()
	end

	::label_1132_0::

	ps1.particle_system.emit = false
	ps2.particle_system.emit = false

	U.y_wait(store, ps2.particle_system.particle_lifetime[2])
	queue_remove(store, ps1)
	queue_remove(store, ps2)
	queue_remove(store, this)
end

scripts.enemy_boss_stage_08 = {}

function scripts.enemy_boss_stage_08.update(this, store, script)
	local spawn_ts = store.tick_ts
	local aa = this.melee.attacks[1]
	local as = this.timed_attacks.list[1]
	local path_controller = E:create_entity("controller_stage_08_boss_path")

	path_controller.boss_ref = this

	queue_insert(store, path_controller)

	local sound_controller = E:create_entity(this.sound_steps_t)

	sound_controller.source_id = this.id

	queue_insert(store, sound_controller)

	local old_bans = this.vis.bans

	local function walk_cart_break_fn(store, this)
		local nodes_to_end = P:nodes_to_goal(this.nav_path.pi, this.nav_path.spi, this.nav_path.ni)

		if this.enraged then
			return nodes_to_end < 75
		else
			return this.health.hp < this.health.hp_max * this.rage_hp or nodes_to_end < this.nodes_to_enrage
		end
	end

	local function walk_break_fn(store, this)
		if as.disabled or store.tick_ts - as.ts < as.cooldown then
			return false
		end

		local targets = U.find_enemies_in_range(store.entities, this.pos, 0, as.range, as.vis_flags, as.vis_bans)

		if targets and #targets >= as.min_targets then
			return true
		else
			as.ts = store.tick_ts - as.cooldown + fts(30)

			return false
		end
	end

	local function kill_all_special_enemies()
		local riders = find_all_t(store, "enemy_rider_goblin")

		for i, v in ipairs(riders) do
			riders[i].forced_death = true
		end

		local clouds = find_all_t(store, "enemy_stage_08_cloud_of_crows")

		for i, v in ipairs(clouds) do
			clouds[i].spawn_count = 0
		end

		local catapults = find_all_t(store, "decal_stage_08_goblin_catapult")

		for i, v in ipairs(catapults) do
			catapults[i].taps_to_explode = 0
			catapults[i].spawn_count = 0
			catapults[i].ui.clicked = true
		end
	end

	local function y_on_death()
		kill_all_special_enemies()
		LU.kill_all_enemies(store, true)
		S:stop_all()
		W:stop_manual_wave("BOSS1")
		S:queue(this.sound_death)
		U.animation_start(this, "death", nil, store.tick_ts, false)
		U.y_wait(store, fts(26))

		local shake = E:create_entity("aura_screen_shake")

		shake.aura.amplitude = 0.5
		shake.aura.duration = 0.5
		shake.aura.freq_factor = 1

		queue_insert(store, shake)
		U.y_animation_wait(this)
		signal.emit("boss-killed", this)

		this.bossfight_ended = true
	end

	U.animation_start(this, "walk", nil, store.tick_ts, true)

	while true do
		if this.health.dead then
			y_on_death()

			return
		end

		if this.unit.is_stunned then
			SU.y_enemy_stun(store, this)
		elseif this.is_pushing_cart then
			local cont, blocker, ranged = SU.y_enemy_walk_until_blocked(store, this, true, walk_cart_break_fn)

			if not cont then
				if this.enraged then
					this.triggered_explosion = true
					this.trigger_deselect = true
					this.vis.bans = F_ALL

					S:queue(this.sound_explosion)

					local explosion = E:create_entity(this.explosion_fx)

					explosion.pos = V.v(512, 384)
					explosion.render.sprites[1].ts = store.tick_ts

					queue_insert(store, explosion)

					local shake = E:create_entity("aura_screen_shake")

					shake.aura.amplitude = 1
					shake.aura.duration = 2
					shake.aura.freq_factor = 3

					queue_insert(store, shake)

					this.render.sprites[1].hidden = true
					this.health_bar.hidden = true

					local b = E:create_entity(this.fly_bullet)

					b.pos.x, b.pos.y = this.pos.x, this.pos.y + 50
					b.bullet.from = V.vclone(b.pos)
					b.bullet.to = P:node_pos(this.nav_path.pi, 1, this.nav_path.ni - this.nodes_knockback)
					b.bullet.source_id = this.id

					queue_insert(store, b)
					U.y_wait(store, b.bullet.flight_time)

					this.pos = V.vclone(b.bullet.to)
					this.nav_path.spi = 1
					this.nav_path.ni = this.nav_path.ni - this.nodes_knockback
					b.render.sprites[1].hidden = true
					this.render.sprites[1].hidden = false
					this.render.sprites[1].prefix = "boss_stage_08Def"
					this.health_bar.offset.x = 0
					this.health_bar.offset.y = 130
					this.unit.hit_offset.x = 0
					this.unit.marker_offset.x = 0
					this.unit.mod_offset.x = 0
					this.motion.max_speed = this.normal_speed
					this.render.sprites[1].angles.walk = {
						"walk",
						"walk",
						"walk"
					}
					this.ui.click_rect = r(-60, 0, 120, 100)
					aa.disabled = false
					as.disabled = false
					as.ts = store.tick_ts

					U.y_animation_play(this, "land", nil, store.tick_ts, 1)
					U.animation_start(this, "land_idle", nil, store.tick_ts, true)
					U.y_wait(store, 1)

					local shake = E:create_entity("aura_screen_shake")

					shake.aura.amplitude = 1
					shake.aura.duration = 1
					shake.aura.freq_factor = 3

					queue_insert(store, shake)
					U.y_wait(store, 1)
					U.y_animation_play(this, "land_get_up", nil, store.tick_ts, 1)

					this.health.ignore_damage = false
					this.vis.bans = band(old_bans, bnot(F_BLOCK))
					this.is_pushing_cart = false
					this.trigger_deselect = nil

					if this.health.hp < this.health.hp_max then
						this.health_bar.hidden = false
					end

					W:start_manual_wave("BOSS1")
					signal.emit("boss_fight_start", this)
				else
					this.enraged = true
					this.motion.max_speed = this.speed_cart_rage

					S:queue(this.sound_angry)

					old_bans = this.vis.bans
					this.vis.bans = F_ALL
					this.health.ignore_damage = true

					U.y_animation_play(this, "angry", nil, store.tick_ts, 1)

					this.render.sprites[1].angles.walk = {
						"rush",
						"rush",
						"rush"
					}
				end
			end
		else
			local cont, blocker, ranged = SU.y_enemy_walk_until_blocked(store, this, false, walk_break_fn)

			if not cont then
				if store.tick_ts - as.ts > as.cooldown then
					U.animation_start(this, as.animation, nil, store.tick_ts, false)
					U.y_wait(store, as.cast_time)

					as.ts = store.tick_ts

					for k, v in pairs(as.auras) do
						local aura = E:create_entity(v)

						aura.aura.source_id = this.id
						aura.aura.ts = store.tick_ts
						aura.pos = V.vclone(this.pos)

						queue_insert(store, aura)
					end

					U.y_animation_wait(this)
				end
			elseif not blocker or not SU.y_wait_for_blocker(store, this, blocker) then
				-- block empty
			else
				while SU.can_melee_blocker(store, this, blocker) do
					if not SU.y_enemy_melee_attacks(store, this, blocker) then
						break
					end

					coroutine.yield()
				end
			end
		end

		coroutine.yield()
	end
end

scripts.controller_stage_08_boss_sound_steps = {}

function scripts.controller_stage_08_boss_sound_steps.update(this, store, script)
	local boss = store.entities[this.source_id]

	while true do
		if not boss or boss.health.dead then
			queue_remove(store, this)
		end

		local do_sound = false
		local boss_prefix = boss.render.sprites[1].prefix

		if this.frames_to_do_sound[boss_prefix] then
			for anim, frames in pairs(this.frames_to_do_sound[boss_prefix]) do
				for i, f in ipairs(frames) do
					local formatted_frame_name = string.format("%s_%s_%04i", boss_prefix, anim, f)

					if boss.render.sprites[1].frame_name == formatted_frame_name then
						S:queue(this.sound)
					end
				end
			end
		end

		coroutine.yield()
	end
end

scripts.controller_stage_08_boss_path = {}

function scripts.controller_stage_08_boss_path.update(this, store, script)
	local current_section = 0
	local decals = {}
	local current_invalid_range_ni = 1
	local ts = store.tick_ts

	while not this.boss_ref.triggered_explosion do
		if this.boss_ref.pos.x > current_section * this.sections_width + this.start_offset then
			local decal = E:create_entity(this.sections_decals_t)

			decal.pos = V.v(512, 384)
			decal.render.sprites[1].name = this.sections_decals_prefix .. current_section

			queue_insert(store, decal)
			table.insert(decals, decal)

			current_section = current_section + 1
		end

		if store.tick_ts - ts > this.boss_ref.loop_walk_every then
			ts = store.tick_ts

			S:queue(this.boss_ref.sound_walk_loop)
		end

		if current_invalid_range_ni < this.boss_ref.nav_path.ni + 6 then
			P:remove_invalid_range(6, current_invalid_range_ni)
			P:add_invalid_range(6, this.boss_ref.nav_path.ni + 6)

			current_invalid_range_ni = this.boss_ref.nav_path.ni + 6
		end

		coroutine.yield()
	end

	P:remove_invalid_range(6, current_invalid_range_ni)

	for i = current_section, 9 do
		local decal = E:create_entity(this.sections_decals_t)

		decal.pos = V.v(512, 384)
		decal.render.sprites[1].name = this.sections_decals_prefix .. i

		queue_insert(store, decal)
		table.insert(decals, decal)
	end

	while not this.boss_ref.ready_to_get_up do
		coroutine.yield()
	end

	for k, v in pairs(decals) do
		queue_remove(store, v)
	end

	queue_remove(store, this)
end

scripts.controller_stage_08_templar_swordsmen = {}

function scripts.controller_stage_08_templar_swordsmen.update(this, store, script)
	this.soldiers_alive = 0

	U.y_wait(store, fts(3))

	while true do
		local spi = 1

		for i = 1, this.spawn_count do
			local soldier = E:create_entity(this.templar_t)

			soldier.path_id = this.path_id
			soldier.subpath_id = spi
			soldier.starting_ni = P:get_end_node(this.path_id) - 3 * i
			soldier.pos = P:node_pos(this.path_id, spi, soldier.starting_ni)
			soldier.source_id = this.id
			soldier.cont_ref = this

			queue_insert(store, soldier)

			spi = spi + 1

			if spi > 3 then
				spi = 1
			end
		end

		this.soldiers_alive = this.spawn_count

		while this.soldiers_alive > 0 do
			coroutine.yield()
		end

		U.y_wait(store, this.spawn_cooldown)
	end
end

scripts.soldier_stage_08_templar_swordsman = {}

function scripts.soldier_stage_08_templar_swordsman.update(this, store)
	local path_ni = this.starting_ni

	this.nav_rally.pos = P:node_pos(this.path_id, this.subpath_id, path_ni)
	this.vis.bans = this.vis._bans
	this.melee.order = U.attack_order(this.melee.attacks)

	while true do
		if path_ni < 3 then
			break
		end

		if this.health.dead then
			local tower = store.entities[this.source_id]

			tower.soldiers_alive = tower.soldiers_alive - 1

			SU.y_soldier_death(store, this)

			return
		end

		local brk, sta = SU.y_soldier_melee_block_and_attacks(store, this)

		if brk or sta == A_DONE or sta == A_IN_COOLDOWN and not this.melee.continue_in_cooldown then
			-- block empty
		else
			if V.dist2(this.nav_rally.pos.x, this.nav_rally.pos.y, this.pos.x, this.pos.y) < 25 then
				path_ni = path_ni - 3
				this.nav_rally.pos = P:node_pos(this.path_id, this.subpath_id, path_ni)
			end

			if SU.soldier_go_back_step(store, this) then
				-- block empty
			else
				SU.soldier_regen(store, this)
			end
		end

		coroutine.yield()
	end

	queue_remove(store, this)
end

function scripts.soldier_stage_08_templar_swordsman.remove(this, store)
	this.cont_ref.soldiers_alive = this.cont_ref.soldiers_alive - 1

	return true
end

scripts.controller_stage_08_tower_stun = {}

function scripts.controller_stage_08_tower_stun.update(this, store, script)
	while store.wave_group_number < 1 do
		coroutine.yield()
	end

	U.y_wait(store, math.random(this.cooldown_min, this.cooldown_max) + 3)

	while true do
		local towers = table.filter(store.entities, function(k, v)
			return not v.pending_removal and v.tower and not v.tower.blocked and v.tower.can_be_mod and v.tower.type ~= "holder" and not v._to_be_stunned and (not v.vis or band(v.vis.bans, F_STUN) == 0)
		end)

		if not towers or #towers < 1 then
			U.y_wait(store, 3)
		else
			local tower_stun = E:create_entity(this.stun_t)

			queue_insert(store, tower_stun)
			U.y_wait(store, math.random(this.cooldown_min, this.cooldown_max))
		end
	end
end

scripts.controller_stage_08_tower_stun_moment = {}

function scripts.controller_stage_08_tower_stun_moment.update(this, store, script)
	local tower, bomb, shake
	local towers = table.filter(store.entities, function(k, v)
		return not v.pending_removal and v.tower and not v.tower.blocked and v.tower.can_be_mod and v.tower.type ~= "holder" and not v._to_be_stunned and (not v.vis or band(v.vis.bans, F_STUN) == 0)
	end)

	if not towers or #towers < 1 then
		U.y_wait(store, 3)
	else
		tower = towers[math.random(1, #towers)]
		tower._to_be_stunned = true
		bomb = E:create_entity(this.bomb_t)
		bomb.pos = V.vclone(tower.pos)
		bomb.render.sprites[1].ts = store.tick_ts

		queue_insert(store, bomb)

		if not this.skip_goblin_anim then
			U.y_animation_play(bomb, "start", nil, store.tick_ts, 1)
			U.animation_start(bomb, "loop", nil, store.tick_ts, true)
			U.y_wait(store, this.wait_time)
		end

		U.animation_start(bomb, "bomb", nil, store.tick_ts, false)
		S:queue(this.sound_fire)
		U.y_wait(store, this.hit_time)
		S:queue(this.sound_hit)

		if not tower or tower.pending_removal or tower.tower.upgrade_to then
			local towers = U.find_towers(store.entities, bomb.pos, 0, 20, function(v, o)
				return v.tower.can_be_mod and v.tower.type ~= "holder" and not v.tower.upgrade_to and (not v.vis or band(v.vis.bans, F_STUN) == 0)
			end)

			tower = towers and #towers > 0 and towers[1]
		end

		if tower then
			local mod = E:create_entity(this.mod_t)

			mod.modifier.target_id = tower.id
			mod.modifier.source_id = this.id

			queue_insert(store, mod)
		end

		shake = E:create_entity("aura_screen_shake")
		shake.aura.amplitude = 0.5
		shake.aura.duration = 1
		shake.aura.freq_factor = 3

		queue_insert(store, shake)
		U.y_animation_wait(bomb)
		queue_remove(store, bomb)
	end

	if tower then
		tower._to_be_stunned = false
	end

	queue_remove(store, this)
end

scripts.mod_stage_08_tower_stun = {}

function scripts.mod_stage_08_tower_stun.update(this, store)
	local m = this.modifier
	local target = store.entities[m.target_id]
	local source = store.entities[m.source_id]

	if not target then
		queue_remove(store, this)

		return
	end

	local shown_hand = false

	local function block_tower()
		local t = target.tower

		t.block_count = t.block_count + 1

		if t.block_count > 0 then
			t.blocked = true

			if target.tower and not target.tower_holder then
				t.can_be_sold = false
			end
		end

		if target.tower and not target.tower._type then
			target.tower._type = target.tower.type
			target.tower.type = "tower_broken_stage_08"
			target.trigger_deselect = true

			if not target.user_selection then
				E:add_comps(target, "user_selection")
			end
		end

		if not target.repair then
			target.repair = {}
			target.repair.cost = this.repair_cost
			target.repair.active = false
		end
	end

	local function unblock_tower()
		local t = target.tower

		t.block_count = 0

		if t.block_count < 1 then
			t.blocked = nil
			t.block_count = 0

			if target.tower and not target.tower_holder then
				t.can_be_sold = true
			end
		end
	end

	m.ts = store.tick_ts

	block_tower()

	this.pos = target.pos

	local start_ts = store.tick_ts
	local tap_ts = store.tick_ts
	local tap_cd = math.random(4, 10)
	local hand

	while true do
		if target.repair and target.user_selection.in_progress and not target.repair.active then
			target.user_selection.in_progress = nil
			target.user_selection.allowed = false
			store.player_gold = store.player_gold - target.repair.cost
			target.repair.active = true

			S:queue(this.sound_events.repair)

			this.tween.disabled = false
			this.tween.reverse = true
			this.tween.ts = store.tick_ts

			break
		end

		if store.tick_ts - start_ts > this.auto_repair_time then
			target.user_selection.in_progress = nil
			target.user_selection.allowed = false
			this.tween.disabled = false
			this.tween.reverse = true
			this.tween.ts = store.tick_ts

			break
		end

		if not shown_hand and tap_cd < store.tick_ts - tap_ts then
			hand = E:create_entity(this.hand_decal_t)
			hand.pos = this.pos
			hand.render.sprites[1].ts = store.tick_ts
			hand.tween.ts = store.tick_ts

			queue_insert(store, hand)

			shown_hand = true
		end

		if not table.contains(store.entities, target) then
			local towers = U.find_towers(store.entities, this.pos, 0, 20, function(v, o)
				return v.tower and not v.tower.blocked or v.tower_holder and not v.tower_holder.blocked
			end)

			if towers and #towers > 0 then
				target = towers[1]
				target.test_deselect = true
				this.modifier.target_id = target.id

				block_tower()
			end
		end

		coroutine.yield()
	end

	if hand then
		queue_remove(store, hand)
	end

	U.y_wait(store, this.tween.props[1].keys[2][1])
	unblock_tower()

	target.trigger_deselect = true
	target.user_selection.allowed = true
	target.repair = nil

	queue_remove(store, this)
end

function scripts.mod_stage_08_tower_stun.remove(this, store)
	local target = store.entities[this.modifier.target_id]

	if target then
		target.tower.type = target.tower._type
		target.tower._type = nil
	end

	return true
end

scripts.decal_stage_09_mortal_kombat = {}

function scripts.decal_stage_09_mortal_kombat.update(this, store)
	local character = "scorpion"
	local ts = store.tick_ts

	local function get_opposite_character()
		if character == "scorpion" then
			return "subzero"
		else
			return "scorpion"
		end
	end

	while true do
		if store.tick_ts - ts > this.attack_cd then
			if this.sound_hit then
				S:queue(this.sound_hit, {
					delay = fts(this.sound_hit_frames[character])
				})
			end

			U.y_animation_play(this, "attk_" .. character, nil, store.tick_ts, 1, 1)
			U.animation_start(this, get_opposite_character() .. "_mareo_loop", nil, store.tick_ts, true, 1, true)

			local stun_ts = store.tick_ts

			while store.tick_ts - stun_ts < this.stun_duration do
				if this.ui and this.ui.clicked then
					if this.sound_finisher then
						S:queue(this.sound_finisher, {
							delay = fts(this.sound_finisher_frame)
						})
					end

					U.y_animation_play(this, get_opposite_character() .. "_mareo_click", nil, store.tick_ts, 1, 1)
					signal.emit("kombat-finisher-stage09")
					queue_remove(store, this)

					return
				end

				coroutine.yield()
			end

			U.y_animation_play(this, get_opposite_character() .. "_mareo_out", nil, store.tick_ts, 1, 1)
			U.animation_start(this, "idle", nil, store.tick_ts, true, 1, true)

			character = get_opposite_character()
			ts = store.tick_ts
		end

		this.ui.clicked = false

		coroutine.yield()
	end
end

scripts.controller_stage_10_jt_icicles = {}

function scripts.controller_stage_10_jt_icicles.update(this, store)
	local start_y = store.visible_coords and store.visible_coords.top or REF_H
	local door = find_all_t(store, this.jt_door)[1]

	this._target_random, this._target_enemies, this._target_allies = 0, 0, 0
	this.icicles_active = true

	local function spawn_icicle(dest)
		local controller = E:create_entity(this.cluster_controller)

		controller.pos.x, controller.pos.y = dest.x, dest.y

		queue_insert(store, controller)

		for i = 1, this.icicles_per_cluster do
			local icicles = E:create_entity(this.icicle_t)

			icicles._controller = controller

			local xr = U.frandom(-this.icicle_spread, this.icicle_spread)
			local yr = U.frandom(-this.icicle_spread, this.icicle_spread)

			icicles.pos.x, icicles.pos.y = dest.x + xr, start_y
			icicles.bullet.from = V.vclone(icicles.pos)
			icicles.render.sprites[1].scale = V.vv(U.frandom(this.scale_min, 1))

			if i == 1 then
				icicles.bullet.to = v(dest.x, dest.y)
			else
				icicles.bullet.to = v(dest.x + xr, dest.y + yr)
			end

			queue_insert(store, icicles)
			U.y_wait(store, U.frandom(0, this.max_delay_icicles))
		end
	end

	local excluded_paths = {
		2,
		3,
		6
	}

	local function target_random()
		local dest, pi

		for _ = 1, 3 do
			dest, pi = P:get_random_position(10, bor(TERRAIN_LAND, TERRAIN_ICE))

			if dest and not table.contains(excluded_paths, pi) then
				break
			end

			dest = nil
		end

		dest = dest or this.target_random_defaults[math.random(#this.target_random_defaults)]

		spawn_icicle(dest)
	end

	local function target_enemies()
		local enemies = table.filter(store.entities, function(k, v)
			return not v.pending_removal and v.enemy and v.nav_path and v.health and not v.health.dead and (not this.excluded_templates or not table.contains(this.excluded_templates, v.template_name)) and band(bor(F_WATER), v.vis.flags) == 0
		end)

		if not enemies or #enemies == 0 then
			target_random()

			return
		end

		local r_enemy = enemies[math.random(1, #enemies)]
		local pred_pos

		if r_enemy.motion.forced_waypoint then
			local dt = this.icicle_fall_time

			pred_pos = V.v(r_enemy.pos.x + dt * r_enemy.motion.speed.x, r_enemy.pos.y + dt * r_enemy.motion.speed.y)
		else
			local node_offset = P:predict_enemy_node_advance(r_enemy, this.icicle_fall_time)

			pred_pos = P:node_pos(r_enemy.nav_path.pi, r_enemy.nav_path.spi, r_enemy.nav_path.ni + node_offset)
		end

		spawn_icicle(pred_pos)
	end

	local function target_allies()
		local soldiers = table.filter(store.entities, function(k, v)
			return not v.pending_removal and v.soldier and v.vis and v.health and not v.health.dead
		end)

		if not soldiers or #soldiers == 0 then
			target_random()

			return
		end

		local dest = V.vclone(soldiers[math.random(1, #soldiers)].pos)

		spawn_icicle(dest)
	end

	local function y_spawn_icicle_barrage()
		local shake = E:create_entity("aura_screen_shake")

		shake.aura.amplitude = 1
		shake.aura.duration = 0.5
		shake.aura.freq_factor = 3

		queue_insert(store, shake)

		local all_targets = this._target_random + this._target_enemies + this._target_allies
		local cr, ca, ce = 0, 0, 0
		local o = {
			1,
			2,
			3
		}

		for i = 1, all_targets do
			if cr >= this._target_random then
				table.remove(o, index_at(o, 1))

				cr = -1
			end

			if ca >= this._target_allies then
				table.remove(o, index_at(o, 2))

				ca = -1
			end

			if ce >= this._target_enemies then
				table.remove(o, index_at(o, 3))

				ce = -1
			end

			if #o == 0 then
				break
			end

			local r = o[math.random(1, #o)]

			if r == 1 then
				target_random()

				cr = cr + 1
			elseif r == 2 then
				target_allies()

				ca = ca + 1
			elseif r == 3 then
				target_enemies()

				ce = ce + 1
			end

			U.y_wait(store, U.frandom(0, this.max_delay_clusters))
		end

		this._target_random, this._target_enemies, this._target_allies = 0, 0, 0
	end

	while true do
		if not door.in_use and this.spawn_icicles and this.icicles_active then
			door.in_use = true

			S:queue(this.sound_events.door_open)

			if door.ready then
				U.animation_start(door, this.door_anim_defrosted, nil, store.tick_ts)
			else
				U.animation_start(door, this.door_anim, nil, store.tick_ts)
			end

			U.y_wait(store, this.door_slam_timing)
			S:queue(this.sound_events.door_close)

			door.in_use = false

			y_spawn_icicle_barrage()
			U.y_wait(store, this.time_to_free_door)
			U.y_animation_wait(door, 1, 1)

			this.spawn_icicles = false
		end

		if not door.in_use and this.spawn_icicles and not this.icicles_active then
			door.in_use = true

			y_spawn_icicle_barrage()

			this.spawn_icicles = false

			U.y_wait(store, this.time_to_free_door)

			door.in_use = false
		end

		coroutine.yield()
	end
end

function scripts.controller_stage_10_jt_icicles.on_event(this, store, action, t_random, t_allies, t_enemies)
	this.spawn_icicles = true

	if t_random and tonumber(t_random) then
		this._target_random = tonumber(t_random)
	else
		this._target_random = this.target_random
	end

	if t_allies and tonumber(t_allies) then
		this._target_allies = tonumber(t_allies)
	else
		this._target_allies = this.target_allies
	end

	if t_enemies and tonumber(t_enemies) then
		this._target_enemies = tonumber(t_enemies)
	else
		this._target_enemies = this.target_enemies
	end
end

scripts.decal_stage_10_jt_door_icicle = {}

function scripts.decal_stage_10_jt_door_icicle.update(this, store)
	local b = this.bullet
	local mspeed = 10 * FPS
	local particle = E:create_entity(this.particles)

	particle.particle_system.track_id = this.id

	queue_insert(store, particle)

	while V.dist(this.pos.x, this.pos.y, b.to.x, b.to.y) > mspeed * store.tick_length do
		mspeed = mspeed + FPS * math.ceil(mspeed * (1 / FPS) * b.acceleration_factor)
		mspeed = km.clamp(b.min_speed, b.max_speed, mspeed)
		b.speed.x, b.speed.y = V.mul(mspeed, V.normalize(b.to.x - this.pos.x, b.to.y - this.pos.y))
		this.pos.x, this.pos.y = this.pos.x + b.speed.x * store.tick_length, this.pos.y + b.speed.y * store.tick_length

		coroutine.yield()
	end

	this.pos.x, this.pos.y = b.to.x, b.to.y
	particle.particle_system.source_lifetime = 0

	if this._controller then
		this._controller._spawn = true
	end

	local targets = U.find_targets_in_range(store.entities, this.pos, 0, this.damage_radius, this.vis.flags, this.vis.bans)

	if targets then
		for _, enemy in pairs(targets) do
			local d = E:create_entity("damage")

			d.damage_type = this.damage_type
			d.value = U.frandom(this.damage_min, this.damage_max)
			d.source_id = this.id
			d.target_id = enemy.id

			queue_damage(store, d)
		end
	end

	S:queue(this.sound_events.hit)

	local d = E:create_entity(b.hit_decal)

	d.pos.x, d.pos.y = this.pos.x, this.pos.y
	d.render.sprites[1].ts = store.tick_ts
	d.render.sprites[1].scale = V.vclone(this.render.sprites[1].scale)

	queue_insert(store, d)
	queue_remove(store, this)
end

scripts.controller_stage_10_jt_icicle_cluster = {}

function scripts.controller_stage_10_jt_icicle_cluster.update(this, store, script)
	this._spawn = false

	while not this._spawn do
		coroutine.yield()
	end

	if this.hit_fx then
		local hfx = E:create_entity(this.hit_fx)

		hfx.pos.x, hfx.pos.y = this.pos.x, this.pos.y
		hfx.render.sprites[1].ts = store.tick_ts

		queue_insert(store, hfx)
	end

	if this.hit_decal then
		local d = E:create_entity(this.hit_decal)

		d.pos.x, d.pos.y = this.pos.x, this.pos.y
		d.render.sprites[1].ts = store.tick_ts

		queue_insert(store, d)
	end

	queue_remove(store, this)
end

scripts.decal_stage_10_jt_door = {}

function scripts.decal_stage_10_jt_door.update(this, store, script)
	local controller = find_all_t(store, this.swipe_controller)[1]

	this.ready = true
	this._swipe_ts = store.tick_ts
	this.in_use = false

	while true do
		if not controller.swipe_active or this.in_use then
			this.ui.clicked = false
		end

		if this.ui.clicked and this.ready then
			this.ui.clicked = false
			this.in_use = true
			this.ready = false

			S:queue(this.sound_events.bell_ring)
			S:queue(this.sound_events.door_open, {
				delay = fts(27)
			})
			U.y_animation_play(this, "out", nil, store.tick_ts, 1)

			controller._signal = true
			this._swipe_ts = store.tick_ts
		end

		if store.tick_ts - this._swipe_ts > this.swipe_cooldown and not this.ready and not this.boss_fight and not this.in_use then
			S:queue(this.sound_events.bell_unfreeze)
			U.y_animation_play(this, this.defrost_anim, nil, store.tick_ts, 1)

			this.ui.clicked = false
			this.ready = true
		end

		coroutine.yield()
	end
end

scripts.controller_stage_10_jt_swipe = {}

function scripts.controller_stage_10_jt_swipe.update(this, store, script)
	local door = find_all_t(store, this.jt_door)[1]

	local function has_targets()
		local at = E:get_template(this.aura_swipe)
		local targets = U.find_targets_in_range(store.entities, this.swipe_pos, 0, at.aura.radius, at.aura.vis_flags, at.aura.vis_bans)

		return targets and #targets > 0
	end

	this._signal = false

	while true do
		if this._signal then
			if this.swipe_active then
				U.animation_start(door, this.door_idle_anim, nil, store.tick_ts, true)

				local ts = store.tick_ts
				local timer_running = true
				local no_targets = true
				local aura

				while timer_running and no_targets do
					timer_running = store.tick_ts - ts < this.swipe_wait
					no_targets = not has_targets()

					coroutine.yield()
				end

				if no_targets and not timer_running then
					-- block empty
				else
					U.animation_start(door, this.door_eat_anim, nil, store.tick_ts, 1)
					S:queue(this.sound_events.eat, {
						delay = fts(23)
					})
					U.y_wait(store, this.swipe_timing)

					aura = E:create_entity(this.aura_swipe)
					aura.pos.x, aura.pos.y = this.swipe_pos.x, this.swipe_pos.y

					queue_insert(store, aura)
					U.y_animation_wait(door, 1, 1)
				end

				S:queue(this.sound_events.bell_freeze, {
					delay = fts(4)
				})
				U.y_animation_play(door, this.bell_frost_anim, nil, store.tick_ts, 1)
				S:queue(this.sound_events.door_close, {
					delay = fts(73)
				})
				U.y_animation_play(door, this.door_end_anim, nil, store.tick_ts, 1)
			end

			this._signal = false
			door._swipe_ts = store.tick_ts

			U.y_wait(store, this.time_to_free_door)

			door.in_use = false
		end

		coroutine.yield()
	end
end

scripts.aura_stage_10_puddle_entrance = {}

function scripts.aura_stage_10_puddle_entrance.update(this, store, script)
	while true do
		local enemies = filter_t(store.entities, this.pos, this.aura.radius, function(v, o)
			return v.enemy and v.nav_path and not v.health.dead and band(v.vis.flags, this.aura.vis_bans) == 0 and band(v.vis.bans, this.aura.vis_flags) == 0 and (not this.excluded_templates or not table.contains(this.aura.excluded_templates, v.template_name)) and U.is_inside_ellipse(v.pos, this.pos, this.aura.radius) and not v._exit_grace_period and v.nav_path.pi == this.pid and not v._passed_entrance and not v._flying
		end)

		if not enemies or #enemies == 0 then
			-- block empty
		else
			for i, e in ipairs(enemies) do
				e._passed_entrance = true

				local fx = E:create_entity(this.splash_fx)

				fx.render.sprites[1].ts = store.tick_ts
				fx.pos = V.vclone(e.pos)

				queue_insert(store, fx)

				if this.sound_events and this.sound_events.water_splash then
					S:queue(this.sound_events.water_splash)
				end

				e.vis._old_flags = e.vis._force_old_flags and e.vis._force_old_flags or e.vis.flags
				e.vis.flags = U.flag_set(e.vis.flags, bor(F_WATER))
				e.vis._old_bans = e.vis._force_old_bans and e.vis._force_old_bans or e.vis.bans
				e.vis.bans = F_ALL - bor(F_ENEMY, F_WATER)

				if game.game_gui.selected_entity and game.game_gui.selected_entity.id == this.id then
					signal.emit("hide-bottom-info")
				end

				if e.health_bar then
					if this.override_health_bar_offset then
						e.health_bar._orig_offset = e.health_bar.offset
						e.health_bar.offset = this.override_health_bar_offset
					end

					if this.hide_healthbar then
						e.health_bar.hidden = true
					end
				end

				if this.remove_mods then
					SU.remove_modifiers(store, e)
				end

				if this.remove_ui and e.ui then
					e.ui.can_click = false
				end

				e.unit._orig_can_explode = e.unit.can_explode
				e.unit._orig_show_blood_pool = e.unit.show_blood_pool
				e.unit.can_explode = false
				e.unit.show_blood_pool = false

				for i = 1, #e.render.sprites do
					local s = e.render.sprites[i]

					if not s._ignore_stage_10_puddles then
						s.hidden = true
					end
				end

				local decal = E:create_entity(this.ice_shadow)

				decal.target_id = e.id

				queue_insert(store, decal)

				e._ice_shadow_decal = decal

				local ps = E:create_entity(this.ps_ice_shadow)

				ps.particle_system.emit = true
				ps.particle_system.track_id = e.id

				queue_insert(store, ps)

				e._ps_ice_shadow_decal = ps
			end
		end

		coroutine.yield()
	end
end

scripts.aura_stage_10_puddle_exit = {}

function scripts.aura_stage_10_puddle_exit.update(this, store, script)
	local grace_period_e = {}

	while true do
		local r = {}

		if #grace_period_e > 0 then
			for i = 1, #grace_period_e do
				local e = grace_period_e[i]

				if store.tick_ts - e._exit_grace_period > this.exit_grace_period then
					table.insert(r, e.id)
				end
			end

			for i = 1, #r do
				local p = index_at(grace_period_e, r[i], function(e, id)
					return e.id == id
				end)
				local e = grace_period_e[p]

				e._exit_grace_period = nil

				table.remove(grace_period_e, p)
			end
		end

		local enemies = filter_t(store.entities, this.pos, this.aura.radius, function(v, o)
			return v.enemy and v.nav_path and not v.health.dead and band(v.vis.flags, this.aura.vis_bans) == 0 and band(v.vis.bans, this.aura.vis_flags) == 0 and U.is_inside_ellipse(v.pos, this.pos, this.aura.radius) and v.nav_path.pi == this.pid and v._passed_entrance
		end)

		if not enemies or #enemies == 0 then
			-- block empty
		else
			for i, e in ipairs(enemies) do
				e._passed_entrance = false
				e._exit_grace_period = store.tick_ts

				table.insert(grace_period_e, e)

				local fx = E:create_entity(this.splash_fx)

				fx.render.sprites[1].ts = store.tick_ts
				fx.pos = V.vclone(e.pos)

				queue_insert(store, fx)

				if this.sound_events and this.sound_events.water_splash then
					S:queue(this.sound_events.water_splash)
				end

				e.vis.flags = e.vis._old_flags
				e.vis.bans = e.vis._old_bans

				if e.health_bar then
					if e.health_bar._orig_offset then
						e.health_bar.offset = e.health_bar._orig_offset
					end

					e.health_bar.hidden = false
				end

				if e.ui then
					e.ui.can_click = true
				end

				e.unit.can_explode = e.unit._orig_can_explode
				e.unit.show_blood_pool = e.unit._orig_show_blood_pool

				for i = 1, #e.render.sprites do
					local s = e.render.sprites[i]

					if not s._ignore_stage_10_puddles then
						s.hidden = false
					end
				end

				queue_remove(store, e._ice_shadow_decal)

				e._ice_shadow_decal = nil

				queue_remove(store, e._ps_ice_shadow_decal)

				e._ps_ice_shadow_decal = nil
			end
		end

		coroutine.yield()
	end
end

scripts.enemy_boss_stage_10 = {}

function scripts.enemy_boss_stage_10.update(this, store, script)
	local af = this.timed_attacks.list[1]
	local controller_icicles = find_all_t(store, af.icicle_controller)[1]
	local freeze_check_ts = store.tick_ts

	af.ts = store.tick_ts

	local trigger_freeze

	local function can_freeze()
		if this.cinematic then
			return true
		end

		if trigger_freeze then
			return true
		end

		if store.tick_ts - freeze_check_ts < 0.25 then
			return false
		end

		if store.tick_ts - af.ts < af.cooldown then
			return false
		end

		freeze_check_ts = store.tick_ts

		local aura_t = E:get_template(af.aura)
		local towers = U.find_towers(store.entities, this.pos, 0, aura_t.aura.radius, function(v, o)
			return v.tower.type ~= "holder" and v.tower.type ~= "build_animation" and (not v.tower_holder or not v.tower_holder.blocked) and (not aura_t.aura.allowed_templates or table.contains(aura_t.aura.allowed_templates, v.template_name)) and (not aura_t.aura.excluded_templates or not table.contains(aura_t.aura.excluded_templates, v.template_name))
		end)

		trigger_freeze = towers and #towers > 0

		return trigger_freeze
	end

	local function y_on_death()
		U.animation_start(this, af.animation_tired, nil, store.tick_ts, true, 1)

		if (store.level_mode_6 or store.level_mode) == GAME_MODE_CAMPAIGN then
			signal.emit("show-curtains")
			signal.emit("hide-gui")
			signal.emit("start-cinematic")
		end

		LU.kill_all_enemies(store, true)
		S:stop_all()
		W:stop_manual_wave("BOSS1")

		if (store.level_mode_6 or store.level_mode) == GAME_MODE_CAMPAIGN then
			signal.emit("pan-zoom-camera", 2, {
				x = this.pos.x,
				y = this.pos.y
			}, OVm(1, 1.3))
		end

		U.y_wait(store, (store.level_mode_6 or store.level_mode) == GAME_MODE_CAMPAIGN and 2.5 or 0.5)
		S:queue(this.sound_death)
		S:queue(this.sound_events.defeat_chest_bang)
		U.y_animation_play(this, "death", nil, store.tick_ts, 1)
		S:queue(this.sound_events.defeat_roar)
		U.animation_start(this, "death_loop", nil, store.tick_ts, true, 1)
		S:queue(this.sound_events.defeat_rumble)

		local collapse = E:create_entity(this.death_rumble_fx)

		collapse.pos.x, collapse.pos.y = 512, 384
		collapse.render.sprites[1].ts = store.tick_ts

		queue_insert(store, collapse)

		local shake = E:create_entity("aura_screen_shake")

		shake.aura.amplitude = 1
		shake.aura.duration = 8
		shake.aura.freq_factor = 3

		queue_insert(store, shake)
		LU.kill_all_enemies(store, true)
		U.y_animation_wait(this)
		signal.emit("boss-killed", this)

		this.bossfight_ended = true
	end

	::label_1174_0::

	while true do
		while this.cinematic do
			coroutine.yield()
		end

		if this.health.dead then
			y_on_death()

			return
		end

		if trigger_freeze then
			U.animation_start(this, af.animation, nil, store.tick_ts, false)

			local fl = this.render.sprites[1].flip_x
			local hit_pos = V.vclone(this.pos)

			if af.hit_offset then
				hit_pos.x = hit_pos.x + (fl and -1 or 1) * af.hit_offset.x
				hit_pos.y = hit_pos.y + af.hit_offset.y
			end

			if af.hit_decal then
				local fx = E:create_entity(af.hit_decal)

				fx.pos = V.vclone(hit_pos)
				fx.render.sprites[1].ts = store.tick_ts

				queue_insert(store, fx)
			end

			if SU.y_enemy_wait(store, this, af.hit_time) then
				goto label_1174_0
			end

			S:queue(this.sound_events.tower_freeze)

			af.ts = store.tick_ts

			scripts.controller_stage_10_jt_icicles.on_event(controller_icicles, store, nil, af.random_icicles, af.allies_icicles, 0)

			local aura = E:create_entity(af.aura)

			aura.aura.source_id = this.id
			aura.aura.ts = store.tick_ts
			aura.pos = V.vclone(this.pos)

			queue_insert(store, aura)
			U.y_animation_wait(this)
			U.animation_start(this, af.animation_tired, nil, store.tick_ts, true, 1)

			local ts = store.tick_ts

			while not this.health.dead and store.tick_ts - ts < af.tired_time do
				coroutine.yield()
			end

			U.y_animation_play(this, af.animation_tired_end, nil, store.tick_ts, 1)

			trigger_freeze = false
		end

		if not SU.y_enemy_mixed_walk_melee_ranged(store, this, false, can_freeze, can_freeze) then
			-- block empty
		else
			coroutine.yield()
		end
	end
end

scripts.mod_boss_tower_block = {}

function scripts.mod_boss_tower_block.insert(this, store, script)
	local m = this.modifier
	local target = store.entities[m.target_id]
	local source = store.entities[m.source_id]

	if not target then
		queue_remove(store, this)

		return
	end

	this.pos = target.pos

	return true
end

function scripts.mod_boss_tower_block.update(this, store)
	local tr = this.tap_removable
	local m = this.modifier
	local target = store.entities[m.target_id]
	local source = store.entities[m.source_id]
	local tap_tut

	if tr then
		tap_tut = E:create_entity(this.tap_tutorial)
		tap_tut.pos = v(this.pos.x + this.tut_offset.x, this.pos.y + this.tut_offset.y)
		tap_tut.render.sprites[1].ts = store.tick_ts

		queue_insert(store, tap_tut)
	end

	if this.anim_start then
		U.animation_start(this, this.anim_start, nil, store.tick_ts, nil, 1)
	end

	U.y_wait(store, U.frandom(0, this.spawn_delay_max))
	SU.tower_block_inc(target)

	m.ts = store.tick_ts

	U.y_animation_wait(this)

	if this.anim_loop then
		U.animation_start(this, this.anim_loop, nil, store.tick_ts)
	end

	local taps = 0
	local tap_ts = store.tick_ts

	while store.tick_ts - m.ts < m.duration - this.end_anim_duration and (not tr or taps < this.taps_to_remove) do
		if tr and this.ui then
			if this.ui.clicked and store.tick_ts - tap_ts > 0.11 then
				taps = taps + 1
				tap_ts = store.tick_ts

				local shake = E:create_entity("mod_shake_sprite")

				shake.modifier.target_id = this.id
				shake.modifier.duration = 0.1
				shake.modifier.intensity = 4

				queue_insert(store, shake)
			end

			this.ui.clicked = false
		end

		coroutine.yield()
	end

	if this.fx_out then
		local fx = E:create_entity(this.fx_out)

		fx.pos = V.vclone(this.pos)
		fx.render.sprites[1].ts = store.tick_ts

		queue_insert(store, fx)
	end

	S:queue(this.sound_events.free_tower)

	if tap_tut then
		queue_remove(store, tap_tut)
	end

	this.render.sprites[1].hidden = true

	U.y_wait(store, 0.5)
	queue_remove(store, this)
end

scripts.decal_stage_10_at_at = {}

function scripts.decal_stage_10_at_at.e_insert(this, store)
	local r = E:create_entity("editor_pillar_rally_point")

	queue_insert(store, r)

	this.editor.shoot_pos_point_id = r.id

	if this.shoot_pos.pos and this.shoot_pos.pos.x ~= 0 and this.shoot_pos.pos.y ~= 0 then
		r.pos = this.shoot_pos.pos
	else
		r.pos = V.v(this.pos.x - 50, this.pos.y - 50)
		this.shoot_pos.pos = r.pos
	end

	return true
end

function scripts.decal_stage_10_at_at.update(this, store)
	local clicks = 0
	local finished_shooting = false

	while true do
		if not finished_shooting and this.ui and this.ui.clicked then
			this.ui.clicked = false
			clicks = clicks + 1

			if clicks == 1 or clicks == 3 then
				S:queue(this.sound_tap_1)
			end

			if clicks == 2 then
				S:queue(this.sound_tap_2)
			end

			U.animation_start(this, "click_" .. clicks, nil, store.tick_ts, false, 1)

			if clicks == 4 then
				S:queue(this.sound_break)

				for i = 1, #this.bullet_hit_times do
					U.y_wait(store, this.bullet_hit_times[i])

					local bullet = E:create_entity(this.bullet)

					bullet.pos = V.v(this.pos.x + this.bullet_offsets[1].x, this.pos.y + this.bullet_offsets[1].y)
					bullet.bullet.from = V.vclone(bullet.pos)
					bullet.bullet.to = this.shoot_pos.pos

					queue_insert(store, bullet)

					local bullet = E:create_entity(this.bullet)

					bullet.pos = V.v(this.pos.x + this.bullet_offsets[2].x, this.pos.y + this.bullet_offsets[2].y)
					bullet.bullet.from = V.vclone(bullet.pos)
					bullet.bullet.to = this.shoot_pos.pos

					queue_insert(store, bullet)
				end

				finished_shooting = true
			end
		end

		coroutine.yield()
	end
end

scripts.decal_stage_10_sasquatch = {}

function scripts.decal_stage_10_sasquatch.update(this, store)
	local clicks = 0

	while true do
		if clicks < 2 and this.ui and this.ui.clicked then
			this.ui.clicked = false
			clicks = clicks + 1
			this.render.sprites[1].hidden = false

			U.y_animation_play(this, "click_" .. clicks, nil, store.tick_ts, 1, 1)
			U.animation_start(this, "idle_" .. clicks, nil, store.tick_ts, true, 1)
		end

		coroutine.yield()
	end
end

scripts.mod_stage_11_tower_web = {}

function scripts.mod_stage_11_tower_web.update(this, store)
	local m = this.modifier

	U.y_animation_wait(this, 1)
	U.animation_start(this, this.idle_anim, nil, store.tick_ts, true, 1)

	local start_ts = store.tick_ts

	while store.tick_ts - start_ts < m.duration do
		coroutine.yield()
	end

	U.y_animation_play(this, this.end_anim, nil, store.tick_ts, 1, 1)
	queue_remove(store, this)
end

scripts.controller_remote_balance_rappel_spawning = {}

function scripts.controller_remote_balance_rappel_spawning.update(this, store, script)
	local spawners = find_all_t(store, this.spawner_t)

	table.sort(spawners, function(v1, v2)
		return v1.spawner_id < v2.spawner_id
	end)

	while true do
		if this.cache_invalidated then
			this.cache_invalidated = false
			spawners = find_all_t(store, this.spawner_t)

			table.sort(spawners, function(v1, v2)
				return v1.spawner_id < v2.spawner_id
			end)
		end

		if this.spawn_rappel then
			this.spawn_rappel = false

			local mid = this.marker_id == -1 and math.random(1, #spawners) or this.marker_id
			local sp = spawners[mid]

			sp.amount = this.amount
			sp.path_id = this.path_id
			sp.trigger_spawn = true
		end

		coroutine.yield()
	end
end

function scripts.controller_remote_balance_rappel_spawning.on_event(this, store, action, marker_id, path_id, amount)
	this.spawn_rappel = true
	this.marker_id = tonumber(marker_id)
	this.path_id = tonumber(path_id)
	this.amount = tonumber(amount)
end

scripts.controller_remote_balance_rappel_spawner = {}

function scripts.controller_remote_balance_rappel_spawner.update(this, store, script)
	local start_y = store.visible_coords and store.visible_coords.top or REF_H

	while true do
		if this.trigger_spawn then
			this.trigger_spawn = false

			local o = {}
			local path = this.path_id
			local current_node = P:nearest_nodes(this.pos.x, this.pos.y, {
				path
			}, nil, true)[1][3]

			for i = 1, this.amount do
				local subpath = get_random_round_robin(o, 3)
				local r = math.random(-this.node_random, this.node_random)
				local node = km.clamp(P:get_start_node(path), P:get_end_node(path), current_node + r)
				local fpos = P:node_pos(path, subpath, node)
				local decal = E:create_entity(this.spawn_decal)

				decal.pos = V.v(fpos.x, start_y)
				decal.target_pos = V.vclone(fpos)
				decal.render.sprites[1].flip_x = this.flip_spawns and this.flip_spawns or false
				decal.pi = path
				decal.spi = subpath
				decal.ni = node

				queue_insert(store, decal)
				U.y_wait(store, U.frandom(0, this.wait_random))
			end
		end

		coroutine.yield()
	end
end

scripts.decal_rappel_utils = {}

function scripts.decal_rappel_utils.set_y(this, store)
	local min_y = (store.visible_coords and store.visible_coords.top or REF_H) + 100
	local ideal_distance = 500
	local dist = math.abs(this.target_pos.y - min_y)
	local start_y = min_y

	if dist < ideal_distance then
		start_y = start_y + ideal_distance
	end

	return start_y
end

function scripts.decal_rappel_utils.y_descend(this, store)
	S:queue(this.sound_events.rappel_down)

	local string = E:create_entity(this.string_t)

	string.target_id = this.id

	queue_insert(store, string)

	local shadow = E:create_entity(this.shadow_t)

	shadow.pos.x, shadow.pos.y = this.target_pos.x, this.target_pos.y
	shadow.render.sprites[1].ts = store.tick_ts

	queue_insert(store, shadow)

	local start_y = this.pos.y
	local max_height = start_y - shadow.pos.y
	local a = 1

	U.y_ease_key(store, this.pos, "y", start_y, this.target_pos.y + this.offset_drop, this.descend_rappel_duration, this.descend_rappel_ease, function(dt, p)
		local height = this.pos.y - shadow.pos.y
		local scale = km.clamp(0.2, 1, (max_height - height) / max_height)

		shadow.render.sprites[1].scale = V.vv(scale)

		local dy = this.pos.y - this.target_pos.y
		local s = this.render.sprites[1]
		local flight_height = this.rappel_flight_height and this.rappel_flight_height or 180

		if flight_height <= dy then
			s.z = Z_FLYING_HEROES
		else
			s.z = Z_OBJECTS
		end

		s.sort_y_offset = -dy + this.offset_extra

		for i, v in ipairs(string.render.sprites) do
			local syo = v.offset.y

			v.sort_y_offset = -syo

			local dy = string.pos.y + v.offset.y - this.target_pos.y

			if flight_height <= dy then
				v.z = Z_FLYING_HEROES
			else
				v.z = Z_OBJECTS
			end
		end

		if this.animation_rappel_descent_sequence and a <= #this.animation_rappel_descent_sequence and dt > this.animation_rappel_descent_sequence[a][2] then
			U.animation_start(this, this.animation_rappel_descent_sequence[a][1], nil, store.tick_ts, nil, 1)

			a = a + 1
		end
	end)

	return shadow, string, max_height
end

function scripts.decal_rappel_utils.y_ascend(this, store, start_y, max_height, shadow, string)
	S:queue(this.sound_events.rappel_up)
	U.y_ease_key(store, this.pos, "y", this.pos.y, start_y, this.ascend_rappel_duration, this.ascend_rappel_ease, function(dt, p)
		if shadow then
			local height = this.pos.y - shadow.pos.y
			local scale = km.clamp(0.1, 1, (max_height - height) / max_height)

			shadow.render.sprites[1].scale = V.vv(scale)
		end

		local dy = this.pos.y - this.target_pos.y
		local s = this.render.sprites[1]
		local flight_height = 180

		if flight_height <= dy then
			s.z = Z_FLYING_HEROES
		else
			s.z = Z_OBJECTS
		end

		s.sort_y_offset = -dy + this.offset_extra

		if string then
			for i, v in ipairs(string.render.sprites) do
				local dy = this.pos.y - v.offset.y - this.target_pos.y

				v.sort_y_offset = -dy
			end
		end
	end)
end

scripts.decal_stage_11_giant_spider_rappel_spawn = {}

function scripts.decal_stage_11_giant_spider_rappel_spawn.update(this, store, script)
	local start_y = store.visible_coords and store.visible_coords.top or REF_H
	local shadow, string, max_height = scripts.decal_rappel_utils.y_descend(this, store)

	U.animation_start(this, this.short_rappel_anim, nil, store.tick_ts, nil, 1)
	U.y_wait(store, this.wait_detach)

	string.dissolve = true

	U.animation_start(shadow, this.short_rappel_shadow_anim, nil, store.tick_ts, nil, 1)
	U.y_ease_key(store, this.pos, "y", this.pos.y, this.target_pos.y + this.trigger_land_distance, this.short_rappel_duration, this.short_rappel_ease, function(dt, p)
		local dy = this.pos.y - this.target_pos.y

		this.render.sprites[1].sort_y_offset = -dy

		for i, v in ipairs(string.render.sprites) do
			local dy = this.pos.y - v.offset.y - this.target_pos.y

			v.sort_y_offset = -dy
		end
	end)

	local sp = E:create_entity(this.spawn_t)

	sp.pos.x, sp.pos.y = this.target_pos.x, this.target_pos.y
	sp.nav_path.pi = this.pi
	sp.nav_path.spi = this.spi
	sp.nav_path.ni = this.ni

	queue_insert(store, sp)
	queue_remove(store, shadow)
	queue_remove(store, this)
end

scripts.decal_rappel_string = {}

function scripts.decal_rappel_string.insert(this, store, script)
	local rhp = math.ceil(REF_H / this.string_parts)

	for i = 1, rhp do
		local s = E:clone_c("sprite")

		s.animated = this.is_animated

		if s.animated then
			s.prefix = this.string_prefix
			s.name = this.string_start_anim
		elseif this.string_start_anim then
			s.name = this.string_prefix .. "_" .. this.string_start_anim
		else
			s.name = this.string_prefix
		end

		s.loop = false
		s.anchor.y = 0
		s.offset.y = this.string_offset + (i - 1) * this.string_parts
		s.scale = v(1, 1)
		this.render.sprites[i] = s
	end

	return true
end

function scripts.decal_rappel_string.update(this, store, script)
	local target = store.entities[this.target_id]

	if not target or not target.pos then
		queue_remove(store, this)

		return
	end

	local eases = {
		linear = function(x)
			return x
		end,
		e_o_quad = function(x)
			return 1 - (1 - x) * (1 - x)
		end,
		e_i_quad = function(x)
			return x * x
		end,
		e_o_cubic = function(x)
			return 1 - (1 - x) * (1 - x) * (1 - x)
		end,
		e_i_cubic = function(x)
			return x * x * x
		end,
		e_i_quint = function(x)
			return x * x * x * x * x
		end,
		e_i_circ = function(x)
			return 1 - math.sqrt(1 - x * x)
		end
	}

	local function map_range_01(start, finish, value)
		return (value - start) / (finish - start)
	end

	local next_to_dissolve = 0
	local last_dissolved = 0
	local dissolving = false
	local moving = false
	local easing = false
	local t, tm = 0, 0
	local top_y = store.visible_coords and store.visible_coords.top or REF_H

	this.pos = target.pos

	while true do
		target = store.entities[this.target_id]

		if not target or this.dissolve then
			this.pos = V.vclone(this.pos)
			this.render.sprites[1].hidden = true
			dissolving = true
			moving = true
			easing = true

			local dist = top_y - this.pos.y
			local start_y = this.pos.y

			while easing do
				local x = map_range_01(0, this.dissolution_duration, t)
				local xm = map_range_01(0, this.dissolution_movement_duration, tm)
				local p = eases[this.dissolution_ease](x)
				local pm = eases[this.dissolution_movement_ease](xm)

				next_to_dissolve = math.floor(#this.render.sprites * p)

				if moving then
					this.pos.y = start_y + dist * pm
				end

				if dissolving and last_dissolved < next_to_dissolve then
					for i = last_dissolved + 1, next_to_dissolve do
						local s = this.render.sprites[i]

						s.name = "end"
						s.ts = store.tick_ts
						last_dissolved = i
					end
				end

				if x >= 1 then
					dissolving = false
				end

				if xm >= 1 then
					moving = false
				end

				if x >= 1 and xm >= 1 then
					easing = false
				end

				coroutine.yield()

				t = t + store.tick_length
				tm = tm + store.tick_length
			end

			U.y_wait(store, fts(10))
			queue_remove(store, this)

			return
		end

		coroutine.yield()
	end
end

scripts.controller_stage_11_spider_block_and_spawn = {}

function scripts.controller_stage_11_spider_block_and_spawn.update(this, store, script)
	local spawners = find_all_t(store, this.spawner_t)
	local r_interval = U.frandom(this.block_towers_interval_min, this.block_towers_interval_max)

	this.in_use = false
	this._tower_block = true
	this._spawn_eggs = true
	this._lower_boss = true
	this._done = true

	table.sort(spawners, function(v1, v2)
		return v1.nest_id < v2.nest_id
	end)
	U.y_wait(store, 1e+99, function(s, t)
		return store.wave_group_number > 0
	end)

	local block_tower_ts = store.tick_ts

	while true do
		if this._spawn_eggs and this.eggs_queue and #this.eggs_queue > 0 and not this.in_use then
			local egg_spawn = table.remove(this.eggs_queue, 1)

			this._done = false
			this.in_use = true

			local mid = this.nest_id == -1 and math.random(1, #spawners) or egg_spawn.nest_id
			local sp = spawners[mid]
			local egg_spawner = E:create_entity(this.spider_spawn_t)

			egg_spawner.controller = this
			egg_spawner.amount = egg_spawn.amount
			egg_spawner.to_spawn = egg_spawn.to_spawn
			egg_spawner.nest_id = sp.id
			egg_spawner.path_id = sp.path_id
			egg_spawner.pos.x = sp.pos.x
			egg_spawner.target_pos.x, egg_spawner.target_pos.y = sp.pos.x, sp.pos.y

			queue_insert(store, egg_spawner)

			while not this._done do
				coroutine.yield()
			end

			U.y_wait(store, this.global_cooldown)

			this.in_use = false
		end

		if this._tower_block and table.contains(this.active_waves, store.wave_group_number) and ((store.level_mode_6 or store.level_mode) == GAME_MODE_CAMPAIGN or (store.level_mode_6 or store.level_mode) == GAME_MODE_KR1) and r_interval < store.tick_ts - block_tower_ts and not this.in_use then
			r_interval = U.frandom(this.block_towers_interval_min, this.block_towers_interval_max)
			this.in_use = true
			this._done = false

			local towers = table.filter(store.entities, function(k, v)
				return not v.pending_removal and v.tower and not v.tower.blocked and v.tower.type ~= "holder" and v.tower.type ~= "build_animation" and v.tower.type ~= "stage_11_spider_eggs_nest" and v.tower.type ~= "stage_11_camp" and v.tower.holder_id ~= "5" and v.tower.holder_id ~= "6" and (not v.tower_holder or not v.tower_holder.blocked) and not U.has_modifier_types(store, v, MOD_TYPE_PROTECTION)
			end)

			if towers and #towers > 0 then
				local r = math.random(1, #towers)
				local blocker = E:create_entity(this.spider_block_t)

				blocker.controller = this
				blocker.holder_id = towers[r].tower.holder_id
				blocker.pos.x = towers[r].pos.x
				blocker.target_pos.x, blocker.target_pos.y = towers[r].pos.x, towers[r].pos.y

				queue_insert(store, blocker)
			else
				this._done = true
			end

			while not this._done do
				coroutine.yield()
			end

			U.y_wait(store, this.global_cooldown)

			block_tower_ts = store.tick_ts
			this.in_use = false
		end

		if this._lower_boss and this.lower_trigger and #this.eggs_queue == 0 and not this.in_use then
			this.in_use = true

			local boss = find_all_t(store, this.boss_t)[1]
			local descent = E:create_entity(this.boss_descent_decal)
			local dest = P:node_pos(this.lower_path_id, 1, this.lower_node_id)

			descent.pos.x = dest.x
			descent.target_pos = V.vclone(dest)

			queue_insert(store, descent)

			boss.lower_path_id = this.lower_path_id
			boss.lower_node_id = this.lower_node_id
			this.in_use = false
			this.lower_trigger = false
		end

		coroutine.yield()
	end
end

function scripts.controller_stage_11_spider_block_and_spawn.on_event(this, store, action, nest_id, amount, to_spawn)
	if not this._spawn_eggs then
		log.info("Received event spider_spawn_eggs, but disabled. Ignore.")

		return
	end

	if this.lower_trigger then
		log.info("Received event spider_spawn_eggs, but Sarelgaz wants to come down. Ignore.")

		return
	end

	local sanitized_to_spawn = this.default_spawn

	if to_spawn then
		for i, v in ipairs(this.allowed_spawns) do
			if to_spawn == v then
				sanitized_to_spawn = to_spawn
			end
		end
	end

	this.to_spawn = sanitized_to_spawn

	if not this.eggs_queue then
		this.eggs_queue = {}
	end

	table.insert(this.eggs_queue, {
		nest_id = tonumber(nest_id),
		amount = tonumber(amount),
		to_spawn = sanitized_to_spawn
	})
	log.info("Received event spider_spawn_eggs, added to queue: nest %s, amount %s, spawn %s", this.eggs_queue[1].nest_id, this.eggs_queue[1].amount, this.eggs_queue[1].to_spawn)
end

scripts.tower_stage_11_spider_eggs_nest = {}

function scripts.tower_stage_11_spider_eggs_nest.update(this, store, script)
	local function activate(camp)
		camp._target_nest_id = this.nest_id
	end

	local can_shoot = false
	local camp

	this.has_eggs = false

	while true do
		camp = camp or find_all_t(store, this.camp_t)[1]

		if camp then
			can_shoot = not camp.arrow_in_cooldown
		end

		this.user_selection.allowed = can_shoot and this.has_eggs
		this.tower.blocked = not this.has_eggs and camp
		this.tower.can_hover = this.has_eggs and camp
		this.ui.can_click = this.has_eggs and camp
		this.ui.can_hover = this.has_eggs and camp

		if this.user_selection.allowed and this.user_selection.arg == 1 then
			store.player_gold = store.player_gold - this.attacks.list[1].price
			this.user_selection.arg = nil
			this.user_selection.in_progress = nil
			this.user_selection.allowed = false

			activate(camp)
		end

		coroutine.yield()
	end
end

scripts.decal_stage_11_sarelgaz_tower_block = {}

function scripts.decal_stage_11_sarelgaz_tower_block.update(this, store, script)
	local start_y = scripts.decal_rappel_utils.set_y(this, store)

	this.pos.y = start_y

	local function find_tower(holder_id)
		local match = table.filter(store.entities, function(k, v)
			return not v.pending_removal and v.tower and not v.tower.blocked and v.tower.type ~= "holder" and v.tower.type ~= "build_animation" and v.tower.holder_id == holder_id
		end)

		if not match or #match == 0 then
			return nil
		end

		return match[1]
	end

	local shadow, string, max_height = scripts.decal_rappel_utils.y_descend(this, store)
	local tap_tut = E:create_entity(this.tap_tutorial)

	tap_tut.pos.x, tap_tut.pos.y = this.pos.x + this.tap_tutorial_offset.x, this.pos.y + this.tap_tutorial_offset.y
	tap_tut.render.sprites[1].ts = store.tick_ts
	tap_tut.render.sprites[1].scale = V.vv(0.6)

	queue_insert(store, tap_tut)

	local spinning_ts = store.tick_ts
	local taps = 0
	local tower = find_tower(this.holder_id)

	if not tower then
		-- block empty
	else
		S:queue(this.sound_events.webbing)
		U.y_animation_play(this, this.start_web_anim, nil, store.tick_ts, 1, 1)
		U.animation_start(this, this.loop_web_anim, nil, store.tick_ts, true, 1)

		tower.ui.can_click = false

		SU.tower_block_inc(tower)

		while store.tick_ts - spinning_ts <= this.time_to_block do
			if not tower then
				goto label_1213_0
			end

			if this.ui.clicked then
				this.ui.clicked = false
				taps = taps + 1
			end

			if taps >= this.taps_to_remove then
				S:queue(this.sound_events.interrupt)
				U.y_animation_play(this, this.tapped_anim, nil, store.tick_ts, 1, 1)

				break
			end

			coroutine.yield()
		end

		tower.ui.can_click = true

		SU.tower_block_dec(tower)

		if taps < this.taps_to_remove then
			local block = E:create_entity(this.block_mod)

			block.modifier.target_id = tower.id

			queue_insert(store, block)
		end
	end

	::label_1213_0::

	queue_remove(store, tap_tut)

	if taps < this.taps_to_remove then
		U.y_wait(store, this.wait_after_trap)
	end

	U.animation_start(this, this.ascend_anim, nil, store.tick_ts, false, 1)
	scripts.decal_rappel_utils.y_ascend(this, store, start_y, max_height, shadow, string)

	this.controller._done = true

	queue_remove(store, shadow)
	queue_remove(store, this)
end

scripts.decal_stage_11_sarelgaz_eggs_spawn = {}

function scripts.decal_stage_11_sarelgaz_eggs_spawn.update(this, store, script)
	local start_y = scripts.decal_rappel_utils.set_y(this, store)

	this.pos.y = start_y

	local shadow, string, max_height = scripts.decal_rappel_utils.y_descend(this, store)

	U.animation_start(this, this.place_egg_anim, nil, store.tick_ts, nil, 1)
	U.y_wait(store, this.egg_spawn_time)
	S:queue(this.sound_events.egg)

	local spawner = store.entities[this.nest_id]
	local egg = E:create_entity(this.egg_prefix .. "_" .. this.to_spawn)

	egg.pos.x, egg.pos.y = this.target_pos.x, this.target_pos.y
	egg.hatch_amount = this.amount
	egg.path_id = this.path_id
	egg.render.sprites[1].ts = store.tick_ts
	egg.source_id = spawner.id

	queue_insert(store, egg)

	spawner.has_eggs = true
	spawner.current_egg = egg

	U.animation_start(this, this.ascend_anim, nil, store.tick_ts, true, 1)
	scripts.decal_rappel_utils.y_ascend(this, store, start_y, max_height, shadow, string)

	this.controller._done = true

	queue_remove(store, shadow)
	queue_remove(store, this)
end

scripts.decal_stage_11_sarelgaz_descent = {}

function scripts.decal_stage_11_sarelgaz_descent.update(this, store, script)
	this.render.sprites[1].ts = store.tick_ts

	local start_y = scripts.decal_rappel_utils.set_y(this, store)

	this.pos.y = start_y

	local shadow, string, max_height = scripts.decal_rappel_utils.y_descend(this, store)
	local boss = find_all_t(store, this.boss_t)[1]

	if boss then
		boss.lower_trigger = true
	end

	local controller = find_all_t(store, this.controller_t)[1]

	controller._done = true
	this.finished = true

	coroutine.yield()

	if not boss then
		coroutine.yield()
	end

	this.render.sprites[1].hidden = true

	U.y_wait(store, fts(10))
	queue_remove(store, shadow)
	queue_remove(store, this)
end

scripts.decal_stage_11_sarelgaz_ascent = {}

function scripts.decal_stage_11_sarelgaz_ascent.update(this, store, script)
	this.render.sprites[1].ts = store.tick_ts

	local start_y = scripts.decal_rappel_utils.set_y(this, store)

	scripts.decal_rappel_utils.y_ascend(this, store, start_y)

	local controller = find_all_t(store, this.controller_t)[1]

	controller._done = true

	queue_remove(store, this)
end

scripts.tower_stage_11_camp = {}

function scripts.tower_stage_11_camp.insert(this, store)
	local personal_barracks = find_all_t(store, this.barracks_t)

	for i, b in ipairs(personal_barracks) do
		b.barrack.max_soldiers = this.barracks_soldiers[this.tower.level]

		local t = E:get_template(b.barrack.soldier_type)

		t.health.dead_lifetime = this.soldiers_dead_lifetime[this.tower.level]

		for i, s in ipairs(b.barrack.soldiers) do
			s.health.dead_lifetime = this.soldiers_dead_lifetime[this.tower.level]
		end
	end

	local lights_controllers = find_all_t(store, this.shadows_controller)

	if not lights_controllers or #lights_controllers == 0 then
		this._shadows_controller = E:create_entity(this.shadows_controller)
		this._shadows_controller.pos = V.vclone(this.pos)
		this._shadows_controller._camp = this

		queue_insert(store, this._shadows_controller)
	else
		this._shadows_controller = lights_controllers[1]
		this._shadows_controller._camp = this
	end

	local invulnerability_auras = find_all_t(store, this.shadows_aura)

	if not invulnerability_auras or #invulnerability_auras == 0 then
		this._shadows_aura = E:create_entity(this.shadows_aura)
		this._shadows_aura.pos = V.v(this.pos.x + this.shadows_offset.x, this.pos.y + this.shadows_offset.y)

		queue_insert(store, this._shadows_aura)
	else
		this._shadows_aura = invulnerability_auras[1]
		this._shadows_aura.pos = V.v(this.pos.x + this.shadows_offset.x, this.pos.y + this.shadows_offset.y)
	end

	this.damage_state = 1
	this.camp_front = find_all_t(store, this.camp_front)[1]
	this.camp_back = find_all_t(store, this.camp_back)[1]
	this.tent_hit_ts = store.tick_ts

	if this.hand_insert then
		scripts.tower_stage_11_camp.on_level_up(this, store, this.tower.level, true)
	end

	return true
end

function scripts.tower_stage_11_camp.enemy_reached_goal_fn(this, store, event_name, e)
	local function hit_animations(defeat_controller)
		if not defeat_controller then
			return
		end

		S:queue(this.sound_events.hit_camp)

		this.tent_hit_ts = store.tick_ts

		local hit_anim = "hit"

		if this.tower.level == 3 then
			hit_anim = "hit2"

			if not defeat_controller.defeat_cinematic then
				if this.fire_arrow_shooter ~= 2 and this.arrow_shooter ~= 2 then
					U.animation_start(this, "hit", nil, store.tick_ts, nil, 2)
				end

				if this.fire_arrow_shooter ~= 3 and this.arrow_shooter ~= 3 then
					U.animation_start(this, "hit", nil, store.tick_ts - fts(math.random(1, 4)), nil, 3)
				end
			end
		end

		if not defeat_controller.defeat_cinematic then
			U.animation_start(this, hit_anim, nil, store.tick_ts, nil, 1)
		end

		U.animation_start(this.camp_front, "hit" .. this.damage_state, nil, store.tick_ts, nil, 1)
		U.animation_start(this.camp_back, "hit" .. (this.damage_state == 1 and "" or this.damage_state), nil, store.tick_ts, nil, 1)
	end

	local size = "small"

	if e.unit.size == UNIT_SIZE_MEDIUM then
		size = "medium"
	end

	if e.unit.size == UNIT_SIZE_LARGE then
		size = "big"
	end

	local fx = E:create_entity(this.camp_damage_fx .. "_" .. size)

	fx.pos.x, fx.pos.y = e.pos.x, e.pos.y
	fx.render.sprites[1].ts = store.tick_ts

	queue_insert(store, fx)

	local defeat_controller = find_all_t(store, "controller_stage_11_loss")[1]

	if not defeat_controller then
		log.debug("tower_stage_11_camp.enemy_reached_goal_fn - defeat_controller removed. skipping...")

		return
	end

	if not defeat_controller.defeat_cinematic and store.lives <= this.lives_thresholds[1] then
		this.damage_state = 2

		hit_animations(defeat_controller)
	end

	if not defeat_controller.defeat_cinematic and store.lives <= this.lives_thresholds[2] then
		this.damage_state = 3

		hit_animations(defeat_controller)
	end

	hit_animations(defeat_controller)

	if not defeat_controller.defeat_cinematic and store.lives <= e.enemy.lives_cost then
		store.game_outcome = {}
		store.ephemeral.defeat_cinematic = true
		defeat_controller.defeat_cinematic = true
		defeat_controller.normal_defeat = true
	end
end

function scripts.tower_stage_11_camp.on_level_up(this, store, current_level, ignore_animation)
	local a = this.attacks
	local aa = a and a.list[2] or nil

	local function replace_holder(h)
		local holder = E:create_entity(this.hand_insert and this.holder_on_fow_instant or this.holder_on_fow_reveal)

		holder.pos = V.vclone(h.pos)
		holder.tower.terrain_style = h.tower.terrain_style
		holder.tower.default_rally_pos = h.tower.default_rally_pos
		holder.tower.holder_id = h.tower.holder_id
		holder.ui.nav_mesh_id = h.ui.nav_mesh_id
		holder.tower.level = 1
		holder.tower.can_be_mod = false

		if holder.tween then
			holder.tween.props[1].ts = store.tick_ts
		end

		queue_insert(store, holder)
		queue_remove(store, h)
	end

	local function ease_lights(from, to, lvl)
		if this._shadows_controller._ease then
			U.y_wait(store, 1e+99, function()
				return not this._shadows_controller._ease
			end)
		end

		this._shadows_controller._ease = true
		this._shadows_controller._ease_from = from
		this._shadows_controller._ease_to = to
		this._shadows_controller._camp_level = lvl
	end

	this._shadows_aura.aura.radius = this._shadows_aura.radius_levels[current_level]

	if current_level == 1 then
		return
	end

	this._shadows_aura.grid_changeup = true

	local walls_lvlup_anim

	if current_level > 1 then
		walls_lvlup_anim = "levelup"

		local fow_blocked_holders = find_all_t(store, this.fow_holders_t)

		for k, v in pairs(fow_blocked_holders) do
			replace_holder(v)
		end

		local buy_c = find_all_t(store, "controller_show_buy_available")[1]

		buy_c.force_check = true
	end

	if current_level == 3 then
		walls_lvlup_anim = "levelup2"

		if not ignore_animation then
			U.animation_start(this, this.anim_level_up, nil, store.tick_ts, false, 1)
		end
	end

	if not ignore_animation then
		S:queue(this.sound_events.level_up)
		S:queue(this.sound_events.level_up_taunt)
	end

	local walls = find_all_t(store, this.walls_t_prefix, true)

	for i, v in ipairs(walls) do
		if not ignore_animation then
			U.animation_start(v, walls_lvlup_anim, nil, store.tick_ts, false, 1)
		else
			U.animation_start(v, "idle" .. current_level, nil, store.tick_ts, false, 1)
		end
	end

	if not ignore_animation then
		U.y_wait(store, 0.5)
	end

	if not ignore_animation then
		ease_lights(this.target_radius[current_level - 1], this.target_radius[current_level], current_level)
	end

	if not ignore_animation then
		U.y_animation_wait(this, 1)
	end

	if current_level == 3 then
		this.render.sprites[2].hidden = false
		this.render.sprites[3].hidden = false

		local arrow_t = E:get_template(aa.bullet)

		aa.pred_time = 2 * (math.sqrt(2 * arrow_t.bullet.fixed_height * arrow_t.bullet.g * -1) / arrow_t.bullet.g * -1)
	end

	U.animation_start(this, "idle" .. current_level - 1, nil, store.tick_ts, true, 1)
end

function scripts.tower_stage_11_camp.update(this, store)
	local a = this.attacks
	local afa = a and a.list[1] or nil
	local aa = a and a.list[2] or nil
	local last_shooter = 2
	local nests = find_all_t(store, this.nest_t)

	table.sort(nests, function(v1, v2)
		return v1.nest_id < v2.nest_id
	end)

	this._target_nest_id = -1

	local function shoot_arrow(attack, pos, shooter, enemy, af, egg)
		local b = E:create_entity(attack.bullet)
		local boffset = aa.bullet_start_offset
		local hoffset = enemy and V.vclone(enemy.unit.hit_offset) or v(0, 0)

		b.pos.x = this.pos.x + shooter.offset.x + boffset.x * (not af and 1 or -1)
		b.pos.y = this.pos.y + shooter.offset.y + boffset.y
		b.bullet.from = V.vclone(b.pos)
		b.bullet.to = V.v(pos.x + hoffset.x, pos.y + hoffset.y)
		b.bullet.source_id = this.id

		if enemy then
			b.bullet.target_id = enemy.id
			b.bullet.damage_factor = this.tower.damage_factor
		elseif egg then
			b.bullet.target_id = egg.id
		end

		if b.bullet.fixed_height then
			b.bullet.flight_time = 2 * (math.sqrt(2 * b.bullet.fixed_height * b.bullet.g * -1) / b.bullet.g * -1)
		end

		queue_insert(store, b)
	end

	if not this.hand_insert then
		scripts.tower_stage_11_camp.on_level_up(this, store, this.tower.level, false)
	end

	local archer_flip_ts = {
		store.tick_ts,
		store.tick_ts - math.random(1, 9)
	}
	local fire_arrow_ts = store.tick_ts

	while true do
		if this.tower.level == 3 and not this.destruction_sequence then
			if this._target_nest_id ~= -1 and not this.arrow_in_cooldown then
				this.arrow_in_cooldown = true
				fire_arrow_ts = store.tick_ts
				last_shooter = last_shooter == 2 and 1 or 2

				local shooter = this.render.sprites[last_shooter + 1]

				this.fire_arrow_shooter = last_shooter + 1

				local nest = nests[this._target_nest_id]
				local nest_pos = nest.pos
				local af = true

				if nest_pos.x > this.pos.x + shooter.offset.x then
					af = false
				end

				nest.current_egg.time_to_spawn = 1e+99

				U.animation_start(this, shooter.shoot, af, store.tick_ts, false, last_shooter + 1)
				U.y_wait(store, afa.shoot_time)
				S:queue(afa.sound_shoot)
				S:queue(afa.sound)
				shoot_arrow(afa, nest_pos, shooter, nil, af, nest.current_egg)

				this.fire_arrow_firing = -1
				this._target_nest_id = -1

				signal.emit("protein-rich")
			end

			if store.tick_ts - aa.ts > aa.cooldown then
				local pred_time = aa.shoot_time
				local trigger_enemy, _, pred_pos = U.find_foremost_enemy(store.entities, tpos(this), 0, a.range, pred_time, aa.vis_flags, aa.vis_bans, function(e, o)
					local nodes_vel = e.motion.max_speed / 5.5
					local nodes_in_fly_time = nodes_vel * aa.pred_time
					local nodes_to_end = P:nodes_to_goal(e.nav_path.pi, e.nav_path.spi, e.nav_path.ni)

					return nodes_in_fly_time < nodes_to_end
				end)
				local final_enemy, final_pos, shooter, b, boffset, hoffset, af

				if not trigger_enemy then
					SU.delay_attack(store, aa, fts(10))

					goto label_1226_0
				end

				final_pos = V.vclone(pred_pos)
				last_shooter = last_shooter == 2 and 1 or 2
				aa.ts = store.tick_ts
				shooter = this.render.sprites[last_shooter + 1]
				this.arrow_shooter = last_shooter + 1
				af = true

				if trigger_enemy.pos.x > this.pos.x + shooter.offset.x then
					af = false
				end

				U.animation_start(this, shooter.shoot, af, store.tick_ts, false, last_shooter + 1)
				U.y_wait(store, aa.shoot_time)

				final_enemy = trigger_enemy

				if not final_enemy or final_enemy.health and final_enemy.health.dead then
					final_enemy, _, pred_pos = U.find_foremost_enemy(store.entities, tpos(this), 0, a.range, false, aa.vis_flags, aa.vis_bans)

					if final_enemy then
						final_pos = V.vclone(pred_pos)
					end
				end

				shoot_arrow(aa, final_pos, shooter, final_enemy, af, nil)
				U.y_animation_wait(this, last_shooter + 1)

				this.arrow_shooter = -1
			end

			for i, ts in ipairs(archer_flip_ts) do
				if store.tick_ts - ts > this.flip_time then
					if math.random() > 0.5 then
						this.render.sprites[i + 1].flip_x = not this.render.sprites[i + 1].flip_x
					end

					archer_flip_ts[i] = store.tick_ts
				end
			end

			::label_1226_0::

			if store.tick_ts - fire_arrow_ts > this.attacks.list[1].cooldown then
				this.arrow_in_cooldown = false
			end
		end

		coroutine.yield()
	end
end

function scripts.tower_stage_11_camp.remove(this, store)
	return true
end

scripts.controller_stage_11_loss = {}

function scripts.controller_stage_11_loss.update(this, store)
	local tents_f = find_all_t(store, this.camp_tents_f_t)[1]
	local tents_b = find_all_t(store, this.camp_tents_b_t)[1]

	while true do
		if this.defeat_cinematic and this.normal_defeat then
			local camp = find_all_t(store, this.camp_prefix_t, true)[1]

			camp.destruction_sequence = true

			signal.emit("show-curtains")
			signal.emit("hide-gui")
			signal.emit("start-cinematic")
			signal.emit("pan-zoom-camera", 1.5, {
				x = camp.pos.x,
				y = camp.pos.y + 70
			}, OVm(1, 1.5))
			U.y_wait(store, 1)
			S:queue(this.sound_events.destroyed_start)

			local anim = camp.tower.level == 3 and "defeat2" or "defeat1"

			U.animation_start(camp, anim, nil, store.tick_ts, nil, 1)
			U.y_wait(store, fts(22))
			S:stop(this.sound_events.destroyed_start)
			S:queue(this.sound_events.destroyed_end)

			camp.render.sprites[2].hidden = true
			camp.render.sprites[3].hidden = true

			U.y_wait(store, fts(58))

			store.ephemeral.defeat_cinematic = nil

			signal.emit("end-cinematic")

			store.game_outcome = nil
			store.lives = 0

			queue_remove(store, this)

			return
		end

		if this.defeat_cinematic and this.sarelgaz_defeat then
			local camp = find_all_t(store, this.camp_prefix_t, true)[1]
			local boss = find_all_t(store, this.boss_t)[1]

			camp.destruction_sequence = true

			signal.emit("boss_fight_end")
			signal.emit("show-curtains")
			signal.emit("hide-gui")
			signal.emit("start-cinematic")

			store.game_outcome = {}
			store.lives = 0

			local af = false

			if camp.pos.x - boss.pos.x < 0 then
				af = true
			end

			U.animation_start(boss, "idle", af, store.tick_ts, false, 1)
			U.unblock_all(store, boss)

			boss.vis.bans = F_ALL
			boss.ui.can_click = false
			boss.ui.can_hover = false
			boss.health_bar.hidden = true

			signal.emit("pan-zoom-camera", 1.5, {
				x = camp.pos.x,
				y = camp.pos.y + 70
			}, OVm(1, 1.5))
			U.y_wait(store, 1)

			for i = 1, this.boss_kill_tent_strikes do
				U.animation_start(boss, "attack", af, store.tick_ts, false, 1)
				U.y_wait(store, boss.melee.attacks[1].hit_time)
				S:queue(this.sound_events.hit_camp)

				if i == this.boss_kill_tent_strikes then
					U.animation_start(tents_f, "hit3", nil, store.tick_ts, nil, 1)
					U.animation_start(tents_b, "hit3", nil, store.tick_ts, nil, 1)
				else
					U.animation_start(tents_f, "hit" .. camp.damage_state, nil, store.tick_ts, nil, 1)
					U.animation_start(tents_b, "hit" .. (camp.damage_state == 1 and "" or camp.damage_state), nil, store.tick_ts, nil, 1)
				end

				camp.damage_state = km.clamp(1, 3, camp.damage_state + 1)

				U.y_wait(store, 0.3)
			end

			camp.damage_state = 3

			for i, v in ipairs(this.rappels_ending) do
				local sp = E:create_entity(this.spawner_t)

				sp.pos.x, sp.pos.y = v[2].x, v[2].y
				sp.spawner_id = 4 + i

				queue_insert(store, sp)
			end

			local spawning = find_all_t(store, "controller_stage_11_spider_rappel_spawning")[1]

			coroutine.yield()

			spawning.cache_invalidated = true

			coroutine.yield()
			S:queue(this.sound_events.destroyed)

			local anim = camp.tower.level == 3 and "defeat2" or "defeat1"

			U.animation_start(camp, anim, nil, store.tick_ts, nil, 1)
			U.y_wait(store, fts(22))

			camp.render.sprites[2].hidden = true
			camp.render.sprites[3].hidden = true

			for i, v in ipairs(this.rappels_ending) do
				scripts.controller_remote_balance_rappel_spawning.on_event(spawning, store, "spider_rappel", 4 + i, v[1], math.random(1, 3))
				U.y_wait(store, 0.15)
			end

			U.animation_start(boss, "jump", nil, store.tick_ts, nil, 1)
			U.y_wait(store, boss.wait_for_ascend_decal)

			local ascent = E:create_entity(boss.ascend_decal)

			ascent.pos.x, ascent.pos.y = boss.pos.x, boss.pos.y
			ascent.render.sprites[1].ts = store.tick_ts

			queue_insert(store, ascent)
			U.y_wait(store, 1.5)

			store.ephemeral.defeat_cinematic = nil

			signal.emit("end-cinematic")

			store.game_outcome = nil
			store.lives = 0

			queue_remove(store, this)

			return
		end

		coroutine.yield()
	end
end

scripts.controller_stage_11_camp_barrack = {}

function scripts.controller_stage_11_camp_barrack.insert(this, store)
	this.barrack.rally_pos = this.default_rally_pos

	return true
end

function scripts.controller_stage_11_camp_barrack.update(this, store)
	local b = this.barrack

	while true do
		for i = 1, b.max_soldiers do
			local s = b.soldiers[i]

			if not s or s.health.dead and not store.entities[s.id] then
				s = E:create_entity(b.soldier_type)
				s.soldier.tower_id = this.id
				s.soldier.tower_soldier_idx = i
				s.pos = V.v(V.add(this.pos.x, this.pos.y, b.respawn_offset.x, b.respawn_offset.y))
				s.nav_rally.pos, s.nav_rally.center = U.rally_formation_position(i, b, b.max_soldiers, math.pi / 4)
				s.nav_rally.new = true

				queue_insert(store, s)

				b.soldiers[i] = s
			end
		end

		coroutine.yield()
	end
end

function scripts.controller_stage_11_camp_barrack.e_insert(this, store)
	local r = E:create_entity("editor_rally_point")

	queue_insert(store, r)

	r.tower_id = this.id
	this.editor.rally_point_id = r.id

	if this.default_rally_pos and this.default_rally_pos.x ~= 0 and this.default_rally_pos.y ~= 0 then
		r.pos = this.default_rally_pos
	else
		r.pos = V.v(this.pos.x + 50, this.pos.y + 50)
		this.default_rally_pos = r.pos
	end

	if this.barrack then
		this.barrack.rally_pos = r.pos
	end

	return true
end

function scripts.controller_stage_11_camp_barrack.e_remove(this, store)
	local r = store.entities[this.editor.rally_point_id]

	if r then
		queue_remove(store, r)
	end

	return true
end

scripts.aura_stage_11_camp_fire_arrow_fire = {}

function scripts.aura_stage_11_camp_fire_arrow_fire.update(this, store, script)
	U.animation_start(this, "hit", nil, store.tick_ts, false, 1)

	local ts = store.tick_ts

	while store.tick_ts - ts < this.aura.duration do
		local targets = table.filter(store.entities, function(k, v)
			return string.match(v.template_name, this.eggs_prefix) and U.is_inside_ellipse(v.pos, this.pos, this.aura.radius)
		end)

		for i, target in ipairs(targets) do
			target.burn = true

			goto label_1236_0
		end

		coroutine.yield()
	end

	::label_1236_0::

	U.y_animation_wait(this, 1)
	queue_remove(store, this)
end

scripts.controller_stage_11_shadows = {}

function scripts.controller_stage_11_shadows.update(this, store, script)
	this._ease = false

	local start_ts
	local torches_durations = this.ease_durations * 0.8

	while true do
		if this._ease and this._ease_from and this._ease_to then
			start_ts = store.tick_ts

			local i = 1
			local torches = find_all_t(store, this.torch_t, false, function(k, v)
				return v.camp_level == this._camp_level
			end)

			local function place_torches(dt, p)
				torches[i].render.sprites[1].hidden = false
				i = km.clamp(1, #torches, i + 1)
			end

			local shadow_out = find_all_t(store, this.shadow_decal_prefix .. "_lvl" .. this._camp_level - 1)[1]
			local shadow_in = find_all_t(store, this.shadow_decal_prefix .. "_lvl" .. this._camp_level)[1]
			local eyes = {}
			local all_eyes = find_all_t(store, "decal_stage_11_spider_eyes_", true, function(k, v)
				return v.template_name ~= "decal_stage_11_spider_eyes_medium" and v.template_name ~= "decal_stage_11_spider_eyes_small" and v.template_name ~= "decal_stage_11_spider_eyes_big"
			end)

			table.append(eyes, all_eyes)

			for _, v in pairs(eyes) do
				queue_remove(store, v)
			end

			if shadow_in then
				shadow_in.render.sprites[1].hidden = false

				U.y_ease_key(store, shadow_in.render.sprites[1], "alpha", 0, 255, this.ease_durations, "quad-in")
			end

			while i < #torches do
				place_torches()
			end

			U.y_wait(store, fts(1))
			U.y_ease_key(store, shadow_out.render.sprites[1], "alpha", 255, 0, this.ease_durations, "quad-in")

			this._ease = false
		end

		coroutine.yield()
	end
end

scripts.aura_stage_11_shadow = {}

function scripts.aura_stage_11_shadow.update(this, store)
	local affected_enemies = {}
	local grid_copy = {}

	this.grid_changeup = true

	local function enemy_invulnerability()
		local targets = table.filter(store.entities, function(k, v)
			return v.enemy and v.unit and v.vis and v.health and not v.health.dead and not affected_enemies[v.id] and band(v.vis.flags, this.aura.vis_bans) == 0 and band(v.vis.bans, this.aura.vis_flags) == 0 and not U.is_inside_ellipse(v.pos, this.pos, this.aura.radius, 0.63)
		end)

		for k, v in pairs(targets) do
			affected_enemies[v.id] = {
				enemy = v
			}
			v._pushed_bans = U.push_bans(v.vis, F_ALL)
		end

		local remove = table.filter(affected_enemies, function(k, v)
			return U.is_inside_ellipse(v.enemy.pos, this.pos, this.aura.radius, 0.63) and v.enemy.unit
		end)

		for k, v in pairs(remove) do
			if v.enemy._pushed_bans then
				U.pop_bans(v.enemy.vis, v.enemy._pushed_bans)

				v.enemy._pushed_bans = nil
			end

			affected_enemies[v.enemy.id] = nil
		end
	end

	local function grid_save()
		local grid_long = #GR.grid
		local grid_tall = #GR.grid[1]

		for i = 1, grid_long do
			if not grid_copy[i] then
				grid_copy[i] = {}
			end

			for j = 1, grid_tall do
				if not grid_copy[i][j] then
					grid_copy[i][j] = {
						GR.grid[i][j]
					}
				else
					grid_copy[i][j] = GR.grid[i][j]
				end
			end
		end
	end

	local function grid_changeup()
		local grid_long = #GR.grid
		local grid_tall = #GR.grid[1]
		local grid_spacing_x = GR.cell_size
		local grid_spacing_y = GR.cell_size

		for i = 0, grid_long - 1 do
			for j = 0, grid_tall - 1 do
				local ul = v(i * grid_spacing_x + GR.ox, (j + 1) * grid_spacing_y + GR.oy)
				local ur = v((i + 1) * grid_spacing_x + GR.ox, (j + 1) * grid_spacing_y + GR.oy)
				local bl = v(i * grid_spacing_x + GR.ox, j * grid_spacing_y + GR.oy)
				local br = v((i + 1) * grid_spacing_x + GR.ox, j * grid_spacing_y + GR.oy)
				local touches_grid = U.is_inside_ellipse(ul, this.pos, this.aura.radius, 0.63) or U.is_inside_ellipse(ur, this.pos, this.aura.radius, 0.63) or U.is_inside_ellipse(bl, this.pos, this.aura.radius, 0.63) or U.is_inside_ellipse(br, this.pos, this.aura.radius, 0.63)

				if not touches_grid then
					GR.grid[i + 1][j + 1] = bor(band(grid_copy[i + 1][j + 1][1], TERRAIN_PROPS_MASK), TERRAIN_FLYING_NOWALK)
				else
					GR.grid[i + 1][j + 1] = grid_copy[i + 1][j + 1][1]
				end
			end
		end
	end

	grid_save()

	while true do
		if this.grid_changeup then
			grid_changeup()

			this.grid_changeup = false
		end

		enemy_invulnerability()
		U.y_wait(store, 0.2)
	end
end

scripts.decal_stage_11_torch = {}

function scripts.decal_stage_11_torch.insert(this, store)
	local l = E:create_entity(this.torch_light_t)

	l.pos.x, l.pos.y = this.pos.x + this.light_offset.x, this.pos.y + this.light_offset.y
	this._torch_light = l

	queue_insert(store, l)

	return true
end

function scripts.decal_stage_11_torch.update(this, store)
	while this.render.sprites[1].hidden do
		coroutine.yield()
	end

	if this.skip_to_loop then
		-- block empty
	else
		this._torch_light.render.sprites[1].hidden = false

		U.animation_start(this, "spawn", nil, store.tick_ts, false, 1)
		U.animation_start(this._torch_light, "spawn", nil, store.tick_ts, false, 1)

		while not U.animation_finished(this, 1) do
			coroutine.yield()
		end
	end

	U.animation_start(this, "loop", nil, store.tick_ts, true, 1)
	U.animation_start(this._torch_light, "loop", nil, store.tick_ts, true, 1)
end

scripts.enemy_boss_stage_11 = {}

function scripts.enemy_boss_stage_11.update(this, store, script)
	local OFF_SCREEN_X, OFF_SCREEN_Y = 512, 1000
	local controller = find_all_t(store, this.controller_t)[1]
	local phase = 1

	this.rose = false
	this.lower_trigger = false

	local reached_end = false
	local defeat_controller = find_all_t(store, "controller_stage_11_loss")[1]

	local function y_land_animation(dest)
		local af = P:node_pos(this.lower_path_id, 1, this.lower_node_id + 1).x - dest.x < 0

		U.animation_start(this, "land", af, store.tick_ts, nil, 1)
		U.y_wait(store, fts(10))

		local sh = E:create_entity(this.shadow_decal)

		sh.pos.x, sh.pos.y = dest.x, dest.y
		sh.render.sprites[1].name = "land"
		sh.render.sprites[1].ts = store.tick_ts

		queue_insert(store, sh)
		U.y_wait(store, fts(4))
		queue_remove(store, sh)

		local shake = E:create_entity("aura_screen_shake")

		shake.aura.amplitude = 0.5
		shake.aura.duration = 0.5
		shake.aura.freq_factor = 1

		queue_insert(store, shake)
		U.y_animation_wait(this, 1)
	end

	local function y_on_death()
		S:stop_all()
		W:stop_manual_wave("BOSS3")
		S:queue(this.sound_events.death)
		U.animation_start(this, "death", nil, store.tick_ts, false)
		LU.kill_all_enemies(store, true)
		U.y_animation_wait(this)
		signal.emit("boss-killed", this)

		this.bossfight_ended = true
	end

	local function y_check_phase_out()
		if phase <= #this.phases_health_thresholds and this.health.hp < this.health.hp_max * this.phases_health_thresholds[phase] then
			W:stop_manual_wave("BOSS" .. phase)

			phase = phase + 1

			W:start_manual_wave("BOSS" .. phase)
			U.animation_start(this, "jump", nil, store.tick_ts, nil, 1)
			U.y_wait(store, this.wait_for_ascend_decal)
			U.unblock_all(store, this)
			SU.remove_modifiers(store, this)

			local old_flags = this.vis.flags

			this._rise_pushed_bans = U.push_bans(this.vis, F_ALL)
			this.vis.flags = F_BOSS
			this.ui.can_click = false
			this.ui.can_hover = false
			this.health.ignore_damage = true

			if game.game_gui.selected_entity and game.game_gui.selected_entity.id == this.id then
				signal.emit("hide-bottom-info")
			end

			this.health_bar.hidden = true

			local ascent = E:create_entity(this.ascend_decal)

			ascent.pos.x, ascent.pos.y = this.pos.x, this.pos.y
			ascent.render.sprites[1].ts = store.tick_ts

			queue_insert(store, ascent)

			this.rose = true
			this.pos.x, this.pos.y = OFF_SCREEN_X, OFF_SCREEN_Y
			this.render.sprites[1].hidden = true

			U.y_wait(store, 2)

			controller._spawn_eggs = true

			while not this.lower_trigger or controller.in_use do
				coroutine.yield()
			end

			this.rose = false
			this.lower_trigger = false
			controller._spawn_eggs = false
			this.motion.forced_waypoint = nil

			local dest = P:node_pos(this.lower_path_id, 1, this.lower_node_id)

			this.nav_path.pi = this.lower_path_id
			this.nav_path.spi = 1
			this.nav_path.ni = this.lower_node_id
			this.pos.x, this.pos.y = dest.x, dest.y

			if this._rise_pushed_bans then
				U.pop_bans(this.vis, this._rise_pushed_bans)

				this._rise_pushed_bans = nil
			end

			this.vis.flags = old_flags
			this.health_bar.hidden = false
			this.render.sprites[1].hidden = false
			this.ui.can_click = true
			this.ui.can_hover = true
			this.health.ignore_damage = false

			y_land_animation(dest)

			return true
		end

		return false
	end

	local function loss_check()
		local pos_close = this.loss_positions[this.nav_path.pi]
		local n = P:nearest_nodes(pos_close.x, pos_close.y, {
			this.nav_path.pi
		}, {
			1
		}, true)[1][3]

		if n <= this.nav_path.ni then
			store.game_outcome = {}
			store.ephemeral.defeat_cinematic = true
			defeat_controller.defeat_cinematic = true
			defeat_controller.sarelgaz_defeat = true
			reached_end = true

			return true
		end

		return false
	end

	local function break_fn()
		return loss_check() or y_check_phase_out()
	end

	y_land_animation(this.pos)

	while not reached_end do
		if this.health.dead then
			y_on_death()

			while true do
				U.y_wait(store, fts(10))
				LU.kill_all_enemies(store, true)
			end

			return
		end

		if not SU.y_enemy_mixed_walk_melee_ranged(store, this, false, break_fn, break_fn) then
			-- block empty
		else
			coroutine.yield()
		end
	end

	while reached_end do
		coroutine.yield()
	end
end

scripts.controller_stage_11_boss_lower = {}

function scripts.controller_stage_11_boss_lower.on_event(this, store, action, path_id, node_id)
	local boss = find_all_t(store, this.boss_t)[1]

	if not boss.rose then
		return
	end

	local controller = find_all_t(store, this.controller_t)[1]

	controller.lower_trigger = true
	controller.lower_path_id = tonumber(path_id)
	controller.lower_node_id = tonumber(node_id)

	log.info("Received event boss_lower, data: %s, %s", controller.lower_path_id, controller.lower_node_id)
end

scripts.controller_stage_11_spider_eyes_decos = {}

function scripts.controller_stage_11_spider_eyes_decos.update(this, store, script)
	local function spawn_eyes(t, p)
		local eyes = E:create_entity(t)

		eyes.pos = V.vclone(p)
		eyes.render.sprites[1].ts = store.tick_ts

		queue_insert(store, eyes)
	end

	local function y_run_sequence(sequence)
		if not sequence then
			return
		end

		while #sequence > 0 do
			local s_roll = math.random(1, #sequence)
			local si = sequence[s_roll]
			local side = si[1]
			local swarms = si[2]
			local severals = si[3]
			local singles = si[4]
			local positions = this.swarm_positions[side]
			local roll = math.random(1, swarms + severals + singles)
			local e

			if roll <= swarms then
				e = this.swarm_t
				si[2] = si[2] - 1
			elseif swarms < roll and roll <= swarms + severals then
				e = this.several_t
				si[3] = si[3] - 1
			elseif roll > swarms + severals and roll <= swarms + severals + singles then
				e = this.single_t
				si[4] = si[4] - 1
			end

			local p = positions[math.random(1, #positions)]

			spawn_eyes(e, p)
			U.y_wait(store, math.random(this.wait_min, this.wait_max))

			if si[2] + si[3] + si[4] == 0 then
				table.remove(sequence, s_roll)
			end
		end
	end

	this.swarm_positions = {}

	for k, v in pairs(this.swarm_boxes) do
		this.swarm_positions[k] = generate_blue_noise_cluster(20, 15, random_point_in_rectangle, v[1].x, v[1].y, v[2].x, v[2].y)
	end

	local in_sequence = false
	local last_wave = store.wave_group_number
	local ts = store.tick_ts
	local cd = math.random(this.pre_battle_periodic_eyes_min, this.pre_battle_periodic_eyes_max)
	local phase = 1

	while true do
		if phase == 1 and store.wave_group_number >= this.waves_phases[1] then
			phase = 2
			this.swarm_positions = {}

			for k, v in pairs(this.swarm_boxes_phase2) do
				this.swarm_positions[k] = generate_blue_noise_cluster(20, 15, random_point_in_rectangle, v[1].x, v[1].y, v[2].x, v[2].y)
			end
		end

		if store.wave_group_number ~= last_wave and not in_sequence then
			in_sequence = true

			local sequence = this.spawn_sequence[store.wave_group_number]

			y_run_sequence(sequence)

			in_sequence = false
		end

		if store.wave_group_number == 0 and cd < store.tick_ts - ts then
			local sides = {
				"left",
				"bottom",
				"right",
				"top"
			}
			local side = sides[math.random(#sides)]
			local fake_sequence = {
				{
					side,
					0,
					0,
					math.random(1, 3)
				}
			}

			y_run_sequence(fake_sequence)

			ts = store.tick_ts
			cd = math.random(this.pre_battle_periodic_eyes_min, this.pre_battle_periodic_eyes_max)
		end

		if cd < store.tick_ts - ts and store.wave_group_number > 0 and store.wave_group_number < this.waves_phases[1] then
			local side = this.periodic_sequence[store.wave_group_number][math.random(#this.periodic_sequence[store.wave_group_number])]
			local fake_sequence = {
				{
					side,
					0,
					0,
					math.random(1, 3)
				}
			}

			y_run_sequence(fake_sequence)

			ts = store.tick_ts
			cd = math.random(this.periodic_eyes_min, this.periodic_eyes_max)
		end

		last_wave = store.wave_group_number

		coroutine.yield()
	end
end

scripts.controller_stage_12_elevator = {}

function scripts.controller_stage_12_elevator.insert(this, store)
	if not this.elevator then
		log.error("There is no elevator, spawning one")

		local e = E:create_entity(this.elevator_t)

		e.pos.x, e.pos.y = 512, 384
		this.elevator = e

		queue_insert(store, e)
	end

	this.mask1 = find_all_t(store, this.elevator_mask_1_t)[1]
	this.mask2 = find_all_t(store, this.elevator_mask_2_t)[1]

	return true
end

function scripts.controller_stage_12_elevator.update(this, store)
	local right_pos_elevator, left_pos_elevator = this.elevator.pos.x, this.elevator.pos.x + this.left_offset_x
	local left_pos_mask_1, left_pos_mask_2, right_pos_mask_1, right_pos_mask_2

	local function deal_area_damage(hit_pos)
		local targets = U.find_soldiers_in_range(store.entities, hit_pos, 0, this.elevator.crush.damage_radius, this.elevator.crush.vis_flags, this.elevator.crush.vis_bans)

		if targets then
			for i, e in ipairs(targets) do
				local d = E:create_entity("damage")

				d.source_id = this.id
				d.target_id = e.id
				d.damage_type = DAMAGE_TRUE
				d.value = 1e+99

				queue_damage(store, d)
			end
		end
	end

	local lowered = false

	while true do
		if not this.mask1 then
			this.mask1 = find_all_t(store, this.elevator_mask_1_t)[1]
			right_pos_mask_1 = this.mask1.pos.x
			left_pos_mask_1 = this.mask1.pos.x + this.left_offset_x
		end

		if not this.mask2 then
			this.mask2 = find_all_t(store, this.elevator_mask_2_t)[1]
			right_pos_mask_2 = this.mask2.pos.x
			left_pos_mask_2 = this.mask2.pos.x + this.left_offset_x
		end

		if this.lower and not lowered then
			lowered = true
			this.elevator.render.sprites[1].hidden = false
			this.elevator.render.sprites[1].z = Z_OBJECTS_COVERS + 1

			if this.elevator_flip then
				this.elevator.pos.x = left_pos_elevator
				this.mask1.pos.x = left_pos_mask_1
				this.mask2.pos.x = left_pos_mask_2
			else
				this.elevator.pos.x = right_pos_elevator
				this.mask1.pos.x = right_pos_mask_1
				this.mask2.pos.x = right_pos_mask_2
			end

			U.animation_start(this.elevator, "start", this.elevator_flip, store.tick_ts, false, 1)
			S:queue(this.sound_events.creaks)
			U.y_wait(store, fts(35))
			S:queue(this.sound_events.creaks)
			U.y_wait(store, fts(41))
			S:queue(this.sound_events.creaks)
			U.y_wait(store, fts(56))
			S:queue(this.sound_events.creaks)
			U.y_wait(store, fts(31))
			S:queue(this.sound_events.land)
			deal_area_damage(this.elevator.crush.hit_pos)
			U.y_wait(store, fts(1))

			this.elevator.render.sprites[1].z = Z_OBJECTS
			this.mask1.render.sprites[1].hidden = false
			this.mask1.render.sprites[1].flip_x = this.elevator_flip
			this.mask2.render.sprites[1].hidden = false
			this.mask2.render.sprites[1].flip_x = this.elevator_flip

			if this.elevator_flip then
				P:activate_path(this.path_r)

				this._last_activated_path = this.path_r
			else
				P:activate_path(this.path_l)

				this._last_activated_path = this.path_l
			end

			U.y_animation_wait(this.elevator, 1)
			U.animation_start(this.elevator, "idle", this.elevator_flip, store.tick_ts, true, 1)

			this.lower = false
		end

		if this.rise and lowered then
			lowered = false
			this.mask1.render.sprites[1].hidden = true
			this.mask2.render.sprites[1].hidden = true

			P:deactivate_path(this._last_activated_path)

			local path_enemies = table.filter(store.entities, function(k, v)
				return v.nav_path and v.nav_path.pi == this._last_activated_path
			end)

			for _, e in pairs(path_enemies) do
				local npi = this._last_activated_path == 8 and 12 or 13
				local nn = P:nearest_nodes(e.pos.x, e.pos.y, {
					npi
				}, {
					1,
					2,
					3
				}, true)

				e.nav_path.pi = nn[1][1]
				e.nav_path.ni = nn[1][3]
			end

			U.animation_start(this.elevator, "leave", this.elevator_flip, store.tick_ts, false, 1)
			U.y_wait(store, fts(71))
			S:queue(this.sound_events.out)
			U.y_wait(store, fts(32))

			this.elevator.render.sprites[1].z = Z_OBJECTS_COVERS + 1

			U.y_animation_wait(this.elevator, 1)

			this.elevator.render.sprites[1].hidden = true
			this.rise = false
		end

		coroutine.yield()
	end
end

function scripts.controller_stage_12_elevator.on_lower_event(this, store, action, direction)
	if direction == nil or direction ~= "l" and direction ~= "left" and direction ~= "r" and direction ~= "right" then
		direction = "r"

		log.error("ERROR: Elevator on lower event wrong direction naming. Defaulting to \"right\" direction.")
	end

	this.lower = true

	if direction == "r" or direction == "right" then
		this.elevator_flip = false
	elseif direction == "l" or direction == "left" then
		this.elevator_flip = true
	end
end

function scripts.controller_stage_12_elevator.on_rise_event(this, store, action)
	this.rise = true
end

scripts.decal_stage_12_troll_warrior_rappel_spawn = {}

function scripts.decal_stage_12_troll_warrior_rappel_spawn.update(this, store, script)
	local start_y = store.visible_coords and store.visible_coords.top or REF_H
	local shadow, string, max_height = scripts.decal_rappel_utils.y_descend(this, store)

	string.dissolve = true

	local sp = E:create_entity(this.spawn_t)

	sp.pos.x, sp.pos.y = this.target_pos.x, this.target_pos.y
	sp.render.sprites[1].flip_x = this.render.sprites[1].flip_x
	sp.nav_path.pi = this.pi
	sp.nav_path.spi = this.spi
	sp.nav_path.ni = this.ni

	queue_insert(store, sp)
	queue_remove(store, shadow)
	queue_remove(store, this)
end

scripts.decal_stage_12_torch = {}

function scripts.decal_stage_12_torch.update(this, store)
	local old_anim = this.render.sprites[1].name

	while true do
		if this.ui.clicked then
			U.y_animation_play(this, this.anim_on_tap, nil, store.tick_ts, 1, 1)
			U.animation_start(this, old_anim, nil, store.tick_ts, true, 1)

			this.ui.clicked = false
		end

		coroutine.yield()
	end
end

scripts.decal_stage_12_trollcito = {}

function scripts.decal_stage_12_trollcito.update(this, store)
	local clicks = 0

	while true do
		if this.ui and this.ui.clicked then
			this.ui.clicked = false
			clicks = clicks + 1

			if clicks == 1 then
				U.y_animation_play(this, "click_1", nil, store.tick_ts, 1, 1)
				U.animation_start(this, "idle_2", nil, store.tick_ts, true, 1)
			elseif clicks == 2 then
				U.y_animation_play(this, "click_2", nil, store.tick_ts, 1, 1)
				U.animation_start(this, "idle_1", nil, store.tick_ts, true, 1)

				clicks = 0
			end
		end

		coroutine.yield()
	end
end

scripts.decal_stage_12_campfire = {}

function scripts.decal_stage_12_campfire.update(this, store)
	local clicks = 0

	while true do
		if this.ui and this.ui.clicked then
			this.ui.clicked = false
			clicks = clicks + 1

			if clicks == 1 or clicks == 2 then
				U.y_animation_play(this, "click_1_y_2", nil, store.tick_ts, 1, 1)
				U.animation_start(this, "idle_1_2_y_3", nil, store.tick_ts, true, 1)
			elseif clicks == 3 then
				U.y_animation_play(this, "click_3", nil, store.tick_ts, 1, 1)
				U.animation_start(this, "idle_4", nil, store.tick_ts, true, 1)

				return
			end
		end

		coroutine.yield()
	end
end

scripts.decal_stage_12_vase = {}

function scripts.decal_stage_12_vase.update(this, store)
	while true do
		if this.ui and this.ui.clicked then
			this.ui.clicked = false

			local tracker = find_all_t(store, this.achievement_tracker)[1]

			if tracker then
				tracker.broken_vases = tracker.broken_vases + 1
			end

			S:queue(this.sound_click)
			U.y_animation_play(this, "click", nil, store.tick_ts, 1, 1)

			return
		end

		coroutine.yield()
	end
end

scripts.controller_stage_12_wreak_havoc_achievement = {}

function scripts.controller_stage_12_wreak_havoc_achievement.update(this, store)
	local total_vases = #find_all_t(store, this.vase_t, true)

	if total_vases > 0 then
		while total_vases > this.broken_vases do
			coroutine.yield()
		end

		signal.emit("wreak-havoc-stage12")
	end

	queue_remove(store, this)
end

scripts.controller_stage_13_sunray_tower_health = {}

function scripts.controller_stage_13_sunray_tower_health.update(this, store, script)
	this.current_health_boss_hits = this.health_boss_hits

	while true do
		if this.current_health_boss_hits <= 0 then
			local tower = find_all_t(store, this.broken_sunray_tower_t)[1]

			tower = tower or find_all_t(store, this.sunray_tower_t)[1]

			signal.emit("show-curtains")
			signal.emit("hide-gui")
			signal.emit("start-cinematic")
			signal.emit("pan-zoom-camera", 1.5, {
				x = tower.pos.x,
				y = tower.pos.y + 70
			}, OVm(1, 1.5))
			U.y_wait(store, 3)
			signal.emit("end-cinematic")

			store.lives = 0

			queue_remove(store, this)

			return
		end

		coroutine.yield()
	end
end

scripts.controller_stage_13_spawn_sorcerer = {}

function scripts.controller_stage_13_spawn_sorcerer.queue_sorcerer(this, store, path_no_boss)
	local boss = find_all_t(store, this.boss_t)[1]
	local spot, boss_spawn

	if not boss or not boss.on_ground then
		spot = this._tower.determine_spot_for_sorcerer(path_no_boss)
	else
		spot = this._tower.determine_spot_for_sorcerer(boss.nav_path.pi == this.boss_left_path and this.right_path or this.left_path)
		boss_spawn = boss.nav_path.pi
	end

	if not spot then
		return
	end

	table.insert(this.to_spawn, {
		spot,
		boss_spawn
	})

	this.sorcerer_spawn_ts = store.tick_ts
end

function scripts.controller_stage_13_spawn_sorcerer.update(this, store, script)
	if not this._tower then
		this._tower = find_all_t(store, this.tower_t)[1]
	end

	local count = 0

	this.sorcerer_spawn_ts = store.tick_ts
	this.to_spawn = {}

	while true do
		if this.automatic_spawning and store.tick_ts - this.sorcerer_spawn_ts >= this.sorcerer_spawn_time then
			log.paranoid("SORCERER SPAWN FROM AUTOMATIC SPAWN.")
			scripts.controller_stage_13_spawn_sorcerer.queue_sorcerer(this, store, count % 2 == 0 and this.left_path or this.right_path)
		end

		if #this.to_spawn > 0 then
			local sp = table.remove(this.to_spawn, 1)
			local sorc_preamble
			local left = false

			if sp[2] == nil then
				if this._tower.spot_is_left_side(sp[1]) then
					left = true
				else
					left = false
				end
			elseif sp[2] == this.boss_left_path then
				left = false
			else
				left = true
			end

			sorc_preamble = E:create_entity(this.sorcerer_preamble_prefix .. (left and "_left" or "_right"))
			sorc_preamble.pos = this.spawn_sorcerer_preamble_pos
			sorc_preamble.render.sprites[1].ts = store.tick_ts

			queue_insert(store, sorc_preamble)
			U.y_animation_wait(sorc_preamble, 1)

			local door_light = E:create_entity(this.sorcerer_door_light_t .. (left and "_left" or "_right"))

			door_light.pos.x, door_light.pos.y = 512, 384
			door_light.tween.ts = store.tick_ts

			queue_insert(store, door_light)
			U.y_wait(store, this.sorcerer_door_wait - door_light.tween.props[1].keys[2][1])

			door_light.tween.disabled = true

			queue_remove(store, door_light)
			U.y_wait(store, door_light.tween.props[1].keys[2][1])

			if sp[2] == nil then
				this._tower.spawn_sorcerer(sp[1])
			else
				this._tower.spawn_sorcerer(sp[1], sp[2] == this.boss_left_path and "ov_right" or "ov_left")
			end

			count = count + 1
		end

		coroutine.yield()
	end
end

function scripts.controller_stage_13_spawn_sorcerer.on_spawn_event(this, store, action, path_id)
	log.info("EVENT SORCERER SPAWN. Path: " .. path_id)

	if not this._tower then
		this._tower = find_all_t(store, this.tower_t)[1]
	end

	local number_path_id = tonumber(path_id)

	scripts.controller_stage_13_spawn_sorcerer.queue_sorcerer(this, store, number_path_id)
end

function scripts.controller_stage_13_spawn_sorcerer.on_activate_automatic_event(this, store, action)
	this.automatic_spawning = true
	this.sorcerer_spawn_ts = store.tick_ts

	log.info("ACTIVATED AUTOMATIC SORCERER SPAWNING.")
end

function scripts.controller_stage_13_spawn_sorcerer.on_deactivate_automatic_event(this, store, action)
	this.automatic_spawning = false
	this.sorcerer_spawn_ts = store.tick_ts

	log.info("DE-ACTIVATED AUTOMATIC SORCERER SPAWNING.")
end

scripts.tower_stage_13_broken_sunray_obelisk = {}

function scripts.tower_stage_13_broken_sunray_obelisk.update(this, store, script)
	this.tower.blocked = true
	this.tower.can_hover = false
	this.ui.can_click = false
	this.ui.can_hover = false

	while not this.summoned do
		coroutine.yield()
	end

	U.y_animation_play(this, this.appear_anim, nil, store.tick_ts, 1, 1)

	this.tower.blocked = false
	this.tower.can_hover = true
	this.ui.can_click = true
	this.ui.can_hover = true

	while true do
		coroutine.yield()
	end
end

scripts.tower_stage_13_sunray_tower = {}

function scripts.tower_stage_13_sunray_tower.insert(this, store, script)
	return true
end

function scripts.tower_stage_13_sunray_tower.update(this, store, script)
	local obelisks
	local health_controller = find_all_t(store, this.controller_health)[1]
	local sorcerer_spawn_ts = store.tick_ts
	local charge_acum = 0
	local started_charging_once = false
	local charged_last_frame = false
	local charging_last_frame = false
	local is_shooting = false
	local ray_decal, last_shake

	this.sorcerers = {
		{
			nil,
			v(this.pos.x + this.sorcerer_slots_offsets[1].x, this.pos.y + this.sorcerer_slots_offsets[1].y),
			true,
			false,
			true
		},
		{
			nil,
			v(this.pos.x + this.sorcerer_slots_offsets[2].x, this.pos.y + this.sorcerer_slots_offsets[2].y),
			true,
			false,
			false
		},
		{
			nil,
			v(this.pos.x + this.sorcerer_slots_offsets[3].x, this.pos.y + this.sorcerer_slots_offsets[3].y),
			false,
			false,
			true
		},
		{
			nil,
			v(this.pos.x + this.sorcerer_slots_offsets[4].x, this.pos.y + this.sorcerer_slots_offsets[4].y),
			false,
			false,
			false
		}
	}

	local function count_charging_sorcerers(left)
		return #table.filter(this.sorcerers, function(k, v)
			return v[1] ~= nil and (left == nil or left == v[3])
		end)
	end

	local function animation_start_all(e, anim, flip_x, ts, loop)
		U.animation_start(e, anim, flip_x, ts, loop, 1)
		U.animation_start(e, anim, flip_x, ts, loop, 2)
	end

	local function y_animation_play_all(e, anim, flip_x, ts)
		animation_start_all(e, anim, flip_x, ts, false)

		while not U.animation_finished(e, 1) and not U.animation_finished(e, 2) do
			coroutine.yield()
		end
	end

	local function is_charged()
		return charge_acum >= this.sunray.points_to_charge
	end

	local function spot_is_left_side(spot)
		return this.sorcerers[spot][3]
	end

	local function spot_open(spot)
		return this.sorcerers[spot][1] == nil and not this.sorcerers[spot][4]
	end

	local function determine_spot_for_sorcerer(path_id)
		local left = path_id == this.left_path
		local spot
		local left_spaces = #table.filter(this.sorcerers, function(k, v)
			return v[3] and not v[1] and not v[4]
		end)
		local right_spaces = #table.filter(this.sorcerers, function(k, v)
			return not v[3] and not v[1] and not v[4]
		end)

		for i, v in ipairs(this.sorcerers) do
			if left then
				if left_spaces > 0 then
					if not this.sorcerers[i][1] and not this.sorcerers[i][4] and this.sorcerers[i][3] then
						spot = i

						break
					end
				elseif right_spaces > 0 and not this.sorcerers[i][1] and not this.sorcerers[i][4] and not this.sorcerers[i][3] then
					spot = i

					break
				end
			elseif right_spaces > 0 then
				if not this.sorcerers[i][1] and not this.sorcerers[i][4] and not this.sorcerers[i][3] then
					spot = i

					break
				end
			elseif left_spaces > 0 and not this.sorcerers[i][1] and not this.sorcerers[i][4] and this.sorcerers[i][3] then
				spot = i

				break
			end
		end

		if spot then
			this.sorcerers[spot][4] = true
		end

		return spot
	end

	local function spawn_sorcerer(spot, override)
		if not spot then
			log.info("Tried to spawn an extra sorcerer (we already have %s). Spawning cancelled.", this.sunray.sorcerers_to_charge)

			return
		end

		local left = not override and spot_is_left_side(spot) or override == "ov_left"
		local path = left and this.left_path or this.right_path
		local sorcerer = E:create_entity(this.sunray.sorcerer_t)

		sorcerer.pos = P:node_pos(path, 1, 1)
		sorcerer.path_id = path
		sorcerer.left_path = left
		sorcerer.is_top = this.sorcerers[spot][5]
		sorcerer.ritual_spot = spot
		sorcerer.final_destination = this.sorcerers[sorcerer.ritual_spot][2]

		queue_insert(store, sorcerer)
		log.info("Summoned sorcerer. Left path: %s, path id: %s, Ritual spot: %s, destination: %s", sorcerer.left_path, sorcerer.path_id, sorcerer.ritual_spot, getfulldump(sorcerer.final_destination, 2))
	end

	local function on_sorcerer_arrived(sorc)
		this.sorcerers[sorc.ritual_spot][1] = sorc
		this.sorcerers[sorc.ritual_spot][4] = false

		log.info("Sorcerer arrived on spot %s.", sorc.ritual_spot)

		sorc.raise_arms = charge_acum < this.sunray.points_to_charge and count_charging_sorcerers() >= this.sunray.sorcerers_to_charge
	end

	local function is_charging()
		return count_charging_sorcerers() >= this.sunray.sorcerers_to_charge
	end

	local function has_sorcerers(left)
		if left == nil then
			return count_charging_sorcerers() > 0
		end

		return count_charging_sorcerers(left) > 0
	end

	local function get_sorcerer_position(is_left)
		if count_charging_sorcerers() <= 0 then
			return nil
		end

		if is_left and count_charging_sorcerers(true) <= 0 then
			is_left = not is_left
		end

		if not is_left and count_charging_sorcerers(false) <= 0 then
			is_left = not is_left
		end

		local sorcerers_per_side = #this.sorcerers / 2
		local start = is_left and 1 or sorcerers_per_side + 1
		local ending = is_left and #this.sorcerers - sorcerers_per_side or #this.sorcerers

		for i = start, ending do
			if this.sorcerers[i][1] then
				return i, this.sorcerers[i][2]
			end
		end

		return nil, nil
	end

	local function get_sorcerer(sorc_id)
		return this.sorcerers[sorc_id][1]
	end

	local function kill_sorcerer(sorc_id, left)
		local sorc = this.sorcerers[sorc_id][1]

		if this.sorcerers[sorc_id][4] then
			this.sorcerers[sorc_id][4] = false

			log.info("Sorcerer on the way to spot %s dead.", sorc_id)
		end

		if sorc then
			if not sorc.health.dead then
				sorc.health.hp = 0
			end

			this.sorcerers[sorc_id][1] = nil

			log.info("Sorcerer on spot %s dead.", sorc_id)
		end

		local achievement_controller = table.filter(game.store.entities, function(k, v)
			return v.template_name == "controller_stage_13_achievement"
		end)

		achievement_controller[1].sorcerer_died = true
	end

	local function on_lose_health(current_health)
		if current_health > 0 then
			if last_shake and store.entities[last_shake.id] then
				queue_remove(store, last_shake)
			end

			last_shake = E:create_entity("aura_shake_entity")
			last_shake.aura.target_id = this.id
			last_shake.aura.source_id = this.id
			last_shake.aura.duration = this.shake_duration
			last_shake.aura.amplitude = this.shake_amplitude
			last_shake.aura.freq_factor = this.shake_frequency
			last_shake.aura.sprites_to_shake = {
				2
			}

			queue_insert(store, last_shake)
		end

		if current_health == 2 then
			this.render.sprites[2].prefix = this.sunray.damaged_health_prefix
		end

		if current_health == 1 then
			this.render.sprites[2].prefix = this.sunray.very_damaged_health_prefix
		end

		if not is_shooting then
			if is_charged() then
				animation_start_all(this, this.sunray.charged_loop_anim, nil, store.tick_ts, true)
			elseif is_charging() then
				animation_start_all(this, this.sunray.charge_loop_anim, nil, store.tick_ts, true)
			else
				animation_start_all(this, this.sunray.off_anim, nil, store.tick_ts, true)
			end
		end
	end

	this.on_sorcerer_arrived = on_sorcerer_arrived
	this.is_charging = is_charging
	this.has_sorcerers = has_sorcerers
	this.get_sorcerer_position = get_sorcerer_position
	this.kill_sorcerer = kill_sorcerer
	this.get_sorcerer = get_sorcerer
	this.spawn_sorcerer = spawn_sorcerer
	this.spot_is_left_side = spot_is_left_side
	this.determine_spot_for_sorcerer = determine_spot_for_sorcerer
	this.on_lose_health = on_lose_health
	this.spot_open = spot_open
	this.is_charged = is_charged

	local function sorcerers_set_raise_arms(b)
		for i, sorc in ipairs(this.sorcerers) do
			if sorc[1] then
				sorc[1].raise_arms = b
			end
		end
	end

	local function y_stop_charge_animation()
		charging_last_frame = false

		sorcerers_set_raise_arms(false)
		S:queue(this.sound_events.ray_end)
		y_animation_play_all(this, this.sunray.charge_cancel_anim, nil, store.tick_ts)
		animation_start_all(this, this.sunray.off_anim, nil, store.tick_ts, true)
	end

	local function y_charge_animation()
		charging_last_frame = true

		sorcerers_set_raise_arms(true)
		S:queue(this.sound_events.charge_start)
		y_animation_play_all(this, this.sunray.charge_start_anim, nil, store.tick_ts)

		if not is_charging() then
			y_stop_charge_animation()
		else
			animation_start_all(this, this.sunray.charge_loop_anim, nil, store.tick_ts, true)
		end
	end

	local function shoot_bullet(attack, enemy, to_boss)
		local roffset = attack.ray_start_offset
		local hoffset = to_boss and V.vclone(enemy.unit.hit_offset) or v(0, 0)
		local b = E:create_entity(attack.bullet)

		b.pos.x = this.pos.x + roffset.x
		b.pos.y = this.pos.y + roffset.y
		b.bullet.from = V.vclone(b.pos)
		b.bullet.to = V.v(enemy.pos.x + hoffset.x, enemy.pos.y + hoffset.y)
		b.bullet.target_id = enemy.id
		b.bullet.source_id = this.id
		b.bullet.damage_factor = this.tower.damage_factor
		ray_decal = E:create_entity(attack.hit_decal)
		ray_decal.pos = V.vclone(b.bullet.to)
		ray_decal.render.sprites[1].ts = store.tick_ts
		ray_decal.render.sprites[1].sort_y_offset = b.pos.y - ray_decal.pos.y + 1

		if to_boss then
			local to_from = v(b.bullet.to.x - b.bullet.from.x, b.bullet.to.y - b.bullet.from.y)

			ray_decal.render.sprites[1].r = V.angleTo(to_from.x, to_from.y) + math.pi / 2
		end

		queue_insert(store, ray_decal)
		queue_insert(store, b)
	end

	local function shoot_bullet_pos(attack, target_pos, to_boss)
		local shooting_right = not this.render.sprites[1].flip_x
		local roffset = attack.ray_start_offset
		local b = E:create_entity(attack.bullet)

		b.pos.x = this.pos.x + roffset.x * (shooting_right and 1 or -1)
		b.pos.y = this.pos.y + roffset.y
		b.bullet.from = V.vclone(b.pos)
		b.bullet.to = V.v(target_pos.x, target_pos.y)
		b.bullet.source_id = this.id
		b.bullet.damage_factor = this.tower.damage_factor
		ray_decal = E:create_entity(attack.hit_decal)
		ray_decal.render.sprites[1].ts = store.tick_ts
		ray_decal.pos = V.vclone(b.bullet.to)
		ray_decal.render.sprites[1].sort_y_offset = b.pos.y - ray_decal.pos.y + 1

		if to_boss then
			local to_from = v(b.bullet.to.x - b.bullet.from.x, b.bullet.to.y - b.bullet.from.y)

			ray_decal.render.sprites[1].r = V.angleTo(to_from.x, to_from.y)
		end

		queue_insert(store, ray_decal)
		queue_insert(store, b)
	end

	local function y_shoot_ray(a)
		local start_ts = store.tick_ts
		local target
		local trigger_target, targets, _ = U.find_foremost_enemy(store.entities, this.pos, a.min_range, a.max_range, a.node_prediction, a.vis_flags, a.vis_bans, function(e, o)
			return e.template_name ~= "enemy_boss_stage_13" and GR:cell_is(e.pos.x, e.pos.y, a.accepted_terrains)
		end)

		if not targets or #targets == 0 then
			SU.delay_attack(store, a, fts(10))

			return false
		end

		local target_pos = V.vclone(trigger_target.pos)

		S:queue(this.sound_events.ray_fire)
		animation_start_all(this, a.start_anim, nil, store.tick_ts)
		U.y_wait(store, a.shoot_time)
		S:queue(this.sound_events.ray_loop)

		local target, targets, _ = U.find_foremost_enemy(store.entities, this.pos, a.min_range, a.max_range, a.node_prediction, a.vis_flags, a.vis_bans, function(e, o)
			return e.template_name ~= "enemy_boss_stage_13" and GR:cell_is(e.pos.x, e.pos.y, a.accepted_terrains)
		end)

		if targets and #targets > 0 then
			local hp_max = 0
			local final_target

			for k, t in pairs(targets) do
				if hp_max < t.health.hp_max then
					hp_max = t.health.hp_max
					final_target = t
				end
			end

			shoot_bullet(a, final_target)
		else
			shoot_bullet_pos(a, target_pos)
		end

		U.y_animation_wait(this, 1)
		animation_start_all(this, a.loop_anim, nil, store.tick_ts, true)
		U.y_wait(store, this.sunray.ray_duration - (a.start_anim_duration - a.shoot_time))
		queue_remove(store, ray_decal)
		S:stop(this.sound_events.ray_loop)
		S:queue(this.sound_events.ray_end)
		y_animation_play_all(this, a.end_anim, nil, store.tick_ts)

		if is_charging() then
			y_charge_animation()
		else
			charging_last_frame = false

			animation_start_all(this, this.sunray.off_anim, nil, store.tick_ts, true)
		end

		charged_last_frame = false
		a.ts = store.tick_ts

		return true
	end

	local function y_shoot_ray_at_boss(boss, a)
		local start_ts = store.tick_ts
		local target
		local target_pos = V.vclone(boss.pos)

		is_shooting = true

		S:queue(this.sound_events.ray_fire)
		animation_start_all(this, a.start_anim, nil, store.tick_ts)
		U.y_wait(store, a.shoot_time)
		S:queue(this.sound_events.ray_loop)

		local boss_still_here = find_all_t(store, this.sunray.boss_t)[1]

		if boss_still_here then
			boss.tanking_ray = true

			local final_target = boss

			shoot_bullet(a, final_target, true)
		else
			shoot_bullet_pos(a, target_pos)
		end

		U.y_animation_wait(this, 1)
		animation_start_all(this, a.loop_anim, nil, store.tick_ts, true)
		U.y_wait(store, this.sunray.boss_ray_duration - (a.start_anim_duration - a.shoot_time))
		queue_remove(store, ray_decal)
		S:stop(this.sound_events.ray_loop)
		S:queue(this.sound_events.ray_end)
		y_animation_play_all(this, a.end_anim, nil, store.tick_ts)

		is_shooting = false

		if is_charging() then
			y_charge_animation()
		else
			charging_last_frame = false

			animation_start_all(this, this.sunray.off_anim, nil, store.tick_ts, true)
		end

		charged_last_frame = false
		a.ts = store.tick_ts
	end

	local function y_animations(charged_last_frame, charging_last_frame)
		if not charged_last_frame and charge_acum >= this.sunray.points_to_charge then
			sorcerers_set_raise_arms(false)
			S:queue(this.sound_events.charge_end)
			y_animation_play_all(this, this.sunray.charged_start_anim, nil, store.tick_ts)
			animation_start_all(this, this.sunray.charged_loop_anim, nil, store.tick_ts, true)

			return
		end

		if this.render.sprites[2].name == this.sunray.charged_loop_anim then
			return
		end

		if not charging_last_frame and is_charging() then
			y_charge_animation()

			return
		end

		if charging_last_frame and not is_charging() then
			y_stop_charge_animation()
		end
	end

	while true do
		if not obelisks or #obelisks < this.expected_obelisks then
			obelisks = find_all_t(store, this.obelisk_t)
		end

		if health_controller.current_health_boss_hits <= 0 then
			this.user_selection.allowed = false
			this.user_selection.in_progress = nil

			U.animation_start(this, this.sunray.destroyed_anim, nil, store.tick_ts, nil, 2)
			U.y_wait(store, fts(10))

			local sorc_ids = {}

			for k, sorc_spot in pairs(this.sorcerers) do
				if sorc_spot[1] then
					sorc_spot[1].health.hp = 0

					table.insert(sorc_ids, sorc_spot[1])
					U.y_wait(store, U.frandom(0, fts(6)))
				end
			end

			local all_other_sorcs = find_all_t(store, this.sorcerer_t, false, function(k, v)
				return not table.contains(sorc_ids, v.id)
			end)

			for k, sorc in pairs(all_other_sorcs) do
				sorc.health.hp = 0

				U.y_wait(store, U.frandom(0, fts(6)))
			end

			U.y_animation_wait(this, 2)

			break
		end

		if charge_acum < this.sunray.points_to_charge and is_charging() then
			if not started_charging_once then
				started_charging_once = true

				for i, obelisk in ipairs(find_all_t(store, this.broken_obelisk_t)) do
					obelisk.summoned = true
				end
			end

			charge_acum = charge_acum + store.tick_length * this.sunray.points_per_second[count_charging_sorcerers()]

			if charge_acum >= this.sunray.points_to_charge then
				this.ui.can_select = false

				if obelisks and #obelisks > 0 then
					for i, obelisk in ipairs(obelisks) do
						obelisk.set_charged()
					end
				end

				sorcerers_set_raise_arms(false)
			end
		end

		y_animations(charged_last_frame, charging_last_frame)

		this.user_selection.allowed = is_charged()

		if is_charged() and this.ui.clicked then
			this.ui.clicked = nil
			this.ui.can_select = true

			local boss = find_all_t(store, this.sunray.boss_t)[1]

			if boss and boss.on_ground then
				y_shoot_ray_at_boss(boss, this.attacks.list[2])
			elseif not y_shoot_ray(this.attacks.list[1]) then
				goto label_1280_0
			end

			charge_acum = 0
		end

		::label_1280_0::

		if this.ui.clicked then
			this.ui.clicked = nil
		end

		charged_last_frame = is_charged()
		charging_last_frame = is_charging()

		coroutine.yield()
	end
end

function scripts.tower_stage_13_sunray_tower.remove(this, store, script)
	return true
end

scripts.soldier_stage_13_sorcerer = {}

function scripts.soldier_stage_13_sorcerer.update(this, store)
	local brk, sta
	local path_ni = 1
	local path_spi = 1
	local target_pos = P:node_pos(this.path_id, path_spi, path_ni)

	this.vis.bans = 0

	local function do_step()
		if V.veq(this.pos, target_pos) then
			this.motion.arrived = true
		else
			U.set_destination(this, target_pos)

			local an, af = U.animation_name_facing_point(this, "walk", this.motion.dest, 1)

			U.animation_start(this, an, af, store.tick_ts, true, 1)
			U.walk(this, store.tick_length)
		end
	end

	local function run_to_tower()
		local distSq = V.dist2(target_pos.x, target_pos.y, this.pos.x, this.pos.y)

		if distSq < 25 then
			path_ni = path_ni + 2
			target_pos = P:node_pos(this.path_id, path_spi, path_ni)
		end

		do_step()
	end

	local sunray = find_all_t(store, this.sunray_tower)[1]

	while true do
		if P:nodes_to_goal(this.path_id, 1, path_ni) < 3 then
			break
		end

		if this.health.dead then
			sunray.kill_sorcerer(this.ritual_spot, this.left_path)
			SU.y_soldier_death(store, this)

			return
		end

		if this.unit.is_stunned then
			SU.soldier_idle(store, this)
		else
			brk, sta = SU.y_soldier_melee_block_and_attacks(store, this)

			if brk or sta ~= A_NO_TARGET then
				if sta == A_DONE then
					local nearest = P:nearest_nodes(this.pos.x, this.pos.y, {
						this.path_id
					})
					local pi, spi, ni = unpack(nearest[1])

					path_ni = ni + 2
					target_pos = P:node_pos(this.path_id, path_spi, path_ni)
				end
			else
				run_to_tower()
			end
		end

		coroutine.yield()
	end

	target_pos = this.final_destination

	while true do
		if this.motion.arrived then
			break
		end

		if this.health.dead then
			sunray.kill_sorcerer(this.ritual_spot, this.left_path)
			SU.y_soldier_death(store, this)

			return
		end

		do_step()
		coroutine.yield()
	end

	sunray.on_sorcerer_arrived(this)

	this.health.hp = this.health.hp_max
	this.health_bar.hidden = true
	this.ui.can_click = false
	this.ui.can_select = false
	this.ui.can_hover = false
	this.vis.bans = F_ALL

	if game.game_gui.selected_entity and game.game_gui.selected_entity.id == this.id then
		signal.emit("hide-bottom-info")
	end

	local suffix = this.is_top and "front" or "back"
	local raising_arms = false

	U.animation_start(this, this.cast_idle_anim .. suffix, not this.left_path, store.tick_ts, true, 1)

	while not this.health.dead do
		if this.raise_arms and not raising_arms then
			U.y_animation_play(this, this.cast_start_anim .. suffix, not this.left_path, store.tick_ts, 1, 1)
			U.animation_start(this, this.cast_loop_anim .. suffix, not this.left_path, store.tick_ts, true, 1)

			raising_arms = true
		end

		if not this.raise_arms and raising_arms then
			U.y_animation_play(this, this.cast_end_anim .. suffix, not this.left_path, store.tick_ts, 1, 1)
			U.animation_start(this, this.cast_idle_anim .. suffix, not this.left_path, store.tick_ts, true, 1)

			raising_arms = false
		end

		coroutine.yield()
	end

	sunray.kill_sorcerer(this.ritual_spot, this.left_path)
	SU.y_soldier_death(store, this)
end

scripts.tower_stage_13_sunray_obelisk = {}

function scripts.tower_stage_13_sunray_obelisk.insert(this, store, script)
	return true
end

function scripts.tower_stage_13_sunray_obelisk.update(this, store, script)
	local charged = false
	local charged_this_frame = false
	local sunray = find_all_t(store, this.sunray_tower)[1]

	local function set_charged()
		charged = true
		charged_this_frame = true
		this.ui.can_select = false
	end

	this.set_charged = set_charged

	local function shoot_bullet(attack, enemy)
		local roffset = attack.ray_start_offset
		local hoffset = enemy.unit.hit_offset
		local random_offset = v(U.frandom(attack.hit_offset_random_min, attack.hit_offset_random_max), U.frandom(attack.hit_offset_random_min, attack.hit_offset_random_max))
		local b = E:create_entity(attack.bullet)

		b.pos.x = this.pos.x + roffset.x
		b.pos.y = this.pos.y + roffset.y
		b.bullet.from = V.vclone(b.pos)
		b.bullet.to = V.v(enemy.pos.x + hoffset.x, enemy.pos.y + hoffset.y)
		b.bullet.target_id = enemy.id
		b.bullet.source_id = this.id
		b.bullet.damage_factor = this.tower.damage_factor

		queue_insert(store, b)
	end

	local function shoot_bullet_pos(attack, target_pos)
		local roffset = attack.ray_start_offset
		local random_offset = v(U.frandom(attack.hit_offset_random_min, attack.hit_offset_random_max), U.frandom(attack.hit_offset_random_min, attack.hit_offset_random_max))
		local b = E:create_entity(attack.bullet)

		b.pos.x = this.pos.x + roffset.x
		b.pos.y = this.pos.y + roffset.y
		b.bullet.from = V.vclone(b.pos)
		b.bullet.to = V.v(target_pos.x + random_offset.x, target_pos.y + random_offset.y)
		b.bullet.source_id = this.id
		b.bullet.damage_factor = this.tower.damage_factor

		queue_insert(store, b)
	end

	local shot_ts = store.tick_ts

	U.y_animation_play(this, this.sunray.buy_start_anim, nil, store.tick_ts, 1, 1)
	U.animation_start(this, this.sunray.idle_loop_anim, nil, store.tick_ts, true, 1)

	if sunray.is_charged() then
		set_charged()
	end

	while true do
		if charged_this_frame then
			S:queue(this.sound_events.power_up)
			U.y_animation_play(this, this.sunray.charged_anim, nil, store.tick_ts, 1, 1)
			U.animation_start(this, this.sunray.charged_loop_anim, nil, store.tick_ts, true, 1)

			charged_this_frame = false
		end

		if charged then
			local a = this.attacks.list[1]
			local action_allowed = charged

			if action_allowed and this.ui.clicked then
				this.ui.clicked = nil
				this.ui.can_select = true

				S:queue(this.sound_events.power_up)

				for i = 1, this.sunray.shots do
					local _, targets = U.find_foremost_enemy(store.entities, this.pos, a.min_range, a.max_range, a.node_prediction, a.vis_flags, a.vis_bans)

					if targets and #targets > 0 then
						U.animation_start(this, a.animation, nil, store.tick_ts, false, 1)
						shoot_bullet(a, targets[1])
					else
						U.y_animation_wait(this, 1)
						U.animation_start(this, a.animation_idle, nil, store.tick_ts, true, 1)
					end

					U.y_wait(store, this.sunray.time_between_shots)
				end

				S:queue(this.sound_events.power_down)
				U.y_animation_play(this, this.sunray.shoot_end_anim, nil, store.tick_ts, 1, 1)
				U.animation_start(this, this.sunray.idle_loop_anim, nil, store.tick_ts, true, 1)

				if not charged_this_frame then
					charged = false
				end
			end

			if this.ui.clicked then
				this.ui.clicked = nil
			end
		end

		coroutine.yield()
	end
end

scripts.enemy_boss_stage_13 = {}

function scripts.enemy_boss_stage_13.insert(this, store, script)
	this.shield = E:create_entity(this.shield_t)
	this.shield.render.sprites[1].ts = store.tick_ts
	this.shield.render.sprites[1].track_attach_point = "shield"
	this.shield.render.sprites[1].track_sprite_id = 1
	this.shield.render.sprites[1].track_id = this.id

	queue_insert(store, this.shield)

	return scripts.enemy_basic.insert(this, store, script)
end

function scripts.enemy_boss_stage_13.update(this, store, script)
	local tower_health = find_all_t(store, this.sunray_tower_health_t)[1]
	local sunray_tower = find_all_t(store, this.sunray_tower_t)[1]

	this.on_ground = true

	local last_jump_ts = store.tick_ts - 10
	local health_range = 1
	local original_armor = this.health.armor
	local original_magic_armor = this.health.magic_armor
	local original_hit_offset = this.unit.hit_offset
	local original_blood = this.unit.blood_color

	this.health.armor = this.shielded_armor
	this.health.magic_armor = this.shielded_magic_armor
	this.unit.hit_offset = this.shield_hit_offset
	this.unit.blood_color = BLOOD_NONE

	local boss_waves = 0
	local jumps = 0
	local boss_strike = E:create_entity(this.boss_strike)

	boss_strike.pos = this.pos

	queue_insert(store, boss_strike)

	local function on_damage(e, store, damage)
		if not this.shield.render.sprites[1].hidden then
			this.shield.shake = true
			this.shield.damage_received = damage.value
		end

		return true
	end

	local function y_on_death()
		LU.kill_all_enemies(store, true)
		S:stop_all()
		W:stop_manual_wave("BOSS_" .. boss_waves % this.amount_of_manual_waves + 1)
		S:queue(this.sound_death)

		this.shield.render.sprites[1].hidden = true

		U.y_animation_play(this, "death", nil, store.tick_ts, 1)
		LU.kill_all_enemies(store, true)
		U.y_animation_wait(this)
		signal.emit("boss-killed", this)

		this.bossfight_ended = true
	end

	local function y_jump_below_and_return(with_shield)
		jumps = jumps + 1

		local first_jump_destination = v(this.jump_target_pos[this.nav_path.pi].x + U.frandom(-this.jump_x_variation, this.jump_x_variation), this.jump_target_pos[this.nav_path.pi].y)

		U.animation_start(this, "jump", nil, store.tick_ts, false, 1)

		while not U.animation_finished(this, 1) do
			if this.health.dead then
				return true
			end

			coroutine.yield()
		end

		this.on_ground = false

		S:queue(this.sound_events.jump)

		local shake = E:create_entity("aura_screen_shake")

		shake.aura.amplitude = 0.5
		shake.aura.duration = 0.5
		shake.aura.freq_factor = 1

		LU.queue_insert(store, shake)

		local jump_dust = E:create_entity(this.land_dust)

		jump_dust.pos.x, jump_dust.pos.y = this.pos.x, this.pos.y
		jump_dust.render.sprites[1].ts = store.tick_ts

		queue_insert(store, jump_dust)

		local old_bans = this.vis.bans
		local old_flags = this.vis.flags

		this.vis.bans = F_ALL
		this.vis.flags = F_BOSS
		this.health.ignore_damage = true
		this.ui.can_click = false
		this.ui.can_hover = false

		U.unblock_all(store, this)
		SU.remove_modifiers(store, this)

		this.health_bar.hidden = true

		if game.game_gui.selected_entity and game.game_gui.selected_entity.id == this.id then
			signal.emit("hide-bottom-info")
		end

		local jump_out = E:create_entity(with_shield and this.jump_bullet_shield or this.jump_bullet_shieldless)

		jump_out.pos.x, jump_out.pos.y = this.pos.x, this.pos.y
		jump_out.bullet.from = V.vclone(jump_out.pos)
		jump_out.bullet.to = first_jump_destination
		jump_out.render.sprites[1].flip_x = this.pos.x > first_jump_destination.x

		LU.queue_insert(store, jump_out)
		coroutine.yield()
		coroutine.yield()

		this.render.sprites[1].hidden = true

		local random_wait = U.frandom(this.offstage_wait_min, this.offstage_wait_max)
		local return_ts = store.tick_ts
		local wave_stop_ts = store.tick_ts
		local wave_stopped = false

		while random_wait > store.tick_ts - return_ts do
			if store.tick_ts - wave_stop_ts > this.turn_off_wave_wait and not wave_stopped then
				wave_stopped = true

				W:stop_manual_wave("BOSS_" .. boss_waves % this.amount_of_manual_waves + 1)

				boss_waves = boss_waves + 1
			end

			coroutine.yield()
		end

		if not wave_stopped then
			wave_stopped = true

			W:stop_manual_wave("BOSS_" .. boss_waves % this.amount_of_manual_waves + 1)

			boss_waves = boss_waves + 1
		end

		W:start_manual_wave("BOSS_" .. boss_waves % this.amount_of_manual_waves + 1)

		local destination = km.clamp(1, #this.path_jump_destinations, math.ceil((jumps + 1) / 2))
		local target_path = this.path_jump_alternations[this.nav_path.pi]
		local target_pos = P:node_pos(target_path, 1, this.path_jump_destinations[destination][target_path])

		this.pos.x, this.pos.y = target_pos.x, target_pos.y
		this.nav_path.pi = target_path
		this.nav_path.spi = 1
		this.nav_path.ni = this.path_jump_destinations[destination][target_path]

		U.set_heading(this, P:node_pos(this.nav_path.pi, this.nav_path.spi, this.nav_path.ni + 1))

		this.health.armor = this.shielded_armor
		this.health.magic_armor = this.shielded_magic_armor
		this.unit.hit_offset = this.shield_hit_offset
		this.unit.blood_color = BLOOD_NONE

		local jump_in = E:create_entity(this.jump_bullet_shield_return)
		local jump_from_pos = v(this.jump_target_pos[this.nav_path.pi].x, this.jump_target_pos[this.nav_path.pi].y)

		jump_in.pos.x, jump_in.pos.y = jump_from_pos.x, jump_from_pos.y
		jump_in.bullet.from = V.vclone(jump_in.pos)
		jump_in.bullet.to = P:node_pos(this.nav_path.pi, this.nav_path.spi, this.nav_path.ni)
		jump_in.render.sprites[1].flip_x = jump_in.pos.x > jump_in.bullet.to.x

		LU.queue_insert(store, jump_in)
		U.y_wait(store, jump_in.bullet.flight_time + fts(1))

		this.render.sprites[1].hidden = false
		this.health.ignore_damage = false
		this.health_bar.hidden = false
		this.ui.can_click = true
		this.ui.can_hover = true
		this.vis.bans = old_bans
		this.vis.flags = old_flags

		local debris_fx = E:create_entity("fx_boss_stage_13_land")

		debris_fx.pos.x, debris_fx.pos.y = 512, 384
		debris_fx.render.sprites[1].ts = store.tick_ts

		LU.queue_insert(store, debris_fx)

		this.on_ground = true

		S:queue(this.sound_events.land)

		this.unit.hit_offset.x = target_path == 12 and -1 * math.abs(this.unit.hit_offset.x) or math.abs(this.unit.hit_offset.x)

		U.animation_start(this, "land", target_path == 12, store.tick_ts, false, 1)

		while not U.animation_finished(this, 1) do
			if this.health.dead or this.tanking_ray then
				return true
			end

			coroutine.yield()
		end

		this.shield.render.sprites[1].hidden = false
		last_jump_ts = store.tick_ts

		return false
	end

	local function y_tower_sunray_shot()
		if this.tanking_ray then
			this.shield.render.sprites[1].hidden = true

			local af = this.pos.x > sunray_tower.pos.x

			U.animation_start(this, "shieldblast", af, store.tick_ts, false, 1)
			U.y_wait(store, fts(59))
			S:queue(this.sound_events.shieldbreak)

			this.tanking_ray = false

			local shield = E:create_entity(this.shield_bullet)

			shield.pos.x, shield.pos.y = this.pos.x + this.shield_bullet_offset.x, this.pos.y + this.shield_bullet_offset.y
			shield.bullet.from = V.vclone(shield.pos)
			shield.bullet.to = v(this.shield_fly_target_pos[this.nav_path.pi].x + U.frandom(-this.shield_fly_x_variation, this.shield_fly_x_variation), this.shield_fly_target_pos[this.nav_path.pi].y)

			LU.queue_insert(store, shield)

			this.health.armor = original_armor
			this.health.magic_armor = original_magic_armor
			this.unit.hit_offset = original_hit_offset
			this.unit.blood_color = original_blood

			U.y_animation_wait(this, 1)
			U.animation_start(this, "stun", nil, store.tick_ts, true, 1)

			local stun_ts = store.tick_ts

			while store.tick_ts - stun_ts < this.sunray_stun do
				if this.health.dead then
					return true
				end

				coroutine.yield()
			end

			y_jump_below_and_return(false)

			return true
		end

		return false
	end

	local function in_front_of_tower()
		return this.nav_path.ni >= P:get_end_node(this.nav_path.pi) - 5
	end

	local function y_strike_tower()
		if in_front_of_tower() and not this.tanking_ray then
			this.shield.render.sprites[1].hidden = true
			this.render.sprites[1].hidden = true
			boss_strike.render.sprites[1].hidden = false
			this.unit.hit_offset.x = this.render.sprites[1].flip_x and -1 * math.abs(this.unit.hit_offset.x) or math.abs(this.unit.hit_offset.x)

			if tower_health.current_health_boss_hits <= 1 then
				U.animation_start(boss_strike, this.anim_destroy_tower, this.render.sprites[1].flip_x, store.tick_ts, false, 1)
			else
				U.animation_start(boss_strike, this.anim_hit_tower, this.render.sprites[1].flip_x, store.tick_ts, false, 1)
			end

			local ts = store.tick_ts

			while store.tick_ts - ts < this.hit_tower_hit_time do
				if this.tanking_ray then
					boss_strike.render.sprites[1].hidden = true
					this.shield.render.sprites[1].hidden = false
					this.render.sprites[1].hidden = false

					return false
				end

				coroutine.yield()
			end

			local tower = find_all_t(store, this.sunray_tower_t)[1]

			S:queue(this.sound_events["tower_hit_" .. 4 - tower_health.current_health_boss_hits])

			tower_health.current_health_boss_hits = tower_health.current_health_boss_hits - 1

			tower.on_lose_health(tower_health.current_health_boss_hits)

			local flipped = this.render.sprites[1].flip_x
			local hit_fx = E:create_entity(this.boss_tower_hit_fx)

			hit_fx.pos = v(this.pos.x + this.boss_tower_hit_offset.x * (flipped and -1 or 1), this.pos.y + this.boss_tower_hit_offset.y)
			hit_fx.render.sprites[1].ts = store.tick_ts

			queue_insert(store, hit_fx)

			while not U.animation_finished(boss_strike, 1) do
				if this.tanking_ray then
					boss_strike.render.sprites[1].hidden = true
					this.shield.render.sprites[1].hidden = false
					this.render.sprites[1].hidden = false

					return false
				end

				coroutine.yield()
			end

			if tower_health.current_health_boss_hits <= 0 then
				U.animation_start(boss_strike, this.anim_loop_scream, this.render.sprites[1].flip_x, store.tick_ts, true, 1)

				while true do
					coroutine.yield()
				end
			end

			boss_strike.render.sprites[1].hidden = true
			this.shield.render.sprites[1].hidden = false
			this.render.sprites[1].hidden = false
			this.render.sprites[1].ts = store.tick_ts

			if this.tanking_ray then
				return false
			end

			return true
		end

		return false
	end

	local function break_fn()
		return y_strike_tower() or y_tower_sunray_shot()
	end

	local function y_enemy_melee_attacks(target, break_fn)
		for _, i in ipairs(this.melee.order) do
			local ma = this.melee.attacks[i]
			local cooldown = ma.cooldown

			if ma.shared_cooldown then
				cooldown = this.melee.cooldown
			end

			if not ma.disabled and cooldown <= store.tick_ts - ma.ts and band(ma.vis_flags, target.vis.bans) == 0 and band(ma.vis_bans, target.vis.flags) == 0 and (not ma.fn_can or ma.fn_can(this, store, ma, target)) then
				ma.ts = store.tick_ts

				if math.random() >= ma.chance then
					-- block empty
				else
					log.paranoid("attack %i selected for entity %s", i, this.template_name)

					for _, aa in pairs(this.melee.attacks) do
						if aa ~= ma and aa.shared_cooldown then
							aa.ts = ma.ts
						end
					end

					ma.ts = store.tick_ts

					S:queue(ma.sound, ma.sound_args)

					local an, af = U.animation_name_facing_point(this, ma.animation, target.pos)

					this.unit.hit_offset.x = af and -1 * math.abs(this.unit.hit_offset.x) or math.abs(this.unit.hit_offset.x)

					for i = 1, #this.render.sprites do
						if this.render.sprites[i].animated then
							U.animation_start(this, an, af, store.tick_ts, 1, i)

							this.shield.render.sprites[1].hidden = true
						end
					end

					local hit_pos = V.vclone(this.pos)

					if ma.hit_offset then
						hit_pos.x = hit_pos.x + (af and -1 or 1) * ma.hit_offset.x
						hit_pos.y = hit_pos.y + ma.hit_offset.y
					end

					local hit_times = ma.hit_times and ma.hit_times or {
						ma.hit_time
					}

					for i = 1, #hit_times do
						local hit_time = hit_times[i]

						while hit_time > store.tick_ts - ma.ts do
							if this.health.dead or this.unit.is_stunned and not ma.ignore_stun or this.dodge and this.dodge.active and not this.dodge.silent or break_fn and break_fn() then
								return false
							end

							coroutine.yield()
						end

						S:queue(ma.sound_hit, ma.sound_hit_args)

						if ma.type == "melee" and table.contains(this.enemy.blockers, target.id) then
							local d = E:create_entity("damage")

							d.source_id = this.id
							d.target_id = target.id
							d.track_kills = this.track_kills ~= nil
							d.track_damage = ma.track_damage
							d.pop = ma.pop
							d.pop_chance = ma.pop_chance
							d.pop_conds = ma.pop_conds

							if ma.instakill then
								d.damage_type = DAMAGE_INSTAKILL

								queue_damage(store, d)
							elseif ma.damage_min then
								d.damage_type = ma.damage_type

								local hit_factor = ma.hit_damage_factor and ma.hit_damage_factor[i] or 1

								d.value = math.ceil(this.unit.damage_factor * hit_factor * math.random(ma.damage_min, ma.damage_max))

								queue_damage(store, d)
							end

							if ma.mod then
								local mod = E:create_entity(ma.mod)

								mod.modifier.target_id = target.id
								mod.modifier.source_id = this.id

								queue_insert(store, mod)
							end
						elseif ma.type == "area" then
							local targets = table.filter(store.entities, function(_, e)
								return e.soldier and e.vis and e.health and not e.health.dead and band(e.vis.flags, ma.vis_bans) == 0 and band(e.vis.bans, ma.vis_flags) == 0 and U.is_inside_ellipse(e.pos, hit_pos, ma.damage_radius) and (not ma.fn_filter or ma.fn_filter(this, store, ma, e))
							end)

							for i, e in ipairs(targets) do
								if e == target and dodged then
									-- block empty
								else
									if ma.count and i > ma.count then
										break
									end

									local d = E:create_entity("damage")

									d.source_id = this.id
									d.target_id = e.id
									d.damage_type = ma.damage_type
									d.value = math.ceil(this.unit.damage_factor * math.random(ma.damage_min, ma.damage_max))
									d.pop = ma.pop
									d.pop_chance = ma.pop_chance
									d.pop_conds = ma.pop_conds

									queue_damage(store, d)

									if ma.mod then
										local mod = E:create_entity(ma.mod)

										mod.modifier.target_id = e.id
										mod.modifier.source_id = this.id

										queue_insert(store, mod)
									end
								end
							end
						end

						if ma.hit_fx and (not ma.hit_fx_once or i == 1) then
							local fx = E:create_entity(ma.hit_fx)

							fx.pos = V.vclone(hit_pos)

							if ma.hit_fx_offset then
								fx.pos.x = fx.pos.x + (af and -1 or 1) * ma.hit_fx_offset.x
								fx.pos.y = fx.pos.y + ma.hit_fx_offset.y
							end

							for i = 1, #fx.render.sprites do
								if ma.hit_fx_flip then
									fx.render.sprites[i].flip_x = af
								end

								fx.render.sprites[i].ts = store.tick_ts
							end

							queue_insert(store, fx)
						end

						if ma.hit_decal then
							local fx = E:create_entity(ma.hit_decal)

							fx.pos = V.vclone(hit_pos)

							for i = 1, #fx.render.sprites do
								fx.render.sprites[i].ts = store.tick_ts
							end

							queue_insert(store, fx)
						end
					end

					while not U.animation_finished(this) do
						if this.health.dead or ma.ignore_stun and this.unit.is_stunned or this.dodge and this.dodge.active and not this.dodge.silent or break_fn and break_fn() then
							return false
						end

						coroutine.yield()
					end

					U.animation_start(this, "idle", nil, store.tick_ts, true)

					this.shield.render.sprites[1].hidden = false

					U.animation_start(this.shield, "idle", nil, store.tick_ts, true, 1)

					return true
				end
			end
		end

		return true
	end

	local function can_melee_blocker(blocker)
		return not this.health.dead and not this.unit.is_stunned and blocker and not blocker.health.dead and table.contains(this.enemy.blockers, blocker.id) and store.entities[blocker.id]
	end

	local function y_wait_for_blocker(blocker)
		local pos = blocker.motion.arrived and blocker.pos or blocker.motion.dest
		local an, af = U.animation_name_facing_point(this, "idle", pos)

		this.unit.hit_offset.x = af and -1 * math.abs(this.unit.hit_offset.x) or math.abs(this.unit.hit_offset.x)

		U.animation_start(this, an, af, store.tick_ts, true)
		U.animation_start(this.shield, "idle", nil, store.tick_ts, true)

		while not blocker.motion.arrived do
			coroutine.yield()

			if this.health.dead or this.unit.is_stunned or not table.contains(this.enemy.blockers, blocker.id) or blocker.health.dead or not store.entities[blocker.id] then
				return false
			end

			if blocker.unit.is_stunned then
				U.unblock_target(store, blocker)

				return false
			end
		end

		return true
	end

	local function y_walk_step(animation_name, sprite_id)
		animation_name = animation_name or "walk"

		local next, new, use_path

		if this.motion.forced_waypoint then
			local w = this.motion.forced_waypoint

			next = w

			if V.dist(w.x, w.y, this.pos.x, this.pos.y) < 2 * this.motion.max_speed * store.tick_length then
				this.pos.x, this.pos.y = w.x, w.y
				this.motion.forced_waypoint = nil

				return false
			end
		else
			use_path = true
			next, new = P:next_entity_node(this, store.tick_length)

			if not next then
				log.debug("enemy %s ran out of nodes to walk", this.id)
				coroutine.yield()

				return false
			end
		end

		U.set_destination(this, next)

		local an, af = U.animation_name_facing_point(this, animation_name, this.motion.dest, sprite_id, nil, use_path)

		if this.sound_events and new then
			S:queue(this.sound_events.new_node, this.sound_events.new_node_args)
		end

		this.unit.hit_offset.x = af and -1 * math.abs(this.unit.hit_offset.x) or math.abs(this.unit.hit_offset.x)

		U.animation_start(this, an, af, store.tick_ts, true, sprite_id)
		U.animation_start(this.shield, "walk", nil, store.tick_ts, true, 1)
		U.walk(this, store.tick_length)
		coroutine.yield()

		this.motion.speed.x, this.motion.speed.y = 0, 0

		return true
	end

	local function y_walk_until_blocked(walk_break_fn)
		local blocker
		local terrain_type = band(GR:cell_type(this.pos.x, this.pos.y), bor(TERRAIN_WATER, TERRAIN_LAND))

		while not blocker do
			if this.unit.is_stunned then
				return false
			end

			if walk_break_fn and walk_break_fn() then
				return false, nil, nil
			end

			if this.health.dead then
				return false
			end

			local node_valid = P:is_node_valid(this.nav_path.pi, this.nav_path.ni)

			if #this.enemy.blockers > 0 then
				U.cleanup_blockers(store, this)

				blocker = store.entities[this.enemy.blockers[1]]
			end

			if not blocker then
				y_walk_step("walk", 1)
			else
				U.animation_start(this, "idle", nil, store.tick_ts, true)
				U.animation_start(this.shield, "idle", nil, store.tick_ts, true)
			end

			if terrain_type ~= band(GR:cell_type(this.pos.x, this.pos.y), bor(TERRAIN_WATER, TERRAIN_LAND)) then
				return false, nil
			end
		end

		return true, blocker
	end

	local function y_walk_melee(walk_break_fn, melee_break_fn)
		local cont, blocker = y_walk_until_blocked(walk_break_fn)

		if not cont then
			return false
		end

		if blocker then
			if not y_wait_for_blocker(blocker) then
				return false
			end

			while can_melee_blocker(blocker) and (not melee_break_fn or not melee_break_fn()) do
				if not y_enemy_melee_attacks(blocker, melee_break_fn) then
					return false
				end

				coroutine.yield()
			end
		end

		return true
	end

	this.health.on_damage = on_damage

	::label_1321_0::

	while true do
		while this.cinematic do
			coroutine.yield()
		end

		if this.health.dead then
			y_on_death()

			return
		end

		if not in_front_of_tower() then
			if not y_walk_melee(break_fn, break_fn) then
				goto label_1321_0
			end
		else
			y_strike_tower()
			y_tower_sunray_shot()
		end

		coroutine.yield()
	end
end

scripts.decal_stage_13_boss_shield = {}

function scripts.decal_stage_13_boss_shield.update(this, store, script)
	this.shake = false

	local phase = math.random(0, 2 * math.pi)

	while true do
		if this.shake then
			this.shake = false

			local shake_ts = store.tick_ts
			local move_ts = 0
			local damage_factor = km.clamp(0, 1, this.damage_received / this.shake_damage_ratio)
			local amp = this.shake_amplitude * damage_factor

			while store.tick_ts - shake_ts < this.shake_duration and not this.shake do
				local t = store.tick_ts - shake_ts
				local wox, woy = U.screen_shake_step(t, amp, this.shake_frequency, phase, this.shake_duration)

				this.render.sprites[1].offset.x, this.render.sprites[1].offset.y = wox, woy

				coroutine.yield()
			end
		end

		coroutine.yield()
	end
end

scripts.controller_graveyard_KR6 = {}

function scripts.controller_graveyard_KR6.update(this, store)
	local animation_decal = find_all_t(store, this.associated_decal)[1]
	local anim_ts = store.tick_ts
	local g = this.graveyard

	while not this.interrupt do
		local targets = table.filter(store.entities, function(k, v)
			return not v._in_graveyard and v.health and v.health.dead and band(v.vis.flags, g.vis_has) ~= 0 and band(v.vis.flags, g.vis_bans) == 0 and band(v.vis.bans, g.vis_flags) == 0 and store.tick_ts - v.health.death_ts >= g.dead_time and (not v.reinforcement or not v.reinforcement.hp_before_timeout) and (not g.excluded_templates or not table.contains(g.excluded_templates, v.template_name))
		end)

		if #targets == 0 then
			U.y_wait(store, g.check_interval)
		else
			if animation_decal and store.tick_ts - anim_ts > this.animation_cooldown then
				U.animation_start(animation_decal, this.animation, nil, store.tick_ts, false, 1)

				anim_ts = store.tick_ts
			end

			for _, t in ipairs(targets) do
				if this.interrupt then
					return
				end

				t._in_graveyard = true

				for _, s in ipairs(g.spawns_by_health) do
					local e, s_pos, pi, spi, ni

					if t.health.hp_max > s[2] then
						-- block empty
					else
						s_pos = table.random(g.spawn_pos)

						local nearest_nodes = P:nearest_nodes(s_pos.x, s_pos.y, g.pi and {
							g.pi
						} or nil, {
							1,
							2,
							3
						})

						if #nearest_nodes < 1 then
							log.error("graveyard controller %s could not spawn enemy. node not found near %s,%s", this.id, s_pos.x, s_pos.y)
						else
							pi, spi, ni = unpack(nearest_nodes[1])
							e = E:create_entity(s[1])
							e.nav_path.pi, e.nav_path.spi, e.nav_path.ni = pi, spi, ni
							e.pos = V.vclone(s_pos)
							e.render.sprites[1].name = "raise"
							e.motion.forced_waypoint = P:node_pos(e.nav_path)

							if not g.keep_gold and e.enemy then
								e.enemy.gold = 0
							end

							queue_insert(store, e)

							break
						end
					end
				end

				U.y_wait(store, g.spawn_interval)
			end
		end
	end

	queue_remove(store, this)
end

scripts.tower_stage_14_blacksmith = {}

function scripts.tower_stage_14_blacksmith.update(this, store, script)
	local visuals = find_all_t(store, this.decal)[1]
	local alert = find_all_t(store, this.alert)[1]
	local achievement_tracker = find_all_t(store, this.achievement_tracker)[1]
	local a
	local repaired = false

	alert.tween.reverse = true

	local run_anim_ts = store.tick_ts - (this.bubble_cd - math.random(5, 15))

	while true do
		if not repaired then
			if store.tick_ts - run_anim_ts > this.bubble_cd and store.player_gold >= this.powers.skill_a.price[1] then
				alert.render.sprites[1].hidden = false
				alert.render.sprites[1].ts = store.tick_ts
				alert.tween.ts = store.tick_ts
				alert.tween.reverse = false
				alert.tween.disabled = false

				U.animation_start(visuals, "broken_action", nil, store.tick_ts, false, 1)
				U.animation_start(alert, "loop", nil, store.tick_ts, true, 1)

				run_anim_ts = store.tick_ts
			end

			if not alert.tween.reverse and store.tick_ts - run_anim_ts > this.loop_bubble_time then
				alert.tween.ts = store.tick_ts
				alert.tween.reverse = true
				run_anim_ts = store.tick_ts - math.random(0, 10)
			end
		end

		if this.powers.skill_a.changed then
			if a then
				queue_remove(store, a)
				S:queue(this.upgrade_taunt)
			else
				repaired = true
				alert.render.sprites[1].hidden = true

				S:queue(this.repair_sound)
				S:queue(this.repair_taunt)
				U.y_animation_play(visuals, "fix", nil, store.tick_ts, 1, 1)
				U.animation_start(visuals, "fixed", nil, store.tick_ts, true, 1)
				S:queue(this.aura_sound)
			end

			a = E:create_entity(this.aura .. this.powers.skill_a.level)
			a.pos.x, a.pos.y = this.pos.x + this.aura_offset.x, this.pos.y + this.aura_offset.y

			queue_insert(store, a)

			if this.powers.skill_a.level == 3 then
				achievement_tracker.blacksmith_maxed = true
			end

			this.powers.skill_a.changed = false
		end

		coroutine.yield()
	end
end

scripts.mod_stage_14_blacksmith_towers = {}

function scripts.mod_stage_14_blacksmith_towers.remove(this, store, script)
	if not this.tween.remove and not this.tween.disabled then
		return true
	end

	local m = this.modifier
	local target = store.entities[m.target_id]

	if not target or not target.tower then
		log.error("error removing mod_stage_14_blacksmith_towers %s", this.id)

		return true
	end

	local tween_remove = scripts.tween_utils.reverse_remove(this, store, script)

	if this.range_factor and tween_remove then
		if target.attacks then
			target.attacks.range = target.attacks.range / this.range_factor
		end

		if target.barrack then
			target.barrack.rally_range = target.barrack.rally_range / this.range_factor
		end
	end

	if this.damage_factor and tween_remove then
		target.tower.damage_factor = target.tower.damage_factor / this.damage_factor
	end

	return tween_remove
end

scripts.tower_stage_14_broken_armory = {}

function scripts.tower_stage_14_broken_armory.update(this, store, script)
	local visuals = find_all_t(store, this.decal)[1]

	this.alert = find_all_t(store, this.alert)[1]
	this.alert.tween.reverse = true

	local run_anim_ts = store.tick_ts - (this.bubble_cd - math.random(5, 15))

	while true do
		if store.tick_ts - run_anim_ts > this.bubble_cd and store.player_gold >= this.repair_price then
			this.alert.render.sprites[1].hidden = false
			this.alert.render.sprites[1].ts = store.tick_ts
			this.alert.tween.ts = store.tick_ts
			this.alert.tween.reverse = false
			this.alert.tween.disabled = false

			U.animation_start(visuals, "broken_action", nil, store.tick_ts, false, 1)
			U.animation_start(this.alert, "loop", nil, store.tick_ts, true, 1)

			run_anim_ts = store.tick_ts
		end

		if not this.alert.tween.reverse and store.tick_ts - run_anim_ts > this.loop_bubble_time then
			this.alert.tween.ts = store.tick_ts
			this.alert.tween.reverse = true
			run_anim_ts = store.tick_ts - math.random(0, 10)
		end

		coroutine.yield()
	end
end

function scripts.tower_stage_14_broken_armory.remove(this, store, script)
	queue_remove(store, this.alert)

	return true
end

scripts.tower_stage_14_armory = {}

function scripts.tower_stage_14_armory.update(this, store, script)
	local b = this.barrack
	local tower_sid = 2
	local door_sid = 3
	local visuals = find_all_t(store, this.decal)[1]
	local achievement_tracker = find_all_t(store, this.achievement_tracker)[1]

	S:queue(this.repair_sound)
	S:queue(this.repair_taunt)
	U.animation_start(visuals, "fix", nil, store.tick_ts, nil, 1)

	local pow_a = this.powers and this.powers.skill_a or nil
	local pow_b = this.powers and this.powers.skill_b or nil

	local function check_max_level()
		if this.powers.skill_a.level == 1 and this.powers.skill_b.level == 3 then
			achievement_tracker.armory_maxed = true
		end
	end

	local function apply_upg_b(level)
		if level <= 0 then
			return
		end

		for i, s in ipairs(this.barrack.soldiers) do
			s.health.dead_lifetime = pow_b.respawn_times[level]
		end
	end

	local function check_powers()
		if not this.powers then
			return
		end

		for pn, p in pairs(this.powers) do
			if p.changed then
				p.changed = nil

				if p == pow_a then
					for i, s in ipairs(this.barrack.soldiers) do
						if s.health.dead then
							-- block empty
						else
							local nst = p.soldier_type
							local ns = E:create_entity(nst)

							ns.info.i18n_key = s.info.i18n_key
							ns.soldier.tower_id = this.id
							ns.soldier.tower_soldier_idx = i
							ns.pos = V.vclone(s.pos)
							ns.motion.dest = V.vclone(s.motion.dest)
							ns.motion.arrived = s.motion.arrived
							ns.render.sprites[1].flip_x = s.render.sprites[1].flip_x
							ns.render.sprites[1].flip_y = s.render.sprites[1].flip_y
							ns.render.sprites[1].name = s.render.sprites[1].name
							ns.render.sprites[1].loop = s.render.sprites[1].loop
							ns.render.sprites[1].ts = s.render.sprites[1].ts
							ns.render.sprites[1].runs = s.render.sprites[1].runs
							ns.nav_rally.pos = V.vclone(s.nav_rally.pos)
							ns.nav_rally.center = V.vclone(s.nav_rally.center)
							ns.nav_rally.new = s.nav_rally._first_forced and true or s.nav_rally.new
							ns.nav_rally._first_forced = s.nav_rally._first_forced

							for i, a in ipairs(ns.melee.attacks) do
								if s.melee.attacks[i] then
									a.ts = s.melee.attacks[i].ts
								end
							end

							U.replace_blocker(store, s, ns)

							this.barrack.soldiers[i] = ns

							queue_insert(store, ns)

							s.health.dead = true

							queue_remove(store, s)
						end
					end

					b.soldier_type = p.soldier_type

					apply_upg_b(pow_b.level)
				end

				if p == pow_b then
					apply_upg_b(p.level)
				end

				check_max_level()
			end
		end
	end

	U.y_wait(store, fts(10))

	find_all_t(store, this.mask)[1].render.sprites[1].hidden = false

	while true do
		check_powers()

		if not this.tower.blocked then
			for i = 1, b.max_soldiers do
				local s = b.soldiers[i]

				if not s or s.health.dead and not store.entities[s.id] then
					if b.has_door and not b.door_open then
						S:queue("GUITowerOpenDoor")
						U.animation_start(this, "open", nil, store.tick_ts, 1, door_sid)

						while not U.animation_finished(this, door_sid) do
							coroutine.yield()
						end

						b.door_open = true
						b.door_open_ts = store.tick_ts
					end

					s = E:create_entity(b.soldier_type)
					s.soldier.tower_id = this.id
					s.soldier.tower_soldier_idx = i
					s.pos = V.v(V.add(this.pos.x, this.pos.y, b.respawn_offset.x, b.respawn_offset.y))

					local c = v(this.pos.x + this.first_rally_offset.x, this.pos.y + this.first_rally_offset.y)

					s.nav_rally.pos, s.nav_rally.center = c, c
					s.nav_rally.new = true
					s.nav_rally._first_forced = true
					s.nav_rally._old_delay_max = s.nav_rally.delay_max
					s.nav_rally.delay_max = 0

					if pow_b.level > 0 then
						s.health.dead_lifetime = pow_b.respawn_times[pow_b.level]
					end

					queue_insert(store, s)

					b.soldiers[i] = s

					signal.emit("tower-spawn", this, s)
					U.y_wait(store, fts(25), function()
						check_powers()

						return false
					end)
				end
			end
		end

		if b.has_door and b.door_open and store.tick_ts - b.door_open_ts > b.door_hold_time then
			U.animation_start(this, "close", nil, store.tick_ts, 1, door_sid)

			while not U.animation_finished(this, door_sid) do
				coroutine.yield()
			end

			b.door_open = false
		end

		if b.rally_new then
			b.rally_new = false

			signal.emit("rally-point-changed", this)

			local all_dead = true

			for i, s in ipairs(b.soldiers) do
				s.nav_rally.pos, s.nav_rally.center = U.rally_formation_position(i, b, b.max_soldiers, b.rally_angle_offset)
				s.nav_rally.new = true
				all_dead = all_dead and s.health.dead
			end

			if not all_dead then
				S:queue(this.sound_events.change_rally_point)
			end
		end

		coroutine.yield()
	end
end

scripts.soldier_stage_14_armory = {}

function scripts.soldier_stage_14_armory.update(this, store, script)
	local brk, sta

	if this.vis._bans then
		this.vis.bans = this.vis._bans
		this.vis._bans = nil
	end

	while true do
		if this.cloak then
			this.vis.flags = band(this.vis.flags, bnot(this.cloak.flags))
			this.vis.bans = band(this.vis.bans, bnot(this.cloak.bans))
			this.render.sprites[1].alpha = 255
		end

		if not this.health.dead or SU.y_soldier_revive(store, this) then
			-- block empty
		else
			SU.y_soldier_death(store, this)

			return
		end

		if this.unit.is_stunned then
			SU.soldier_idle(store, this)
		else
			if this.dodge and this.dodge.active then
				this.dodge.active = false

				if this.dodge.counter_attack and this.powers[this.dodge.counter_attack.power_name].level > 0 then
					this.dodge.counter_attack_pending = true
				elseif this.dodge.animation then
					U.animation_start(this, this.dodge.animation, nil, store.tick_ts, 1)

					while not U.animation_finished(this) do
						coroutine.yield()
					end
				end

				signal.emit("soldier-dodge", this)
			end

			while this.nav_rally.new do
				if SU.y_soldier_new_rally(store, this) and not this.nav_rally._first_forced then
					goto label_1348_1
				end

				local b = store.entities[this.soldier.tower_id].barrack

				this.nav_rally.pos, this.nav_rally.center = U.rally_formation_position(this.soldier.tower_soldier_idx, b, b.max_soldiers)
				this.nav_rally.new = false
				this.nav_rally._first_forced = false
				this.nav_rally.delay_max = this.nav_rally._old_delay_max
			end

			if this.timed_actions then
				brk, sta = SU.y_soldier_timed_actions(store, this)

				if brk then
					goto label_1348_1
				end
			end

			if this.timed_attacks then
				brk, sta = SU.y_soldier_timed_attacks(store, this)

				if brk then
					goto label_1348_1
				end
			end

			if this.ranged and this.ranged.range_while_blocking then
				brk, sta = SU.y_soldier_ranged_attacks(store, this)

				if brk then
					goto label_1348_1
				end
			end

			if this.melee then
				brk, sta = SU.y_soldier_melee_block_and_attacks(store, this)

				if brk or sta ~= A_NO_TARGET then
					goto label_1348_1
				end
			end

			if this.ranged and not this.ranged.range_while_blocking then
				brk, sta = SU.y_soldier_ranged_attacks(store, this)

				if brk or sta == A_DONE then
					goto label_1348_1
				elseif sta == A_IN_COOLDOWN and not this.ranged.go_back_during_cooldown then
					goto label_1348_0
				end
			end

			if SU.soldier_go_back_step(store, this) then
				goto label_1348_1
			end

			::label_1348_0::

			SU.soldier_idle(store, this)

			if this.cloak then
				this.vis.flags = bor(this.vis.flags, this.cloak.flags)
				this.vis.bans = bor(this.vis.bans, this.cloak.bans)

				if this.cloak.alpha then
					this.render.sprites[1].alpha = this.cloak.alpha
				end
			end

			SU.soldier_regen(store, this)
		end

		::label_1348_1::

		coroutine.yield()
	end
end

scripts.controller_stage_14_houses = {}

function scripts.controller_stage_14_houses.update(this, store)
	local conts = {}
	local houses = find_all_t(store, this.bush_t)

	for i, h in pairs(houses) do
		local cont = E:create_entity(this.cont_t)

		cont.house_id = h.id

		queue_insert(store, cont)
		table.insert(conts, cont)
	end

	table.sort(houses, function(b1, b2)
		return b1.pos.x < b2.pos.x
	end)
	table.sort(conts, function(c1, c2)
		return store.entities[c1.house_id].pos.x < store.entities[c2.house_id].pos.x
	end)

	while true do
		if this.spawn_blades then
			conts[this.house_id].do_spawn = true
			conts[this.house_id].path_id = this.path_id
			conts[this.house_id].enemies_count = this.enemies_count
			this.spawn_blades = false
		end

		coroutine.yield()
	end
end

function scripts.controller_stage_14_houses.on_event(this, store, action, house_id, count)
	this.spawn_blades = true
	this.house_id = tonumber(house_id)
	this.enemies_count = tonumber(count)

	log.info("EVENT HOUSE SPAWN. COUNT: " .. this.enemies_count)
end

scripts.controller_stage_14_house_spawner = {}

function scripts.controller_stage_14_house_spawner.update(this, store)
	local house = store.entities[this.house_id]

	while true do
		if this.do_spawn then
			local start_ts = store.tick_ts

			U.y_wait(store, this.spawn_delay - (store.tick_ts - start_ts))

			local nearest_nodes = P:nearest_nodes(house.pos.x, house.pos.y, {
				this.path_id
			}, {
				1
			})
			local pi, spi, ni = unpack(nearest_nodes[1])

			for i = 1, this.enemies_count do
				local enemy = E:create_entity(this.enemy_t)

				enemy.nav_path.pi = this.path_id
				enemy.nav_path.ni = ni + 5
				enemy.nav_path.spi = math.random(1, 3)
				enemy.pos = V.vclone(house.pos)
				enemy.source_id = this.id

				queue_insert(store, enemy)
				U.y_wait(store, this.delay_between)
			end

			this.do_spawn = false
		end

		coroutine.yield()
	end
end

scripts.controller_stage_14_community_building_achievement = {}

function scripts.controller_stage_14_community_building_achievement.update(this, store)
	while true do
		if this.armory_maxed and this.blacksmith_maxed then
			signal.emit("community-building-stage14")
			queue_remove(store, this)

			return
		end

		coroutine.yield()
	end
end

scripts.easter_egg_stage_14_delorean = {}

function scripts.easter_egg_stage_14_delorean.update(this, store, script)
	local clicks = 0

	while true do
		if this.ui.clicked then
			this.ui.clicked = false
			clicks = clicks + 1

			if clicks == 1 then
				S:queue(this.sound_turn_on)
				U.y_animation_play(this, "tap_1", nil, store.tick_ts, 1, 1)
				U.animation_start(this, "loop_1", nil, store.tick_ts, true, 1)
			elseif clicks == 2 then
				S:stop(this.sound_turn_on)
				S:queue(this.sound_power_down)
				U.y_animation_play(this, "tap_2", nil, store.tick_ts, 1, 1)
				U.animation_start(this, "idle2", nil, store.tick_ts, true, 1)
				signal.emit("depower-of-love-stage14")

				return
			end
		end

		coroutine.yield()
	end
end

scripts.easter_egg_stage_14_goat_fall = {}

function scripts.easter_egg_stage_14_goat_fall.update(this, store, script)
	local clicks = 0

	while true do
		if this.ui.clicked then
			this.ui.clicked = false
			clicks = clicks + 1

			if this.sound_tap then
				if clicks > 1 then
					S:stop(this.sound_tap[clicks - 1])
				end

				local frame = this.sound_tap_frames and this.sound_tap_frames[clicks]

				S:queue(this.sound_tap[clicks], frame and frame > 0 and {
					delay = fts(frame)
				} or nil)
			end

			U.y_animation_play(this, "tap_" .. clicks, nil, store.tick_ts, 1, 1)
			U.animation_start(this, "idle_" .. clicks + 1, nil, store.tick_ts, true, 1)

			if clicks == 2 then
				return
			end
		end

		coroutine.yield()
	end
end

scripts.stage_14_goat_graveyard = {}

function scripts.stage_14_goat_graveyard.update(this, store, script)
	local taps_count = 0
	local eat_ts = store.tick_ts
	local eat_cd = fts(math.random(3 * FPS, 7 * FPS))

	while true do
		if this.ui.clicked and not features.censored_cn then
			this.ui.clicked = nil
			taps_count = taps_count + 1

			if taps_count == this.taps_to_explode then
				S:queue(this.sound)

				this.health.dead = true
				this.health.death_ts = store.tick_ts - 1

				U.y_animation_play(this, "death", nil, store.tick_ts, 1)

				break
			else
				U.animation_start(this, "tap", nil, store.tick_ts, 1)
			end
		end

		if eat_cd < store.tick_ts - eat_ts then
			local eat_cd = fts(math.random(3 * FPS, 7 * FPS))

			eat_ts = store.tick_ts

			U.animation_start(this, "eat", nil, store.tick_ts, false)
		end

		if this.render.sprites[1].name == "tap" and U.animation_finished(this) then
			U.animation_start(this, "idle", nil, store.tick_ts, 1)
		end

		if this.render.sprites[1].name == "eat" and U.animation_finished(this) then
			U.animation_start(this, "idle", nil, store.tick_ts, true)
		end

		coroutine.yield()
	end

	queue_remove(store, this)
end

scripts.controller_stage_15_lord_blackburn_wp = {}

function scripts.controller_stage_15_lord_blackburn_wp.on_event(this, store, action, x, y)
	local bb = find_all_t(store, "soldier_stage_15_lord_blackburn", true)[1]

	if bb then
		bb.waypoint(tonumber(x), tonumber(y))
	end
end

scripts.hero_stage_15_lord_blackburn = {}

function scripts.hero_stage_15_lord_blackburn.insert(this, store)
	this.melee.order = U.attack_order(this.melee.attacks)

	return true
end

function scripts.hero_stage_15_lord_blackburn.update(this, store)
	local brk, stam, star, blocked_enemy, counted_id
	local cauldron = find_all_t(store, "decal_stage_15_cauldron")[1]

	this.health_bar.hidden = false

	local function do_corruption(count)
		this.render.sprites[1].prefix = this.corruption.renders[count]
		-- this.info.portrait = this.corruption.portraits[count]
		this.info.hero_portrait = this.corruption.hero_portraits[count]
		this.ui.click_rect = this.corruption.click_rects[count]
		this.soldier.melee_slot_offset = this.corruption.melee_offsets[count]
		this.health_bar.offset = this.corruption.health_bar_offsets[count]
		this.hero.tombstone_decal = this.corruption.tombstones[count]
		this.health.hp_max = this.corruption.hp_max[count]
		this.health.hp = this.corruption.hp_max[count]
		this.health.armor = this.corruption.armor[count]
		this.health.magic_armor = this.corruption.magic_armor[count]
		this.regen.health = this.corruption.regen_health[count]
		this.melee.attacks[1].damage_min = this.corruption.damage_min[count]
		this.melee.attacks[1].damage_max = this.corruption.damage_max[count]
		this.melee.attacks[2].damage_min = this.corruption.damage_min[count]
		this.melee.attacks[2].damage_max = this.corruption.damage_max[count]
		this.melee.attacks[1].hit_fx = this.corruption.hit_fx[count]
		this.melee.attacks[2].hit_fx = this.corruption.hit_fx[count]

		signal.emit("change-stage-hero-image", this)
	end

	local function y_corrupt(count)
		this.corrupting = true
		this.ui.can_click = false
		this.health_bar.hidden = true
		this.health.ignore_damage = true

		local old_vis_bans = this.vis.bans

		this.vis.bans = F_ALL

		U.unblock_target(store, this)
		SU.remove_modifiers(store, this, nil, "mod_stage_15_black_burn_mind_control")

		if count == 4 then
			S:queue(this.sound_energy)
		end

		if count == 2 then
			U.animation_start(this, "cinematic", nil, store.tick_ts, false, 1)
			U.y_wait(store, fts(50))
		else
			U.animation_start(this, "transform", nil, store.tick_ts, false, 1)
			S:queue(this.sound_energy)
			U.y_wait(store, fts(52))
		end

		if count == 2 then
			U.y_wait(store, fts(19))
			U.animation_start(this, "cinematictalkloop2", nil, store.tick_ts, true, 1)
			U.y_wait(store, (store.level_mode_6 or store.level_mode) ~= GAME_MODE_KR1 and 10.5 or 0)
			U.animation_start(this, "cinematiccontinue2", nil, store.tick_ts, false, 1)
			U.y_wait(store, fts(29))

			local decal = E:create_entity(this.explosion_ground_decal)

			decal.pos = V.vclone(this.pos)
			decal.render.sprites[1].ts = store.tick_ts

			queue_insert(store, decal)
			S:queue(this.sound_power_up)
			U.y_wait(store, fts(82))
		elseif count == 4 then
			U.y_wait(store, fts(18))
			U.animation_start(this, "transformtalk", nil, store.tick_ts, true, 1)
			U.y_wait(store, 0.5)
			signal.emit("show-balloon_tutorial-pos", "S15_PRE_BOSS_01", false, V.v(this.pos.x - 6, this.pos.y + 60))
			U.y_wait(store, 3)
			U.animation_start(this, "transform2", nil, store.tick_ts, false, 1)
			S:queue(this.sound_power_up, {
				delay = 0.85
			})
			U.y_wait(store, fts(33))
			signal.emit("show-balloon_tutorial-pos", "S15_PRE_BOSS_02", false, V.v(this.pos.x - 6, this.pos.y + 85))
			S:queue(this.sound_jump, {
				delay = 4
			})
			U.y_wait(store, fts(73))
		else
			U.y_wait(store, fts(66))

			local decal = E:create_entity(this.explosion_ground_decal)

			decal.pos = V.vclone(this.pos)
			decal.render.sprites[1].ts = store.tick_ts

			queue_insert(store, decal)
			S:queue(this.sound_power_up)
			U.y_wait(store, fts(82))
		end

		if count >= 4 then
			local boss = E:create_entity(this.corruption.boss)

			boss.pos.x, boss.pos.y = this.pos.x, this.pos.y
			boss.render.sprites[1].flip_x = this.render.sprites[1].flip_x
			boss.render.sprites[1].hidden = true

			queue_insert(store, boss)
			coroutine.yield()

			boss.render.sprites[1].hidden = false
			this.render.sprites[1].hidden = true

			signal.emit("hide-stage-hero", this.id)
			queue_remove(store, this)

			return
		end

		this.health_bar.hidden = false
		this.ui.can_click = true
		this.health.ignore_damage = false
		this.vis.bans = old_vis_bans
		this.unit.is_stunned = false

		U.animation_start(this, "idle", nil, store.tick_ts, true, 1)
		do_corruption(count)

		this.corrupting = false
	end

	if not this.skip_cutscene then
		while not this.start_intro do
			coroutine.yield()
		end

		if string.find(this.render.sprites[1].prefix, "1") then
			U.y_wait(store, this.intro_drink_time)
			S:queue(this.sound_drink)
			U.y_wait(store, this.intro_explosion_time)
			S:queue(this.sound_power_up)
		end

		while not U.animation_finished(this, 1) do
			coroutine.yield()
		end
	end

	U.animation_start(this, "idle", nil, store.tick_ts, 1, 1)
	do_corruption(this.corrupt_count)

	while true do
		if blocked_enemy then
			if this.soldier.target_id ~= blocked_enemy.id then
				blocked_enemy = nil
			elseif blocked_enemy.health.dead then
				signal.emit("lord-of-destruction-stage15")

				counted_id = blocked_enemy.id
				blocked_enemy = nil
			end
		end

		if not blocked_enemy and this.soldier.target_id and this.soldier.target_id ~= counted_id then
			blocked_enemy = store.entities[this.soldier.target_id]
		end

		if this.corrupt then
			this.corrupt_count = this.corrupt_count + 1

			y_corrupt(this.corrupt_count)

			this.corrupt = false
		end

		if this.cutscene then
			-- block empty
		else
			if this.health.dead then
				SU.y_hero_death_and_respawn_kr5(store, this)
			end

			while this.nav_rally.new do
				if SU.y_hero_new_rally(store, this) then
					goto label_1360_0
				end
			end

			if this.melee then
				brk, stam = SU.y_soldier_melee_block_and_attacks(store, this)

				if brk or stam == A_DONE or stam == A_IN_COOLDOWN and not this.melee.continue_in_cooldown then
					goto label_1360_0
				end
			end

			if this.melee.continue_in_cooldown and stam == A_IN_COOLDOWN then
				-- block empty
			elseif SU.soldier_go_back_step(store, this) then
				-- block empty
			else
				SU.soldier_idle(store, this)
				SU.soldier_regen(store, this)
			end
		end

		::label_1360_0::

		coroutine.yield()
	end
end

function scripts.hero_stage_15_lord_blackburn.remove(this, store)
	return true
end

scripts.soldier_stage_15_lord_blackburn = {}

function scripts.soldier_stage_15_lord_blackburn.insert(this, store)
	local controller = find_all_t(store, "controller_stage_15_lord_blackburn")[1]

	if controller and controller.nav_rally_pos then
		this.nav_rally.pos = controller.nav_rally_pos
	else
		this.nav_rally.pos = V.vclone(this.pos)
	end

	this.melee.order = U.attack_order(this.melee.attacks)

	return true
end

function scripts.soldier_stage_15_lord_blackburn.update(this, store)
	local brk, stam, star
	local witch = find_all_t(store, "decal_stage_15_witch")[1]

	local function waypoint(x, y)
		U.unblock_target(store, this)

		this.nav_rally.new = true
		this.nav_rally.pos = v(x, y)
	end

	this.waypoint = waypoint

	local function rays()
		local towers = table.filter(store.entities, function(k, v)
			return not v.pending_removal and v.tower and v.tower.type ~= "holder"
		end)
		local n = #towers / 2
		local path_rays = math.random(3, 5)
		local delay = (n + path_rays) / fts(42)

		for i = 1, n do
			local id = get_random_round_robin(towers, 1, #towers).id
			local t = store.entities[id]
			local r = E:create_entity(this.decal_ray)

			r.pos = V.vclone(tpos(t))
			r.render.sprites[1].ts = store.tick_ts
			r._tower = t

			queue_insert(store, r)
			U.y_wait(store, fts(delay))
		end

		local points = generate_blue_noise_cluster(path_rays, 3, random_point_in_ellipse, REF_OX, REF_OX, 250, 250)

		for _, v in pairs(points) do
			local r = E:create_entity(this.decal_ray)

			r.pos = V.vclone(v)
			r.render.sprites[1].ts = store.tick_ts

			queue_insert(store, r)
			U.y_wait(store, fts(delay))
		end
	end

	local function death()
		local last_death = string.find(this.template_name, "3")

		if last_death then
			signal.emit("show-curtains")
			signal.emit("hide-gui")
			signal.emit("start-cinematic")
		end

		this.ui.can_click = false
		this.health.ignore_damage = true

		U.unblock_target(store, this)
		SU.remove_modifiers(store, this)
		U.animation_start(this, "death", nil, store.tick_ts, 1, 1)
		U.y_wait(store, this.death_sound_time)
		S:queue(this.sound_explosion)
		U.y_wait(store, this.death_time)
		U.y_wait(store, this.death_drink_time)
		S:queue(this.sound_drink)
		U.y_wait(store, this.death_time_explosion_ground)

		if witch then
			witch.reaction()
		end

		local decal = E:create_entity(this.explosion_ground_decal)

		decal.pos = this.pos
		decal.render.sprites[1].ts = store.tick_ts

		queue_insert(store, decal)
		S:queue(this.sound_power_up)

		while not U.animation_finished(this, 1) do
			coroutine.yield()
		end

		local controller = find_all_t(store, "controller_stage_15_lord_blackburn")[1]

		if controller then
			controller.nav_rally_pos = this.nav_rally.pos
		end

		if last_death then
			U.animation_start(this, "ending_loop", nil, store.tick_ts, true, 1)
			U.y_wait(store, fts(10))
			rays()
			U.y_wait(store, 2)

			store.lives = 0
		else
			SU.do_death_spawns(store, this)
			queue_remove(store, this)

			return
		end
	end

	if not this.skip_cutscene then
		if string.find(this.render.sprites[1].prefix, "1") then
			U.y_wait(store, this.intro_drink_time)
			S:queue(this.sound_drink)
			U.y_wait(store, this.intro_explosion_time)
			S:queue(this.sound_power_up)
		end

		while not U.animation_finished(this, 1) do
			coroutine.yield()
		end
	end

	U.animation_start(this, "idle", nil, store.tick_ts, 1, 1)

	while true do
		if this.health.dead then
			death()
		end

		while this.nav_rally.new do
			if SU.y_soldier_new_rally(store, this) then
				goto label_1365_0
			end
		end

		if this.melee then
			brk, stam = SU.y_soldier_melee_block_and_attacks(store, this)

			if brk or stam == A_DONE or stam == A_IN_COOLDOWN and not this.melee.continue_in_cooldown then
				goto label_1365_0
			end
		end

		if this.melee.continue_in_cooldown and stam == A_IN_COOLDOWN then
			-- block empty
		elseif SU.soldier_go_back_step(store, this) then
			-- block empty
		else
			SU.soldier_idle(store, this)
		end

		::label_1365_0::

		coroutine.yield()
	end
end

