scripts.mod_stage_15_black_burn_mind_control = {}

function scripts.mod_stage_15_black_burn_mind_control.insert(this, store, script)
	local target = store.entities[this.modifier.target_id]

	if target.sound_events then
		this.saved_rally_sound = target.sound_events.change_rally_point
		target.sound_events.change_rally_point = nil
	end

	target.nav_rally.new = true
	target.nav_rally.pos = this.target_pos
	target.nav_rally.center = this.target_pos
	target.nav_grid.waypoints = GR:find_waypoints(target.pos, this.target_pos, this.target_pos, target.nav_grid.valid_terrains, true) or {}
	target.motion.max_speed = target.motion.max_speed * this.modifier.speed_factor
	target.ui.can_click = false
	target.ui.can_select = false
	target.ui.can_hover = false
	target.ui.can_drag = false
	this.inserted = true

	return true
end

function scripts.mod_stage_15_black_burn_mind_control.remove(this, store, script)
	local target = store.entities[this.modifier.target_id]

	if target.sound_events then
		target.sound_events.change_rally_point = this.saved_rally_sound
	end

	target.nav_grid.waypoints = {}
	target.motion.max_speed = target.motion.max_speed / this.modifier.speed_factor
	target.ui.can_click = true
	target.ui.can_select = true
	target.ui.can_hover = true
	target.ui.can_drag = true

	return true
end

scripts.controller_stage_15_accusation_cinematic = {}

function scripts.controller_stage_15_accusation_cinematic.update(this, store, script)
	local cauldron = find_all_t(store, this.cauldron_t)[1]
	local swamps = find_all_t(store, this.swamps_t)[1]
	local mist = find_all_t(store, this.mist_t)[1]

	while true do
		if this.cinematic_trigger then
			local bb = find_all_t(store, this.blackburn_t)[1]

			if bb.health.dead then
				bb.force_respawn = true
			end

			bb.unit.is_stunned = true

			U.animation_start(bb, "idle", nil, store.tick_ts, true, 1)
			signal.emit("show-curtains")
			signal.emit("hide-gui")
			signal.emit("start-cinematic")
			signal.emit("pan-zoom-camera", 2, {
				x = 300,
				y = 500
			}, 1.5)

			local mod = E:create_entity(this.mod_t)

			mod.modifier.target_id = bb.id
			mod.target_pos = this.target_pos

			queue_insert(store, mod)

			local pre_wait_ts = store.tick_ts

			U.y_wait(store, 1e+99, function()
				return V.eq(bb.pos.x, bb.pos.y, this.target_pos.x, this.target_pos.y)
			end)

			bb.cutscene = true
			bb.health_bar.hidden = true

			if store.tick_ts - pre_wait_ts < 1.9 then
				U.y_wait(store, 1.9 - (store.tick_ts - pre_wait_ts))
			end

			S:queue(this.sound_energy)

			bb.render.sprites[1].flip_x = bb.pos.x > cauldron.pos.x + cauldron.ui.click_rect.pos.x
			bb.corrupt = true

			U.y_wait(store, fts(61) + 1)

			local bb_balloon_pos = V.v(bb.pos.x - 6, bb.pos.y + 60)

			signal.emit("show-balloon_tutorial-pos", "S15_MID_01", false, bb_balloon_pos)
			U.y_wait(store, 3.5)

			local witch_balloon_pos = cauldron.dialog_pos

			signal.emit("show-balloon_tutorial-pos", "S15_MID_02", false, witch_balloon_pos)
			U.y_wait(store, 3.5)
			signal.emit("show-balloon_tutorial-pos", "S15_MID_03", false, bb_balloon_pos)
			U.y_wait(store, 3.5)
			U.y_wait(store, fts(111) - 2)
			signal.emit("show-balloon_tutorial-pos", "S15_MID_04", false, witch_balloon_pos)
			U.y_wait(store, 3)
			S:queue(this.sound_boil, {
				delay = fts(14)
			})
			S:queue(this.sound_kick, {
				delay = 3.65
			})
			S:queue(this.sound_splash, {
				delay = 4.5
			})
			U.animation_start(cauldron, "cinematic", nil, store.tick_ts, 1, 1)
			U.y_wait(store, fts(133))

			local bubbles_controller = find_all_t(store, this.bubbles_controller_t)[1]

			scripts.controller_stage_15_swamp_bubbles.on_start_bubbles(bubbles_controller, store, nil, "5")

			local bubbles_random_controller = find_all_t(store, this.random_bubbles_controller_t)[1]

			bubbles_random_controller.disabled = false

			local mist = E:create_entity(this.mist_t)

			mist.pos.x, mist.pos.y = 512, 384
			mist.render.sprites[1].ts = store.tick_ts

			queue_insert(store, mist)

			local mask_1 = E:create_entity(this.swamp_mask_1_t)

			mask_1.pos.x, mask_1.pos.y = 512, 384
			mask_1.tween.ts = store.tick_ts

			queue_insert(store, mask_1)

			local mask_2 = E:create_entity(this.swamp_mask_2_t)

			mask_2.pos.x, mask_2.pos.y = 512, 384
			mask_2.tween.ts = store.tick_ts

			queue_insert(store, mask_2)
			U.y_wait(store, fts(15))
			U.animation_start(mist, "loop", nil, store.tick_ts, true, 1)
			U.y_wait(store, fts(24))
			scripts.controller_stage_15_swamp_bubbles.on_start_bubbles(bubbles_controller, store, nil, "6")
			U.y_animation_wait(cauldron, 1)
			queue_remove(store, mod)
			signal.emit("hide-curtains")
			signal.emit("show-gui")
			signal.emit("end-cinematic")
			signal.emit("accusation_cinematic_end")

			bb.cutscene = false

			local p = V.v(320, 590)
			local swamp_thing_t = "enemy_swamp_thing_g6"
			local swamp_thing = E:create_entity("enemy_swamp_thing_g6")
			local nn = P:nearest_nodes(p.x, p.y, {
				5
			}, {
				1,
				2,
				3
			}, true)[1]

			swamp_thing.nav_path.pi = nn[1]
			swamp_thing.nav_path.spi = 1
			swamp_thing.nav_path.ni = nn[3]
			swamp_thing.pos.x, swamp_thing.pos.y = p.x, p.y

			queue_insert(store, swamp_thing)

			if not U.is_seen(store, swamp_thing_t) then
				signal.emit("wave-notification", "icon", swamp_thing_t)
				U.mark_seen(store, swamp_thing_t)
			end

			U.animation_start(cauldron, "cinematic2", nil, store.tick_ts, 1, 1)
			U.y_animation_wait(cauldron, 1)

			cauldron.ui.can_click = false

			queue_remove(store, this)

			return
		end

		coroutine.yield()
	end
end

