scripts.enemy_boss_stage_15 = {}

function scripts.enemy_boss_stage_15.update(this, store, script)
	local ab = this.timed_attacks.list[1]
	local block_check_ts = store.tick_ts

	ab.ts = store.tick_ts

	local trigger_block
	local old_bans = this.vis.bans

	this.vis.bans = F_ALL

	local function cinematic_entrance()
		U.y_animation_play(this, "fromspawntoidle", nil, store.tick_ts, 1, 1)
		U.animation_start(this, "idle", nil, store.tick_ts, true, 1)

		local np = P:node_pos(this.start_path, 1, this.start_node)
		local shake, death_aura
		local nearest = false

		if V.dist2(this.pos.x, this.pos.y, np.x, np.y) <= math.pow(this.safe_area_to_jump, 2) then
			this.render.sprites[1].flip_x = false
			nearest = true
			this.final_cinematic_skip_jump = true
		else
			U.animation_start(this, "jump", nil, store.tick_ts, false, 1)
			U.y_wait(store, fts(31))

			shake = E:create_entity("aura_screen_shake")
			shake.aura.amplitude = 0.5
			shake.aura.duration = 0.2
			shake.aura.freq_factor = 1

			queue_insert(store, shake)
			U.y_animation_wait(this, 1)
			U.y_wait(store, 1)

			this.pos.x, this.pos.y = np.x, np.y
			this.render.sprites[1].flip_x = false

			U.animation_start(this, "jump2", nil, store.tick_ts, false, 1)
			U.y_wait(store, fts(5))

			death_aura = E:create_entity(this.fall_death_aura)
			death_aura.pos.x, death_aura.pos.y = np.x, np.y

			queue_insert(store, death_aura)

			shake = E:create_entity("aura_screen_shake")
			shake.aura.amplitude = 2
			shake.aura.duration = 0.2
			shake.aura.freq_factor = 4

			queue_insert(store, shake)
		end

		this.nav_path.pi = this.start_path
		this.nav_path.spi = 1
		this.nav_path.ni = not nearest and this.start_node or P:nearest_nodes(this.pos.x, this.pos.y, {
			this.start_path
		}, {
			1
		}, true)[1][3]

		U.y_wait(store, 0.5)
		signal.emit("show-balloon_tutorial-pos", "S15_PRE_BOSS_03", false, V.v(this.pos.x + 6, this.pos.y + 85))
		U.y_wait(store, 3)
		U.y_animation_wait(this, 1)

		this.vis.bans = old_bans
	end

	local function can_block()
		if this.cinematic then
			return true
		end

		if trigger_block then
			return true
		end

		if store.tick_ts - block_check_ts < 0.25 then
			return false
		end

		if store.tick_ts - ab.ts < ab.cooldown then
			return false
		end

		block_check_ts = store.tick_ts

		local aura_t = E:get_template(ab.aura)
		local towers = U.find_towers(store.entities, this.pos, 0, aura_t.aura.radius, function(v, o)
			return v.tower.type ~= "holder" and v.tower.type ~= "build_animation" and (not v.tower_holder or not v.tower_holder.blocked) and (not aura_t.aura.allowed_templates or table.contains(aura_t.aura.allowed_templates, v.template_name)) and (not aura_t.aura.excluded_templates or not table.contains(aura_t.aura.excluded_templates, v.template_name))
		end)

		trigger_block = towers and #towers > 0

		return trigger_block
	end

	local function y_on_death()
		signal.emit("boss_fight_end")
		LU.kill_all_enemies(store, true)
		S:stop_all()
		W:stop_manual_wave("BOSS1")

		local death_decal = E:create_entity(this.death_decal)

		death_decal.pos.x, death_decal.pos.y = this.pos.x, this.pos.y

		queue_insert(store, death_decal)
		S:queue(this.sound_death)

		this.render.sprites[1].hidden = true

		U.animation_start(death_decal, "end", nil, store.tick_ts, 1)
		U.y_animation_wait(death_decal, 1)
		U.animation_start(death_decal, "endloop", nil, store.tick_ts, true, 1)
		U.y_wait(store, 2)
		W:stop_manual_wave("BOSS_BUBBLES")
		signal.emit("boss-killed", this)

		this.bossfight_ended = true
	end

	this.in_cinematic = true

	cinematic_entrance()

	::label_1381_0::

	while true do
		this.in_cinematic = false

		if this.health.dead then
			y_on_death()

			return
		end

		if trigger_block then
			U.animation_start(this, ab.animation, nil, store.tick_ts, false)
			S:queue(ab.sound, {
				delay = fts(6)
			})

			local fl = this.render.sprites[1].flip_x
			local hit_pos = V.vclone(this.pos)

			if ab.hit_offset then
				hit_pos.x = hit_pos.x + (fl and -1 or 1) * ab.hit_offset.x
				hit_pos.y = hit_pos.y + ab.hit_offset.y
			end

			if ab.hit_decal then
				local fx = E:create_entity(ab.hit_decal)

				fx.pos = V.vclone(hit_pos)
				fx.render.sprites[1].ts = store.tick_ts

				queue_insert(store, fx)
			end

			if SU.y_enemy_wait(store, this, ab.hit_time) then
				goto label_1381_0
			end

			ab.ts = store.tick_ts

			if ab.hit_fx then
				local fx = E:create_entity(ab.hit_fx)

				fx.pos = V.vclone(hit_pos)
				fx.render.sprites[1].ts = store.tick_ts

				queue_insert(store, fx)
			end

			local dmg_aura = E:create_entity(ab.damage_aura)

			dmg_aura.pos = V.vclone(this.pos)

			queue_insert(store, dmg_aura)

			local shake = E:create_entity("aura_screen_shake")

			shake.aura.amplitude = 2
			shake.aura.duration = 0.35
			shake.aura.freq_factor = 2

			queue_insert(store, shake)

			local aura = E:create_entity(ab.aura)

			aura.aura.source_id = this.id
			aura.aura.ts = store.tick_ts
			aura.pos = V.vclone(this.pos)

			queue_insert(store, aura)
			U.y_animation_wait(this)

			trigger_block = false
		end

		if not SU.y_enemy_mixed_walk_melee_ranged(store, this, false, can_block, can_block) then
			-- block empty
		else
			coroutine.yield()
		end
	end
end

scripts.controller_stage_15_swamp_spawner = {}

function scripts.controller_stage_15_swamp_spawner.update(this, store, script)
	local spawn_set = this.spawn_data
	local aux = {}

	for i = 1, spawn_set[2] do
		local e, s_pos, pi, spi, ni
		local spawn_points = store.entities[spawn_set[4]]

		if spawn_set[5] then
			s_pos = spawn_points.center_spawn
			pi, spi, ni = spawn_set[3], 1, 1
		else
			s_pos = spawn_points.graveyard.spawn_pos[get_random_round_robin(aux, #spawn_points.graveyard.spawn_pos)]

			local nearest_nodes = P:nearest_nodes(s_pos.x, s_pos.y, spawn_set[3] and {
				spawn_set[3]
			} or nil, {
				1,
				2,
				3
			})

			if #nearest_nodes < 1 then
				log.error("swamps controller %s could not spawn enemy. node not found near %s,%s", this.id, s_pos.x, s_pos.y)

				break
			end

			pi, spi, ni = unpack(nearest_nodes[1])
		end

		local enemy = spawn_set[1]

		if not U.is_seen(store, enemy) then
			signal.emit("wave-notification", "icon", enemy)
			U.mark_seen(store, enemy)
		end

		e = E:create_entity(enemy)
		e.nav_path.pi, e.nav_path.spi, e.nav_path.ni = pi, spi, ni
		e.pos = V.vclone(s_pos)
		e.render.sprites[1].name = "raise"
		e.motion.forced_waypoint = P:node_pos(e.nav_path)

		queue_insert(store, e)
		U.y_wait(store, this.spawn_interval)
	end

	queue_remove(store, this)
end

scripts.controller_stage_15_swamps = {}

function scripts.controller_stage_15_swamps.spawn_event(this, store, spawn, path_id, amount, force_center)
	local int_pid = tonumber(path_id)
	local int_am = tonumber(amount)
	local swamp_id = this.path_spawner_map[int_pid]
	local swamp = find_all_t(store, this.swamp_t, false, function(k, v)
		return v.swamp_id == swamp_id
	end)[1]

	if not swamp then
		log.error("ERROR: No swamp found of id: %s", swamp_id)

		return
	end

	local spawner = E:create_entity(this.spawner_t)

	spawner.spawn_data = {
		spawn,
		int_am,
		int_pid,
		swamp.id,
		force_center
	}

	queue_insert(store, spawner)
end

function scripts.controller_stage_15_swamps.on_event_1(this, store, action, path_id, amount)
	scripts.controller_stage_15_swamps.spawn_event(this, store, "enemy_swamp_husk", path_id, amount)
end

function scripts.controller_stage_15_swamps.on_event_2(this, store, action, path_id)
	scripts.controller_stage_15_swamps.spawn_event(this, store, "enemy_swamp_thing_g6", path_id, "1", true)
end

scripts.controller_stage_15_swamp_bubbles = {}

function scripts.controller_stage_15_swamp_bubbles.on_start_bubbles(this, store, action, path_id)
	local int_pid = tonumber(path_id)
	local swamp_id = this.path_spawner_map[int_pid]
	local bubbler = find_all_t(store, this.bubble_spawner_t, false, function(k, v)
		return v.swamp_id == swamp_id
	end)[1]

	if not bubbler then
		log.error("ERROR: No swamp found of id: %s", swamp_id)

		return
	end

	bubbler.bubble = true
	bubbler.spawn_data = {
		this.bubble_count,
		this.bubble_scales,
		this.bubble_intervals
	}
end

function scripts.controller_stage_15_swamp_bubbles.on_end_bubbles(this, store, action, path_id)
	local int_pid = tonumber(path_id)
	local swamp_id = this.path_spawner_map[int_pid]
	local bubbler = find_all_t(store, this.bubble_spawner_t, false, function(k, v)
		return v.swamp_id == swamp_id
	end)[1]

	if not bubbler then
		log.error("ERROR: No swamp found of id: %s", swamp_id)

		return
	end

	bubbler.bubble = false
end

scripts.controller_stage_15_swamp_bubbles_spawner = {}

function scripts.controller_stage_15_swamp_bubbles_spawner.update(this, store, script)
	local bubble_positions = generate_blue_noise_cluster(8, 40, random_point_in_ellipse, this.pos.x, this.pos.y, this.radius, this.radius * 0.7)
	local bubbling = false
	local bubbles = {}
	local sound_ts

	while true do
		if this.bubble and not bubbling then
			bubbling = true
			sound_ts = store.tick_ts + U.frandom(this.bubble_sound_interval[1], this.bubble_sound_interval[2])

			local bubble_count_range = this.spawn_data[1]
			local bubble_scale_range = this.spawn_data[2]
			local bubble_interval_range = this.spawn_data[3]
			local aux = {}

			for i = 1, math.random(bubble_count_range[1], bubble_count_range[2]) do
				local scale = U.frandom(bubble_scale_range[1], bubble_scale_range[2])
				local bubble_pos = bubble_positions[get_random_round_robin(aux, 8)]
				local bubble = E:create_entity(this.bubble_t)

				bubble.duration = 1e+99
				bubble.pos = V.v(bubble_pos.x, bubble_pos.y)
				bubble.render.sprites[1].scale = V.vv(scale)

				queue_insert(store, bubble)
				table.insert(bubbles, bubble)
				U.y_wait(store, U.frandom(bubble_interval_range[1], bubble_interval_range[2]))
			end
		end

		if not this.bubble and bubbling then
			bubbling = false

			local bubble_interval_range = this.spawn_data[3]

			for i, b in ipairs(bubbles) do
				b.duration = 0

				U.y_wait(store, U.frandom(bubble_interval_range[1], bubble_interval_range[2]))
			end

			bubbles = {}
		end

		if bubbling and sound_ts <= store.tick_ts then
			S:queue(this.bubble_sound)

			sound_ts = store.tick_ts + U.frandom(this.bubble_sound_interval[1], this.bubble_sound_interval[2])
		end

		coroutine.yield()
	end
end

scripts.controller_stage_15_bubble_decorations = {}

function scripts.controller_stage_15_bubble_decorations.update(this, store, script)
	local decals = find_all_t(store, this.decal_t)

	if not decals or #decals == 0 then
		log.error("ERROR: No decals on stage to cause bubbles.")
		queue_remove(store, this)

		return
	end

	for i, d in ipairs(decals) do
		d.render.sprites[1].hidden = true
	end

	while this.disabled do
		coroutine.yield()
	end

	local temp = {}

	while true do
		U.y_wait(store, math.random(this.bubble_cd_min, this.bubble_cd_max))

		local bi = get_random_round_robin(temp, 1, #decals)

		decals[bi].render.sprites[1].hidden = false

		U.animation_start(decals[bi], "loop", nil, store.tick_ts, false, 1)
	end
end

scripts.controller_stage_15_wave_report = {}

function scripts.controller_stage_15_wave_report.on_end_wave_14(this, store, action)
	this.no_more_enemies = true
end

scripts.easter_egg_stage_15_the_ring = {}

function scripts.easter_egg_stage_15_the_ring.update(this, store, script)
	local loop_2_ts = store.tick_ts

	local function queue_tap_sounds()
		if this.sound_lid_open then
			S:queue(this.sound_lid_open, {
				delay = fts(this.sound_lid_open_frame)
			})
		end

		for i, id in ipairs(this.sound_samara_glitch or {}) do
			S:queue(id, {
				delay = fts(this.sound_samara_glitch_frames[i])
			})
		end
	end

	while true do
		if store.tick_ts - loop_2_ts > this.loop_2_cd then
			U.animation_start(this, "loop_2", nil, store.tick_ts, false, 1)

			while not U.animation_finished(this) do
				if this.ui and this.ui.clicked then
					this.ui.clicked = false

					queue_tap_sounds()
					U.y_animation_play(this, "tap", nil, store.tick_ts, 1, 1)
					U.animation_start(this, "loop_3", nil, store.tick_ts, true, 1)

					return
				end

				coroutine.yield()
			end

			loop_2_ts = store.tick_ts

			U.animation_start(this, "loop_1", nil, store.tick_ts, true, 1)
		end

		if this.ui and this.ui.clicked then
			this.ui.clicked = false

			queue_tap_sounds()
			U.y_animation_play(this, "tap", nil, store.tick_ts, 1, 1)
			U.animation_start(this, "loop_3", nil, store.tick_ts, true, 1)

			return
		end

		coroutine.yield()
	end
end

scripts.easter_egg_stage_15_the_simpsons = {}

function scripts.easter_egg_stage_15_the_simpsons.update(this, store, script)
	local clicks = 0
	local ts = store.tick_ts

	U.y_animation_wait(this)
	U.animation_start(this, "idle", nil, store.tick_ts, true)

	while true do
		::label_1400_0::

		if this.ui and this.ui.clicked then
			this.ui.clicked = false
			clicks = clicks + 1

			if clicks == 1 then
				S:queue(this.sound_tap_1)
				U.animation_start(this, "tap", nil, store.tick_ts, false)

				while not U.animation_finished(this) do
					if this.ui.clicked then
						goto label_1400_0
					end

					coroutine.yield()
				end
			elseif clicks == 2 then
				S:queue(this.sound_tap_2)
				U.y_animation_play(this, "tap_final", nil, store.tick_ts, 1)
				signal.emit("three-eyes-on-every-fish-stage15", this)
				queue_remove(store, this)

				return
			end
		end

		if store.tick_ts - ts > this.duration then
			U.y_animation_play(this, "disappear", nil, store.tick_ts, 1)
			queue_remove(store, this)

			return
		end

		coroutine.yield()
	end
end

scripts.controller_easter_egg_stage_15_simpsons = {}

function scripts.controller_easter_egg_stage_15_simpsons.update(this, store, script)
	while true do
		if store.wave_group_number > 6 then
			local random = math.random(this.min_time, this.max_time)

			U.y_wait(store, random)

			local f = E:create_entity(this.fish_t)

			f.pos = V.vclone(this.spawn_pos[math.random(1, #this.spawn_pos)])

			queue_insert(store, f)
		end

		coroutine.yield()
	end
end

scripts.controller_stage_16_tree_cut = {}

function scripts.controller_stage_16_tree_cut.on_event(this, store, action)
	this.tree_cut = true
end

function scripts.controller_stage_16_tree_cut.update(this, store)
	local holders_to_hide = table.filter(store.entities, function(k, v)
		return v.tower and v.tower_holder and table.contains(this.holders_to_reveal, v.tower.holder_id)
	end)

	for i, h in ipairs(holders_to_hide) do
		h.render.sprites[1].hidden = true
		h.render.sprites[2].hidden = true
		h.tower.blocked = true
		h.ui.can_click = false
		h.tower.can_hover = false
	end

	local forest = find_all_t(store, this.forest_t)[1]

	local function spawn_treant(t, th)
		local treant = E:create_entity(t)

		treant.pos = V.vclone(th.pos)
		treant.tower.holder_id = th.tower.holder_id
		treant.tower.holder_template = th.tower_holder and not th.tower_holder.blocked and th.template_name or th.tower.holder_template

		if th.tower.terrain_style then
			treant.tower.terrain_style = th.tower.terrain_style
			treant.render.sprites[1].name = string.format(treant.render.sprites[1].name, th.tower.terrain_style)
		end

		if treant.ui and th.ui then
			treant.ui.nav_mesh_id = th.ui.nav_mesh_id
		end

		queue_insert(store, treant)
		queue_remove(store, th)
		signal.emit("tower-upgraded", treant, th)
		signal.emit("tower-removed", treant, th)

		return treant
	end

	local function spawn_fx(fx_t, pos, scale)
		local fx = E:create_entity(fx_t)

		fx.pos = V.vclone(pos)
		fx.render.sprites[1].ts = store.tick_ts

		queue_insert(store, fx)
	end

	local function y_spawn_sequence(t)
		local tt, cover_scale, start_offset, target_holder = unpack(t)
		local th = find_all_t(store, this.treant_holders_t, false, function(k, v)
			return v.tower and v.tower.holder_id == target_holder
		end)[1]
		local b = E:create_entity(this.trail_t)

		b.bullet.from = V.v(forest.pos.x + start_offset.x, forest.pos.y + start_offset.y)
		b.bullet.to = V.v(th.pos.x, th.pos.y + 8)
		b.pos = V.vclone(b.bullet.from)

		queue_insert(store, b)
		coroutine.yield()

		local ts = store.tick_ts

		U.y_wait(store, 1e+99, function()
			return not store.entities[b.id]
		end)
		spawn_fx(this.cover_fx_t, th.pos, cover_scale)

		local treant = spawn_treant(tt, th)

		return store.tick_ts - ts
	end

	local ts = store.tick_ts
	local wait = U.frandom(this.idle_anim_interval_min, this.idle_anim_interval_max)

	while true do
		if wait < store.tick_ts - ts then
			U.animation_start(forest, "everyxseconds", nil, store.tick_ts)

			ts = store.tick_ts
			wait = U.frandom(this.idle_anim_interval_min, this.idle_anim_interval_max)
		end

		if this.tree_cut then
			if (store.level_mode_6 or store.level_mode) == GAME_MODE_CAMPAIGN then
				signal.emit("pan-zoom-camera", 2, {
					x = forest.pos.x + this.cinematic_camera_offset.x,
					y = forest.pos.y + this.cinematic_camera_offset.y
				}, 1.5)
				signal.emit("show-curtains")
				signal.emit("hide-gui")
				signal.emit("start-cinematic")
			end

			U.animation_start(forest, "break", nil, store.tick_ts)
			U.y_wait(store, fts(107))

			for i, h in ipairs(holders_to_hide) do
				h.render.sprites[1].hidden = false
				h.render.sprites[2].hidden = false
				h.tower.blocked = false
				h.ui.can_click = true
				h.tower.can_hover = true
			end

			U.y_wait(store, fts(133))

			local w = y_spawn_sequence(this.treants_t[1])

			U.y_wait(store, fts(39) - w)

			local w = y_spawn_sequence(this.treants_t[2])

			U.y_wait(store, fts(26) - w)

			local w = y_spawn_sequence(this.treants_t[3])

			U.y_wait(store, fts(48) - w)

			local b = E:create_entity(this.brigand_t)
			local trf = forest.render.frames[1]
			local tra_idx = trf.exo_frame and trf.exo_frame.exo.attach_points and trf.exo_frame.exo.attach_idx.brigand
			local tra_part_idx = tra_idx and trf.exo_frame.a and trf.exo_frame.a[tra_idx]
			local tra = tra_part_idx and trf.exo_frame[tra_part_idx]
			local attach_offset_x, attach_offset_y = unpack(tra, 4, 5)
			local attach_pos = V.v(forest.pos.x + attach_offset_x, forest.pos.y + attach_offset_y)

			b.pos = attach_pos
			b.nav_path.pi = this.brigand_path
			b.nav_path.spi = 3
			b.nav_path.ni = P:nearest_nodes(b.pos.x, b.pos.y, {
				this.brigand_path
			}, {
				3
			})[1][3]
			b.render.sprites[1].hidden = true
			b.unit.is_stunned = true

			queue_insert(store, b)
			U.y_animation_wait(forest, 1)

			b.render.sprites[1].hidden = false

			U.animation_start(forest, "idleend", nil, store.tick_ts, true)

			if (store.level_mode_6 or store.level_mode) == GAME_MODE_CAMPAIGN then
				signal.emit("hide-curtains")
				signal.emit("pan-zoom-camera", 2, {
					x = forest.pos.x,
					y = forest.pos.y
				}, OVm(1, 1.3))
				signal.emit("show-gui")
				signal.emit("end-cinematic")
			end

			b.unit.is_stunned = false

			signal.emit("tree_cut_end")
			coroutine.yield()

			local swapper = E:create_entity("controller_stage_16_treant_swapper")

			queue_insert(store, swapper)
			queue_remove(store, this)

			return
		end

		coroutine.yield()
	end
end

scripts.controller_stage_16_treant_swapper = {}

function scripts.controller_stage_16_treant_swapper.update(this, store)
	local treants = {}
	local scales = {}

	for _, t in ipairs(this.treants_t) do
		local tt, cs = unpack(t)

		treants[tt] = find_all_t(store, tt)[1]
		scales[tt] = cs
	end

	while true do
		if this.swap then
			this.swap = false

			local t1 = treants[this.swap_treant_1]
			local t2 = treants[this.swap_treant_2]
			local s1 = scales[this.swap_treant_1]
			local s2 = scales[this.swap_treant_2]
			local swap_t1 = E:create_entity(this.swap_t)

			swap_t1.treant_from = t1
			swap_t1.treant_to = t2
			swap_t1.cover_scale = s1

			queue_insert(store, swap_t1)

			local swap_t2 = E:create_entity(this.swap_t)

			swap_t2.treant_from = t2
			swap_t2.treant_to = t1
			swap_t2.cover_scale = s2

			queue_insert(store, swap_t2)
		end

		coroutine.yield()
	end
end

scripts.controller_stage_16_single_swap = {}

function scripts.controller_stage_16_single_swap.update(this, store)
	local t1 = this.treant_from
	local t2 = this.treant_to
	local t2_pos = V.vclone(t2.pos)
	local pt1 = V.v(t1.pos.x + t1.render.sprites[2].offset.x, t1.pos.y + t1.render.sprites[2].offset.y)
	local pt2 = V.v(t2.pos.x + t2.render.sprites[2].offset.x, t2.pos.y + t2.render.sprites[2].offset.y)
	local bt = E:create_entity(this.trail_t)

	bt.bullet.from = pt1
	bt.bullet.to = pt2
	bt.pos = V.vclone(bt.bullet.from)

	queue_insert(store, bt)

	local smfx = E:create_entity(this.cover_fx_t)

	smfx.pos = V.vclone(pt1)
	smfx.render.sprites[1].ts = store.tick_ts
	smfx.render.sprites[1].scale = this.cover_scale

	queue_insert(store, smfx)
	U.animation_start(t1, t1.root_anim, nil, store.tick_ts, true, 2)
	coroutine.yield()

	local ts = store.tick_ts

	U.y_wait(store, 1e+99, function()
		return not store.entities[bt.id]
	end)

	local fx = E:create_entity(this.cover_fx_t)

	fx.pos = V.vclone(pt2)
	fx.render.sprites[1].ts = store.tick_ts
	fx.render.sprites[1].scale = this.cover_scale

	queue_insert(store, fx)

	t1.pos = t2_pos

	U.animation_start(t1, "idle", nil, store.tick_ts, true, 2)

	t1.swapping = false
	t2.swapping = false

	queue_remove(store, this)
end

scripts.tower_stage_16_treant_commons = {}

function scripts.tower_stage_16_treant_commons.check_for_swap(this, store)
	if this.user_selection.actions.tw_free_action.allowed and this.user_selection.in_progress then
		if not this.swapper then
			this.swapper = find_all_t(store, this.swapper_t)[1]
		end

		if not this.treants then
			this.treants = {}
		end

		local target_treant_t = string.format(this.treant_t_basis, this.user_selection.arg)
		local target_treant

		if this.treants[target_treant_t] then
			target_treant = this.treants[target_treant_t]
		else
			local tt = find_all_t(store, target_treant_t)[1]

			this.treants[target_treant_t] = tt
			target_treant = tt
		end

		this.user_selection.in_progress = false
		this.user_selection.actions.tw_free_action.allowed = false
		target_treant.user_selection.actions.tw_free_action.allowed = false

		U.y_wait(store, 1e+99, function()
			return target_treant.can_swap and this.can_swap
		end)

		this.swapper.swap = true
		this.swapper.swap_treant_1 = this.template_name
		this.swapper.swap_treant_2 = target_treant_t
		target_treant.swapping = true
		this.swapping = true

		if this.on_swap then
			this.on_swap()
		end

		if target_treant.on_swap then
			target_treant.on_swap()
		end

		U.y_wait(store, 1e+99, function()
			return not this.swapping
		end)
		coroutine.yield()

		if this.on_post_swap then
			this.on_post_swap()
		end

		if target_treant.on_post_swap then
			target_treant.on_post_swap()
		end

		target_treant.user_selection.actions.tw_free_action.allowed = true
		this.user_selection.actions.tw_free_action.allowed = true
	end
end

scripts.tower_stage_16_treant_attacker = {}

function scripts.tower_stage_16_treant_attacker.update(this, store)
	this.can_swap = true

	local aa = this.attacks.list[1]

	while true do
		if aa and store.tick_ts - aa.ts > aa.cooldown then
			this.can_swap = false

			local pred_time = aa.cast_time + E:get_template(E:get_template(aa.bullet).bullet.hit_payload).time_to_blow
			local target, targets = U.find_foremost_enemy(store.entities, this.pos, aa.min_range, aa.max_range, pred_time, aa.vis_flags, aa.vis_bans)

			if not targets or #targets == 0 then
				SU.delay_attack(store, aa, fts(5))

				this.can_swap = true
			else
				U.animation_start(this, aa.animation, nil, store.tick_ts, false, 2)
				U.y_wait(store, aa.cast_time)

				local nearest = P:nearest_nodes(this.pos.x, this.pos.y)

				nearest = table.filter(nearest, function(k, v)
					return v[4] < this.attacks.range
				end)

				local count = 0
				local tries = 0

				for i = 1, aa.projectile_count do
					local point

					if #targets == 0 then
						local n = nearest[math.random(1, #nearest)]

						point = P:node_pos(n[1], n[2], n[3])
					else
						local t = get_random_round_robin(targets, 1)

						point = V.vclone(t.__ffe_pos)
					end

					local b = E:create_entity(aa.bullet)

					b.pos.x, b.pos.y = tpos(this).x + aa.bullet_start_offset.x, tpos(this).y + aa.bullet_start_offset.y
					b.bullet.from = V.vclone(b.pos)
					b.bullet.to = v(point.x, point.y)
					b.bullet.source_id = this.id

					queue_insert(store, b)
					U.y_wait(store, fts(3))
				end

				U.y_animation_wait(this, 2)

				aa.ts = store.tick_ts
				this.can_swap = true

				U.animation_start(this, "idle", nil, store.tick_ts, true, 2)
			end
		end

		scripts.tower_stage_16_treant_commons.check_for_swap(this, store)
		coroutine.yield()
	end
end

scripts.controller_stage_16_rider_fog_emitter = {}

function scripts.controller_stage_16_rider_fog_emitter.update(this, store)
	local interval = 1 / (this.emission_rate or 6)
	local last_ts = store.tick_ts - interval
	local dir_x, dir_y = 0, 0

	while true do
		local target = store.entities[this.target_id]

		if this.finished or not target or target.health and target.health.dead then
			queue_remove(store, this)

			return
		end

		if interval <= store.tick_ts - last_ts then
			last_ts = store.tick_ts

			local dx = target.motion.dest.x - target.pos.x
			local dy = target.motion.dest.y - target.pos.y
			local d = math.sqrt(dx * dx + dy * dy)

			if d > 0.001 then
				dir_x, dir_y = dx / d, dy / d
			end

			local off = this.trail_offset or 0
			local fx = E:create_entity(this.trail_fx)

			fx.pos.x = target.pos.x - dir_x * off
			fx.pos.y = target.pos.y - dir_y * off

			local s = fx.render.sprites[1]

			s.flip_x = math.random() < 0.5
			s.scale = V.vv(U.frandom(this.trail_scale[1], this.trail_scale[2]))

			queue_insert(store, fx)
			U.animation_start(fx, "run", nil, store.tick_ts, false, 1)
		end

		coroutine.yield()
	end
end

scripts.tower_stage_16_treant_killer = {}

function scripts.tower_stage_16_treant_killer.on_corromper_tree(this, store, event_name, tree_name)
	if tree_name ~= this.tower.tree_name then
		return
	end

	this.attacks.list[1].ability = "bullets"
	this.ui.can_click = false
	this.tower.can_hover = false
	this.transforming = true

	U.animation_start(this, "transformation", nil, store.tick_ts, false, 2)

	if this.update_started then
		S:queue(this.sound_transformation, this.sound_transformation_args)
	end
end

function scripts.tower_stage_16_treant_killer.on_tirar_treants(this, store, event_name, tree_name, zone)
	if tree_name ~= this.tower.tree_name then
		return
	end

	if this.attacks.list[1].ability ~= "bullets" then
		return
	end

	this.pending_bullets_zone = tonumber(zone) or 1
end

function scripts.tower_stage_16_treant_killer.zone_landing_nodes(this, aa, zone)
	local center = this.tower["bullets_zone_" .. zone]

	if not center or center.x == 0 and center.y == 0 then
		return nil
	end

	local radius = this.tower.bullets_zone_radius or 90
	local min_dist = this.tower.bullets_min_dist or 50
	local near = P:nearest_nodes(center.x, center.y, nil, nil, true)
	local base = near and near[1]

	if not base then
		return nil
	end

	local pi = base[1]
	local nsub = 1

	while P:path(pi, nsub + 1) do
		nsub = nsub + 1
	end

	nsub = math.min(3, nsub)

	local path = P:path(pi, 1)
	local cands = {}

	for ni = 1, #path do
		local o = path[ni]

		if radius >= V.dist(o.x, o.y, center.x, center.y) then
			cands[#cands + 1] = ni
		end
	end

	if #cands == 0 then
		cands = {
			base[3]
		}
	end

	local chosen = {}
	local pool = {}
	local relax = false

	for i = 1, #cands do
		pool[i] = cands[i]
	end

	while #chosen < aa.projectile_count and #cands > 0 do
		if #pool == 0 then
			for i = 1, #cands do
				pool[i] = cands[i]
			end

			relax = true
		end

		local ni = table.remove(pool, math.random(1, #pool))
		local rspi = math.random(1, nsub)
		local p = P:node_pos(pi, rspi, ni)
		local ok = true

		if not relax then
			for _, c in ipairs(chosen) do
				if min_dist > V.dist(p.x, p.y, c.pos.x, c.pos.y) then
					ok = false

					break
				end
			end
		end

		if ok then
			chosen[#chosen + 1] = {
				pi = pi,
				spi = rspi,
				ni = ni,
				pos = p
			}
		end
	end

	return chosen
end

function scripts.tower_stage_16_treant_killer.fire_bullets(this, store, aa, zone)
	local points = {}
	local znodes = zone and scripts.tower_stage_16_treant_killer.zone_landing_nodes(this, aa, zone)

	if znodes and #znodes > 0 then
		for _, n in ipairs(znodes) do
			points[#points + 1] = n.pos
		end
	else
		local pred_time = aa.cast_time + E:get_template(E:get_template(aa.bullet).bullet.payload).time_to_blow
		local target, targets = U.find_foremost_enemy(store.entities, this.pos, aa.min_range, aa.max_range, pred_time, aa.vis_flags, aa.vis_bans)
		local nearest = P:nearest_nodes(this.pos.x, this.pos.y)
		local in_range = table.filter(nearest, function(k, v)
			return v[4] < this.attacks.range
		end)
		local nodes = #in_range > 0 and in_range or nearest

		for i = 1, aa.projectile_count do
			if targets and #targets > 0 then
				local t = get_random_round_robin(targets, 1)

				points[i] = V.vclone(t.__ffe_pos)
			else
				local n = nodes[math.random(1, #nodes)]

				points[i] = P:node_pos(n[1], n[2], n[3])
			end
		end
	end

	U.animation_start(this, "attack_corrupted", nil, store.tick_ts, false, 2)
	S:queue(aa.sound, aa.sound_args)
	U.y_wait(store, aa.cast_time)

	for i = 1, #points do
		local point = points[i]
		local b = E:create_entity(aa.bullet)

		b.pos.x, b.pos.y = tpos(this).x + aa.bullet_start_offset.x, tpos(this).y + aa.bullet_start_offset.y
		b.bullet.from = V.vclone(b.pos)
		b.bullet.to = v(point.x, point.y)
		b.bullet.source_id = this.id

		queue_insert(store, b)
		U.y_wait(store, fts(3))
	end

	U.y_animation_wait(this, 2)
end

function scripts.tower_stage_16_treant_killer.instakill_area(this, store, aa)
	local TONGUE_TIP_REACH = 129
	local rally_pos = this.tower.default_rally_pos
	local candidates = U.find_enemies_in_range(store.entities, rally_pos, 0, aa.instakill_detection_radius, F_INSTAKILL, bor(F_BOSS, F_FLYING))
	local center

	if not candidates then
		center = V.vclone(rally_pos)
	else
		local predicted_positions = {}

		for _, enemy in ipairs(candidates) do
			table.insert(predicted_positions, P:predict_enemy_pos(enemy, aa.node_prediction))
		end

		if #predicted_positions == 1 then
			center = V.vclone(predicted_positions[1])
		else
			local best_group, best_count, best_distance = nil, 0, math.huge

			for _, candidate_pos in ipairs(predicted_positions) do
				local group = {}

				for _, predicted_pos in ipairs(predicted_positions) do
					if U.is_inside_ellipse(predicted_pos, candidate_pos, aa.instakill_radius) then
						table.insert(group, predicted_pos)
					end
				end

				local distance = V.dist(candidate_pos.x, candidate_pos.y, rally_pos.x, rally_pos.y)

				if best_count < #group or #group == best_count and distance < best_distance then
					best_group = group
					best_count = #group
					best_distance = distance
				end
			end

			center = v(0, 0)

			for _, predicted_pos in ipairs(best_group) do
				center.x = center.x + predicted_pos.x
				center.y = center.y + predicted_pos.y
			end

			center.x = center.x / best_count
			center.y = center.y / best_count
		end
	end

	U.animation_start(this, aa.animation, nil, store.tick_ts, false, 2)
	S:queue(this.sound_instakill, this.sound_instakill_args)
	U.y_wait(store, fts(6))

	local origin = v(tpos(this).x + 0, tpos(this).y + 40)
	local tongue = E:create_entity("fx_stage_16_treant_killer_tongue")

	tongue.pos.x, tongue.pos.y = origin.x, origin.y

	local s = tongue.render.sprites[1]

	s.r = V.angleTo(center.x - origin.x, center.y - origin.y)
	s.scale = V.v(V.dist(center.x, center.y, origin.x, origin.y) / TONGUE_TIP_REACH, 1)

	queue_insert(store, tongue)
	U.animation_start(tongue, "run", nil, store.tick_ts, false, 1)
	U.y_wait(store, fts(2))

	local enemies = U.find_enemies_in_range(store.entities, center, 0, aa.instakill_radius, F_INSTAKILL, bor(F_BOSS, F_FLYING))

	if enemies then
		S:queue(this.sound_eat, this.sound_eat_args)

		for _, enemy in pairs(enemies) do
			local m = E:create_entity("mod_stage_16_treant_killer_tangle")

			m.modifier.source_id = this.id
			m.modifier.target_id = enemy.id

			queue_insert(store, m)

			local fx = E:create_entity("fx_stage_16_treant_killer_tangle")

			fx.pos = V.vclone(enemy.pos)
			fx.render.sprites[1].flip_x = enemy.render.sprites[1].flip_x

			queue_insert(store, fx)
			U.animation_start(fx, "run", nil, store.tick_ts, false, 1)
		end

		U.y_wait(store, fts(5))

		for _, enemy in pairs(enemies) do
			if store.entities[enemy.id] and not enemy.health.dead then
				enemy.unit.can_explode = false
				enemy.unit.death_animation = nil
				enemy.unit.hide_during_death = true

				local d = E:create_entity("damage")

				d.source_id = this.id
				d.target_id = enemy.id
				d.damage_type = bor(DAMAGE_EAT, DAMAGE_INSTAKILL, DAMAGE_NO_SPAWNS)

				queue_damage(store, d)
				signal.emit("last-march-of-the-treants-stage16")
			end
		end
	end

	U.y_animation_wait(this, 2)

	if enemies then
		U.animation_start(this, "eat", nil, store.tick_ts, false, 2)
		U.y_animation_wait(this, 2)
	end

	return enemies ~= nil
end

function scripts.tower_stage_16_treant_killer.update(this, store)
	this.update_started = true

	local aa = this.attacks.list[1]

	if aa.ability == "bullets" then
		this.ability_available = true
		this.ui.can_click = false
		this.transforming = nil

		U.animation_start(this, "idle_corrupted", nil, store.tick_ts, true, 2)
	else
		this.ability_available = false
		this.ui.can_click = false

		U.animation_start(this, "sleep_loop", nil, store.tick_ts, true, 2, true)

		while store.wave_group_number < 1 do
			coroutine.yield()
		end

		if aa.ability == "instakill" then
			U.animation_start(this, "wake_up", nil, store.tick_ts, false, 2)
			U.y_animation_wait(this, 2)
		end

		this.ability_available = true
		this.ui.clicked = nil

		if aa.ability == "instakill" then
			this.ui.can_click = true

			U.animation_start(this, "idle", nil, store.tick_ts, true, 2)
		end
	end

	while true do
		if this.transforming then
			U.y_animation_wait(this, 2)

			this.transforming = nil

			U.animation_start(this, "idle_corrupted", nil, store.tick_ts, true, 2)
		end

		local action, zone

		if this.ability_available and this.pending_bullets_zone then
			zone = this.pending_bullets_zone
			this.pending_bullets_zone = nil
			action = "bullets_zone"
		elseif this.ability_available and this.ui.clicked then
			this.ui.clicked = nil
			action = "click"
		elseif this.ui.clicked then
			this.ui.clicked = nil
		end

		if action then
			local action_performed = true

			this.ability_available = false
			this.ui.can_click = false

			if action == "bullets_zone" then
				scripts.tower_stage_16_treant_killer.fire_bullets(this, store, aa, zone)
			elseif aa.ability == "bullets" then
				scripts.tower_stage_16_treant_killer.fire_bullets(this, store, aa)
			else
				action_performed = scripts.tower_stage_16_treant_killer.instakill_area(this, store, aa)
			end

			if not action_performed then
				U.animation_start(this, "idle", nil, store.tick_ts, true, 2)

				this.ability_available = true
				this.ui.can_click = true
			elseif aa.ability == "bullets" then
				U.animation_start(this, "idle_corrupted", nil, store.tick_ts, true, 2)

				this.ability_available = true
			else
				local function corrupted()
					return aa.ability ~= "instakill"
				end

				if not corrupted() then
					U.animation_start(this, "sleep_start", nil, store.tick_ts, false, 2)

					while not U.animation_finished(this, 2) and not corrupted() do
						coroutine.yield()
					end
				end

				if not corrupted() then
					U.animation_start(this, "sleep_loop", nil, store.tick_ts, true, 2, true)
					U.y_wait(store, aa.cooldown, corrupted)
				end

				if corrupted() then
					this.ability_available = true
				else
					U.animation_start(this, "wake_up", nil, store.tick_ts, false, 2)
					U.y_animation_wait(this, 2)

					this.ability_available = true

					if aa.ability == "instakill" then
						this.ui.can_click = true

						U.animation_start(this, "idle", nil, store.tick_ts, true, 2)
					end
				end
			end
		end

		coroutine.yield()
	end
end

scripts.editor_treant_killer = {}

function scripts.editor_treant_killer.insert(this, store)
	scripts.editor_tower.insert(this, store)

	this.editor.killer_zone_ids = {}

	for i = 1, 3 do
		local field = "bullets_zone_" .. i
		local p = E:create_entity("editor_treant_killer_zone_point")

		queue_insert(store, p)

		p.tower_id = this.id
		this.editor.killer_zone_ids[i] = p.id

		if this.tower[field] and (this.tower[field].x ~= 0 or this.tower[field].y ~= 0) then
			p.pos = this.tower[field]
		else
			p.pos = V.v(this.pos.x + (i - 2) * 60, this.pos.y - 60)
			this.tower[field] = p.pos
		end
	end

	return true
end

function scripts.editor_treant_killer.remove(this, store)
	scripts.editor_tower.remove(this, store)

	if this.editor.killer_zone_ids then
		for _, id in ipairs(this.editor.killer_zone_ids) do
			local p = store.entities[id]

			if p then
				queue_remove(store, p)
			end
		end
	end

	return true
end

scripts.tower_stage_16_treant_healer = {}

function scripts.tower_stage_16_treant_healer.update(this, store)
	this.can_swap = true

	local aa = this.attacks.list[1]
	local aura
	local decals = {}

	local function on_swap()
		aa.done = false

		for i, ds in ipairs(decals) do
			queue_remove(store, ds[1])
			queue_remove(store, ds[2])
		end

		decals = {}

		if aura then
			queue_remove(store, aura)
		end
	end

	this.on_swap = on_swap

	while true do
		if not aa.done and not this.swapping then
			aa.done = true

			local tower_pos = tpos(this)

			S:queue(aa.sound, {
				delay = fts(4)
			})

			aura = E:create_entity(aa.aura)
			aura.pos.x, aura.pos.y = tower_pos.x, tower_pos.y

			queue_insert(store, aura)

			local inc = math.pi / 5

			for i = 1, 10 do
				local pe = U.point_on_ellipse(tpos(this), aura.aura.radius * 0.6, inc * (i - 1))

				if P:valid_node_nearby(pe.x, pe.y) then
					local small_decal = E:create_entity(aa.decal_mist)
					local flowers_decal = E:create_entity(aa.decal)
					local p = {}

					for i, v in ipairs(P.paths) do
						table.insert(p, i)
					end

					local nn = P:nearest_nodes(pe.x, pe.y, p, {
						1
					})[1]
					local np = P:node_pos(nn[1], nn[2], nn[3] + math.random(aa.min_cloud_node_offset, aa.max_cloud_node_offset))

					small_decal.pos.x, small_decal.pos.y = np.x, np.y
					small_decal.render.sprites[1].ts = store.tick_ts - math.random(0, fts(30))

					queue_insert(store, small_decal)

					flowers_decal.pos.x, flowers_decal.pos.y = np.x, np.y
					flowers_decal.render.sprites[1].flip_x = math.random(0, 1) >= 0.5

					queue_insert(store, flowers_decal)
					table.insert(decals, {
						small_decal,
						flowers_decal
					})
				end
			end
		end

		scripts.tower_stage_16_treant_commons.check_for_swap(this, store)
		coroutine.yield()
	end
end

scripts.tower_stage_16_treant_rooter = {}

function scripts.tower_stage_16_treant_rooter.update(this, store)
	this.can_swap = true

	local aa = this.attacks.list[1]
	local aura
	local roots = {}

	local function determine_root_spread()
		local positions = generate_blue_noise_cluster(aa.amount_of_roots, 20, random_point_in_ellipse, this.pos.x, this.pos.y, aa.range, aa.range * 0.7)
		local remove = {}

		for i, p in ipairs(positions) do
			if not P:valid_node_nearby(p.x, p.y, 0.8) then
				table.insert(remove, p)
			end
		end

		this.cached_root_positions = positions

		for i, r in ipairs(remove) do
			table.removeobject(positions, r)
		end
	end

	local function on_swap()
		aa.done = false

		for i, r in ipairs(roots) do
			r.duration = 0
		end

		roots = {}
		this.cached_root_positions = {}

		if aura then
			queue_remove(store, aura)
		end
	end

	this.on_swap = on_swap

	function this.on_post_swap()
		determine_root_spread()

		aa.done = false
	end

	determine_root_spread()

	while true do
		if not aa.done and not this.swapping then
			aa.done = true

			local tower_pos = tpos(this)

			S:queue(aa.sound, {
				delay = fts(4)
			})

			aura = E:create_entity(aa.aura)
			aura.pos.x, aura.pos.y = tower_pos.x, tower_pos.y

			queue_insert(store, aura)

			for i, rp in ipairs(this.cached_root_positions) do
				local root = E:create_entity(aa.roots[math.random(1, #aa.roots)])

				root.pos.x, root.pos.y = rp.x, rp.y

				local d = V.dist(rp.x, rp.y, tower_pos.x, tower_pos.y)

				root.delay_animation_start = 0.3 * (d / aura.aura.radius)
				root.name = nil

				queue_insert(store, root)
				table.insert(roots, root)
			end
		end

		scripts.tower_stage_16_treant_commons.check_for_swap(this, store)
		coroutine.yield()
	end
end

scripts.easter_egg_stage_16_deku_sprout = {}

function scripts.easter_egg_stage_16_deku_sprout.update(this, store, script)
	local ts = store.tick_ts

	while true do
		::label_1435_0::

		if this.ui.clicked then
			if this.sound_tap_in then
				S:queue(this.sound_tap_in, {
					delay = fts(this.sound_tap_in_frame)
				})
			end

			if this.sound_tap_out then
				S:queue(this.sound_tap_out, {
					delay = fts(this.sound_tap_out_frame)
				})
			end

			U.y_animation_play(this, "run", nil, store.tick_ts, 1, 1)
			queue_remove(store, this)

			return
		end

		if store.tick_ts - ts > this.anim_cd then
			U.animation_start(this, "shake", nil, store.tick_ts, false, 1)

			while not U.animation_finished(this) do
				if this.ui.clicked then
					goto label_1435_0
				end

				coroutine.yield()
			end

			ts = store.tick_ts

			U.animation_start(this, "idle", nil, store.tick_ts, false, 1)
		end

		coroutine.yield()
	end
end

scripts.tower_stage_17_joust = {}

function scripts.tower_stage_17_joust.update(this, store)
	local lady = find_all_t(store, this.lady_t)[1]

	this.ui.can_click = false

	while store.wave_group_number == 0 do
		coroutine.yield()
	end

	S:queue(this.sound_horse_gallop)
	U.y_animation_play(this, this.start_anim, nil, store.tick_ts, 1)

	this.ui.can_click = true

	U.animation_start(this, this.idle_anim, nil, store.tick_ts, false)

	local idle_ts = store.tick_ts
	local lady_idle_ts = store.tick_ts

	while true do
		if this.user_selection.in_progress and not this.tower_action.active then
			local choice = this.user_selection.arg

			this.user_selection.in_progress = nil
			this.user_selection.allowed = false
			this.tower_action.active = true
			store.player_gold = store.player_gold - this.tower_action.cost

			local result = math.random(0, 1) == 0 and "red" or "blue"

			U.animation_start(this, result .. "Win", nil, store.tick_ts, false, 1)

			local delay_joust_start, delay_clash, delay_knocked_out, delay_win, delay_lose

			if result == "red" then
				delay_joust_start = fts(79)
				delay_clash = fts(129)
				delay_knocked_out = fts(147)
				delay_win = fts(169)
				delay_lose = fts(180)
			else
				delay_joust_start = fts(87)
				delay_clash = fts(137)
				delay_knocked_out = fts(155)
				delay_win = fts(180)
				delay_lose = fts(180)
			end

			S:queue(this.sound_battle_cry)
			S:queue(this.sound_joust_start, {
				delay = delay_joust_start
			})
			S:queue(this.sound_clash, {
				delay = delay_clash
			})
			S:queue(this.sound_knocked_out, {
				delay = delay_knocked_out
			})

			if result == choice then
				S:queue(this.sound_player_win, {
					delay = delay_win
				})
				S:queue(this.sound_lady_win, {
					delay = delay_win
				})
			else
				S:queue(this.sound_player_lose, {
					delay = delay_lose
				})
				S:queue(this.sound_lady_lose, {
					delay = delay_lose
				})
			end

			U.y_wait(store, fts(179))
			U.animation_start(lady, result == choice and "celebration" or "sad", nil, store.tick_ts, false, 1)

			if result == choice then
				local v = V.v(this.pos.x + this.show_gold_offset.x, this.pos.y + this.show_gold_offset.y)
				local reward = E:create_entity(this.gold_reward_t)

				reward.pos.x, reward.pos.y = v.x, v.y
				reward.render.sprites[1].ts = store.tick_ts
				reward.reward = this.bet.payout_mult * this.tower_action.cost

				queue_insert(store, reward)
				signal.emit("feeling-lucky-stage17")
			end

			U.y_animation_wait(this, 1)
			U.y_wait(store, this.bet.cooldown)

			this.tower_action.active = false
			this.user_selection.allowed = true
			this.user_selection.in_progress = nil

			S:queue(this.sound_horse_gallop)
			U.y_animation_play(this, this.start_anim, nil, store.tick_ts, 1)
		end

		if store.tick_ts - idle_ts >= 5 then
			U.animation_start(this, this.idle_anim, nil, store.tick_ts, false)

			idle_ts = store.tick_ts
		end

		if store.tick_ts - lady_idle_ts >= 14 then
			U.animation_start(lady, this.idle_lady_anim, nil, store.tick_ts, false)

			lady_idle_ts = store.tick_ts
		end

		coroutine.yield()
	end
end

