	end

	if this.render.sprites[1].size_scales then
		this.render.sprites[1].scale = this.render.sprites[1].size_scales[target.unit.size]
	end

	this.pos = target.pos

	U.y_animation_play(this, this.animation_enter, nil, store.tick_ts, 1, 1)
	scripts.mod_track_target.update(this, store)
end

function scripts.controller_stage_17_castle_paladins.e_insert(this, store)
	local r = E:create_entity("editor_rally_point")

	queue_insert(store, r)

	r.tower_id = this.id
	this.editor.rally_point_id = r.id

	if this.default_rally_pos and this.default_rally_pos.x ~= 0 and this.default_rally_pos.y ~= 0 then
		r.pos = this.default_rally_pos
	else
		r.pos = V.v(this.pos.x + 50, this.pos.y + 50)
		this.default_rally_pos = r.pos
