scripts.stage_17_blacksmith = {}

function scripts.stage_17_blacksmith.update(this, store, script)
	local ts = store.tick_ts

	while true do
		::label_1459_0::

		if this.ui.clicked then
			U.y_animation_play(this, "click", nil, store.tick_ts, 1)
			U.animation_start(this, "idle_yunke", nil, store.tick_ts, true)

			return
		end

		if store.tick_ts - ts > this.loop_time then
			U.animation_start(this, "hamer", nil, store.tick_ts, false)

			while not U.animation_finished(this) do
				if this.ui.clicked then
					goto label_1459_0
				end

				coroutine.yield()
			end

			U.animation_start(this, "loop", nil, store.tick_ts, false)

			ts = store.tick_ts
		end

		coroutine.yield()
	end
end

scripts.nightfall_dissolve = {}

function scripts.nightfall_dissolve.quad_screen_rect(pos, s)
	local sd = I:s(s.name)

	if not sd or not sd.f_quad or not sd.size then
		return nil
	end

	local rs = sd.ref_scale or 1
	local sx = rs * (s.scale and s.scale.x or 1)
	local sy = rs * (s.scale and s.scale.y or 1)
	local ax = s.anchor and s.anchor.x or 0.5
	local ay = s.anchor and s.anchor.y or 0.5
	local trim = sd.trim or {
		0,
		0,
		0,
		0
	}
	local x = pos.x + (s.offset and s.offset.x or 0)
	local y = REF_H - (pos.y + (s.offset and s.offset.y or 0))

	return x - (ax * sd.size[1] - trim[1]) * sx, y - ((1 - ay) * sd.size[2] - trim[2]) * sy, sd.f_quad[3] * sx, sd.f_quad[4] * sy
end

function scripts.nightfall_dissolve.front_noise(px, py)
	local n = 0.5 + 0.3 * math.sin(px * 2.1 + py * 1.3) + 0.2 * math.sin(px * 1 - py * 2.6 + 1.7)

	return math.max(0, math.min(1, n))
end

function scripts.nightfall_dissolve.refresh_view_args(args, store)
	local gs = game.game_scale
	local rox, roy

	if game.camera then
		local c = game.camera

		rox = -(c.x * c.zoom - game.screen_w / 2)
		roy = -(c.y * c.zoom - game.screen_h / 2)
		gs = gs * c.zoom
	else
		rox = game.game_ref_origin.x
		roy = game.game_ref_origin.y
	end

	if store.world_offset then
		rox = rox + store.world_offset.x
		roy = roy + store.world_offset.y
	end

	args.view_off = args.view_off or {
		0,
		0
	}
	args.view_off[1], args.view_off[2] = rox, roy
	args.view_scale = gs
end

function scripts.nightfall_dissolve.find_swap_from(this, store)
	for _, e in pairs(store.entities) do
		if e.template_name == this.swap_from and e.pos and (not this.holder_id or e.tower and e.tower.holder_id == this.holder_id) and V.dist(e.pos.x, e.pos.y, this.pos.x, this.pos.y) < 8 then
			return e
		end
	end

	return nil
end

function scripts.nightfall_dissolve.find_tower_over(this, store)
	for _, e in pairs(store.entities) do
		if e.tower and e.tower.holder_template == this.swap_from and e.pos and (not this.holder_id or e.tower.holder_id == this.holder_id) and V.dist(e.pos.x, e.pos.y, this.pos.x, this.pos.y) < 8 then
			return e
		end
	end

	return nil
end

function scripts.nightfall_dissolve.find_replace_from(this, store)
	for _, e in pairs(store.entities) do
		if e.template_name == this.replace_from and e.pos and V.dist(e.pos.x, e.pos.y, this.pos.x, this.pos.y) < 8 then
			return e
		end
	end

	return nil
end

function scripts.nightfall_dissolve.do_swap(this, store, insert_fn)
	local tpl = E:get_template(this.swap_to)
	local swap_style = tpl and tpl.tower and tpl.tower.terrain_style
	local best = scripts.nightfall_dissolve.find_swap_from(this, store)

	if best then
		local h = E:create_entity(this.swap_to)

		h.pos = V.vclone(best.pos)

		if h.tower and best.tower then
			h.tower.default_rally_pos = best.tower.default_rally_pos
			h.tower.holder_id = best.tower.holder_id
		end

		if h.ui and best.ui then
			h.ui.nav_mesh_id = best.ui.nav_mesh_id
		end

		if insert_fn then
			insert_fn(h)

			for _, s in ipairs(best.render.sprites) do
				s.hidden = true
			end
		else
			queue_insert(store, h)
		end

		queue_remove(store, best)

		local buy_c = find_all_t(store, "controller_show_buy_available")[1]

		if buy_c then
			buy_c.force_check = true
		end
	else
		local tw = scripts.nightfall_dissolve.find_tower_over(this, store)

		if tw then
			tw.tower.holder_template = this.swap_to

			if swap_style then
				tw.tower.terrain_style = swap_style

				local twt = E:get_template(tw.template_name)

				for i = 1, 2 do
					local ts = twt and twt.render and twt.render.sprites[i]
					local s = tw.render and tw.render.sprites[i]

					if ts and s and type(ts.name) == "string" and string.find(ts.name, "%%") then
						s.name = string.format(ts.name, swap_style)
					end
				end
			end
		elseif this.swap_from then
			log.warning("nightfall_dissolve: no encontré \"%s\" ni torre encima en (%s,%s)", tostring(this.swap_from), tostring(this.pos.x), tostring(this.pos.y))
		end
	end
end

function scripts.nightfall_dissolve.update(this, store)
	if this._final_applied then
		return
	end

	local SH = require("klove.shader_db")
	local qrect = scripts.nightfall_dissolve.quad_screen_rect
	local find_swap_from = scripts.nightfall_dissolve.find_swap_from
	local find_tower_over = scripts.nightfall_dissolve.find_tower_over
	local find_replace_from = scripts.nightfall_dissolve.find_replace_from

	local function find_driver()
		if this.transition_id then
			return store.entities[this.transition_id]
		end

		local name = this.nightfall_name or "decal_stage_18_nightfall"

		for _, e in pairs(store.entities) do
			if e.template_name == name then
				return e
			end
		end

		return nil
	end

	local function full_cover_fire(driver_args, e)
		e = e or this

		local br = driver_args and (driver_args.mask_rect or driver_args.bg_rect)

		if not br or not br[3] or br[3] == 0 or not br[4] or br[4] == 0 then
			return 1
		end

		local bx, by, bw, bh = br[1], br[2], br[3], br[4]
		local amp = driver_args.noise_amp or 0
		local max_fire = 0

		for _, s in ipairs(e.render.sprites) do
			if not s.hidden and (e ~= this or s.shader) then
				local qx, qy, qw, qh = qrect(e.pos, s)

				if qx then
					for _, c in ipairs({
						{
							qx,
							qy
						},
						{
							qx + qw,
							qy
						},
						{
							qx,
							qy + qh
						},
						{
							qx + qw,
							qy + qh
						}
					}) do
						local bluvx = (c[1] - bx) / bw
						local bluvy = (c[2] - by) / bh
						local prog

						if driver_args.origin and driver_args.dist_scale then
							local dx = (bluvx - driver_args.origin[1]) * driver_args.dist_scale[1]
							local dy = (bluvy - driver_args.origin[2]) * driver_args.dist_scale[2]

							prog = math.sqrt(dx * dx + dy * dy)
						else
							local dir = driver_args.dir or {
								0,
								1
							}
							local dl = math.sqrt(dir[1] * dir[1] + dir[2] * dir[2])

							if dl == 0 then
								dl = 1
							end

							prog = (bluvx - 0.5) * dir[1] / dl + (bluvy - 0.5) * dir[2] / dl + 0.5
						end

						local fire = (prog + amp) / (1 + amp)

						if max_fire < fire then
							max_fire = fire
						end
					end
				end
			end
		end

		if max_fire <= 0 then
			return 1
		end

		return math.min(max_fire, 1)
	end

	local function share_driver(driver, sid)
		local ns = driver.render.sprites[sid]
		local nfr = driver.render.frames and driver.render.frames[sid]
		local na = ns and ns.shader_args

		if not na then
			return nil
		end

		for i, s in ipairs(this.render.sprites) do
			if s.shader and not s.hidden then
				s.shader_args = na

				local fr = this.render.frames and this.render.frames[i]

				if fr then
					fr.shader_args = na

					if nfr and nfr.shader then
						fr.shader = nfr.shader
					end
				end
			end
		end

		return na
	end

	local tpl = this.swap_to and E:get_template(this.swap_to)
	local swap_style = tpl and tpl.tower and tpl.tower.terrain_style
	local sid = this.transition_sid or 1

	local function config_holder()
		for i = 1, #this.render.sprites do
			local ts = tpl.render.sprites[i]
			local s = this.render.sprites[i]

			if ts then
				s.name = ts.name
				s.offset = V.v(ts.offset.x, ts.offset.y)
				s.z = ts.z
				s.flip_x = ts.flip_x
				s.hidden = ts.hidden
				s.sort_y_offset = (ts.sort_y_offset or 0) - 0.1
			else
				s.hidden = true
				s.shader_args = nil
			end
		end
	end

	local function config_tower(tw)
		local twt = E:get_template(tw.template_name)
		local pt = twt and twt.render and twt.render.sprites[1] and twt.render.sprites[1].name
		local live = tw.render and tw.render.sprites[1]

		if not swap_style or not live or type(pt) ~= "string" or not string.find(pt, "%%") then
			return false
		end

		local s = this.render.sprites[1]

		s.name = string.format(pt, swap_style)
		s.offset = V.v(live.offset.x, live.offset.y)
		s.z = live.z
		s.flip_x = live.flip_x
		s.hidden = false
		s.sort_y_offset = (live.sort_y_offset or 0) - 0.1

		for i = 2, #this.render.sprites do
			this.render.sprites[i].hidden = true
		end

		return true
	end

	local function config_none()
		for _, s in ipairs(this.render.sprites) do
			if s.shader then
				s.hidden = true
			end
		end
	end

	if tpl then
		config_holder()
	else
		for _, s in ipairs(this.render.sprites) do
			if s.shader then
				s.sort_y_offset = (s.sort_y_offset or 0) - 0.1
			end
		end
	end

	coroutine.yield()

	local fire, driver, driver_args, replaced, replaced_args
	local hide_target = this.hide_from and find_replace_from({
		replace_from = this.hide_from,
		pos = this.pos
	}, store) or nil
	local hide_args

	if hide_target then
		hide_args = {
			invert = 1
		}

		local tsh = this.transition_shader or "p_dissolve_reveal"
		local hsh = SH:clone(tsh, tsh .. "#invert:" .. this.id)

		for i, s in ipairs(hide_target.render.sprites) do
			if not s.hidden then
				s.shader_args = hide_args

				local fr = hide_target.render.frames and hide_target.render.frames[i]

				if fr then
					fr.shader = hsh
					fr.shader_args = hide_args
				end
			end
		end
	end

	local cut_args, cut_sh, cut_target

	if this.swap_from then
		cut_args = {
			invert = 1
		}

		local tsh = this.transition_shader or "p_dissolve_reveal"

		cut_sh = SH:clone(tsh, tsh .. "#swapcut:" .. this.id)
	end

	local function unwire_swap_cut()
		if cut_target and store.entities[cut_target.id] and cut_target.render.frames then
			for _, cfr in ipairs(cut_target.render.frames) do
				if cfr.shader == cut_sh then
					cfr.shader = nil
					cfr.shader_args = nil
				end
			end
		end

		cut_target = nil
	end

	local function wire_swap_cut(target, only)
		if cut_target == target then
			return
		end

		unwire_swap_cut()

		if not target then
			return
		end

		cut_target = target

		for i, s in ipairs(target.render.sprites) do
			if not s.hidden and (not only or only[i]) then
				s.shader_args = cut_args

				local cfr = target.render.frames and target.render.frames[i]

				if cfr then
					cfr.shader = cut_sh
					cfr.shader_args = cut_args
				end
			end
		end
	end

	local function tower_terrain_indices(tw)
		local twt = E:get_template(tw.template_name)
		local only, any = {}, false

		for i = 1, 2 do
			local ts = twt and twt.render and twt.render.sprites[i]

			if ts and type(ts.name) == "string" and string.find(ts.name, "%%") then
				only[i] = true
				any = true
			end
		end

		return any and only or nil
	end

	local function visual_fire()
		local f = full_cover_fire(driver_args)

		if hide_target and store.entities[hide_target.id] then
			f = math.max(f, full_cover_fire(driver_args, hide_target))
		end

		return math.min(1, f + ((driver_args.edge_width or 0) + (driver_args.edge_softness or 0)) / (1 + (driver_args.noise_amp or 0)))
	end

	local function resync()
		driver = find_driver()
		driver_args = driver and share_driver(driver, sid) or nil

		if tpl then
			fire = driver_args and full_cover_fire(driver_args) or nil

			if fire and cut_target and store.entities[cut_target.id] then
				fire = math.max(fire, full_cover_fire(driver_args, cut_target))
			end
		elseif this.replace_from then
			fire = 1
		else
			fire = driver_args and visual_fire() or nil
		end
	end

	if cut_args then
		wire_swap_cut(find_swap_from(this, store))
	end

	resync()

	if this.replace_from then
		replaced = find_replace_from(this, store)

		if replaced then
			replaced_args = {
				invert = 1
			}

			local rsh = SH:clone("p_corrupt_reveal", "p_corrupt_reveal#replace:" .. this.id)

			for i, s in ipairs(replaced.render.sprites) do
				if not s.hidden then
					s.shader_args = replaced_args

					local fr = replaced.render.frames and replaced.render.frames[i]

					if fr then
						fr.shader = rsh
						fr.shader_args = replaced_args
					end
				end
			end
		end
	end

	local mode_key = "holder"

	while true do
		if tpl and this.swap_from and (not this._next_mode_check or store.tick_ts >= this._next_mode_check) then
			this._next_mode_check = store.tick_ts + 0.25

			local holder = find_swap_from(this, store)
			local tw = not holder and find_tower_over(this, store) or nil
			local key = holder and "holder" or tw and "tower:" .. tw.id or "none"

			if holder then
				wire_swap_cut(holder)
			elseif tw then
				local only = tower_terrain_indices(tw)

				if only then
					wire_swap_cut(tw, only)
				else
					unwire_swap_cut()
				end
			else
				unwire_swap_cut()
			end

			if key ~= mode_key then
				mode_key = key

				if holder then
					config_holder()
				elseif not tw or not config_tower(tw) then
					config_none()
				end

				resync()
			end
		end

		if not driver or not store.entities[driver.id] then
			driver = find_driver()
			driver_args = driver and share_driver(driver, sid) or nil
		end

		if driver_args and (driver_args.mask_rect or driver_args.bg_rect) then
			if tpl then
				fire = full_cover_fire(driver_args)

				if cut_target and store.entities[cut_target.id] then
					fire = math.max(fire, full_cover_fire(driver_args, cut_target))
				end
			elseif not this.replace_from then
				fire = visual_fire()
			end
		end

		if replaced_args and driver_args then
			for k, v in pairs(driver_args) do
				if k ~= "invert" then
					replaced_args[k] = v
				end
			end

			replaced_args.invert = 1
		end

		if hide_args and driver_args then
			for k, v in pairs(driver_args) do
				if k ~= "invert" then
					hide_args[k] = v
				end
			end

			hide_args.invert = 1
		end

		if cut_args and driver_args then
			for k, v in pairs(driver_args) do
				if k ~= "invert" then
					cut_args[k] = v
				end
			end

			cut_args.invert = 1
		end

		local th = driver_args and driver_args.threshold or 0

		if fire and fire <= th then
			break
		end

		coroutine.yield()
	end

	local function strip(e)
		if not e or not e.render or not e.render.frames then
			return
		end

		for _, efr in ipairs(e.render.frames) do
			efr.shader = nil
			efr.shader_args = nil
		end
	end

	strip(this)

	if this.replace_from then
		if replaced and store.entities[replaced.id] then
			for _, s in ipairs(replaced.render.sprites) do
				s.hidden = true
			end

			strip(replaced)
			queue_remove(store, replaced)
		elseif not replaced then
			log.warning("nightfall_dissolve: no encontré \"%s\" en (%s,%s)", tostring(this.replace_from), tostring(this.pos.x), tostring(this.pos.y))
		end

		return
	end

	if not tpl then
		if this.hide_from then
			if hide_target and store.entities[hide_target.id] then
				for _, s in ipairs(hide_target.render.sprites) do
					s.hidden = true
				end

				strip(hide_target)
			else
				log.warning("nightfall_dissolve: no encontré \"%s\" en (%s,%s)", tostring(this.hide_from), tostring(this.pos.x), tostring(this.pos.y))
			end
		end

		return
	end

	scripts.nightfall_dissolve.do_swap(this, store)

	if cut_target and store.entities[cut_target.id] and not cut_target.pending_removal then
		unwire_swap_cut()
	end

	if this.swap_to then
		queue_remove(store, this)
	end
end

scripts.decal_stage_18_spawner = {}

function scripts.decal_stage_18_spawner.on_nightfall(this, store)
	this.render.sprites[1].name = "stage23_1_spawner_noche"
end

scripts.stage_18_nightfall = {}

function scripts.stage_18_nightfall.set_day_bg_hidden(this, store, hidden)
	for _, e in pairs(store.entities) do
		if e.template_name == "decal_background" and e.render then
			for _, s in ipairs(e.render.sprites) do
				s.hidden = hidden
			end
		end
	end
end

function scripts.stage_18_nightfall.apply_final(this, store)
	local function insert_now(e)
		for _, sys in ipairs(simulation.systems_on_queue) do
			sys:on_queue(e, store, true)
		end

		simulation:insert_entity(e)
	end

	if this._final_applied then
		return
	end

	this._final_applied = true

	local direct_swaps = not this._swap_spawned

	this._swap_spawned = true
	this.triggered = false
	this.skip_anim = false
	this.render.sprites[1].hidden = false

	if this.render.sprites[1].shader_args then
		this.render.sprites[1].shader_args.threshold = 1
	end

	if this.render.frames then
		for _, f in ipairs(this.render.frames) do
			f.shader = nil
			f.shader_args = nil
		end
	end

	scripts.stage_18_nightfall.set_day_bg_hidden(this, store, true)

	for _, e in pairs(store.entities) do
		if e.template_name == "decal_nightfall_overlay" and not e.swap_to and not e.replace_from and (e.nightfall_name or "decal_stage_18_nightfall") == this.template_name then
			e._final_applied = true

			for _, s in ipairs(e.render.sprites) do
				s.hidden = false
			end

			if e.render.frames then
				for _, f in ipairs(e.render.frames) do
					f.shader = nil
					f.shader_args = nil
				end
			end

			if e.hide_from then
				local day = scripts.nightfall_dissolve.find_replace_from({
					replace_from = e.hide_from,
					pos = e.pos
				}, store)

				if day then
					for _, s in ipairs(day.render.sprites) do
						s.hidden = true
					end
				end
			end
		end
	end

	if direct_swaps then
		for _, pair in ipairs(this.swap_list or {}) do
			for _, t in ipairs(find_all_t(store, pair.from)) do
				scripts.nightfall_dissolve.do_swap({
					swap_from = pair.from,
					swap_to = pair.to,
					pos = t.pos
				}, store, insert_now)
			end
		end
	end
end

function scripts.stage_18_nightfall.update(this, store)
	if this._final_applied then
		return
	end

	local SH = require("klove.shader_db")
	local args = this.render.sprites[1].shader_args
	local refresh_view_args = scripts.nightfall_dissolve.refresh_view_args
	local front_noise = scripts.nightfall_dissolve.front_noise

	coroutine.yield()

	local fr = this.render.frames and this.render.frames[1]
	local bx, by, bw, bh = scripts.nightfall_dissolve.quad_screen_rect(this.pos, this.render.sprites[1])

	if bx then
		args.bg_rect = {
			bx,
			by,
			bw,
			bh
		}
	end

	args.view_off = args.view_off or {
		0,
		0
	}
	args.view_scale = args.view_scale or 1

	local cuts = {}

	local function refresh_cuts()
		for _, c in ipairs(cuts) do
			for k, v in pairs(args) do
				if k ~= "invert" then
					c.args[k] = v
				end
			end

			c.args.invert = 1
		end
	end

	local function refresh_view()
		refresh_view_args(args, store)
		refresh_cuts()
	end

	local function wire_cuts()
		for _, name in ipairs(this.cut_list or {}) do
			local sh = SH:clone("p_dissolve_reveal", "p_dissolve_reveal#invert:" .. name)

			for _, e in ipairs(find_all_t(store, name)) do
				local cargs = {
					invert = 1
				}

				for i, s in ipairs(e.render.sprites) do
					local efr = e.render.frames and e.render.frames[i]

					if efr and not s.hidden then
						s.shader_args = cargs
						efr.shader = sh
						efr.shader_args = cargs
					end
				end

				cuts[#cuts + 1] = {
					id = e.id,
					args = cargs
				}
			end
		end

		refresh_cuts()
	end

	local function strip_cuts()
		for _, c in ipairs(cuts) do
			local e = store.entities[c.id]

			if e and e.render then
				for _, s in ipairs(e.render.sprites) do
					s.hidden = true
				end

				for _, efr in ipairs(e.render.frames or {}) do
					efr.shader = nil
					efr.shader_args = nil
				end
			end
		end

		cuts = {}
	end

	local function resolve_targets()
		local out = {}
		local list = this.notify_list

		if not list or #list == 0 then
			return out
		end

		local br = args.bg_rect

		if not br or not br[3] or br[3] == 0 or not br[4] or br[4] == 0 then
			return out
		end

		local bx, by, bw, bh = br[1], br[2], br[3], br[4]
		local amp = args.noise_amp or 0
		local nscale = args.noise_scale or 6
		local dir = args.dir or {
			0,
			1
		}
		local dl = math.sqrt(dir[1] * dir[1] + dir[2] * dir[2])

		if dl == 0 then
			dl = 1
		end

		local dnx, dny = dir[1] / dl, dir[2] / dl

		for _, item in ipairs(list) do
			local best, bestd

			for _, e in pairs(store.entities) do
				if e.pos and (not item.name or e.template_name == item.name) then
					local d = V.dist(e.pos.x, e.pos.y, item.x, item.y)

					if not bestd or d < bestd then
						best, bestd = e, d
					end
				end
			end

			if best then
				local bluvx = (item.x - bx) / bw
				local bluvy = (REF_H - item.y - by) / bh
				local prog = (bluvx - 0.5) * dnx + (bluvy - 0.5) * dny + 0.5
				local n = front_noise(bluvx * nscale, bluvy * nscale)

				out[#out + 1] = {
					notified = false,
					id = best.id,
					fire = (prog + amp * (1 - n)) / (1 + amp)
				}

				if not best.on_nightfall then
					log.warning("stage_18_nightfall: \"%s\" en (%s,%s) no tiene on_nightfall", tostring(item.name), tostring(item.x), tostring(item.y))
				end
			else
				log.warning("stage_18_nightfall: no encontré \"%s\" cerca de (%s,%s)", tostring(item.name), tostring(item.x), tostring(item.y))
			end
		end

		table.sort(out, function(a, b)
			return a.fire < b.fire
		end)

		return out
	end

	refresh_view()

	local front_fx_total = 0

	for _, it in ipairs(this.front_fx or {}) do
		front_fx_total = front_fx_total + (it.weight or 1)
	end

	local function pick_front_fx()
		local r = math.random() * front_fx_total

		for _, it in ipairs(this.front_fx) do
			r = r - (it.weight or 1)

			if r <= 0 then
				return it.fx
			end
		end

		return this.front_fx[#this.front_fx].fx
	end

	local function emit_front_fx(threshold, count)
		local br = args.bg_rect

		if not br or front_fx_total <= 0 then
			return
		end

		local amp = args.noise_amp or 0
		local nscale = args.noise_scale or 6
		local band = this.front_fx_band or 0
		local lead = this.front_fx_lead or 0
		local smin = this.front_fx_scale_min or 1
		local smax = this.front_fx_scale_max or 1
		local dir = args.dir or {
			0,
			1
		}
		local dl = math.sqrt(dir[1] * dir[1] + dir[2] * dir[2])

		if dl == 0 then
			dl = 1
		end

		local dnx, dny = dir[1] / dl, dir[2] / dl

		for _ = 1, count do
			local s = math.random() - 0.5
			local p = threshold
			local luvx, luvy

			for _ = 1, 2 do
				luvx = 0.5 - dny * s + dnx * (p - 0.5)
				luvy = 0.5 + dnx * s + dny * (p - 0.5)

				local n = front_noise(luvx * nscale, luvy * nscale)

				p = threshold * (1 + amp) - amp * (1 - n)
			end

			p = p + lead + (math.random() * 2 - 1) * band
			luvx = 0.5 - dny * s + dnx * (p - 0.5)
			luvy = 0.5 + dnx * s + dny * (p - 0.5)

			if luvx >= 0 and luvx <= 1 and luvy >= 0 and luvy <= 1 then
				local fx = E:create_entity(pick_front_fx())

				fx.pos.x = br[1] + luvx * br[3]
				fx.pos.y = REF_H - (br[2] + luvy * br[4])

				local fs = fx.render.sprites[1]

				fs.flip_x = this.front_fx_flip and math.random() < 0.5
				fs.scale = V.vv(U.frandom(smin, smax))
				fs.ts = store.tick_ts

				queue_insert(store, fx)
			end
		end
	end

	if this.swap_list and not this._swap_spawned then
		this._swap_spawned = true

		for _, pair in ipairs(this.swap_list) do
			for _, t in ipairs(find_all_t(store, pair.from)) do
				local o = E:create_entity("decal_nightfall_overlay")

				o.pos = V.vclone(t.pos)
				o.swap_from = pair.from
				o.swap_to = pair.to
				o.nightfall_name = this.template_name

				queue_insert(store, o)
			end
		end
	end

	while true do
		args.threshold = 0

		while not this.triggered do
			refresh_view()
			coroutine.yield()
		end

		this.triggered = false

		if fr then
			fr.shader = SH:get("p_dissolve_reveal")
			fr.shader_args = args
		end

		this.render.sprites[1].hidden = false

		scripts.stage_18_nightfall.set_day_bg_hidden(this, store, false)
		wire_cuts()

		local targets = resolve_targets()

		local function notify(phase)
			for _, t in ipairs(targets) do
				if phase < t.fire then
					break
				end

				if not t.notified then
					t.notified = true

					local e = store.entities[t.id]

					if e and e.on_nightfall then
						e.on_nightfall(e, store)
					end
				end
			end
		end

		if this.skip_anim then
			this.skip_anim = false
			args.threshold = 1

			refresh_view()
			notify(1)
		else
			local ffx_rate = this.front_fx_rate or 0

			this._ffx_accum = 0
			this._ffx_last_dt = 0

			U.y_ease_key(store, args, "threshold", 0, 1, this.reveal_time, this.reveal_ease, function(dt, phase)
				refresh_view()
				notify(phase)

				if ffx_rate > 0 then
					local delta = dt - this._ffx_last_dt

					this._ffx_last_dt = dt
					this._ffx_accum = this._ffx_accum + ffx_rate * delta

					local n = math.floor(this._ffx_accum)

					if n > 0 then
						this._ffx_accum = this._ffx_accum - n

						emit_front_fx(args.threshold, n)
					end
				end
			end)

			args.threshold = 1

			refresh_view()
			notify(1)
		end

		if fr then
			fr.shader = nil
			fr.shader_args = nil
		end

		strip_cuts()
		scripts.stage_18_nightfall.set_day_bg_hidden(this, store, true)

		while not this.triggered do
			refresh_view()
			coroutine.yield()
		end
	end
end

scripts.stage_16_bg_corrupt = {}

function scripts.stage_16_bg_corrupt.fire_corromper(store, tree_name)
	local handlers = store.event_handlers and store.event_handlers.corromper_tree

	if not handlers then
		log.error("stage_16_bg_corrupt: sin handlers para corromper_tree")

		return
	end

	for _, ev in pairs(handlers) do
		ev.on_event(store.entities[ev.entity_id], store, ev.name, tree_name)
	end
end

function scripts.stage_16_bg_corrupt.apply_final(this, store)
	local function insert_now(e)
		for _, sys in ipairs(simulation.systems_on_queue) do
			sys:on_queue(e, store, true)
		end

		simulation:insert_entity(e)
	end

	if this._final_applied then
		return
	end

	if not store.entities[this.id] then
		insert_now(this)
	end

	this._final_applied = true
	this._start_final = true
	this._overlays_spawned = true

	for _, s in ipairs(this.render.sprites) do
		s.hidden = false

		if s.shader_args then
			s.shader_args.threshold = 1
		end

		s.shader = nil
	end

	if this.render.frames then
		for _, f in ipairs(this.render.frames) do
			f.shader = nil
			f.shader_args = nil
		end
	end

	for _, item in ipairs(this.corromper_list or {}) do
		scripts.stage_16_bg_corrupt.fire_corromper(store, item.tree)
	end

	for _, item in ipairs(this.overlay_list or {}) do
		if item.replace_from then
			local old = scripts.nightfall_dissolve.find_replace_from({
				replace_from = item.replace_from,
				pos = {
					x = item.x,
					y = item.y
				}
			}, store)

			if old then
				for _, s in ipairs(old.render.sprites) do
					s.hidden = true
				end

				queue_remove(store, old)
			end

			local o = E:create_entity("decal_stage_16_corrupt_overlay")

			o.transition_id = this.id
			o.transition_sid = item.transition_sid
			o.pos.x, o.pos.y = item.x, item.y

			if item.name then
				local s = o.render.sprites[1]

				s.name = item.name
				s.z = item.z
				s.sort_y_offset = item.sort_y_offset or 0
			end

			local sid = item.transition_sid or 1
			local na = this.render.sprites[sid] and this.render.sprites[sid].shader_args

			for _, s in ipairs(o.render.sprites) do
				if na and s.shader then
					s.shader_args = na
				end

				s.shader = nil
			end

			insert_now(o)
		elseif item.swap_from and item.swap_to then
			scripts.nightfall_dissolve.do_swap({
				swap_from = item.swap_from,
				swap_to = item.swap_to,
				holder_id = item.holder_id,
				pos = {
					x = item.x,
					y = item.y
				}
			}, store, insert_now)
		end
	end
end

function scripts.stage_16_bg_corrupt.update(this, store)
	local SH = require("klove.shader_db")
	local qrect = scripts.nightfall_dissolve.quad_screen_rect
	local refresh_view_args = scripts.nightfall_dissolve.refresh_view_args
	local front_noise = scripts.nightfall_dissolve.front_noise

	coroutine.yield()

	local function refresh_view()
		for _, s in ipairs(this.render.sprites) do
			if s.shader_args then
				refresh_view_args(s.shader_args, store)
			end
		end

		if this._grass_shader_args then
			refresh_view_args(this._grass_shader_args, store)
		end
	end

	local function resolve_targets()
		local out = {}

		for _, item in ipairs(this.corromper_list or {}) do
			local fire

			for _, s in ipairs(this.render.sprites) do
				local a = s.shader_args
				local br = a and a.mask_rect

				if br and br[3] and br[3] ~= 0 and br[4] and br[4] ~= 0 then
					local bluvx = (item.x - br[1]) / br[3]
					local bluvy = (REF_H - item.y - br[2]) / br[4]

					if bluvx >= 0 and bluvx <= 1 and bluvy >= 0 and bluvy <= 1 then
						local amp = a.noise_amp or 0
						local nscale = a.noise_scale or 6
						local dx = (bluvx - a.origin[1]) * a.dist_scale[1]
						local dy = (bluvy - a.origin[2]) * a.dist_scale[2]
						local prog = math.sqrt(dx * dx + dy * dy)
						local n = front_noise(bluvx * nscale, bluvy * nscale)

						fire = (prog + amp * (1 - n)) / (1 + amp)

						break
					end
				end
			end

			if not fire then
				log.warning("stage_16_bg_corrupt: (%s,%s) fuera de las máscaras, \"%s\" se corrompe al arrancar el barrido", tostring(item.x), tostring(item.y), tostring(item.tree))

				fire = 0
			end

			out[#out + 1] = {
				fired = false,
				tree = item.tree,
				fire = fire
			}
		end

		table.sort(out, function(a, b)
			return a.fire < b.fire
		end)

		return out
	end

	local function fire_crossed(targets, phase)
		for _, t in ipairs(targets) do
			if phase < t.fire then
				break
			end

			if not t.fired then
				t.fired = true

				scripts.stage_16_bg_corrupt.fire_corromper(store, t.tree)
			end
		end
	end

	local function front_point(em, p, phi)
		if not p or p <= 0 then
			return nil
		end

		local c, s = math.cos(phi), math.sin(phi)
		local luvx = em.ox + em.sx * p * c / em.dsx
		local luvy = em.oy + em.sy * p * s / em.dsy

		if luvx < 0 or luvx > 1 or luvy < 0 or luvy > 1 then
			return nil
		end

		local wx = em.qx + luvx * em.qw
		local wy = REF_H - (em.qy + luvy * em.qh)
		local mdx = em.qw * (em.sx * c / em.dsx)
		local mdy = -em.qh * (em.sy * s / em.dsy)
		local move_a = math.atan2(mdy, mdx)

		return wx, wy, move_a, move_a + math.pi * 0.5
	end

	local function front_prog_wobble(em, threshold, phi)
		local amp = em.amp or 0
		local nscale = em.nscale or 6
		local c, s = math.cos(phi), math.sin(phi)
		local p = threshold

		for _ = 1, 2 do
			local luvx = em.ox + em.sx * p * c / em.dsx
			local luvy = em.oy + em.sy * p * s / em.dsy
			local n = front_noise(luvx * nscale, luvy * nscale)

			p = threshold * (1 + amp) - amp * (1 - n)
		end

		return p
	end

	local grass_life = 0.7333333333333333

	do
		local pt = this.grass_ps and E:get_template(this.grass_ps)
		local pl = pt and pt.particle_system and pt.particle_system.particle_lifetime

		if pl and pl[2] then
			grass_life = pl[2]
		end
	end

	local emit_stop_dt = math.max(0, (this.reveal_time or 0) - grass_life)

	local function stop_all_grass_emitters()
		for _, em in ipairs(this._grass_ps or {}) do
			local ps = store.entities[em.id] or em.e

			if ps and ps.particle_system then
				ps.particle_system.emit = false
			end

			em.last_x, em.last_y = nil
		end
	end

	local function update_grass_emitters(threshold, dt)
		if dt == nil or dt >= emit_stop_dt or not threshold or threshold <= 0 then
			stop_all_grass_emitters()

			return
		end

		for _, em in ipairs(this._grass_ps or {}) do
			local ps = store.entities[em.id] or em.e

			if ps and ps.particle_system then
				local p = front_prog_wobble(em, threshold, em.phi)
				local wx, wy, _, perp_a = front_point(em, p, em.phi)

				if wx then
					em.last_x, em.last_y = wx, wy
					ps.pos.x, ps.pos.y = wx, wy
					ps.particle_system.emit_direction = perp_a
				elseif em.last_x then
					ps.pos.x, ps.pos.y = em.last_x, em.last_y
				end

				ps.particle_system.emit = em.last_x ~= nil
			end
		end
	end

	local function mask_uv_rect(sd)
		if not sd or not sd.f_quad or not sd.a_size then
			return {
				0,
				0,
				0,
				0
			}
		end

		local aw, ah = sd.a_size[1], sd.a_size[2]

		if aw <= 0 or ah <= 0 then
			return {
				0,
				0,
				0,
				0
			}
		end

		local fq = sd.f_quad

		return {
			fq[1] / aw,
			fq[2] / ah,
			fq[3] / aw,
			fq[4] / ah
		}
	end

	local function spawn_grass_emitters()
		local tpl = this.grass_ps

		if not tpl then
			return
		end

		local n_cfg = this.grass_emitters_per_mask or 4
		local smin = this.grass_scale_min or 1
		local smax = this.grass_scale_max or 1.35
		local rot_spread = math.pi * 0.5
		local area_frac = this.grass_emit_area_frac or 0.25

		this._grass_ps = {}

		local function n_per_for(sid)
			if type(n_cfg) == "table" then
				return n_cfg[sid] or n_cfg[1] or 4
			end

			return n_cfg
		end

		local total_emitters = 0

		for sid = 1, #this.render.sprites do
			total_emitters = total_emitters + n_per_for(sid)
		end

		local rate = (this.grass_rate or 0) / math.max(1, total_emitters)
		local area_x, area_y = 0, 0

		do
			local A = require("klove.animation_db")
			local pt = E:get_template(tpl)
			local pname = pt and pt.particle_system and pt.particle_system.name
			local fn = pname and A:fn(pname, 0, false)
			local psd = fn and I:s(fn)

			if psd and psd.size then
				area_x = psd.size[1] * area_frac
				area_y = psd.size[2] * area_frac
			end
		end

		local s1 = this.render.sprites[1]
		local sd1 = s1 and I:s(s1.name)
		local mask_im = sd1 and sd1.atlas and I:i(sd1.atlas)
		local grass_args

		if mask_im then
			local bx, by, bw, bh = qrect(this.pos, s1)

			grass_args = {
				view_scale = 1,
				mask = mask_im,
				mask_uv_rect = mask_uv_rect(sd1),
				mask_rect = bx and {
					bx,
					by,
					bw,
					bh
				} or {
					0,
					0,
					0,
					0
				},
				mask_uv_rect_2 = {
					0,
					0,
					0,
					0
				},
				mask_rect_2 = {
					0,
					0,
					0,
					0
				},
				view_off = {
					0,
					0
				}
			}

			local s2 = this.render.sprites[2]
			local sd2 = s2 and I:s(s2.name)

			if sd2 and sd2.atlas == sd1.atlas then
				local bx2, by2, bw2, bh2 = qrect(this.pos, s2)

				if bx2 then
					grass_args.mask_uv_rect_2 = mask_uv_rect(sd2)
					grass_args.mask_rect_2 = {
						bx2,
						by2,
						bw2,
						bh2
					}
				end
			end

			refresh_view_args(grass_args, store)

			this._grass_shader_args = grass_args
		end

		local grass_sh = grass_args and SH:get("p_ps_alpha_mask")
		local flip_i = 0

		for sid, s in ipairs(this.render.sprites) do
			local args = s.shader_args
			local br = args and args.mask_rect

			if br and br[3] and br[3] > 0 and br[4] and br[4] > 0 then
				local qx, qy, qw, qh = br[1], br[2], br[3], br[4]
				local ox, oy = args.origin[1], args.origin[2]
				local n_per = n_per_for(sid)
				local dphi = math.pi * 0.5 / n_per

				for k = 1, n_per do
					local phi = (k - 0.5) * dphi
					local ps = E:create_entity(tpl)

					flip_i = flip_i + 1

					local sign = flip_i % 2 == 0 and -1 or 1

					ps.particle_system.emit = false
					ps.particle_system.emission_rate = rate
					ps.particle_system.emit_area_spread = V.v(area_x, area_y)
					ps.particle_system.emit_direction = 0
					ps.particle_system.emit_rotation_spread = rot_spread
					ps.particle_system.scale_var = {
						smin,
						smax
					}
					ps.particle_system.scales_x = {
						sign
					}
					ps.particle_system.scales_y = {
						1
					}

					if grass_sh then
						ps.particle_system.shader = grass_sh
						ps.particle_system.shader_args = grass_args
					end

					queue_insert(store, ps)

					this._grass_ps[#this._grass_ps + 1] = {
						e = ps,
						id = ps.id,
						phi = phi,
						amp = args.noise_amp or 0,
						nscale = args.noise_scale or 6,
						ox = ox,
						oy = oy,
						sx = ox == 0 and 1 or -1,
						sy = oy == 0 and 1 or -1,
						dsx = args.dist_scale[1],
						dsy = args.dist_scale[2],
						qx = qx,
						qy = qy,
						qw = qw,
						qh = qh
					}
				end
			end
		end
	end

	local function spawn_overlays()
		if this._overlays_spawned then
			return
		end

		this._overlays_spawned = true

		for _, item in ipairs(this.overlay_list or {}) do
			local o = E:create_entity("decal_stage_16_corrupt_overlay")

			o.transition_id = this.id
			o.transition_sid = item.transition_sid
			o.pos.x, o.pos.y = item.x, item.y
			o.holder_id = item.holder_id
			o.replace_from = item.replace_from
			o.swap_from = item.swap_from
			o.swap_to = item.swap_to

			if item.name then
				local s = o.render.sprites[1]

				s.name = item.name
				s.z = item.z
				s.sort_y_offset = item.sort_y_offset or 0
			end

			queue_insert(store, o)
		end
	end

	local function set_thresholds(value)
		for _, s in ipairs(this.render.sprites) do
			if s.shader_args then
				s.shader_args.threshold = value
			end
		end
	end

	if this._start_final then
		set_thresholds(1)

		for _, s in ipairs(this.render.sprites) do
			s.hidden = false
		end

		return
	end

	local lead_args = this.render.sprites[1].shader_args

	for i, s in ipairs(this.render.sprites) do
		local args = s.shader_args
		local sd = I:s(s.name)
		local bx, by, bw, bh = qrect(this.pos, s)

		if bx then
			args.mask_rect = {
				bx,
				by,
				bw,
				bh
			}
		end

		if sd and sd.size and sd.trim then
			local w = sd.size[1] - sd.trim[1] - sd.trim[3]
			local h = sd.size[2] - sd.trim[2] - sd.trim[4]
			local d = math.sqrt(w * w + h * h)

			args.dist_scale = {
				w / d,
				h / d
			}
		end

		refresh_view_args(args, store)

		local fr = this.render.frames and this.render.frames[i]

		if fr then
			fr.shader = SH:clone("p_corrupt_reveal", "p_corrupt_reveal#" .. this.id .. ":" .. i)
			fr.shader_args = args
		end
	end

	local function strip_shaders()
		for i = 1, #this.render.sprites do
			local fr = this.render.frames and this.render.frames[i]

			if fr then
				fr.shader = nil
				fr.shader_args = nil
			end
		end
	end

	spawn_overlays()

	while true do
		for i = 1, #this.render.sprites do
			local fr = this.render.frames and this.render.frames[i]
			local args = this.render.sprites[i].shader_args

			if fr and args and not fr.shader then
				fr.shader = SH:clone("p_corrupt_reveal", "p_corrupt_reveal#" .. this.id .. ":" .. i)
				fr.shader_args = args
			end
		end

		set_thresholds(0)

		for _, s in ipairs(this.render.sprites) do
			s.hidden = false
		end

		stop_all_grass_emitters()

		while not this.triggered do
			refresh_view()
			coroutine.yield()
		end

		this.triggered = false

		local targets = resolve_targets()

		if this.skip_anim then
			this.skip_anim = false

			set_thresholds(1)
			refresh_view()
			fire_crossed(targets, 1)
			stop_all_grass_emitters()
		else
			for _, fog_t in ipairs(this.fog_fx or {}) do
				queue_insert(store, E:create_entity(fog_t))
			end

			U.y_ease_key(store, lead_args, "threshold", 0, 1, this.reveal_time, this.reveal_ease, function(dt, phase)
				local th = lead_args.threshold

				for i = 2, #this.render.sprites do
					local a = this.render.sprites[i].shader_args

					if a then
						a.threshold = th
					end
				end

				refresh_view()
				fire_crossed(targets, th)
				update_grass_emitters(th, dt)
			end)
			set_thresholds(1)
			refresh_view()
			fire_crossed(targets, 1)
			stop_all_grass_emitters()
		end

		strip_shaders()

		while not this.triggered do
			refresh_view()
			coroutine.yield()
		end
	end
end

scripts.decal_stage_18_portal = {}

local function y_portal_apply_want(this, store)
	if this._want and this._want ~= this._state then
		this._state = this._want

		local sound = not this._mute_sfx and (this._state == "open" and this.sound_open or this.sound_close)

		this._mute_sfx = nil

		if sound then
			S:queue(sound)
		end

		if this._state == "open" then
			U.y_animation_play(this, "on_in", nil, store.tick_ts, 1, 1)
			U.animation_start(this, "on_loop", nil, store.tick_ts, true, 1, true)
		else
			U.y_animation_play(this, "off_in", nil, store.tick_ts, 1, 1)
			U.animation_start(this, "off_idle", nil, store.tick_ts, true, 1, true)
		end
	end
end

function scripts.decal_stage_18_portal.on_event(this, store, event_name, portal, action)
	if tonumber(portal) ~= this.portal_idx then
		return
	end

	if action ~= "open" and action ~= "close" then
		log.error("stage_18_portal: action invalida %s (portal %s)", action, portal)

		return
	end

	this._want = action
end

function scripts.decal_stage_18_portal.fire(store, portal, action)
	local handlers = store.event_handlers and store.event_handlers.stage_18_portal

	if not handlers then
		return
	end

	for _, ev in pairs(handlers) do
		ev.on_event(store.entities[ev.entity_id], store, ev.name, portal, action)
	end
end

function scripts.decal_stage_18_portal.update(this, store)
	this._state = "close"

	while true do
		y_portal_apply_want(this, store)
		coroutine.yield()
	end
end

function scripts.decal_stage_18_portal.update_auto(this, store)
	this._state = "close"

	local tunnels = {}
	local empty_ts

	while true do
		if #tunnels == 0 then
			for _, e in pairs(store.entities) do
				if e.tunnel then
					for _, pi in ipairs(this.tunnel_place_pis) do
						if e.tunnel.place_pi == pi then
							tunnels[#tunnels + 1] = e

							break
						end
					end
				end
			end
		end

		local occupied = false

		for _, tu in ipairs(tunnels) do
			if tu.tunnel.picked_enemies and #tu.tunnel.picked_enemies > 0 then
				occupied = true

				break
			end
		end

		if this._force_open then
			empty_ts = nil
			this._want = "open"
		elseif occupied then
			empty_ts = nil
			this._want = "open"
		else
			empty_ts = empty_ts or store.tick_ts

			if store.tick_ts - empty_ts >= this.close_delay then
				this._want = "close"
			end
		end

		y_portal_apply_want(this, store)
		coroutine.yield()
	end
end

scripts.decal_stage_18_puerta = {}

function scripts.decal_stage_18_puerta.on_event(this, store, event_name, action)
	if action ~= "open" and action ~= "close" then
		log.error("stage_18_puerta: action invalida %s", action)

		return
	end

	this._want = action
end

function scripts.decal_stage_18_puerta.fire(store, action)
	local handlers = store.event_handlers and store.event_handlers.stage_18_puerta

	if not handlers then
		return
	end

	for _, ev in pairs(handlers) do
		ev.on_event(store.entities[ev.entity_id], store, ev.name, action)
	end
end

function scripts.decal_stage_18_puerta.on_nightfall(this, store)
	this.render.sprites[1].prefix = "animations_puerta_st_18_terreno_2Def"

	local anim = this._state == "open" and "open_idle" or "closed_idle"

	U.animation_start(this, anim, nil, store.tick_ts, true, 1, true)
end

function scripts.decal_stage_18_puerta.update(this, store)
	this._state = "close"

	while true do
		if this._want and this._want ~= this._state then
			this._state = this._want

			if this._state == "open" then
				if this.sound_open then
					S:queue(this.sound_open, {
						delay = fts(this.sound_open_frame)
					})
				end

				U.y_animation_play(this, "open_in", nil, store.tick_ts, 1, 1)
				U.animation_start(this, "open_idle", nil, store.tick_ts, true, 1, true)
			else
				if this.sound_close then
					S:queue(this.sound_close, {
						delay = fts(this.sound_close_frame)
					})
				end

				U.y_animation_play(this, "open_out", nil, store.tick_ts, 1, 1)
				U.animation_start(this, "closed_idle", nil, store.tick_ts, true, 1, true)
			end
		end

		coroutine.yield()
	end
end

scripts.bullet_stage_18_veznan_bolt = {}

function scripts.bullet_stage_18_veznan_bolt.insert(this, store, script)
	local b = this.bullet

	if b.target_id then
		local target = store.entities[b.target_id]

		if not target or band(target.vis.bans, F_RANGED) ~= 0 then
			if this.keep_on_target_loss then
				b.target_id = nil
			else
				return false
			end
		end
	end

	b.speed.x, b.speed.y = V.normalize(b.to.x - b.from.x, b.to.y - b.from.y)

	local s = this.render.sprites[1]

	if not b.ignore_rotation then
		s.r = V.angleTo(b.to.x - this.pos.x, b.to.y - this.pos.y)
	end

	return true
end

function scripts.bullet_stage_18_veznan_bolt.update(this, store)
	local b = this.bullet
	local fm = this.force_motion
	local target = store.entities[b.target_id]
	local ps

	local function move_step(dest)
		local dx, dy = V.sub(dest.x, dest.y, this.pos.x, this.pos.y)
		local dist = V.len(dx, dy)

		if this.straight_flight then
			fm.v.x, fm.v.y = V.mul(fm.max_v, V.normalize(dx, dy))
			this.pos.x, this.pos.y = V.add(this.pos.x, this.pos.y, V.mul(store.tick_length, fm.v.x, fm.v.y))

			return dist <= fm.max_v * store.tick_length
		end

		local nx, ny = V.mul(fm.max_v, V.normalize(dx, dy))
		local stx, sty = V.sub(nx, ny, fm.v.x, fm.v.y)

		if dist <= 4 * fm.max_v * store.tick_length then
			stx, sty = V.mul(fm.max_a, V.normalize(stx, sty))
		end

		fm.a.x, fm.a.y = V.add(fm.a.x, fm.a.y, V.trim(fm.max_a, V.mul(fm.a_step, stx, sty)))
		fm.v.x, fm.v.y = V.trim(fm.max_v, V.add(fm.v.x, fm.v.y, V.mul(store.tick_length, fm.a.x, fm.a.y)))
		this.pos.x, this.pos.y = V.add(this.pos.x, this.pos.y, V.mul(store.tick_length, fm.v.x, fm.v.y))
		fm.a.x, fm.a.y = 0, 0

		return dist <= fm.max_v * store.tick_length
	end

	if b.particles_name then
		ps = E:create_entity(b.particles_name)
		ps.particle_system.emit = true
		ps.particle_system.track_id = this.id

		queue_insert(store, ps)
	end

	local iix, iiy = V.normalize(b.to.x - this.pos.x, b.to.y - this.pos.y)
	local last_pos = V.vclone(this.pos)
	local target_is_flying = false

	b.ts = store.tick_ts

	while true do
		target = store.entities[b.target_id]

		if target and target.health and not target.health.dead and band(target.vis.bans, F_RANGED) == 0 then
			local hit_offset = V.v(0, 0)

			target_is_flying = band(target.vis.flags, F_FLYING) ~= 0

			if not b.ignore_hit_offset or target_is_flying then
				hit_offset.x = target.unit.hit_offset.x
				hit_offset.y = target.unit.hit_offset.y
			end

			local d = math.max(math.abs(target.pos.x + hit_offset.x - b.to.x), math.abs(target.pos.y + hit_offset.y - b.to.y))

			if d > b.max_track_distance then
				target = nil
				b.target_id = nil
			else
				b.to.x, b.to.y = target.pos.x + hit_offset.x, target.pos.y + hit_offset.y
			end
		end

		if this.initial_impulse and store.tick_ts - b.ts < this.initial_impulse_duration then
			local t = store.tick_ts - b.ts
			local angle = this.initial_impulse_angle

			if this.initial_impulse_side then
				angle = angle * this.initial_impulse_side
			elseif iix < 0 then
				angle = angle * -1
			end

			fm.a.x, fm.a.y = V.mul((1 - t) * this.initial_impulse, V.rotate(angle, iix, iiy))
			fm.v.x, fm.v.y = V.trim(fm.max_v, V.add(fm.v.x, fm.v.y, V.mul(store.tick_length, fm.a.x, fm.a.y)))
			this.pos.x, this.pos.y = V.add(this.pos.x, this.pos.y, V.mul(store.tick_length, fm.v.x, fm.v.y))
		else
			last_pos.x, last_pos.y = this.pos.x, this.pos.y

			if move_step(b.to) then
				break
			end
		end

		if b.align_with_trajectory then
			this.render.sprites[1].r = V.angleTo(this.pos.x - last_pos.x, this.pos.y - last_pos.y)
		end

		coroutine.yield()
	end

	if target and not target.health.dead then
		local d = SU.create_bullet_damage(b, target.id, this.id)

		queue_damage(store, d)
	end

	this.render.sprites[1].hidden = true

	local hit_fx = target_is_flying and b.hit_fx_air or b.hit_fx

	if hit_fx then
		local fx = E:create_entity(hit_fx)

		fx.pos.x, fx.pos.y = b.to.x, b.to.y
		fx.render.sprites[1].ts = store.tick_ts
		fx.render.sprites[1].runs = 0

		queue_insert(store, fx)
	end

	if this.hit_sfx then
		S:queue(this.hit_sfx)
	end

	if ps and ps.particle_system.emit then
		ps.particle_system.emit = false

		U.y_wait(store, ps.particle_system.particle_lifetime[2])
	end

	queue_remove(store, this)
end

scripts.bullet_stage_18_veznan_soul = {}

function scripts.bullet_stage_18_veznan_soul.insert(this, store, script)
	local b = this.bullet

	b.speed.x, b.speed.y = V.normalize(b.to.x - b.from.x, b.to.y - b.from.y)

	U.animation_start(this, "in", nil, store.tick_ts, false)

	return true
end

function scripts.bullet_stage_18_veznan_soul.update(this, store, script)
	local b = this.bullet
	local ts = store.tick_ts

	while store.tick_ts - ts < (this.soul_in_time or 0) do
		b.speed.x, b.speed.y = V.mul(b.min_speed, V.normalize(b.to.x - this.pos.x, b.to.y - this.pos.y))
		this.pos.x, this.pos.y = this.pos.x + b.speed.x * store.tick_length, this.pos.y + b.speed.y * store.tick_length

		if b.align_with_trajectory then
			this.render.sprites[1].r = V.angleTo(b.to.x - this.pos.x, b.to.y - this.pos.y)
		end

		coroutine.yield()
	end

	U.animation_start(this, "flying", nil, store.tick_ts, true)
	scripts.bolt_enemy.update(this, store, script)

	if this.arrive_fx then
		local fx = E:create_entity(this.arrive_fx)

		fx.pos = V.vclone(this.pos)
		fx.render.sprites[1].ts = store.tick_ts

		queue_insert(store, fx)
	end

	if this.arrive_pump_fx then
		local src = store.entities[this.bullet.source_id]
		local pfx = E:create_entity(this.arrive_pump_fx)

		pfx.pos = V.vclone(src and src.pos or this.pos)
		pfx.render.sprites[1].ts = store.tick_ts

		queue_insert(store, pfx)
	end
end

scripts.bullet_stage_18_veznan_soul_reveal = {}

function scripts.bullet_stage_18_veznan_soul_reveal.update(this, store, script)
	local b = this.bullet
	local flight_time = V.dist(b.from.x, b.from.y, b.to.x, b.to.y) / b.min_speed
	local mx, my = (b.from.x + b.to.x) / 2, (b.from.y + b.to.y) / 2
	local nx, ny = V.normalize(b.from.y - b.to.y, b.to.x - b.from.x)
	local curve = U.frandom(this.curve_offset[1], this.curve_offset[2]) * (math.random(2) == 1 and 1 or -1)
	local cx, cy = mx + nx * curve, my + ny * curve
	local ts = store.tick_ts
	local flying, ps

	while true do
		local elapsed = store.tick_ts - ts
		local s = math.min(1, elapsed / flight_time)
		local oms = 1 - s

		this.pos.x = oms * oms * b.from.x + 2 * s * oms * cx + s * s * b.to.x
		this.pos.y = oms * oms * b.from.y + 2 * s * oms * cy + s * s * b.to.y

		if b.align_with_trajectory then
			this.render.sprites[1].r = V.angleTo(2 * oms * (cx - b.from.x) + 2 * s * (b.to.x - cx), 2 * oms * (cy - b.from.y) + 2 * s * (b.to.y - cy))
		end

		if ps then
			ps.particle_system.emit_direction = this.render.sprites[1].r
		end

		if not flying and elapsed >= (this.soul_in_time or 0) then
			flying = true

			U.animation_start(this, "flying", nil, store.tick_ts, true)

			if b.particles_name then
				ps = E:create_entity(b.particles_name)
				ps.particle_system.track_id = this.id

				queue_insert(store, ps)
			end
		end

		if s >= 1 then
			break
		end

		coroutine.yield()
	end

	local src = store.entities[this.bullet.source_id]

	if this.arrive_fx then
		local fx = E:create_entity(this.arrive_fx)

		fx.pos = V.vclone(this.pos)
		fx.render.sprites[1].ts = store.tick_ts

		queue_insert(store, fx)
	end

	if this.arrive_pump_fx then
		local pfx = E:create_entity(this.arrive_pump_fx)

		pfx.pos = V.vclone(src and src.pos or this.pos)
		pfx.render.sprites[1].ts = store.tick_ts

		queue_insert(store, pfx)
	end

	if src and this.reveal_heal and this.reveal_heal > 0 then
		src.health.hp = km.clamp(0, src.health.hp_max, src.health.hp + this.reveal_heal)
	end

	queue_remove(store, this)
end

scripts.controller_stage_18_veznan = {}

function scripts.controller_stage_18_veznan.on_disable_towers(this, store, event_name, count, holder_group, duration)
	this._queue = this._queue or {}

	table.insert(this._queue, {
		skill = "disable_towers",
		count = tonumber(count) or this.disable_default_count,
		holder_group = holder_group ~= nil and holder_group ~= "" and tostring(holder_group) or this.disable_default_group,
		duration = tonumber(duration)
	})
end

function scripts.controller_stage_18_veznan.on_summon_demons(this, store, event_name, path, group)
	this._queue = this._queue or {}

	local g = tonumber(group) or this.summon_default_group

	if not this.summon_groups[g] then
		g = this.summon_default_group
	end

	table.insert(this._queue, {
		skill = "summon_demons",
		path = tonumber(path) or this.summon_default_path,
		group = g
	})
end

function scripts.controller_stage_18_veznan.on_bolts_off(this, store, event_name)
	this._bolts_off = true

	if this._queue then
		for i = #this._queue, 1, -1 do
			if this._queue[i].skill == "gem_blast" then
				table.remove(this._queue, i)
			end
		end
	end
end

scripts.fx_stage_18_explosion_estatua = {}

function scripts.fx_stage_18_explosion_estatua.update(this, store, script)
	if this.screenshake_amplitude then
		local shake = E:create_entity("aura_screen_shake")

		shake.aura.amplitude = this.screenshake_amplitude
		shake.aura.duration = this.screenshake_duration
		shake.aura.freq_factor = this.screenshake_freq_factor

		queue_insert(store, shake)
	end

	U.y_wait(store, this.mask_off_time)

	for _, e in pairs(store.entities) do
		if e.template_name == "decal_stage_18_statue_mask" or e.template_name == "decal_stage_18_statue_mask_noche" or e.template_name == "decal_nightfall_overlay" and e.swap_from == "decal_stage_18_statue_mask" then
			queue_remove(store, e)
		end
	end
end

scripts.fx_stage_18_campana = {}

function scripts.fx_stage_18_campana.update(this, store)
	S:queue(this.sound_bell_in)

	local cam_end_x = 750
	local cam_step = (cam_end_x - this.ray_cam_start.x) / #this.ray_positions
	local prev = 0

	for i, f in ipairs(this.sound_bell_frames) do
		local pos = this.ray_positions[i]

		U.y_wait(store, fts(f - prev))

		prev = f

		S:queue(this.sound_bell)

		if pos then
			U.y_wait(store, fts(this.ray_delay_frames))

			prev = f + this.ray_delay_frames

			local ray = E:create_entity(this.ray_fx_t)

			ray.pos = V.v(pos.x, pos.y)
			ray.render.sprites[1].flip_x = math.random() < 0.5
			ray.render.sprites[1].ts = store.tick_ts

			if REF_H - pos.y > ray.image_h then
				ray.render.sprites[1].scale = V.v(1, (REF_H - pos.y) / ray.image_h)
			end

			queue_insert(store, ray)

			local exp = E:create_entity(this.ray_explosion_fx)

			exp.pos = V.v(pos.x, pos.y)
			exp.render.sprites[1].ts = store.tick_ts

			queue_insert(store, exp)
			S:queue(this.sound_ray)

			local grieta = E:create_entity(this.grieta_fx_t)

			grieta.pos = V.v(pos.x, pos.y)
			grieta.render.sprites[1].ts = store.tick_ts

			queue_insert(store, grieta)

			local shake = E:create_entity("aura_screen_shake")

			shake.aura.amplitude = this.ray_shake.amplitude
			shake.aura.duration = this.ray_shake.duration
			shake.aura.freq_factor = this.ray_shake.freq_factor

			queue_insert(store, shake)
			U.y_wait(store, fts(this.ray_cam_delay_frames))

			prev = prev + this.ray_cam_delay_frames

			signal.emit("pan-zoom-camera", this.ray_cam_speed, {
				x = this.ray_cam_start.x + i * cam_step,
				y = this.ray_cam_start.y
			}, this.ray_cam_zoom)
		end
	end

	local ADB = require("klove.animation_db")
	local total = ADB:duration(this.render.sprites[1].prefix .. "_" .. this.render.sprites[1].name) or 0

	U.y_wait(store, math.max(0, total - fts(prev)))
	S:queue(this.sound_bell_out)
end

scripts.decal_stage_18_demon_circle = {}

function scripts.decal_stage_18_demon_circle.update(this, store, script)
	while true do
		while not this._cast do
			coroutine.yield()
		end

		this._cast = nil

		U.y_animation_play(this, "in", nil, store.tick_ts, 1)
		U.animation_start(this, "loop", nil, store.tick_ts, true)

		while not this._out do
			coroutine.yield()
		end

		this._out = nil

		U.y_animation_play(this, "out", nil, store.tick_ts, 1)
	end
end

function scripts.controller_stage_18_veznan.on_explode_statue(this, store, event_name, x, y)
	this._queue = this._queue or {}

	table.insert(this._queue, {
		skill = "explode_statue",
		x = tonumber(x),
		y = tonumber(y)
	})
end

function scripts.controller_stage_18_veznan.update(this, store, script)
	this._queue = this._queue or {}

	local body, sigil_pi, sigil_spi, sigil_ni

	local function body_idle()
		if body then
			U.animation_start(body, "idle", nil, store.tick_ts, true)
		end
	end

	local function y_body_cast(sound, animation, time)
		S:queue(sound)

		if body then
			U.animation_start(body, animation, nil, store.tick_ts, false)
		end

		U.y_wait(store, time or this.cast_time)
	end

	local function y_body_recover()
		if body then
			U.y_animation_wait(body)
			U.animation_start(body, "idle", nil, store.tick_ts, true, nil, true)
		end
	end

	local function y_cast_gem_blast()
		local gb = this.gem_blast
		local targets = U.find_soldiers_in_range(store.entities, this.sigil_pos, 0, gb.radius, this.gem_blast_vis_flags, this.gem_blast_vis_bans)

		if not targets then
			return false
		end

		S:queue(this.gem_blast_sound)

		if body then
			U.animation_start(body, this.gem_blast_animation, nil, store.tick_ts, false)
		end

		local function muzzle_for(pos)
			local off = this.gem_blast_muzzle_offsets.center

			if pos.x < this.gem_blast_zone_left_x then
				off = this.gem_blast_muzzle_offsets.left
			elseif pos.x > this.gem_blast_zone_right_x then
				off = this.gem_blast_muzzle_offsets.right
			end

			return V.v(this.pos.x + off.x, this.pos.y + off.y)
		end

		targets = table.random_order(targets)

		local attacked = {}
		local last_pos = V.vclone(targets[1].pos)
		local last_hit_pos = V.vclone(last_pos)

		if targets[1].unit and targets[1].unit.hit_offset then
			last_hit_pos.x = last_hit_pos.x + targets[1].unit.hit_offset.x
			last_hit_pos.y = last_hit_pos.y + targets[1].unit.hit_offset.y
		end

		local prev_frame = 0

		for i, frame in ipairs(this.gem_blast_shot_frames) do
			U.y_wait(store, fts(frame - prev_frame))

			prev_frame = frame
			targets = U.find_soldiers_in_range(store.entities, this.sigil_pos, 0, gb.radius, this.gem_blast_vis_flags, this.gem_blast_vis_bans)

			local target

			if targets then
				targets = table.random_order(targets)
				target = targets[1]

				for _, t in ipairs(targets) do
					if not attacked[t.id] then
						target = t

						break
					end
				end
			end

			if target then
				attacked[target.id] = true
				last_pos = V.vclone(target.pos)
				last_hit_pos = V.vclone(last_pos)

				if target.unit and target.unit.hit_offset then
					last_hit_pos.x = last_hit_pos.x + target.unit.hit_offset.x
					last_hit_pos.y = last_hit_pos.y + target.unit.hit_offset.y
				end
			end

			local muzzle = muzzle_for(last_pos)

			if this.gem_blast_release_sound then
				S:queue(this.gem_blast_release_sound)
			end

			local bullet = E:create_entity(this.gem_blast_bullet_t)

			if this.gem_blast_curve_sides then
				bullet.initial_impulse_side = this.gem_blast_curve_sides[i]
			end

			bullet.pos = V.vclone(muzzle)
			bullet.bullet.from = V.vclone(muzzle)
			bullet.bullet.to = V.vclone(last_hit_pos)
			bullet.bullet.target_id = target and target.id
			bullet.keep_on_target_loss = true
			bullet.bullet.source_id = this.id

			if this.gem_blast_spawn_fx then
				local sfx = E:create_entity(this.gem_blast_spawn_fx)

				sfx.pos = V.vclone(muzzle)
				sfx.render.sprites[1].ts = store.tick_ts

				local sfx_angle = V.angleTo(bullet.bullet.to.x - muzzle.x, bullet.bullet.to.y - muzzle.y)

				if bullet.initial_impulse_side and bullet.initial_impulse_angle then
					sfx_angle = sfx_angle + bullet.initial_impulse_angle * bullet.initial_impulse_side
				end

				sfx.render.sprites[1].r = sfx_angle

				queue_insert(store, sfx)
			end

			queue_insert(store, bullet)
		end

		y_body_recover()

		return true
	end

	local function y_cast_disable_towers(cmd)
		local all = cmd.holder_group == "*"
		local groups = {}

		for g in string.gmatch(cmd.holder_group, "[^+]+") do
			groups[g] = true
		end

		local towers = table.filter(store.entities, function(k, v)
			return not v.pending_removal and v.tower and not v.tower.blocked and v.tower.type ~= "holder" and v.tower.type ~= "build_animation" and v.tower.can_be_mod and (all or v.tower.holder_id ~= nil and groups[tostring(v.tower.holder_id)]) and (not v.tower_holder or not v.tower_holder.blocked) and not U.has_modifier_types(store, v, MOD_TYPE_PROTECTION)
		end)

		if not towers or #towers == 0 then
			return false
		end

		y_body_cast(this.disable_cast_sound, this.disable_animation)

		towers = table.random_order(towers)

		for i = 1, math.min(cmd.count, #towers) do
			local m = E:create_entity(this.disable_mod_t)

			m.modifier.target_id = towers[i].id
			m.modifier.source_id = this.id

			if cmd.duration then
				m.modifier.duration = cmd.duration
			end

			queue_insert(store, m)
		end

		y_body_recover()

		return true
	end

	local function y_cast_summon(cmd)
		local circle = this._circle

		if this.summon_circle_t then
			if not circle or not store.entities[circle.id] then
				circle = E:create_entity(this.summon_circle_t)
				circle.pos = V.vclone(this.sigil_pos)
				circle.render.sprites[1].ts = store.tick_ts

				queue_insert(store, circle)

				this._circle = circle
			end

			circle._cast = true
		end

		y_body_cast(this.summon_cast_sound, this.summon_animation, fts(this.summon_shot_frame))

		local body_idle_restored = false

		local function y_wait_restore_idle(time)
			local ts = store.tick_ts

			while time > store.tick_ts - ts do
				if not body_idle_restored and body and U.animation_finished(body) then
					body_idle_restored = true

					U.animation_start(body, "idle", nil, store.tick_ts, true, nil, true)
				end

				coroutine.yield()
			end
		end

		local fx = E:create_entity(this.sigil_burst_fx)

		fx.pos = V.vclone(this.sigil_pos)
		fx.render.sprites[1].ts = store.tick_ts

		queue_insert(store, fx)

		local pi, ni = sigil_pi, sigil_ni
		local n = P:nearest_nodes(this.sigil_pos.x, this.sigil_pos.y, {
			cmd.path
		})[1]

		if n then
			pi, ni = n[1], n[3]
		else
			log.error("controller_stage_18_veznan: path %s sin nodos cerca del sigil, uso path %s", cmd.path, pi)
		end

		local ranged_holds = {}

		for _, row in ipairs(this.summon_groups[cmd.group]) do
			local subpath, delay, template = unpack(row)

			y_wait_restore_idle(math.max(0, delay - fts(5)))

			if this.summon_spawn_fx then
				local sfx = E:create_entity(this.summon_spawn_fx)

				sfx.pos = V.vclone(this.sigil_pos)
				sfx.render.sprites[1].ts = store.tick_ts

				queue_insert(store, sfx)
			end

			if this.summon_spawn_sound then
				S:queue(this.summon_spawn_sound)
			end

			y_wait_restore_idle(fts(5))

			if not U.is_seen(store, template) then
				signal.emit("wave-notification", "icon", template)
				U.mark_seen(store, template)
			end

			local e = E:create_entity(template)

			e.nav_path.pi = pi
			e.nav_path.spi = subpath
			e.nav_path.ni = ni
			e.pos.x, e.pos.y = this.sigil_pos.x, this.sigil_pos.y

			if this.summon_ranged_delay and e.ranged then
				for _, a in pairs(e.ranged.attacks) do
					a.ts = store.tick_ts + this.summon_ranged_delay - (a.cooldown or 0)

					if a.hold_advance then
						a.hold_advance = nil

						table.insert(ranged_holds, a)
					end
				end
			end

			queue_insert(store, e)
		end

		if circle then
			circle._out = true
		end

		if #ranged_holds > 0 then
			y_wait_restore_idle(this.summon_ranged_delay)

			for _, a in ipairs(ranged_holds) do
				a.hold_advance = true
			end
		end

		if not body_idle_restored then
			y_body_recover()
		end
	end

	local function y_cast_explode_statue(cmd)
		if not body or body.render.sprites[1].prefix ~= "veznan_fase2_balconDef" then
			log.error("controller_stage_18_veznan: veznan_explode_statue con exo %s (necesita veznan_fase2_balconDef), evento descartado", body and body.render.sprites[1].prefix or "nil")

			return false
		end

		S:queue(this.statue_cast_sound)
		U.animation_start(body, this.statue_animation, nil, store.tick_ts, false)
		U.y_wait(store, fts(this.statue_shot_frame))

		if this.statue_bolt_sound then
			S:queue(this.statue_bolt_sound)
		end

		local bullet = E:create_entity(this.statue_bullet_t)

		bullet.pos = V.v(this.pos.x + this.statue_muzzle_offset.x, this.pos.y + this.statue_muzzle_offset.y)
		bullet.bullet.from = V.vclone(bullet.pos)
		bullet.bullet.to = V.v(cmd.x or this.statue_target_pos.x, cmd.y or this.statue_target_pos.y)
		bullet.bullet.source_id = this.id

		queue_insert(store, bullet)
		y_body_recover()

		return true
	end

	local taunt_history = {}

	local function y_play_random_taunt()
		local sprite = body.render.sprites[1]
		local pool = this.taunt_animations[sprite.prefix]

		if not pool then
			return
		end

		local hist = taunt_history[sprite.prefix]

		if not hist then
			hist = {}
			taunt_history[sprite.prefix] = hist
		end

		local name = pool[get_random_round_robin(hist, #pool)]
		local ts = store.tick_ts

		U.animation_start(body, name, nil, ts, false)

		while sprite.name == name and sprite.ts == ts do
			if U.animation_finished(body) then
				U.animation_start(body, "idle", nil, store.tick_ts, true, nil, true)

				return
			end

			coroutine.yield()
		end
	end

	U.y_wait(store, 1e+99, function()
		return store.wave_group_number > 0
	end)

	body = find_all_t(store, this.body_decal_t)[1]

	body_idle()

	local nodes = P:nearest_nodes(this.sigil_pos.x, this.sigil_pos.y)

	if #nodes < 1 then
		log.error("controller_stage_18_veznan: no path nodes near sigil %s,%s", this.sigil_pos.x, this.sigil_pos.y)
		queue_remove(store, this)

		return
	end

	sigil_pi, sigil_spi, sigil_ni = unpack(nodes[1])

	local gem_ts = store.tick_ts
	local taunt_ts = store.tick_ts
	local taunt_wait = U.frandom(this.taunt_cooldown_min, this.taunt_cooldown_max)

	while true do
		if (store.level_mode_6 or store.level_mode) == GAME_MODE_CAMPAIGN or (store.level_mode_6 or store.level_mode) == GAME_MODE_NO_HEROES or (store.level_mode_6 or store.level_mode) == GAME_MODE_KR1 then
			if not this._bolts_off and store.wave_group_number >= this.gem_blast.start_wave and store.tick_ts - gem_ts >= this.gem_blast.cooldown and #this._queue == 0 then
				table.insert(this._queue, {
					skill = "gem_blast"
				})
			end

			local cmd = not this.hold_casts and table.remove(this._queue, 1) or nil

			if cmd then
				local casted = false

				if cmd.skill == "gem_blast" then
					casted = y_cast_gem_blast()
					gem_ts = casted and store.tick_ts or store.tick_ts - math.max(0, this.gem_blast.cooldown - 2)
				elseif cmd.skill == "disable_towers" then
					casted = y_cast_disable_towers(cmd)
				elseif cmd.skill == "summon_demons" then
					y_cast_summon(cmd)

					casted = true
				elseif cmd.skill == "explode_statue" then
					casted = y_cast_explode_statue(cmd)
				end

				if casted then
					U.y_wait(store, this.global_cooldown)

					taunt_ts = store.tick_ts
				end
			end
		end

		if this.hold_casts then
			taunt_ts = store.tick_ts
		elseif body and #this._queue == 0 and body.render.sprites[1].name == "idle" and taunt_wait < store.tick_ts - taunt_ts then
			y_play_random_taunt()

			taunt_ts = store.tick_ts
			taunt_wait = U.frandom(this.taunt_cooldown_min, this.taunt_cooldown_max)
		end

		coroutine.yield()
	end
end

scripts.mod_stage_18_veznan_tower_jail = {}

function scripts.mod_stage_18_veznan_tower_jail.update(this, store)
	local m = this.modifier
	local target = store.entities[m.target_id]

	if not target then
		queue_remove(store, this)

		return
	end

	U.animation_start(this, this.anim_tap[1], nil, store.tick_ts, nil, 1)
	U.y_animation_wait(this)
	U.animation_start(this, this.anim_tap[2], nil, store.tick_ts, true)

	local tap_tut = E:create_entity(this.tap_tutorial)

	tap_tut.pos = v(this.pos.x + this.tut_offset.x, this.pos.y + this.tut_offset.y)
	tap_tut.render.sprites[1].ts = store.tick_ts

	queue_insert(store, tap_tut)

	local taps = 0
	local tap_ts = store.tick_ts
	local window_ts = store.tick_ts
	local freed = false

	while store.tick_ts - window_ts < this.click_time do
		if this.ui and this.ui.clicked and store.tick_ts - tap_ts > 0.11 then
			taps = taps + 1
			tap_ts = store.tick_ts

			local shake = E:create_entity("mod_shake_sprite")

			shake.modifier.target_id = this.id
			shake.modifier.duration = 0.1
			shake.modifier.intensity = 4

			queue_insert(store, shake)

			if taps >= this.taps_to_thaw then
				freed = true

				S:queue(this.sound_events.interrupted)

				break
			end
		end

		this.ui.clicked = false

		coroutine.yield()
	end

	queue_remove(store, tap_tut)

	if not freed then
		S:queue(this.sound_events.locked)

		local lock_ts = store.tick_ts

		U.y_animation_play(this, this.anim_locked[1], nil, store.tick_ts, 1)
		U.animation_start(this, this.anim_locked[2], nil, store.tick_ts, true)
		U.y_wait(store, math.max(0, this.lock_duration - (store.tick_ts - lock_ts)))
		S:queue(this.sound_events.free_tower)
	end

	U.y_animation_play(this, this.anim_end, nil, store.tick_ts, 1)
	queue_remove(store, this)
end

scripts.enemy_stage_18_veznan_illusion = {}

function scripts.enemy_stage_18_veznan_illusion.update(this, store, script)
	local shared = this.shared or {
		illusions_killed = 0
	}

	this.shared = shared

	if this.melee_engage then
		this._melee_window = false
		this._melee_engage_ts = store.tick_ts
		this.vis.bans = U.flag_set(this.vis.bans, F_BLOCK)
	end

	local stagger = (this.stagger_idx or 0) * (this.skill_stagger or 0)
	local gem_ts = store.tick_ts + stagger - this.gem_blast.cooldown * 0.5
	local disable_ts = store.tick_ts + stagger
	local check_ts = store.tick_ts
	local skill_ts = 0
	local trigger_skill

	function this.health.on_damage(e, st, d)
		if e.health.dead or e._revealing then
			return false
		end

		if U.predict_damage(e, d) < e.health.hp then
			return true
		end

		if shared.illusions_killed < 2 then
			shared.illusions_killed = shared.illusions_killed + 1
			e._revealing = true
			e.health.ignore_damage = true
		end

		return false
	end

	local function gem_target_in_front(t)
		local dir = this.render.sprites[1].flip_x and -1 or 1

		return (t.pos.x - this.pos.x) * dir >= 0
	end

	local function aura_set_alpha(a)
		for i = 2, #this.render.sprites do
			this.render.sprites[i].alpha = a
		end
	end

	local function y_aura_fade_out()
		if not this.render.sprites[2] or not this.aura_fade_time then
			return
		end

		this._aura_fade_in_ts = nil

		local from = this.render.sprites[2].alpha or 255
		local ts = store.tick_ts

		while store.tick_ts - ts < this.aura_fade_time do
			aura_set_alpha(from * (1 - (store.tick_ts - ts) / this.aura_fade_time))
			coroutine.yield()
		end

		aura_set_alpha(0)
	end

	local function aura_fade_in_start()
		if not this.render.sprites[2] or not this.aura_fade_time then
			return
		end

		this._aura_fade_in_ts = store.tick_ts
	end

	local function aura_fade_in_tick()
		if not this._aura_fade_in_ts then
			return
		end

		local t = (store.tick_ts - this._aura_fade_in_ts) / this.aura_fade_time

		if t >= 1 then
			aura_set_alpha(255)

			this._aura_fade_in_ts = nil
		else
			aura_set_alpha(255 * t)
		end
	end

	local function find_jailable_towers()
		return U.find_towers(store.entities, this.pos, 0, this.disable.radius, function(v, o)
			return not v.pending_removal and not v.tower.blocked and v.tower.type ~= "holder" and v.tower.type ~= "build_animation" and v.tower.can_be_mod and (not v.tower_holder or not v.tower_holder.blocked) and not U.has_modifier_types(store, v, MOD_TYPE_PROTECTION)
		end)
	end

	local function can_cast()
		aura_fade_in_tick()

		if this.cinematic or this._revealing then
			return true
		end

		if shared.illusions_killed >= 2 then
			return true
		end

		if trigger_skill then
			return true
		end

		local me = this.melee_engage

		if me then
			if not this._melee_window and store.tick_ts - this._melee_engage_ts >= me.cooldown then
				this._melee_window = true
				this._melee_window_ts = store.tick_ts
				this.vis.bans = U.flag_clear(this.vis.bans, F_BLOCK)
			elseif this._melee_window and store.tick_ts - this._melee_window_ts >= me.duration then
				this._melee_window = false
				this._melee_engage_ts = store.tick_ts
				this.vis.bans = U.flag_set(this.vis.bans, F_BLOCK)

				for i = #this.enemy.blockers, 1, -1 do
					local blocker = store.entities[this.enemy.blockers[i]]

					if blocker then
						U.unblock_target(store, blocker)
					end

					table.remove(this.enemy.blockers, i)
				end
			end
		end

		if store.tick_ts - check_ts < 0.25 then
			return false
		end

		check_ts = store.tick_ts

		if store.tick_ts - skill_ts < this.skill_master_delay then
			return false
		end

		if store.tick_ts - gem_ts >= this.gem_blast.cooldown and U.find_soldiers_in_range(store.entities, this.pos, this.gem_blast.min_radius or 0, this.gem_blast.radius, this.gem_blast_vis_flags, this.gem_blast_vis_bans, gem_target_in_front) then
			trigger_skill = "gem_blast"

			return true
		end

		if store.tick_ts - disable_ts >= this.disable.cooldown then
			local towers = find_jailable_towers()

			if towers and #towers > 0 then
				trigger_skill = "disable"

				return true
			end
		end

		return false
	end

	local function y_cast_windup(sound, animation, time)
		S:queue(sound)
		U.animation_start(this, animation, nil, store.tick_ts, false)
		y_aura_fade_out()

		local t = (time or this.cast_time) - (this.aura_fade_time or 0)

		if SU.y_enemy_wait(store, this, math.max(0, t)) then
			return false
		end

		return not this._revealing
	end

	local function y_cast_gem_blast()
		gem_ts = store.tick_ts

		local gb = this.gem_blast
		local pre = U.find_soldiers_in_range(store.entities, this.pos, gb.min_radius or 0, gb.radius, this.gem_blast_vis_flags, this.gem_blast_vis_bans, gem_target_in_front)
		local last_pos = pre and V.vclone(pre[1].pos)

		if not y_cast_windup(this.gem_blast_sound, this.gem_blast_animation, this.gem_blast_shot_time) then
			return
		end

		if this.gem_blast_release_sound then
			S:queue(this.gem_blast_release_sound)
		end

		local targets = U.find_soldiers_in_range(store.entities, this.pos, gb.min_radius or 0, gb.radius, this.gem_blast_vis_flags, this.gem_blast_vis_bans, gem_target_in_front)

		if targets then
			targets = table.random_order(targets)

			for i = 1, math.min(gb.count, #targets) do
				local target = targets[i]
				local bullet = E:create_entity(this.gem_blast_bullet_t)
				local mo = this.gem_blast_muzzle_offset

				bullet.pos = V.v(this.pos.x + mo.x * (this.render.sprites[1].flip_x and -1 or 1), this.pos.y + mo.y)
				bullet.bullet.from = V.vclone(bullet.pos)
				bullet.bullet.to = V.vclone(target.pos)
				bullet.bullet.target_id = target.id
				bullet.bullet.source_id = this.id

				if gb.damage_min then
					bullet.bullet.damage_min = gb.damage_min
				end

				if gb.damage_max then
					bullet.bullet.damage_max = gb.damage_max
				end

				if this.gem_blast_spawn_fx then
					local sfx = E:create_entity(this.gem_blast_spawn_fx)

					sfx.pos = V.vclone(bullet.pos)
					sfx.render.sprites[1].ts = store.tick_ts
					sfx.render.sprites[1].r = V.angleTo(bullet.bullet.to.x - bullet.pos.x, bullet.bullet.to.y - bullet.pos.y)

					queue_insert(store, sfx)
				end

				queue_insert(store, bullet)

				if SU.y_enemy_wait(store, this, fts(4)) or this._revealing then
					return
				end
			end
		elseif last_pos then
			local bullet = E:create_entity(this.gem_blast_bullet_t)
			local mo = this.gem_blast_muzzle_offset

			bullet.pos = V.v(this.pos.x + mo.x * (this.render.sprites[1].flip_x and -1 or 1), this.pos.y + mo.y)
			bullet.bullet.from = V.vclone(bullet.pos)
			bullet.bullet.to = V.vclone(last_pos)
			bullet.bullet.source_id = this.id

			if this.gem_blast_spawn_fx then
				local sfx = E:create_entity(this.gem_blast_spawn_fx)

				sfx.pos = V.vclone(bullet.pos)
				sfx.render.sprites[1].ts = store.tick_ts
				sfx.render.sprites[1].r = V.angleTo(bullet.bullet.to.x - bullet.pos.x, bullet.bullet.to.y - bullet.pos.y)

				queue_insert(store, sfx)
			end

			queue_insert(store, bullet)
		end

		while not U.animation_finished(this) and not this._revealing do
			coroutine.yield()
		end

		aura_fade_in_start()

		skill_ts = store.tick_ts
	end

	local function y_cast_disable()
		disable_ts = store.tick_ts

		for i = #this.enemy.blockers, 1, -1 do
			local blocker = store.entities[this.enemy.blockers[i]]

			if blocker then
				U.unblock_target(store, blocker)
			end

			table.remove(this.enemy.blockers, i)
		end

		this.vis.bans = U.flag_set(this.vis.bans, F_BLOCK)
		this.health.ignore_damage = true

		if y_cast_windup(this.disable_cast_sound, this.disable_animation) then
			local towers = find_jailable_towers()

			if towers and #towers > 0 then
				towers = table.random_order(towers)

				for i = 1, math.min(this.disable.count, #towers) do
					local m = E:create_entity(this.disable_mod_t)

					m.modifier.target_id = towers[i].id
					m.modifier.source_id = this.id

					queue_insert(store, m)
				end
			end

			U.y_animation_wait(this)
		end

		if not this.melee_engage or this._melee_window then
			this.vis.bans = U.flag_clear(this.vis.bans, F_BLOCK)
		end

		this.health.ignore_damage = false

		aura_fade_in_start()

		skill_ts = store.tick_ts
	end

	local function y_reveal_illusion()
		log.debug("stage_18 veznan: ilusion revelada (%s/2)", shared.illusions_killed)

		local db = this.death_blast

		S:queue(this.illusion_death_sound)

		this.health_bar.hidden = true

		U.animation_start(this, this.illusion_death_animation, nil, store.tick_ts, false)

		local anim_start = store.tick_ts
		local souls_emitted = 0
		local ADB = require("klove.animation_db")
		local anim_duration = ADB:duration(this.render.sprites[1].prefix .. "_" .. this.illusion_death_animation) or 0
		local spawn_time = anim_duration - (this.death_spawns_lead_time or 0)
		local spawn_done = false

		local function spawn_demon_lord()
			if spawn_done or store.tick_ts - anim_start < spawn_time then
				return
			end

			spawn_done = true
			this.render.sprites[1].sort_y_offset = -10

			SU.do_death_spawns(store, this)
		end

		local aura_from = this.render.sprites[2] and this.aura_fade_time and (this.render.sprites[2].alpha or 255) or nil

		local function update_aura_fade()
			if not aura_from then
				return
			end

			local k = math.min(1, (store.tick_ts - anim_start) / this.aura_fade_time)
			local a = aura_from * (1 - k)

			for i = 2, #this.render.sprites do
				this.render.sprites[i].alpha = a
			end

			if k >= 1 then
				aura_from = nil
			end
		end

		local function spawn_release_soul(from, to)
			to = to or V.v(from.x + U.frandom(-db.soul_offset_x, db.soul_offset_x), from.y + U.frandom(db.soul_offset_y[1], db.soul_offset_y[2]))

			local blt = E:create_entity(this.death_blast_bullet_t)

			blt.pos = V.vclone(from)
			blt.bullet.from = V.vclone(from)
			blt.bullet.to = to
			blt.bullet.source_id = this.id

			local speed = V.dist(from.x, from.y, to.x, to.y) / db.soul_time

			blt.bullet.min_speed = speed
			blt.bullet.max_speed = speed
			blt.tween.ts = store.tick_ts

			queue_insert(store, blt)
		end

		local shockwave_done = false

		local function emit_pending_death_souls()
			local elapsed = store.tick_ts - anim_start

			if not shockwave_done and elapsed >= this.death_blast_shockwave_action_time then
				shockwave_done = true

				if this.death_blast_shockwave_fx then
					local swfx = E:create_entity(this.death_blast_shockwave_fx)

					swfx.pos = V.vclone(this.pos)
					swfx.render.sprites[1].ts = store.tick_ts

					queue_insert(store, swfx)
				end
			end

			while souls_emitted < db.death_soul_count and elapsed >= this.death_souls_action_time + souls_emitted * (this.death_souls_stagger or this.death_blast_stagger) do
				spawn_release_soul(V.v(this.pos.x, this.pos.y + this.unit.hit_offset.y))

				souls_emitted = souls_emitted + 1
			end
		end

		local victims
		local blast_pending = 0

		local function pump_blast()
			local elapsed = store.tick_ts - anim_start

			if not victims then
				if elapsed < this.death_blast_action_time then
					return
				end

				local targets = U.find_enemies_in_range(store.entities, this.pos, 0, db.radius, F_INSTAKILL, 0) or {}
				local allies = U.find_soldiers_in_range(store.entities, this.pos, 0, db.radius, F_INSTAKILL, F_ENEMY)

				if allies then
					for _, a in ipairs(allies) do
						table.insert(targets, a)
					end
				end

				targets = table.random_order(targets) or {}
				victims = {}

				for i, v in ipairs(targets) do
					victims[i] = {
						stage = 1,
						e = v,
						start = this.death_blast_action_time + (i - 1) * this.death_blast_stagger
					}
				end

				blast_pending = #victims
			end

			for _, w in ipairs(victims) do
				while w.stage < 5 do
					local v = w.e

					if not store.entities[v.id] or v.health.dead then
						w.stage = 5
						blast_pending = blast_pending - 1

						break
					end

					local due = w.start

					if w.stage >= 2 then
						due = due + (this.death_blast_flash_soul_time or 0)
					end

					if w.stage >= 3 then
						due = due + (this.death_blast_soul_disintegrate_time or 0)
					end

					if w.stage >= 4 then
						due = due + (this.death_blast_disintegrate_kill_time or 0)
					end

					if elapsed < due then
						break
					end

					if w.stage == 1 then
						w.from = V.v(v.pos.x, v.pos.y + (v.unit and v.unit.hit_offset and v.unit.hit_offset.y or 0))
						w.to = V.v(w.from.x + U.frandom(-db.soul_offset_x, db.soul_offset_x), w.from.y + U.frandom(db.soul_offset_y[1], db.soul_offset_y[2]))
						w.doomed = not v.hero and v.unit

						if this.death_blast_flash_fx then
							local sfx = E:create_entity(this.death_blast_flash_fx)

							sfx.pos = V.vclone(w.from)
							sfx.render.sprites[1].ts = store.tick_ts
							sfx.render.sprites[1].r = V.angleTo(w.to.x - w.from.x, w.to.y - w.from.y)

							queue_insert(store, sfx)
						end

						w.stage = 2
					elseif w.stage == 2 then
						spawn_release_soul(w.from, w.to)

						if w.doomed then
							w.stage = 3
						else
							local d = E:create_entity("damage")

							d.source_id = this.id
							d.target_id = v.id
							d.damage_type = DAMAGE_INSTAKILL

							queue_damage(store, d)

							w.stage = 5
							blast_pending = blast_pending - 1
						end
					elseif w.stage == 3 then
						v.unit.hide_during_death = true
						v.unit.show_blood_pool = false

						local dis_fx = E:create_entity(this.death_blast_disintegrate_fx)

						dis_fx.pos = V.vclone(v.pos)
						dis_fx.render.sprites[1].ts = store.tick_ts

						queue_insert(store, dis_fx)

						w.stage = 4
					elseif w.stage == 4 then
						local d = E:create_entity("damage")

						d.source_id = this.id
						d.target_id = v.id
						d.damage_type = bor(DAMAGE_TRUE, DAMAGE_EAT)

						queue_damage(store, d)

						w.stage = 5
						blast_pending = blast_pending - 1
					end
				end
			end
		end

		while not U.animation_finished(this) or not victims or blast_pending > 0 or souls_emitted < db.death_soul_count or not shockwave_done or not spawn_done do
			update_aura_fade()
			pump_blast()
			emit_pending_death_souls()
			spawn_demon_lord()
			coroutine.yield()
		end

		shared.reveals_done = (shared.reveals_done or 0) + 1

		queue_remove(store, this)
	end

	local function y_swap_to_real()
		local real = E:create_entity(this.real_template)

		real.pos = V.vclone(this.pos)
		real.nav_path.pi = this.nav_path.pi
		real.nav_path.spi = this.nav_path.spi
		real.nav_path.ni = this.nav_path.ni

		local rs, is = real.render.sprites[1], this.render.sprites[1]

		rs.name = is.name
		rs.ts = is.ts
		rs.time_offset = is.time_offset
		rs.loop = is.loop
		rs.flip_x = is.flip_x
		real._inherited_hp = this.health.hp
		real.shared = this.shared

		queue_insert(store, real)
		queue_remove(store, this)
	end

	while true do
		while this.cinematic do
			coroutine.yield()
		end

		if this.health.dead then
			SU.y_enemy_death(store, this)

			return
		end

		if this._revealing then
			y_reveal_illusion()

			return
		end

		if shared.illusions_killed >= 2 then
			y_swap_to_real()

			return
		end

		if trigger_skill then
			local skill = trigger_skill

			trigger_skill = nil

			if skill == "gem_blast" then
				y_cast_gem_blast()
			elseif skill == "disable" then
				y_cast_disable()
			end
		end

		if not SU.y_enemy_mixed_walk_melee_ranged(store, this, false, can_cast, can_cast) then
			-- block empty
		else
			coroutine.yield()
		end
	end
end

scripts.enemy_stage_18_veznan = {}

function scripts.enemy_stage_18_veznan.update(this, store, script)
	local gem_ts = store.tick_ts
	local disable_ts = store.tick_ts
	local siphon_ts = store.tick_ts
	local check_ts = store.tick_ts
	local skill_ts = 0
	local trigger_skill

	local function gem_target_in_front(t)
		local dir = this.render.sprites[1].flip_x and -1 or 1

		return (t.pos.x - this.pos.x) * dir >= 0
	end

	local function aura_set_alpha(a)
		for i = 2, #this.render.sprites do
			this.render.sprites[i].alpha = a
		end
	end

	local function y_aura_fade_out()
		if not this.render.sprites[2] or not this.aura_fade_time then
			return
		end

		this._aura_fade_in_ts = nil

		local from = this.render.sprites[2].alpha or 255
		local ts = store.tick_ts

		while store.tick_ts - ts < this.aura_fade_time do
			aura_set_alpha(from * (1 - (store.tick_ts - ts) / this.aura_fade_time))
			coroutine.yield()
		end

		aura_set_alpha(0)
	end

	local function aura_fade_in_start()
		if not this.render.sprites[2] or not this.aura_fade_time then
			return
		end

		this._aura_fade_in_ts = store.tick_ts
	end

	local function aura_fade_in_tick()
		if not this._aura_fade_in_ts then
			return
		end

		local t = (store.tick_ts - this._aura_fade_in_ts) / this.aura_fade_time

		if t >= 1 then
			aura_set_alpha(255)

			this._aura_fade_in_ts = nil
		else
			aura_set_alpha(255 * t)
		end
	end

	local function find_jailable_towers()
		return U.find_towers(store.entities, this.pos, 0, this.disable.radius, function(v, o)
			return not v.pending_removal and not v.tower.blocked and v.tower.type ~= "holder" and v.tower.type ~= "build_animation" and v.tower.can_be_mod and (not v.tower_holder or not v.tower_holder.blocked) and not U.has_modifier_types(store, v, MOD_TYPE_PROTECTION)
		end)
	end

	local function can_cast()
		aura_fade_in_tick()

		if this.cinematic then
			return true
		end

		if trigger_skill then
			return true
		end

		local rs = this.render.sprites[3]

		if rs then
			if not rs.hidden and rs.runs and rs.runs > 0 then
				rs.hidden = true
				this._ray_next_ts = store.tick_ts + U.frandom(1, 2)
			elseif rs.hidden and store.tick_ts >= (this._ray_next_ts or 0) then
				rs.hidden = false
				rs.ts = store.tick_ts
				rs.runs = 0
			end
		end

		local me = this.melee_engage

		if me then
			if not this._melee_window and store.tick_ts - this._melee_engage_ts >= me.cooldown then
				this._melee_window = true
				this._melee_window_ts = store.tick_ts
				this.vis.bans = U.flag_clear(this.vis.bans, F_BLOCK)
			elseif this._melee_window and store.tick_ts - this._melee_window_ts >= me.duration then
				this._melee_window = false
				this._melee_engage_ts = store.tick_ts
				this.vis.bans = U.flag_set(this.vis.bans, F_BLOCK)

				for i = #this.enemy.blockers, 1, -1 do
					local blocker = store.entities[this.enemy.blockers[i]]

					if blocker then
						U.unblock_target(store, blocker)
					end

					table.remove(this.enemy.blockers, i)
				end
			end
		end

		if store.tick_ts - check_ts < 0.25 then
			return false
		end

		check_ts = store.tick_ts

		if store.tick_ts - skill_ts < this.skill_master_delay then
			return false
		end

		if store.tick_ts - gem_ts >= this.gem_blast.cooldown and U.find_soldiers_in_range(store.entities, this.pos, this.gem_blast.min_radius or 0, this.gem_blast.radius, this.gem_blast_vis_flags, this.gem_blast_vis_bans, gem_target_in_front) then
			trigger_skill = "gem_blast"

			return true
		end

		if not this.disable_towers_off and store.tick_ts - disable_ts >= this.disable.cooldown then
			local towers = find_jailable_towers()

			if towers and #towers > 0 then
				trigger_skill = "disable"

				return true
			end
		end

		if store.tick_ts - siphon_ts >= this.siphon.cooldown and U.find_soldiers_in_range(store.entities, this.pos, this.siphon.min_radius or 0, this.siphon.radius, this.siphon_vis_flags, this.siphon_vis_bans) then
			trigger_skill = "siphon"

			return true
		end

		return false
	end

	local function y_cast_windup(sound, animation, time)
		S:queue(sound)
		U.animation_start(this, animation, nil, store.tick_ts, false)
		y_aura_fade_out()

		local t = (time or this.cast_time) - (this.aura_fade_time or 0)

		return not SU.y_enemy_wait(store, this, math.max(0, t))
	end

	local function y_cast_gem_blast()
		gem_ts = store.tick_ts

		local gb = this.gem_blast
		local pre = U.find_soldiers_in_range(store.entities, this.pos, gb.min_radius or 0, gb.radius, this.gem_blast_vis_flags, this.gem_blast_vis_bans, gem_target_in_front)
		local last_pos = pre and V.vclone(pre[1].pos)

		if not y_cast_windup(this.gem_blast_sound, this.gem_blast_animation, this.gem_blast_shot_time) then
			return
		end

		if this.gem_blast_release_sound then
			S:queue(this.gem_blast_release_sound)
		end

		local targets = U.find_soldiers_in_range(store.entities, this.pos, gb.min_radius or 0, gb.radius, this.gem_blast_vis_flags, this.gem_blast_vis_bans, gem_target_in_front)

		if targets then
			targets = table.random_order(targets)

			for i = 1, math.min(gb.count, #targets) do
				local target = targets[i]
				local bullet = E:create_entity(this.gem_blast_bullet_t)
				local mo = this.gem_blast_muzzle_offset

				bullet.pos = V.v(this.pos.x + mo.x * (this.render.sprites[1].flip_x and -1 or 1), this.pos.y + mo.y)
				bullet.bullet.from = V.vclone(bullet.pos)
				bullet.bullet.to = V.vclone(target.pos)
				bullet.bullet.target_id = target.id
				bullet.bullet.source_id = this.id

				if gb.damage_min then
					bullet.bullet.damage_min = gb.damage_min
				end

				if gb.damage_max then
					bullet.bullet.damage_max = gb.damage_max
				end

				if this.gem_blast_spawn_fx then
					local sfx = E:create_entity(this.gem_blast_spawn_fx)

					sfx.pos = V.vclone(bullet.pos)
					sfx.render.sprites[1].ts = store.tick_ts
					sfx.render.sprites[1].r = V.angleTo(bullet.bullet.to.x - bullet.pos.x, bullet.bullet.to.y - bullet.pos.y)

					queue_insert(store, sfx)
				end

				queue_insert(store, bullet)

				if SU.y_enemy_wait(store, this, fts(4)) then
					return
				end
			end
		elseif last_pos then
			local bullet = E:create_entity(this.gem_blast_bullet_t)
			local mo = this.gem_blast_muzzle_offset

			bullet.pos = V.v(this.pos.x + mo.x * (this.render.sprites[1].flip_x and -1 or 1), this.pos.y + mo.y)
			bullet.bullet.from = V.vclone(bullet.pos)
			bullet.bullet.to = V.vclone(last_pos)
			bullet.bullet.source_id = this.id

			if this.gem_blast_spawn_fx then
				local sfx = E:create_entity(this.gem_blast_spawn_fx)

				sfx.pos = V.vclone(bullet.pos)
				sfx.render.sprites[1].ts = store.tick_ts
				sfx.render.sprites[1].r = V.angleTo(bullet.bullet.to.x - bullet.pos.x, bullet.bullet.to.y - bullet.pos.y)

				queue_insert(store, sfx)
			end

			queue_insert(store, bullet)
		end

		while not U.animation_finished(this) and not this.health.dead do
			coroutine.yield()
		end

		aura_fade_in_start()

		skill_ts = store.tick_ts
	end

	local function y_cast_disable()
		disable_ts = store.tick_ts

		for i = #this.enemy.blockers, 1, -1 do
			local blocker = store.entities[this.enemy.blockers[i]]

			if blocker then
				U.unblock_target(store, blocker)
			end

			table.remove(this.enemy.blockers, i)
		end

		this.vis.bans = U.flag_set(this.vis.bans, F_BLOCK)
		this.health.ignore_damage = true

		if y_cast_windup(this.disable_cast_sound, this.disable_animation) then
			local towers = find_jailable_towers()

			if towers and #towers > 0 then
				towers = table.random_order(towers)

				for i = 1, math.min(this.disable.count, #towers) do
					local m = E:create_entity(this.disable_mod_t)

					m.modifier.target_id = towers[i].id
					m.modifier.source_id = this.id

					queue_insert(store, m)
				end
			end

			U.y_animation_wait(this)
		end

		if not this.melee_engage or this._melee_window then
			this.vis.bans = U.flag_clear(this.vis.bans, F_BLOCK)
		end

		this.health.ignore_damage = false

		aura_fade_in_start()

		skill_ts = store.tick_ts
	end

	local function y_cast_siphon()
		siphon_ts = store.tick_ts

		local sp = this.siphon
		local targets = U.find_soldiers_in_range(store.entities, this.pos, sp.min_radius or 0, sp.radius, this.siphon_vis_flags, this.siphon_vis_bans)

		if not targets then
			return
		end

		targets = table.random_order(targets)

		local count = math.min(sp.count, #targets)

		S:queue(this.siphon_sound)

		if this.siphon_cast_decal then
			local cfx = E:create_entity(this.siphon_cast_decal)

			cfx.pos = V.vclone(this.pos)
			cfx.render.sprites[1].ts = store.tick_ts

			queue_insert(store, cfx)
		end

		U.animation_start(this, this.siphon_animations[1], nil, store.tick_ts, false)
		y_aura_fade_out()

		if SU.y_enemy_wait(store, this, math.max(0, this.siphon_shoot_time - (this.aura_fade_time or 0))) then
			return
		end

		U.animation_start(this, this.siphon_animations[2], nil, store.tick_ts, true)

		local bullets = {}

		for i = 1, count do
			do
				local target = targets[i]

				if not store.entities[target.id] or target.health.dead then
					-- block empty
				else
					local co = this.siphon_catch_offset or this.unit.hit_offset
					local to = V.v(this.pos.x + co.x * (this.render.sprites[1].flip_x and -1 or 1), this.pos.y + co.y)
					local d = E:create_entity("damage")

					d.damage_type = DAMAGE_TRUE
					d.value = math.ceil(U.frandom(sp.damage_min, sp.damage_max))
					d.target_id = target.id
					d.source_id = this.id

					local doomed = not target.hero and target.unit and U.predict_damage(target, d) >= target.health.hp
					local from = V.v(target.pos.x, target.pos.y + (target.unit and target.unit.hit_offset and target.unit.hit_offset.y or 0))

					if this.siphon_flash_fx then
						local sfx = E:create_entity(this.siphon_flash_fx)

						sfx.pos = V.vclone(from)
						sfx.render.sprites[1].ts = store.tick_ts
						sfx.render.sprites[1].r = V.angleTo(to.x - from.x, to.y - from.y)

						queue_insert(store, sfx)
					end

					if SU.y_enemy_wait(store, this, this.siphon_flash_soul_time or 0) then
						return
					end

					if not store.entities[target.id] or target.health.dead then
						-- block empty
					else
						from = V.v(target.pos.x, target.pos.y + (target.unit and target.unit.hit_offset and target.unit.hit_offset.y or 0))

						local speed = V.dist(from.x, from.y, to.x, to.y) / sp.soul_time
						local bullet = E:create_entity(this.siphon_bullet_t)

						bullet.pos = V.vclone(from)
						bullet.bullet.from = V.vclone(from)
						bullet.bullet.to = to
						bullet.bullet.source_id = this.id
						bullet.bullet.min_speed = speed
						bullet.bullet.max_speed = speed

						queue_insert(store, bullet)
						table.insert(bullets, bullet)

						if doomed then
							if SU.y_enemy_wait(store, this, this.siphon_soul_disintegrate_time or 0) then
								return
							end

							if not store.entities[target.id] or target.health.dead then
								goto label_1582_0
							end

							d.damage_type = bor(DAMAGE_TRUE, DAMAGE_EAT)
							target.unit.hide_during_death = true
							target.unit.show_blood_pool = false

							local dis_fx = E:create_entity(this.siphon_disintegrate_fx)

							dis_fx.pos = V.vclone(target.pos)
							dis_fx.render.sprites[1].ts = store.tick_ts

							queue_insert(store, dis_fx)

							if SU.y_enemy_wait(store, this, this.siphon_disintegrate_kill_time or 0) then
								return
							end

							if not store.entities[target.id] or target.health.dead then
								goto label_1582_0
							end
						end

						queue_damage(store, d)

						if i < count and sp.stagger and sp.stagger > 0 and SU.y_enemy_wait(store, this, sp.stagger) then
							return
						end
					end
				end
			end

			::label_1582_0::
		end

		SU.y_enemy_wait(store, this, sp.soul_time + fts(3))

		for _, blt in ipairs(bullets) do
			if store.entities[blt.id] then
				if this.siphon_arrive_fx then
					local afx = E:create_entity(this.siphon_arrive_fx)

					afx.pos = V.vclone(blt.pos)
					afx.render.sprites[1].ts = store.tick_ts

					queue_insert(store, afx)
				end

				if blt.arrive_pump_fx then
					local pfx = E:create_entity(blt.arrive_pump_fx)

					pfx.pos = V.vclone(this.pos)
					pfx.render.sprites[1].ts = store.tick_ts

					queue_insert(store, pfx)
				end

				queue_remove(store, blt)
			end
		end

		if this.health.dead then
			return
		end

		if this.siphon_heal_fx then
			local hfx = E:create_entity(this.siphon_heal_fx)

			hfx.pos = V.vclone(this.pos)
			hfx.render.sprites[1].ts = store.tick_ts

			queue_insert(store, hfx)
		end

		this.health.hp = km.clamp(0, this.health.hp_max, this.health.hp + count * sp.heal_per_soul)

		local spr = this.render.sprites[1]
		local loop_runs = spr.runs

		while spr.runs == loop_runs and not this.health.dead do
			coroutine.yield()
		end

		if this.health.dead then
			return
		end

		U.y_animation_play(this, this.siphon_animations[3], nil, store.tick_ts, 1)
		aura_fade_in_start()

		skill_ts = store.tick_ts
	end

	local function y_on_death()
		this._death_started = true

		if this._wave_real_started then
			W:stop_manual_wave(this.wave_real)
		end

		pcall(signal.emit, "boss_fight_end")

		store.kill_tunnel_releases = true

		LU.kill_all_enemies(store, true)

		local shake = E:create_entity("aura_screen_shake")

		shake.aura.amplitude = 1
		shake.aura.duration = 2
		shake.aura.freq_factor = 3

		queue_insert(store, shake)
		signal.emit("boss-killed", this)

		local function cam_out()
			local c = this.death_cam_out

			if not c then
				return
			end

			signal.emit("pan-zoom-camera", c.time, {
				x = c.pos.x,
				y = c.pos.y
			}, c.zoom)
		end

		signal.emit("hide-gui")

		store.ephemeral.stage_18_final_cinematic = true

		signal.emit("start-cinematic")

		if this.death_cam_in then
			signal.emit("pan-zoom-camera", this.death_cam_in.time, {
				x = this.pos.x,
				y = this.pos.y
			}, this.death_cam_in.zoom)
		end

		U.animation_start(this, "idle", nil, store.tick_ts, true, nil, true)
		y_aura_fade_out()
		U.y_wait(store, math.max(0, this.death_cam_in.time - (this.aura_fade_time or 0)))
		S:queue(this.death_sound)
		U.y_animation_play(this, this.death_animations[1], nil, store.tick_ts, 1)
		U.animation_start(this, this.death_animations[2], nil, store.tick_ts, true, nil, true)

		this._death_loop_ts = store.tick_ts

		if this.death_loop_shockwave_fx then
			local off = this.death_loop_soul_offset
			local swfx = E:create_entity(this.death_loop_shockwave_fx)

			swfx.pos = V.v(this.pos.x + off.x, this.pos.y + off.y)
			swfx.render.sprites[1].ts = store.tick_ts

			queue_insert(store, swfx)
		end

		cam_out()

		if this.death_loop_shake then
			local shake = E:create_entity("aura_screen_shake")

			shake.aura.amplitude = this.death_loop_shake.amplitude
			shake.aura.duration = this.death_loop_shake.duration
			shake.aura.freq_factor = this.death_loop_shake.freq_factor

			queue_insert(store, shake)
		end

		local sd = this.death_loop_soul_delay
		local ramp_time = this.death_loop_time * (1 - this.death_loop_soul_delay_tail_ptg)
		local soul_ts = store.tick_ts
		local next_delay = sd[1]
		local end_shake_done = false

		while store.tick_ts - this._death_loop_ts < this.death_loop_time do
			if not end_shake_done and store.tick_ts - this._death_loop_ts >= this.death_loop_time - this.death_end_shake_lead then
				end_shake_done = true

				local shake = E:create_entity("aura_screen_shake")

				shake.aura.amplitude = this.death_end_shake.amplitude
				shake.aura.duration = this.death_end_shake.duration
				shake.aura.freq_factor = this.death_end_shake.freq_factor

				queue_insert(store, shake)
			end

			if next_delay <= store.tick_ts - soul_ts then
				soul_ts = store.tick_ts

				local k = ramp_time > 0 and math.min(1, (soul_ts - this._death_loop_ts) / ramp_time) or 1

				next_delay = sd[1] + (sd[2] - sd[1]) * k

				local off = this.death_loop_soul_offset
				local from = V.v(this.pos.x + off.x, this.pos.y + off.y)
				local vc = store.visible_coords
				local to = V.v(vc and U.frandom(vc.left, vc.right) or from.x, (vc and vc.top or REF_H) + 100)
				local blt = E:create_entity(this.death_loop_soul_t)

				blt.pos = V.vclone(from)
				blt.bullet.from = V.vclone(from)
				blt.bullet.to = to
				blt.bullet.source_id = this.id

				local speed = V.dist(from.x, from.y, to.x, to.y) / this.death_loop_soul_time

				blt.bullet.min_speed = speed
				blt.bullet.max_speed = speed

				queue_insert(store, blt)
			end

			coroutine.yield()
		end

		if this.death_end_flash_fx and not features.censored_cn then
			local flash = E:create_entity(this.death_end_flash_fx)

			flash.tween.ts = store.tick_ts

			queue_insert(store, flash)
		end

		U.y_animation_play(this, this.death_animations[3], nil, store.tick_ts, 1)
		LU.kill_all_enemies(store, true)
		signal.emit("end-cinematic")

		store.ephemeral.stage_18_final_cinematic = nil
		this._death_finished = true
		this.unit.death_animation = nil

		SU.y_enemy_death(store, this)
	end

	local ro = this.real_overrides or {}

	if ro.hp_max then
		this.health.hp_max = get_difficulty_field_value(store, ro.hp_max)
	end

	this.health.hp = km.clamp(0, this.health.hp_max, this._inherited_hp or this.health.hp_max)

	if ro.speed then
		this.motion.max_speed = ro.speed
	end

	if ro.basic_attack then
		if ro.basic_attack.cooldown then
			this.melee.cooldown = ro.basic_attack.cooldown
		end

		for _, a in ipairs(this.melee.attacks) do
			a.cooldown = ro.basic_attack.cooldown or a.cooldown
			a.damage_min = ro.basic_attack.damage_min or a.damage_min
			a.damage_max = ro.basic_attack.damage_max or a.damage_max
			a.damage_radius = ro.basic_attack.damage_radius or a.damage_radius
		end
	end

	if ro.gem_blast then
		for k, v in pairs(ro.gem_blast) do
			this.gem_blast[k] = v
		end
	end

	if ro.disable_towers then
		for k, v in pairs(ro.disable_towers) do
			this.disable[k] = v
		end
	end

	if not U.is_seen(store, "enemy_stage_18_veznan") then
		signal.emit("wave-notification", "icon", "enemy_stage_18_veznan")
		U.mark_seen(store, "enemy_stage_18_veznan")
	end

	W:stop_manual_wave(this.wave_illusions)

	if not S:sound_is_playing("MusicBossFight_18") then
		S:stop_group("MUSIC")
		S:queue("MusicBossFight_18")
	end

	function this.health.on_damage(e, st, d)
		if e.health.dead then
			return false
		end

		return U.predict_damage(e, d) < e.health.hp
	end

	local shared = this.shared

	local function reveal_ready()
		return not shared or (shared.reveals_done or 0) >= 2
	end

	while not reveal_ready() do
		if this.health.dead then
			y_on_death()

			return
		end

		if not SU.y_enemy_mixed_walk_melee_ranged(store, this, false, reveal_ready, reveal_ready) then
			-- block empty
		else
			coroutine.yield()
		end
	end

	local rv = this.reveal

	while #this.enemy.blockers > 0 do
		local blocker = store.entities[this.enemy.blockers[1]]

		if blocker then
			U.unblock_target(store, blocker)
		else
			table.remove(this.enemy.blockers, 1)
		end
	end

	local reveal_bans = this.vis.bans

	this.vis.bans = F_ALL
	this.health.ignore_damage = true

	if this.center_reveal then
		signal.emit("hide-gui")
		signal.emit("start-cinematic")

		store.ephemeral.disable_live_costs = true

		local tc = this.death_teleport_cam
		local cam_ts = store.tick_ts

		if tc then
			signal.emit("pan-zoom-camera", tc.time, {
				x = this.center_reveal_pos.x,
				y = this.center_reveal_pos.y
			}, tc.zoom)
		end

		U.animation_start(this, "idle", nil, store.tick_ts, true, nil, true)

		if this.health_bar then
			this.health_bar.hidden = true
		end

		local ray_ts = store.tick_ts

		S:queue(this.center_reveal_sound)

		if this.center_reveal_fx then
			local tfx = E:create_entity(this.center_reveal_fx)

			tfx.pos = V.vclone(this.pos)
			tfx.render.sprites[1].ts = store.tick_ts

			queue_insert(store, tfx)
		end

		y_aura_fade_out()
		U.y_wait(store, math.max(0, this.center_reveal_show_time - (store.tick_ts - ray_ts)))
		U.sprites_hide(this)

		this.pos.x, this.pos.y = this.center_reveal_pos.x, this.center_reveal_pos.y

		if tc then
			U.y_wait(store, math.max(0, tc.time - (store.tick_ts - cam_ts)))
		end

		S:queue(this.center_reveal_sound)

		if this.center_reveal_fx then
			local tfx = E:create_entity(this.center_reveal_fx)

			tfx.pos = V.vclone(this.pos)
			tfx.render.sprites[1].ts = store.tick_ts

			queue_insert(store, tfx)
		end

		U.y_wait(store, this.center_reveal_show_time)
		U.sprites_show(this)
	end

	U.animation_start(this, "idle", nil, store.tick_ts, true, nil, true)
	SU.y_enemy_wait(store, this, rv.taunt_pre_delay)

	local bo = this.reveal_taunt_balloon_offset

	signal.emit("show-balloon_tutorial-pos", this.reveal_taunt_balloon, false, V.v(this.pos.x + bo.x, this.pos.y + bo.y))
	U.y_animation_play(this, this.reveal_taunt_animation, nil, store.tick_ts, 1)
	U.animation_start(this, "idle", nil, store.tick_ts, true, nil, true)
	SU.y_enemy_wait(store, this, rv.taunt_post_delay)
	S:queue(this.reveal_in_sound)
	U.y_animation_play(this, this.reveal_animations[1], nil, store.tick_ts, 1)
	U.animation_start(this, this.reveal_animations[2], nil, store.tick_ts, true)

	local loop_start = store.tick_ts

	if this.center_reveal then
		if this.center_reveal_shockwave_fx then
			local swfx = E:create_entity(this.center_reveal_shockwave_fx)

			swfx.pos = V.vclone(this.pos)
			swfx.render.sprites[1].ts = store.tick_ts

			queue_insert(store, swfx)
		end

		LU.kill_all_enemies(store, false)

		for _, e in pairs(store.entities) do
			if e.soldier and e.health and not e.health.dead and e.vis and band(e.vis.flags, F_ENEMY) == 0 and band(e.vis.bans, F_INSTAKILL) == 0 then
				if e.hero then
					local d = E:create_entity("damage")

					d.damage_type = DAMAGE_TRUE
					d.value = math.ceil(U.frandom(rv.hero_damage_min, rv.hero_damage_max))
					d.target_id = e.id
					d.source_id = this.id

					queue_damage(store, d)

					local s = E:create_entity(this.reveal_hero_stun_mod)

					s.modifier.target_id = e.id
					s.modifier.source_id = this.id

					queue_insert(store, s)
				else
					local d = E:create_entity("damage")

					d.damage_type = DAMAGE_INSTAKILL
					d.target_id = e.id
					d.source_id = this.id

					queue_damage(store, d)
				end
			end
		end
	end

	local cfx = E:create_entity(this.reveal_cast_decal)

	cfx.pos = V.vclone(this.pos)
	cfx.render.sprites[1].ts = store.tick_ts

	queue_insert(store, cfx)

	local ok, err = pcall(signal.emit, "boss_fight_start_tweened", this, 0.3)

	if not ok then
		log.error("enemy_stage_18_veznan: boss_fight_start_tweened fallo (widget destruido tras restart?): %s", err)
	end

	local co = this.reveal_catch_offset or this.unit.hit_offset
	local to = V.v(this.pos.x + co.x * (this.render.sprites[1].flip_x and -1 or 1), this.pos.y + co.y)
	local stagger = (rv.loop_time - rv.soul_time) / math.max(1, rv.soul_count - 1)
	local heal_chunk = this.reveal_full_heal and (this.health.hp_max - this.health.hp) / rv.soul_count or 0

	for i = 1, rv.soul_count do
		local from = V.v(this.pos.x + U.frandom(-rv.soul_offset_x, rv.soul_offset_x), this.pos.y + U.frandom(rv.soul_offset_y[1], rv.soul_offset_y[2]))
		local speed = V.dist(from.x, from.y, to.x, to.y) / rv.soul_time
		local bullet = E:create_entity(this.reveal_bullet_t)

		bullet.pos = V.vclone(from)
		bullet.bullet.from = V.vclone(from)
		bullet.bullet.to = V.vclone(to)
		bullet.bullet.source_id = this.id
		bullet.bullet.min_speed = speed
		bullet.bullet.max_speed = speed
		bullet.tween.ts = store.tick_ts
		bullet.reveal_heal = heal_chunk

		queue_insert(store, bullet)

		if i < rv.soul_count then
			SU.y_enemy_wait(store, this, stagger)
		end
	end

	SU.y_enemy_wait(store, this, rv.loop_time - (store.tick_ts - loop_start))

	if this.reveal_full_heal then
		this.health.hp = this.health.hp_max
	end

	U.y_animation_play(this, this.reveal_animations[3], nil, store.tick_ts, 1)

	if this.center_reveal then
		signal.emit("show-gui")
		signal.emit("end-cinematic")

		store.ephemeral.disable_live_costs = nil

		aura_fade_in_start()
	end

	this._wave_real_started = true

	W:start_manual_wave(this.wave_real)

	this.vis.bans = reveal_bans
	this.health.ignore_damage = false
	this.health.on_damage = nil
	gem_ts = store.tick_ts
	disable_ts = store.tick_ts

	if this.melee_engage then
		this._melee_window = false
		this._melee_engage_ts = store.tick_ts
		this.vis.bans = U.flag_set(this.vis.bans, F_BLOCK)
	end

	this._ray_next_ts = store.tick_ts + U.frandom(1, 2)

	if this.center_reveal then
		local n = P:nearest_nodes(this.pos.x, this.pos.y, {
			this.center_reveal_path
		})[1]

		if n then
			this.nav_path.pi, this.nav_path.spi, this.nav_path.ni = n[1], n[2], n[3]
		else
			log.error("enemy_stage_18_veznan: sin nodos del path %s cerca del centro, sigue con el heredado", this.center_reveal_path)
		end
	end

	siphon_ts = store.tick_ts

	while true do
		while this.cinematic do
			coroutine.yield()
		end

		if this.health.dead then
			y_on_death()

			return
		end

		if trigger_skill then
			local skill = trigger_skill

			trigger_skill = nil

			if skill == "gem_blast" then
				y_cast_gem_blast()
			elseif skill == "disable" then
				y_cast_disable()
			elseif skill == "siphon" then
				y_cast_siphon()
			end
		end

		if not SU.y_enemy_mixed_walk_melee_ranged(store, this, false, can_cast, can_cast) then
			-- block empty
		else
			coroutine.yield()
		end
	end
end

scripts.bullet_stage_18_moloch_lava_ball = {}

function scripts.bullet_stage_18_moloch_lava_ball.update(this, store, script)
	scripts.enemy_bomb.update(this, store, script)

	if this.spawn_data then
		this.spawn_data.die_after_spawn = store.ephemeral.stage_18_final_cinematic
	end

	if this.screenshake_amplitude then
		local shake = E:create_entity("aura_screen_shake")

		shake.aura.amplitude = this.screenshake_amplitude
		shake.aura.duration = this.screenshake_duration
		shake.aura.freq_factor = this.screenshake_freq_factor

		queue_insert(store, shake)
	end
end

scripts.controller_stage_18_moloch = {}

function scripts.controller_stage_18_moloch.on_claw_slam(this, store, event_name)
	this._queue = this._queue or {}

	table.insert(this._queue, {
		skill = "claw_slam"
	})
end

function scripts.controller_stage_18_moloch.on_lava_ball(this, store, event_name, area, count)
	this._queue = this._queue or {}

	local a = tonumber(area)

	if not a or a < 1 or a > #this.lava_ball.areas then
		a = 1
	end

	table.insert(this._queue, {
		skill = "lava_ball",
		area = a,
		count = tonumber(count)
	})
end

function scripts.controller_stage_18_moloch.on_hellspawn_boost(this, store, event_name, duration)
	this._queue = this._queue or {}

	table.insert(this._queue, {
		skill = "hellspawn_boost",
		duration = tonumber(duration)
	})
end

function scripts.controller_stage_18_moloch.mod_tower_stun_update(this, store)
	local m = this.modifier

	U.animation_start(this, "loop", nil, store.tick_ts, true)

	while store.tick_ts - m.ts < m.duration - this.fade_time do
		coroutine.yield()
	end

	local s = this.render.sprites[1]

	while store.tick_ts - m.ts < m.duration do
		s.alpha = 255 * km.clamp(0, 1, (m.duration - (store.tick_ts - m.ts)) / this.fade_time)

		coroutine.yield()
	end

	queue_remove(store, this)
end

function scripts.controller_stage_18_moloch.bullet_target_update(this, store)
	local start_ts = store.tick_ts

	U.animation_start(this, "in2", nil, store.tick_ts, false)

	while store.tick_ts - start_ts < this.duration - this.out_time do
		if this.render.sprites[1].name == "in2" and U.animation_finished(this) then
			U.animation_start(this, "loop2", nil, store.tick_ts, true)
		end

		coroutine.yield()
	end

	U.y_animation_play(this, "out2", nil, store.tick_ts, 1)
	queue_remove(store, this)
end

function scripts.controller_stage_18_moloch.mod_buff_update(this, store)
	local m = this.modifier
	local target = store.entities[m.target_id]

	if target then
		this.pos = target.pos
	end

	U.animation_start(this, "in", nil, store.tick_ts, false)
	U.y_animation_wait(this)
	U.animation_start(this, "loop", nil, store.tick_ts, true)

	local expired = false

	while true do
		local target = store.entities[m.target_id]

		if not target or target.health and target.health.dead then
			break
		end

		if store.tick_ts - m.ts >= m.duration - this.out_time then
			expired = true

			break
		end

		coroutine.yield()
	end

	if expired then
		U.y_animation_play(this, "out", nil, store.tick_ts, 1)
	end

	queue_remove(store, this)
end

function scripts.controller_stage_18_moloch.update(this, store, script)
	this._queue = this._queue or {}

	local body

	local function body_shake(duration, intensity)
		if not body then
			return
		end

		local shake = E:create_entity("mod_shake_sprite")

		shake.modifier.target_id = body.id
		shake.modifier.duration = duration
		shake.modifier.intensity = intensity

		queue_insert(store, shake)
	end

	local function y_body_cast(sound, anim, hit_time, sound_frame)
		S:queue(sound, sound_frame and {
			delay = fts(sound_frame)
		} or nil)
		U.animation_start(body, anim, nil, store.tick_ts, false)
		U.y_wait(store, hit_time)
	end

	local function y_body_recover()
		U.y_animation_wait(body)
		U.animation_start(body, "idle", nil, store.tick_ts, true, nil, true)
	end

	local function screen_shake(cfg)
		local shake = E:create_entity("aura_screen_shake")

		shake.aura.amplitude = cfg.amplitude
		shake.aura.duration = cfg.duration
		shake.aura.freq_factor = cfg.freq_factor

		queue_insert(store, shake)
	end

	local function y_cast_claw_slam()
		local cs = this.claw_slam

		S:queue(this.claw_cast_sound)

		if this.claw_hit_time >= cs.telegraph_time then
			U.animation_start(body, this.claw_animation, nil, store.tick_ts, false)
			U.y_wait(store, this.claw_hit_time - cs.telegraph_time, function()
				return this._abort
			end)

			if this._abort then
				U.animation_start(body, "idle", nil, store.tick_ts, true, nil, true)

				return
			end
		end

		local target_pos = V.v(cs.pos.x, cs.pos.y)
		local tele = E:create_entity(this.claw_telegraph_t)

		tele.pos = V.vclone(target_pos)
		tele.render.sprites[1].ts = store.tick_ts

		queue_insert(store, tele)
		U.animation_start(tele, "in", nil, store.tick_ts, false)

		local anim_started = this.claw_hit_time >= cs.telegraph_time
		local anim_delay = cs.telegraph_time - this.claw_hit_time
		local start_ts = store.tick_ts

		while store.tick_ts - start_ts < cs.telegraph_time - tele.out_time do
			if this._abort then
				queue_remove(store, tele)
				U.animation_start(body, "idle", nil, store.tick_ts, true, nil, true)

				return
			end

			if not anim_started and anim_delay <= store.tick_ts - start_ts then
				U.animation_start(body, this.claw_animation, nil, store.tick_ts, false)

				anim_started = true
			end

			if tele.render.sprites[1].name == "in" and U.animation_finished(tele) then
				U.animation_start(tele, "loop", nil, store.tick_ts, true)
			end

			coroutine.yield()
		end

		if not anim_started then
			U.animation_start(body, this.claw_animation, nil, store.tick_ts, false)
		end

		U.y_animation_play(tele, "out", nil, store.tick_ts, 1)
		queue_remove(store, tele)
		S:queue(this.claw_hit_sound)

		local shake = E:create_entity("aura_screen_shake")

		shake.aura.amplitude = 1
		shake.aura.duration = 0.5
		shake.aura.freq_factor = 2

		queue_insert(store, shake)

		local fx = E:create_entity(this.claw_hit_fx)

		fx.pos = V.vclone(target_pos)
		fx.render.sprites[1].ts = store.tick_ts

		queue_insert(store, fx)

		local sdecal = E:create_entity(this.claw_decal_t)

		sdecal.pos = V.vclone(target_pos)
		sdecal.render.sprites[1].ts = store.tick_ts

		queue_insert(store, sdecal)

		local kills = 0
		local killed = {}
		local targets = U.find_soldiers_in_range(store.entities, target_pos, 0, cs.damage_radius, F_INSTAKILL, bor(F_ENEMY, F_HERO))

		if targets then
			for _, e in ipairs(targets) do
				local d = E:create_entity("damage")

				d.source_id = this.id
				d.target_id = e.id
				d.damage_type = DAMAGE_INSTAKILL

				queue_damage(store, d)

				killed[e.id] = true
				kills = kills + 1
			end
		end

		local shock_targets = U.find_soldiers_in_range(store.entities, target_pos, 0, cs.shock_radius, 0, bor(F_ENEMY))

		if shock_targets then
			for _, e in ipairs(shock_targets) do
				if not killed[e.id] then
					local dist_factor = U.dist_factor_inside_ellipse(e.pos, target_pos, cs.shock_radius)
					local d = E:create_entity("damage")

					d.source_id = this.id
					d.target_id = e.id
					d.damage_type = DAMAGE_TRUE
					d.value = math.floor(cs.shock_damage_max - (cs.shock_damage_max - cs.shock_damage_min) * dist_factor)

					queue_damage(store, d)
				end
			end
		end

		local stuns = 0
		local towers = U.find_towers(store.entities, target_pos, 0, cs.damage_radius, function(v, o)
			return not v.pending_removal and not v.tower.blocked and v.tower.type ~= "holder" and v.tower.type ~= "build_animation" and v.tower.can_be_mod and (not v.tower_holder or not v.tower_holder.blocked) and not U.has_modifier_types(store, v, MOD_TYPE_PROTECTION)
		end)

		if towers then
			for _, t in ipairs(towers) do
				local m = E:create_entity(this.claw_stun_mod_t)

				m.modifier.target_id = t.id
				m.modifier.source_id = this.id

				queue_insert(store, m)

				stuns = stuns + 1
			end
		end

		y_body_recover()
	end

	local function lava_safe(pi, ni)
		local sp = P.paths[pi] and P.paths[pi][1]

		if not sp or #sp < 2 then
			return false
		end

		local a, b = sp[1], sp[2]
		local spacing = math.sqrt((a.x - b.x) * (a.x - b.x) + (a.y - b.y) * (a.y - b.y))

		return (#sp - ni) * spacing >= this.lava_ball.exit_safezone
	end

	local function lava_node_onscreen(pi, ni)
		local n = P.paths[pi][1][ni]

		return n.x > 40 and n.x < 984 and n.y > 60 and n.y < 700
	end

	local function find_lava_unit_nodes(area)
		local result = {}
		local lb = this.lava_ball
		local units = U.find_soldiers_in_range(store.entities, area.pos, 0, area.range, 0, bor(F_ENEMY))

		if not units then
			return result
		end

		for _, u in ipairs(units) do
			local nodes = P:nearest_nodes(u.pos.x, u.pos.y, lb.paths)

			if #nodes > 0 then
				local pi, spi, ni, dist = unpack(nodes[1])

				if dist and dist <= lb.unit_snap_radius and P:is_path_active(pi) and lava_safe(pi, ni) and lava_node_onscreen(pi, ni) then
					local n = P.paths[pi][1][ni]

					table.insert(result, {
						pi = pi,
						ni = ni,
						pos = V.v(n.x, n.y)
					})
				end
			end
		end

		return result
	end

	local function random_lava_node(area)
		local lb = this.lava_ball
		local candidates = {}

		for _, pi in ipairs(lb.paths) do
			local sp = P:is_path_active(pi) and P.paths[pi] and P.paths[pi][1]

			if sp then
				for ni = 1, #sp do
					if U.is_inside_ellipse(sp[ni], area.pos, area.range) and lava_safe(pi, ni) and lava_node_onscreen(pi, ni) then
						table.insert(candidates, {
							pi = pi,
							ni = ni,
							pos = V.v(sp[ni].x, sp[ni].y)
						})
					end
				end
			end
		end

		if #candidates == 0 then
			return nil
		end

		return candidates[math.random(#candidates)]
	end

	local function y_cast_lava_ball(cmd)
		local lb = this.lava_ball

		S:queue(this.lava_cast_sound, this.lava_cast_sound_frame and {
			delay = fts(this.lava_cast_sound_frame)
		} or nil)
		U.animation_start(body, this.throw_animation, nil, store.tick_ts, false)

		local count = cmd.count and cmd.count > 0 and cmd.count or lb.count
		local area = lb.areas[cmd.area]
		local unit_nodes = table.random_order(find_lava_unit_nodes(area)) or {}
		local from = V.v(this.pos.x + this.throw_offset.x, this.pos.y + this.throw_offset.y)
		local targeted = 0
		local impacts = {}

		for i = 1, count do
			local target = table.remove(unit_nodes, 1)

			if target then
				targeted = targeted + 1
			else
				target = random_lava_node(area)
			end

			if target then
				target.ft = V.dist(from.x, from.y, target.pos.x, target.pos.y) / lb.speed

				table.insert(impacts, target)
			end
		end

		local events = {}

		for _, s in ipairs(this.throw_shakes) do
			table.insert(events, {
				time = math.min(s.time, this.throw_hit_time),
				shake = s
			})
		end

		for i, im in ipairs(impacts) do
			local t_impact = this.throw_hit_time + (i - 1) * fts(2) + im.ft
			local t_show = math.min(math.max(0, t_impact - lb.target_warn_time), this.throw_hit_time)

			table.insert(events, {
				time = t_show,
				impact = im,
				duration = t_impact - t_show
			})
		end

		table.sort(events, function(a, b)
			return a.time < b.time
		end)

		local elapsed = 0

		for _, ev in ipairs(events) do
			U.y_wait(store, ev.time - elapsed, function()
				return this._abort
			end)

			if this._abort then
				U.animation_start(body, "idle", nil, store.tick_ts, true, nil, true)

				return
			end

			elapsed = ev.time

			if ev.shake then
				screen_shake(ev.shake)
			else
				local marker = E:create_entity(this.bullet_target_t)

				marker.pos = V.vclone(ev.impact.pos)
				marker.render.sprites[1].ts = store.tick_ts
				marker.duration = ev.duration

				queue_insert(store, marker)
			end
		end

		U.y_wait(store, this.throw_hit_time - elapsed, function()
			return this._abort
		end)

		if this._abort then
			U.animation_start(body, "idle", nil, store.tick_ts, true, nil, true)

			return
		end

		S:queue(this.throw_sound)

		local max_ft = 0

		for _, im in ipairs(impacts) do
			local shadow = E:create_entity(this.lava_shadow_t)

			shadow.pos = V.vclone(im.pos)
			shadow.render.sprites[1].ts = store.tick_ts
			shadow.tween.props[1].keys[2][1] = im.ft

			queue_insert(store, shadow)

			local ball = E:create_entity(this.lava_ball_t)

			ball.pos = V.vclone(from)
			ball.bullet.from = V.vclone(from)
			ball.bullet.to = V.vclone(im.pos)
			ball.bullet.flight_time = im.ft
			ball.bullet.source_id = this.id
			ball.spawn_data = im

			queue_insert(store, ball)

			max_ft = math.max(max_ft, im.ft)

			U.y_wait(store, fts(2))
		end

		if #impacts > 0 then
			U.y_wait(store, max_ft)

			for _, im in ipairs(impacts) do
				local sfx = E:create_entity(this.lava_spawn_fx)

				sfx.pos = V.vclone(im.pos)
				sfx.render.sprites[1].ts = store.tick_ts

				queue_insert(store, sfx)

				if not U.is_seen(store, lb.spawn_template) then
					signal.emit("wave-notification", "icon", lb.spawn_template)
					U.mark_seen(store, lb.spawn_template)
				end

				local e = E:create_entity(lb.spawn_template)

				e.play_spawn_animation = true
				e.die_after_spawn = im.die_after_spawn
				e.nav_path.pi = im.pi
				e.nav_path.spi = 1
				e.nav_path.ni = im.ni
				e.pos.x, e.pos.y = im.pos.x, im.pos.y

				if e.enemy then
					e.enemy.gold = 0
				end

				queue_insert(store, e)
			end

			local pis = {}

			for _, im in ipairs(impacts) do
				table.insert(pis, im.pi)
			end

			log.debug("stage_18 moloch: lava ball x%s (%s elementales, %s sobre unidades, paths %s)", count, #impacts, targeted, table.concat(pis, ","))
		else
			log.debug("stage_18 moloch: lava ball sin nodos validos")
		end

		y_body_recover()
	end

	local function y_cast_hellspawn(cmd)
		local hb = this.hellspawn_boost

		y_body_cast(this.hellspawn_cast_sound, this.yell_animation, this.yell_shake.time, this.yell_sound_frame)
		screen_shake(this.yell_shake)
		U.y_wait(store, this.yell_hit_time - this.yell_shake.time)

		local targets = table.filter(store.entities, function(_, v)
			return v.enemy and v.unit and v.health and not v.health.dead and v.vis and not U.flag_has(v.vis.flags, F_FLYING) and table.contains(hb.allowed_templates, v.template_name)
		end)
		local count = 0

		if targets then
			for _, e in ipairs(targets) do
				local m = E:create_entity(this.hellspawn_mod_t)

				m.modifier.target_id = e.id
				m.modifier.source_id = this.id

				if cmd.duration and cmd.duration > 0 then
					m.modifier.duration = cmd.duration
				end

				queue_insert(store, m)

				count = count + 1
			end
		end

		log.debug("stage_18 moloch: hellspawn boost a %s demonios", count)
		y_body_recover()
	end

	U.y_wait(store, 1e+99, function()
		return this._appear
	end)

	local fx = E:create_entity(this.appear_fx)

	fx.pos = V.vclone(this.pos)
	fx.render.sprites[1].ts = store.tick_ts

	queue_insert(store, fx)
	S:queue(this.appear_sound)

	for _, name in ipairs(this.masks_off_on_appear or {}) do
		for _, e in pairs(store.entities) do
			if e.template_name == name or e.template_name == "decal_nightfall_overlay" and e.hide_from == name then
				queue_remove(store, e)
			end
		end
	end

	local mascara = E:create_entity(this.mascara_fondo_decal_t)

	queue_insert(store, mascara)

	body = E:create_entity(this.body_decal_t)
	body.pos = V.vclone(this.pos)
	body.render.sprites[1].ts = store.tick_ts
	body.render.sprites[2].ts = store.tick_ts
	body.render.sprites[3].ts = store.tick_ts

	queue_insert(store, body)
	U.animation_start(body, this.appear_animation, nil, store.tick_ts, false)

	if this.appear_roar_sound then
		S:queue(this.appear_roar_sound, {
			delay = fts(this.appear_roar_frame)
		})
	end

	local events = {}

	for _, s in ipairs(this.appear_shakes) do
		table.insert(events, {
			time = s.time,
			shake = s
		})
	end

	table.insert(events, {
		mascara = true,
		time = this.mascara_time
	})
	table.insert(events, {
		camino = true,
		time = this.camino_time
	})
	table.sort(events, function(a, b)
		return a.time < b.time
	end)

	local elapsed = 0

	for _, ev in ipairs(events) do
		U.y_wait(store, ev.time - elapsed)

		elapsed = ev.time

		if ev.shake then
			screen_shake(ev.shake)
		elseif ev.mascara then
			mascara.render.sprites[1].hidden = false
		elseif ev.camino then
			local camino = E:create_entity(this.camino_decal_t)

			queue_insert(store, camino)

			mascara.render.sprites[2].hidden = false
		end
	end

	U.y_animation_wait(body)

	if math.random() < 0.5 then
		U.animation_start(body, "idle", nil, store.tick_ts, true, nil, true)
	else
		U.animation_start(body, "idle2", nil, store.tick_ts, false)
	end

	log.debug("stage_18 moloch: aparece (wave %s)", store.wave_group_number)

	while true do
		local s1 = body.render.sprites[1]

		if s1.name == "idle2" and U.animation_finished(body) then
			U.animation_start(body, "idle", nil, store.tick_ts, true)
		elseif s1.name == "idle" and s1.sync_flag and math.random() < this.idle2_chance then
			U.animation_start(body, "idle2", nil, store.tick_ts, false)
		end

		local cmd = table.remove(this._queue, 1)

		if cmd and not this._abort then
			this._casting = true

			if cmd.skill == "claw_slam" then
				y_cast_claw_slam()
			elseif cmd.skill == "lava_ball" then
				y_cast_lava_ball(cmd)
			elseif cmd.skill == "hellspawn_boost" then
				y_cast_hellspawn(cmd)
			end

			this._casting = false

			U.y_wait(store, this.global_cooldown)
		end

		coroutine.yield()
	end
end

scripts.tower_holder_pillar_terrain_2_1 = {}

function scripts.tower_holder_pillar_terrain_2_1.e_insert(this, store)
	local r = E:create_entity("editor_pillar_rally_point")

	queue_insert(store, r)

	r.tower_id = this.id
	this.editor.pillar_point_id = r.id

	if this.pillar.pillar_damage_center and this.pillar.pillar_damage_center.x ~= 0 and this.pillar.pillar_damage_center.y ~= 0 then
		r.pos = this.pillar.pillar_damage_center
	else
		r.pos = V.v(this.pos.x + 50, this.pos.y + 50)
		this.pillar.pillar_damage_center = r.pos
	end

	local r = E:create_entity("editor_rally_point")

	queue_insert(store, r)

	r.tower_id = this.id
	this.editor.rally_point_id = r.id

	if this.pillar.default_rally_pos and this.pillar.default_rally_pos.x ~= 0 and this.pillar.default_rally_pos.y ~= 0 then
		r.pos = this.pillar.default_rally_pos
	else
		r.pos = V.v(this.pos.x + 50, this.pos.y + 50)
		this.pillar.default_rally_pos = r.pos
	end

	if not this.pillar.holder_id then
		this.pillar.holder_id = tostring(this.id)
	end

	if this.barrack then
		this.barrack.rally_pos = r.pos
	end

	return true
end

function scripts.tower_holder_pillar_terrain_2_1.e_remove(this, store)
	local r = store.entities[this.editor.rally_point_id]

	if r then
		queue_remove(store, r)
	end

	local p = store.entities[this.editor.pillar_point_id]

	if p then
		queue_remove(store, p)
	end

	return true
end

function scripts.tower_holder_pillar_terrain_2_1.update(this, store)
	local tap_count = 0
	local last_tap, crumble
	local wait = math.random(this.random_min, this.random_max)
	local start_ts = store.tick_ts

	while wait > store.tick_ts - start_ts do
		if this.ui.clicked then
			goto label_1616_0
		end

		coroutine.yield()
	end

	U.animation_start(this, "idle", nil, store.tick_ts, true, 1, true)

	::label_1616_0::

	while true do
		::label_1616_1::

		if this.ui.clicked then
			this.ui.clicked = false
			tap_count = tap_count + 1
			crumble = tap_count >= this.pillar.taps_to_break

			if tap_count == 1 then
				S:queue(this.sound_events.tap)
				U.animation_start(this, "tap", nil, store.tick_ts, false, 1)

				while not U.animation_finished(this, 1, 1) do
					if this.ui.clicked then
						goto label_1616_1
					end

					coroutine.yield()
				end
			elseif not crumble then
				if tap_count == this.pillar.taps_to_break - 1 then
					S:queue(this.sound_events.pre_crumble)
				else
					S:queue(this.sound_events.tap)
				end

				U.animation_start(this, "tap_" .. tap_count, nil, store.tick_ts, false, 1)

				while not U.animation_finished(this, 1, 1) do
					if this.ui.clicked then
						goto label_1616_1
					end

					coroutine.yield()
				end
			end

			if crumble then
				S:queue(this.sound_events.crumble)

				local dmg_visuals = E:create_entity(this.pillar.explosion_t)

				dmg_visuals.pos = V.vclone(this.pos)
				dmg_visuals.render.sprites[1].ts = store.tick_ts

				queue_insert(store, dmg_visuals)
				coroutine.yield()

				this.render.sprites[1].hidden = true

				local holder = E:create_entity(this.pillar.holder_on_break)

				holder.pos = V.vclone(this.pos)
				holder.tower.terrain_style = this.pillar.terrain_style
				holder.tower.default_rally_pos = this.pillar.default_rally_pos
				holder.tower.holder_id = this.pillar.holder_id
				holder.ui.nav_mesh_id = this.ui.nav_mesh_id
				holder.tower.level = 1
				holder.tower.can_be_mod = false

				queue_insert(store, holder)
				signal.emit("tower-removed", this, holder)
				U.y_wait(store, this.pillar.hit_time)

				local dmg_aura = E:create_entity(this.pillar.damage_aura_t)

				dmg_aura.pos = this.pillar.pillar_damage_center

				queue_insert(store, dmg_aura)

				local decal = E:create_entity(this.pillar.decal_t)

				decal.pos = this.pillar.pillar_damage_center

				queue_insert(store, decal)

				break
			else
				U.animation_start(this, "idle_" .. tap_count + 1, nil, store.tick_ts, true, 1)
			end
		end

		coroutine.yield()
	end

	U.y_animation_wait(this)
	queue_remove(store, this)
end

