scripts.controller_item_bomb = {}

function scripts.controller_item_bomb.can_fire_fn(this, x, y, store)
	return true
end

function scripts.controller_item_bomb.update(this, store)
	local animation = E:create_entity(this.decal_animation)

	animation.pos.x, animation.pos.y = this.pos.x, this.pos.y
	animation.render.sprites[1].ts = store.tick_ts
	animation.render.sprites[1].flip_x = animation.pos.x > 512

	queue_insert(store, animation)
	U.y_wait(store, fts(63))
	S:queue(this.sound_in)
	U.y_wait(store, fts(33))

	local extra_sounds = E:create_entity(this.extra_sounds_t)

	queue_insert(store, extra_sounds)

	if not features.censored_cn then
		signal.emit("fat-boy-explosion-sequence")
	end

	local shake = E:create_entity("aura_screen_shake")

	shake.aura.amplitude = 0.4
	shake.aura.duration = 3
	shake.aura.freq_factor = 2

	queue_insert(store, shake)

	local targets = table.filter(store.entities, function(k, v)
		return v.enemy and v.vis and v.health and not v.health.dead and band(v.vis.flags, this.vis_bans) == 0 and band(v.vis.bans, this.vis_flags) == 0 and (not this.allowed_templates or table.contains(this.allowed_templates, v.template_name)) and (not this.excluded_templates or not table.contains(this.excluded_templates, v.template_name))
	end)

	if targets and #targets > 0 then
		for i = #targets, 2, -1 do
			local j = math.random(i)

			targets[i], targets[j] = targets[j], targets[i]
		end

		local delay_between = 60 / #targets

		for _, enemy in ipairs(targets) do
			S:queue(this.sound_ashes)

			if band(enemy.vis.flags, F_FLYING) ~= 0 then
				local fx = E:create_entity(this.fx_instakill_air)

				fx.pos = V.vclone(enemy.pos)
				fx.pos.x, fx.pos.y = fx.pos.x + enemy.unit.hit_offset.x, fx.pos.y + enemy.unit.hit_offset.y
				fx.render.sprites[1].ts = store.tick_ts

				queue_insert(store, fx)
			else
				local fx = E:create_entity(this.fx_instakill_ground)

				fx.pos = V.vclone(enemy.pos)
				fx.render.sprites[1].ts = store.tick_ts

				queue_insert(store, fx)
			end

			enemy.health.ignore_damage = nil

			local d = E:create_entity("damage")

			d.source_id = this.id
			d.target_id = enemy.id
			d.value = math.random(this.damage_min, this.damage_max)

			if d.value > enemy.health.hp then
				d.damage_type = bor(DAMAGE_INSTAKILL, DAMAGE_NO_SPAWNS)
				enemy.unit.can_explode = false
				enemy.unit.death_animation = nil
				enemy.unit.hide_during_death = true
			else
				d.damage_type = DAMAGE_TRUE
			end

			queue_damage(store, d)
			U.y_wait(store, fts(math.random(delay_between / 2, delay_between * 2)))
		end
	end

	queue_remove(store, this)
end

scripts.controller_item_bomb_explosions = {}

function scripts.controller_item_bomb_explosions.update(this, store)
	local pp = this.possible_positions

	for i = #pp, 2, -1 do
