		pp[i], pp[j] = pp[j], pp[i]
	end

	for i = 1, this.amount_explosions do
		S:queue(this.sound_small_explosion)

		local xp = E:create_entity(this.decal_explosion)
		local j = i <= #pp and i or i % #pp + 1
		local p = pp[j]

		xp.pos.x, xp.pos.y = p.x, p.y
		xp.render.sprites[1].ts = store.tick_ts

		queue_insert(store, xp)
		U.y_wait(store, U.frandom(this.min_wait, this.max_wait))
	end

	queue_remove(store, this)
end

scripts.mod_fear = {}

function scripts.mod_fear.insert(this, store, script)
	local m = this.modifier
	local target = store.entities[m.target_id]

	if band(this.modifier.vis_flags, target.vis.bans) ~= 0 or band(this.modifier.vis_bans, target.vis.flags) ~= 0 then
		log.paranoid("mod %s cannot be applied to entity %s:%s because of vis flags/bans", this.template_name, target.id, target.template_name)

		return false
	end

	local i_speed = scripts.mod_slow.insert(this, store, script)

	target.nav_path.dir = -1
	this._old_enemy_update = target.main_script.update
	target.main_script.update = this.enemy_with_fear_update

	for i = #target.enemy.blockers, 1, -1 do
		local blocker_id = target.enemy.blockers[i]
		local blocker = store.entities[blocker_id]

		U.unblock_target(store, blocker)
		table.remove(target.enemy.blockers, i)
	end

	this._pushed_bans = U.push_bans(target.vis, F_BLOCK)

	return true
end

function scripts.mod_fear.update(this, store, script)
	local m = this.modifier

	this.modifier.ts = store.tick_ts

	local target = store.entities[m.target_id]

	if not target or not target.pos then
		queue_remove(store, this)

		return
	end

	this.pos = target.pos

	while true do
		target = store.entities[m.target_id]

		if not target or target.health.dead or target._end_fear or m.duration >= 0 and store.tick_ts - m.ts > m.duration or m.last_node and target.nav_path.ni > m.last_node then
			queue_remove(store, this)

			return
		end

		if this.render and m.use_mod_offset and target.unit.mod_offset then
			for i = 1, #this.render.sprites do
				local s = this.render.sprites[i]

				if not s.exclude_mod_offset then
					s.offset.x, s.offset.y = target.unit.mod_offset.x, target.unit.mod_offset.y
				end
			end
		end

		coroutine.yield()
	end
end

function scripts.mod_fear.remove(this, store, script)
	scripts.mod_slow.remove(this, store, script)

	local m = this.modifier
	local target = store.entities[m.target_id]

	if target then
		target.nav_path.dir = 1
		target.main_script.update = this._old_enemy_update

		if this._pushed_bans then
			U.pop_bans(target.vis, this._pushed_bans)

			this._pushed_bans = nil
		end
	end

	return true
end

scripts.enemy_with_fear = {}

function scripts.enemy_with_fear.update(this, store)
	local function walk_backwards()
		local terrain_type = band(GR:cell_type(this.pos.x, this.pos.y), bor(TERRAIN_WATER, TERRAIN_LAND))

		while true do
			if this.unit.is_stunned then
				return false
			end

			if this.health.dead then
				return false
			end

			local node_valid = P:is_node_valid(this.nav_path.pi, this.nav_path.ni)

			SU.y_enemy_walk_step(store, this)

			if terrain_type ~= band(GR:cell_type(this.pos.x, this.pos.y), bor(TERRAIN_WATER, TERRAIN_LAND)) then
				return false
			end

			coroutine.yield()
		end

		return true
	end

	while true do
		if this.health.dead then
			return
		end

		if this.unit.is_stunned then
			SU.y_enemy_stun(store, this)
		else
			local cont = walk_backwards(store, this)

			if not cont then
				this._end_fear = true
			end

			coroutine.yield()
		end
	end
end

scripts.controller_show_buy_available = {}

function scripts.controller_show_buy_available.update(this, store)
end

scripts.mod_buy_available = {}

function scripts.mod_buy_available.update(this, store)
	local sh = this.render.sprites[1]
	local t = store.entities[this.modifier.target_id]

	if not t then
		log.paranoid("mod_buy_available: No target, remove!")
		queue_remove(store, this)

		return
	end

	this.pos = t.pos
	sh.ts = store.tick_ts

	if t.ui and t.ui.hover_sprite_anchor then
		sh.anchor = t.ui.hover_sprite_anchor
	end

	if t.ui and t.ui.hover_sprite_scale then
		sh.scale = t.ui.hover_sprite_scale
	end

	if t.ui and t.ui.hover_sprite_offset then
		sh.offset = t.ui.hover_sprite_offset
	end

	while true do
		t = store.entities[this.modifier.target_id]

		if not t then
			log.paranoid("mod_buy_available: Tower removed, removing")
			queue_remove(store, this)

			return
		end

		local hidden = true

		if store.ephemeral.hide_buy_av then
			hidden = true

			log.paranoid("mod_buy_available: Tower %s:%s show buy disabled.", t.template_name, t.id)
		elseif t.tower.disable_spend_highlight then
			log.paranoid("mod_buy_available: Tower %s:%s disabled spend highlight: %s.", t.template_name, t.id, t.tower.disable_spend_highlight)

			hidden = true
		elseif t.repair and t.repair.active then
			log.paranoid("mod_buy_available: Tower %s:%s repair already on the way.", t.template_name, t.id)
		elseif t.repair and not t.repair.active then
			hidden = store.player_gold < t.repair.cost

			log.paranoid("mod_buy_available: Tower %s:%s repair, hide: %s, current gold: %s, repair_price: %s", t.template_name, t.id, hidden, store.player_gold, t.repair.cost)
		else
			if t.powers then
				local cheapest = 1e+99

				for k, v in pairs(t.powers) do
					if k ~= "ultimate" and v.level < #v.price and cheapest > v.price[v.level + 1] then
						cheapest = v.price[v.level + 1]
					end
				end

				hidden = cheapest > store.player_gold

				log.paranoid("mod_buy_available: Tower %s:%s power upgrade, hide: %s, current gold: %s, cheapest upg price: %s", t.template_name, t.id, hidden, store.player_gold, cheapest)

				goto label_1632_1
			end

			if t.user_selection and t.user_selection.allowed and t.attacks and #t.attacks.list > 0 then
				for i, a in ipairs(t.attacks.list) do
					if a.price then
						hidden = store.player_gold < a.price

						log.paranoid("mod_buy_available: Tower %s:%s buyable attack, hide: %s, attack id: %s, current gold: %s, attack_price: %s", t.template_name, t.id, hidden, i, store.player_gold, a.price)

						goto label_1632_1
					end
				end
			end

			if not t.tower_holder and t.tower.level and t.tower.level < 4 and (not t.tower.max_level or t.tower.level < t.tower.max_level) then
				local name = t.tower.override_next_level_e and t.tower.override_next_level_e or "tower_" .. t.tower.type .. "_lvl" .. t.tower.level + 1

				if type(name) == "table" and #name > 0 then
					for _, n in pairs(name) do
						local next = E:get_template(n)

						hidden = next and store.player_gold < next.tower.price or store.level.locked_towers and table.contains(store.level.locked_towers, n)
					end
				else
					local next = E:get_template(name)

					if not next then
						goto label_1632_0
					end

					hidden = next and store.player_gold < next.tower.price or store.level.locked_towers and table.contains(store.level.locked_towers, name)

					log.paranoid("mod_buy_available: Tower %s:%s upgrade to: %s, hide: %s, current gold: %s, upg_price: %s", t.template_name, t.id, next.template_name, hidden, store.player_gold, next.tower.price)
				end

				goto label_1632_1
			end

			::label_1632_0::

			if t.tower_holder and not t.tower_holder.blocked then
				hidden = store.player_gold < this.min_cost

				log.paranoid("mod_buy_available: Tower %s:%s unblocked, hide: %s, current gold: %s, min_cost: %s", t.template_name, t.id, hidden, store.player_gold, this.min_cost)
			elseif t.tower_holder and t.tower_holder.blocked then
				hidden = store.player_gold < t.tower_holder.unblock_price

				log.paranoid("mod_buy_available: Tower %s:%s blocked, hide: %s, current gold: %s, unblock_price: %s", t.template_name, t.id, hidden, store.player_gold, t.tower_holder.unblock_price)
			end
		end

		::label_1632_1::

		if t.ui and not t.ui.can_click then
			hidden = true
		end

		this.render.sprites[1].hidden = hidden

		U.y_wait(store, 0.2)
	end
end

scripts.tower_archer = {}

function scripts.tower_archer.insert(this, store, script)
	return true
end

function scripts.tower_archer.update(this, store, script)
	local at = this.attacks
	local a = this.attacks.list[1]
	local shooter_sprite_ids = table.slice({
		3,
		4,
		5
	}, 1, #a.bullet_start_offset)
	local last_target_pos = V.v(0, 0)

	a.ts = store.tick_ts

	while true do
		local enemy

		if this.tower.blocked then
			-- block empty
		elseif store.tick_ts - a.ts < a.cooldown then
			-- block empty
		else
			enemy = U.find_foremost_enemy(store.entities, tpos(this), 0, at.range, false, a.vis_flags, a.vis_bans)

			if enemy then
				a.ts = store.tick_ts
				a.count = a.count + 1

				local shooter_idx = a.count % #a.bullet_start_offset + 1
				local shooter_sid = shooter_sprite_ids[shooter_idx]
				local start_offset = a.bullet_start_offset[shooter_idx]
				local s = this.render.sprites[shooter_sid]
				local an, af = U.animation_name_facing_point(this, "shoot", enemy.pos, shooter_sid, start_offset)

				U.animation_start(this, an, af, store.tick_ts, 1, shooter_sid)

				last_target_pos = enemy.pos

				while store.tick_ts - a.ts < a.shoot_time do
					coroutine.yield()
				end

				enemy = U.find_foremost_enemy(store.entities, tpos(this), 0, at.range, false, a.vis_flags, a.vis_bans)

				if enemy then
					last_target_pos = enemy.pos

					local an, af = U.animation_name_facing_point(this, "shoot", enemy.pos, shooter_sid, start_offset)

					this.render.sprites[shooter_sid].flip_x = af

					local bullet = E:create_entity(a.bullet)

					bullet.bullet.damage_factor = this.tower.damage_factor

					if IS_KR6 then
						bullet.pos.x, bullet.pos.y = this.pos.x + s.offset.x + start_offset.x * (af and -1 or 1), this.pos.y + s.offset.y + start_offset.y
					else
						bullet.pos.x, bullet.pos.y = this.pos.x + start_offset.x * (af and -1 or 1), this.pos.y + start_offset.y
					end

					bullet.bullet.from = V.vclone(bullet.pos)
					bullet.bullet.to = V.v(enemy.pos.x + enemy.unit.hit_offset.x, enemy.pos.y + enemy.unit.hit_offset.y)
					bullet.bullet.target_id = enemy.id
					bullet.bullet.source_id = this.id

					if bullet.bullet.flight_time_min and bullet.bullet.flight_time_factor then
						local dist = V.dist(bullet.bullet.to.x, bullet.bullet.to.y, bullet.bullet.from.x, bullet.bullet.from.y)

						bullet.bullet.flight_time = bullet.bullet.flight_time_min + dist / at.range * bullet.bullet.flight_time_factor
					end

					local u = UP:get_upgrade("archer_el_obsidian_heads")

					if u and enemy.health and enemy.health.armor == 0 then
						bullet.bullet.damage_min = bullet.bullet.damage_max
					end

					u = UP:get_upgrade("archer_precision")

					if u and math.random() < u.chance then
						bullet.bullet.damage_min = bullet.bullet.damage_min * u.damage_factor
						bullet.bullet.damage_max = bullet.bullet.damage_max * u.damage_factor
						bullet.bullet.pop = {
							"pop_crit"
						}
						bullet.bullet.pop_conds = DR_DAMAGE
					end

					queue_insert(store, bullet)

					u = UP:get_upgrade("archer_twin_shot")

					if u and math.random() < u.chance then
						local b2 = E:clone_entity(bullet)

						b2.bullet.flight_time = b2.bullet.flight_time - 1 / FPS

						queue_insert(store, b2)

						bullet.bullet.flight_time = bullet.bullet.flight_time + 1 / FPS
					end
				end

				while not U.animation_finished(this, shooter_sid) do
					coroutine.yield()
				end

				an, af = U.animation_name_facing_point(this, "idle", last_target_pos, shooter_sid, start_offset)

				U.animation_start(this, an, af, store.tick_ts, -1, shooter_sid)
			end

			if store.tick_ts - a.ts > this.tower.long_idle_cooldown then
				for _, sid in pairs(shooter_sprite_ids) do
					local an, af = U.animation_name_facing_point(this, "idle", this.tower.long_idle_pos, sid)

					U.animation_start(this, an, af, store.tick_ts, -1, sid)
				end
			end
		end

		coroutine.yield()
	end
end

scripts.tower_ranger_kr1 = {}

function scripts.tower_ranger_kr1.update(this, store)
	local shooter_sids = {
		3,
		4
	}
	local shooter_idx = 2
	local druid_sid = 5
	local a = this.attacks
	local aa = this.attacks.list[1]
	local pow_p = this.powers.poison
	local pow_t = this.powers.thorn

	aa.ts = store.tick_ts

	local function shot_animation(attack, shooter_idx, enemy)
		local ssid = shooter_sids[shooter_idx]
		local soffset = this.render.sprites[ssid].offset
		local s = this.render.sprites[ssid]
		local an, af = U.animation_name_facing_point(this, attack.animation, enemy.pos, ssid, soffset)

		U.animation_start(this, an, af, store.tick_ts, 1, ssid)

		return U.animation_name_facing_point(this, "idle", enemy.pos, ssid, soffset)
	end

	local function shot_bullet(attack, shooter_idx, enemy, level)
		local ssid = shooter_sids[shooter_idx]
		local shooting_up = tpos(this).y < enemy.pos.y
		local shooting_right = tpos(this).x < enemy.pos.x
		local soffset = this.render.sprites[ssid].offset
		local boffset = attack.bullet_start_offset[shooting_up and 1 or 2]
		local b = E:create_entity(attack.bullet)

		b.pos.x = this.pos.x + soffset.x + boffset.x * (shooting_right and 1 or -1)
		b.pos.y = this.pos.y + soffset.y + boffset.y
		b.bullet.from = V.vclone(b.pos)
		b.bullet.to = V.v(enemy.pos.x + enemy.unit.hit_offset.x, enemy.pos.y + enemy.unit.hit_offset.y)
		b.bullet.target_id = enemy.id
		b.bullet.level = level
		b.bullet.damage_factor = this.tower.damage_factor
		b.bullet.mod = pow_p.level > 0 and pow_p.mod
		b.bullet.hit_fx = pow_p.level > 0 and pow_p.hit_fx
		b.bullet.particles_name = pow_p.level > 0 and pow_p.particles
		b.render.sprites[1].name = pow_p.level > 0 and pow_p.sprite_name or b.render.sprites[1].name
		b.bullet.miss_decal = pow_p.level > 0 and pow_p.miss_name or b.bullet.miss_decal

		local u = UP:get_upgrade("archer_precision")

		if u and math.random() < u.chance then
			b.bullet.damage_min = b.bullet.damage_min * u.damage_factor
			b.bullet.damage_max = b.bullet.damage_max * u.damage_factor
			b.bullet.pop = {
				"pop_crit"
			}
			b.bullet.pop_conds = DR_DAMAGE
		end

		queue_insert(store, b)
	end

	local function check_upgrades()
		for k, pow in pairs(this.powers) do
			if pow.changed then
				pow.changed = nil

				if pow == pow_t and this.render.sprites[druid_sid].hidden then
					this.render.sprites[druid_sid].hidden = false

					local ta = E:create_entity(pow_t.aura)

					ta.aura.source_id = this.id
					ta.pos = tpos(this)

					queue_insert(store, ta)
				end
			end
		end
	end

	while true do
		if this.tower.blocked then
			coroutine.yield()
		else
			check_upgrades()

			if store.tick_ts - aa.ts > aa.cooldown then
				local enemy, enemies = U.find_foremost_enemy(store.entities, tpos(this), 0, a.range, false, aa.vis_flags, aa.vis_bans)

				if not enemy then
					-- block empty
				else
					if pow_p.level > 0 then
						local poisonable = table.filter(enemies, function(_, e)
							return not U.flag_has(e.vis.bans, F_POISON) and not U.has_modifiers(store, e, pow_p.mod)
						end)

						if #poisonable > 0 then
							enemy = poisonable[1]
						end
					end

					aa.ts = store.tick_ts
					shooter_idx = km.zmod(shooter_idx + 1, #shooter_sids)

					local idle_an, idle_af = shot_animation(aa, shooter_idx, enemy)

					U.y_wait(store, aa.shoot_time, function()
						check_upgrades()

						return false
					end)

					if V.dist(tpos(this).x, tpos(this).y, enemy.pos.x, enemy.pos.y) <= a.range then
						shot_bullet(aa, shooter_idx, enemy, pow_p.level)
					end

					while not U.animation_finished(this, shooter_sids[shooter_idx]) do
						coroutine.yield()
						check_upgrades()
					end

					U.animation_start(this, idle_an, idle_af, store.tick_ts, false, shooter_sids[shooter_idx])
				end
			end

			if store.tick_ts - aa.ts > this.tower.long_idle_cooldown then
				for _, sid in pairs(shooter_sids) do
					local an, af = U.animation_name_facing_point(this, "idle", this.tower.long_idle_pos, sid)

					U.animation_start(this, an, af, store.tick_ts, -1, sid)
				end
			end

			coroutine.yield()
		end
	end
end

scripts.tower_musketeer = {}

function scripts.tower_musketeer.update(this, store)
	local shooter_sids = {
		3,
		4
	}
	local shooter_idx = 2
	local a = this.attacks
	local aa = this.attacks.list[1]
	local asn = this.attacks.list[2]
	local asi = this.attacks.list[3]
	local ash = this.attacks.list[4]
	local pow_sn = this.powers.sniper
	local pow_sh = this.powers.shrapnel

	aa.ts = store.tick_ts

	local function shot_animation(attack, shooter_idx, pos, animation, posfix)
		local ssid = shooter_sids[shooter_idx]
		local soffset = this.render.sprites[ssid].offset
		local s = this.render.sprites[ssid]
		local an, af, ai = U.animation_name_facing_point(this, animation or attack.animation, pos, ssid, soffset)

		if posfix then
			an = an .. "_" .. posfix
		end

		local px = this.shooter_prefix_right
		local off_x = 0

		if shooter_idx == 1 then
			px = af and this.shooter_prefix_right or this.shooter_prefix_left
			off_x = af and -this.shooter_offset_right_x or -this.shooter_offset_left_x
		elseif shooter_idx == 2 then
			px = af and this.shooter_prefix_left or this.shooter_prefix_right
			off_x = af and this.shooter_offset_left_x or this.shooter_offset_right_x
		end

		this.render.sprites[shooter_sids[shooter_idx]].prefix = px
		this.render.sprites[shooter_sids[shooter_idx]].offset.x = off_x
		this.render.sprites[shooter_sids[1]].draw_order = nil
		this.render.sprites[shooter_sids[2]].draw_order = nil

		U.animation_start(this, an, af, store.tick_ts, 1, ssid)

		return an, af, ai
	end

	local function shot_bullet(attack, shooter_idx, ani_idx, enemy, level, shoot_pos, head)
		local ssid = shooter_sids[shooter_idx]
		local shooting_right = tpos(this).x < shoot_pos.x
		local soffset = this.render.sprites[ssid].offset
		local boffset = attack.bullet_start_offset[ani_idx]
		local hoffset = head and enemy.unit.head_offset and enemy.unit.head_offset or enemy.unit.hit_offset
		local b = E:create_entity(attack.bullet)

		b.pos.x = this.pos.x + soffset.x + boffset.x * (shooting_right and 1 or -1)
		b.pos.y = this.pos.y + soffset.y + boffset.y
		b.bullet.from = V.vclone(b.pos)
		b.bullet.to = V.v(shoot_pos.x + hoffset.x * (enemy.render.sprites[1].flip_x and -1 or 1), shoot_pos.y + hoffset.y)
		b.bullet.target_id = enemy.id
		b.bullet.source_id = this.id
		b.bullet.level = level
		b.bullet.damage_factor = this.tower.damage_factor

		if attack == asn then
			local extra_damage = pow_sn.damage_factor_inc * pow_sn.level * enemy.health.hp_max

			b.bullet.damage_max = b.bullet.damage_max + extra_damage
			b.bullet.damage_min = b.bullet.damage_min + extra_damage
		end

		queue_insert(store, b)

		return b
	end

	local function check_power_upgrades()
		for k, pow in pairs(this.powers) do
			if pow.changed then
				pow.changed = nil

				if pow.level == 1 then
					for _, ax in pairs(a.list) do
						if ax.power_name and this.powers[ax.power_name] == pow then
							ax.ts = store.tick_ts - ax.cooldown
						end
					end
				end

				if pow == pow_sn then
					asi.chance = pow_sn.instakill_chance_inc * pow_sn.level
				end
			end
		end
	end

	local function wait_animation_apply_upgrades(entity, idx, times)
		while not U.animation_finished(entity, idx, times) do
			check_power_upgrades()
			coroutine.yield()
		end
	end

	while true do
		if this.tower.blocked then
			coroutine.yield()
		else
			check_power_upgrades()

			if pow_sn.level > 0 then
				for _, ax in pairs({
					asi,
					asn
				}) do
					if (ax.chance == 1 or math.random() < ax.chance) and store.tick_ts - ax.ts > ax.cooldown then
						local enemy, _ = U.find_foremost_enemy(store.entities, tpos(this), 0, ax.range, 0, ax.vis_flags, ax.vis_bans)

						if not enemy then
							break
						end

						for _, axx in pairs({
							aa,
							asi,
							asn
						}) do
							axx.ts = store.tick_ts
						end

						shooter_idx = km.zmod(shooter_idx + 1, #shooter_sids)

						local seeker_idx = km.zmod(shooter_idx + 1, #shooter_sids)
						local an, af, ai = shot_animation(ax, shooter_idx, enemy.pos, nil, "in")

						shot_animation(ax, seeker_idx, enemy.pos, ax.animation_seeker, "in")

						local mod = E:create_entity(ax.mod)

						mod.modifier.target_id = enemy.id
						mod.render.sprites[1].ts = store.tick_ts

						queue_insert(store, mod)

						local start_ts = store.tick_ts

						U.y_animation_wait(this, shooter_sids[shooter_idx])

						while store.tick_ts - start_ts < ax.shoot_time do
							check_power_upgrades()
							shot_animation(ax, shooter_idx, enemy.pos, nil, "loop")
							shot_animation(ax, seeker_idx, enemy.pos, ax.animation_seeker, "loop")
							coroutine.yield()
						end

						an, af, ai = shot_animation(ax, shooter_idx, enemy.pos, nil, "out")

						shot_animation(ax, seeker_idx, enemy.pos, ax.animation_seeker, "out")

						if V.dist(tpos(this).x, tpos(this).y, enemy.pos.x, enemy.pos.y) <= ax.range then
							shot_bullet(ax, shooter_idx, ai, enemy, pow_sn.level, enemy.pos, true)
						end

						local shotgun_template = E:get_template(ax.bullet)

						U.y_wait(store, shotgun_template.hit_delay)

						if mod then
							queue_remove(store, mod)
						end

						wait_animation_apply_upgrades(this, shooter_sids[shooter_idx])
					end
				end
			end

			if pow_sh.level > 0 and store.tick_ts - ash.ts > ash.cooldown then
				local enemy, _, pred_pos = U.find_foremost_enemy(store.entities, tpos(this), 0, ash.range, ash.shoot_time, ash.vis_flags, ash.vis_bans)

				if not enemy then
					-- block empty
				else
					ash.ts = store.tick_ts
					aa.ts = store.tick_ts
					shooter_idx = km.zmod(shooter_idx + 1, #shooter_sids)

					local fuse_idx = km.zmod(shooter_idx + 1, #shooter_sids)
					local ssid = shooter_sids[shooter_idx]
					local fsid = shooter_sids[fuse_idx]
					local an, af, ai = shot_animation(ash, shooter_idx, pred_pos)

					shot_animation(ash, fuse_idx, pred_pos, ash.animation_seeker)

					this.render.sprites[ssid].draw_order = 5

					U.y_wait(store, ash.shoot_time, function()
						check_power_upgrades()

						return false
					end)

					local shooting_right = tpos(this).x < enemy.pos.x
					local soffset = this.render.sprites[ssid].offset
					local boffset = ash.bullet_start_offset[ai]
					local dest_pos = P:predict_enemy_pos(enemy, ash.node_prediction)
					local src_pos = V.v(this.pos.x + soffset.x + boffset.x * (shooting_right and 1 or -1), this.pos.y + soffset.y + boffset.y)

					for i = 1, ash.loops do
						local b = E:create_entity(ash.bullet)

						b.bullet.flight_time = U.frandom(b.bullet.flight_time_min, b.bullet.flight_time_max)
						b.pos = V.vclone(src_pos)
						b.bullet.from = V.vclone(src_pos)
						b.bullet.to = U.point_on_ellipse(dest_pos, U.frandom(ash.min_spread, ash.max_spread), (i - 1) * 2 * math.pi / ash.loops)
						b.bullet.level = pow_sh.level
						b.bullet.source_id = this.id

						queue_insert(store, b)
					end

					wait_animation_apply_upgrades(this, shooter_sids[shooter_idx])

					this.render.sprites[ssid].draw_order = nil
				end
			end

			if store.tick_ts - aa.ts > aa.cooldown then
				local enemy, enemies, pred_pos = U.find_foremost_enemy(store.entities, tpos(this), 0, a.range, aa.shoot_time, aa.vis_flags, aa.vis_bans)

				if not enemy then
					-- block empty
				else
					aa.ts = store.tick_ts
					shooter_idx = km.zmod(shooter_idx + 1, #shooter_sids)

					local an, af, ai = shot_animation(aa, shooter_idx, pred_pos, nil)

					if af then
						this.render.sprites[4].draw_order = 5
					else
						this.render.sprites[3].draw_order = 5
					end

					U.y_wait(store, aa.shoot_time, function()
						check_power_upgrades()

						return false
					end)

					if V.dist(tpos(this).x, tpos(this).y, enemy.pos.x, enemy.pos.y) <= a.range then
						shot_bullet(aa, shooter_idx, ai, enemy, 0, pred_pos)
					end

					wait_animation_apply_upgrades(this, shooter_sids[shooter_idx])
				end
			end

			if store.tick_ts - aa.ts > this.tower.long_idle_cooldown then
				for _, sid in pairs(shooter_sids) do
					local an, af = U.animation_name_facing_point(this, "idle", this.tower.long_idle_pos, sid)
					local px = this.shooter_prefix_right
					local off_x = 0

					if sid == 3 then
						px = af and this.shooter_prefix_right or this.shooter_prefix_left
						off_x = af and -this.shooter_offset_right_x or -this.shooter_offset_left_x
					elseif sid == 4 then
						px = af and this.shooter_prefix_left or this.shooter_prefix_right
						off_x = af and this.shooter_offset_left_x or this.shooter_offset_right_x
					end

					this.render.sprites[sid].prefix = px
					this.render.sprites[sid].offset.x = off_x

					U.animation_start(this, an, af, store.tick_ts, -1, sid)
				end
			end

			coroutine.yield()
		end
	end
end

scripts.mod_thorn = {}

function scripts.mod_thorn.queue(this, store, insertion)
	local target = store.entities[this.modifier.target_id]

	if not target then
		return
	end

	if insertion then
		log.debug("%s (%s) queue/insertion", this.template_name, this.id)

		if U.flags_pass(target.vis, this.modifier) then
			this._pushed_bans = U.push_bans(target.vis, F_THORN)
		end
	else
		log.debug("%s (%s) queue/removal", this.template_name, this.id)

		if this._pushed_bans then
			U.pop_bans(target.vis, this._pushed_bans)

			this._pushed_bans = nil
		end
	end
end

function scripts.mod_thorn.dequeue(this, store, insertion)
	local target = store.entities[this.modifier.target_id]

	if not target then
		return
	end

	if insertion then
		log.debug("%s (%s) dequeue/insertion", this.template_name, this.id)

		if this._pushed_bans then
			U.pop_bans(target.vis, this._pushed_bans)

			this._pushed_bans = nil
		end
	end
end

function scripts.mod_thorn.insert(this, store)
	local m = this.modifier
	local target = store.entities[m.target_id]
	local s = this.render.sprites[1]

	s.ts = store.tick_ts

	if target and target.health and not target.health.dead and this._pushed_bans ~= nil and (not target.enemy.counts.mod_thorn or target.enemy.counts.mod_thorn < this.max_times_applied) then
		SU.stun_inc(target)

		s.prefix = s.size_prefixes[target.unit.size]
		s.scale = s.size_scales[target.unit.size]

		return true
	else
		return false
	end
end

function scripts.mod_thorn.remove(this, store)
	local target = store.entities[this.modifier.target_id]

	if target then
		target.health.ignore_damage = false

		SU.stun_dec(target)
	end

	return true
end

function scripts.mod_thorn.update(this, store)
	local hit_ts
	local m = this.modifier
	local target = store.entities[m.target_id]

	if not target or not target.health or target.health.dead then
		queue_remove(store, this)

		return
	end

	if this.max_times_applied then
		if not target.enemy.counts.mod_thorn then
			target.enemy.counts.mod_thorn = 0
		end

		target.enemy.counts.mod_thorn = target.enemy.counts.mod_thorn + 1
	end

	this.pos = target.pos

	local target_flip = target.render.sprites[1].flip_x

	U.animation_start(this, "start", target_flip, store.tick_ts, false)

	while not U.animation_finished(this) do
		if target.health.dead then
			goto label_1652_0
		end

		coroutine.yield()
	end

	m.ts = store.tick_ts
	hit_ts = store.tick_ts

	U.animation_start(this, "loop", target_flip, store.tick_ts, true)

	while store.tick_ts - m.ts <= m.duration + 1e-09 do
		if this.interrupt or target.health.dead then
			break
		end

		if store.tick_ts - hit_ts >= this.damage_every then
			hit_ts = store.tick_ts

			local d = SU.create_attack_damage(this, target.id, this.id)

			queue_damage(store, d)
		end

		coroutine.yield()
	end

	::label_1652_0::

	U.y_animation_play(this, "end", target_flip, store.tick_ts, false)
	queue_remove(store, this)
	signal.emit("mod-applied", this, target)
end

scripts.aura_ranger_thorn = {}

function scripts.aura_ranger_thorn.update(this, store)
	local a = this.aura

	a.ts = store.tick_ts - a.cooldown

	local function find_targets()
		local targets = U.find_enemies_in_range(store.entities, this.pos, 0, a.radius, a.vis_flags, a.vis_bans, function(e)
			return not e.enemy.counts[a.mod] or e.enemy.counts[a.mod] < a.max_times
		end)

		return targets
	end

	while true do
		local owner = store.entities[a.source_id]

		if not owner then
			log.error("aura_ranger_thorn has no parent tower. removing")

			break
		end

		if owner.tower.blocked then
			-- block empty
		elseif store.tick_ts - a.ts >= a.cooldown then
			local targets = find_targets()

			if not targets or #targets < a.min_count then
				-- block empty
			else
				a.ts = store.tick_ts

				U.animation_start(owner, a.owner_animation, nil, store.tick_ts, false, a.owner_sid)
				U.y_wait(store, a.hit_time)

				targets = find_targets()

				if not targets or #targets < a.min_count then
					-- block empty
				else
					S:queue(a.hit_sound)

					for i = 1, math.min(#targets, a.max_count + a.max_count_inc * owner.powers.thorn.level) do
						local e = targets[i]
						local m = E:create_entity(a.mod)

						m.modifier.target_id = e.id
						m.modifier.source_id = this.id
						m.modifier.level = owner.powers.thorn.level
						m.modifier.duration = m.modifier.duration + m.modifier.duration_inc * owner.powers.thorn.level

						queue_insert(store, m)
					end

					U.y_animation_wait(owner, a.owner_sid)
					U.animation_start(owner, a.owner_idle, nil, store.tick_ts, false, a.owner_sid)
				end
			end
		end

		coroutine.yield()
	end

	queue_remove(store, this)
end

scripts.tower_barbarian_kr1 = {}

function scripts.tower_barbarian_kr1.get_info(this)
	local s = E:create_entity(this.barrack.soldier_type)

	if this.powers then
		for pn, p in pairs(this.powers) do
			for i = 1, p.level do
				SU.soldier_power_upgrade(s, pn)
			end
		end
	end

	local a = s.melee.attacks[1]
	local min, max = a.damage_min, a.damage_max
	local factor = a.multi_hit_factor and a.multi_hit_factor[a.level]

	if factor then
		min, max = min * (1 + factor), max * (1 + factor)
	end

	if this.tower then
		min, max = min * this.tower.damage_factor, max * this.tower.damage_factor
	end

	min, max = math.ceil(min), math.ceil(max)

	return {
		type = STATS_TYPE_TOWER_BARRACK,
		hp_max = s.health.hp_max,
		damage_min = min,
		damage_max = max,
		armor = s.health.armor,
		respawn = s.health.dead_lifetime
	}
end

scripts.soldier_barbarian = {}

function scripts.soldier_barbarian.get_info(this)
	local a = this.melee.attacks[1]
	local min, max = a.damage_min, a.damage_max
	local factor = a.multi_hit_factor and a.multi_hit_factor[a.level]

	if factor then
		min, max = min * (1 + factor), max * (1 + factor)
	end

	if this.unit then
		min, max = min * this.unit.damage_factor, max * this.unit.damage_factor
	end

	min, max = math.ceil(min), math.ceil(max)

	return {
		type = STATS_TYPE_SOLDIER,
		hp = this.health.hp,
		hp_max = this.health.hp_max,
		damage_min = min,
		damage_max = max,
		damage_icon = this.info.damage_icon,
		armor = this.health.armor,
		respawn = this.health.dead_lifetime
	}
end

function scripts.soldier_barbarian.on_power_upgrade(this, power_name, power)
	if not this._on_power_upgrade_called then
		this._on_power_upgrade_called = true
		this.ranged.attacks[1].animation = this.ranged.attacks[1].animation .. "2"
		this.melee.attacks[1].animation = this.melee.attacks[1].animation .. "2"
		this.melee.attacks[2].animation = this.melee.attacks[2].animation .. "2"
		this.render.sprites[1].angles.walk[1] = this.render.sprites[1].angles.walk[1] .. "2"
		this.idle_flip.last_animation = this.idle_flip.last_animation .. "2"
		this.unit.death_animation = this.unit.death_animation .. "2"
		this.melee.attacks[1].hit_time = nil
		this.melee.attacks[1].hit_times = this.melee.attacks[1].hit_times_dual
		this.melee.attacks[1].loops = 1
		this.melee.attacks[1].animations = {
			[2] = this.melee.attacks[1].animation
		}
		this.soldier.melee_slot_offset = V.v(7, 0)
		-- this.info.portrait = "gui_bottom_info_image_soldiers_0036"
	end
end

function scripts.soldier_barbarian.attack_fn(this, store, attack, target)
	if not attack.level or attack.level == 0 then
		return math.ceil(U.frandom(attack.damage_min, attack.damage_max) * this.unit.damage_factor)
	end

	local dmin, dmax = attack.damage_min, attack.damage_max

	if attack.damage_inc then
		dmin = attack.damage_min + attack.damage_inc * attack.level
		dmax = attack.damage_max + attack.damage_inc * attack.level
	end

	local factor
	local frame_number = string.gsub(this.render.sprites[1].frame_name, "KR1_barracks_tower_lvl4_unit_barbarian_skill_axe_", "")

	factor = (tonumber(frame_number) or 0) < attack.frames_hits[2] - 1 and 1 or attack.multi_hit_factor[attack.level] or 1

	return math.ceil(U.frandom(dmin, dmax) * factor * this.unit.damage_factor)
end

